-- Pure business-core schema
-- Extracted from GHOST source schema dump
-- (source: kokoro0615/ghost-website @ 7f6c7c39d6a4e515f8833f0bd53ce598ec8f66a0,
--  dump: docs/porting/evidence/schema/source-final-schema-dump.sql)
-- Exclusions: incident/* subsystem only. trial_run_id columns + trial stamp
-- machinery kept for schema parity (inert: GUC unset -> null).
SET statement_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET client_min_messages = warning;

CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;

-- SCHEMA: extensions (already created above)
-- CREATE SCHEMA extensions;

-- EXTENSION: pgcrypto
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;

-- COMMENT: EXTENSION pgcrypto
COMMENT ON EXTENSION pgcrypto IS 'cryptographic functions';

-- TYPE: payment_status
CREATE TYPE public.payment_status AS ENUM (
    'requires_payment_method',
    'requires_confirmation',
    'processing',
    'requires_action',
    'succeeded',
    'failed',
    'cancelled',
    'refund_pending',
    'refunded',
    'review',
    'partially_refunded'
);

-- TYPE: payment_type
CREATE TYPE public.payment_type AS ENUM (
    'card_setup',
    'deposit',
    'no_show_charge',
    'late_cancel_charge',
    'refund'
);

-- TYPE: reservation_hold_request_status
CREATE TYPE public.reservation_hold_request_status AS ENUM (
    'intent_pending',
    'stripe_create_in_progress',
    'stripe_unknown',
    'stripe_created',
    'finalize_retry',
    'finalized',
    'failed_released',
    'retry_exhausted',
    'manual_review'
);

-- TYPE: reservation_lock_status
CREATE TYPE public.reservation_lock_status AS ENUM (
    'held',
    'payment_grace_locked',
    'confirmed',
    'released',
    'expired'
);

-- TYPE: reservation_status
CREATE TYPE public.reservation_status AS ENUM (
    'draft',
    'pending',
    'pending_card_setup',
    'pending_deposit',
    'confirmed',
    'checked_in',
    'cancelled',
    'hold_expired',
    'payment_window_expired',
    'late_cancel_review',
    'no_show_review',
    'refund_required',
    'payment_binding_review',
    'card_saved_inventory_lost',
    'inventory_conflict_review',
    'admin_hold',
    'admin_hold_review',
    'failed'
);

-- TYPE: vip_service_status
CREATE TYPE public.vip_service_status AS ENUM (
    'expected',
    'late',
    'no_contact',
    'arrived',
    'partial_arrival',
    'seated',
    'bottle_pending',
    'bottle_served',
    'bill_requested',
    'paid',
    'resetting',
    'completed',
    'no_show'
);

-- TYPE: webhook_processing_status
CREATE TYPE public.webhook_processing_status AS ENUM (
    'received',
    'processing',
    'retry',
    'processed',
    'ignored',
    'dead'
);

-- FUNCTION: active_reservation_assignment_v8(uuid, timestamp with time zone)
CREATE FUNCTION public.active_reservation_assignment_v8(p_reservation_resource_id uuid, p_as_of timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE((
    SELECT
      rr.released_at IS NULL
      AND p_as_of IS NOT NULL
      AND CASE rr.lock_status
        WHEN 'confirmed'::public.reservation_lock_status THEN true
        WHEN 'held'::public.reservation_lock_status THEN
          COALESCE(
            GREATEST(
              rr.hold_expires_at,
              rr.admin_hold_expires_at,
              r.hold_expires_at,
              r.admin_hold_expires_at
            ),
            '-infinity'::timestamptz
          ) > p_as_of
        WHEN 'payment_grace_locked'::public.reservation_lock_status THEN
          COALESCE(
            GREATEST(
              r.payment_grace_until_at,
              rr.hold_expires_at,
              rr.admin_hold_expires_at,
              r.hold_expires_at,
              r.admin_hold_expires_at
            ),
            '-infinity'::timestamptz
          ) > p_as_of
        ELSE false
      END
    FROM public.reservation_resources AS rr
    JOIN public.reservations AS r
      ON r.id = rr.reservation_id
    WHERE rr.id = p_reservation_resource_id
  ), false);
$$;

-- FUNCTION: admin_constant_time_text_equal_v7(text, text)
CREATE FUNCTION public.admin_constant_time_text_equal_v7(p_left text, p_right text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_left text := COALESCE(p_left, '');
  v_right text := COALESCE(p_right, '');
  v_len int := GREATEST(length(COALESCE(p_left, '')), length(COALESCE(p_right, '')));
  v_diff int := length(COALESCE(p_left, '')) # length(COALESCE(p_right, ''));
  v_i int;
  v_left_code int;
  v_right_code int;
BEGIN
  IF v_len = 0 THEN
    RETURN v_diff = 0;
  END IF;

  FOR v_i IN 1..v_len LOOP
    v_left_code := CASE WHEN v_i <= length(v_left) THEN ascii(substr(v_left, v_i, 1)) ELSE 0 END;
    v_right_code := CASE WHEN v_i <= length(v_right) THEN ascii(substr(v_right, v_i, 1)) ELSE 0 END;
    v_diff := v_diff | (v_left_code # v_right_code);
  END LOOP;

  RETURN v_diff = 0;
END;
$$;

-- FUNCTION: admin_hold_default_expires_at_v7(timestamp with time zone)
CREATE FUNCTION public.admin_hold_default_expires_at_v7(p_created_at timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT p_created_at + make_interval(
    mins => COALESCE(
      ((SELECT value_json->>'minutes'
        FROM app_settings
        WHERE key = 'admin_hold_default_expiry_minutes')::int),
      1440
    )
  );
$$;

-- FUNCTION: admin_pin_hash_v7(text, text)
CREATE FUNCTION public.admin_pin_hash_v7(p_pin_salt text, p_pin text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT encode(digest(p_pin_salt || ':' || p_pin, 'sha256'), 'hex');
$$;

-- FUNCTION: admit_legacy_ticket_v27(text, uuid, uuid, text)
CREATE FUNCTION public.admit_legacy_ticket_v27(p_admission_code text, p_actor_admin_id uuid, p_expected_event_session_id uuid, p_expected_environment text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admission_id uuid;
  v_order_id uuid;
  v_event_day_id uuid;
  v_event_session_id uuid;
  v_order_mode text;
  v_event_day public.event_days%ROWTYPE;
  v_session public.ticket_event_sessions%ROWTYPE;
  v_order public.ticket_orders%ROWTYPE;
  v_admission public.ticket_admissions%ROWTYPE;
  v_observed_at timestamptz := clock_timestamp();
  v_updated integer;
BEGIN
  SELECT admission.id, admission.ticket_order_id, ticket_order.event_session_id,
         ticket_order.check_in_mode, session.event_day_id
  INTO v_admission_id, v_order_id, v_event_session_id, v_order_mode, v_event_day_id
  FROM public.ticket_admissions AS admission
  JOIN public.ticket_orders AS ticket_order ON ticket_order.id = admission.ticket_order_id
  LEFT JOIN public.ticket_event_sessions AS session ON session.id = ticket_order.event_session_id
  WHERE admission.admission_code = p_admission_code;
  IF NOT FOUND THEN RETURN jsonb_build_object('action', 'not_found'); END IF;

  IF v_order_mode = 'wallet_swipe' THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reason', 'wallet_swipe_requires_wallet_commit');
  END IF;
  IF v_event_session_id IS NULL OR v_event_day_id IS NULL THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'event_session_required');
  END IF;
  IF p_expected_event_session_id IS NULL
    OR p_expected_event_session_id <> v_event_session_id
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'event_session_mismatch');
  END IF;
  IF COALESCE(p_expected_environment, '') NOT IN ('test', 'live') THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'environment_invalid');
  END IF;

  SELECT * INTO v_event_day FROM public.event_days
  WHERE id = v_event_day_id FOR NO KEY UPDATE;
  SELECT * INTO v_session FROM public.ticket_event_sessions
  WHERE id = v_event_session_id
    AND event_day_id = v_event_day.id
  FOR NO KEY UPDATE;
  SELECT * INTO v_order FROM public.ticket_orders
  WHERE id = v_order_id
    AND event_session_id = v_session.id
  FOR UPDATE;

  IF v_order.check_in_mode <> 'legacy_qr' THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reason', 'wallet_swipe_requires_wallet_commit');
  END IF;
  IF v_order.payment_hold_reason IS NOT NULL THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reason', 'payment_hold_required',
      'paymentHoldReason', v_order.payment_hold_reason,
      'orderId', v_order.id, 'publicCode', v_order.public_code);
  END IF;
  IF v_order.environment <> p_expected_environment
    OR v_session.environment <> p_expected_environment
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'environment_mismatch');
  END IF;
  IF v_event_day.business_date <> v_order.event_date
    OR v_session.event_date <> v_order.event_date
    OR v_session.catalog_event_id <> v_order.event_id
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'event_binding_mismatch');
  END IF;
  IF v_event_day.operating_status <> 'open' THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'event_day_closed');
  END IF;
  IF NOT v_session.enabled THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'event_session_disabled');
  END IF;
  IF v_session.admission_state <> 'scheduled' THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'reason', CASE WHEN v_session.admission_state = 'cancelled'
        THEN 'event_session_cancelled' ELSE 'event_session_closed' END);
  END IF;
  IF v_observed_at < v_session.admission_opens_at THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'admission_too_early');
  END IF;
  IF v_observed_at >= v_session.admission_closes_at THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'admission_too_late');
  END IF;

  -- Money that successfully moved but is not terminally allocated is the most
  -- actionable rejection, even when a full refund also moved order.status.
  PERFORM 1
  FROM public.ticket_refund_events AS refund
  WHERE refund.ticket_order_id = v_order.id
    AND refund.money_may_have_moved
    AND refund.resolution_status IN ('review_required', 'conflict_review')
    AND refund.resolved_at IS NULL
  ORDER BY refund.created_at, refund.id
  FOR UPDATE;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reason', 'refund_review_required',
      'orderId', v_order.id, 'publicCode', v_order.public_code);
  END IF;

  IF v_order.status NOT IN ('paid', 'fulfilled')
    OR NULLIF(v_order.payment_intent_id, '') IS NULL
    OR v_order.paid_at IS NULL
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reason', 'order_not_valid',
      'orderStatus', v_order.status);
  END IF;

  SELECT * INTO v_admission
  FROM public.ticket_admissions
  WHERE id = v_admission_id
    AND ticket_order_id = v_order.id
    AND admission_code = p_admission_code
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'admission_state_changed');
  END IF;
  IF v_admission.status = 'void' THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'admission_void');
  END IF;
  IF v_admission.status = 'admitted' THEN
    RETURN jsonb_build_object(
      'action', 'already_admitted', 'admittedAt', v_admission.admitted_at,
      'publicCode', v_order.public_code, 'serial', v_admission.serial,
      'eventDate', v_order.event_date, 'eventTitle', v_order.event_title);
  END IF;

  UPDATE public.ticket_admissions
  SET status = 'admitted', admitted_at = v_observed_at,
      admitted_by_admin_id = p_actor_admin_id
  WHERE id = v_admission.id AND status = 'issued';
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> 1 THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'admission_state_changed');
  END IF;

  RETURN jsonb_build_object(
    'action', 'admitted', 'publicCode', v_order.public_code,
    'serial', v_admission.serial, 'totalQuantity', v_order.total_quantity,
    'ticketTypeLabel', v_admission.ticket_type_label,
    'eventDate', v_order.event_date, 'eventTitle', v_order.event_title,
    'eventSessionId', v_session.id, 'admittedAt', v_observed_at);
END;
$$;

-- FUNCTION: admit_ticket_at_door_v27(text, uuid, uuid, text)
CREATE FUNCTION public.admit_ticket_at_door_v27(p_admission_code text, p_actor_admin_id uuid, p_expected_event_session_id uuid, p_expected_environment text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT public.admit_legacy_ticket_v27(
    p_admission_code, p_actor_admin_id,
    p_expected_event_session_id, p_expected_environment
  );
$$;

-- COMMENT: FUNCTION admit_ticket_at_door_v27(p_admission_code text, p_actor_admin_id uuid, p_expected_event_session_id uuid, p_expected_environment text)
COMMENT ON FUNCTION public.admit_ticket_at_door_v27(p_admission_code text, p_actor_admin_id uuid, p_expected_event_session_id uuid, p_expected_environment text) IS 'Sole service-callable legacy QR admission entry point after v31.';

-- FUNCTION: admit_ticket_v23(text, uuid)
CREATE FUNCTION public.admit_ticket_v23(p_admission_code text, p_actor_admin_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_event_session_id uuid;
  v_environment text;
  v_mode text;
BEGIN
  SELECT ticket_order.event_session_id, ticket_order.environment,
         ticket_order.check_in_mode
  INTO v_event_session_id, v_environment, v_mode
  FROM public.ticket_admissions AS admission
  JOIN public.ticket_orders AS ticket_order ON ticket_order.id = admission.ticket_order_id
  WHERE admission.admission_code = p_admission_code;
  IF NOT FOUND THEN RETURN jsonb_build_object('action', 'not_found'); END IF;
  IF v_mode = 'wallet_swipe' THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reason', 'wallet_swipe_requires_wallet_commit');
  END IF;
  IF v_event_session_id IS NULL THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'event_session_required');
  END IF;
  RETURN public.admit_legacy_ticket_v27(
    p_admission_code, p_actor_admin_id, v_event_session_id, v_environment);
END;
$$;

-- COMMENT: FUNCTION admit_ticket_v23(p_admission_code text, p_actor_admin_id uuid)
COMMENT ON FUNCTION public.admit_ticket_v23(p_admission_code text, p_actor_admin_id uuid) IS 'Retained for schema compatibility only; service EXECUTE revoked by v31 after Website caller promotion.';

-- FUNCTION: append_vip_floor_audit_v8(uuid, uuid, uuid, text, uuid, text, text, text, bigint, bigint, bigint, text[], jsonb, jsonb, jsonb)
CREATE FUNCTION public.append_vip_floor_audit_v8(p_actor_admin_id uuid, p_event_day_id uuid, p_reservation_id uuid, p_entity_type text, p_entity_id uuid, p_operation text, p_request_id text, p_reason text, p_expected_version bigint, p_version_before bigint, p_version_after bigint, p_changed_fields text[], p_before_json jsonb, p_after_json jsonb, p_metadata_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_entity_type text := lower(btrim(COALESCE(p_entity_type, '')));
  v_operation text := btrim(COALESCE(p_operation, ''));
  v_request_id text := btrim(COALESCE(p_request_id, ''));
  v_changed_fields text[];
  v_target_table text;
  v_audit_log_id uuid;
  v_document_name text;
  v_document jsonb;
  v_forbidden_key text;
  v_forbidden_value boolean;
  v_entity_context_valid boolean := false;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.admin_users
    WHERE id = p_actor_admin_id
      AND active = true
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'UNAUTHENTICATED',
        'details', jsonb_build_object('reason', 'actor_unavailable')
      )
    );
  END IF;

  IF p_event_day_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.event_days
    WHERE id = p_event_day_id
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', CASE WHEN p_event_day_id IS NULL THEN 'INVALID_COMMAND' ELSE 'NOT_FOUND' END,
        'details', jsonb_build_object('field', 'eventDayId')
      )
    );
  END IF;

  IF p_reservation_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.reservations
    WHERE id = p_reservation_id
      AND event_day_id = p_event_day_id
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'NOT_FOUND',
        'details', jsonb_build_object(
          'entityType', 'reservation',
          'reason', 'reservation_event_day_mismatch_or_missing'
        )
      )
    );
  END IF;

  IF v_entity_type NOT IN ('reservation', 'assignment', 'block', 'note', 'customer')
    OR p_entity_id IS NULL
    OR v_operation = ''
    OR v_request_id = ''
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object('reason', 'invalid_audit_identity')
      )
    );
  END IF;

  SELECT COALESCE(
    array_agg(DISTINCT btrim(field_name) ORDER BY btrim(field_name))
      FILTER (WHERE NULLIF(btrim(field_name), '') IS NOT NULL),
    '{}'::text[]
  )
  INTO v_changed_fields
  FROM unnest(COALESCE(p_changed_fields, '{}'::text[])) AS changed(field_name);

  IF NOT COALESCE((
    (
      p_expected_version IS NULL
      AND p_version_before IS NULL
      AND p_version_after = 1
    )
    OR (
      p_expected_version = p_version_before
      AND p_version_before >= 1
      AND p_version_after > p_version_before
      AND p_version_after - p_version_before = 1
    )
    OR (
      p_expected_version IS NULL
      AND p_version_before IS NULL
      AND p_version_after IS NULL
      AND cardinality(v_changed_fields) = 0
    )
  ), false) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object('reason', 'invalid_audit_version_shape')
      )
    );
  END IF;

  v_entity_context_valid := CASE v_entity_type
    WHEN 'reservation' THEN
      p_reservation_id IS NOT NULL
      AND p_entity_id = p_reservation_id
      AND EXISTS (
        SELECT 1
        FROM public.reservations AS r
        WHERE r.id = p_entity_id
          AND r.event_day_id = p_event_day_id
      )
    WHEN 'assignment' THEN
      p_reservation_id IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM public.reservation_resources AS rr
        JOIN public.reservations AS r
          ON r.id = rr.reservation_id
        WHERE rr.id = p_entity_id
          AND rr.reservation_id = p_reservation_id
          AND r.event_day_id = p_event_day_id
      )
    WHEN 'block' THEN
      p_reservation_id IS NULL
      AND EXISTS (
        SELECT 1
        FROM public.reservation_blocks AS rb
        WHERE rb.id = p_entity_id
          AND rb.event_day_id = p_event_day_id
      )
    WHEN 'note' THEN
      p_reservation_id IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM public.reservation_notes AS rn
        JOIN public.reservations AS r
          ON r.id = rn.reservation_id
        WHERE rn.id = p_entity_id
          AND rn.reservation_id = p_reservation_id
          AND r.event_day_id = p_event_day_id
      )
    WHEN 'customer' THEN
      EXISTS (
        SELECT 1
        FROM public.customers AS c
        JOIN public.reservations AS r
          ON r.customer_id = c.id
        WHERE c.id = p_entity_id
          AND r.event_day_id = p_event_day_id
          AND (p_reservation_id IS NULL OR r.id = p_reservation_id)
      )
    ELSE false
  END;

  IF NOT v_entity_context_valid THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'NOT_FOUND',
        'details', jsonb_build_object(
          'entityType', v_entity_type,
          'reason', 'audit_entity_context_mismatch'
        )
      )
    );
  END IF;

  IF p_reason IS NOT NULL AND (
    p_reason ~* '[[:alnum:]._%+-]+@[[:alnum:].-]+\.[[:alpha:]]{2,}'
    OR p_reason ~*
      '(^|[^0-9])(\+81|0[0-9]{1,4})[- ]?[0-9]{1,4}[- ]?[0-9]{3,4}($|[^0-9])'
    OR p_reason ~*
      '((sk|rk)_(live|test)_[a-z0-9]+|whsec_[a-z0-9]+|bearer[[:space:]]+[a-z0-9._~+/=-]+|-----begin [a-z ]*private key-----)'
    OR p_reason ~ '^(cus|pi|pm|ch|re|evt|seti|cs)_[A-Za-z0-9_]+$'
    OR p_reason ~ '^U[0-9a-fA-F]{32}$'
    OR p_reason ~*
      '"(stripe|provider|webhook|client_secret|payment_method|line_user)"[[:space:]]*:'
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object(
          'field', 'reason',
          'reason', 'forbidden_value'
        )
      )
    );
  END IF;

  FOR v_document_name, v_document IN
    SELECT document_name, document
    FROM (
      VALUES
        ('beforeJson'::text, p_before_json),
        ('afterJson'::text, p_after_json),
        ('metadataJson'::text, COALESCE(p_metadata_json, '{}'::jsonb))
    ) AS documents(document_name, document)
  LOOP
    IF v_document IS NOT NULL AND jsonb_typeof(v_document) <> 'object' THEN
      RETURN jsonb_build_object(
        'action', 'rejected',
        'error', jsonb_build_object(
          'code', 'INVALID_COMMAND',
          'details', jsonb_build_object(
            'field', v_document_name,
            'reason', 'object_required'
          )
        )
      );
    END IF;

    v_forbidden_key := NULL;
    v_forbidden_value := false;

    WITH RECURSIVE json_nodes(value) AS (
      SELECT v_document
      UNION ALL
      SELECT child.value
      FROM json_nodes AS parent
      CROSS JOIN LATERAL (
        SELECT object_child.value
        FROM jsonb_each(
          CASE
            WHEN jsonb_typeof(parent.value) = 'object' THEN parent.value
            ELSE '{}'::jsonb
          END
        ) AS object_child(key, value)
        UNION ALL
        SELECT array_child.value
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(parent.value) = 'array' THEN parent.value
            ELSE '[]'::jsonb
          END
        ) AS array_child(value)
      ) AS child
    ),
    forbidden AS (
      SELECT
        object_entry.key AS forbidden_key,
        false AS forbidden_value
      FROM json_nodes AS node
      CROSS JOIN LATERAL jsonb_each(
        CASE
          WHEN jsonb_typeof(node.value) = 'object' THEN node.value
          ELSE '{}'::jsonb
        END
      ) AS object_entry(key, value)
      WHERE lower(object_entry.key) ~
        '(^name$|name.?kana|email|phone|contact|display.?name|customer.?name|guest.?name|line.?user|address|birth|allerg|preference|secret|password|token|authorization|cookie|api.?key|client.?secret|stripe|provider|webhook|payload|ciphertext|auth.?tag|nonce)'

      UNION ALL

      SELECT
        NULL::text AS forbidden_key,
        true AS forbidden_value
      FROM json_nodes AS node
      WHERE jsonb_typeof(node.value) = 'string'
        -- Internal entity references are permitted in protected audit rows.
        -- Exclude canonical UUIDs before applying the deliberately broad
        -- Japanese phone pattern; otherwise random UUID digit runs can be
        -- misclassified as contact data and make valid commands flaky.
        AND node.value #>> '{}' !~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        -- Exact RFC 3339 / PostgreSQL timestamptz JSON scalars are
        -- operational timestamps, not contact values. Keep this anchored so
        -- surrounding text and all existing PII/secret patterns still fail.
        AND node.value #>> '{}' !~*
          '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'
        AND (
          node.value #>> '{}' ~*
            '[[:alnum:]._%+-]+@[[:alnum:].-]+\.[[:alpha:]]{2,}'
          OR node.value #>> '{}' ~*
            '(^|[^0-9])(\+81|0[0-9]{1,4})[- ]?[0-9]{1,4}[- ]?[0-9]{3,4}($|[^0-9])'
          OR node.value #>> '{}' ~*
            '((sk|rk)_(live|test)_[a-z0-9]+|whsec_[a-z0-9]+|bearer[[:space:]]+[a-z0-9._~+/=-]+|-----begin [a-z ]*private key-----)'
          OR node.value #>> '{}' ~
            '^(cus|pi|pm|ch|re|evt|seti|cs)_[A-Za-z0-9_]+$'
          OR node.value #>> '{}' ~
            '^U[0-9a-fA-F]{32}$'
          OR node.value #>> '{}' ~*
            '"(stripe|provider|webhook|client_secret|payment_method|line_user)"[[:space:]]*:'
        )
    )
    SELECT forbidden_key, forbidden_value
    INTO v_forbidden_key, v_forbidden_value
    FROM forbidden
    ORDER BY forbidden_value, forbidden_key NULLS LAST
    LIMIT 1;

    IF FOUND THEN
      RETURN jsonb_build_object(
        'action', 'rejected',
        'error', jsonb_build_object(
          'code', 'INVALID_COMMAND',
          'details', jsonb_strip_nulls(jsonb_build_object(
            'field', v_document_name,
            'reason', CASE
              WHEN v_forbidden_value THEN 'forbidden_value'
              ELSE 'forbidden_key'
            END,
            'key', v_forbidden_key
          ))
        )
      );
    END IF;
  END LOOP;

  v_target_table := CASE v_entity_type
    WHEN 'reservation' THEN 'reservations'
    WHEN 'assignment' THEN 'reservation_resources'
    WHEN 'block' THEN 'reservation_blocks'
    WHEN 'note' THEN 'reservation_notes'
    WHEN 'customer' THEN 'customer_profiles'
  END;

  INSERT INTO public.audit_logs(
    actor_admin_id,
    actor_type,
    action,
    target_table,
    target_id,
    request_id,
    before_json,
    after_json,
    reason,
    event_day_id,
    reservation_id,
    entity_type,
    entity_id,
    operation,
    expected_version,
    version_before,
    version_after,
    changed_fields,
    metadata_json
  )
  VALUES (
    p_actor_admin_id,
    'admin',
    v_operation,
    v_target_table,
    p_entity_id,
    v_request_id,
    p_before_json,
    p_after_json,
    p_reason,
    p_event_day_id,
    p_reservation_id,
    v_entity_type,
    p_entity_id,
    v_operation,
    p_expected_version,
    p_version_before,
    p_version_after,
    v_changed_fields,
    COALESCE(p_metadata_json, '{}'::jsonb)
  )
  RETURNING id INTO v_audit_log_id;

  RETURN jsonb_build_object(
    'action', 'appended',
    'auditLogId', v_audit_log_id,
    'eventDayId', p_event_day_id,
    'entityType', v_entity_type,
    'entityId', p_entity_id
  );
END;
$_$;

-- FUNCTION: apply_external_dispute_fact_v8(text, text, text, text, bigint, text, text, text, text, jsonb, text, timestamp with time zone)
CREATE FUNCTION public.apply_external_dispute_fact_v8(p_environment text, p_stripe_account_id text, p_stripe_dispute_id text, p_stripe_status text, p_amount_yen bigint, p_currency text, p_reason text, p_stripe_charge_id text, p_stripe_payment_intent_id text, p_payload_json jsonb, p_last_event_id text, p_last_event_created_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_payment public.payments%ROWTYPE;
  v_existing public.stripe_disputes%ROWTYPE;
  v_review_id uuid;
BEGIN
  IF p_environment NOT IN ('test','live')
    OR NULLIF(btrim(COALESCE(p_stripe_dispute_id, '')), '') IS NULL THEN
    RAISE EXCEPTION 'invalid external dispute identity';
  END IF;

  IF NULLIF(btrim(COALESCE(p_stripe_charge_id, '')), '') IS NOT NULL THEN
    SELECT * INTO v_payment
    FROM public.payments p
    WHERE p.environment = p_environment
      AND p.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND p.stripe_charge_id = p_stripe_charge_id
    ORDER BY p.created_at DESC
    LIMIT 1;
  END IF;

  IF NOT FOUND AND NULLIF(btrim(COALESCE(p_stripe_payment_intent_id, '')), '') IS NOT NULL THEN
    SELECT * INTO v_payment
    FROM public.payments p
    WHERE p.environment = p_environment
      AND p.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND p.provider_object_type = 'payment_intent'
      AND p.provider_object_id = p_stripe_payment_intent_id
    ORDER BY p.created_at DESC
    LIMIT 1;
  END IF;

  IF NOT FOUND AND NULLIF(btrim(COALESCE(p_stripe_payment_intent_id, '')), '') IS NOT NULL THEN
    SELECT p.* INTO v_payment
    FROM public.stripe_intent_bindings b
    JOIN public.payments p ON p.id = b.payment_id
    WHERE b.environment = p_environment
      AND b.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND b.provider_object_type = 'payment_intent'
      AND b.provider_object_id = p_stripe_payment_intent_id
      AND b.payment_id IS NOT NULL
    ORDER BY b.created_at DESC
    LIMIT 1;
  END IF;

  SELECT * INTO v_existing
  FROM public.stripe_disputes d
  WHERE d.environment = p_environment
    AND d.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
    AND d.stripe_dispute_id = p_stripe_dispute_id
  FOR UPDATE;

  IF FOUND AND v_existing.payment_id IS NOT NULL
    AND (v_payment.id IS NULL OR v_existing.payment_id <> v_payment.id) THEN
    INSERT INTO public.external_finance_reviews(
      environment, stripe_account_id, event_kind, provider_object_id,
      payment_id, reservation_id, amount_yen, currency, reason, payload_json
    ) VALUES (
      p_environment, p_stripe_account_id, 'dispute_identity_conflict', p_stripe_dispute_id,
      v_existing.payment_id, v_existing.reservation_id, p_amount_yen,
      lower(btrim(COALESCE(p_currency, 'jpy'))), 'bound_to_different_payment',
      COALESCE(p_payload_json, '{}'::jsonb)
    )
    ON CONFLICT (environment, stripe_account_key, event_kind, provider_object_id, reason)
    DO UPDATE SET payload_json = EXCLUDED.payload_json, updated_at = now()
    RETURNING id INTO v_review_id;
    RETURN jsonb_build_object('applied', false, 'reason', 'identity_conflict', 'reviewId', v_review_id);
  END IF;

  IF NOT FOUND AND v_payment.id IS NULL THEN
    INSERT INTO public.external_finance_reviews(
      environment, stripe_account_id, event_kind, provider_object_id,
      amount_yen, currency, reason, payload_json
    ) VALUES (
      p_environment, p_stripe_account_id, 'dispute', p_stripe_dispute_id,
      p_amount_yen, lower(btrim(COALESCE(p_currency, 'jpy'))), 'payment_unresolved',
      COALESCE(p_payload_json, '{}'::jsonb) || jsonb_build_object(
        '_lastEventId', p_last_event_id,
        '_lastEventCreatedAt', p_last_event_created_at
      )
    )
    ON CONFLICT (environment, stripe_account_key, event_kind, provider_object_id, reason)
    DO UPDATE SET payload_json = EXCLUDED.payload_json, updated_at = now()
    RETURNING id INTO v_review_id;
    -- Still persist the dispute fact itself; the payment link is resolved
    -- later via review or the balance importer.
  END IF;

  INSERT INTO public.stripe_disputes(
    reservation_id, payment_id, environment, stripe_account_id, stripe_dispute_id,
    stripe_charge_id, stripe_payment_intent_id, amount_yen, currency, status,
    reason, last_event_id, last_event_created_at, payload_json
  ) VALUES (
    v_payment.reservation_id, v_payment.id, p_environment, p_stripe_account_id,
    p_stripe_dispute_id, NULLIF(btrim(COALESCE(p_stripe_charge_id, '')), ''),
    NULLIF(btrim(COALESCE(p_stripe_payment_intent_id, '')), ''), p_amount_yen,
    lower(btrim(COALESCE(p_currency, 'jpy'))), lower(btrim(COALESCE(p_stripe_status, 'unknown'))),
    p_reason, p_last_event_id, p_last_event_created_at, COALESCE(p_payload_json, '{}'::jsonb)
  )
  ON CONFLICT (environment, stripe_account_key, stripe_dispute_id)
  DO UPDATE SET
    status = EXCLUDED.status,
    reason = COALESCE(EXCLUDED.reason, stripe_disputes.reason),
    reservation_id = COALESCE(stripe_disputes.reservation_id, EXCLUDED.reservation_id),
    payment_id = COALESCE(stripe_disputes.payment_id, EXCLUDED.payment_id),
    stripe_charge_id = COALESCE(stripe_disputes.stripe_charge_id, EXCLUDED.stripe_charge_id),
    stripe_payment_intent_id = COALESCE(stripe_disputes.stripe_payment_intent_id, EXCLUDED.stripe_payment_intent_id),
    last_event_id = EXCLUDED.last_event_id,
    last_event_created_at = EXCLUDED.last_event_created_at,
    payload_json = EXCLUDED.payload_json,
    updated_at = now()
  WHERE stripe_disputes.last_event_created_at IS NULL
     OR EXCLUDED.last_event_created_at >= stripe_disputes.last_event_created_at;

  RETURN jsonb_build_object(
    'applied', true,
    'stripeDisputeId', p_stripe_dispute_id,
    'paymentId', v_payment.id,
    'reservationId', v_payment.reservation_id
  );
END;
$$;

-- FUNCTION: apply_external_refund_fact_v8(text, text, text, text, bigint, text, text, text, jsonb, jsonb, text, timestamp with time zone, uuid)
CREATE FUNCTION public.apply_external_refund_fact_v8(p_environment text, p_stripe_account_id text, p_stripe_refund_id text, p_stripe_status text, p_amount_yen bigint, p_currency text, p_stripe_charge_id text, p_stripe_payment_intent_id text, p_metadata_json jsonb, p_payload_json jsonb, p_last_event_id text, p_last_event_created_at timestamp with time zone, p_payment_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_payment public.payments%ROWTYPE;
  v_case_id uuid;
  v_existing public.stripe_refunds%ROWTYPE;
  v_status text := lower(btrim(COALESCE(p_stripe_status, '')));
  v_origin text := 'external';
  v_derived jsonb;
  v_review_id uuid;
  v_amount int := GREATEST(COALESCE(p_amount_yen, 0), 0)::int;
  v_currency text := lower(btrim(COALESCE(p_currency, 'jpy')));
BEGIN
  IF p_environment NOT IN ('test','live')
    OR NULLIF(btrim(COALESCE(p_stripe_refund_id, '')), '') IS NULL THEN
    RAISE EXCEPTION 'invalid external refund identity';
  END IF;

  -- Explicit link (review resolution) wins over inference; still verified
  -- against environment/account so a link can never cross environment lines.
  IF p_payment_id IS NOT NULL THEN
    SELECT * INTO v_payment
    FROM public.payments p
    WHERE p.id = p_payment_id
      AND p.environment = p_environment
      AND p.stripe_account_key = COALESCE(p_stripe_account_id, 'platform');
    IF NOT FOUND THEN
      RAISE EXCEPTION 'linked payment not in scope for external refund fact';
    END IF;
  END IF;

  -- Resolve the owning payment. Every Stripe refund carries `charge`; the
  -- PaymentIntent is the fallback, then our own intent binding table.
  IF v_payment.id IS NULL AND NULLIF(btrim(COALESCE(p_stripe_charge_id, '')), '') IS NOT NULL THEN
    SELECT * INTO v_payment
    FROM public.payments p
    WHERE p.environment = p_environment
      AND p.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND p.stripe_charge_id = p_stripe_charge_id
    ORDER BY p.created_at DESC
    LIMIT 1;
  END IF;

  IF NOT FOUND AND NULLIF(btrim(COALESCE(p_stripe_payment_intent_id, '')), '') IS NOT NULL THEN
    SELECT * INTO v_payment
    FROM public.payments p
    WHERE p.environment = p_environment
      AND p.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND p.provider_object_type = 'payment_intent'
      AND p.provider_object_id = p_stripe_payment_intent_id
    ORDER BY p.created_at DESC
    LIMIT 1;
  END IF;

  IF NOT FOUND AND NULLIF(btrim(COALESCE(p_stripe_payment_intent_id, '')), '') IS NOT NULL THEN
    SELECT p.* INTO v_payment
    FROM public.stripe_intent_bindings b
    JOIN public.payments p ON p.id = b.payment_id
    WHERE b.environment = p_environment
      AND b.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND b.provider_object_type = 'payment_intent'
      AND b.provider_object_id = p_stripe_payment_intent_id
      AND b.payment_id IS NOT NULL
    ORDER BY b.created_at DESC
    LIMIT 1;
  END IF;

  -- Last resort: our own refund worker stamps payment_id metadata on the
  -- refunds it creates; verify the hinted row still belongs to this
  -- environment/account before trusting it.
  IF NOT FOUND AND COALESCE(p_metadata_json ->> 'payment_id', '') ~* '^[0-9a-f-]{36}$' THEN
    SELECT * INTO v_payment
    FROM public.payments p
    WHERE p.id = (p_metadata_json ->> 'payment_id')::uuid
      AND p.environment = p_environment
      AND p.stripe_account_key = COALESCE(p_stripe_account_id, 'platform');
  END IF;

  IF NOT FOUND THEN
    INSERT INTO public.external_finance_reviews(
      environment, stripe_account_id, event_kind, provider_object_id,
      amount_yen, currency, reason, payload_json
    ) VALUES (
      p_environment, p_stripe_account_id, 'refund', p_stripe_refund_id,
      p_amount_yen, v_currency, 'payment_unresolved',
      COALESCE(p_payload_json, '{}'::jsonb) || jsonb_build_object(
        '_lastEventId', p_last_event_id,
        '_lastEventCreatedAt', p_last_event_created_at
      )
    )
    ON CONFLICT (environment, stripe_account_key, event_kind, provider_object_id, reason)
    DO UPDATE SET payload_json = EXCLUDED.payload_json, updated_at = now()
    RETURNING id INTO v_review_id;
    RETURN jsonb_build_object('applied', false, 'reason', 'payment_unresolved', 'reviewId', v_review_id);
  END IF;

  -- A refund_cases row that already claimed this provider identity (or the
  -- worker's own metadata) makes this an internally-originated fact.
  SELECT rc.id INTO v_case_id
  FROM public.refund_cases rc
  WHERE rc.environment = p_environment
    AND rc.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
    AND rc.stripe_refund_id = p_stripe_refund_id
    AND rc.payment_id = v_payment.id
  ORDER BY rc.created_at DESC
  LIMIT 1;
  IF v_case_id IS NULL AND COALESCE(p_metadata_json ->> 'refund_case_id', '') ~* '^[0-9a-f-]{36}$' THEN
    SELECT rc.id INTO v_case_id
    FROM public.refund_cases rc
    WHERE rc.id = (p_metadata_json ->> 'refund_case_id')::uuid
      AND rc.payment_id = v_payment.id;
  END IF;
  IF v_case_id IS NOT NULL THEN
    v_origin := 'internal';
  END IF;

  SELECT * INTO v_existing
  FROM public.stripe_refunds sr
  WHERE sr.environment = p_environment
    AND sr.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
    AND sr.stripe_refund_id = p_stripe_refund_id
  FOR UPDATE;

  IF FOUND AND (
    v_existing.payment_id <> v_payment.id
    OR v_existing.reservation_id <> v_payment.reservation_id
    OR (v_existing.refund_case_id IS NOT NULL AND v_case_id IS NOT NULL AND v_existing.refund_case_id <> v_case_id)
  ) THEN
    -- The provider identity already belongs to different money. Never
    -- rebind; the collision is a durable, auditable review item.
    INSERT INTO public.external_finance_reviews(
      environment, stripe_account_id, event_kind, provider_object_id,
      payment_id, reservation_id, amount_yen, currency, reason, payload_json
    ) VALUES (
      p_environment, p_stripe_account_id, 'refund_identity_conflict', p_stripe_refund_id,
      v_payment.id, v_payment.reservation_id, p_amount_yen, v_currency, 'bound_to_different_payment',
      jsonb_build_object(
        'boundPaymentId', v_existing.payment_id,
        'boundReservationId', v_existing.reservation_id,
        'boundRefundCaseId', v_existing.refund_case_id,
        'observedPayload', COALESCE(p_payload_json, '{}'::jsonb)
      )
    )
    ON CONFLICT (environment, stripe_account_key, event_kind, provider_object_id, reason)
    DO UPDATE SET payload_json = EXCLUDED.payload_json, updated_at = now()
    RETURNING id INTO v_review_id;
    RETURN jsonb_build_object('applied', false, 'reason', 'identity_conflict', 'reviewId', v_review_id);
  END IF;

  IF NOT FOUND THEN
    INSERT INTO public.stripe_refunds(
      reservation_id, payment_id, refund_case_id, environment, stripe_account_id,
      stripe_refund_id, stripe_charge_id, amount_yen, status, origin,
      last_event_id, last_event_created_at, payload_json
    ) VALUES (
      v_payment.reservation_id, v_payment.id, v_case_id, p_environment, p_stripe_account_id,
      p_stripe_refund_id, NULLIF(btrim(COALESCE(p_stripe_charge_id, '')), ''), v_amount, v_status, v_origin,
      p_last_event_id, p_last_event_created_at, COALESCE(p_payload_json, '{}'::jsonb)
    )
    ON CONFLICT (environment, stripe_account_key, stripe_refund_id) DO NOTHING;

    -- Re-read under row lock; a racing internal writer may have won the insert.
    SELECT * INTO v_existing
    FROM public.stripe_refunds sr
    WHERE sr.environment = p_environment
      AND sr.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND sr.stripe_refund_id = p_stripe_refund_id
    FOR UPDATE;
  END IF;

  -- A refund that already moved money (ledger row exists) cannot later report
  -- failed/canceled without an operator-visible contradiction.
  IF v_status IN ('failed','canceled')
    AND EXISTS (SELECT 1 FROM public.ledger_entries le WHERE le.stripe_refund_id = p_stripe_refund_id) THEN
    INSERT INTO public.external_finance_reviews(
      environment, stripe_account_id, event_kind, provider_object_id,
      payment_id, reservation_id, amount_yen, currency, reason, payload_json
    ) VALUES (
      p_environment, p_stripe_account_id, 'provider_state_contradiction', p_stripe_refund_id,
      v_payment.id, v_payment.reservation_id, p_amount_yen, v_currency, 'refund_succeeded_then_failed',
      COALESCE(p_payload_json, '{}'::jsonb)
    )
    ON CONFLICT (environment, stripe_account_key, event_kind, provider_object_id, reason)
    DO UPDATE SET payload_json = EXCLUDED.payload_json, updated_at = now();
  END IF;

  -- Newest observed event wins the mutable provider fields; identity columns
  -- are immutable (trigger backstop in patch 0001).
  IF FOUND AND (
    v_existing.last_event_created_at IS NULL
    OR p_last_event_created_at > v_existing.last_event_created_at
    OR (p_last_event_created_at = v_existing.last_event_created_at
        AND COALESCE(p_last_event_id, '') > COALESCE(v_existing.last_event_id, ''))
  ) THEN
    UPDATE public.stripe_refunds
    SET status = v_status,
        payload_json = COALESCE(p_payload_json, '{}'::jsonb),
        last_event_id = p_last_event_id,
        last_event_created_at = p_last_event_created_at,
        refund_case_id = COALESCE(refund_case_id, v_case_id),
        stripe_charge_id = COALESCE(stripe_charge_id, NULLIF(btrim(COALESCE(p_stripe_charge_id, '')), '')),
        updated_at = now()
    WHERE id = v_existing.id;
    v_existing.status := v_status;
    v_existing.refund_case_id := COALESCE(v_existing.refund_case_id, v_case_id);
  END IF;

  -- Money moved only when the provider says succeeded. The ledger row is
  -- keyed on the provider refund id (patch 0001 index); payment_id stays NULL
  -- on case-less rows so the legacy (payment_id, entry_type) partial unique
  -- index can never collapse two distinct external refunds on one payment.
  IF COALESCE(v_existing.status, v_status) = 'succeeded' OR v_status = 'succeeded' THEN
    INSERT INTO public.ledger_entries(
      reservation_id, payment_id, refund_case_id, entry_type,
      amount_yen, currency, stripe_refund_id
    ) VALUES (
      v_payment.reservation_id,
      CASE WHEN COALESCE(v_existing.refund_case_id, v_case_id) IS NULL THEN NULL ELSE v_payment.id END,
      COALESCE(v_existing.refund_case_id, v_case_id),
      'refund_succeeded',
      -v_amount,
      'jpy',
      p_stripe_refund_id
    )
    ON CONFLICT DO NOTHING;
  END IF;

  -- Re-derive the payment posture from the whole provider refund set.
  v_derived := public.derive_vip_payment_refund_state_v8(v_payment.id);
  UPDATE public.payments
  SET status = (v_derived ->> 'derivedStatus')::public.payment_status,
      updated_at = now()
  WHERE id = v_payment.id
    AND status::text IN ('succeeded','refund_pending','refunded','partially_refunded')
    AND status::text IS DISTINCT FROM v_derived ->> 'derivedStatus';

  RETURN jsonb_build_object(
    'applied', true,
    'stripeRefundId', p_stripe_refund_id,
    'paymentId', v_payment.id,
    'reservationId', v_payment.reservation_id,
    'origin', v_origin,
    'providerStatus', v_status,
    'derived', v_derived
  );
END;
$_$;

-- FUNCTION: apply_stripe_provider_event_v21(text, text, text, text, text, text, timestamp with time zone, jsonb, boolean, text)
CREATE FUNCTION public.apply_stripe_provider_event_v21(p_environment text, p_stripe_account_id text, p_object_type text, p_object_id text, p_stripe_status text, p_last_event_id text, p_last_event_created_at timestamp with time zone, p_payload_json jsonb, p_apply_reservation_effect boolean DEFAULT false, p_reservation_provider_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_current public.stripe_object_states%ROWTYPE;
  v_reservation_result jsonb := NULL;
BEGIN
  IF p_environment NOT IN ('test', 'live')
    OR NULLIF(BTRIM(p_object_type), '') IS NULL
    OR NULLIF(BTRIM(p_object_id), '') IS NULL
    OR NULLIF(BTRIM(p_last_event_id), '') IS NULL
    OR p_last_event_created_at IS NULL THEN
    RAISE EXCEPTION 'invalid provider event identity';
  END IF;

  -- The advisory key closes the first-insert race where no row exists to lock.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      CONCAT_WS(
        E'\x1f',
        p_environment,
        COALESCE(p_stripe_account_id, 'platform'),
        p_object_type,
        p_object_id
      ),
      0
    )
  );

  SELECT *
  INTO v_current
  FROM public.stripe_object_states
  WHERE environment = p_environment
    AND stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
    AND object_type = p_object_type
    AND object_id = p_object_id
  FOR UPDATE;

  IF FOUND AND (
    v_current.last_event_created_at > p_last_event_created_at
    OR (
      v_current.last_event_created_at = p_last_event_created_at
      AND v_current.last_event_id >= p_last_event_id
    )
  ) THEN
    RETURN jsonb_build_object(
      'accepted', false,
      'reason', 'stale_or_duplicate_event',
      'winningEventId', v_current.last_event_id,
      'winningEventCreatedAt', v_current.last_event_created_at
    );
  END IF;

  PERFORM public.record_stripe_object_state_v7(
    p_environment,
    p_stripe_account_id,
    p_object_type,
    p_object_id,
    p_stripe_status,
    p_last_event_id,
    p_last_event_created_at,
    COALESCE(p_payload_json, '{}'::jsonb)
  );

  IF p_apply_reservation_effect THEN
    v_reservation_result := public.confirm_reservation_locks_v7(
      p_environment,
      p_stripe_account_id,
      p_object_type,
      p_object_id,
      COALESCE(NULLIF(BTRIM(p_reservation_provider_status), ''), p_stripe_status),
      COALESCE(p_payload_json, '{}'::jsonb)
    );
  END IF;

  RETURN jsonb_build_object(
    'accepted', true,
    'winningEventId', p_last_event_id,
    'winningEventCreatedAt', p_last_event_created_at,
    'reservationLockResult', v_reservation_result
  );
END;
$$;

-- FUNCTION: apply_stripe_provider_event_v22(text, text, text, text, text, text, timestamp with time zone, jsonb, boolean, text)
CREATE FUNCTION public.apply_stripe_provider_event_v22(p_environment text, p_stripe_account_id text, p_object_type text, p_object_id text, p_stripe_status text, p_last_event_id text, p_last_event_created_at timestamp with time zone, p_payload_json jsonb, p_apply_reservation_effect boolean DEFAULT false, p_reservation_provider_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_current public.stripe_object_states%ROWTYPE;
  v_reservation_result jsonb := NULL;
  v_finance_result jsonb := NULL;
BEGIN
  IF p_environment NOT IN ('test', 'live')
    OR NULLIF(BTRIM(p_object_type), '') IS NULL
    OR NULLIF(BTRIM(p_object_id), '') IS NULL
    OR NULLIF(BTRIM(p_last_event_id), '') IS NULL
    OR p_last_event_created_at IS NULL THEN
    RAISE EXCEPTION 'invalid provider event identity';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      CONCAT_WS(
        E'\x1f',
        p_environment,
        COALESCE(p_stripe_account_id, 'platform'),
        p_object_type,
        p_object_id
      ),
      0
    )
  );

  SELECT *
  INTO v_current
  FROM public.stripe_object_states
  WHERE environment = p_environment
    AND stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
    AND object_type = p_object_type
    AND object_id = p_object_id
  FOR UPDATE;

  IF FOUND AND (
    v_current.last_event_created_at > p_last_event_created_at
    OR (
      v_current.last_event_created_at = p_last_event_created_at
      AND v_current.last_event_id >= p_last_event_id
    )
  ) THEN
    RETURN jsonb_build_object(
      'accepted', false,
      'reason', 'stale_or_duplicate_event',
      'winningEventId', v_current.last_event_id,
      'winningEventCreatedAt', v_current.last_event_created_at
    );
  END IF;

  PERFORM public.record_stripe_object_state_v7(
    p_environment,
    p_stripe_account_id,
    p_object_type,
    p_object_id,
    p_stripe_status,
    p_last_event_id,
    p_last_event_created_at,
    COALESCE(p_payload_json, '{}'::jsonb)
  );

  -- Money objects are durable facts, not watermarks. refund.* / charge.refunded
  -- / charge.dispute.* write stripe_refunds / stripe_disputes / ledger and
  -- re-derive the payment posture, all inside this transaction.
  IF p_object_type IN ('refund', 'dispute', 'charge') THEN
    v_finance_result := public.record_external_stripe_money_event_v8(
      p_environment,
      p_stripe_account_id,
      p_object_type,
      p_object_id,
      p_stripe_status,
      p_last_event_id,
      p_last_event_created_at,
      COALESCE(p_payload_json, '{}'::jsonb)
    );
  END IF;

  IF p_apply_reservation_effect THEN
    v_reservation_result := public.confirm_reservation_locks_v7(
      p_environment,
      p_stripe_account_id,
      p_object_type,
      p_object_id,
      COALESCE(NULLIF(BTRIM(p_reservation_provider_status), ''), p_stripe_status),
      COALESCE(p_payload_json, '{}'::jsonb)
    );
  END IF;

  RETURN jsonb_build_object(
    'accepted', true,
    'winningEventId', p_last_event_id,
    'winningEventCreatedAt', p_last_event_created_at,
    'reservationLockResult', v_reservation_result,
    'externalFinanceResult', v_finance_result
  );
END;
$$;

-- FUNCTION: apply_ticket_checkout_refund_v28(uuid, uuid, uuid, text, text, text, text, text, text, text, text, timestamp with time zone, text, integer, text, integer[], text, boolean, text)
CREATE FUNCTION public.apply_ticket_checkout_refund_v28(p_ticket_order_id uuid, p_provider_checkout_action_id uuid, p_provider_event_session_id uuid, p_provider_check_in_mode text, p_environment text, p_stripe_account_id text, p_checkout_session_id text, p_client_reference_id text, p_payment_intent_id text, p_provider_flow text, p_provider_response_hash text, p_provider_expires_at timestamp with time zone, p_stripe_refund_id text, p_amount_yen integer, p_provider_status text, p_admission_serials integer[], p_provider_reason text, p_input_valid boolean, p_validation_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_binding jsonb;
  v_result jsonb;
  v_hold_cleared boolean := false;
BEGIN
  IF NULLIF(btrim(COALESCE(p_stripe_refund_id, '')), '') IS NULL
    OR p_amount_yen IS NULL OR p_amount_yen < 1
    OR COALESCE(p_provider_status, '') NOT IN ('succeeded', 'failed', 'canceled')
    OR cardinality(COALESCE(p_admission_serials, '{}'::integer[])) > 100
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'refund_provider_facts_invalid');
  END IF;

  v_binding := public.bind_verified_ticket_checkout_payment_v28(
    p_ticket_order_id, p_provider_checkout_action_id,
    p_provider_event_session_id, p_provider_check_in_mode,
    p_environment, p_stripe_account_id,
    p_checkout_session_id, p_client_reference_id, p_payment_intent_id,
    p_provider_flow, p_provider_response_hash, p_provider_expires_at);
  IF v_binding ->> 'action' NOT IN ('bound', 'reused') THEN
    RETURN v_binding;
  END IF;

  v_result := public.apply_ticket_refund_v26(
    p_environment, p_stripe_account_id, p_stripe_refund_id,
    p_payment_intent_id, p_amount_yen, p_provider_status,
    p_admission_serials, p_provider_reason, p_input_valid,
    p_validation_reason);
  IF v_result ->> 'action' IN ('not_found', 'rejected') THEN
    RAISE EXCEPTION 'verified ticket refund apply failed after binding: %', v_result;
  END IF;

  -- charge.refunded may precede its normalized Refund object. Clear that
  -- coarse payment hold only after allocation-ledger value proves the entire
  -- order and no successful refund remains unresolved.
  UPDATE public.ticket_orders AS ticket_order
  SET payment_hold_reason = NULL,
      payment_hold_at = NULL
  WHERE ticket_order.id = p_ticket_order_id
    AND ticket_order.payment_hold_reason = 'charge_refunded'
    AND (
      SELECT COALESCE(sum(allocation.amount_yen), 0)
      FROM public.ticket_refund_allocations AS allocation
      WHERE allocation.ticket_order_id = ticket_order.id
    ) >= ticket_order.amount_yen
    AND NOT EXISTS (
      SELECT 1
      FROM public.ticket_refund_events AS refund
      WHERE refund.ticket_order_id = ticket_order.id
        AND refund.money_may_have_moved
        AND refund.resolution_status IN ('review_required', 'conflict_review')
        AND refund.resolved_at IS NULL
    );
  v_hold_cleared := FOUND;
  IF v_hold_cleared THEN
    UPDATE public.ticket_checkout_actions
    SET state = CASE WHEN completed_at IS NOT NULL
          THEN 'completed' ELSE 'provider_created' END,
        review_reason = NULL,
        updated_at = now()
    WHERE id = (v_binding ->> 'checkoutActionId')::uuid
      AND review_reason = 'charge_refunded';
  END IF;
  RETURN v_result || jsonb_build_object(
    'checkoutActionId', v_binding ->> 'checkoutActionId',
    'paymentHoldCleared', v_hold_cleared);
END;
$$;

-- FUNCTION: apply_ticket_refund_v25(text, text, text, text, integer, text, integer[], text)
CREATE FUNCTION public.apply_ticket_refund_v25(p_environment text, p_stripe_account_id text, p_stripe_refund_id text, p_payment_intent_id text, p_amount_yen integer, p_provider_status text, p_admission_serials integer[], p_provider_reason text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT public.apply_ticket_refund_v26(
    p_environment, p_stripe_account_id, p_stripe_refund_id,
    p_payment_intent_id, p_amount_yen, p_provider_status,
    p_admission_serials, p_provider_reason, true, NULL
  );
$$;

-- FUNCTION: apply_ticket_refund_v26(text, text, text, text, integer, text, integer[], text, boolean, text)
CREATE FUNCTION public.apply_ticket_refund_v26(p_environment text, p_stripe_account_id text, p_stripe_refund_id text, p_payment_intent_id text, p_amount_yen integer, p_provider_status text, p_admission_serials integer[], p_provider_reason text, p_input_valid boolean, p_validation_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_order public.ticket_orders%ROWTYPE;
  v_existing public.ticket_refund_events%ROWTYPE;
  v_event public.ticket_refund_events%ROWTYPE;
  v_existing_order_id uuid;
  v_input_serials integer[];
  v_allocation_serials integer[] := '{}'::integer[];
  v_target_serials integer[] := '{}'::integer[];
  v_input_valid boolean := COALESCE(p_input_valid, false);
  v_validation_reason text := NULLIF(left(btrim(COALESCE(p_validation_reason, '')), 240), '');
  v_observation_hash text;
  v_next_observation_version bigint;
  v_resolution text := 'review_required';
  v_review_reason text;
  v_selected integer := 0;
  v_missing_price integer := 0;
  v_allocated_amount bigint := 0;
  v_admitted integer := 0;
  v_already_void integer := 0;
  v_cross_allocated integer := 0;
  v_voided integer := 0;
  v_inserted integer := 0;
BEGIN
  SELECT COALESCE(array_agg(serial ORDER BY serial), '{}'::integer[])
  INTO v_input_serials
  FROM unnest(COALESCE(p_admission_serials, '{}'::integer[])) AS serial;

  IF COALESCE(p_environment, '') NOT IN ('test', 'live')
    OR NULLIF(btrim(COALESCE(p_stripe_refund_id, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_payment_intent_id, '')), '') IS NULL
    OR p_amount_yen IS NULL OR p_amount_yen < 1
    OR COALESCE(p_provider_status, '') NOT IN ('succeeded', 'failed', 'canceled')
    OR cardinality(v_input_serials) > 100
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'refund_provider_facts_invalid');
  END IF;

  IF cardinality(v_input_serials) > 20
    OR EXISTS (SELECT 1 FROM unnest(v_input_serials) AS serial WHERE serial < 1 OR serial > 20)
    OR cardinality(v_input_serials) <>
       (SELECT count(DISTINCT serial) FROM unnest(v_input_serials) AS serial)
  THEN
    v_input_valid := false;
    v_validation_reason := COALESCE(v_validation_reason, 'admission_serials_invalid');
  END IF;
  IF NOT v_input_valid THEN
    v_validation_reason := COALESCE(v_validation_reason, 'recognized_ticket_refund_invalid');
  ELSE
    v_allocation_serials := v_input_serials;
    v_validation_reason := NULL;
  END IF;

  v_observation_hash := public.ticket_refund_observation_hash_v26(
    p_payment_intent_id, p_amount_yen, p_provider_status,
    v_input_serials, v_input_valid, v_validation_reason);

  -- A replay may carry a conflicting payment_intent_id. Resolve its original
  -- order non-lockingly, then acquire the order before the refund row so lock
  -- order remains order -> refund -> allocation -> admissions.
  SELECT e.ticket_order_id INTO v_existing_order_id
  FROM public.ticket_refund_events AS e
  WHERE e.environment = p_environment
    AND e.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
    AND e.stripe_refund_id = p_stripe_refund_id;

  IF v_existing_order_id IS NOT NULL THEN
    SELECT * INTO v_order
    FROM public.ticket_orders
    WHERE id = v_existing_order_id
    FOR UPDATE;
  ELSE
    SELECT * INTO v_order
    FROM public.ticket_orders
    WHERE environment = p_environment
      AND stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND payment_intent_id = p_payment_intent_id
    FOR UPDATE;
  END IF;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'not_found');
  END IF;

  SELECT * INTO v_existing
  FROM public.ticket_refund_events
  WHERE environment = p_environment
    AND stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
    AND stripe_refund_id = p_stripe_refund_id
  FOR UPDATE;

  IF FOUND THEN
    IF EXISTS (
      SELECT 1
      FROM public.ticket_refund_observations AS observation
      WHERE observation.ticket_refund_event_id = v_existing.id
        AND observation.facts_hash = v_observation_hash
    ) THEN
      RETURN jsonb_build_object(
        'action', 'reused',
        'orderId', v_existing.ticket_order_id,
        'refundEventId', v_existing.id,
        'resolutionStatus', v_existing.resolution_status,
        'resolutionVersion', v_existing.resolution_version,
        'observationVersion', v_existing.observation_version,
        'observationHash', v_existing.observation_set_hash,
        'reason', v_existing.review_reason,
        'voided', 0
      );
    END IF;

    v_next_observation_version := v_existing.observation_version + 1;
    INSERT INTO public.ticket_refund_observations(
      ticket_refund_event_id, observation_version, facts_hash,
      payment_intent_id, amount_yen, provider_status,
      input_admission_serials, input_valid, validation_reason
    ) VALUES (
      v_existing.id, v_next_observation_version, v_observation_hash,
      p_payment_intent_id, p_amount_yen, p_provider_status,
      v_input_serials, v_input_valid, v_validation_reason
    );

    UPDATE public.ticket_refund_events
    SET resolution_status = 'conflict_review',
        review_reason = CASE
          WHEN observation_history_state = 'legacy_incomplete'
            THEN 'refund_observation_history_incomplete'
          ELSE 'refund_replay_fact_conflict'
        END,
        resolved_at = NULL,
        resolution_version = resolution_version + 1,
        observation_version = v_next_observation_version,
        observation_set_hash = pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
          observation_set_hash || ':' || v_observation_hash, 'UTF8'), 'sha256'), 'hex'),
        conflict_count = conflict_count + 1,
        money_may_have_moved = money_may_have_moved
          OR p_provider_status = 'succeeded',
        last_conflict_at = now(),
        conflict_facts_json = jsonb_build_object(
          'paymentIntentId', p_payment_intent_id,
          'amountYen', p_amount_yen,
          'providerStatus', p_provider_status,
          'inputAdmissionSerials', to_jsonb(v_input_serials),
          'inputValid', v_input_valid,
          'validationReason', v_validation_reason
        ),
        updated_at = now()
    WHERE id = v_existing.id
    RETURNING * INTO v_existing;

    INSERT INTO public.audit_logs(
      action, actor_type, target_table, target_id,
      entity_type, entity_id, operation, reason, metadata_json
    ) VALUES (
      'ticket_refund.conflict_review', 'system', 'ticket_refund_events', v_existing.id,
      'ticket_refund_event', v_existing.id, 'update', 'refund_replay_fact_conflict',
      jsonb_build_object('stripeRefundId', p_stripe_refund_id,
                         'resolutionVersion', v_existing.resolution_version)
    );

    RETURN jsonb_build_object(
      'action', 'conflict_review',
      'orderId', v_existing.ticket_order_id,
      'refundEventId', v_existing.id,
      'resolutionStatus', v_existing.resolution_status,
      'resolutionVersion', v_existing.resolution_version,
      'observationVersion', v_existing.observation_version,
      'observationHash', v_existing.observation_set_hash,
      'reason', v_existing.review_reason,
      'voided', 0
    );
  END IF;

  IF p_provider_status IN ('failed', 'canceled') THEN
    v_review_reason := CASE
      WHEN p_provider_status = 'failed' THEN 'provider_refund_failed'
      ELSE 'provider_refund_canceled'
    END;
  ELSIF NOT v_input_valid THEN
    v_review_reason := v_validation_reason;
  ELSE
    IF p_amount_yen = v_order.amount_yen THEN
      SELECT COALESCE(array_agg(a.serial ORDER BY a.serial), '{}'::integer[])
      INTO v_target_serials
      FROM public.ticket_admissions AS a
      WHERE a.ticket_order_id = v_order.id;
    ELSIF cardinality(v_allocation_serials) = 0 THEN
      v_review_reason := 'admission_allocation_required';
    ELSE
      v_target_serials := v_allocation_serials;
    END IF;

    IF v_review_reason IS NULL THEN
      PERFORM 1
      FROM public.ticket_admissions AS a
      WHERE a.ticket_order_id = v_order.id
        AND a.serial = ANY(v_target_serials)
      ORDER BY a.serial
      FOR UPDATE;

      SELECT
        count(*),
        count(*) FILTER (WHERE a.status = 'admitted'),
        count(*) FILTER (WHERE a.status = 'void'),
        count(*) FILTER (WHERE price.unit_price_yen IS NULL),
        COALESCE(sum(price.unit_price_yen), 0),
        count(*) FILTER (WHERE allocated.ticket_admission_id IS NOT NULL)
      INTO v_selected, v_admitted, v_already_void, v_missing_price,
           v_allocated_amount, v_cross_allocated
      FROM public.ticket_admissions AS a
      LEFT JOIN LATERAL (
        SELECT CASE
          WHEN item.value ->> 'unitPriceYen' ~ '^[1-9][0-9]*$'
            THEN (item.value ->> 'unitPriceYen')::integer
          ELSE NULL
        END AS unit_price_yen
        FROM jsonb_array_elements(v_order.items_json) WITH ORDINALITY AS item(value, ordinality)
        WHERE item.value ->> 'ticketTypeId' = a.ticket_type_id
        ORDER BY item.ordinality
        LIMIT 1
      ) AS price ON true
      LEFT JOIN public.ticket_refund_allocations AS allocated
        ON allocated.ticket_admission_id = a.id
      WHERE a.ticket_order_id = v_order.id
        AND a.serial = ANY(v_target_serials);

      IF v_selected <> cardinality(v_target_serials) THEN
        v_review_reason := 'admission_not_found';
      ELSIF v_cross_allocated > 0 THEN
        v_review_reason := 'cross_refund_allocation_conflict';
      ELSIF v_admitted > 0 THEN
        v_review_reason := 'admission_already_admitted';
      ELSIF v_already_void > 0 THEN
        v_review_reason := 'admission_already_void';
      ELSIF v_missing_price > 0 OR v_allocated_amount <> p_amount_yen THEN
        v_review_reason := 'allocation_amount_mismatch';
      ELSE
        v_resolution := 'applied';
      END IF;
    END IF;
  END IF;

  INSERT INTO public.ticket_refund_events(
    ticket_order_id, environment, stripe_account_id, stripe_refund_id,
    payment_intent_id, amount_yen, provider_status, resolution_status,
    admission_serials, input_admission_serials, input_valid,
    money_may_have_moved, validation_reason, provider_reason, review_reason,
    observation_version, observation_set_hash
  ) VALUES (
    v_order.id, p_environment, p_stripe_account_id, p_stripe_refund_id,
    p_payment_intent_id, p_amount_yen, p_provider_status, v_resolution,
    v_allocation_serials, v_input_serials, v_input_valid,
    p_provider_status = 'succeeded', v_validation_reason,
    left(p_provider_reason, 240), v_review_reason,
    1, v_observation_hash
  ) RETURNING * INTO v_event;

  INSERT INTO public.ticket_refund_observations(
    ticket_refund_event_id, observation_version, facts_hash,
    payment_intent_id, amount_yen, provider_status,
    input_admission_serials, input_valid, validation_reason
  ) VALUES (
    v_event.id, 1, v_observation_hash,
    p_payment_intent_id, p_amount_yen, p_provider_status,
    v_input_serials, v_input_valid, v_validation_reason
  );

  IF p_provider_status = 'succeeded' AND p_amount_yen = v_order.amount_yen THEN
    UPDATE public.ticket_orders
    SET status = 'refunded',
        cancelled_at = COALESCE(cancelled_at, now())
    WHERE id = v_order.id
      AND status IN ('pending', 'paid', 'fulfilled');
  END IF;

  IF v_resolution = 'applied' THEN
    UPDATE public.ticket_admissions
    SET status = 'void',
        voided_at = now(),
        void_reason = left('stripe_refund:' || p_stripe_refund_id, 240)
    WHERE ticket_order_id = v_order.id
      AND serial = ANY(v_target_serials)
      AND status = 'issued';
    GET DIAGNOSTICS v_voided = ROW_COUNT;
    IF v_voided <> v_selected THEN
      RAISE EXCEPTION 'ticket refund void row-count mismatch: expected %, got %',
        v_selected, v_voided;
    END IF;

    INSERT INTO public.ticket_refund_allocations(
      ticket_refund_event_id, ticket_order_id, ticket_admission_id,
      admission_serial, environment, stripe_account_key, stripe_refund_id,
      amount_yen, outcome
    )
    SELECT
      v_event.id, v_order.id, a.id, a.serial,
      v_event.environment, v_event.stripe_account_key, v_event.stripe_refund_id,
      price.unit_price_yen, 'voided'
    FROM public.ticket_admissions AS a
    JOIN LATERAL (
      SELECT (item.value ->> 'unitPriceYen')::integer AS unit_price_yen
      FROM jsonb_array_elements(v_order.items_json) WITH ORDINALITY AS item(value, ordinality)
      WHERE item.value ->> 'ticketTypeId' = a.ticket_type_id
      ORDER BY item.ordinality
      LIMIT 1
    ) AS price ON true
    WHERE a.ticket_order_id = v_order.id
      AND a.serial = ANY(v_target_serials)
    ORDER BY a.serial;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted <> v_selected THEN
      RAISE EXCEPTION 'ticket refund allocation row-count mismatch: expected %, got %',
        v_selected, v_inserted;
    END IF;
  END IF;

  INSERT INTO public.audit_logs(
    action, actor_type, target_table, target_id,
    entity_type, entity_id, operation, reason, metadata_json
  ) VALUES (
    CASE WHEN v_resolution = 'applied'
      THEN 'ticket_refund.applied' ELSE 'ticket_refund.review_required' END,
    'system', 'ticket_refund_events', v_event.id,
    'ticket_refund_event', v_event.id, 'insert',
    COALESCE(v_review_reason, left(p_provider_reason, 240)),
    jsonb_build_object(
      'stripeRefundId', p_stripe_refund_id,
      'paymentIntentId', p_payment_intent_id,
      'amountYen', p_amount_yen,
      'providerStatus', p_provider_status,
      'inputAdmissionSerials', to_jsonb(v_input_serials),
      'allocationSerials', to_jsonb(v_target_serials),
      'voided', v_voided
    )
  );

  RETURN jsonb_build_object(
    'action', CASE WHEN v_resolution = 'applied' THEN 'applied' ELSE 'review_required' END,
    'orderId', v_order.id,
    'refundEventId', v_event.id,
    'resolutionStatus', v_resolution,
    'resolutionVersion', v_event.resolution_version,
    'observationVersion', v_event.observation_version,
    'observationHash', v_event.observation_set_hash,
    'reason', v_review_reason,
    'voided', v_voided
  );
END;
$_$;

-- FUNCTION: approve_admin_late_cancel_case_v7(uuid, text, text, text, text, uuid, boolean, text)
CREATE FUNCTION public.approve_admin_late_cancel_case_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_case_id uuid, p_approved boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_case late_cancel_cases%ROWTYPE;
  v_reservation reservations%ROWTYPE;
  v_terms reservation_charge_terms%ROWTYPE;
  v_payment_method payment_methods%ROWTYPE;
  v_payment_id uuid;
  v_attempt_id uuid;
  v_disarmed_attempt_ids uuid[];
  v_disarmed_payment_ids uuid[];
  v_response jsonb;
BEGIN
  SELECT * INTO v_admin FROM admin_users WHERE id = p_actor_admin_id FOR UPDATE;
  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;
  IF v_admin.role NOT IN ('manager','owner','engineer') THEN
    RAISE EXCEPTION 'admin role cannot approve late-cancel cases';
  END IF;

  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'reason is required for late-cancel approval decisions';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;
    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  SELECT * INTO v_case FROM late_cancel_cases WHERE id = p_case_id FOR UPDATE;
  IF NOT FOUND OR v_case.status NOT IN ('reported','approved') THEN
    RAISE EXCEPTION 'late-cancel case cannot be approved';
  END IF;

  IF v_case.reported_by_admin_id IS NOT NULL
    AND v_case.reported_by_admin_id = p_actor_admin_id THEN
    RAISE EXCEPTION 'reporting admin cannot approve own late-cancel case';
  END IF;

  SELECT * INTO v_reservation FROM reservations WHERE id = v_case.reservation_id FOR UPDATE;

  IF p_approved = false THEN
    UPDATE late_cancel_cases
    SET status = 'rejected',
        approved_by_admin_id = p_actor_admin_id,
        reviewed_at = now(),
        updated_at = now()
    WHERE id = v_case.id;

    -- W07-N2 (v75): identical disarm for the late-cancel path.
    WITH disarmed AS (
      DELETE FROM off_session_charge_attempts
      WHERE case_type = 'late_cancel'
        AND case_id = v_case.id
        AND status IN ('approved', 'processing', 'failed')
      RETURNING id, payment_id
    )
    SELECT COALESCE(array_agg(d.id), '{}'::uuid[]),
           COALESCE(array_agg(d.payment_id), '{}'::uuid[])
    INTO v_disarmed_attempt_ids, v_disarmed_payment_ids
    FROM disarmed d;

    UPDATE payments
    SET status = 'cancelled',
        updated_at = now()
    WHERE id = ANY (v_disarmed_payment_ids)
      AND status = 'requires_confirmation';

    UPDATE reservations
    SET status = 'cancelled',
        updated_at = now()
    WHERE id = v_case.reservation_id
      AND status = 'late_cancel_review';

    v_response := jsonb_build_object(
      'caseId', v_case.id,
      'reservationId', v_case.reservation_id,
      'approved', false,
      'disarmedOffSessionAttemptIds', COALESCE(v_disarmed_attempt_ids, '{}'::uuid[])
    );
  ELSE
    IF v_case.charge_amount_yen <= 0 THEN
      UPDATE late_cancel_cases
      SET status = 'waived',
          approved_by_admin_id = p_actor_admin_id,
          reviewed_at = now(),
          updated_at = now()
      WHERE id = v_case.id;

      UPDATE reservations
      SET status = 'cancelled',
          updated_at = now()
      WHERE id = v_case.reservation_id
        AND status = 'late_cancel_review';

      v_response := jsonb_build_object('caseId', v_case.id, 'reservationId', v_case.reservation_id, 'approved', true, 'waived', true);
    ELSE
      SELECT * INTO v_terms FROM reservation_charge_terms WHERE reservation_id = v_reservation.id;
      IF v_case.charge_amount_yen > COALESCE(v_terms.agreed_late_cancel_fee_yen, 0) THEN
        RAISE EXCEPTION 'charge amount exceeds consented late-cancel fee';
      END IF;

      SELECT pm.* INTO v_payment_method
      FROM payments p
      JOIN payment_methods pm ON pm.id = p.payment_method_id
      WHERE p.reservation_id = v_reservation.id
        AND p.type = 'deposit'
        AND p.status IN ('succeeded','refund_pending','refunded')
        AND pm.status = 'active'
        AND pm.customer_id = v_reservation.customer_id
        AND pm.stripe_customer_id IS NOT DISTINCT FROM p.stripe_customer_id
        AND pm.stripe_payment_method_id IS NOT DISTINCT FROM p.stripe_payment_method_id
        AND pm.environment = p.environment
        AND pm.stripe_account_id IS NOT DISTINCT FROM p.stripe_account_id
      ORDER BY p.created_at DESC, p.id DESC
      LIMIT 1
      FOR UPDATE OF pm;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'consented deposit payment method unavailable for late-cancel charge';
      END IF;

      INSERT INTO payments(
        reservation_id,
        payment_method_id,
        type,
        status,
        amount_yen,
        currency,
        environment,
        stripe_account_id,
        stripe_customer_id,
        stripe_payment_method_id,
        idempotency_key
      )
      VALUES (
        v_case.reservation_id,
        v_payment_method.id,
        'late_cancel_charge',
        'requires_confirmation',
        v_case.charge_amount_yen,
        'jpy',
        v_payment_method.environment,
        v_payment_method.stripe_account_id,
        v_payment_method.stripe_customer_id,
        v_payment_method.stripe_payment_method_id,
        'admin_late_cancel_charge:' || v_case.id
      )
      ON CONFLICT (environment, stripe_account_key, idempotency_key)
      DO UPDATE
      SET amount_yen = EXCLUDED.amount_yen,
          payment_method_id = EXCLUDED.payment_method_id,
          stripe_customer_id = EXCLUDED.stripe_customer_id,
          stripe_payment_method_id = EXCLUDED.stripe_payment_method_id,
          updated_at = now()
      RETURNING id INTO v_payment_id;

      INSERT INTO off_session_charge_attempts(
        case_type,
        case_id,
        reservation_id,
        payment_id,
        status,
        environment,
        stripe_account_id,
        amount_yen,
        currency,
        stripe_customer_id,
        stripe_payment_method_id,
        stripe_idempotency_key
      )
      VALUES (
        'late_cancel',
        v_case.id,
        v_case.reservation_id,
        v_payment_id,
        'approved',
        v_payment_method.environment,
        v_payment_method.stripe_account_id,
        v_case.charge_amount_yen,
        'jpy',
        v_payment_method.stripe_customer_id,
        v_payment_method.stripe_payment_method_id,
        'stripe_late_cancel_charge:' || v_case.id
      )
      ON CONFLICT (case_type, case_id)
      DO UPDATE
      SET status = 'approved',
          payment_id = EXCLUDED.payment_id,
          amount_yen = EXCLUDED.amount_yen,
          updated_at = now()
      RETURNING id INTO v_attempt_id;

      UPDATE late_cancel_cases
      SET status = 'approved',
          approved_by_admin_id = p_actor_admin_id,
          reviewed_at = now(),
          payment_method_id = v_payment_method.id,
          payment_id = v_payment_id,
          stripe_idempotency_key = 'stripe_late_cancel_charge:' || v_case.id,
          updated_at = now()
      WHERE id = v_case.id;

      -- W04C consolidation fix: the W07 patch dropped this head-era UPDATE
      -- while restructuring the branches. It is the only statement that moves
      -- a reservation out of 'late_cancel_review' after an approved charge;
      -- without it the booking would stay in review forever.
      UPDATE reservations
      SET status = 'cancelled',
          updated_at = now()
      WHERE id = v_case.reservation_id
        AND status = 'late_cancel_review';

      v_response := jsonb_build_object(
        'caseId', v_case.id,
        'reservationId', v_case.reservation_id,
        'approved', true,
        'paymentId', v_payment_id,
        'offSessionAttemptId', v_attempt_id
      );
    END IF;
  END IF;

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'late_cancel_cases', v_case.id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'reviewed', 'response', v_response);
END;
$$;

-- FUNCTION: approve_admin_no_show_case_v7(uuid, text, text, text, text, uuid, boolean, text)
CREATE FUNCTION public.approve_admin_no_show_case_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_case_id uuid, p_approved boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_case no_show_cases%ROWTYPE;
  v_reservation reservations%ROWTYPE;
  v_terms reservation_charge_terms%ROWTYPE;
  v_payment_method payment_methods%ROWTYPE;
  v_payment_id uuid;
  v_attempt_id uuid;
  v_disarmed_attempt_ids uuid[];
  v_disarmed_payment_ids uuid[];
  v_response jsonb;
BEGIN
  SELECT * INTO v_admin FROM admin_users WHERE id = p_actor_admin_id FOR UPDATE;
  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;
  IF v_admin.role NOT IN ('manager','owner','engineer') THEN
    RAISE EXCEPTION 'admin role cannot approve no-show cases';
  END IF;

  -- W07-G-49: every money-affecting decision requires a reason.
  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'reason is required for no-show approval decisions';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;
    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  SELECT * INTO v_case FROM no_show_cases WHERE id = p_case_id FOR UPDATE;
  IF NOT FOUND OR v_case.status NOT IN ('reported','approved') THEN
    RAISE EXCEPTION 'no-show case cannot be approved';
  END IF;

  -- W07-G-01: maker-checker. The reporter may never approve, even with a
  -- different session or higher role.
  IF v_case.reported_by_admin_id IS NOT NULL
    AND v_case.reported_by_admin_id = p_actor_admin_id THEN
    RAISE EXCEPTION 'reporting admin cannot approve own no-show case';
  END IF;

  SELECT * INTO v_reservation FROM reservations WHERE id = v_case.reservation_id FOR UPDATE;

  IF p_approved = false THEN
    UPDATE no_show_cases
    SET status = 'rejected',
        approved_by_admin_id = p_actor_admin_id,
        reviewed_at = now(),
        updated_at = now()
    WHERE id = v_case.id;

    -- W07-N2 (v75): a rejected case must not leave an armed charge attempt.
    -- The attempt row is deleted outright: a 'dead' row would surface in the
    -- incident scan forever and could be re-armed by a dead-item requeue,
    -- while deletion leaves the cancelled payment row and this audit entry as
    -- the complete record. An attempt that already succeeded cannot reach this
    -- branch (success moves the case to 'charged', which is not approvable).
    WITH disarmed AS (
      DELETE FROM off_session_charge_attempts
      WHERE case_type = 'no_show'
        AND case_id = v_case.id
        AND status IN ('approved', 'processing', 'failed')
      RETURNING id, payment_id
    )
    SELECT COALESCE(array_agg(d.id), '{}'::uuid[]),
           COALESCE(array_agg(d.payment_id), '{}'::uuid[])
    INTO v_disarmed_attempt_ids, v_disarmed_payment_ids
    FROM disarmed d;

    -- The attempt's payment row only ever exists in 'requires_confirmation'
    -- while the charge is still planned; cancelling it keeps payments and the
    -- rejected case consistent. A provider-completed payment is evidence and
    -- is never touched here.
    UPDATE payments
    SET status = 'cancelled',
        updated_at = now()
    WHERE id = ANY (v_disarmed_payment_ids)
      AND status = 'requires_confirmation';

    UPDATE reservations
    SET status = 'confirmed',
        updated_at = now()
    WHERE id = v_case.reservation_id
      AND status = 'no_show_review';

    v_response := jsonb_build_object(
      'caseId', v_case.id,
      'reservationId', v_case.reservation_id,
      'approved', false,
      'disarmedOffSessionAttemptIds', COALESCE(v_disarmed_attempt_ids, '{}'::uuid[])
    );
  ELSE
    IF v_case.charge_amount_yen <= 0 THEN
      UPDATE no_show_cases
      SET status = 'waived',
          approved_by_admin_id = p_actor_admin_id,
          reviewed_at = now(),
          updated_at = now()
      WHERE id = v_case.id;

      v_response := jsonb_build_object('caseId', v_case.id, 'reservationId', v_case.reservation_id, 'approved', true, 'waived', true);
    ELSE
      -- W07-G-01: re-verify the consent cap at approval time so a case filed
      -- before the fix (or after a terms change) cannot charge over consent.
      SELECT * INTO v_terms FROM reservation_charge_terms WHERE reservation_id = v_reservation.id;
      IF v_case.charge_amount_yen > COALESCE(v_terms.agreed_no_show_fee_yen, 0) THEN
        RAISE EXCEPTION 'charge amount exceeds consented no-show fee';
      END IF;

      -- W07-G-50: charge the payment method that was bound to the
      -- reservation's succeeded deposit payment. Verify the stored
      -- payment_methods row is still active, belongs to the reservation's
      -- customer, and still points at the recorded stripe objects. No
      -- silent fallback to the customer's latest card.
      SELECT pm.* INTO v_payment_method
      FROM payments p
      JOIN payment_methods pm ON pm.id = p.payment_method_id
      WHERE p.reservation_id = v_reservation.id
        AND p.type = 'deposit'
        AND p.status IN ('succeeded','refund_pending','refunded')
        AND pm.status = 'active'
        AND pm.customer_id = v_reservation.customer_id
        AND pm.stripe_customer_id IS NOT DISTINCT FROM p.stripe_customer_id
        AND pm.stripe_payment_method_id IS NOT DISTINCT FROM p.stripe_payment_method_id
        AND pm.environment = p.environment
        AND pm.stripe_account_id IS NOT DISTINCT FROM p.stripe_account_id
      ORDER BY p.created_at DESC, p.id DESC
      LIMIT 1
      FOR UPDATE OF pm;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'consented deposit payment method unavailable for no-show charge';
      END IF;

      INSERT INTO payments(
        reservation_id,
        payment_method_id,
        type,
        status,
        amount_yen,
        currency,
        environment,
        stripe_account_id,
        stripe_customer_id,
        stripe_payment_method_id,
        idempotency_key
      )
      VALUES (
        v_case.reservation_id,
        v_payment_method.id,
        'no_show_charge',
        'requires_confirmation',
        v_case.charge_amount_yen,
        'jpy',
        v_payment_method.environment,
        v_payment_method.stripe_account_id,
        v_payment_method.stripe_customer_id,
        v_payment_method.stripe_payment_method_id,
        'admin_no_show_charge:' || v_case.id
      )
      ON CONFLICT (environment, stripe_account_key, idempotency_key)
      DO UPDATE
      SET amount_yen = EXCLUDED.amount_yen,
          payment_method_id = EXCLUDED.payment_method_id,
          stripe_customer_id = EXCLUDED.stripe_customer_id,
          stripe_payment_method_id = EXCLUDED.stripe_payment_method_id,
          updated_at = now()
      RETURNING id INTO v_payment_id;

      INSERT INTO off_session_charge_attempts(
        case_type,
        case_id,
        reservation_id,
        payment_id,
        status,
        environment,
        stripe_account_id,
        amount_yen,
        currency,
        stripe_customer_id,
        stripe_payment_method_id,
        stripe_idempotency_key
      )
      VALUES (
        'no_show',
        v_case.id,
        v_case.reservation_id,
        v_payment_id,
        'approved',
        v_payment_method.environment,
        v_payment_method.stripe_account_id,
        v_case.charge_amount_yen,
        'jpy',
        v_payment_method.stripe_customer_id,
        v_payment_method.stripe_payment_method_id,
        'stripe_no_show_charge:' || v_case.id
      )
      ON CONFLICT (case_type, case_id)
      DO UPDATE
      SET status = 'approved',
          payment_id = EXCLUDED.payment_id,
          amount_yen = EXCLUDED.amount_yen,
          updated_at = now()
      RETURNING id INTO v_attempt_id;

      UPDATE no_show_cases
      SET status = 'approved',
          approved_by_admin_id = p_actor_admin_id,
          reviewed_at = now(),
          payment_method_id = v_payment_method.id,
          payment_id = v_payment_id,
          stripe_idempotency_key = 'stripe_no_show_charge:' || v_case.id,
          updated_at = now()
      WHERE id = v_case.id;

      v_response := jsonb_build_object(
        'caseId', v_case.id,
        'reservationId', v_case.reservation_id,
        'approved', true,
        'paymentId', v_payment_id,
        'offSessionAttemptId', v_attempt_id
      );
    END IF;
  END IF;

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'no_show_cases', v_case.id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'reviewed', 'response', v_response);
END;
$$;

-- FUNCTION: approve_admin_refund_case_v7(uuid, text, text, text, text, uuid, boolean, text)
CREATE FUNCTION public.approve_admin_refund_case_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_refund_case_id uuid, p_approved boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_case refund_cases%ROWTYPE;
  v_payment payments%ROWTYPE;
  v_reserved_amount bigint := 0;
  v_unlinked_refund_amount bigint := 0;
  v_remaining_amount bigint := 0;
  v_response jsonb;
BEGIN
  SELECT * INTO v_admin FROM admin_users WHERE id = p_actor_admin_id FOR UPDATE;
  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;
  IF v_admin.role NOT IN ('manager','owner','engineer','accountant') THEN
    RAISE EXCEPTION 'admin role cannot approve refunds';
  END IF;

  -- W07-G-49: reason is mandatory for approve and waive decisions.
  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'reason is required for refund approval decisions';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;
    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  SELECT * INTO v_case
  FROM refund_cases
  WHERE id = p_refund_case_id
  FOR UPDATE;

  -- W07-G-11: 'requested' review cases (produced by v8 refund_decision=
  -- 'review') must be resolved through resolve_admin_refund_review_v7,
  -- which requires an explicit final amount. Approving here would
  -- silently charge the full remaining ceiling. No baseline writer ever
  -- emitted 'requested', so no legacy rows are stranded by this.
  IF FOUND AND v_case.status = 'requested' THEN
    RAISE EXCEPTION 'refund review case must be resolved via resolve_admin_refund_review_v7';
  END IF;

  IF NOT FOUND OR v_case.status NOT IN ('required','failed','approved') THEN
    RAISE EXCEPTION 'refund case cannot be approved';
  END IF;

  -- W07-G-02: maker-checker. Admin-filed cases need a different approver.
  -- System-filed cases (requested_by_admin_id IS NULL, e.g.
  -- confirm_reservation_locks_v7 inventory-lost auto-file) are explicitly
  -- policy-bound: only owner or accountant may approve them.
  IF v_case.requested_by_admin_id IS NOT NULL THEN
    IF v_case.requested_by_admin_id = p_actor_admin_id THEN
      RAISE EXCEPTION 'requesting admin cannot approve own refund case';
    END IF;
  ELSIF v_admin.role NOT IN ('owner','accountant') THEN
    RAISE EXCEPTION 'system-filed refund case requires owner or accountant approval';
  END IF;

  -- W07-R-10: re-check remaining refundable amount under the payment row
  -- lock before re-approving an already-approved or previously failed case.
  IF p_approved THEN
    SELECT * INTO v_payment FROM payments WHERE id = v_case.payment_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'refund case payment not found';
    END IF;

    SELECT COALESCE(sum(rc.amount_yen), 0)
    INTO v_reserved_amount
    FROM refund_cases rc
    WHERE rc.payment_id = v_payment.id
      AND rc.id <> v_case.id
      AND rc.status IN ('required','requested','approved','processing','refunded');

    SELECT COALESCE(sum(sr.amount_yen), 0)
    INTO v_unlinked_refund_amount
    FROM stripe_refunds sr
    WHERE sr.payment_id = v_payment.id
      AND sr.refund_case_id IS NULL
      AND lower(sr.status) IN ('created','pending','succeeded');

    v_remaining_amount := v_payment.amount_yen - v_reserved_amount - v_unlinked_refund_amount;

    IF v_case.amount_yen > v_remaining_amount THEN
      RAISE EXCEPTION 'refund amount exceeds remaining refundable balance'
        USING ERRCODE = 'P0001',
              DETAIL = 'remaining_refundable_yen=' || v_remaining_amount;
    END IF;
  END IF;

  UPDATE refund_cases
  SET status = CASE WHEN p_approved THEN 'approved' ELSE 'waived' END,
      approved_by_admin_id = p_actor_admin_id,
      approved_at = now(),
      error_json = CASE WHEN p_approved THEN error_json ELSE jsonb_build_object('waivedReason', p_reason) END,
      updated_at = now()
  WHERE id = v_case.id;

  v_response := jsonb_build_object(
    'refundCaseId', v_case.id,
    'reservationId', v_case.reservation_id,
    'paymentId', v_case.payment_id,
    'approved', p_approved,
    'workerEligible', p_approved
  );

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'refund_cases', v_case.id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'reviewed', 'response', v_response);
END;
$$;

-- FUNCTION: archive_admin_reservation_note_v8(uuid, text, text, text, uuid, bigint, uuid, bigint, text)
CREATE FUNCTION public.archive_admin_reservation_note_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_reservation_version bigint, p_note_id uuid, p_expected_note_version bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation_note.archived';
  v_step jsonb;
  v_reservation public.reservations%ROWTYPE;
  v_note public.reservation_notes%ROWTYPE;
  v_note_version bigint;
  v_reservation_version bigint;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;
    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(p_actor_admin_id, 'reservation_note.write'),
      ARRAY['allowed']
    );
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_note_id IS NULL OR p_expected_note_version IS NULL OR p_expected_note_version < 1
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'noteCommand')
        )), ARRAY['allowed']
      );
    END IF;
    v_step := public.assert_reservation_version_v8(
      p_reservation_id, p_expected_reservation_version
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
    SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id;
    PERFORM sr.id FROM public.seat_resources AS sr
    WHERE EXISTS (
      SELECT 1 FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id AND rr.seat_resource_id = sr.id
    ) ORDER BY sr.id FOR UPDATE OF sr;
    PERFORM rr.id FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id ORDER BY rr.id FOR UPDATE OF rr;
    PERFORM rb.id FROM public.reservation_blocks AS rb
    WHERE rb.event_day_id = v_reservation.event_day_id
      AND rb.status = 'active'
      AND rb.start_at < v_reservation.expected_release_at
      AND rb.end_at > v_reservation.scheduled_start_at
    ORDER BY rb.id FOR UPDATE OF rb;
    SELECT * INTO v_note FROM public.reservation_notes
    WHERE id = p_note_id FOR UPDATE;
    IF NOT FOUND OR v_note.reservation_id <> v_reservation.id THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'NOT_FOUND', 'details', jsonb_build_object('entityType', 'note')
        )), ARRAY['allowed']
      );
    END IF;
    IF v_note.version <> p_expected_note_version THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'VERSION_CONFLICT', 'currentVersion', v_note.version, 'details', '{}'::jsonb
        )), ARRAY['allowed']
      );
    END IF;
    IF v_note.archived_at IS NOT NULL THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION', 'details', jsonb_build_object('reason', 'note_already_archived')
        )), ARRAY['allowed']
      );
    END IF;
    UPDATE public.reservation_notes
    SET archived_at = now(), updated_by_admin_id = p_actor_admin_id,
        version = version + 1, updated_at = now()
    WHERE id = v_note.id RETURNING version INTO v_note_version;
    UPDATE public.reservations
    SET version = version + 1, updated_at = now()
    WHERE id = v_reservation.id RETURNING version INTO v_reservation_version;

    PERFORM ed.id FROM public.event_days AS ed
    WHERE ed.id = v_reservation.event_day_id FOR KEY SHARE OF ed;
    PERFORM public.lock_vip_floor_day_revision_v32(v_reservation.event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1 INTO v_predicted_revision
    FROM (SELECT 1) AS seed LEFT JOIN public.vip_floor_day_revisions AS vfr
      ON vfr.event_day_id = v_reservation.event_day_id;
    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, v_reservation.event_day_id, v_reservation.id,
      'note', v_note.id, v_action, p_request_id, p_reason,
      p_expected_note_version, v_note.version, v_note_version,
      ARRAY['archived_at', 'version'],
      jsonb_build_object('archived', false, 'version', v_note.version),
      jsonb_build_object('archived', true, 'version', v_note_version),
      '{}'::jsonb
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_response := jsonb_build_object(
      'ok', true, 'action', v_action, 'reused', false,
      'noteId', v_note.id, 'entityVersion', v_note_version,
      'reservationVersion', v_reservation_version,
      'boardRevision', v_predicted_revision, 'auditLogId', v_audit_id
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(v_reservation.event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'XX000', MESSAGE = 'VIP floor revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS v_error_detail = PG_EXCEPTION_DETAIL, v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN RETURN v_error_detail::jsonb; END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: assert_assignment_conflict_free_v8(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, timestamp with time zone)
CREATE FUNCTION public.assert_assignment_conflict_free_v8(p_event_day_id uuid, p_reservation_id uuid, p_seat_resource_id uuid, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_as_of timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_seat public.seat_resources%ROWTYPE;
  v_reservation_event_day_id uuid;
  v_assignment record;
  v_block record;
  v_online_warnings jsonb := '[]'::jsonb;
BEGIN
  IF p_event_day_id IS NULL
    OR p_seat_resource_id IS NULL
    OR p_start_at IS NULL
    OR p_end_at IS NULL
    OR p_as_of IS NULL
    OR p_start_at >= p_end_at
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object(
          'field', CASE
            WHEN p_event_day_id IS NULL THEN 'eventDayId'
            WHEN p_seat_resource_id IS NULL THEN 'tableId'
            WHEN p_as_of IS NULL THEN 'asOf'
            ELSE 'interval'
          END
        )
      )
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.event_days
    WHERE id = p_event_day_id
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'NOT_FOUND',
        'details', jsonb_build_object(
          'entityType', 'event_day'
        )
      )
    );
  END IF;

  IF p_reservation_id IS NOT NULL THEN
    SELECT event_day_id
    INTO v_reservation_event_day_id
    FROM public.reservations
    WHERE id = p_reservation_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object(
        'action', 'rejected',
        'error', jsonb_build_object(
          'code', 'NOT_FOUND',
          'details', jsonb_build_object(
            'entityType', 'reservation'
          )
        )
      );
    END IF;

    IF v_reservation_event_day_id <> p_event_day_id THEN
      RETURN jsonb_build_object(
        'action', 'rejected',
        'error', jsonb_build_object(
          'code', 'INVALID_COMMAND',
          'details', jsonb_build_object(
            'field', 'eventDayId',
            'reason', 'reservation_event_day_mismatch'
          )
        )
      );
    END IF;
  END IF;

  -- The caller must already hold every target seat lock in UUID order. This
  -- re-read happens after that lock and before relation/block conflict checks.
  SELECT *
  INTO v_seat
  FROM public.seat_resources
  WHERE id = p_seat_resource_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'NOT_FOUND',
        'details', jsonb_build_object(
          'entityType', 'table'
        )
      )
    );
  END IF;

  IF v_seat.active = false OR v_seat.operational_locked THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'TABLE_LOCKED',
        'details', jsonb_strip_nulls(jsonb_build_object(
          'tableDisplayCode', v_seat.display_code,
          'reason', CASE
            WHEN v_seat.active = false THEN 'inactive'
            ELSE 'operational_locked'
          END
        ))
      )
    );
  END IF;

  -- Lock overlapping relation rows in UUID order after the caller's seat lock.
  PERFORM rr.id
  FROM public.reservation_resources AS rr
  WHERE rr.seat_resource_id = p_seat_resource_id
    AND (p_reservation_id IS NULL OR rr.reservation_id <> p_reservation_id)
    AND rr.assigned_start_at < p_end_at
    AND rr.assigned_end_at > p_start_at
    AND public.active_reservation_assignment_v8(rr.id, p_as_of)
  ORDER BY rr.id
  FOR UPDATE OF rr;

  SELECT
    rr.id AS reservation_resource_id,
    rr.reservation_id,
    rr.assigned_start_at,
    rr.assigned_end_at,
    r.public_code
  INTO v_assignment
  FROM public.reservation_resources AS rr
  JOIN public.reservations AS r
    ON r.id = rr.reservation_id
  WHERE rr.seat_resource_id = p_seat_resource_id
    AND (p_reservation_id IS NULL OR rr.reservation_id <> p_reservation_id)
    AND rr.assigned_start_at < p_end_at
    AND rr.assigned_end_at > p_start_at
    AND public.active_reservation_assignment_v8(rr.id, p_as_of)
  ORDER BY rr.assigned_start_at, r.public_code, rr.id
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'TABLE_TIME_CONFLICT',
        'details', jsonb_build_object(
          'tableDisplayCode', v_seat.display_code,
          'conflictingReservationPublicCode', v_assignment.public_code,
          'conflictingStartAt', v_assignment.assigned_start_at,
          'conflictingEndAt', v_assignment.assigned_end_at
        )
      )
    );
  END IF;

  -- Lock every overlapping active block in UUID order. Target matching includes
  -- table, section, and venue-wide rows; overlap is the strict half-open test.
  PERFORM rb.id
  FROM public.reservation_blocks AS rb
  WHERE rb.event_day_id = p_event_day_id
    AND rb.status = 'active'
    AND rb.start_at < p_end_at
    AND rb.end_at > p_start_at
    AND EXISTS (
      SELECT 1
      FROM public.reservation_block_targets AS rbt
      WHERE rbt.block_id = rb.id
        AND (
          rbt.seat_resource_id = p_seat_resource_id
          OR rbt.floor_section_id = v_seat.floor_section_id
          OR rbt.venue_wide
        )
    )
  ORDER BY rb.id
  FOR UPDATE OF rb;

  SELECT rb.id, rb.kind, rb.start_at, rb.end_at
  INTO v_block
  FROM public.reservation_blocks AS rb
  WHERE rb.event_day_id = p_event_day_id
    AND rb.status = 'active'
    AND rb.scope = 'all_operations'
    AND rb.start_at < p_end_at
    AND rb.end_at > p_start_at
    AND EXISTS (
      SELECT 1
      FROM public.reservation_block_targets AS rbt
      WHERE rbt.block_id = rb.id
        AND (
          rbt.seat_resource_id = p_seat_resource_id
          OR rbt.floor_section_id = v_seat.floor_section_id
          OR rbt.venue_wide
        )
    )
  ORDER BY rb.start_at, rb.id
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'BLOCK_CONFLICT',
        'details', jsonb_build_object(
          'tableDisplayCode', v_seat.display_code,
          'blockKind', v_block.kind,
          'conflictingStartAt', v_block.start_at,
          'conflictingEndAt', v_block.end_at
        )
      )
    );
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'code', 'ONLINE_ONLY_BLOCK',
        'blockKind', rb.kind,
        'startAt', rb.start_at,
        'endAt', rb.end_at
      )
      ORDER BY rb.start_at, rb.id
    ),
    '[]'::jsonb
  )
  INTO v_online_warnings
  FROM public.reservation_blocks AS rb
  WHERE rb.event_day_id = p_event_day_id
    AND rb.status = 'active'
    AND rb.scope = 'online_only'
    AND rb.start_at < p_end_at
    AND rb.end_at > p_start_at
    AND EXISTS (
      SELECT 1
      FROM public.reservation_block_targets AS rbt
      WHERE rbt.block_id = rb.id
        AND (
          rbt.seat_resource_id = p_seat_resource_id
          OR rbt.floor_section_id = v_seat.floor_section_id
          OR rbt.venue_wide
        )
    );

  RETURN jsonb_build_object(
    'action', 'allowed',
    'tableId', v_seat.id,
    'tableDisplayCode', v_seat.display_code,
    'interval', jsonb_build_object(
      'startAt', p_start_at,
      'endAt', p_end_at
    ),
    'warnings', v_online_warnings
  );
END;
$$;

-- FUNCTION: assert_reservation_version_v8(uuid, bigint)
CREATE FUNCTION public.assert_reservation_version_v8(p_reservation_id uuid, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_reservation public.reservations%ROWTYPE;
BEGIN
  IF p_reservation_id IS NULL OR p_expected_version IS NULL OR p_expected_version < 1 THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object(
          'field', CASE
            WHEN p_reservation_id IS NULL THEN 'reservationId'
            ELSE 'expectedVersion'
          END
        )
      )
    );
  END IF;

  -- This is the first entity lock. The caller locks sorted seats/relations and
  -- blocks next, appends audit, then bumps the day revision last.
  SELECT *
  INTO v_reservation
  FROM public.reservations
  WHERE id = p_reservation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'NOT_FOUND',
        'details', jsonb_build_object(
          'entityType', 'reservation'
        )
      )
    );
  END IF;

  IF v_reservation.version <> p_expected_version THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'VERSION_CONFLICT',
        'currentVersion', v_reservation.version,
        'details', '{}'::jsonb
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'action', 'allowed',
    'reservationId', v_reservation.id,
    'eventDayId', v_reservation.event_day_id,
    'currentVersion', v_reservation.version
  );
END;
$$;

-- FUNCTION: assert_vip_floor_helper_success_v8(jsonb, text[])
CREATE FUNCTION public.assert_vip_floor_helper_success_v8(p_result jsonb, p_allowed_actions text[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action text;
BEGIN
  IF p_result IS NULL OR jsonb_typeof(p_result) <> 'object' THEN
    RAISE EXCEPTION USING
      ERRCODE = 'XX000',
      MESSAGE = 'VIP floor helper returned a malformed result';
  END IF;

  v_action := p_result ->> 'action';
  IF v_action = ANY(COALESCE(p_allowed_actions, '{}'::text[])) THEN
    RETURN;
  END IF;

  IF v_action <> 'rejected'
    OR jsonb_typeof(p_result -> 'error') <> 'object'
    OR NULLIF(p_result #>> '{error,code}', '') IS NULL
  THEN
    RAISE EXCEPTION USING
      ERRCODE = 'XX000',
      MESSAGE = 'VIP floor helper returned an unexpected action';
  END IF;

  -- Only this marked exception is caught by external RPCs. The surrounding
  -- PL/pgSQL exception block is a subtransaction, so the preclaim and every
  -- later write are rolled back before this sanitized JSON is returned.
  RAISE EXCEPTION USING
    ERRCODE = 'P0001',
    MESSAGE = 'VIP floor command rejected',
    DETAIL = p_result::text,
    CONSTRAINT = 'vip_floor_business_rejection_v8';
END;
$$;

-- FUNCTION: assign_admin_reservation_resource_v7(uuid, text, text, text, text, uuid, text, text)
CREATE FUNCTION public.assign_admin_reservation_resource_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_public_resource_code text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_reservation reservations%ROWTYPE;
  v_slot booking_slots%ROWTYPE;
  v_resource seat_resources%ROWTYPE;
  v_lock_status reservation_lock_status := 'held';
  v_released_count int := 0;
  v_response jsonb;
BEGIN
  SELECT * INTO v_admin FROM admin_users WHERE id = p_actor_admin_id FOR UPDATE;
  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;
  IF v_admin.role NOT IN ('manager','owner','engineer') THEN
    RAISE EXCEPTION 'admin role cannot assign reservations';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;
    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  SELECT * INTO v_reservation FROM reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND OR v_reservation.status IN ('cancelled','hold_expired','payment_window_expired','failed','checked_in') THEN
    RAISE EXCEPTION 'reservation cannot be assigned';
  END IF;

  SELECT * INTO v_slot FROM booking_slots WHERE id = v_reservation.booking_slot_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'booking slot not found';
  END IF;

  SELECT * INTO v_resource
  FROM seat_resources
  WHERE public_resource_code = p_public_resource_code
    AND active = true
    AND v_reservation.guest_count BETWEEN capacity_min AND capacity_max
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'seat resource not found';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM reservation_resources rr
    JOIN reservations r ON r.id = rr.reservation_id
    JOIN booking_slots locked_slot ON locked_slot.id = r.booking_slot_id
    WHERE rr.seat_resource_id = v_resource.id
      AND rr.reservation_id <> v_reservation.id
      AND locked_slot.start_at < v_slot.end_at
      AND locked_slot.end_at > v_slot.start_at
      AND rr.lock_status IN ('held','payment_grace_locked','confirmed')
      AND r.status NOT IN ('cancelled','hold_expired','payment_window_expired','failed')
      AND (
        rr.lock_status = 'confirmed'
        OR COALESCE(rr.hold_expires_at, rr.admin_hold_expires_at, r.hold_expires_at, r.admin_hold_expires_at, 'infinity'::timestamptz) > now()
      )
  ) THEN
    RAISE EXCEPTION 'seat resource is already locked';
  END IF;

  IF v_reservation.status = 'confirmed' THEN
    v_lock_status := 'confirmed';
  END IF;

  UPDATE reservation_resources
  SET lock_status = 'released',
      released_at = now(),
      updated_at = now()
  WHERE reservation_id = v_reservation.id
    AND seat_resource_id <> v_resource.id
    AND lock_status IN ('held','payment_grace_locked','confirmed');

  GET DIAGNOSTICS v_released_count = ROW_COUNT;

  INSERT INTO reservation_resources(
    reservation_id,
    seat_resource_id,
    lock_status,
    hold_expires_at,
    admin_hold_expires_at,
    confirmed_at,
    released_at
  )
  VALUES (
    v_reservation.id,
    v_resource.id,
    v_lock_status,
    v_reservation.hold_expires_at,
    v_reservation.admin_hold_expires_at,
    CASE WHEN v_lock_status = 'confirmed' THEN COALESCE(v_reservation.confirmed_at, now()) ELSE NULL END,
    NULL
  )
  ON CONFLICT (reservation_id, seat_resource_id)
  DO UPDATE
  SET lock_status = EXCLUDED.lock_status,
      hold_expires_at = EXCLUDED.hold_expires_at,
      admin_hold_expires_at = EXCLUDED.admin_hold_expires_at,
      confirmed_at = EXCLUDED.confirmed_at,
      released_at = NULL,
      updated_at = now();

  v_response := jsonb_build_object(
    'reservationId', v_reservation.id,
    'resourceId', v_resource.id,
    'publicResourceCode', v_resource.public_resource_code,
    'lockStatus', v_lock_status,
    'releasedResourceCount', v_released_count
  );

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'reservations', v_reservation.id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'assigned', 'response', v_response);
END;
$$;

-- FUNCTION: assign_ticket_wallet_holder_v34()
CREATE FUNCTION public.assign_ticket_wallet_holder_v34() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE h uuid;
BEGIN
 IF NEW.auth_method='passkey' THEN
  IF NOT EXISTS(SELECT 1 FROM public.ticket_wallet_credentials c JOIN public.ticket_wallet_holders h ON h.id=c.holder_id
   WHERE c.id=NEW.credential_id AND c.holder_id=NEW.holder_id AND c.revoked_at IS NULL AND h.environment=NEW.environment) THEN
   RAISE EXCEPTION 'passkey session holder mismatch'; END IF;
  RETURN NEW;
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('ticket-holder-email:'||NEW.environment||':'||NEW.identity_email_hash,0));
 SELECT holder_id INTO h FROM public.ticket_holder_email_identities WHERE environment=NEW.environment AND identity_email_hash=NEW.identity_email_hash;
 IF h IS NULL THEN
  INSERT INTO public.ticket_wallet_holders(environment) VALUES(NEW.environment) RETURNING id INTO h;
  INSERT INTO public.ticket_holder_email_identities VALUES(NEW.environment,NEW.identity_email_hash,h);
  INSERT INTO public.ticket_wallet_credential_audits(holder_id,session_id,action) VALUES(h,NEW.id,'holder_migrated');
 END IF;
 PERFORM 1 FROM public.ticket_wallet_holders WHERE id=h FOR UPDATE;
 NEW.holder_id:=h;
 INSERT INTO public.ticket_holder_orders(holder_id,ticket_order_id,grant_method)
 SELECT h,o.id,'email_otp' FROM public.ticket_orders o
 WHERE o.environment=NEW.environment AND o.purchaser_email_hash=NEW.identity_email_hash AND o.check_in_mode='wallet_swipe'
 AND o.status='fulfilled' AND o.paid_at IS NOT NULL AND o.fulfilled_at IS NOT NULL ON CONFLICT DO NOTHING;
 RETURN NEW;
END; $$;

-- FUNCTION: attach_public_reservation_gclid_v58(uuid, text)
CREATE FUNCTION public.attach_public_reservation_gclid_v58(p_reservation_id uuid, p_gclid text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_reservation_id IS NULL THEN
    RETURN jsonb_build_object('attached', false, 'error', 'reservation_required');
  END IF;

  IF p_gclid IS NULL
    OR length(btrim(p_gclid)) < 4
    OR length(p_gclid) > 500
    OR p_gclid ~ '\s'
  THEN
    RETURN jsonb_build_object('attached', false, 'error', 'invalid_gclid');
  END IF;

  UPDATE public.reservations
  SET gclid = btrim(p_gclid),
      updated_at = now()
  WHERE id = p_reservation_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('attached', false, 'error', 'not_found');
  END IF;

  RETURN jsonb_build_object('attached', true);
END;
$$;

-- FUNCTION: authenticate_admin_session_v7(text, text)
CREATE FUNCTION public.authenticate_admin_session_v7(p_session_token_hash text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_session admin_sessions%ROWTYPE;
  v_admin admin_users%ROWTYPE;
BEGIN
  SELECT * INTO v_session
  FROM admin_sessions
  WHERE session_token_hash = p_session_token_hash
  FOR UPDATE;

  IF NOT FOUND OR v_session.active = false OR v_session.expires_at <= now() THEN
    RAISE EXCEPTION 'invalid or expired admin session';
  END IF;

  SELECT * INTO v_admin
  FROM admin_users
  WHERE id = v_session.admin_user_id
  FOR UPDATE;

  IF NOT FOUND OR v_admin.active = false THEN
    UPDATE admin_sessions
    SET active = false,
        retired_at = COALESCE(retired_at, now()),
        updated_at = now()
    WHERE id = v_session.id;

    RAISE EXCEPTION 'admin is retired';
  END IF;

  UPDATE admin_sessions
  SET last_seen_at = now(),
      updated_at = now()
  WHERE id = v_session.id;

  RETURN jsonb_build_object(
    'adminId', v_admin.id,
    'sessionId', v_session.id,
    'role', v_admin.role,
    'displayName', v_admin.display_name,
    'requestId', p_request_id
  );
END;
$$;

-- FUNCTION: backfill_legacy_ticket_event_sessions_v27()
CREATE FUNCTION public.backfill_legacy_ticket_event_sessions_v27() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_missing_event_days integer;
  v_inserted integer := 0;
  v_bound integer := 0;
  v_remaining integer;
BEGIN
  SELECT count(*) INTO v_missing_event_days
  FROM (
    SELECT DISTINCT ticket_order.event_date
    FROM public.ticket_orders AS ticket_order
    LEFT JOIN public.event_days AS event_day
      ON event_day.business_date = ticket_order.event_date
    WHERE ticket_order.check_in_mode = 'legacy_qr'
      AND ticket_order.event_session_id IS NULL
      AND event_day.id IS NULL
  ) AS missing;
  IF v_missing_event_days > 0 THEN
    RAISE EXCEPTION
      'legacy ticket Event Session backfill requires % missing Event Day rows',
      v_missing_event_days;
  END IF;

  PERFORM 1
  FROM public.event_days AS event_day
  WHERE EXISTS (
    SELECT 1 FROM public.ticket_orders AS ticket_order
    WHERE ticket_order.check_in_mode = 'legacy_qr'
      AND ticket_order.event_session_id IS NULL
      AND ticket_order.event_date = event_day.business_date
  )
  ORDER BY event_day.id
  FOR UPDATE;

  INSERT INTO public.ticket_event_sessions(
    event_day_id, catalog_event_id, event_date, environment,
    stripe_account_id, venue_timezone, door_at, close_at,
    admission_opens_at, admission_closes_at, sales_check_in_mode,
    sales_state, admission_state, materialization_source
  )
  SELECT DISTINCT
    event_day.id, ticket_order.event_id, ticket_order.event_date,
    ticket_order.environment, ticket_order.stripe_account_id, 'Asia/Tokyo',
    schedule_window.door_at,
    schedule_window.door_at + interval '7 hours',
    schedule_window.door_at - interval '30 minutes',
    schedule_window.door_at + interval '7 hours 30 minutes',
    'legacy_qr', 'draining', 'scheduled', 'legacy_v27_backfill'
  FROM public.ticket_orders AS ticket_order
  JOIN public.event_days AS event_day
    ON event_day.business_date = ticket_order.event_date
  CROSS JOIN LATERAL (
    SELECT make_timestamptz(
      extract(year FROM ticket_order.event_date)::integer,
      extract(month FROM ticket_order.event_date)::integer,
      extract(day FROM ticket_order.event_date)::integer,
      22, 0, 0, 'Asia/Tokyo'
    ) AS door_at
  ) AS schedule_window
  WHERE ticket_order.check_in_mode = 'legacy_qr'
    AND ticket_order.event_session_id IS NULL
  ON CONFLICT ON CONSTRAINT uq_ticket_event_sessions_natural_v27 DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  PERFORM 1
  FROM public.ticket_event_sessions AS session
  WHERE EXISTS (
    SELECT 1 FROM public.ticket_orders AS ticket_order
    WHERE ticket_order.check_in_mode = 'legacy_qr'
      AND ticket_order.event_session_id IS NULL
      AND ticket_order.event_id = session.catalog_event_id
      AND ticket_order.event_date = session.event_date
      AND ticket_order.environment = session.environment
      AND ticket_order.stripe_account_key = session.stripe_account_key
  )
  ORDER BY session.id
  FOR UPDATE;

  PERFORM 1
  FROM public.ticket_orders AS ticket_order
  WHERE ticket_order.check_in_mode = 'legacy_qr'
    AND ticket_order.event_session_id IS NULL
  ORDER BY ticket_order.id
  FOR UPDATE;

  UPDATE public.ticket_orders AS ticket_order
  SET event_session_id = session.id
  FROM public.ticket_event_sessions AS session
  WHERE ticket_order.check_in_mode = 'legacy_qr'
    AND ticket_order.event_session_id IS NULL
    AND ticket_order.event_id = session.catalog_event_id
    AND ticket_order.event_date = session.event_date
    AND ticket_order.environment = session.environment
    AND ticket_order.stripe_account_key = session.stripe_account_key;
  GET DIAGNOSTICS v_bound = ROW_COUNT;

  SELECT count(*) INTO v_remaining
  FROM public.ticket_orders
  WHERE check_in_mode = 'legacy_qr' AND event_session_id IS NULL;
  IF v_remaining > 0 THEN
    RAISE EXCEPTION
      'legacy ticket Event Session backfill left % unbound orders', v_remaining;
  END IF;

  RETURN jsonb_build_object(
    'action', 'backfilled', 'eventSessionsCreated', v_inserted,
    'legacyOrdersBound', v_bound);
END;
$$;

-- FUNCTION: begin_public_reservation_hold_v7(text, text, text, text, text, integer, text, text, text, text, integer, integer)
CREATE FUNCTION public.begin_public_reservation_hold_v7(p_source_system text, p_idempotency_key text, p_request_hash text, p_public_slot_id text, p_public_offering_id text, p_guest_count integer, p_customer_email_hash text, p_customer_phone_hash text, p_public_resource_code text DEFAULT NULL::text, p_payment_type text DEFAULT 'card_setup'::text, p_deposit_amount_yen integer DEFAULT 0, p_hold_minutes integer DEFAULT 15) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_existing reservation_hold_requests%ROWTYPE;
  v_existing_response jsonb;
  v_slot booking_slots%ROWTYPE;
  v_offering booking_offerings%ROWTYPE;
  v_customer_id uuid;
  v_reservation_id uuid;
  v_payment_id uuid;
  v_resource_id uuid;
  v_hold_expires_at timestamptz;
  v_status reservation_status;
  v_payment_type payment_type;
  v_stripe_idempotency_key text;
  v_public_code text;
  v_status_token text;
  v_amount_yen int;
BEGIN
  IF p_source_system NOT IN ('pure_web','pure_admin','pure_system') THEN
    RAISE EXCEPTION 'invalid source system';
  END IF;

  IF p_idempotency_key IS NULL OR length(trim(p_idempotency_key)) < 8 THEN
    RAISE EXCEPTION 'invalid idempotency key';
  END IF;

  SELECT * INTO v_existing
  FROM reservation_hold_requests
  WHERE source_system = p_source_system
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;

    SELECT response_snapshot_json INTO v_existing_response
    FROM reservation_hold_requests
    WHERE id = v_existing.id;

    SELECT r.id, r.customer_id, p.id, p.type, p.amount_yen, r.hold_expires_at, r.public_code
    INTO v_reservation_id, v_customer_id, v_payment_id, v_payment_type, v_amount_yen, v_hold_expires_at, v_public_code
    FROM reservations r
    JOIN payments p ON p.reservation_id = r.id
    WHERE r.id = v_existing.reservation_id
    ORDER BY p.created_at DESC
    LIMIT 1;

    v_status_token := v_existing_response->>'statusToken';

    RETURN jsonb_build_object(
      'action', 'reused',
      'reservationId', v_reservation_id,
      'holdRequestId', v_existing.id,
      'paymentId', v_payment_id,
      'customerId', v_customer_id,
      'publicCode', v_public_code,
      'statusToken', v_status_token,
      'status', v_existing.status,
      'stripeIdempotencyKey', v_existing.stripe_idempotency_key,
      'paymentType', v_payment_type,
      'amountYen', v_amount_yen,
      'holdExpiresAt', v_hold_expires_at,
      'providerObjectType', v_existing.provider_object_type,
      'providerObjectId', v_existing.provider_object_id,
      'response', v_existing_response
    );
  END IF;

  SELECT * INTO v_slot
  FROM booking_slots
  WHERE public_slot_id = p_public_slot_id
    AND active = true
    AND admin_only = false
    AND bookable_until_at > now()
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'booking slot is unavailable';
  END IF;

  SELECT * INTO v_offering
  FROM booking_offerings
  WHERE public_offering_id = p_public_offering_id
    AND active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'booking offering is unavailable';
  END IF;

  IF p_guest_count NOT BETWEEN v_offering.min_guests AND v_offering.max_guests THEN
    RAISE EXCEPTION 'guest count is outside offering limits';
  END IF;

  IF p_payment_type NOT IN ('card_setup','deposit') THEN
    RAISE EXCEPTION 'invalid payment type';
  END IF;

  v_payment_type := p_payment_type::payment_type;

  IF v_payment_type = 'deposit' AND p_deposit_amount_yen <= 0 THEN
    RAISE EXCEPTION 'deposit amount must be positive';
  END IF;

  IF p_hold_minutes <= 0 OR p_hold_minutes > 60 THEN
    RAISE EXCEPTION 'hold minutes must be between 1 and 60';
  END IF;

  IF p_public_resource_code IS NOT NULL THEN
    SELECT sr.id INTO v_resource_id
    FROM seat_resources sr
    WHERE sr.public_resource_code = p_public_resource_code
      AND sr.active = true
      AND p_guest_count BETWEEN sr.capacity_min AND sr.capacity_max
    FOR UPDATE;
  ELSE
    SELECT sr.id INTO v_resource_id
    FROM seat_resources sr
    LEFT JOIN offering_resource_requirements orr
      ON orr.booking_offering_id = v_offering.id
    LEFT JOIN resource_group_members rgm
      ON rgm.resource_group_id = orr.resource_group_id
    WHERE sr.active = true
      AND p_guest_count BETWEEN sr.capacity_min AND sr.capacity_max
      AND (
        orr.id IS NULL
        OR orr.seat_resource_id = sr.id
        OR rgm.seat_resource_id = sr.id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM reservation_resources rr
        JOIN reservations r ON r.id = rr.reservation_id
        JOIN booking_slots locked_slot ON locked_slot.id = r.booking_slot_id
        WHERE rr.seat_resource_id = sr.id
          AND locked_slot.start_at < v_slot.end_at
          AND locked_slot.end_at > v_slot.start_at
          AND rr.lock_status IN ('held','payment_grace_locked','confirmed')
          AND r.status NOT IN ('cancelled','hold_expired','payment_window_expired','failed')
          AND (
            rr.lock_status = 'confirmed'
            OR COALESCE(rr.hold_expires_at, rr.admin_hold_expires_at, r.hold_expires_at, r.admin_hold_expires_at, 'infinity'::timestamptz) > now()
          )
      )
    ORDER BY sr.capacity_max, sr.name
    LIMIT 1
    FOR UPDATE OF sr;
  END IF;

  IF v_resource_id IS NULL THEN
    RAISE EXCEPTION 'no matching seat resource is available';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM reservation_resources rr
    JOIN reservations r ON r.id = rr.reservation_id
    JOIN booking_slots locked_slot ON locked_slot.id = r.booking_slot_id
    WHERE rr.seat_resource_id = v_resource_id
      AND locked_slot.start_at < v_slot.end_at
      AND locked_slot.end_at > v_slot.start_at
      AND rr.lock_status IN ('held','payment_grace_locked','confirmed')
      AND r.status NOT IN ('cancelled','hold_expired','payment_window_expired','failed')
      AND (
        rr.lock_status = 'confirmed'
        OR COALESCE(rr.hold_expires_at, rr.admin_hold_expires_at, r.hold_expires_at, r.admin_hold_expires_at, 'infinity'::timestamptz) > now()
      )
  ) THEN
    RAISE EXCEPTION 'seat resource is already locked';
  END IF;

  INSERT INTO customers(email_hash, phone_hash)
  VALUES (p_customer_email_hash, p_customer_phone_hash)
  RETURNING id INTO v_customer_id;

  v_hold_expires_at := now() + make_interval(mins => p_hold_minutes);
  v_status := CASE
    WHEN v_payment_type = 'deposit' THEN 'pending_deposit'::reservation_status
    ELSE 'pending_card_setup'::reservation_status
  END;
  v_public_code := upper('G' || encode(gen_random_bytes(5), 'hex'));
  v_status_token := encode(gen_random_bytes(24), 'hex');
  v_stripe_idempotency_key := 'stripe_reservation_hold:' || p_source_system || ':' || p_idempotency_key;

  INSERT INTO reservations(
    public_code,
    status_token_hash,
    customer_id,
    booking_slot_id,
    booking_offering_id,
    guest_count,
    status,
    hold_expires_at
  )
  VALUES (
    v_public_code,
    encode(digest(v_status_token, 'sha256'), 'hex'),
    v_customer_id,
    v_slot.id,
    v_offering.id,
    p_guest_count,
    v_status,
    v_hold_expires_at
  )
  RETURNING id INTO v_reservation_id;

  INSERT INTO reservation_resources(reservation_id, seat_resource_id, lock_status, hold_expires_at)
  VALUES (v_reservation_id, v_resource_id, 'held', v_hold_expires_at);

  INSERT INTO reservation_lock_requirements_snapshot(reservation_id, requirements_json)
  VALUES (
    v_reservation_id,
    jsonb_build_object(
      'publicResourceCode', p_public_resource_code,
      'seatResourceId', v_resource_id,
      'guestCount', p_guest_count,
      'createdBy', 'begin_public_reservation_hold_v7'
    )
  );

  INSERT INTO reservation_charge_terms(reservation_id, agreed_no_show_fee_yen, agreed_late_cancel_fee_yen)
  VALUES (v_reservation_id, v_slot.no_show_fee_yen, v_slot.late_cancel_fee_yen);

  INSERT INTO payments(reservation_id, type, status, amount_yen, environment, idempotency_key)
  VALUES (
    v_reservation_id,
    v_payment_type,
    CASE
      WHEN v_payment_type = 'deposit' THEN 'requires_confirmation'::payment_status
      ELSE 'requires_payment_method'::payment_status
    END,
    CASE WHEN v_payment_type = 'deposit' THEN p_deposit_amount_yen ELSE 0 END,
    'test',
    v_stripe_idempotency_key
  )
  RETURNING id INTO v_payment_id;

  INSERT INTO reservation_hold_requests(
    reservation_id,
    source_system,
    idempotency_key,
    request_hash,
    stripe_idempotency_key,
    status
  )
  VALUES (
    v_reservation_id,
    p_source_system,
    p_idempotency_key,
    p_request_hash,
    v_stripe_idempotency_key,
    'stripe_create_in_progress'
  );

  RETURN jsonb_build_object(
    'action', 'created',
    'reservationId', v_reservation_id,
    'paymentId', v_payment_id,
    'customerId', v_customer_id,
    'publicCode', v_public_code,
    'statusToken', v_status_token,
    'status', v_status,
    'stripeIdempotencyKey', v_stripe_idempotency_key,
    'paymentType', v_payment_type,
    'amountYen', CASE WHEN v_payment_type = 'deposit' THEN p_deposit_amount_yen ELSE 0 END,
    'holdExpiresAt', v_hold_expires_at
  );
END;
$$;

-- FUNCTION: begin_public_reservation_hold_v8(text, text, text, text, text, integer, text, text, text, text, integer, integer)
CREATE FUNCTION public.begin_public_reservation_hold_v8(p_source_system text, p_idempotency_key text, p_request_hash text, p_public_slot_id text, p_public_offering_id text, p_guest_count integer, p_customer_email_hash text, p_customer_phone_hash text, p_public_resource_code text DEFAULT NULL::text, p_payment_type text DEFAULT 'card_setup'::text, p_deposit_amount_yen integer DEFAULT 0, p_hold_minutes integer DEFAULT 15) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_existing public.reservation_hold_requests%ROWTYPE;
  v_existing_response jsonb;
  v_slot public.booking_slots%ROWTYPE;
  v_offering public.booking_offerings%ROWTYPE;
  v_resource public.seat_resources%ROWTYPE;
  v_customer_id uuid;
  v_reservation_id uuid;
  v_assignment_id uuid;
  v_payment_id uuid;
  v_audit_id uuid;
  v_hold_expires_at timestamptz;
  v_status public.reservation_status;
  v_payment_type public.payment_type;
  v_stripe_idempotency_key text;
  v_public_code text;
  v_status_token text;
  v_amount_yen int;
  v_revision_step jsonb;
BEGIN
  IF NOT public.vip_floor_v2_dual_write_enabled() THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = 'VIP Floor v8 public hold requires vip_floor_v2_dual_write=true';
  END IF;

  IF p_source_system NOT IN ('pure_web', 'pure_admin', 'pure_system') THEN
    RAISE EXCEPTION 'invalid source system';
  END IF;

  IF p_idempotency_key IS NULL OR length(trim(p_idempotency_key)) < 8 THEN
    RAISE EXCEPTION 'invalid idempotency key';
  END IF;

  IF NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL THEN
    RAISE EXCEPTION 'invalid request hash';
  END IF;

  -- Serialize equal idempotency keys before the row exists. This closes the
  -- unique-index race without introducing a partially initialized hold row.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(p_source_system || E'\x1f' || p_idempotency_key, 8088)
  );

  SELECT * INTO v_existing
  FROM public.reservation_hold_requests
  WHERE source_system = p_source_system
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object(
        'action', 'mismatch',
        'error', 'idempotency_key_reused_with_different_request'
      );
    END IF;

    SELECT response_snapshot_json INTO v_existing_response
    FROM public.reservation_hold_requests
    WHERE id = v_existing.id;

    SELECT
      reservation.id,
      reservation.customer_id,
      payment.id,
      payment.type,
      payment.amount_yen,
      reservation.hold_expires_at,
      reservation.public_code
    INTO
      v_reservation_id,
      v_customer_id,
      v_payment_id,
      v_payment_type,
      v_amount_yen,
      v_hold_expires_at,
      v_public_code
    FROM public.reservations AS reservation
    JOIN public.payments AS payment
      ON payment.reservation_id = reservation.id
    WHERE reservation.id = v_existing.reservation_id
    ORDER BY payment.created_at DESC
    LIMIT 1;

    v_status_token := v_existing_response ->> 'statusToken';

    RETURN jsonb_build_object(
      'action', 'reused',
      'reservationId', v_reservation_id,
      'holdRequestId', v_existing.id,
      'paymentId', v_payment_id,
      'customerId', v_customer_id,
      'publicCode', v_public_code,
      'statusToken', v_status_token,
      'status', v_existing.status,
      'stripeIdempotencyKey', v_existing.stripe_idempotency_key,
      'paymentType', v_payment_type,
      'amountYen', v_amount_yen,
      'holdExpiresAt', v_hold_expires_at,
      'providerObjectType', v_existing.provider_object_type,
      'providerObjectId', v_existing.provider_object_id,
      'response', v_existing_response
    );
  END IF;

  SELECT * INTO v_slot
  FROM public.booking_slots
  WHERE public_slot_id = p_public_slot_id
    AND active = true
    AND admin_only = false
    AND bookable_until_at > now()
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'booking slot is unavailable';
  END IF;

  SELECT * INTO v_offering
  FROM public.booking_offerings
  WHERE public_offering_id = p_public_offering_id
    AND active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'booking offering is unavailable';
  END IF;

  IF p_guest_count NOT BETWEEN v_offering.min_guests AND v_offering.max_guests THEN
    RAISE EXCEPTION 'guest count is outside offering limits';
  END IF;

  IF p_payment_type NOT IN ('card_setup', 'deposit') THEN
    RAISE EXCEPTION 'invalid payment type';
  END IF;
  v_payment_type := p_payment_type::public.payment_type;

  IF v_payment_type = 'deposit' AND p_deposit_amount_yen <= 0 THEN
    RAISE EXCEPTION 'deposit amount must be positive';
  END IF;

  IF p_hold_minutes <= 0 OR p_hold_minutes > 60 THEN
    RAISE EXCEPTION 'hold minutes must be between 1 and 60';
  END IF;

  IF p_public_resource_code IS NOT NULL THEN
    SELECT seat.* INTO v_resource
    FROM public.seat_resources AS seat
    WHERE seat.public_resource_code = p_public_resource_code
      AND seat.active = true
      AND seat.online_eligible = true
      AND seat.operational_locked = false
      AND p_guest_count BETWEEN seat.capacity_min AND seat.capacity_max
      AND public.seat_resource_satisfies_offering_requirement_v7(
        v_offering.id,
        seat.id
      )
    ORDER BY seat.id
    FOR UPDATE OF seat;
  ELSE
    SELECT seat.* INTO v_resource
    FROM public.seat_resources AS seat
    WHERE seat.active = true
      AND seat.online_eligible = true
      AND seat.operational_locked = false
      AND p_guest_count BETWEEN seat.capacity_min AND seat.capacity_max
      AND public.seat_resource_satisfies_offering_requirement_v7(
        v_offering.id,
        seat.id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.reservation_resources AS assignment
        WHERE assignment.seat_resource_id = seat.id
          AND assignment.assigned_start_at < v_slot.end_at
          AND assignment.assigned_end_at > v_slot.start_at
          AND public.active_reservation_assignment_v8(assignment.id, now())
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.reservation_blocks AS block
        WHERE block.event_day_id = v_slot.event_day_id
          AND block.status = 'active'
          AND block.scope IN ('online_only', 'all_operations')
          AND block.start_at < v_slot.end_at
          AND block.end_at > v_slot.start_at
          AND EXISTS (
            SELECT 1
            FROM public.reservation_block_targets AS target
            WHERE target.block_id = block.id
              AND (
                target.seat_resource_id = seat.id
                OR target.floor_section_id = seat.floor_section_id
                OR target.venue_wide
              )
          )
      )
    ORDER BY seat.capacity_max, seat.sort_order, seat.name, seat.id
    LIMIT 1
    FOR UPDATE OF seat SKIP LOCKED;
  END IF;

  IF v_resource.id IS NULL THEN
    RAISE EXCEPTION 'no matching seat resource is available';
  END IF;

  -- Follow the v8 lock order: sorted seat, assignments, blocks, then event day.
  -- The candidate seat is already locked; lock every overlapping relation and
  -- recheck predicates after any waiter has resumed.
  PERFORM assignment.id
  FROM public.reservation_resources AS assignment
  WHERE assignment.seat_resource_id = v_resource.id
    AND assignment.assigned_start_at < v_slot.end_at
    AND assignment.assigned_end_at > v_slot.start_at
  ORDER BY assignment.id
  FOR UPDATE OF assignment;

  PERFORM block.id
  FROM public.reservation_blocks AS block
  WHERE block.event_day_id = v_slot.event_day_id
    AND block.status = 'active'
    AND block.start_at < v_slot.end_at
    AND block.end_at > v_slot.start_at
    AND EXISTS (
      SELECT 1
      FROM public.reservation_block_targets AS target
      WHERE target.block_id = block.id
        AND (
          target.seat_resource_id = v_resource.id
          OR target.floor_section_id = v_resource.floor_section_id
          OR target.venue_wide
        )
    )
  ORDER BY block.id
  FOR UPDATE OF block;

  IF NOT v_resource.active
    OR NOT v_resource.online_eligible
    OR v_resource.operational_locked
    OR p_guest_count NOT BETWEEN v_resource.capacity_min AND v_resource.capacity_max
    OR NOT public.seat_resource_satisfies_offering_requirement_v7(
      v_offering.id,
      v_resource.id
    )
    OR EXISTS (
      SELECT 1
      FROM public.reservation_resources AS assignment
      WHERE assignment.seat_resource_id = v_resource.id
        AND assignment.assigned_start_at < v_slot.end_at
        AND assignment.assigned_end_at > v_slot.start_at
        AND public.active_reservation_assignment_v8(assignment.id, now())
    )
    OR EXISTS (
      SELECT 1
      FROM public.reservation_blocks AS block
      WHERE block.event_day_id = v_slot.event_day_id
        AND block.status = 'active'
        AND block.scope IN ('online_only', 'all_operations')
        AND block.start_at < v_slot.end_at
        AND block.end_at > v_slot.start_at
        AND EXISTS (
          SELECT 1
          FROM public.reservation_block_targets AS target
          WHERE target.block_id = block.id
            AND (
              target.seat_resource_id = v_resource.id
              OR target.floor_section_id = v_resource.floor_section_id
              OR target.venue_wide
            )
        )
    )
  THEN
    RAISE EXCEPTION 'seat resource is unavailable for the requested interval';
  END IF;

  PERFORM set_config('ghost.vip_floor_v8_writer', 'on', true);

  INSERT INTO public.customers(email_hash, phone_hash)
  VALUES (p_customer_email_hash, p_customer_phone_hash)
  RETURNING id INTO v_customer_id;

  v_hold_expires_at := now() + make_interval(mins => p_hold_minutes);
  v_status := CASE
    WHEN v_payment_type = 'deposit'
      THEN 'pending_deposit'::public.reservation_status
    ELSE 'pending_card_setup'::public.reservation_status
  END;
  v_public_code := upper('G' || encode(gen_random_bytes(5), 'hex'));
  v_status_token := encode(gen_random_bytes(24), 'hex');
  v_stripe_idempotency_key :=
    'stripe_reservation_hold:' || p_source_system || ':' || p_idempotency_key;

  INSERT INTO public.reservations(
    public_code,
    status_token_hash,
    customer_id,
    booking_slot_id,
    booking_offering_id,
    guest_count,
    status,
    hold_expires_at,
    intake_channel,
    event_day_id,
    scheduled_start_at,
    scheduled_end_at,
    expected_release_at,
    version
  )
  VALUES (
    v_public_code,
    encode(digest(v_status_token, 'sha256'), 'hex'),
    v_customer_id,
    v_slot.id,
    v_offering.id,
    p_guest_count,
    v_status,
    v_hold_expires_at,
    'online',
    v_slot.event_day_id,
    v_slot.start_at,
    v_slot.end_at,
    v_slot.end_at,
    1
  )
  RETURNING id INTO v_reservation_id;

  INSERT INTO public.reservation_resources(
    reservation_id,
    seat_resource_id,
    lock_status,
    hold_expires_at,
    assigned_start_at,
    assigned_end_at,
    assignment_role,
    version
  )
  VALUES (
    v_reservation_id,
    v_resource.id,
    'held',
    v_hold_expires_at,
    v_slot.start_at,
    v_slot.end_at,
    'primary',
    1
  )
  RETURNING id INTO v_assignment_id;

  INSERT INTO public.reservation_assignment_events(
    reservation_id,
    reservation_resource_id,
    seat_resource_id,
    event_type,
    interval_before,
    interval_after,
    reason,
    request_id
  )
  VALUES (
    v_reservation_id,
    v_assignment_id,
    v_resource.id,
    'assigned',
    NULL,
    jsonb_build_object('startAt', v_slot.start_at, 'endAt', v_slot.end_at),
    'public_v8_hold',
    p_request_hash
  );

  INSERT INTO public.reservation_lock_requirements_snapshot(
    reservation_id,
    requirements_json
  )
  VALUES (
    v_reservation_id,
    jsonb_build_object(
      'publicResourceCode', p_public_resource_code,
      'seatResourceId', v_resource.id,
      'guestCount', p_guest_count,
      'createdBy', 'begin_public_reservation_hold_v8'
    )
  );

  INSERT INTO public.reservation_charge_terms(
    reservation_id,
    agreed_no_show_fee_yen,
    agreed_late_cancel_fee_yen
  )
  VALUES (
    v_reservation_id,
    v_slot.no_show_fee_yen,
    v_slot.late_cancel_fee_yen
  );

  INSERT INTO public.payments(
    reservation_id,
    type,
    status,
    amount_yen,
    environment,
    idempotency_key
  )
  VALUES (
    v_reservation_id,
    v_payment_type,
    CASE
      WHEN v_payment_type = 'deposit'
        THEN 'requires_confirmation'::public.payment_status
      ELSE 'requires_payment_method'::public.payment_status
    END,
    CASE WHEN v_payment_type = 'deposit' THEN p_deposit_amount_yen ELSE 0 END,
    'test',
    v_stripe_idempotency_key
  )
  RETURNING id INTO v_payment_id;

  INSERT INTO public.reservation_hold_requests(
    reservation_id,
    source_system,
    idempotency_key,
    request_hash,
    stripe_idempotency_key,
    status,
    response_snapshot_json
  )
  VALUES (
    v_reservation_id,
    p_source_system,
    p_idempotency_key,
    p_request_hash,
    v_stripe_idempotency_key,
    'stripe_create_in_progress',
    jsonb_build_object(
      'reservationId', v_reservation_id,
      'paymentId', v_payment_id,
      'publicCode', v_public_code,
      'statusToken', v_status_token,
      'holdExpiresAt', v_hold_expires_at
    )
  );

  PERFORM event_day.id
  FROM public.event_days AS event_day
  WHERE event_day.id = v_slot.event_day_id
  FOR KEY SHARE OF event_day;

  INSERT INTO public.audit_logs(
    actor_type,
    action,
    target_table,
    target_id,
    request_id,
    after_json,
    event_day_id,
    reservation_id,
    entity_type,
    entity_id,
    operation,
    version_after,
    changed_fields,
    metadata_json,
    source_contract
  )
  VALUES (
    'customer',
    'vip_floor.public_hold.created',
    'reservations',
    v_reservation_id,
    p_request_hash,
    jsonb_build_object('version', 1),
    v_slot.event_day_id,
    v_reservation_id,
    'reservation',
    v_reservation_id,
    'public_hold_create',
    1,
    ARRAY[
      'status', 'hold_expires_at', 'guest_count', 'lock_status',
      'payment_status', 'scheduled_start_at', 'scheduled_end_at',
      'expected_release_at', 'version'
    ],
    jsonb_build_object(
      'sourceContract', 'v8',
      'redaction', 'field_names_and_versions_only'
    ),
    'v8'
  )
  RETURNING id INTO v_audit_id;

  v_revision_step := public.bump_vip_floor_day_revision_v8(
    v_slot.event_day_id,
    v_audit_id
  );
  IF v_revision_step ->> 'action' <> 'bumped' THEN
    RAISE EXCEPTION 'VIP Floor v8 public hold revision bump failed';
  END IF;

  RETURN jsonb_build_object(
    'action', 'created',
    'reservationId', v_reservation_id,
    'paymentId', v_payment_id,
    'customerId', v_customer_id,
    'publicCode', v_public_code,
    'statusToken', v_status_token,
    'status', v_status,
    'stripeIdempotencyKey', v_stripe_idempotency_key,
    'paymentType', v_payment_type,
    'amountYen', CASE WHEN v_payment_type = 'deposit' THEN p_deposit_amount_yen ELSE 0 END,
    'holdExpiresAt', v_hold_expires_at
  );
END;
$$;

-- FUNCTION: begin_ticket_passkey_challenge_v34(text, text, uuid, text, text, uuid, text, text, text)
CREATE FUNCTION public.begin_ticket_passkey_challenge_v34(p_kind text, p_environment text, p_authority_id uuid, p_token text, p_csrf text, p_challenge_id uuid, p_challenge text, p_rp_id text, p_origin text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.ticket_wallet_sessions%ROWTYPE; f public.ticket_wallet_preauth_flows%ROWTYPE; at timestamptz:=clock_timestamp();
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('ticket-passkey-transition-v34',0));
 IF p_kind='registration' THEN
  SELECT * INTO s FROM public.ticket_wallet_sessions WHERE id=p_authority_id AND environment=p_environment FOR UPDATE;
  IF NOT FOUND OR s.revoked_at IS NOT NULL OR s.expires_at<=at OR s.verified_at<at-interval '5 minutes'
   OR NOT public.ticket_auth_digest_equal_v29(s.token_verifier,p_token) OR NOT public.ticket_auth_digest_equal_v29(s.csrf_verifier,p_csrf) OR s.holder_id IS NULL THEN RETURN jsonb_build_object('action','reauthentication_required'); END IF;
  IF (SELECT count(*) FROM public.ticket_wallet_credentials WHERE holder_id=s.holder_id AND revoked_at IS NULL)>=10 THEN RETURN jsonb_build_object('action','credential_limit'); END IF;
 ELSE
  IF p_kind<>'authentication' THEN RETURN jsonb_build_object('action','rejected'); END IF;
  SELECT * INTO f FROM public.ticket_wallet_preauth_flows WHERE id=p_authority_id FOR UPDATE;
  IF NOT FOUND OR f.state<>'active' OR f.expires_at<=at
   OR NOT public.ticket_auth_digest_equal_v29(f.token_verifier,p_token) OR NOT public.ticket_auth_digest_equal_v29(f.csrf_verifier,p_csrf) THEN RETURN jsonb_build_object('action','rejected'); END IF;
 END IF;
 IF NOT public.consume_ticket_wallet_rate_limit_v29('passkey_begin_60s',p_authority_id::text,60,10) THEN RETURN jsonb_build_object('action','rate_limited'); END IF;
 UPDATE public.ticket_wallet_passkey_challenges SET consumed_at=at WHERE consumed_at IS NULL AND (session_id=p_authority_id OR preauth_flow_id=p_authority_id);
 INSERT INTO public.ticket_wallet_passkey_challenges(id,kind,challenge,holder_id,session_id,preauth_flow_id,rp_id,origin)
 VALUES(p_challenge_id,p_kind,p_challenge,s.holder_id,CASE WHEN p_kind='registration' THEN s.id END,CASE WHEN p_kind='authentication' THEN f.id END,p_rp_id,p_origin);
 RETURN jsonb_build_object('action','created','holderId',s.holder_id);
END; $$;

-- FUNCTION: begin_ticket_wallet_event_session_drain_v30(uuid, text, text, text, uuid, bigint, text)
CREATE FUNCTION public.begin_ticket_wallet_event_session_drain_v30(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_session_id uuid, p_expected_policy_version bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_claim jsonb;
  v_response jsonb;
  v_event_day_id uuid;
  v_session public.ticket_event_sessions%ROWTYPE;
  v_before jsonb;
  v_after jsonb;
  v_policy_audit_id uuid;
  v_audit_id uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admin_users AS admin_user
    WHERE admin_user.id = p_actor_admin_id
      AND admin_user.active
      AND admin_user.role = 'owner'
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'owner_role_required');
  END IF;
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR char_length(btrim(p_request_id)) > 200
    OR NULLIF(btrim(COALESCE(p_idempotency_key, '')), '') IS NULL
    OR char_length(btrim(p_idempotency_key)) > 200
    OR NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL
    OR char_length(btrim(p_request_hash)) > 200
    OR p_event_session_id IS NULL
    OR p_expected_policy_version IS NULL OR p_expected_policy_version < 1
    OR NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL
    OR char_length(btrim(p_reason)) > 240
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'begin_drain_input_invalid');
  END IF;

  -- Durable command identity is claimed before any policy/entity lock. Two
  -- distinct commands still serialize through Event Day -> Event Session CAS.
  v_claim := public.preclaim_admin_action_request_v8(
    p_actor_admin_id, 'begin_ticket_wallet_event_session_drain_v30',
    btrim(p_idempotency_key), btrim(p_request_hash));
  IF v_claim ->> 'action' = 'reused' THEN
    RETURN (v_claim -> 'response') || jsonb_build_object('reused', true);
  ELSIF v_claim ->> 'action' <> 'claimed' THEN
    RETURN CASE v_claim #>> '{error,code}'
      WHEN 'IDEMPOTENCY_MISMATCH' THEN jsonb_build_object(
        'action', 'conflict', 'reused', false, 'reason', 'idempotency_mismatch')
      WHEN 'IDEMPOTENCY_IN_PROGRESS' THEN jsonb_build_object(
        'action', 'conflict', 'reused', false, 'reason', 'idempotency_in_progress')
      ELSE jsonb_build_object(
        'action', 'rejected', 'reused', false, 'reason', 'begin_drain_input_invalid')
    END;
  END IF;

  SELECT event_session.event_day_id INTO v_event_day_id
  FROM public.ticket_event_sessions AS event_session
  WHERE event_session.id = p_event_session_id;
  IF v_event_day_id IS NULL THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'event_session_not_found',
      'serverNow', clock_timestamp());
    RETURN public.complete_ticket_wallet_begin_drain_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  -- Checkout claim/materialization/policy paths use the same FK-compatible
  -- parent order. NO KEY UPDATE lets order/action FK checks coexist while the
  -- policy CAS remains serialized.
  PERFORM 1 FROM public.event_days
  WHERE id = v_event_day_id FOR NO KEY UPDATE;
  SELECT * INTO v_session
  FROM public.ticket_event_sessions
  WHERE id = p_event_session_id FOR NO KEY UPDATE;

  IF v_session.policy_version <> p_expected_policy_version THEN
    v_response := jsonb_build_object(
      'action', 'version_conflict', 'reused', false,
      'reason', 'policy_version_mismatch',
      'eventSessionId', v_session.id,
      'policyVersion', v_session.policy_version,
      'serverNow', clock_timestamp());
    RETURN public.complete_ticket_wallet_begin_drain_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;
  IF v_session.sales_check_in_mode <> 'wallet_swipe' THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'check_in_mode_mismatch',
      'eventSessionId', v_session.id, 'policyVersion', v_session.policy_version,
      'serverNow', clock_timestamp());
    RETURN public.complete_ticket_wallet_begin_drain_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;
  IF NOT v_session.enabled THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'event_session_disabled',
      'eventSessionId', v_session.id, 'policyVersion', v_session.policy_version,
      'serverNow', clock_timestamp());
    RETURN public.complete_ticket_wallet_begin_drain_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;
  IF v_session.sales_state <> 'active' THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false,
      'reason', CASE v_session.sales_state
        WHEN 'draining' THEN 'sales_already_draining'
        ELSE 'sales_already_closed' END,
      'eventSessionId', v_session.id, 'policyVersion', v_session.policy_version,
      'serverNow', clock_timestamp());
    RETURN public.complete_ticket_wallet_begin_drain_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.ticket_event_session_policy_audits AS policy_audit
    WHERE policy_audit.ticket_event_session_id = v_session.id
      AND policy_audit.request_id = btrim(p_request_id)
  ) THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'request_id_reused',
      'eventSessionId', v_session.id, 'policyVersion', v_session.policy_version,
      'serverNow', clock_timestamp());
    RETURN public.complete_ticket_wallet_begin_drain_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  v_before := jsonb_build_object(
    'salesCheckInMode', v_session.sales_check_in_mode,
    'salesState', v_session.sales_state,
    'admissionState', v_session.admission_state,
    'enabled', v_session.enabled,
    'doorAt', v_session.door_at,
    'closeAt', v_session.close_at,
    'admissionOpensAt', v_session.admission_opens_at,
    'admissionClosesAt', v_session.admission_closes_at,
    'policyVersion', v_session.policy_version);

  UPDATE public.ticket_event_sessions
  SET sales_state = 'draining',
      policy_version = policy_version + 1,
      updated_at = clock_timestamp()
  WHERE id = v_session.id
    AND policy_version = p_expected_policy_version
    AND sales_state = 'active'
  RETURNING * INTO v_session;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket Wallet begin-drain policy CAS changed under held lock';
  END IF;

  v_after := jsonb_build_object(
    'salesCheckInMode', v_session.sales_check_in_mode,
    'salesState', v_session.sales_state,
    'admissionState', v_session.admission_state,
    'enabled', v_session.enabled,
    'doorAt', v_session.door_at,
    'closeAt', v_session.close_at,
    'admissionOpensAt', v_session.admission_opens_at,
    'admissionClosesAt', v_session.admission_closes_at,
    'policyVersion', v_session.policy_version);

  INSERT INTO public.ticket_event_session_policy_audits(
    ticket_event_session_id, actor_admin_id, request_id, reason,
    previous_policy_version, new_policy_version, before_json, after_json,
    authority_action
  ) VALUES (
    v_session.id, p_actor_admin_id, btrim(p_request_id), btrim(p_reason),
    p_expected_policy_version, v_session.policy_version, v_before, v_after,
    'begin_wallet_drain_v30'
  ) RETURNING id INTO v_policy_audit_id;

  INSERT INTO public.audit_logs(
    action, actor_type, actor_admin_id, target_table, target_id,
    entity_type, entity_id, operation, request_id, reason, metadata_json
  ) VALUES (
    'ticket_event_session.begin_wallet_drain', 'admin', p_actor_admin_id,
    'ticket_event_sessions', v_session.id,
    'ticket_event_session', v_session.id, 'update', btrim(p_request_id),
    btrim(p_reason),
    jsonb_build_object(
      'policyVersion', v_session.policy_version,
      'policyAuditId', v_policy_audit_id,
      'salesState', v_session.sales_state)
  ) RETURNING id INTO v_audit_id;

  v_response := jsonb_build_object(
    'action', 'draining', 'reused', false,
    'eventSessionId', v_session.id,
    'policyVersion', v_session.policy_version,
    'policyAuditId', v_policy_audit_id,
    'auditLogId', v_audit_id,
    'salesState', v_session.sales_state,
    'admissionState', v_session.admission_state,
    'enabled', v_session.enabled,
    'serverNow', clock_timestamp());
  RETURN public.complete_ticket_wallet_begin_drain_v30(
    p_actor_admin_id, p_idempotency_key, v_response);
END;
$$;

-- FUNCTION: bind_verified_ticket_checkout_payment_v28(uuid, uuid, uuid, text, text, text, text, text, text, text, text, timestamp with time zone)
CREATE FUNCTION public.bind_verified_ticket_checkout_payment_v28(p_ticket_order_id uuid, p_provider_checkout_action_id uuid, p_provider_event_session_id uuid, p_provider_check_in_mode text, p_environment text, p_stripe_account_id text, p_checkout_session_id text, p_client_reference_id text, p_payment_intent_id text, p_provider_flow text, p_provider_response_hash text, p_provider_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_action public.ticket_checkout_actions%ROWTYPE;
  v_order public.ticket_orders%ROWTYPE;
  v_provider_result jsonb;
  v_bound boolean := false;
BEGIN
  IF p_ticket_order_id IS NULL
    OR p_provider_checkout_action_id IS NULL
    OR p_provider_event_session_id IS NULL
    OR COALESCE(p_provider_check_in_mode, '') NOT IN ('legacy_qr', 'wallet_swipe')
    OR COALESCE(p_environment, '') NOT IN ('test', 'live')
    OR NULLIF(btrim(COALESCE(p_checkout_session_id, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_client_reference_id, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_payment_intent_id, '')), '') IS NULL
    OR COALESCE(p_provider_flow, '') <> 'ticket_calendar'
    OR COALESCE(p_provider_response_hash, '') !~ '^[0-9a-f]{64}$'
    OR p_provider_expires_at IS NULL
  THEN
    RETURN jsonb_build_object('action', 'not_ticket', 'reason', 'provider_binding_invalid');
  END IF;

  SELECT * INTO v_action
  FROM public.ticket_checkout_actions
  WHERE ticket_order_id = p_ticket_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'not_ticket', 'reason', 'checkout_action_not_found');
  END IF;

  SELECT * INTO v_order
  FROM public.ticket_orders
  WHERE id = v_action.ticket_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'not_ticket', 'reason', 'checkout_order_not_found');
  END IF;

  -- Every lookup fact must identify the already-created ticket authority.
  -- Any mismatch is foreign/unattributed and changes no durable row.
  IF v_order.id <> p_ticket_order_id
    OR v_action.id <> p_provider_checkout_action_id
    OR v_action.event_session_id <> p_provider_event_session_id
    OR v_order.event_session_id <> p_provider_event_session_id
    OR v_action.check_in_mode <> p_provider_check_in_mode
    OR v_order.check_in_mode <> p_provider_check_in_mode
    OR btrim(p_client_reference_id) <> v_order.id::text
    OR v_order.environment <> p_environment
    OR v_action.environment <> p_environment
    OR v_order.stripe_account_key <> COALESCE(p_stripe_account_id, 'platform')
    OR v_action.stripe_account_key <> COALESCE(p_stripe_account_id, 'platform')
    OR v_action.event_session_id IS DISTINCT FROM v_order.event_session_id
    OR v_action.check_in_mode <> v_order.check_in_mode
    OR v_action.state IN ('failed', 'expired')
    OR (v_action.checkout_session_id IS NOT NULL
      AND v_action.checkout_session_id <> btrim(p_checkout_session_id))
    OR (v_order.checkout_session_id IS NOT NULL
      AND v_order.checkout_session_id <> btrim(p_checkout_session_id))
    OR (v_order.payment_intent_id IS NOT NULL
      AND v_order.payment_intent_id <> btrim(p_payment_intent_id))
  THEN
    RETURN jsonb_build_object('action', 'not_ticket', 'reason', 'checkout_binding_mismatch');
  END IF;

  IF v_action.checkout_session_id IS NULL THEN
    IF v_action.state <> 'claimed' OR v_order.checkout_session_id IS NOT NULL THEN
      RETURN jsonb_build_object('action', 'not_ticket', 'reason', 'checkout_binding_state_invalid');
    END IF;
    v_provider_result := public.record_ticket_checkout_provider_result_v28(
      v_action.id, v_action.request_hash, btrim(p_checkout_session_id),
      p_provider_response_hash, p_provider_expires_at);
    IF v_provider_result ->> 'action' NOT IN ('provider_created', 'reused') THEN
      RETURN v_provider_result;
    END IF;
    v_bound := true;
  ELSIF v_action.provider_response_hash IS DISTINCT FROM p_provider_response_hash
    OR v_action.provider_expires_at IS DISTINCT FROM p_provider_expires_at
  THEN
    RETURN jsonb_build_object('action', 'not_ticket', 'reason', 'provider_evidence_mismatch');
  END IF;

  UPDATE public.ticket_orders
  SET payment_intent_id = btrim(p_payment_intent_id)
  WHERE id = v_order.id
    AND payment_intent_id IS NULL;
  IF FOUND THEN v_bound := true; END IF;

  RETURN jsonb_build_object(
    'action', CASE WHEN v_bound THEN 'bound' ELSE 'reused' END,
    'checkoutActionId', v_action.id,
    'orderId', v_order.id,
    'publicCode', v_order.public_code,
    'checkoutSessionId', btrim(p_checkout_session_id),
    'paymentIntentId', btrim(p_payment_intent_id)
  );
END;
$_$;

-- FUNCTION: bootstrap_ticket_wallet_preauth_v29(timestamp with time zone, uuid, text, uuid, text, text, timestamp with time zone, text, text, integer, integer, integer, integer, integer)
CREATE FUNCTION public.bootstrap_ticket_wallet_preauth_v29(p_now timestamp with time zone, p_presented_flow_id uuid, p_presented_token_verifier text, p_candidate_flow_id uuid, p_candidate_token_verifier text, p_candidate_csrf_verifier text, p_candidate_expires_at timestamp with time zone, p_abuse_ip_hash text, p_abuse_user_agent_hash text, p_minimum_remaining_seconds integer, p_ip_window_seconds integer, p_ip_maximum integer, p_global_window_seconds integer, p_global_maximum integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_presented public.ticket_wallet_preauth_flows%ROWTYPE;
  v_action text := 'created';
  v_key_id text;
BEGIN
  IF p_now IS NULL OR abs(extract(epoch FROM (p_now - v_now))) > 300
    OR p_candidate_flow_id IS NULL
    OR p_candidate_token_verifier IS NULL OR char_length(p_candidate_token_verifier) NOT BETWEEN 16 AND 256
    OR p_candidate_csrf_verifier IS NULL OR char_length(p_candidate_csrf_verifier) NOT BETWEEN 16 AND 256
    OR p_candidate_expires_at <= v_now + interval '12 minutes'
    OR p_candidate_expires_at > v_now + interval '15 minutes 5 seconds'
    OR p_abuse_ip_hash IS NULL OR char_length(p_abuse_ip_hash) NOT BETWEEN 16 AND 256
    OR p_abuse_user_agent_hash IS NULL OR char_length(p_abuse_user_agent_hash) NOT BETWEEN 16 AND 256
    OR ROW(
      p_minimum_remaining_seconds, p_ip_window_seconds, p_ip_maximum,
      p_global_window_seconds, p_global_maximum
    ) IS DISTINCT FROM ROW(720, 600, 100, 600, 500)
  THEN
    RETURN jsonb_build_object('action', 'rejected');
  END IF;

  v_key_id := split_part(p_candidate_token_verifier, ':', 2);
  IF v_key_id !~ '^[A-Za-z0-9._-]{1,64}$' THEN
    RETURN jsonb_build_object('action', 'rejected');
  END IF;

  IF p_presented_flow_id IS NOT NULL AND p_presented_token_verifier IS NOT NULL THEN
    SELECT * INTO v_presented
    FROM public.ticket_wallet_preauth_flows
    WHERE id = p_presented_flow_id
    FOR UPDATE;

    IF FOUND AND v_presented.state = 'active'
      AND v_presented.expires_at > v_now
      AND public.ticket_auth_digest_equal_v29(
        v_presented.token_verifier, p_presented_token_verifier)
    THEN
      IF v_presented.expires_at >= v_now + make_interval(secs => p_minimum_remaining_seconds) THEN
        RETURN jsonb_build_object(
          'action', 'reused', 'flowId', v_presented.id,
          'expiresAt', v_presented.expires_at
        );
      END IF;

      UPDATE public.ticket_wallet_preauth_flows
      SET state = 'superseded', token_verifier = NULL, csrf_verifier = NULL,
          terminal_at = v_now, updated_at = v_now
      WHERE id = v_presented.id;
      UPDATE public.ticket_wallet_otp_challenges
      SET state = 'superseded', code_ciphertext = NULL,
          terminal_at = v_now, updated_at = v_now
      WHERE preauth_flow_id = v_presented.id
        AND state IN ('pending', 'sending', 'sent');
      v_action := 'rotated';
    END IF;
  END IF;

  IF NOT public.consume_ticket_wallet_rate_limit_v29(
      'preauth_ip', p_abuse_ip_hash, p_ip_window_seconds, p_ip_maximum)
    OR NOT public.consume_ticket_wallet_rate_limit_v29(
      'preauth_global', 'global', p_global_window_seconds, p_global_maximum)
  THEN
    RETURN jsonb_build_object('action', 'rate_limited');
  END IF;

  INSERT INTO public.ticket_wallet_preauth_flows(
    id, token_verifier, csrf_verifier, auth_key_id,
    abuse_ip_hash, abuse_user_agent_hash, state,
    created_at, expires_at, updated_at
  ) VALUES (
    p_candidate_flow_id, p_candidate_token_verifier, p_candidate_csrf_verifier,
    v_key_id, p_abuse_ip_hash, p_abuse_user_agent_hash, 'active',
    v_now, p_candidate_expires_at, v_now
  );

  RETURN jsonb_build_object(
    'action', v_action, 'flowId', p_candidate_flow_id,
    'expiresAt', p_candidate_expires_at
  );
END;
$_$;

-- FUNCTION: bump_ticket_order_authority_version_v30()
CREATE FUNCTION public.bump_ticket_order_authority_version_v30() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.admission_version < OLD.admission_version THEN
    RAISE EXCEPTION 'ticket order admission_version cannot decrease';
  END IF;

  IF ROW(
      NEW.status, NEW.environment, NEW.stripe_account_id,
      NEW.checkout_session_id, NEW.payment_intent_id,
      NEW.purchaser_email_hash, NEW.paid_at, NEW.fulfilled_at,
      NEW.cancelled_at, NEW.event_id, NEW.event_date,
      NEW.event_session_id, NEW.check_in_mode,
      NEW.payment_hold_reason, NEW.payment_hold_at,
      NEW.amount_yen, NEW.total_quantity
    ) IS DISTINCT FROM ROW(
      OLD.status, OLD.environment, OLD.stripe_account_id,
      OLD.checkout_session_id, OLD.payment_intent_id,
      OLD.purchaser_email_hash, OLD.paid_at, OLD.fulfilled_at,
      OLD.cancelled_at, OLD.event_id, OLD.event_date,
      OLD.event_session_id, OLD.check_in_mode,
      OLD.payment_hold_reason, OLD.payment_hold_at,
      OLD.amount_yen, OLD.total_quantity
    )
    AND NEW.admission_version = OLD.admission_version
  THEN
    NEW.admission_version := OLD.admission_version + 1;
  END IF;

  RETURN NEW;
END;
$$;

-- FUNCTION: bump_ticket_order_from_admission_delete_v30()
CREATE FUNCTION public.bump_ticket_order_from_admission_delete_v30() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.ticket_orders AS ticket_order
  SET admission_version = ticket_order.admission_version + 1
  FROM (
    SELECT DISTINCT deleted.ticket_order_id
    FROM deleted_admissions_v30 AS deleted
  ) AS changed
  WHERE ticket_order.id = changed.ticket_order_id;
  RETURN NULL;
END;
$$;

-- FUNCTION: bump_ticket_order_from_admission_insert_v30()
CREATE FUNCTION public.bump_ticket_order_from_admission_insert_v30() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.ticket_orders AS ticket_order
  SET admission_version = ticket_order.admission_version + 1
  FROM (
    SELECT DISTINCT inserted.ticket_order_id
    FROM inserted_admissions_v30 AS inserted
  ) AS changed
  WHERE ticket_order.id = changed.ticket_order_id;
  RETURN NULL;
END;
$$;

-- FUNCTION: bump_ticket_order_from_admission_update_v30()
CREATE FUNCTION public.bump_ticket_order_from_admission_update_v30() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.ticket_orders AS ticket_order
  SET admission_version = ticket_order.admission_version + 1
  FROM (
    SELECT DISTINCT affected.ticket_order_id
    FROM updated_admissions_v30 AS updated
    JOIN previous_admissions_v30 AS previous ON previous.id = updated.id
    CROSS JOIN LATERAL (
      VALUES (updated.ticket_order_id), (previous.ticket_order_id)
    ) AS affected(ticket_order_id)
    WHERE ROW(
      updated.ticket_order_id, updated.serial, updated.ticket_type_id,
      updated.ticket_type_label, updated.admission_code, updated.status,
      updated.admitted_at, updated.admitted_by_admin_id,
      updated.voided_at, updated.void_reason
    ) IS DISTINCT FROM ROW(
      previous.ticket_order_id, previous.serial, previous.ticket_type_id,
      previous.ticket_type_label, previous.admission_code, previous.status,
      previous.admitted_at, previous.admitted_by_admin_id,
      previous.voided_at, previous.void_reason
    )
  ) AS changed
  WHERE ticket_order.id = changed.ticket_order_id;
  RETURN NULL;
END;
$$;

-- FUNCTION: bump_ticket_order_from_refund_delete_v30()
CREATE FUNCTION public.bump_ticket_order_from_refund_delete_v30() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.ticket_orders AS ticket_order
  SET admission_version = ticket_order.admission_version + 1
  FROM (
    SELECT DISTINCT deleted.ticket_order_id
    FROM deleted_refunds_v30 AS deleted
  ) AS changed
  WHERE ticket_order.id = changed.ticket_order_id;
  RETURN NULL;
END;
$$;

-- FUNCTION: bump_ticket_order_from_refund_insert_v30()
CREATE FUNCTION public.bump_ticket_order_from_refund_insert_v30() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.ticket_orders AS ticket_order
  SET admission_version = ticket_order.admission_version + 1
  FROM (
    SELECT DISTINCT inserted.ticket_order_id
    FROM inserted_refunds_v30 AS inserted
  ) AS changed
  WHERE ticket_order.id = changed.ticket_order_id;
  RETURN NULL;
END;
$$;

-- FUNCTION: bump_ticket_order_from_refund_update_v30()
CREATE FUNCTION public.bump_ticket_order_from_refund_update_v30() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.ticket_orders AS ticket_order
  SET admission_version = ticket_order.admission_version + 1
  FROM (
    SELECT DISTINCT affected.ticket_order_id
    FROM updated_refunds_v30 AS updated
    JOIN previous_refunds_v30 AS previous ON previous.id = updated.id
    CROSS JOIN LATERAL (
      VALUES (updated.ticket_order_id), (previous.ticket_order_id)
    ) AS affected(ticket_order_id)
    WHERE (to_jsonb(updated) - 'updated_at')
      IS DISTINCT FROM (to_jsonb(previous) - 'updated_at')
  ) AS changed
  WHERE ticket_order.id = changed.ticket_order_id;
  RETURN NULL;
END;
$$;

-- FUNCTION: bump_ticket_wallet_entity_version_v29()
CREATE FUNCTION public.bump_ticket_wallet_entity_version_v29() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.entity_version < OLD.entity_version
    OR NEW.entity_version > OLD.entity_version + 1
  THEN
    RAISE EXCEPTION 'Ticket Wallet entity version must advance by one';
  END IF;
  IF (to_jsonb(NEW) - 'updated_at' - 'entity_version')
      IS DISTINCT FROM (to_jsonb(OLD) - 'updated_at' - 'entity_version')
  THEN
    IF NEW.entity_version = OLD.entity_version THEN
      NEW.entity_version := OLD.entity_version + 1;
    END IF;
  ELSIF NEW.entity_version <> OLD.entity_version THEN
    RAISE EXCEPTION 'Ticket Wallet entity version cannot change without state';
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: bump_vip_floor_day_revision_v8(uuid, uuid)
CREATE FUNCTION public.bump_vip_floor_day_revision_v8(p_event_day_id uuid, p_last_audit_log_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_revision bigint;
  v_last_audit_log_id uuid;
BEGIN
  IF p_event_day_id IS NULL THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object('field', 'eventDayId')
      )
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.event_days
    WHERE id = p_event_day_id
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'NOT_FOUND',
        'details', jsonb_build_object(
          'entityType', 'event_day'
        )
      )
    );
  END IF;

  IF p_last_audit_log_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.audit_logs
    WHERE id = p_last_audit_log_id
      AND event_day_id = p_event_day_id
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object(
          'field', 'lastAuditLogId',
          'reason', 'audit_event_day_mismatch'
        )
      )
    );
  END IF;

  INSERT INTO public.vip_floor_day_revisions AS current_revision(
    event_day_id,
    revision,
    last_audit_log_id,
    updated_at
  )
  VALUES (
    p_event_day_id,
    1,
    p_last_audit_log_id,
    now()
  )
  ON CONFLICT (event_day_id)
  DO UPDATE
  SET revision = current_revision.revision + 1,
      last_audit_log_id = COALESCE(
        EXCLUDED.last_audit_log_id,
        current_revision.last_audit_log_id
      ),
      updated_at = now()
  RETURNING revision, last_audit_log_id
  INTO v_revision, v_last_audit_log_id;

  RETURN jsonb_build_object(
    'action', 'bumped',
    'eventDayId', p_event_day_id,
    'revision', v_revision,
    'lastAuditLogId', v_last_audit_log_id
  );
END;
$$;

-- FUNCTION: bump_vip_floor_legacy_revision_deferred()
CREATE FUNCTION public.bump_vip_floor_legacy_revision_deferred() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old jsonb := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END;
  v_new jsonb := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END;
  v_changed_fields text[];
  v_event_day_ids uuid[];
  v_event_day_id uuid;
  v_raw_processed text := current_setting('ghost.vip_floor_revision_days_processed', true);
  v_processed uuid[] := ARRAY[]::uuid[];
  v_token text;
BEGIN
  IF NOT public.vip_floor_v2_dual_write_enabled()
    OR current_setting('ghost.vip_floor_v8_writer', true) = 'on'
  THEN
    RETURN NULL;
  END IF;

  v_changed_fields := public.vip_floor_compat_changed_fields(TG_TABLE_NAME, v_old, v_new);
  IF cardinality(v_changed_fields) = 0 THEN
    RETURN NULL;
  END IF;

  IF length(COALESCE(v_raw_processed, '')) > 19000 THEN
    RAISE EXCEPTION USING
      ERRCODE = '54000',
      MESSAGE = 'VIP Floor processed event-day setting exceeds its bound';
  END IF;

  IF COALESCE(v_raw_processed, '') <> '' THEN
    FOREACH v_token IN ARRAY string_to_array(v_raw_processed, ',')
    LOOP
      BEGIN
        v_processed := array_append(v_processed, v_token::uuid);
      EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION USING
          ERRCODE = '22023',
          MESSAGE = 'VIP Floor processed event-day setting is malformed';
      END;
    END LOOP;
  END IF;

  IF cardinality(v_processed) > 512 THEN
    RAISE EXCEPTION USING
      ERRCODE = '54000',
      MESSAGE = 'VIP Floor processed event-day set exceeds 512 UUIDs';
  END IF;

  v_event_day_ids := public.vip_floor_compat_event_day_ids(TG_TABLE_NAME, v_old, v_new);
  FOREACH v_event_day_id IN ARRAY v_event_day_ids
  LOOP
    IF NOT v_event_day_id = ANY(v_processed) THEN
      INSERT INTO public.vip_floor_day_revisions AS current_revision(
        event_day_id,
        revision,
        last_audit_log_id,
        updated_at
      )
      VALUES (v_event_day_id, 1, NULL, now())
      ON CONFLICT (event_day_id)
      DO UPDATE
      SET revision = current_revision.revision + 1,
          updated_at = now();

      v_processed := array_append(v_processed, v_event_day_id);
      PERFORM set_config(
        'ghost.vip_floor_revision_days_processed',
        array_to_string(v_processed, ','),
        true
      );
    END IF;
  END LOOP;

  RETURN NULL;
END;
$$;

-- FUNCTION: calculate_public_availability_v7(date, integer)
CREATE FUNCTION public.calculate_public_availability_v7(p_business_date date DEFAULT NULL::date, p_guest_count integer DEFAULT NULL::integer) RETURNS TABLE(public_slot_id text, start_at timestamp with time zone, end_at timestamp with time zone, public_offering_id text, offering_name text, min_guests integer, max_guests integer, min_spend_yen integer, available_resource_count integer, is_available boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH active_locks AS (
    SELECT rr.seat_resource_id, locked_slot.start_at, locked_slot.end_at
    FROM reservation_resources rr
    JOIN reservations r ON r.id = rr.reservation_id
    JOIN booking_slots locked_slot ON locked_slot.id = r.booking_slot_id
    WHERE rr.lock_status IN ('held','payment_grace_locked','confirmed')
      AND r.status NOT IN ('cancelled','hold_expired','payment_window_expired','failed')
      AND (
        rr.lock_status = 'confirmed'
        OR COALESCE(
          rr.hold_expires_at,
          rr.admin_hold_expires_at,
          r.hold_expires_at,
          r.admin_hold_expires_at,
          'infinity'::timestamptz
        ) > now()
      )
  ),
  requirements AS (
    SELECT
      bo.id AS booking_offering_id,
      COALESCE(orr.id, bo.id) AS requirement_id,
      COALESCE(orr.quantity, 1) AS required_quantity,
      orr.resource_group_id,
      orr.seat_resource_id,
      orr.id IS NULL AS uses_any_resource
    FROM booking_offerings bo
    LEFT JOIN offering_resource_requirements orr
      ON orr.booking_offering_id = bo.id
    WHERE bo.active = true
  ),
  slot_requirement_availability AS (
    SELECT
      bs.public_slot_id,
      bs.start_at,
      bs.end_at,
      bo.public_offering_id,
      bo.name AS offering_name,
      bo.min_guests,
      bo.max_guests,
      bo.min_spend_yen,
      req.requirement_id,
      req.required_quantity,
      COUNT(DISTINCT sr.id) FILTER (
        WHERE sr.id IS NOT NULL
          AND al.seat_resource_id IS NULL
      )::int AS available_units
    FROM booking_slots bs
    JOIN event_days ed ON ed.id = bs.event_day_id
    CROSS JOIN booking_offerings bo
    JOIN requirements req ON req.booking_offering_id = bo.id
    LEFT JOIN seat_resources sr
      ON sr.active = true
     AND (p_guest_count IS NULL OR p_guest_count BETWEEN sr.capacity_min AND sr.capacity_max)
     AND (
       req.uses_any_resource = true
       OR sr.id = req.seat_resource_id
       OR EXISTS (
         SELECT 1
         FROM resource_group_members rgm
         WHERE rgm.resource_group_id = req.resource_group_id
           AND rgm.seat_resource_id = sr.id
       )
     )
    LEFT JOIN active_locks al
      ON al.seat_resource_id = sr.id
     AND al.start_at < bs.end_at
     AND al.end_at > bs.start_at
    WHERE bs.active = true
      AND bs.admin_only = false
      AND bo.active = true
      AND bs.bookable_until_at > now()
      AND (p_business_date IS NULL OR ed.business_date = p_business_date)
      AND (p_guest_count IS NULL OR p_guest_count BETWEEN bo.min_guests AND bo.max_guests)
    GROUP BY
      bs.public_slot_id,
      bs.start_at,
      bs.end_at,
      bo.public_offering_id,
      bo.name,
      bo.min_guests,
      bo.max_guests,
      bo.min_spend_yen,
      req.requirement_id,
      req.required_quantity
  )
  SELECT
    sra.public_slot_id,
    sra.start_at,
    sra.end_at,
    sra.public_offering_id,
    sra.offering_name,
    sra.min_guests,
    sra.max_guests,
    sra.min_spend_yen,
    MIN(sra.available_units)::int AS available_resource_count,
    BOOL_AND(sra.available_units >= sra.required_quantity) AS is_available
  FROM slot_requirement_availability sra
  GROUP BY
    sra.public_slot_id,
    sra.start_at,
    sra.end_at,
    sra.public_offering_id,
    sra.offering_name,
    sra.min_guests,
    sra.max_guests,
    sra.min_spend_yen
  HAVING BOOL_AND(sra.available_units >= sra.required_quantity)
  ORDER BY sra.start_at, sra.min_spend_yen DESC, sra.offering_name;
$$;

-- FUNCTION: calculate_public_availability_v8(date, integer)
CREATE FUNCTION public.calculate_public_availability_v8(p_business_date date DEFAULT NULL::date, p_guest_count integer DEFAULT NULL::integer) RETURNS TABLE(public_slot_id text, start_at timestamp with time zone, end_at timestamp with time zone, public_offering_id text, offering_name text, min_guests integer, max_guests integer, min_spend_yen integer, available_resource_count integer, is_available boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH requirements AS (
    SELECT
      bo.id AS booking_offering_id,
      COALESCE(orr.id, bo.id) AS requirement_id,
      COALESCE(orr.quantity, 1) AS required_quantity,
      orr.resource_group_id,
      orr.seat_resource_id,
      orr.id IS NULL AS uses_any_resource
    FROM public.booking_offerings AS bo
    LEFT JOIN public.offering_resource_requirements AS orr
      ON orr.booking_offering_id = bo.id
    WHERE bo.active = true
  ),
  slot_requirement_availability AS (
    SELECT
      bs.public_slot_id,
      bs.start_at,
      bs.end_at,
      bo.public_offering_id,
      bo.name AS offering_name,
      bo.min_guests,
      bo.max_guests,
      bo.min_spend_yen,
      req.requirement_id,
      req.required_quantity,
      count(DISTINCT sr.id) FILTER (
        WHERE sr.id IS NOT NULL
      )::int AS available_units
    FROM public.booking_slots AS bs
    JOIN public.event_days AS ed
      ON ed.id = bs.event_day_id
    CROSS JOIN public.booking_offerings AS bo
    JOIN requirements AS req
      ON req.booking_offering_id = bo.id
    LEFT JOIN public.seat_resources AS sr
      ON sr.active = true
     AND sr.online_eligible = true
     AND sr.operational_locked = false
     AND (
       p_guest_count IS NULL
       OR p_guest_count BETWEEN sr.capacity_min AND sr.capacity_max
     )
     AND (
       req.uses_any_resource
       OR sr.id = req.seat_resource_id
       OR EXISTS (
         SELECT 1
         FROM public.resource_group_members AS rgm
         WHERE rgm.resource_group_id = req.resource_group_id
           AND rgm.seat_resource_id = sr.id
       )
     )
     AND NOT EXISTS (
       SELECT 1
       FROM public.reservation_resources AS rr
       JOIN public.reservations AS r
         ON r.id = rr.reservation_id
       WHERE rr.seat_resource_id = sr.id
         AND r.status NOT IN (
           'cancelled',
           'hold_expired',
           'payment_window_expired',
           'failed'
         )
         AND r.service_status IS DISTINCT FROM 'completed'
         AND r.service_status IS DISTINCT FROM 'no_show'
         AND rr.assigned_start_at < bs.end_at
         AND rr.assigned_end_at > bs.start_at
         AND public.active_reservation_assignment_v8(rr.id, now())
     )
     AND NOT EXISTS (
       SELECT 1
       FROM public.reservation_blocks AS rb
       WHERE rb.event_day_id = bs.event_day_id
         AND rb.status = 'active'
         AND rb.scope IN ('online_only', 'all_operations')
         AND rb.start_at < bs.end_at
         AND rb.end_at > bs.start_at
         AND EXISTS (
           SELECT 1
           FROM public.reservation_block_targets AS rbt
           WHERE rbt.block_id = rb.id
             AND (
               rbt.seat_resource_id = sr.id
               OR rbt.floor_section_id = sr.floor_section_id
               OR rbt.venue_wide
             )
         )
     )
    WHERE bs.active = true
      AND bs.admin_only = false
      AND bs.bookable_until_at > now()
      AND bo.active = true
      AND (p_business_date IS NULL OR ed.business_date = p_business_date)
      AND (
        p_guest_count IS NULL
        OR p_guest_count BETWEEN bo.min_guests AND bo.max_guests
      )
    GROUP BY
      bs.public_slot_id,
      bs.start_at,
      bs.end_at,
      bo.public_offering_id,
      bo.name,
      bo.min_guests,
      bo.max_guests,
      bo.min_spend_yen,
      req.requirement_id,
      req.required_quantity
  )
  SELECT
    sra.public_slot_id,
    sra.start_at,
    sra.end_at,
    sra.public_offering_id,
    sra.offering_name,
    sra.min_guests,
    sra.max_guests,
    sra.min_spend_yen,
    min(sra.available_units)::int AS available_resource_count,
    bool_and(sra.available_units >= sra.required_quantity) AS is_available
  FROM slot_requirement_availability AS sra
  GROUP BY
    sra.public_slot_id,
    sra.start_at,
    sra.end_at,
    sra.public_offering_id,
    sra.offering_name,
    sra.min_guests,
    sra.max_guests,
    sra.min_spend_yen
  HAVING bool_and(sra.available_units >= sra.required_quantity)
  ORDER BY sra.start_at, sra.min_spend_yen DESC, sra.offering_name;
$$;

-- FUNCTION: calculate_public_seat_availability_v7(date, integer)
CREATE FUNCTION public.calculate_public_seat_availability_v7(p_business_date date DEFAULT NULL::date, p_guest_count integer DEFAULT NULL::integer) RETURNS TABLE(public_slot_id text, start_at timestamp with time zone, end_at timestamp with time zone, public_resource_code text, seat_name text, capacity_min integer, capacity_max integer, is_available boolean, business_date date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH active_locks AS (
    SELECT rr.seat_resource_id, locked_slot.start_at, locked_slot.end_at
    FROM reservation_resources rr
    JOIN reservations r ON r.id = rr.reservation_id
    JOIN booking_slots locked_slot ON locked_slot.id = r.booking_slot_id
    WHERE rr.lock_status IN ('held','payment_grace_locked','confirmed')
      AND r.status NOT IN ('cancelled','hold_expired','payment_window_expired','failed')
      AND (
        rr.lock_status = 'confirmed'
        OR COALESCE(
          rr.hold_expires_at,
          rr.admin_hold_expires_at,
          r.hold_expires_at,
          r.admin_hold_expires_at,
          'infinity'::timestamptz
        ) > now()
      )
  )
  SELECT
    bs.public_slot_id,
    bs.start_at,
    bs.end_at,
    sr.public_resource_code,
    sr.name AS seat_name,
    sr.capacity_min,
    sr.capacity_max,
    (
      al.seat_resource_id IS NULL
      AND (p_guest_count IS NULL OR p_guest_count BETWEEN sr.capacity_min AND sr.capacity_max)
    ) AS is_available,
    ed.business_date
  FROM booking_slots bs
  JOIN event_days ed ON ed.id = bs.event_day_id
  CROSS JOIN seat_resources sr
  LEFT JOIN active_locks al
    ON al.seat_resource_id = sr.id
   AND al.start_at < bs.end_at
   AND al.end_at > bs.start_at
  WHERE bs.active = true
    AND bs.admin_only = false
    AND bs.bookable_until_at > now()
    AND sr.active = true
    AND sr.public_resource_code IS NOT NULL
    AND (p_business_date IS NULL OR ed.business_date = p_business_date)
  ORDER BY bs.start_at, sr.name;
$$;

-- FUNCTION: calculate_public_seat_availability_v8(date, integer)
CREATE FUNCTION public.calculate_public_seat_availability_v8(p_business_date date DEFAULT NULL::date, p_guest_count integer DEFAULT NULL::integer) RETURNS TABLE(public_slot_id text, start_at timestamp with time zone, end_at timestamp with time zone, public_resource_code text, seat_name text, capacity_min integer, capacity_max integer, is_available boolean, business_date date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    bs.public_slot_id,
    bs.start_at,
    bs.end_at,
    sr.public_resource_code,
    sr.name AS seat_name,
    sr.capacity_min,
    sr.capacity_max,
    (
      sr.online_eligible = true
      AND sr.operational_locked = false
      AND (
        p_guest_count IS NULL
        OR p_guest_count BETWEEN sr.capacity_min AND sr.capacity_max
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.reservation_resources AS rr
        JOIN public.reservations AS r
          ON r.id = rr.reservation_id
        WHERE rr.seat_resource_id = sr.id
          AND r.status NOT IN (
            'cancelled',
            'hold_expired',
            'payment_window_expired',
            'failed'
          )
          AND r.service_status IS DISTINCT FROM 'completed'
          AND r.service_status IS DISTINCT FROM 'no_show'
          AND rr.assigned_start_at < bs.end_at
          AND rr.assigned_end_at > bs.start_at
          AND public.active_reservation_assignment_v8(rr.id, now())
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.reservation_blocks AS rb
        WHERE rb.event_day_id = bs.event_day_id
          AND rb.status = 'active'
          AND rb.scope IN ('online_only', 'all_operations')
          AND rb.start_at < bs.end_at
          AND rb.end_at > bs.start_at
          AND EXISTS (
            SELECT 1
            FROM public.reservation_block_targets AS rbt
            WHERE rbt.block_id = rb.id
              AND (
                rbt.seat_resource_id = sr.id
                OR rbt.floor_section_id = sr.floor_section_id
                OR rbt.venue_wide
              )
          )
      )
    ) AS is_available,
    ed.business_date
  FROM public.booking_slots AS bs
  JOIN public.event_days AS ed
    ON ed.id = bs.event_day_id
  CROSS JOIN public.seat_resources AS sr
  WHERE bs.active = true
    AND bs.admin_only = false
    AND bs.bookable_until_at > now()
    AND sr.active = true
    AND sr.public_resource_code IS NOT NULL
    AND (p_business_date IS NULL OR ed.business_date = p_business_date)
  ORDER BY bs.start_at, sr.name, sr.id;
$$;

-- FUNCTION: cancel_admin_reservation_block_v8(uuid, text, text, text, uuid, bigint, text)
CREATE FUNCTION public.cancel_admin_reservation_block_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_block_id uuid, p_expected_version bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation_block.cancelled';
  v_step jsonb;
  v_block public.reservation_blocks%ROWTYPE;
  v_target_seat_ids uuid[];
  v_new_version bigint;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;
    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(p_actor_admin_id, 'reservation_block.write'),
      ARRAY['allowed']
    );
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_block_id IS NULL OR p_expected_version IS NULL OR p_expected_version < 1
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'blockCommand')
        )), ARRAY['allowed']
      );
    END IF;
    SELECT * INTO v_block FROM public.reservation_blocks WHERE id = p_block_id;
    IF NOT FOUND THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'NOT_FOUND', 'details', jsonb_build_object('entityType', 'block')
        )), ARRAY['allowed']
      );
    END IF;
    SELECT COALESCE(array_agg(sr.id ORDER BY sr.id), '{}'::uuid[])
    INTO v_target_seat_ids
    FROM public.seat_resources AS sr
    WHERE EXISTS (
      SELECT 1 FROM public.reservation_block_targets AS rbt
      WHERE rbt.block_id = v_block.id
        AND (rbt.seat_resource_id = sr.id OR rbt.floor_section_id = sr.floor_section_id OR rbt.venue_wide)
    );

    PERFORM sr.id FROM public.seat_resources AS sr
    WHERE sr.id = ANY(v_target_seat_ids)
    ORDER BY sr.id FOR UPDATE OF sr;
    PERFORM rr.id
    FROM public.reservation_resources AS rr
    WHERE rr.seat_resource_id = ANY(v_target_seat_ids)
      AND rr.assigned_start_at < v_block.end_at
      AND rr.assigned_end_at > v_block.start_at
    ORDER BY rr.id FOR UPDATE OF rr;
    PERFORM rb.id
    FROM public.reservation_blocks AS rb
    WHERE rb.id = v_block.id
       OR (
         rb.event_day_id = v_block.event_day_id
         AND rb.status = 'active'
         AND rb.start_at < v_block.end_at
         AND rb.end_at > v_block.start_at
         AND EXISTS (
           SELECT 1 FROM public.reservation_block_targets AS rbt
           JOIN public.seat_resources AS sr ON sr.id = ANY(v_target_seat_ids)
           WHERE rbt.block_id = rb.id
             AND (rbt.seat_resource_id = sr.id OR rbt.floor_section_id = sr.floor_section_id OR rbt.venue_wide)
         )
       )
    ORDER BY rb.id FOR UPDATE OF rb;

    SELECT * INTO v_block FROM public.reservation_blocks WHERE id = p_block_id;
    IF v_block.version <> p_expected_version THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'VERSION_CONFLICT', 'currentVersion', v_block.version, 'details', '{}'::jsonb
        )), ARRAY['allowed']
      );
    END IF;
    IF v_block.status <> 'active' THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION', 'details', jsonb_build_object('reason', 'block_not_active')
        )), ARRAY['allowed']
      );
    END IF;

    UPDATE public.reservation_blocks
    SET status = 'cancelled', cancelled_by_admin_id = p_actor_admin_id,
        cancelled_at = now(), version = version + 1, updated_at = now()
    WHERE id = v_block.id
    RETURNING version INTO v_new_version;

    PERFORM ed.id FROM public.event_days AS ed
    WHERE ed.id = v_block.event_day_id FOR KEY SHARE OF ed;
    PERFORM public.lock_vip_floor_day_revision_v32(v_block.event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1 INTO v_predicted_revision
    FROM (SELECT 1) AS seed
    LEFT JOIN public.vip_floor_day_revisions AS vfr ON vfr.event_day_id = v_block.event_day_id;
    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, v_block.event_day_id, NULL,
      'block', v_block.id, v_action, p_request_id, p_reason,
      p_expected_version, v_block.version, v_new_version,
      ARRAY['status', 'cancelled_at', 'cancelled_by_admin_id', 'version'],
      jsonb_build_object('status', v_block.status, 'version', v_block.version),
      jsonb_build_object('status', 'cancelled', 'version', v_new_version),
      '{}'::jsonb
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_response := jsonb_build_object(
      'ok', true, 'action', v_action, 'reused', false,
      'blockId', v_block.id, 'entityVersion', v_new_version,
      'boardRevision', v_predicted_revision, 'auditLogId', v_audit_id
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(v_block.event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'XX000', MESSAGE = 'VIP floor revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS v_error_detail = PG_EXCEPTION_DETAIL, v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN RETURN v_error_detail::jsonb; END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: cancel_admin_reservation_v7(uuid, text, text, text, text, uuid, text, integer)
CREATE FUNCTION public.cancel_admin_reservation_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_reason text, p_refund_amount_yen integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_reservation reservations%ROWTYPE;
  v_payment payments%ROWTYPE;
  v_released_count int := 0;
  v_refund_case_id uuid;
  v_reserved_amount bigint := 0;
  v_unlinked_refund_amount bigint := 0;
  v_remaining_amount bigint := 0;
  v_has_arrival_evidence boolean := false;
  v_response jsonb;
BEGIN
  SELECT * INTO v_admin FROM admin_users WHERE id = p_actor_admin_id FOR UPDATE;
  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;
  IF v_admin.role NOT IN ('manager','owner','engineer') THEN
    RAISE EXCEPTION 'admin role cannot cancel reservations';
  END IF;

  -- W07-G-49: cancelling a reservation is an important audited operation;
  -- the reason is mandatory (the admin cancel route already forwards it).
  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'reason is required to cancel a reservation';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;
    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  IF p_refund_amount_yen < 0 THEN
    RAISE EXCEPTION 'invalid refund amount';
  END IF;

  SELECT * INTO v_reservation
  FROM reservations
  WHERE id = p_reservation_id
  FOR UPDATE;

  IF NOT FOUND OR v_reservation.status IN ('cancelled','hold_expired','failed') THEN
    RAISE EXCEPTION 'reservation cannot be cancelled';
  END IF;

  -- W07-G-48: arrival evidence = checked-in timestamps or arrival-side
  -- service status. Post-admission money decisions must go through the
  -- reviewed path (v8 refund_decision='review'), never a direct v7 refund.
  v_has_arrival_evidence :=
    v_reservation.arrived_at IS NOT NULL
    OR v_reservation.checked_in_at IS NOT NULL
    OR v_reservation.vipapp_arrived_at IS NOT NULL
    OR v_reservation.service_status IN (
         'arrived','partial_arrival','seated','bottle_pending',
         'bottle_served','bill_requested','paid','resetting','completed')
    OR v_reservation.vipapp_service_status IN (
         'arrived','partial_arrival','seated','bottle_pending',
         'bottle_served','bill_requested','paid','resetting','completed');

  IF p_refund_amount_yen > 0 AND v_has_arrival_evidence THEN
    RAISE EXCEPTION 'post-admission refund requires review flow'
      USING ERRCODE = 'P0001',
            DETAIL = 'use cancel_admin_reservation_v8 with refund_decision=review';
  END IF;

  UPDATE reservation_resources
  SET lock_status = 'released',
      released_at = now(),
      updated_at = now()
  WHERE reservation_id = v_reservation.id
    AND lock_status IN ('held','payment_grace_locked','confirmed');

  GET DIAGNOSTICS v_released_count = ROW_COUNT;

  UPDATE reservations
  SET status = 'cancelled',
      updated_at = now()
  WHERE id = v_reservation.id;

  INSERT INTO notification_jobs(reservation_id, channel, payload_json)
  VALUES (
    v_reservation.id,
    'line',
    jsonb_build_object(
      'template', 'admin_reservation_cancelled',
      'reservationId', v_reservation.id,
      'reason', p_reason,
      'refundAmountYen', p_refund_amount_yen
    )
  );

  IF p_refund_amount_yen > 0 THEN
    SELECT * INTO v_payment
    FROM payments
    WHERE reservation_id = v_reservation.id
      AND type = 'deposit'
      AND status = 'succeeded'
    ORDER BY created_at DESC
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'no succeeded deposit payment found for refund';
    END IF;

    -- W07-R-10: remaining refundable = payment amount - open/terminal refund
    -- cases on this payment - unlinked external stripe_refunds. Computed
    -- while holding FOR UPDATE on the payment row so concurrent v7 cancels
    -- serialize here.
    SELECT COALESCE(sum(rc.amount_yen), 0)
    INTO v_reserved_amount
    FROM refund_cases rc
    WHERE rc.payment_id = v_payment.id
      AND rc.status IN ('required','requested','approved','processing','refunded');

    SELECT COALESCE(sum(sr.amount_yen), 0)
    INTO v_unlinked_refund_amount
    FROM stripe_refunds sr
    WHERE sr.payment_id = v_payment.id
      AND sr.refund_case_id IS NULL
      AND lower(sr.status) IN ('created','pending','succeeded');

    v_remaining_amount := v_payment.amount_yen - v_reserved_amount - v_unlinked_refund_amount;

    IF p_refund_amount_yen > v_remaining_amount THEN
      RAISE EXCEPTION 'refund amount exceeds remaining refundable balance'
        USING ERRCODE = 'P0001',
              DETAIL = 'remaining_refundable_yen=' || v_remaining_amount;
    END IF;

    INSERT INTO refund_cases(
      reservation_id,
      payment_id,
      amount_yen,
      currency,
      reason,
      status,
      requested_by_admin_id,
      environment,
      stripe_account_id,
      idempotency_key,
      stripe_idempotency_key
    )
    VALUES (
      v_reservation.id,
      v_payment.id,
      p_refund_amount_yen,
      v_payment.currency,
      COALESCE(p_reason, 'admin_cancel_refund'),
      'required',
      p_actor_admin_id,
      v_payment.environment,
      v_payment.stripe_account_id,
      'admin_cancel_refund:' || v_payment.id || ':' || p_idempotency_key,
      'stripe_refund:admin_cancel:' || v_payment.id || ':' || p_idempotency_key
    )
    ON CONFLICT (idempotency_key) DO UPDATE
    SET amount_yen = EXCLUDED.amount_yen,
        reason = EXCLUDED.reason,
        updated_at = now()
    RETURNING id INTO v_refund_case_id;
  END IF;

  v_response := jsonb_build_object(
    'reservationId', v_reservation.id,
    'releasedResourceCount', v_released_count,
    'refundCaseId', v_refund_case_id
  );

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'reservations', v_reservation.id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'cancelled', 'response', v_response);
END;
$$;

-- FUNCTION: cancel_admin_reservation_v8(uuid, text, text, text, uuid, bigint, text, text, text, integer, boolean)
CREATE FUNCTION public.cancel_admin_reservation_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_version bigint, p_reason_code text, p_reason_note text, p_refund_decision text, p_refund_amount_yen integer, p_notify_customer boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation.cancelled';
  v_reason_code text := lower(btrim(COALESCE(p_reason_code, '')));
  v_refund_decision text := lower(btrim(COALESCE(p_refund_decision, '')));
  v_step jsonb;
  v_reservation public.reservations%ROWTYPE;
  v_payment public.payments%ROWTYPE;
  v_refund_case_id uuid;
  v_reserved_amount bigint := 0;
  v_refunded_amount bigint := 0;
  v_unlinked_refund_amount bigint := 0;
  v_remaining_amount int := 0;
  v_effective_refund_amount int;
  v_review_case_amount int := 0;
  v_released_count int := 0;
  v_has_arrival_evidence boolean := false;
  v_new_version bigint;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;
    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(p_actor_admin_id, 'reservation_cancel.write'),
      ARRAY['allowed']
    );
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR v_reason_code NOT IN ('customer_request', 'duplicate', 'venue_decision', 'no_contact', 'other')
      OR (v_reason_code = 'other' AND NULLIF(btrim(COALESCE(p_reason_note, '')), '') IS NULL)
      OR v_refund_decision NOT IN ('none', 'full', 'partial', 'review')
      OR p_notify_customer IS NULL
      OR (v_refund_decision = 'none' AND COALESCE(p_refund_amount_yen, 0) <> 0)
      OR (v_refund_decision = 'partial' AND p_refund_amount_yen IS NULL)
      OR (v_refund_decision IN ('full', 'review') AND p_refund_amount_yen IS NOT NULL)
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'cancellationCommand')
        )), ARRAY['allowed']
      );
    END IF;

    v_step := public.assert_reservation_version_v8(p_reservation_id, p_expected_version);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
    SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id;
    IF v_reservation.status IN ('cancelled', 'hold_expired', 'payment_window_expired', 'failed')
      OR v_reservation.service_status IN ('completed', 'no_show')
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION',
          'details', jsonb_build_object('reason', 'reservation_terminal')
        )), ARRAY['allowed']
      );
    END IF;

    PERFORM sr.id FROM public.seat_resources AS sr
    WHERE EXISTS (
      SELECT 1 FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id AND rr.seat_resource_id = sr.id
    )
    ORDER BY sr.id FOR UPDATE OF sr;
    PERFORM rr.id FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
    ORDER BY rr.id FOR UPDATE OF rr;
    PERFORM rb.id
    FROM public.reservation_blocks AS rb
    WHERE rb.event_day_id = v_reservation.event_day_id
      AND rb.status = 'active'
      AND rb.start_at < v_reservation.expected_release_at
      AND rb.end_at > v_reservation.scheduled_start_at
      AND EXISTS (
        SELECT 1
        FROM public.reservation_block_targets AS rbt
        JOIN public.reservation_resources AS rr ON rr.reservation_id = v_reservation.id
        JOIN public.seat_resources AS sr ON sr.id = rr.seat_resource_id
        WHERE rbt.block_id = rb.id
          AND (rbt.seat_resource_id = sr.id OR rbt.floor_section_id = sr.floor_section_id OR rbt.venue_wide)
      )
    ORDER BY rb.id FOR UPDATE OF rb;

    -- Lock financial evidence only after the entity/seat/relation/block order.
    PERFORM payment.id
    FROM public.payments AS payment
    WHERE payment.reservation_id = v_reservation.id
    ORDER BY payment.id FOR UPDATE OF payment;
    PERFORM refund_case.id
    FROM public.refund_cases AS refund_case
    WHERE refund_case.reservation_id = v_reservation.id
    ORDER BY refund_case.id FOR UPDATE OF refund_case;
    PERFORM refund.id
    FROM public.stripe_refunds AS refund
    WHERE refund.reservation_id = v_reservation.id
    ORDER BY refund.id FOR UPDATE OF refund;

    SELECT * INTO v_payment
    FROM public.payments
    WHERE reservation_id = v_reservation.id
      AND type = 'deposit'
      AND status IN ('succeeded', 'refund_pending', 'refunded')
    ORDER BY created_at DESC, id DESC
    LIMIT 1;

    IF v_refund_decision = 'partial' AND NOT FOUND THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'REFUND_PAYMENT_MISSING',
          'details', jsonb_build_object('reason', 'refundable_deposit_required')
        )), ARRAY['allowed']
      );
    END IF;

    -- W07-G-11: 'review' also needs the binding evidence + remaining amount,
    -- because the review case is persisted with the remaining ceiling.
    IF FOUND AND v_refund_decision IN ('partial', 'full', 'review') THEN
      IF lower(v_payment.currency) <> 'jpy'
        OR v_payment.environment NOT IN ('test', 'live')
        OR EXISTS (
          SELECT 1 FROM public.refund_cases AS rc
          WHERE rc.payment_id = v_payment.id
            AND (
              lower(rc.currency) <> lower(v_payment.currency)
              OR rc.environment <> v_payment.environment
              OR rc.stripe_account_key <> v_payment.stripe_account_key
              OR rc.reservation_id <> v_reservation.id
            )
        )
        OR EXISTS (
          SELECT 1 FROM public.stripe_refunds AS sr
          WHERE sr.payment_id = v_payment.id
            AND (
              sr.environment <> v_payment.environment
              OR sr.stripe_account_key <> v_payment.stripe_account_key
              OR sr.reservation_id <> v_reservation.id
            )
        )
        OR EXISTS (
          SELECT 1 FROM public.refund_cases AS rc
          WHERE rc.payment_id = v_payment.id
            AND rc.status = 'refunded'
            AND NOT EXISTS (
              SELECT 1 FROM public.stripe_refunds AS sr
              WHERE sr.refund_case_id = rc.id
                AND lower(sr.status) IN ('created', 'pending', 'succeeded')
                AND sr.payment_id = v_payment.id
                AND sr.reservation_id = v_reservation.id
                AND sr.environment = v_payment.environment
                AND sr.stripe_account_key = v_payment.stripe_account_key
            )
        )
      THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
            'code', 'REFUND_BINDING_INVALID',
            'details', jsonb_build_object('reason', 'financial_evidence_mismatch')
          )), ARRAY['allowed']
        );
      END IF;

      SELECT COALESCE(sum(rc.amount_yen), 0)
      INTO v_reserved_amount
      FROM public.refund_cases AS rc
      WHERE rc.payment_id = v_payment.id
        AND rc.status IN ('required', 'requested', 'approved', 'processing');
      SELECT COALESCE(sum(rc.amount_yen), 0)
      INTO v_refunded_amount
      FROM public.refund_cases AS rc
      WHERE rc.payment_id = v_payment.id
        AND rc.status = 'refunded';
      -- W07-R-10 follow-through: unlinked external refund evidence also
      -- reduces the remaining refundable balance.
      SELECT COALESCE(sum(sr.amount_yen), 0)
      INTO v_unlinked_refund_amount
      FROM public.stripe_refunds AS sr
      WHERE sr.payment_id = v_payment.id
        AND sr.refund_case_id IS NULL
        AND lower(sr.status) IN ('created', 'pending', 'succeeded');
      IF v_reserved_amount < 0 OR v_refunded_amount < 0
        OR v_reserved_amount + v_refunded_amount + v_unlinked_refund_amount > v_payment.amount_yen
      THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
            'code', 'REFUND_BINDING_INVALID',
            'details', jsonb_build_object('reason', 'refund_evidence_exceeds_payment')
          )), ARRAY['allowed']
        );
      END IF;
      v_remaining_amount := GREATEST(
        v_payment.amount_yen - v_reserved_amount - v_refunded_amount - v_unlinked_refund_amount, 0
      )::int;
      IF v_remaining_amount > 0 AND (
        v_payment.provider_object_type IS DISTINCT FROM 'payment_intent'
        OR NULLIF(btrim(COALESCE(v_payment.provider_object_id, '')), '') IS NULL
      ) THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
            'code', 'REFUND_BINDING_INVALID',
            'details', jsonb_build_object('reason', 'provider_payment_binding_missing')
          )), ARRAY['allowed']
        );
      END IF;
    END IF;

    -- W07-G-48: arrival evidence means the party consumed service. Direct
    -- refunds are refused; the money question must go through 'review'
    -- (persisted 'requested' case resolved by a different admin).
    v_has_arrival_evidence :=
      v_reservation.arrived_at IS NOT NULL
      OR v_reservation.checked_in_at IS NOT NULL
      OR v_reservation.vipapp_arrived_at IS NOT NULL
      OR v_reservation.service_status IN (
           'arrived','partial_arrival','seated','bottle_pending',
           'bottle_served','bill_requested','paid','resetting')
      OR v_reservation.vipapp_service_status IN (
           'arrived','partial_arrival','seated','bottle_pending',
           'bottle_served','bill_requested','paid','resetting');

    IF v_has_arrival_evidence AND v_refund_decision IN ('full', 'partial') THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'POST_ADMISSION_REVIEW_REQUIRED',
          'details', jsonb_build_object(
            'reason', 'arrival_evidence_present',
            'allowedDecisions', jsonb_build_array('none', 'review')
          )
        )), ARRAY['allowed']
      );
    END IF;

    v_effective_refund_amount := CASE v_refund_decision
      WHEN 'none' THEN 0
      WHEN 'partial' THEN p_refund_amount_yen
      WHEN 'full' THEN v_remaining_amount
      ELSE p_refund_amount_yen
    END;
    IF v_refund_decision = 'partial'
      AND (v_effective_refund_amount <= 0 OR v_effective_refund_amount > v_remaining_amount)
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'REFUND_AMOUNT_INVALID',
          'details', jsonb_build_object('remainingRefundableYen', v_remaining_amount)
        )), ARRAY['allowed']
      );
    END IF;

    INSERT INTO public.reservation_assignment_events(
      reservation_id, reservation_resource_id, seat_resource_id, event_type,
      interval_before, interval_after, actor_admin_id, reason, request_id
    )
    SELECT rr.reservation_id, rr.id, rr.seat_resource_id, 'released',
      jsonb_build_object('startAt', rr.assigned_start_at, 'endAt', rr.assigned_end_at),
      NULL, p_actor_admin_id, v_reason_code, p_request_id
    FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now());
    UPDATE public.reservation_resources AS rr
    SET lock_status = 'released', released_at = now(),
        released_by_admin_id = p_actor_admin_id,
        release_reason = v_reason_code,
        version = rr.version + 1, updated_at = now()
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now());
    GET DIAGNOSTICS v_released_count = ROW_COUNT;
    UPDATE public.reservations
    SET status = 'cancelled', version = version + 1, updated_at = now()
    WHERE id = v_reservation.id RETURNING version INTO v_new_version;

    IF v_refund_decision IN ('partial', 'full') AND v_effective_refund_amount > 0 THEN
      INSERT INTO public.refund_cases(
        reservation_id, payment_id, amount_yen, currency, reason, status,
        requested_by_admin_id, environment, stripe_account_id,
        idempotency_key, stripe_idempotency_key
      ) VALUES (
        v_reservation.id, v_payment.id, v_effective_refund_amount,
        lower(v_payment.currency), 'admin_cancellation:' || v_reason_code,
        'required', p_actor_admin_id, v_payment.environment,
        v_payment.stripe_account_id,
        'vip_floor_cancel:' || v_payment.id || ':' || p_idempotency_key,
        'vip_floor_cancel_refund:' || v_payment.id || ':' || p_idempotency_key
      ) RETURNING id INTO v_refund_case_id;
    ELSIF v_refund_decision = 'review' AND v_remaining_amount > 0 THEN
      -- W07-G-11: persist the open monetary obligation as a 'requested'
      -- case holding the remaining ceiling. Resolved later via
      -- resolve_admin_refund_review_v7 by a different admin.
      v_review_case_amount := v_remaining_amount;
      INSERT INTO public.refund_cases(
        reservation_id, payment_id, amount_yen, currency, reason, status,
        requested_by_admin_id, environment, stripe_account_id,
        idempotency_key, stripe_idempotency_key
      ) VALUES (
        v_reservation.id, v_payment.id, v_review_case_amount,
        lower(v_payment.currency), 'admin_cancellation_review:' || v_reason_code,
        'requested', p_actor_admin_id, v_payment.environment,
        v_payment.stripe_account_id,
        'vip_floor_cancel_review:' || v_payment.id || ':' || p_idempotency_key,
        'vip_floor_cancel_review_refund:' || v_payment.id || ':' || p_idempotency_key
      ) RETURNING id INTO v_refund_case_id;
    END IF;
    INSERT INTO public.reservation_cancellations(
      reservation_id, reason_code, reason_note, refund_decision,
      refund_amount_yen, refund_case_id, notify_customer,
      cancelled_by_admin_id, request_id
    ) VALUES (
      v_reservation.id, v_reason_code,
      NULLIF(btrim(COALESCE(p_reason_note, '')), ''),
      v_refund_decision,
      CASE WHEN v_refund_decision = 'review'
           THEN COALESCE(v_review_case_amount, 0)
           ELSE v_effective_refund_amount END,
      v_refund_case_id,
      p_notify_customer, p_actor_admin_id, p_request_id
    );
    IF p_notify_customer THEN
      INSERT INTO public.notification_jobs(reservation_id, channel, payload_json)
      VALUES (
        v_reservation.id, 'line',
        jsonb_build_object(
          'template', 'admin_reservation_cancelled',
          'reservationId', v_reservation.id,
          'reasonCode', v_reason_code,
          'refundDecision', v_refund_decision
        )
      );
    END IF;

    PERFORM ed.id FROM public.event_days AS ed
    WHERE ed.id = v_reservation.event_day_id FOR KEY SHARE OF ed;
    PERFORM public.lock_vip_floor_day_revision_v32(v_reservation.event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1 INTO v_predicted_revision
    FROM (SELECT 1) AS seed LEFT JOIN public.vip_floor_day_revisions AS vfr
      ON vfr.event_day_id = v_reservation.event_day_id;
    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, v_reservation.event_day_id, v_reservation.id,
      'reservation', v_reservation.id, v_action, p_request_id, v_reason_code,
      p_expected_version, v_reservation.version, v_new_version,
      ARRAY['status', 'cancellation', 'assignments', 'version'],
      jsonb_build_object('status', v_reservation.status, 'version', v_reservation.version),
      jsonb_build_object('status', 'cancelled', 'version', v_new_version),
      jsonb_build_object(
        'reasonCode', v_reason_code,
        'refundDecision', v_refund_decision,
        'refundAmountYen', v_effective_refund_amount,
        'refundCaseCreated', v_refund_case_id IS NOT NULL,
        'reviewCaseAmountYen', v_review_case_amount,
        'postAdmissionEvidence', v_has_arrival_evidence,
        'notifyCustomer', p_notify_customer,
        'releasedAssignmentCount', v_released_count
      )
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    IF v_refund_case_id IS NOT NULL THEN
      UPDATE public.refund_cases SET audit_log_id = v_audit_id WHERE id = v_refund_case_id;
    END IF;
    v_response := jsonb_build_object(
      'ok', true, 'action', v_action, 'reused', false,
      'reservationId', v_reservation.id, 'entityVersion', v_new_version,
      'boardRevision', v_predicted_revision, 'auditLogId', v_audit_id,
      'refundDecision', v_refund_decision,
      'refundAmountYen', CASE WHEN v_refund_decision = 'review'
                              THEN COALESCE(v_review_case_amount, 0)
                              ELSE v_effective_refund_amount END,
      'remainingRefundableYen', v_remaining_amount,
      'refundCaseId', v_refund_case_id,
      'releasedAssignmentCount', v_released_count
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(v_reservation.event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'XX000', MESSAGE = 'VIP floor revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS v_error_detail = PG_EXCEPTION_DETAIL, v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN RETURN v_error_detail::jsonb; END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: change_admin_reservation_assignments_v8(uuid, text, text, text, uuid, bigint, text, uuid[], boolean, boolean, text)
CREATE FUNCTION public.change_admin_reservation_assignments_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_version bigint, p_operation text, p_table_ids uuid[], p_reopen_online_inventory boolean, p_capacity_override boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation.assignments.changed';
  v_operation text := lower(btrim(COALESCE(p_operation, '')));
  v_step jsonb;
  v_reservation public.reservations%ROWTYPE;
  v_current_ids uuid[] := '{}'::uuid[];
  v_requested_ids uuid[] := '{}'::uuid[];
  v_lock_ids uuid[] := '{}'::uuid[];
  v_final_ids uuid[] := '{}'::uuid[];
  v_table_id uuid;
  v_assignment public.reservation_resources%ROWTYPE;
  v_role text;
  v_capacity int;
  v_guard_block_id uuid;
  v_warnings jsonb := '[]'::jsonb;
  v_material_change boolean;
  v_new_version bigint;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;

    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(p_actor_admin_id, 'reservation_assignment.write'),
      ARRAY['allowed']
    );
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR v_operation NOT IN ('replace', 'add', 'remove', 'unassign')
      OR EXISTS (SELECT 1 FROM unnest(COALESCE(p_table_ids, '{}'::uuid[])) AS requested(id) WHERE id IS NULL)
      OR (
        v_operation IN ('replace', 'add', 'remove')
        AND cardinality(COALESCE(p_table_ids, '{}'::uuid[])) = 0
      )
      OR (v_operation = 'unassign' AND cardinality(COALESCE(p_table_ids, '{}'::uuid[])) <> 0)
      OR (v_operation = 'unassign' AND p_reopen_online_inventory IS NULL)
      OR (v_operation <> 'unassign' AND p_reopen_online_inventory IS NOT NULL)
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'assignmentCommand')
          )
        ), ARRAY['allowed']
      );
    END IF;

    SELECT COALESCE(array_agg(DISTINCT id ORDER BY id), '{}'::uuid[])
    INTO v_requested_ids
    FROM unnest(COALESCE(p_table_ids, '{}'::uuid[])) AS requested(id);
    IF cardinality(v_requested_ids) <> cardinality(COALESCE(p_table_ids, '{}'::uuid[])) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'tableIds', 'reason', 'duplicates_not_allowed')
          )
        ), ARRAY['allowed']
      );
    END IF;

    v_step := public.assert_reservation_version_v8(p_reservation_id, p_expected_version);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
    SELECT * INTO v_reservation
    FROM public.reservations
    WHERE id = p_reservation_id;

    IF v_reservation.status IN ('cancelled', 'hold_expired', 'payment_window_expired', 'failed')
      OR v_reservation.service_status IN ('completed', 'no_show')
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION',
          'details', jsonb_build_object('reason', 'reservation_terminal')
        )), ARRAY['allowed']
      );
    END IF;

    SELECT COALESCE(array_agg(rr.seat_resource_id ORDER BY rr.seat_resource_id), '{}'::uuid[])
    INTO v_current_ids
    FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now());

    v_final_ids := CASE v_operation
      WHEN 'replace' THEN v_requested_ids
      WHEN 'add' THEN ARRAY(
        SELECT DISTINCT id FROM unnest(v_current_ids || v_requested_ids) AS combined(id) ORDER BY id
      )
      WHEN 'remove' THEN ARRAY(
        SELECT id FROM unnest(v_current_ids) AS current_table(id)
        WHERE NOT (id = ANY(v_requested_ids)) ORDER BY id
      )
      ELSE '{}'::uuid[]
    END;
    v_lock_ids := ARRAY(
      SELECT DISTINCT id FROM unnest(v_current_ids || v_requested_ids) AS combined(id) ORDER BY id
    );

    IF v_operation = 'remove' AND cardinality(v_final_ids) = 0 THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object(
              'field', 'operation',
              'reason', 'use_unassign_for_last_table'
            )
          )
        ), ARRAY['allowed']
      );
    END IF;

    IF v_operation IN ('remove', 'unassign')
      AND v_operation = 'remove'
      AND EXISTS (
        SELECT 1 FROM unnest(v_requested_ids) AS requested(id)
        WHERE NOT (id = ANY(v_current_ids))
      )
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'tableIds', 'reason', 'table_not_assigned')
          )
        ), ARRAY['allowed']
      );
    END IF;

    -- Lock the union of existing and requested seats, then every reservation
    -- relation, then all overlapping block rows.
    PERFORM sr.id
    FROM public.seat_resources AS sr
    WHERE sr.id = ANY(v_lock_ids)
    ORDER BY sr.id
    FOR UPDATE OF sr;
    IF (SELECT count(*) FROM public.seat_resources WHERE id = ANY(v_lock_ids))
      <> cardinality(v_lock_ids)
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'NOT_FOUND',
            'details', jsonb_build_object('entityType', 'table')
          )
        ), ARRAY['allowed']
      );
    END IF;

    PERFORM rr.id
    FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
       OR rr.seat_resource_id = ANY(v_lock_ids)
    ORDER BY rr.id
    FOR UPDATE OF rr;

    PERFORM rb.id
    FROM public.reservation_blocks AS rb
    WHERE rb.event_day_id = v_reservation.event_day_id
      AND rb.status = 'active'
      AND rb.start_at < v_reservation.expected_release_at
      AND rb.end_at > v_reservation.scheduled_start_at
      AND EXISTS (
        SELECT 1
        FROM public.reservation_block_targets AS rbt
        JOIN public.seat_resources AS sr
          ON sr.id = ANY(v_lock_ids)
        WHERE rbt.block_id = rb.id
          AND (
            rbt.seat_resource_id = sr.id
            OR rbt.floor_section_id = sr.floor_section_id
            OR rbt.venue_wide
          )
      )
    ORDER BY rb.id
    FOR UPDATE OF rb;

    FOREACH v_table_id IN ARRAY v_final_ids LOOP
      v_step := public.assert_assignment_conflict_free_v8(
        v_reservation.event_day_id,
        v_reservation.id,
        v_table_id,
        v_reservation.scheduled_start_at,
        v_reservation.expected_release_at,
        now()
      );
      PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
      SELECT COALESCE(jsonb_agg(warning ORDER BY warning::text), '[]'::jsonb)
      INTO v_warnings
      FROM (
        SELECT DISTINCT warning
        FROM jsonb_array_elements(
          v_warnings || COALESCE(v_step -> 'warnings', '[]'::jsonb)
        ) AS combined(warning)
      ) AS deduplicated;
    END LOOP;

    IF COALESCE(p_capacity_override, false)
      AND NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'reason', 'reason', 'capacity_override')
          )
        ), ARRAY['allowed']
      );
    END IF;
    SELECT COALESCE(sum(sr.capacity_max), 0)::int
    INTO v_capacity
    FROM public.seat_resources AS sr
    WHERE sr.id = ANY(v_final_ids);
    IF cardinality(v_final_ids) > 0 AND v_capacity < v_reservation.guest_count THEN
      IF NOT COALESCE(p_capacity_override, false) THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object(
            'action', 'rejected',
            'error', jsonb_build_object(
              'code', 'CAPACITY_WARNING_REQUIRES_OVERRIDE',
              'details', jsonb_build_object(
                'guestCount', v_reservation.guest_count,
                'combinedCapacity', v_capacity
              )
            )
          ), ARRAY['allowed']
        );
      ELSIF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object(
            'action', 'rejected',
            'error', jsonb_build_object(
              'code', 'INVALID_COMMAND',
              'details', jsonb_build_object('field', 'reason', 'reason', 'capacity_override')
            )
          ), ARRAY['allowed']
        );
      END IF;
    END IF;

    SELECT
      EXISTS (
        SELECT 1 FROM unnest(v_current_ids) AS current_table(id)
        WHERE NOT (id = ANY(v_final_ids))
      )
      OR EXISTS (
        SELECT 1
        FROM unnest(v_final_ids) WITH ORDINALITY AS final_table(id, ordinal)
        LEFT JOIN public.reservation_resources AS rr
          ON rr.reservation_id = v_reservation.id
         AND rr.seat_resource_id = final_table.id
        WHERE rr.id IS NULL
           OR NOT public.active_reservation_assignment_v8(rr.id, now())
           OR rr.assigned_start_at IS DISTINCT FROM v_reservation.scheduled_start_at
           OR rr.assigned_end_at IS DISTINCT FROM v_reservation.expected_release_at
           OR rr.assignment_role IS DISTINCT FROM
             CASE WHEN final_table.ordinal = 1 THEN 'primary' ELSE 'additional' END
      )
    INTO v_material_change;

    IF NOT v_material_change THEN
      PERFORM ed.id FROM public.event_days AS ed
      WHERE ed.id = v_reservation.event_day_id FOR KEY SHARE OF ed;
      PERFORM public.lock_vip_floor_day_revision_v32(v_reservation.event_day_id);
    SELECT COALESCE(vfr.revision, 0)
      INTO v_predicted_revision
      FROM (SELECT 1) AS seed
      LEFT JOIN public.vip_floor_day_revisions AS vfr
        ON vfr.event_day_id = v_reservation.event_day_id;
      v_step := public.append_vip_floor_audit_v8(
        p_actor_admin_id, v_reservation.event_day_id, v_reservation.id,
        'reservation', v_reservation.id, v_action || '.noop', p_request_id, p_reason,
        NULL, NULL, NULL, '{}'::text[],
        jsonb_build_object('tableIds', to_jsonb(v_current_ids), 'version', v_reservation.version),
        jsonb_build_object('tableIds', to_jsonb(v_current_ids), 'version', v_reservation.version),
        jsonb_build_object('operation', v_operation, 'warnings', v_warnings)
      );
      PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
      v_audit_id := (v_step ->> 'auditLogId')::uuid;
      v_response := jsonb_build_object(
        'ok', true, 'action', v_action, 'reused', false,
        'reservationId', v_reservation.id,
        'entityVersion', v_reservation.version,
        'boardRevision', v_predicted_revision,
        'auditLogId', v_audit_id,
        'operation', v_operation,
        'tableIds', to_jsonb(v_current_ids),
        'warnings', v_warnings,
        'noOp', true
      );
      PERFORM public.complete_admin_action_request_v8(
        p_actor_admin_id, v_action, p_idempotency_key, v_response
      );
      RETURN v_response;
    END IF;

    -- Release relations that are absent from the final set.
    INSERT INTO public.reservation_assignment_events(
      reservation_id, reservation_resource_id, seat_resource_id, event_type,
      interval_before, interval_after, actor_admin_id, reason, request_id
    )
    SELECT
      rr.reservation_id, rr.id, rr.seat_resource_id, 'released',
      jsonb_build_object('startAt', rr.assigned_start_at, 'endAt', rr.assigned_end_at),
      NULL, p_actor_admin_id, p_reason, p_request_id
    FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now())
      AND NOT (rr.seat_resource_id = ANY(v_final_ids));

    UPDATE public.reservation_resources AS rr
    SET lock_status = 'released',
        released_at = now(),
        released_by_admin_id = p_actor_admin_id,
        release_reason = p_reason,
        version = rr.version + 1,
        updated_at = now()
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now())
      AND NOT (rr.seat_resource_id = ANY(v_final_ids));

    FOREACH v_table_id IN ARRAY v_final_ids LOOP
      v_role := CASE WHEN v_table_id = v_final_ids[1] THEN 'primary' ELSE 'additional' END;
      SELECT * INTO v_assignment
      FROM public.reservation_resources
      WHERE reservation_id = v_reservation.id
        AND seat_resource_id = v_table_id;

      IF NOT FOUND THEN
        INSERT INTO public.reservation_resources(
          reservation_id, seat_resource_id, lock_status, confirmed_at,
          assigned_start_at, assigned_end_at, assignment_role,
          assigned_by_admin_id
        )
        VALUES (
          v_reservation.id, v_table_id, 'confirmed', now(),
          v_reservation.scheduled_start_at, v_reservation.expected_release_at,
          v_role, p_actor_admin_id
        )
        RETURNING * INTO v_assignment;
        INSERT INTO public.reservation_assignment_events(
          reservation_id, reservation_resource_id, seat_resource_id, event_type,
          interval_before, interval_after, actor_admin_id, reason, request_id
        ) VALUES (
          v_reservation.id, v_assignment.id, v_table_id, 'assigned', NULL,
          jsonb_build_object(
            'startAt', v_reservation.scheduled_start_at,
            'endAt', v_reservation.expected_release_at
          ),
          p_actor_admin_id, p_reason, p_request_id
        );
      ELSIF NOT public.active_reservation_assignment_v8(v_assignment.id, now()) THEN
        UPDATE public.reservation_resources
        SET lock_status = 'confirmed',
            confirmed_at = COALESCE(confirmed_at, now()),
            released_at = NULL,
            released_by_admin_id = NULL,
            release_reason = NULL,
            assigned_start_at = v_reservation.scheduled_start_at,
            assigned_end_at = v_reservation.expected_release_at,
            assignment_role = v_role,
            assigned_by_admin_id = p_actor_admin_id,
            version = version + 1,
            updated_at = now()
        WHERE id = v_assignment.id;
        INSERT INTO public.reservation_assignment_events(
          reservation_id, reservation_resource_id, seat_resource_id, event_type,
          interval_before, interval_after, actor_admin_id, reason, request_id
        ) VALUES (
          v_reservation.id, v_assignment.id, v_table_id, 'reactivated',
          jsonb_build_object(
            'startAt', v_assignment.assigned_start_at,
            'endAt', v_assignment.assigned_end_at
          ),
          jsonb_build_object(
            'startAt', v_reservation.scheduled_start_at,
            'endAt', v_reservation.expected_release_at
          ),
          p_actor_admin_id, p_reason, p_request_id
        );
      ELSIF (v_assignment.assigned_start_at, v_assignment.assigned_end_at)
        IS DISTINCT FROM (
          v_reservation.scheduled_start_at, v_reservation.expected_release_at
        )
      THEN
        UPDATE public.reservation_resources
        SET assigned_start_at = v_reservation.scheduled_start_at,
            assigned_end_at = v_reservation.expected_release_at,
            assignment_role = v_role,
            assigned_by_admin_id = p_actor_admin_id,
            version = version + 1,
            updated_at = now()
        WHERE id = v_assignment.id;
        INSERT INTO public.reservation_assignment_events(
          reservation_id, reservation_resource_id, seat_resource_id, event_type,
          interval_before, interval_after, actor_admin_id, reason, request_id
        ) VALUES (
          v_reservation.id, v_assignment.id, v_table_id, 'interval_changed',
          jsonb_build_object('startAt', v_assignment.assigned_start_at, 'endAt', v_assignment.assigned_end_at),
          jsonb_build_object('startAt', v_reservation.scheduled_start_at, 'endAt', v_reservation.expected_release_at),
          p_actor_admin_id, p_reason, p_request_id
        );
      ELSIF v_assignment.assignment_role IS DISTINCT FROM v_role THEN
        UPDATE public.reservation_resources
        SET assignment_role = v_role,
            assigned_by_admin_id = p_actor_admin_id,
            version = version + 1,
            updated_at = now()
        WHERE id = v_assignment.id;
        INSERT INTO public.reservation_assignment_events(
          reservation_id, reservation_resource_id, seat_resource_id, event_type,
          interval_before, interval_after, actor_admin_id, reason, request_id
        ) VALUES (
          v_reservation.id, v_assignment.id, v_table_id, 'role_changed',
          jsonb_build_object('startAt', v_assignment.assigned_start_at, 'endAt', v_assignment.assigned_end_at),
          jsonb_build_object('startAt', v_assignment.assigned_start_at, 'endAt', v_assignment.assigned_end_at),
          p_actor_admin_id, p_reason, p_request_id
        );
      END IF;
    END LOOP;

    IF v_operation = 'unassign' AND p_reopen_online_inventory = false
      AND cardinality(v_current_ids) > 0
    THEN
      INSERT INTO public.reservation_blocks(
        event_day_id, scope, kind, start_at, end_at, memo, created_by_admin_id
      ) VALUES (
        v_reservation.event_day_id, 'online_only', 'unassignment_guard',
        v_reservation.scheduled_start_at, v_reservation.expected_release_at,
        'unassignment_guard', p_actor_admin_id
      ) RETURNING id INTO v_guard_block_id;
      INSERT INTO public.reservation_block_targets(block_id, seat_resource_id)
      SELECT v_guard_block_id, id FROM unnest(v_current_ids) AS current_table(id)
      ORDER BY id;
    END IF;

    UPDATE public.reservations
    SET version = version + 1,
        updated_at = now()
    WHERE id = v_reservation.id
    RETURNING version INTO v_new_version;

    PERFORM ed.id FROM public.event_days AS ed
    WHERE ed.id = v_reservation.event_day_id
    FOR KEY SHARE OF ed;
    PERFORM public.lock_vip_floor_day_revision_v32(v_reservation.event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1
    INTO v_predicted_revision
    FROM (SELECT 1) AS seed
    LEFT JOIN public.vip_floor_day_revisions AS vfr
      ON vfr.event_day_id = v_reservation.event_day_id;

    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, v_reservation.event_day_id, v_reservation.id,
      'reservation', v_reservation.id, v_action, p_request_id, p_reason,
      p_expected_version, v_reservation.version, v_new_version,
      ARRAY['assignments', 'version'],
      jsonb_build_object('tableIds', to_jsonb(v_current_ids), 'version', v_reservation.version),
      jsonb_build_object('tableIds', to_jsonb(v_final_ids), 'version', v_new_version),
      jsonb_build_object(
        'operation', v_operation,
        'capacityOverride', COALESCE(p_capacity_override, false),
        'reopenOnlineInventory', p_reopen_online_inventory,
        'warnings', v_warnings
      )
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;

    v_response := jsonb_build_object(
      'ok', true, 'action', v_action, 'reused', false,
      'reservationId', v_reservation.id,
      'entityVersion', v_new_version,
      'boardRevision', v_predicted_revision,
      'auditLogId', v_audit_id,
      'operation', v_operation,
      'tableIds', to_jsonb(v_final_ids),
      'guardBlockId', v_guard_block_id,
      'warnings', v_warnings
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(v_reservation.event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'XX000', MESSAGE = 'VIP floor revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: check_in_admin_reservation_v7(uuid, text, text, text, text, uuid, text)
CREATE FUNCTION public.check_in_admin_reservation_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_reservation reservations%ROWTYPE;
  v_checked_in_at timestamptz := now();
  v_due_at timestamptz;
  v_response jsonb;
BEGIN
  SELECT * INTO v_admin FROM admin_users WHERE id = p_actor_admin_id FOR UPDATE;
  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;
  IF v_admin.role NOT IN ('staff','manager','owner','engineer') THEN
    RAISE EXCEPTION 'admin role cannot check in reservations';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;
    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  SELECT * INTO v_reservation FROM reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND OR v_reservation.status <> 'confirmed' THEN
    RAISE EXCEPTION 'reservation is not confirmed';
  END IF;

  v_due_at := v_checked_in_at + interval '120 minutes';

  UPDATE reservations
  SET status = 'checked_in',
      checked_in_at = v_checked_in_at,
      seat_due_at = v_due_at,
      seat_extended_until_at = v_due_at,
      seat_extension_minutes = 0,
      updated_at = v_checked_in_at
  WHERE id = v_reservation.id;

  INSERT INTO notification_jobs(reservation_id, channel, payload_json)
  VALUES (
    v_reservation.id,
    'line',
    jsonb_build_object(
      'template', 'reservation_checked_in',
      'reservationId', v_reservation.id
    )
  );

  v_response := jsonb_build_object(
    'reservationId', v_reservation.id,
    'checkedInAt', v_checked_in_at,
    'seatDueAt', v_due_at,
    'seatExtendedUntilAt', v_due_at,
    'seatExtensionMinutes', 0
  );

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'reservations', v_reservation.id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'checked_in', 'response', v_response);
END;
$$;

-- FUNCTION: check_in_admin_reservation_v8(uuid, text, text, text, uuid, bigint, timestamp with time zone, text)
CREATE FUNCTION public.check_in_admin_reservation_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_version bigint, p_occurred_at timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation.checked_in';
  v_step jsonb;
  v_reservation public.reservations%ROWTYPE;
  v_assignment record;
  v_release_at timestamptz;
  v_new_version bigint;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_warnings jsonb := '[]'::jsonb;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;
    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(p_actor_admin_id, 'service_status.write'),
      ARRAY['allowed']
    );
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL OR p_occurred_at IS NULL THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'occurredAt')
        )), ARRAY['allowed']
      );
    END IF;
    v_step := public.assert_reservation_version_v8(p_reservation_id, p_expected_version);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
    SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id;
    IF v_reservation.status <> 'confirmed'
      OR v_reservation.service_status IN ('completed', 'no_show')
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION',
          'details', jsonb_build_object('fromStatus', v_reservation.status, 'toStatus', 'checked_in')
        )), ARRAY['allowed']
      );
    END IF;
    v_step := public.resolve_business_day_for_timestamp_v8(p_occurred_at);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['resolved']);
    IF (v_step ->> 'eventDayId')::uuid <> v_reservation.event_day_id THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'occurredAt', 'reason', 'business_day_mismatch')
        )), ARRAY['allowed']
      );
    END IF;
    v_release_at := GREATEST(v_reservation.expected_release_at, p_occurred_at + interval '120 minutes');

    PERFORM sr.id FROM public.seat_resources AS sr
    WHERE EXISTS (
      SELECT 1 FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id
        AND rr.seat_resource_id = sr.id
        AND public.active_reservation_assignment_v8(rr.id, now())
    )
    ORDER BY sr.id FOR UPDATE OF sr;
    PERFORM rr.id FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
       OR (
         rr.seat_resource_id IN (
           SELECT current_rr.seat_resource_id
           FROM public.reservation_resources AS current_rr
           WHERE current_rr.reservation_id = v_reservation.id
             AND public.active_reservation_assignment_v8(current_rr.id, now())
         )
         AND rr.assigned_start_at < v_release_at
         AND rr.assigned_end_at > v_reservation.scheduled_start_at
       )
    ORDER BY rr.id FOR UPDATE OF rr;
    PERFORM rb.id
    FROM public.reservation_blocks AS rb
    WHERE rb.event_day_id = v_reservation.event_day_id
      AND rb.status = 'active'
      AND rb.start_at < v_release_at
      AND rb.end_at > v_reservation.scheduled_start_at
      AND EXISTS (
        SELECT 1
        FROM public.reservation_block_targets AS rbt
        JOIN public.reservation_resources AS rr ON rr.reservation_id = v_reservation.id
        JOIN public.seat_resources AS sr ON sr.id = rr.seat_resource_id
        WHERE rbt.block_id = rb.id
          AND (rbt.seat_resource_id = sr.id OR rbt.floor_section_id = sr.floor_section_id OR rbt.venue_wide)
      )
    ORDER BY rb.id FOR UPDATE OF rb;
    IF NOT EXISTS (
      SELECT 1 FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id
        AND public.active_reservation_assignment_v8(rr.id, now())
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION', 'details', jsonb_build_object('reason', 'active_assignment_required')
        )), ARRAY['allowed']
      );
    END IF;
    FOR v_assignment IN
      SELECT rr.* FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id
        AND public.active_reservation_assignment_v8(rr.id, now())
      ORDER BY rr.id
    LOOP
      v_step := public.assert_assignment_conflict_free_v8(
        v_reservation.event_day_id, v_reservation.id, v_assignment.seat_resource_id,
        v_assignment.assigned_start_at, v_release_at, now()
      );
      PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
      SELECT COALESCE(jsonb_agg(warning ORDER BY warning::text), '[]'::jsonb)
      INTO v_warnings FROM (
        SELECT DISTINCT warning FROM jsonb_array_elements(
          v_warnings || COALESCE(v_step -> 'warnings', '[]'::jsonb)
        ) AS all_warnings(warning)
      ) AS deduplicated;
    END LOOP;

    INSERT INTO public.reservation_assignment_events(
      reservation_id, reservation_resource_id, seat_resource_id, event_type,
      interval_before, interval_after, actor_admin_id, reason, request_id, occurred_at
    )
    SELECT rr.reservation_id, rr.id, rr.seat_resource_id, 'interval_changed',
      jsonb_build_object('startAt', rr.assigned_start_at, 'endAt', rr.assigned_end_at),
      jsonb_build_object('startAt', rr.assigned_start_at, 'endAt', v_release_at),
      p_actor_admin_id, p_reason, p_request_id, p_occurred_at
    FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now())
      AND rr.assigned_end_at IS DISTINCT FROM v_release_at;
    UPDATE public.reservation_resources AS rr
    SET assigned_end_at = v_release_at, version = rr.version + 1, updated_at = now()
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now())
      AND rr.assigned_end_at IS DISTINCT FROM v_release_at;
    IF v_reservation.service_status IS DISTINCT FROM 'seated'::public.vip_service_status THEN
      INSERT INTO public.reservation_service_events(
        reservation_id, from_status, to_status, occurred_at,
        actor_admin_id, reason, request_id, metadata_json
      ) VALUES (
        v_reservation.id, v_reservation.service_status, 'seated', p_occurred_at,
        p_actor_admin_id, p_reason, p_request_id, jsonb_build_object('source', 'check_in')
      );
    END IF;
    UPDATE public.reservations
    SET status = 'checked_in', checked_in_at = p_occurred_at,
        seat_due_at = v_release_at, seat_extended_until_at = v_release_at,
        expected_release_at = v_release_at,
        service_status = 'seated', service_status_changed_at = p_occurred_at,
        arrived_at = COALESCE(arrived_at, p_occurred_at),
        version = version + 1, updated_at = now()
    WHERE id = v_reservation.id RETURNING version INTO v_new_version;

    PERFORM ed.id FROM public.event_days AS ed
    WHERE ed.id = v_reservation.event_day_id FOR KEY SHARE OF ed;
    PERFORM public.lock_vip_floor_day_revision_v32(v_reservation.event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1 INTO v_predicted_revision
    FROM (SELECT 1) AS seed LEFT JOIN public.vip_floor_day_revisions AS vfr
      ON vfr.event_day_id = v_reservation.event_day_id;
    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, v_reservation.event_day_id, v_reservation.id,
      'reservation', v_reservation.id, v_action, p_request_id, p_reason,
      p_expected_version, v_reservation.version, v_new_version,
      ARRAY['status', 'checked_in_at', 'expected_release_at', 'service_status', 'version'],
      jsonb_build_object('status', v_reservation.status, 'serviceStatus', v_reservation.service_status, 'version', v_reservation.version),
      jsonb_build_object('status', 'checked_in', 'serviceStatus', 'seated', 'expectedReleaseAt', v_release_at, 'version', v_new_version),
      jsonb_build_object('occurredAt', p_occurred_at, 'warnings', v_warnings)
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_response := jsonb_build_object(
      'ok', true, 'action', v_action, 'reused', false,
      'reservationId', v_reservation.id, 'entityVersion', v_new_version,
      'boardRevision', v_predicted_revision, 'auditLogId', v_audit_id,
      'checkedInAt', p_occurred_at, 'expectedReleaseAt', v_release_at,
      'warnings', v_warnings
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(v_reservation.event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'XX000', MESSAGE = 'VIP floor revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS v_error_detail = PG_EXCEPTION_DETAIL, v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN RETURN v_error_detail::jsonb; END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: check_public_hold_rate_limit_v7(text, text, text, text, text)
CREATE FUNCTION public.check_public_hold_rate_limit_v7(p_ip_hash text, p_ua_hash text, p_email_hash text, p_phone_hash text, p_request_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_now timestamptz := now();
  v_limited jsonb := NULL;
  v_bucket record;
  v_window_started_at timestamptz;
  v_attempt_count int;
  v_active_hold_count int;
BEGIN
  FOR v_bucket IN
    SELECT * FROM (
      VALUES
        ('ip'::text, p_ip_hash, 600, 20, 0),
        ('ua'::text, p_ua_hash, 600, 60, 0),
        ('email'::text, p_email_hash, 3600, 5, 3),
        ('phone'::text, p_phone_hash, 3600, 5, 3),
        ('request'::text, p_request_hash, 300, 3, 0)
    ) AS buckets(bucket_type, bucket_key_hash, window_seconds, max_attempts, max_active_holds)
    WHERE bucket_key_hash IS NOT NULL
  LOOP
    v_window_started_at := to_timestamp(
      floor(extract(epoch FROM v_now) / v_bucket.window_seconds) * v_bucket.window_seconds
    );

    IF v_bucket.bucket_type = 'email' THEN
      SELECT COUNT(*)::int INTO v_active_hold_count
      FROM customers c
      JOIN reservations r ON r.customer_id = c.id
      WHERE c.email_hash = v_bucket.bucket_key_hash
        AND r.status IN ('pending','pending_card_setup','pending_deposit')
        AND COALESCE(r.hold_expires_at, '-infinity'::timestamptz) > v_now;
    ELSIF v_bucket.bucket_type = 'phone' THEN
      SELECT COUNT(*)::int INTO v_active_hold_count
      FROM customers c
      JOIN reservations r ON r.customer_id = c.id
      WHERE c.phone_hash = v_bucket.bucket_key_hash
        AND r.status IN ('pending','pending_card_setup','pending_deposit')
        AND COALESCE(r.hold_expires_at, '-infinity'::timestamptz) > v_now;
    ELSE
      v_active_hold_count := 0;
    END IF;

    INSERT INTO public_hold_rate_limits(
      bucket_type,
      bucket_key_hash,
      window_started_at,
      window_seconds,
      attempt_count,
      active_hold_count
    )
    VALUES (
      v_bucket.bucket_type,
      v_bucket.bucket_key_hash,
      v_window_started_at,
      v_bucket.window_seconds,
      1,
      v_active_hold_count
    )
    ON CONFLICT (bucket_type, bucket_key_hash, window_started_at, window_seconds)
    DO UPDATE
    SET attempt_count = public_hold_rate_limits.attempt_count + 1,
        active_hold_count = EXCLUDED.active_hold_count,
        updated_at = now()
    RETURNING attempt_count, active_hold_count
    INTO v_attempt_count, v_active_hold_count;

    IF v_limited IS NULL AND (
      v_attempt_count > v_bucket.max_attempts
      OR (
        v_bucket.max_active_holds > 0
        AND v_active_hold_count >= v_bucket.max_active_holds
      )
    ) THEN
      v_limited := jsonb_build_object(
        'allowed', false,
        'bucketType', v_bucket.bucket_type,
        'retryAfterSeconds', GREATEST(
          1,
          v_bucket.window_seconds
            - floor(extract(epoch FROM (v_now - v_window_started_at)))::int
        )
      );
    END IF;
  END LOOP;

  RETURN COALESCE(v_limited, jsonb_build_object('allowed', true));
END;
$$;

-- FUNCTION: claim_email_notification_jobs_v10(uuid, integer, integer)
CREATE FUNCTION public.claim_email_notification_jobs_v10(p_worker_id uuid, p_limit integer DEFAULT 10, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(id uuid, reservation_id uuid, payload_json jsonb, claim_token uuid, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_worker_id IS NULL
    OR p_limit < 1
    OR p_limit > 100
    OR p_lease_seconds < 30
    OR p_lease_seconds > 3600
  THEN
    RAISE EXCEPTION 'invalid email worker claim';
  END IF;

  RETURN QUERY
  WITH claimable AS (
    SELECT nj.id
    FROM public.notification_jobs AS nj
    WHERE nj.channel = 'email'
      AND nj.status IN ('pending', 'retry')
      AND nj.attempt_count < 3
      AND nj.next_attempt_at <= now()
      AND (
        nj.locked_at IS NULL
        OR nj.locked_at < now() - make_interval(secs => p_lease_seconds)
      )
    ORDER BY nj.created_at, nj.id
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  ),
  updated AS (
    UPDATE public.notification_jobs AS nj
    SET status = 'processing',
        locked_by = p_worker_id,
        locked_at = now(),
        claim_token = gen_random_uuid(),
        attempt_count = nj.attempt_count + 1,
        updated_at = now()
    FROM claimable
    WHERE nj.id = claimable.id
    RETURNING nj.*
  )
  SELECT
    updated.id,
    updated.reservation_id,
    updated.payload_json,
    updated.claim_token,
    updated.attempt_count
  FROM updated;
END;
$$;

-- FUNCTION: claim_email_notification_jobs_v11(uuid, integer, integer)
CREATE FUNCTION public.claim_email_notification_jobs_v11(p_worker_id uuid, p_limit integer DEFAULT 10, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(id uuid, reservation_id uuid, waitlist_entry_id uuid, payload_json jsonb, claim_token uuid, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_worker_id IS NULL
    OR p_limit < 1
    OR p_limit > 100
    OR p_lease_seconds < 30
    OR p_lease_seconds > 3600
  THEN
    RAISE EXCEPTION 'invalid email worker claim';
  END IF;

  RETURN QUERY
  WITH claimable AS (
    SELECT nj.id
    FROM public.notification_jobs AS nj
    WHERE nj.channel = 'email'
      AND nj.status IN ('pending', 'retry')
      AND nj.attempt_count < 3
      AND nj.next_attempt_at <= now()
      AND (
        nj.locked_at IS NULL
        OR nj.locked_at < now() - make_interval(secs => p_lease_seconds)
      )
    ORDER BY nj.created_at, nj.id
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  ),
  updated AS (
    UPDATE public.notification_jobs AS nj
    SET status = 'processing',
        locked_by = p_worker_id,
        locked_at = now(),
        claim_token = gen_random_uuid(),
        attempt_count = nj.attempt_count + 1,
        updated_at = now()
    FROM claimable
    WHERE nj.id = claimable.id
    RETURNING nj.*
  )
  SELECT
    updated.id,
    updated.reservation_id,
    updated.waitlist_entry_id,
    updated.payload_json,
    updated.claim_token,
    updated.attempt_count
  FROM updated;
END;
$$;

-- FUNCTION: claim_email_notification_jobs_v25(uuid, integer, integer)
CREATE FUNCTION public.claim_email_notification_jobs_v25(p_worker_id uuid, p_limit integer DEFAULT 10, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(id uuid, reservation_id uuid, waitlist_entry_id uuid, ticket_order_id uuid, payload_json jsonb, claim_token uuid, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_worker_id IS NULL
    OR p_limit < 1 OR p_limit > 100
    OR p_lease_seconds < 30 OR p_lease_seconds > 3600
  THEN
    RAISE EXCEPTION 'invalid email worker claim';
  END IF;

  -- W11 (v75): a row whose first provider request is older than the 23-hour
  -- dedupe horizon can no longer be retried safely — the provider may have
  -- forgotten the idempotency key and a retry would double-send. Sweep those
  -- rows to 'dead' so the boundary is explicit and the item stays visible in
  -- dead-items instead of retrying forever.
  UPDATE public.notification_jobs
  SET status = 'dead',
      error_json = jsonb_build_object('code', 'email_first_send_window_expired'),
      locked_by = NULL,
      locked_at = NULL,
      claim_token = NULL,
      updated_at = now()
  WHERE channel = 'email'
    AND first_send_at <= now() - interval '23 hours'
    AND (
      status IN ('pending', 'retry')
      OR (status = 'processing'
        AND locked_at < now() - make_interval(secs => p_lease_seconds))
    );

  RETURN QUERY
  WITH claimable AS (
    SELECT nj.id
    FROM public.notification_jobs AS nj
    WHERE nj.channel = 'email'
      AND (
        (nj.status IN ('pending', 'retry')
          AND nj.attempt_count < 3
          AND nj.next_attempt_at <= now())
        -- W11 (v75): reclaim a stranded claim whose lease expired.
        OR (nj.status = 'processing'
          AND nj.locked_at < now() - make_interval(secs => p_lease_seconds))
      )
      AND (nj.locked_at IS NULL OR nj.locked_at < now() - make_interval(secs => p_lease_seconds))
      -- W11 (v75): never start a provider request outside the dedupe window.
      AND (nj.first_send_at IS NULL OR nj.first_send_at > now() - interval '23 hours')
    ORDER BY nj.created_at, nj.id
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  ),
  updated AS (
    UPDATE public.notification_jobs AS nj
    SET status = 'processing', locked_by = p_worker_id, locked_at = now(),
        claim_token = gen_random_uuid(), attempt_count = nj.attempt_count + 1,
        -- W11 (v75): durable first-send marker. Rows already attempted before
        -- this column existed keep NULL — their provider acceptance is
        -- unknown, so the worker fails them closed for review.
        first_send_at = COALESCE(nj.first_send_at,
          CASE WHEN nj.attempt_count = 0 THEN now() ELSE NULL END),
        payload_json = nj.payload_json || jsonb_build_object('workerRetryStartedAt',
          CASE
            WHEN nj.payload_json ? 'workerRetryStartedAt' THEN nj.payload_json->>'workerRetryStartedAt'
            WHEN nj.attempt_count = 0 THEN now()::text
            -- Older attempts had no provider retry key: their acceptance is unknown.
            ELSE NULL
          END),
        updated_at = now()
    FROM claimable
    WHERE nj.id = claimable.id
    RETURNING nj.*
  )
  SELECT updated.id, updated.reservation_id, updated.waitlist_entry_id,
         updated.ticket_order_id, updated.payload_json, updated.claim_token,
         updated.attempt_count
  FROM updated;
END;
$$;

-- FUNCTION: claim_notification_jobs_v7(uuid, integer, integer)
CREATE FUNCTION public.claim_notification_jobs_v7(p_worker_id uuid, p_limit integer DEFAULT 10, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(id uuid, reservation_id uuid, channel text, payload_json jsonb, claim_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_worker_id IS NULL OR p_limit IS NULL OR p_limit < 1 OR p_limit > 100
    OR p_lease_seconds IS NULL OR p_lease_seconds < 30 OR p_lease_seconds > 3600 THEN
    RAISE EXCEPTION 'invalid worker claim bounds';
  END IF;
  RETURN QUERY
  WITH claimable AS (
    SELECT nj.id
    FROM notification_jobs nj
    WHERE nj.channel = 'line'
      AND nj.payload_json->>'template' IS DISTINCT FROM 'incident_v1'
      AND (
        (nj.status IN ('pending','retry') AND nj.next_attempt_at <= now())
        OR (nj.status = 'processing'
          AND nj.locked_at < now() - make_interval(secs => p_lease_seconds))
      )
      AND (nj.locked_at IS NULL OR nj.locked_at < now() - make_interval(secs => p_lease_seconds))
    ORDER BY nj.created_at
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  ),
  updated AS (
    UPDATE notification_jobs nj
    SET status = 'processing',
        payload_json = nj.payload_json || jsonb_build_object('workerRetryStartedAt',
          CASE
            WHEN nj.payload_json ? 'workerRetryStartedAt' THEN nj.payload_json->>'workerRetryStartedAt'
            WHEN nj.attempt_count = 0 THEN now()::text
            -- Older attempts had no provider retry key: their acceptance is unknown.
            ELSE NULL
          END),
        locked_by = p_worker_id,
        locked_at = now(),
        claim_token = gen_random_uuid(),
        attempt_count = nj.attempt_count + 1,
        updated_at = now()
    FROM claimable c
    WHERE nj.id = c.id
    RETURNING nj.*
  )
  SELECT updated.id, updated.reservation_id, updated.channel, updated.payload_json, updated.claim_token
  FROM updated;
END;
$$;

-- FUNCTION: claim_off_session_charge_attempts_v7(uuid, integer, integer)
CREATE FUNCTION public.claim_off_session_charge_attempts_v7(p_worker_id uuid, p_limit integer DEFAULT 10, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(id uuid, case_type text, case_id uuid, reservation_id uuid, payment_id uuid, amount_yen integer, currency text, stripe_customer_id text, stripe_payment_method_id text, stripe_account_id text, stripe_idempotency_key text, claim_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_worker_id IS NULL OR p_limit IS NULL OR p_limit < 1 OR p_limit > 100
    OR p_lease_seconds IS NULL OR p_lease_seconds < 30 OR p_lease_seconds > 3600 THEN
    RAISE EXCEPTION 'invalid worker claim bounds';
  END IF;
  RETURN QUERY
  WITH claimable AS (
    SELECT a.id
    FROM off_session_charge_attempts a
    WHERE (
        (a.status = 'approved' AND a.next_attempt_at <= now())
        OR (a.status = 'processing'
          AND a.locked_at < now() - make_interval(secs => p_lease_seconds))
      )
      AND (a.locked_at IS NULL OR a.locked_at < now() - make_interval(secs => p_lease_seconds))
      -- W07-N2 (v75): a charge may only run while its parent case is approved.
      AND (
        (a.case_type = 'no_show' AND EXISTS (
          SELECT 1 FROM no_show_cases c
          WHERE c.id = a.case_id AND c.status = 'approved'))
        OR (a.case_type = 'late_cancel' AND EXISTS (
          SELECT 1 FROM late_cancel_cases c
          WHERE c.id = a.case_id AND c.status = 'approved'))
      )
    ORDER BY a.created_at
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  ),
  updated AS (
    UPDATE off_session_charge_attempts a
    SET status = 'processing',
        provider_request_started_at = COALESCE(a.provider_request_started_at, now()),
        locked_by = p_worker_id,
        locked_at = now(),
        claim_token = gen_random_uuid(),
        attempt_count = a.attempt_count + 1,
        updated_at = now()
    FROM claimable c
    WHERE a.id = c.id
    RETURNING a.*
  )
  SELECT updated.id, updated.case_type, updated.case_id, updated.reservation_id, updated.payment_id,
         updated.amount_yen, updated.currency, updated.stripe_customer_id,
         updated.stripe_payment_method_id, updated.stripe_account_id,
         updated.stripe_idempotency_key, updated.claim_token
  FROM updated;
END;
$$;

-- FUNCTION: claim_refund_cases_v7(uuid, integer, integer)
CREATE FUNCTION public.claim_refund_cases_v7(p_worker_id uuid, p_limit integer DEFAULT 10, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(id uuid, reservation_id uuid, payment_id uuid, amount_yen integer, currency text, stripe_payment_intent_id text, stripe_charge_id text, stripe_account_id text, stripe_idempotency_key text, claim_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_worker_id IS NULL OR p_limit IS NULL OR p_limit < 1 OR p_limit > 100
    OR p_lease_seconds IS NULL OR p_lease_seconds < 30 OR p_lease_seconds > 3600 THEN
    RAISE EXCEPTION 'invalid worker claim bounds';
  END IF;
  RETURN QUERY
  WITH claimable AS (
    SELECT rc.id
    FROM refund_cases rc
    WHERE (
        (rc.status = 'approved' AND rc.next_attempt_at <= now())
        OR (rc.status = 'processing'
          AND rc.locked_at < now() - make_interval(secs => p_lease_seconds))
      )
      AND (rc.locked_at IS NULL OR rc.locked_at < now() - make_interval(secs => p_lease_seconds))
    ORDER BY rc.created_at
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  ),
  updated AS (
    UPDATE refund_cases rc
    SET status = 'processing',
        provider_request_started_at = COALESCE(rc.provider_request_started_at, now()),
        locked_by = p_worker_id,
        locked_at = now(),
        claim_token = gen_random_uuid(),
        attempt_count = rc.attempt_count + 1,
        updated_at = now()
    FROM claimable c
    WHERE rc.id = c.id
    RETURNING rc.*
  )
  SELECT updated.id, updated.reservation_id, updated.payment_id, updated.amount_yen,
         updated.currency, p.provider_object_id, p.stripe_charge_id, updated.stripe_account_id,
         updated.stripe_idempotency_key, updated.claim_token
  FROM updated
  JOIN payments p ON p.id = updated.payment_id;
END;
$$;

-- FUNCTION: claim_reservation_hold_finalizers_v7(uuid, integer, integer)
CREATE FUNCTION public.claim_reservation_hold_finalizers_v7(p_worker_id uuid, p_limit integer DEFAULT 10, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(id uuid, reservation_id uuid, payment_id uuid, source_system text, idempotency_key text, request_hash text, stripe_idempotency_key text, provider_object_type text, provider_object_id text, stripe_account_id text, claim_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH claimable AS (
    SELECT rhr.id
    FROM reservation_hold_requests rhr
    WHERE rhr.status IN ('stripe_create_in_progress','stripe_unknown','stripe_created','finalize_retry')
      AND COALESCE(rhr.next_attempt_at, now()) <= now()
      AND (
        rhr.locked_at IS NULL
        OR rhr.locked_at < now() - make_interval(secs => p_lease_seconds)
      )
      AND (
        rhr.status IN ('stripe_unknown','stripe_created','finalize_retry')
        OR rhr.updated_at < now() - make_interval(secs => p_lease_seconds)
      )
    ORDER BY rhr.updated_at
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  ),
  updated AS (
    UPDATE reservation_hold_requests rhr
    SET status = 'finalize_retry',
        locked_by = p_worker_id,
        locked_at = now(),
        claim_token = gen_random_uuid(),
        finalize_attempts = rhr.finalize_attempts + 1,
        updated_at = now()
    FROM claimable c
    WHERE rhr.id = c.id
    RETURNING rhr.*
  )
  SELECT updated.id,
         updated.reservation_id,
         p.id AS payment_id,
         updated.source_system,
         updated.idempotency_key,
         updated.request_hash,
         updated.stripe_idempotency_key,
         updated.provider_object_type,
         updated.provider_object_id,
         p.stripe_account_id,
         updated.claim_token
  FROM updated
  JOIN LATERAL (
    SELECT payments.id, payments.stripe_account_id
    FROM payments
    WHERE payments.reservation_id = updated.reservation_id
    ORDER BY payments.created_at DESC
    LIMIT 1
  ) p ON true;
END;
$$;

-- FUNCTION: claim_ticket_checkout_action_v28(text, text, text, text, uuid, text, boolean, text, text, text, date, text, integer, integer, jsonb)
CREATE FUNCTION public.claim_ticket_checkout_action_v28(p_environment text, p_stripe_account_id text, p_idempotency_key_hash text, p_request_hash text, p_event_session_id uuid, p_check_in_mode text, p_wallet_readiness_valid boolean, p_public_code text, p_event_id text, p_event_slug text, p_event_date date, p_event_title text, p_amount_yen integer, p_total_quantity integer, p_items_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_action public.ticket_checkout_actions%ROWTYPE;
  v_event_day_id uuid;
  v_event_day public.event_days%ROWTYPE;
  v_session public.ticket_event_sessions%ROWTYPE;
  v_order public.ticket_orders%ROWTYPE;
  v_action_id uuid := gen_random_uuid();
  v_provider_key text;
  v_inserted integer := 0;
  v_declared_quantity integer;
  v_bad_item integer;
BEGIN
  IF COALESCE(p_environment, '') NOT IN ('test', 'live')
    OR NULLIF(btrim(COALESCE(p_idempotency_key_hash, '')), '') IS NULL
    OR char_length(btrim(p_idempotency_key_hash)) > 200
    OR NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL
    OR char_length(btrim(p_request_hash)) > 200
    OR p_event_session_id IS NULL
    OR COALESCE(p_check_in_mode, '') NOT IN ('legacy_qr', 'wallet_swipe')
    OR p_wallet_readiness_valid IS NULL
    OR NULLIF(btrim(COALESCE(p_event_id, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_event_slug, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_event_title, '')), '') IS NULL
    OR p_event_date IS NULL
    OR p_amount_yen IS NULL OR p_amount_yen < 0
    OR p_total_quantity IS NULL OR p_total_quantity < 1 OR p_total_quantity > 20
    OR p_items_json IS NULL OR jsonb_typeof(p_items_json) <> 'array'
    OR jsonb_array_length(p_items_json) = 0
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'checkout_input_invalid');
  END IF;

  SELECT
    COALESCE(sum(CASE WHEN item ->> 'quantity' ~ '^[1-9][0-9]*$'
      THEN (item ->> 'quantity')::integer ELSE 0 END), 0),
    count(*) FILTER (
      WHERE item ->> 'quantity' !~ '^[1-9][0-9]*$'
        OR item ->> 'ticketTypeId' IS NULL
        OR item ->> 'unitPriceYen' !~ '^[0-9]+$'
    )
  INTO v_declared_quantity, v_bad_item
  FROM jsonb_array_elements(p_items_json) AS item;
  IF v_bad_item > 0 OR v_declared_quantity <> p_total_quantity THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'checkout_items_invalid');
  END IF;

  -- Existing action is the first lock and wins over later policy changes. This
  -- is what makes a retry after draining return the already-created obligation.
  SELECT * INTO v_action
  FROM public.ticket_checkout_actions
  WHERE environment = p_environment
    AND stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
    AND idempotency_key_hash = btrim(p_idempotency_key_hash)
  FOR UPDATE;
  IF FOUND THEN
    IF v_action.request_hash <> btrim(p_request_hash) THEN
      RETURN jsonb_build_object(
        'action', 'conflict', 'reason', 'idempotency_request_hash_mismatch',
        'checkoutActionId', v_action.id, 'orderId', v_action.ticket_order_id);
    END IF;
    SELECT * INTO v_order
    FROM public.ticket_orders
    WHERE id = v_action.ticket_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object(
        'action', 'rejected', 'reason', 'checkout_order_missing',
        'checkoutActionId', v_action.id);
    END IF;
    RETURN jsonb_build_object(
      'action', 'reused', 'checkoutActionId', v_action.id,
      'orderId', v_action.ticket_order_id,
      'publicCode', v_order.public_code,
      'providerIdempotencyKey', v_action.provider_idempotency_key,
      'state', v_action.state,
      'checkoutSessionId', v_action.checkout_session_id,
      'checkInMode', v_action.check_in_mode,
      'providerRequestVersion', v_action.provider_request_version,
      'providerRequestOrigin', v_action.provider_request_origin,
      'providerRequestCreatedAt', CASE WHEN v_action.provider_request_created_at IS NULL
        THEN NULL ELSE to_char(v_action.provider_request_created_at AT TIME ZONE 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
      'providerRequestHash', v_action.provider_request_hash,
      'createdAt', to_char(
        v_action.created_at AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
    );
  END IF;

  SELECT session.event_day_id INTO v_event_day_id
  FROM public.ticket_event_sessions AS session
  WHERE session.id = p_event_session_id;
  IF v_event_day_id IS NULL THEN
    RETURN jsonb_build_object('action', 'not_found', 'reason', 'event_session_not_found');
  END IF;

  v_provider_key := 'ghost-ticket-checkout-v28-' || v_action_id::text;
  INSERT INTO public.ticket_checkout_actions(
    id, event_session_id, environment, stripe_account_id, check_in_mode,
    idempotency_key_hash, request_hash, provider_idempotency_key, state
  ) VALUES (
    v_action_id, p_event_session_id, p_environment, p_stripe_account_id,
    p_check_in_mode, btrim(p_idempotency_key_hash), btrim(p_request_hash),
    v_provider_key, 'initializing'
  )
  ON CONFLICT ON CONSTRAINT uq_ticket_checkout_actions_public_key_v28 DO NOTHING
  RETURNING * INTO v_action;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  IF v_inserted = 0 THEN
    SELECT * INTO v_action
    FROM public.ticket_checkout_actions
    WHERE environment = p_environment
      AND stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND idempotency_key_hash = btrim(p_idempotency_key_hash)
    FOR UPDATE;
    IF v_action.request_hash <> btrim(p_request_hash) THEN
      RETURN jsonb_build_object(
        'action', 'conflict', 'reason', 'idempotency_request_hash_mismatch',
        'checkoutActionId', v_action.id, 'orderId', v_action.ticket_order_id);
    END IF;
    SELECT * INTO v_order
    FROM public.ticket_orders
    WHERE id = v_action.ticket_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object(
        'action', 'rejected', 'reason', 'checkout_order_missing',
        'checkoutActionId', v_action.id);
    END IF;
    RETURN jsonb_build_object(
      'action', 'reused', 'checkoutActionId', v_action.id,
      'orderId', v_action.ticket_order_id,
      'publicCode', v_order.public_code,
      'providerIdempotencyKey', v_action.provider_idempotency_key,
      'state', v_action.state,
      'checkoutSessionId', v_action.checkout_session_id,
      'checkInMode', v_action.check_in_mode,
      'providerRequestVersion', v_action.provider_request_version,
      'providerRequestOrigin', v_action.provider_request_origin,
      'providerRequestCreatedAt', CASE WHEN v_action.provider_request_created_at IS NULL
        THEN NULL ELSE to_char(v_action.provider_request_created_at AT TIME ZONE 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
      'providerRequestHash', v_action.provider_request_hash,
      'createdAt', to_char(
        v_action.created_at AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
    );
  END IF;

  SELECT * INTO v_event_day
  FROM public.event_days
  WHERE id = v_event_day_id
  FOR NO KEY UPDATE;
  SELECT * INTO v_session
  FROM public.ticket_event_sessions
  WHERE id = p_event_session_id
    AND event_day_id = v_event_day.id
  FOR NO KEY UPDATE;

  IF v_session.environment <> p_environment
    OR v_session.stripe_account_key <> COALESCE(p_stripe_account_id, 'platform')
  THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'checkout_scope_mismatch');
  END IF;
  IF v_session.catalog_event_id <> p_event_id
    OR v_session.event_date <> p_event_date
    OR v_event_day.business_date <> p_event_date
  THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'event_binding_mismatch');
  END IF;
  IF v_event_day.operating_status <> 'open' THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'event_day_closed');
  END IF;
  IF clock_timestamp() < v_event_day.sales_open_at
    OR clock_timestamp() >= v_event_day.sales_close_at
  THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'sales_window_closed');
  END IF;
  IF NOT v_session.enabled THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'event_session_disabled');
  END IF;
  IF v_session.sales_state <> 'active' THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'sales_not_active');
  END IF;
  IF v_session.admission_state <> 'scheduled' THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'admission_not_scheduled');
  END IF;
  IF v_session.sales_check_in_mode <> p_check_in_mode THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'check_in_mode_mismatch');
  END IF;
  IF p_check_in_mode = 'wallet_swipe' AND NOT p_wallet_readiness_valid THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'wallet_readiness_required');
  END IF;
  IF EXISTS (SELECT 1 FROM public.ticket_orders WHERE public_code = p_public_code) THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'conflict', 'reason', 'public_code_conflict');
  END IF;

  INSERT INTO public.ticket_orders(
    public_code, event_id, event_slug, event_date, event_title,
    status, environment, stripe_account_id, amount_yen, currency,
    total_quantity, items_json, event_session_id, check_in_mode
  ) VALUES (
    p_public_code, p_event_id, p_event_slug, p_event_date, p_event_title,
    'pending', p_environment, p_stripe_account_id, p_amount_yen, 'jpy',
    p_total_quantity, p_items_json, v_session.id, p_check_in_mode
  ) RETURNING * INTO v_order;

  UPDATE public.ticket_checkout_actions
  SET ticket_order_id = v_order.id,
      state = 'claimed',
      -- Give the in-request Stripe call a short head start. Recovery owns the
      -- obligation after this grace period, including response-loss failures.
      recovery_next_attempt_at = clock_timestamp() + interval '2 minutes',
      updated_at = now()
  WHERE id = v_action.id
  RETURNING * INTO v_action;

  RETURN jsonb_build_object(
    'action', 'claimed', 'checkoutActionId', v_action.id,
    'orderId', v_order.id, 'publicCode', v_order.public_code,
    'providerIdempotencyKey', v_action.provider_idempotency_key,
    'state', v_action.state, 'checkInMode', v_action.check_in_mode,
    'eventSessionId', v_action.event_session_id,
    'providerRequestVersion', v_action.provider_request_version,
    'providerRequestOrigin', v_action.provider_request_origin,
    'providerRequestCreatedAt', NULL,
    'providerRequestHash', v_action.provider_request_hash,
    'createdAt', to_char(
      v_action.created_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  );
END;
$_$;

-- FUNCTION: claim_ticket_checkout_action_v33(text, text, text, text, uuid, text, boolean, text, text, text, date, text, integer, integer, jsonb)
CREATE FUNCTION public.claim_ticket_checkout_action_v33(p_environment text, p_stripe_account_id text, p_idempotency_key_hash text, p_request_hash text, p_event_session_id uuid, p_check_in_mode text, p_wallet_readiness_valid boolean, p_public_code text, p_event_id text, p_event_slug text, p_event_date date, p_event_title text, p_amount_yen integer, p_total_quantity integer, p_items_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_action public.ticket_checkout_actions%ROWTYPE;
  v_event_day_id uuid;
  v_event_day public.event_days%ROWTYPE;
  v_session public.ticket_event_sessions%ROWTYPE;
  v_order public.ticket_orders%ROWTYPE;
  v_action_id uuid := gen_random_uuid();
  v_provider_key text;
  v_inserted integer := 0;
  v_declared_quantity integer;
  v_bad_item integer;
  v_publication public.ticket_sale_publications%ROWTYPE;
  v_sales_close timestamptz;
  v_provider_expiry timestamptz;
  v_reserved bigint;
BEGIN
  IF COALESCE(p_environment, '') NOT IN ('test', 'live')
    OR NULLIF(btrim(COALESCE(p_idempotency_key_hash, '')), '') IS NULL
    OR char_length(btrim(p_idempotency_key_hash)) > 200
    OR NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL
    OR char_length(btrim(p_request_hash)) > 200
    OR p_event_session_id IS NULL
    OR COALESCE(p_check_in_mode, '') NOT IN ('legacy_qr', 'wallet_swipe')
    OR p_wallet_readiness_valid IS NULL
    OR NULLIF(btrim(COALESCE(p_event_id, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_event_slug, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_event_title, '')), '') IS NULL
    OR p_event_date IS NULL
    OR p_amount_yen IS NULL OR p_amount_yen < 0
    OR p_total_quantity IS NULL OR p_total_quantity < 1 OR p_total_quantity > 20
    OR p_items_json IS NULL OR jsonb_typeof(p_items_json) <> 'array'
    OR jsonb_array_length(p_items_json) = 0
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'checkout_input_invalid');
  END IF;

  SELECT
    COALESCE(sum(CASE WHEN item ->> 'quantity' ~ '^[1-9][0-9]*$'
      THEN (item ->> 'quantity')::integer ELSE 0 END), 0),
    count(*) FILTER (
      WHERE item ->> 'quantity' !~ '^[1-9][0-9]*$'
        OR item ->> 'ticketTypeId' IS NULL
        OR item ->> 'unitPriceYen' !~ '^[0-9]+$'
    )
  INTO v_declared_quantity, v_bad_item
  FROM jsonb_array_elements(p_items_json) AS item;
  IF v_bad_item > 0 OR v_declared_quantity <> p_total_quantity THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'checkout_items_invalid');
  END IF;

  -- Existing action is the first lock and wins over later policy changes. This
  -- is what makes a retry after draining return the already-created obligation.
  SELECT * INTO v_action
  FROM public.ticket_checkout_actions
  WHERE environment = p_environment
    AND stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
    AND idempotency_key_hash = btrim(p_idempotency_key_hash)
  FOR UPDATE;
  IF FOUND THEN
    IF v_action.request_hash <> btrim(p_request_hash) THEN
      RETURN jsonb_build_object(
        'action', 'conflict', 'reason', 'idempotency_request_hash_mismatch',
        'checkoutActionId', v_action.id, 'orderId', v_action.ticket_order_id);
    END IF;
    SELECT * INTO v_order
    FROM public.ticket_orders
    WHERE id = v_action.ticket_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object(
        'action', 'rejected', 'reason', 'checkout_order_missing',
        'checkoutActionId', v_action.id);
    END IF;
    RETURN jsonb_build_object(
      'action', 'reused', 'checkoutActionId', v_action.id,
      'orderId', v_action.ticket_order_id,
      'publicCode', v_order.public_code,
      'checkoutExpiresAt',v_order.checkout_expires_at,
      'providerIdempotencyKey', v_action.provider_idempotency_key,
      'state', v_action.state,
      'checkoutSessionId', v_action.checkout_session_id,
      'checkInMode', v_action.check_in_mode,
      'providerRequestVersion', v_action.provider_request_version,
      'providerRequestOrigin', v_action.provider_request_origin,
      'providerRequestCreatedAt', CASE WHEN v_action.provider_request_created_at IS NULL
        THEN NULL ELSE to_char(v_action.provider_request_created_at AT TIME ZONE 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
      'providerRequestHash', v_action.provider_request_hash,
      'createdAt', to_char(
        v_action.created_at AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
    );
  END IF;

  SELECT session.event_day_id INTO v_event_day_id
  FROM public.ticket_event_sessions AS session
  WHERE session.id = p_event_session_id;
  IF v_event_day_id IS NULL THEN
    RETURN jsonb_build_object('action', 'not_found', 'reason', 'event_session_not_found');
  END IF;

  v_provider_key := 'ghost-ticket-checkout-v28-' || v_action_id::text;
  INSERT INTO public.ticket_checkout_actions(
    id, event_session_id, environment, stripe_account_id, check_in_mode,
    idempotency_key_hash, request_hash, provider_idempotency_key, state
  ) VALUES (
    v_action_id, p_event_session_id, p_environment, p_stripe_account_id,
    p_check_in_mode, btrim(p_idempotency_key_hash), btrim(p_request_hash),
    v_provider_key, 'initializing'
  )
  ON CONFLICT ON CONSTRAINT uq_ticket_checkout_actions_public_key_v28 DO NOTHING
  RETURNING * INTO v_action;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  IF v_inserted = 0 THEN
    SELECT * INTO v_action
    FROM public.ticket_checkout_actions
    WHERE environment = p_environment
      AND stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND idempotency_key_hash = btrim(p_idempotency_key_hash)
    FOR UPDATE;
    IF v_action.request_hash <> btrim(p_request_hash) THEN
      RETURN jsonb_build_object(
        'action', 'conflict', 'reason', 'idempotency_request_hash_mismatch',
        'checkoutActionId', v_action.id, 'orderId', v_action.ticket_order_id);
    END IF;
    SELECT * INTO v_order
    FROM public.ticket_orders
    WHERE id = v_action.ticket_order_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object(
        'action', 'rejected', 'reason', 'checkout_order_missing',
        'checkoutActionId', v_action.id);
    END IF;
    RETURN jsonb_build_object(
      'action', 'reused', 'checkoutActionId', v_action.id,
      'orderId', v_action.ticket_order_id,
      'publicCode', v_order.public_code,
      'checkoutExpiresAt',v_order.checkout_expires_at,
      'providerIdempotencyKey', v_action.provider_idempotency_key,
      'state', v_action.state,
      'checkoutSessionId', v_action.checkout_session_id,
      'checkInMode', v_action.check_in_mode,
      'providerRequestVersion', v_action.provider_request_version,
      'providerRequestOrigin', v_action.provider_request_origin,
      'providerRequestCreatedAt', CASE WHEN v_action.provider_request_created_at IS NULL
        THEN NULL ELSE to_char(v_action.provider_request_created_at AT TIME ZONE 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
      'providerRequestHash', v_action.provider_request_hash,
      'createdAt', to_char(
        v_action.created_at AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
    );
  END IF;

  SELECT * INTO v_event_day
  FROM public.event_days
  WHERE id = v_event_day_id
  FOR NO KEY UPDATE;
  SELECT * INTO v_session
  FROM public.ticket_event_sessions
  WHERE id = p_event_session_id
    AND event_day_id = v_event_day.id
  FOR NO KEY UPDATE;

  IF v_session.environment <> p_environment
    OR v_session.stripe_account_key <> COALESCE(p_stripe_account_id, 'platform')
  THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'checkout_scope_mismatch');
  END IF;
  IF v_session.catalog_event_id <> p_event_id
    OR v_session.event_date <> p_event_date
    OR v_event_day.business_date <> p_event_date
  THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'event_binding_mismatch');
  END IF;
  IF v_event_day.operating_status <> 'open' THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'event_day_closed');
  END IF;
  IF NOT v_session.enabled THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'event_session_disabled');
  END IF;
  IF v_session.sales_state <> 'active' THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'sales_not_active');
  END IF;
  IF v_session.admission_state <> 'scheduled' THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'admission_not_scheduled');
  END IF;
  IF v_session.sales_check_in_mode <> p_check_in_mode THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'check_in_mode_mismatch');
  END IF;
  SELECT * INTO v_publication FROM public.ticket_sale_publications WHERE event_session_id=v_session.id FOR UPDATE;
  IF clock_timestamp() < COALESCE(v_publication.sales_launch_at,v_event_day.sales_open_at)
    OR clock_timestamp() >= v_event_day.sales_close_at
  THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'sales_window_closed');
  END IF;
  IF NOT FOUND OR NOT v_publication.published OR v_publication.inventory_mode='pending' THEN
    DELETE FROM public.ticket_checkout_actions WHERE id=v_action.id;
    RETURN jsonb_build_object('action','rejected','reason','ticket_sales_preparing');
  END IF;
  IF p_event_date < (clock_timestamp() AT TIME ZONE 'Asia/Tokyo')::date
    OR p_event_date > ((clock_timestamp() AT TIME ZONE 'Asia/Tokyo')::date+interval '1 month')::date THEN
    DELETE FROM public.ticket_checkout_actions WHERE id=v_action.id;
    RETURN jsonb_build_object('action','rejected','reason','event_outside_public_window');
  END IF;
  PERFORM 1 FROM public.ticket_sale_products WHERE event_session_id=v_session.id ORDER BY ticket_type_id FOR SHARE;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_items_json) item LEFT JOIN public.ticket_sale_products t
    ON t.event_session_id=v_session.id AND t.ticket_type_id=item->>'ticketTypeId'
    WHERE t.ticket_type_id IS NULL OR NOT t.enabled OR t.price_yen<>(item->>'unitPriceYen')::integer
      OR t.label_en IS DISTINCT FROM item->>'label')
    OR p_amount_yen<>(SELECT sum((item->>'quantity')::integer*(item->>'unitPriceYen')::integer) FROM jsonb_array_elements(p_items_json) item)
    OR (SELECT count(*) FROM jsonb_array_elements(p_items_json))<>(SELECT count(DISTINCT item->>'ticketTypeId') FROM jsonb_array_elements(p_items_json) item) THEN
    DELETE FROM public.ticket_checkout_actions WHERE id=v_action.id;
    RETURN jsonb_build_object('action','rejected','reason','ticket_product_changed');
  END IF;
  SELECT LEAST(v_event_day.sales_close_at,min(t.sales_close_at)) INTO v_sales_close FROM public.ticket_sale_products t
    JOIN jsonb_array_elements(p_items_json) item ON t.ticket_type_id=item->>'ticketTypeId' WHERE t.event_session_id=v_session.id;
  -- Close new-session creation 31 minutes before payment deadline: Stripe needs
  -- at least 30 minutes; one minute leaves bounded network/clock headroom.
  IF v_sales_close IS NULL OR v_sales_close<=clock_timestamp()+interval '31 minutes' THEN
    DELETE FROM public.ticket_checkout_actions WHERE id=v_action.id;
    RETURN jsonb_build_object('action','rejected','reason','ticket_checkout_deadline');
  END IF;
  v_provider_expiry:=date_trunc('second',LEAST(v_sales_close,clock_timestamp()+interval '23 hours'));
  IF v_publication.inventory_mode='finite' THEN
    SELECT COALESCE(sum(o.total_quantity),0) INTO v_reserved FROM public.ticket_orders o
    LEFT JOIN public.ticket_checkout_actions a ON a.ticket_order_id=o.id WHERE o.event_session_id=v_session.id
    -- W09 G-19 residual (v75): session-less terminal unpaid orders no longer
    -- pin capacity; see the migration header for the full release contract.
    AND NOT COALESCE((o.status IN ('expired','cancelled') AND o.paid_at IS NULL AND o.provider_paid_at IS NULL
      AND (a.provider_terminal_status='expired'
           OR (a.checkout_session_id IS NULL AND o.checkout_session_id IS NULL AND a.state IS DISTINCT FROM 'review_required'))
      AND NOT EXISTS(SELECT 1 FROM public.ticket_admissions ad WHERE ad.ticket_order_id=o.id AND ad.status<>'void')),false);
    IF v_reserved+p_total_quantity>v_publication.capacity THEN
      DELETE FROM public.ticket_checkout_actions WHERE id=v_action.id;
      RETURN jsonb_build_object('action','rejected','reason','ticket_sold_out');
    END IF;
  END IF;
  IF p_check_in_mode = 'wallet_swipe' AND NOT p_wallet_readiness_valid THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'wallet_readiness_required');
  END IF;
  IF EXISTS (SELECT 1 FROM public.ticket_orders WHERE public_code = p_public_code) THEN
    DELETE FROM public.ticket_checkout_actions WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'conflict', 'reason', 'public_code_conflict');
  END IF;

  INSERT INTO public.ticket_orders(
    public_code, event_id, event_slug, event_date, event_title,
    status, environment, stripe_account_id, amount_yen, currency,
    total_quantity, items_json, event_session_id, check_in_mode, checkout_expires_at, sales_close_at_snapshot
  ) VALUES (
    p_public_code, p_event_id, p_event_slug, p_event_date, p_event_title,
    'pending', p_environment, p_stripe_account_id, p_amount_yen, 'jpy',
    p_total_quantity, p_items_json, v_session.id, p_check_in_mode, v_provider_expiry, v_sales_close
  ) RETURNING * INTO v_order;

  UPDATE public.ticket_checkout_actions
  SET ticket_order_id = v_order.id,
      state = 'claimed',
      -- Give the in-request Stripe call a short head start. Recovery owns the
      -- obligation after this grace period, including response-loss failures.
      recovery_next_attempt_at = clock_timestamp() + interval '2 minutes',
      updated_at = now()
  WHERE id = v_action.id
  RETURNING * INTO v_action;

  RETURN jsonb_build_object(
    'action', 'claimed', 'checkoutActionId', v_action.id,
    'orderId', v_order.id, 'publicCode', v_order.public_code,
      'checkoutExpiresAt',v_order.checkout_expires_at,
    'providerIdempotencyKey', v_action.provider_idempotency_key,
    'state', v_action.state, 'checkInMode', v_action.check_in_mode,
    'eventSessionId', v_action.event_session_id,
    'providerRequestVersion', v_action.provider_request_version,
    'providerRequestOrigin', v_action.provider_request_origin,
    'providerRequestCreatedAt', NULL,
    'providerRequestHash', v_action.provider_request_hash,
    'createdAt', to_char(
      v_action.created_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  );
END;
$_$;

-- FUNCTION: claim_ticket_checkout_action_v36(text, text, text, text, uuid, text, boolean, text, text, text, date, text, integer, integer, jsonb, text)
CREATE FUNCTION public.claim_ticket_checkout_action_v36(p_environment text, p_stripe_account_id text, p_idempotency_key_hash text, p_request_hash text, p_event_session_id uuid, p_check_in_mode text, p_wallet_readiness_valid boolean, p_public_code text, p_event_id text, p_event_slug text, p_event_date date, p_event_title text, p_amount_yen integer, p_total_quantity integer, p_items_json jsonb, p_browser_verifier text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE r jsonb; v text;
BEGIN
 IF p_browser_verifier IS NULL OR p_browser_verifier !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('action','rejected','reason','purchase_browser_required'); END IF;
 PERFORM set_config('ghost.ticket_purchase_browser_v47',p_browser_verifier,true);
 r:=public.claim_ticket_checkout_action_v33(p_environment,p_stripe_account_id,p_idempotency_key_hash,p_request_hash,p_event_session_id,p_check_in_mode,p_wallet_readiness_valid,p_public_code,p_event_id,p_event_slug,p_event_date,p_event_title,p_amount_yen,p_total_quantity,p_items_json);
 IF r->>'action'='claimed' THEN
  INSERT INTO public.ticket_purchase_browser_bindings(checkout_action_id,browser_verifier) VALUES((r->>'checkoutActionId')::uuid,p_browser_verifier);
 ELSIF r->>'action'='reused' THEN
  SELECT browser_verifier INTO v FROM public.ticket_purchase_browser_bindings WHERE checkout_action_id=(r->>'checkoutActionId')::uuid AND expires_at>clock_timestamp();
  IF v IS DISTINCT FROM p_browser_verifier THEN RETURN jsonb_build_object('action','rejected','reason','purchase_browser_mismatch'); END IF;
 END IF;
 RETURN r;
END; $_$;

-- FUNCTION: claim_ticket_checkout_recovery_batch_v28(text, integer, integer)
CREATE FUNCTION public.claim_ticket_checkout_recovery_batch_v28(p_worker_id text, p_limit integer, p_lease_seconds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_jobs jsonb;
BEGIN
  IF NULLIF(btrim(COALESCE(p_worker_id, '')), '') IS NULL
    OR char_length(p_worker_id) > 120
    OR p_worker_id !~ '^[a-zA-Z0-9:_-]+$'
    OR NOT (p_limit BETWEEN 1 AND 25)
    OR NOT (p_lease_seconds BETWEEN 15 AND 120)
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'recovery_claim_input_invalid');
  END IF;

  WITH candidates AS (
    SELECT action.id
    FROM public.ticket_checkout_actions AS action
    WHERE action.state IN ('claimed', 'provider_created')
      AND (
        action.recovery_next_attempt_at <= v_now
        OR EXISTS (SELECT 1 FROM public.ticket_orders o JOIN public.ticket_event_sessions es ON es.id=o.event_session_id JOIN public.event_days d ON d.id=es.event_day_id WHERE o.id=action.ticket_order_id AND o.sales_close_at_snapshot IS NOT NULL AND (o.sales_close_at_snapshot<=v_now OR d.operating_status<>'open' OR NOT es.enabled OR es.sales_state<>'active' OR es.admission_state IN ('closed','cancelled') OR es.close_at<=v_now))
        OR (
          action.state = 'provider_created'
          AND action.recovery_last_outcome = 'provider_created'
          AND action.updated_at < v_now - interval '15 minutes'
        )
      )
      AND (
        action.recovery_claim_token IS NULL
        OR action.recovery_claim_expires_at <= v_now
      )
      AND EXISTS (
        SELECT 1 FROM public.ticket_orders AS ticket_order
        WHERE ticket_order.id = action.ticket_order_id
          AND (
            ticket_order.status = 'pending'
            OR (
              -- W09 G-19: a cancelled or swept-expired order whose provider
              -- session was created but never terminally evidenced may still
              -- be claimed for reconciliation. Evidence collection only --
              -- expire_ticket_checkout_action_verified_v28 still requires
              -- literal Stripe expired+unpaid authority and never transitions
              -- a non-pending order.
              ticket_order.status IN ('cancelled', 'expired')
              AND action.state = 'provider_created'
              AND action.provider_terminal_status IS NULL
            )
          )
      )
    ORDER BY action.recovery_next_attempt_at, action.created_at, action.id
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  ), claimed AS (
    UPDATE public.ticket_checkout_actions AS action
    SET recovery_claim_token = gen_random_uuid(),
        recovery_claimed_by = btrim(p_worker_id),
        recovery_claimed_at = v_now,
        recovery_claim_expires_at =
          v_now + make_interval(secs => p_lease_seconds),
        recovery_attempt_count = action.recovery_attempt_count + 1,
        updated_at = now()
    FROM candidates
    WHERE action.id = candidates.id
    RETURNING action.*
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'checkoutActionId', action.id,
    'recoveryClaimToken', action.recovery_claim_token,
    'orderId', ticket_order.id,
    'eventSessionId', action.event_session_id,
    'checkoutExpiresAt', ticket_order.checkout_expires_at,
    'shouldExpire', EXISTS (SELECT 1 FROM public.ticket_orders o JOIN public.ticket_event_sessions es ON es.id=o.event_session_id JOIN public.event_days d ON d.id=es.event_day_id WHERE o.id=ticket_order.id AND o.sales_close_at_snapshot IS NOT NULL AND (o.sales_close_at_snapshot<=v_now OR d.operating_status<>'open' OR NOT es.enabled OR es.sales_state<>'active' OR es.admission_state IN ('closed','cancelled') OR es.close_at<=v_now)),
    'environment', action.environment,
    'stripeAccountId', action.stripe_account_id,
    'checkInMode', action.check_in_mode,
    'requestHash', action.request_hash,
    'providerIdempotencyKey', action.provider_idempotency_key,
    'state', action.state,
    'checkoutSessionId', action.checkout_session_id,
    'providerExpiresAt', CASE WHEN action.provider_expires_at IS NULL
      THEN NULL ELSE to_char(action.provider_expires_at AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
    'createdAt', to_char(action.created_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'providerRequestVersion', action.provider_request_version,
    'providerRequestOrigin', action.provider_request_origin,
    'providerRequestCreatedAt', CASE WHEN action.provider_request_created_at IS NULL
      THEN NULL ELSE to_char(action.provider_request_created_at AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
    'providerRequestHash', action.provider_request_hash,
    'recoveryAttemptCount', action.recovery_attempt_count,
    'publicCode', ticket_order.public_code,
    'eventId', ticket_order.event_id,
    'eventSlug', ticket_order.event_slug,
    'eventDate', ticket_order.event_date,
    'eventTitle', ticket_order.event_title,
    'amountYen', ticket_order.amount_yen,
    'totalQuantity', ticket_order.total_quantity,
    'items', ticket_order.items_json
  ) ORDER BY action.recovery_next_attempt_at, action.created_at, action.id), '[]'::jsonb)
  INTO v_jobs
  FROM claimed AS action
  JOIN public.ticket_orders AS ticket_order ON ticket_order.id = action.ticket_order_id;

  RETURN jsonb_build_object(
    'action', 'claimed',
    'count', jsonb_array_length(v_jobs),
    'jobs', v_jobs,
    'serverNow', to_char(v_now AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
END;
$_$;

-- FUNCTION: claim_transactional_email_job_v29(uuid, text, integer, integer, uuid)
CREATE FUNCTION public.claim_transactional_email_job_v29(p_worker_id uuid, p_provider_name text, p_lease_seconds integer, p_maximum_provider_sends_per_second integer, p_specific_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_job public.transactional_email_jobs%ROWTYPE;
  v_challenge public.ticket_wallet_otp_challenges%ROWTYPE;
  v_claim_token uuid;
  v_circuit public.transactional_email_provider_circuits%ROWTYPE;
BEGIN
  IF p_worker_id IS NULL OR p_provider_name NOT IN ('fake', 'resend')
    OR p_lease_seconds NOT BETWEEN 30 AND 3600
    OR p_maximum_provider_sends_per_second <> 4
  THEN
    RAISE EXCEPTION 'invalid transactional email claim';
  END IF;

  SELECT * INTO v_circuit
  FROM public.transactional_email_provider_circuits
  WHERE provider_name = p_provider_name;
  IF FOUND AND v_circuit.is_open
    AND (v_circuit.open_until IS NULL OR v_circuit.open_until > v_now)
  THEN
    RETURN jsonb_build_object('action', 'circuit_open');
  END IF;

  -- Challenge precedes job in the row-lock list everywhere that can advance
  -- both records (verify/expiry/claim/outcome/webhook/manager recovery).
  SELECT job.* INTO v_job
  FROM public.ticket_wallet_otp_challenges AS challenge
  JOIN public.transactional_email_jobs AS job
    ON job.otp_challenge_id = challenge.id
  WHERE (p_specific_job_id IS NULL OR job.id = p_specific_job_id)
    AND (
      job.state IN ('pending', 'retry')
      OR (job.state = 'processing' AND job.lease_expires_at <= v_now)
    )
    AND job.attempt_count < job.maximum_attempts
    AND job.next_attempt_at <= v_now
    AND challenge.state IN ('pending', 'sending', 'sent')
    AND challenge.expires_at > v_now
    AND challenge.code_ciphertext IS NOT NULL
  ORDER BY CASE WHEN job.id = p_specific_job_id THEN 0 ELSE 1 END,
           job.created_at, job.id
  LIMIT 1
  FOR UPDATE OF challenge, job SKIP LOCKED;

  -- NEW (G-59): a suppression recorded between enqueue and claim terminalizes
  -- the job instead of allowing one residual provider send. The challenge is
  -- failed and its code ciphertext scrubbed, matching the provider-event
  -- suppression path in record_transactional_email_provider_event_v29.
  IF FOUND AND v_job.otp_challenge_id IS NOT NULL AND v_job.recipient_email_hash IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM public.transactional_email_suppressions AS suppression
      WHERE suppression.provider_name = p_provider_name
        AND suppression.recipient_email_hash = v_job.recipient_email_hash
        AND suppression.active
    )
  THEN
    UPDATE public.transactional_email_jobs
    SET state = 'dead',
        safe_error_category = 'recipient_suppressed',
        terminal_at = v_now,
        completed_at = v_now,
        claimed_by = NULL, claim_token = NULL,
        claimed_at = NULL, lease_expires_at = NULL,
        updated_at = v_now
    WHERE id = v_job.id;
    UPDATE public.ticket_wallet_otp_challenges
    SET state = 'failed',
        code_ciphertext = NULL,
        terminal_at = COALESCE(terminal_at, v_now),
        updated_at = v_now
    WHERE id = v_job.otp_challenge_id
      AND state IN ('pending', 'sending', 'sent');
    RETURN jsonb_build_object('action', 'suppressed', 'jobId', v_job.id);
  END IF;

  IF NOT FOUND THEN
    SELECT job.* INTO v_job FROM public.ticket_orders o JOIN public.transactional_email_jobs job ON job.ticket_order_id=o.id
    WHERE job.purpose='ticket_wallet_purchase' AND public.ticket_entry_delivery_active_v53(job.ticket_order_id,job.render_data_json) AND (p_specific_job_id IS NULL OR job.id=p_specific_job_id)
      AND (job.state IN ('pending','retry') OR (job.state='processing' AND job.lease_expires_at<=v_now))
      AND job.attempt_count<job.maximum_attempts AND job.next_attempt_at<=v_now
      AND (job.render_data_json->>'expiresAt')::timestamptz>v_now
      AND (job.first_send_at IS NULL OR job.first_send_at>v_now-interval '23 hours')
      AND NOT EXISTS(SELECT 1 FROM public.transactional_email_suppressions s WHERE s.provider_name=p_provider_name AND s.recipient_email_hash=job.recipient_email_hash AND s.active)
    ORDER BY (job.attempt_count>0),job.created_at,job.id LIMIT 1 FOR UPDATE OF o,job SKIP LOCKED;
    IF NOT FOUND THEN RETURN jsonb_build_object('action','empty'); END IF;
    -- Purchase notices keep a one-per-second cadence; there is no daily cap.
    IF NOT public.consume_ticket_wallet_rate_limit_v29('purchase_send_1s_'||p_provider_name,'global',1,1)

    THEN RETURN jsonb_build_object('action','cadence_limited'); END IF;
  END IF;

  IF NOT public.consume_ticket_wallet_rate_limit_v29(
      'provider_send_1s_' || p_provider_name, 'global', 1,
      p_maximum_provider_sends_per_second)

  THEN
    RETURN jsonb_build_object('action', 'cadence_limited');
  END IF;

  SELECT * INTO v_challenge
  FROM public.ticket_wallet_otp_challenges
  WHERE id = v_job.otp_challenge_id;
  IF v_job.otp_challenge_id IS NOT NULL AND (v_challenge.state NOT IN ('pending', 'sending', 'sent')
    OR v_challenge.expires_at <= v_now OR v_challenge.code_ciphertext IS NULL)
  THEN
    RETURN jsonb_build_object('action', 'empty');
  END IF;

  -- v79: no application daily budget. Provider refusals are classified by
  -- the dispatcher (daily_quota_exceeded opens the circuit until UTC reset).

  v_claim_token := gen_random_uuid();
  UPDATE public.transactional_email_jobs
  SET state = 'processing', provider_name = p_provider_name,
      first_send_at = COALESCE(first_send_at,v_now),
      attempt_count = attempt_count + 1,
      claimed_by = p_worker_id, claim_token = v_claim_token,
      claimed_at = v_now,
      lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
      updated_at = v_now
  WHERE id = v_job.id
  RETURNING * INTO v_job;
  UPDATE public.ticket_wallet_otp_challenges
  SET state = 'sending', updated_at = v_now
  WHERE id = v_challenge.id;

  RETURN jsonb_build_object(
    'action', 'claimed',
    'job', jsonb_build_object(
      'id', v_job.id,
      'claimToken', v_claim_token,
      'attemptCount', v_job.attempt_count,
      'providerIdempotencyKey', v_job.provider_idempotency_key,
      'expectedPayloadHash', v_job.payload_hash,
      'otpChallengeId', v_challenge.id,
      'authKeyId', v_challenge.auth_key_id,
      'recipientCiphertextBase64', replace(
        encode(v_job.recipient_email_ciphertext, 'base64'), E'\n', ''),
      'otpCiphertextBase64', replace(
        encode(v_challenge.code_ciphertext, 'base64'), E'\n', ''),
      'renderDataJson', v_job.render_data_json
    )
  );
END;
$$;

-- FUNCTION: claim_webhook_events_v7(uuid, integer, integer)
CREATE FUNCTION public.claim_webhook_events_v7(p_worker_id uuid, p_limit integer DEFAULT 25, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(id uuid, stripe_event_id text, event_type text, payload_json jsonb, claim_token uuid, environment text, stripe_account_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_worker_id IS NULL OR p_limit IS NULL OR p_limit < 1 OR p_limit > 100
    OR p_lease_seconds IS NULL OR p_lease_seconds < 30 OR p_lease_seconds > 3600 THEN
    RAISE EXCEPTION 'invalid worker claim bounds';
  END IF;
  RETURN QUERY
  WITH claimable AS (
    SELECT we.id
    FROM webhook_events we
    WHERE (
        (we.processing_status IN ('received','retry') AND we.next_attempt_at <= now())
        OR (we.processing_status = 'processing'
          AND we.locked_at < now() - make_interval(secs => p_lease_seconds))
      )
      AND (
        we.locked_at IS NULL
        OR we.locked_at < now() - make_interval(secs => p_lease_seconds)
      )
    ORDER BY we.created_at
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  ),
  updated AS (
    UPDATE webhook_events we
    SET processing_status = 'processing',
        locked_by = p_worker_id,
        locked_at = now(),
        claim_token = gen_random_uuid(),
        attempt_count = we.attempt_count + 1,
        updated_at = now()
    FROM claimable c
    WHERE we.id = c.id
    RETURNING we.id, we.stripe_event_id, we.event_type, we.payload_json,
      we.claim_token, we.environment, we.stripe_account_id
  )
  SELECT updated.id, updated.stripe_event_id, updated.event_type,
    updated.payload_json, updated.claim_token, updated.environment,
    updated.stripe_account_id
  FROM updated;
END;
$$;

-- FUNCTION: cleanup_ticket_checkout_recovery_v28(integer)
CREATE FUNCTION public.cleanup_ticket_checkout_recovery_v28(p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_rate_deleted integer := 0;
  v_claims_cleared integer := 0;
BEGIN
  IF NOT (p_limit BETWEEN 1 AND 5000) THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'cleanup_limit_invalid');
  END IF;

  WITH stale AS (
    SELECT bucket.ctid
    FROM public.ticket_checkout_rate_limit_buckets AS bucket
    WHERE bucket.window_started_at < v_now - interval '1 day'
    ORDER BY bucket.window_started_at, bucket.bucket_type, bucket.bucket_key_hash
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  )
  DELETE FROM public.ticket_checkout_rate_limit_buckets AS bucket
  USING stale
  WHERE bucket.ctid = stale.ctid;
  GET DIAGNOSTICS v_rate_deleted = ROW_COUNT;

  WITH stale AS (
    SELECT action.id
    FROM public.ticket_checkout_actions AS action
    WHERE action.recovery_claim_token IS NOT NULL
      AND action.recovery_claim_expires_at <= v_now
    ORDER BY action.recovery_claim_expires_at, action.id
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.ticket_checkout_actions AS action
  SET recovery_claim_token = NULL,
      recovery_claimed_by = NULL,
      recovery_claimed_at = NULL,
      recovery_claim_expires_at = NULL,
      updated_at = now()
  FROM stale
  WHERE action.id = stale.id;
  GET DIAGNOSTICS v_claims_cleared = ROW_COUNT;

  RETURN jsonb_build_object(
    'action', 'cleaned',
    'rateBucketsDeleted', v_rate_deleted,
    'staleClaimsCleared', v_claims_cleared,
    'serverNow', to_char(v_now AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
END;
$$;

-- FUNCTION: cleanup_ticket_wallet_auth_email_v29(integer)
CREATE FUNCTION public.cleanup_ticket_wallet_auth_email_v29(p_batch_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_expired_challenges integer := 0;
  v_expired_flows integer := 0;
  v_expired_sessions integer := 0;
  v_scrubbed_challenges integer := 0;
  v_deleted_flows integer := 0;
  v_deleted_sessions integer := 0;
  v_deleted_rates integer := 0;
  v_deleted_events integer := 0;
  v_deleted_jobs integer := 0;
  v_deleted_suppressions integer := 0;
BEGIN
  IF p_batch_limit NOT BETWEEN 1 AND 10000 THEN
    RAISE EXCEPTION 'invalid Ticket Wallet retention batch';
  END IF;

  -- Clear expired WebAuthn FK children before parent flow/session retention.
  WITH candidates AS (
    SELECT id FROM public.ticket_wallet_passkey_challenges
    WHERE expires_at <= v_now - interval '7 days'
    ORDER BY expires_at, id FOR UPDATE SKIP LOCKED LIMIT p_batch_limit
  )
  DELETE FROM public.ticket_wallet_passkey_challenges AS challenge
  USING candidates WHERE challenge.id = candidates.id;

  WITH candidates AS (
    SELECT id FROM public.ticket_wallet_otp_challenges
    WHERE state IN ('pending', 'sending', 'sent') AND expires_at <= v_now
    ORDER BY expires_at, id FOR UPDATE SKIP LOCKED LIMIT p_batch_limit
  )
  UPDATE public.ticket_wallet_otp_challenges AS challenge
  SET state = 'expired', code_ciphertext = NULL,
      terminal_at = v_now, updated_at = v_now
  FROM candidates WHERE challenge.id = candidates.id;
  GET DIAGNOSTICS v_expired_challenges = ROW_COUNT;

  UPDATE public.transactional_email_jobs AS job
  SET state = 'cancelled', terminal_at = v_now,
      claimed_by = NULL, claim_token = NULL, claimed_at = NULL,
      lease_expires_at = NULL, updated_at = v_now
  FROM public.ticket_wallet_otp_challenges AS challenge
  WHERE challenge.id = job.otp_challenge_id
    AND challenge.state IN ('consumed', 'expired', 'locked', 'failed', 'superseded')
    AND job.state IN ('pending', 'processing', 'retry');

  WITH candidates AS (
    SELECT id FROM public.ticket_wallet_preauth_flows
    WHERE state = 'active' AND expires_at <= v_now
    ORDER BY expires_at, id FOR UPDATE SKIP LOCKED LIMIT p_batch_limit
  )
  UPDATE public.ticket_wallet_preauth_flows AS flow
  SET state = 'expired', token_verifier = NULL, csrf_verifier = NULL,
      terminal_at = v_now, updated_at = v_now
  FROM candidates WHERE flow.id = candidates.id;
  GET DIAGNOSTICS v_expired_flows = ROW_COUNT;

  WITH candidates AS (
    SELECT id FROM public.ticket_wallet_sessions
    WHERE revoked_at IS NULL AND expires_at <= v_now
    ORDER BY expires_at, id FOR UPDATE SKIP LOCKED LIMIT p_batch_limit
  )
  UPDATE public.ticket_wallet_sessions AS session
  SET revoked_at = v_now, revocation_reason = 'expired',
      token_verifier = NULL, csrf_verifier = NULL, updated_at = v_now
  FROM candidates WHERE session.id = candidates.id;
  GET DIAGNOSTICS v_expired_sessions = ROW_COUNT;

  WITH candidates AS (
    SELECT id FROM public.ticket_wallet_otp_challenges
    WHERE terminal_at <= v_now - interval '7 days'
      AND (code_verifier IS NOT NULL OR identity_email_hash IS NOT NULL
        OR abuse_email_hash IS NOT NULL OR abuse_ip_hash IS NOT NULL
        OR abuse_user_agent_hash IS NOT NULL)
    ORDER BY terminal_at, id FOR UPDATE SKIP LOCKED LIMIT p_batch_limit
  )
  UPDATE public.ticket_wallet_otp_challenges AS challenge
  SET code_verifier = NULL, identity_email_hash = NULL,
      abuse_email_hash = NULL, abuse_ip_hash = NULL,
      abuse_user_agent_hash = NULL,
      preauth_flow_id = NULL, preauth_expires_at = NULL,
      scrubbed_at = v_now, updated_at = v_now
  FROM candidates WHERE challenge.id = candidates.id;
  GET DIAGNOSTICS v_scrubbed_challenges = ROW_COUNT;

  WITH candidates AS (
    SELECT id FROM public.ticket_wallet_preauth_flows
    WHERE terminal_at <= v_now - interval '7 days'
    ORDER BY terminal_at, id LIMIT p_batch_limit
  )
  DELETE FROM public.ticket_wallet_preauth_flows AS flow
  USING candidates
  WHERE flow.id = candidates.id
    AND NOT EXISTS (
      SELECT 1 FROM public.ticket_wallet_otp_challenges AS challenge
      WHERE challenge.preauth_flow_id = flow.id
    )
    AND NOT EXISTS (SELECT 1 FROM public.ticket_wallet_passkey_challenges AS challenge
      WHERE challenge.preauth_flow_id = flow.id);
  GET DIAGNOSTICS v_deleted_flows = ROW_COUNT;

  WITH candidates AS (
    SELECT id FROM public.ticket_wallet_sessions
    WHERE revoked_at <= v_now - interval '30 days'
    ORDER BY revoked_at, id LIMIT p_batch_limit
  )
  DELETE FROM public.ticket_wallet_sessions AS session
  USING candidates WHERE session.id = candidates.id
    AND NOT EXISTS (SELECT 1 FROM public.ticket_wallet_passkey_challenges AS challenge
      WHERE challenge.session_id = session.id);
  GET DIAGNOSTICS v_deleted_sessions = ROW_COUNT;

  WITH candidates AS (
    SELECT bucket_name, bucket_hash
    FROM public.ticket_wallet_rate_limit_buckets
    WHERE GREATEST(window_expires_at, COALESCE(blocked_until, window_expires_at))
      <= v_now - interval '7 days'
    ORDER BY window_expires_at, bucket_name, bucket_hash LIMIT p_batch_limit
  )
  DELETE FROM public.ticket_wallet_rate_limit_buckets AS bucket
  USING candidates
  WHERE bucket.bucket_name = candidates.bucket_name
    AND bucket.bucket_hash = candidates.bucket_hash;
  GET DIAGNOSTICS v_deleted_rates = ROW_COUNT;

  WITH candidates AS (
    SELECT id, (occurred_at AT TIME ZONE 'UTC')::date AS aggregate_date,
           normalized_delivery_state
    FROM public.transactional_email_provider_events
    WHERE created_at <= v_now - interval '90 days'
    ORDER BY created_at, id LIMIT p_batch_limit
  ), aggregate_rows AS (
    INSERT INTO public.ticket_auth_email_retention_aggregates(
      aggregate_date, aggregate_type, aggregate_state, aggregate_count, updated_at
    )
    SELECT aggregate_date, 'provider_event', normalized_delivery_state, count(*), v_now
    FROM candidates GROUP BY aggregate_date, normalized_delivery_state
    ON CONFLICT (aggregate_date, aggregate_type, aggregate_state) DO UPDATE
    SET aggregate_count = public.ticket_auth_email_retention_aggregates.aggregate_count
          + EXCLUDED.aggregate_count,
        updated_at = EXCLUDED.updated_at
    RETURNING 1
  )
  DELETE FROM public.transactional_email_provider_events AS event
  USING candidates WHERE event.id = candidates.id;
  GET DIAGNOSTICS v_deleted_events = ROW_COUNT;

  WITH candidates AS (
    SELECT id, (COALESCE(completed_at, terminal_at, accepted_at, created_at)
      AT TIME ZONE 'UTC')::date AS aggregate_date, state
    FROM public.transactional_email_jobs
    WHERE state IN ('accepted', 'dead', 'configuration', 'cancelled')
      AND COALESCE(completed_at, terminal_at, accepted_at, created_at)
        <= v_now - interval '90 days'
    ORDER BY COALESCE(completed_at, terminal_at, accepted_at, created_at), id
    LIMIT p_batch_limit
  ), aggregate_rows AS (
    INSERT INTO public.ticket_auth_email_retention_aggregates(
      aggregate_date, aggregate_type, aggregate_state, aggregate_count, updated_at
    )
    SELECT aggregate_date, 'email_job', state, count(*), v_now
    FROM candidates GROUP BY aggregate_date, state
    ON CONFLICT (aggregate_date, aggregate_type, aggregate_state) DO UPDATE
    SET aggregate_count = public.ticket_auth_email_retention_aggregates.aggregate_count
          + EXCLUDED.aggregate_count,
        updated_at = EXCLUDED.updated_at
    RETURNING 1
  )
  DELETE FROM public.transactional_email_jobs AS job
  USING candidates WHERE job.id = candidates.id;
  GET DIAGNOSTICS v_deleted_jobs = ROW_COUNT;

  WITH candidates AS (
    SELECT provider_name, recipient_email_hash
    FROM public.transactional_email_suppressions
    WHERE NOT active AND deactivated_at <= v_now - interval '90 days'
    ORDER BY deactivated_at, provider_name, recipient_email_hash LIMIT p_batch_limit
  )
  DELETE FROM public.transactional_email_suppressions AS suppression
  USING candidates
  WHERE suppression.provider_name = candidates.provider_name
    AND suppression.recipient_email_hash = candidates.recipient_email_hash;
  GET DIAGNOSTICS v_deleted_suppressions = ROW_COUNT;

  RETURN jsonb_build_object(
    'action', 'cleaned',
    'expiredChallenges', v_expired_challenges,
    'expiredPreauthFlows', v_expired_flows,
    'expiredSessions', v_expired_sessions,
    'scrubbedChallenges', v_scrubbed_challenges,
    'deletedPreauthFlows', v_deleted_flows,
    'deletedSessions', v_deleted_sessions,
    'deletedRateBuckets', v_deleted_rates,
    'deletedProviderEvents', v_deleted_events,
    'deletedEmailJobs', v_deleted_jobs,
    'deletedSuppressions', v_deleted_suppressions
  );
END;
$$;

-- FUNCTION: cleanup_vip_manager_trial_restricted_rows_v17(text)
CREATE FUNCTION public.cleanup_vip_manager_trial_restricted_rows_v17(p_trial_run_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_headers jsonb := COALESCE(
    NULLIF(current_setting('request.headers', true), '')::jsonb,
    '{}'::jsonb
  );
  v_header_run_id text := NULLIF(v_headers ->> 'x-ghost-vip-trial-run-id', '');
  v_assignment_events bigint := 0;
  v_service_events bigint := 0;
  v_customer_link_events bigint := 0;
  v_table_staff_assignments bigint := 0;
  v_waitlist_entries bigint := 0;
  v_staff_members bigint := 0;
BEGIN
  IF p_trial_run_id !~ '^trial-[a-z0-9][a-z0-9-]{7,80}$'
    OR v_header_run_id IS DISTINCT FROM p_trial_run_id
    OR NOT EXISTS (
      SELECT 1
      FROM public.vip_manager_trial_runs
      WHERE trial_run_id = p_trial_run_id
        AND closed_at IS NULL
    )
  THEN
    RAISE EXCEPTION 'trial_cleanup_run_not_authorized';
  END IF;

  DELETE FROM public.reservation_customer_link_events
  WHERE trial_run_id = p_trial_run_id;
  GET DIAGNOSTICS v_customer_link_events = ROW_COUNT;

  -- The two history tables reject all runtime DELETE operations by design.
  -- Disable only their named row guards inside this transaction; any error
  -- rolls the trigger state and deletes back together.
  ALTER TABLE public.reservation_assignment_events
    DISABLE TRIGGER trg_reservation_assignment_events_append_only_rows;
  ALTER TABLE public.reservation_service_events
    DISABLE TRIGGER trg_reservation_service_events_append_only_rows;

  DELETE FROM public.reservation_assignment_events
  WHERE trial_run_id = p_trial_run_id;
  GET DIAGNOSTICS v_assignment_events = ROW_COUNT;

  DELETE FROM public.reservation_service_events
  WHERE trial_run_id = p_trial_run_id;
  GET DIAGNOSTICS v_service_events = ROW_COUNT;

  ALTER TABLE public.reservation_assignment_events
    ENABLE TRIGGER trg_reservation_assignment_events_append_only_rows;
  ALTER TABLE public.reservation_service_events
    ENABLE TRIGGER trg_reservation_service_events_append_only_rows;

  DELETE FROM public.vip_table_staff_assignments
  WHERE trial_run_id = p_trial_run_id;
  GET DIAGNOSTICS v_table_staff_assignments = ROW_COUNT;

  DELETE FROM public.vip_waitlist_entries
  WHERE trial_run_id = p_trial_run_id;
  GET DIAGNOSTICS v_waitlist_entries = ROW_COUNT;

  DELETE FROM public.vip_staff_members
  WHERE trial_run_id = p_trial_run_id;
  GET DIAGNOSTICS v_staff_members = ROW_COUNT;

  RETURN jsonb_build_object(
    'reservation_assignment_events', v_assignment_events,
    'reservation_service_events', v_service_events,
    'reservation_customer_link_events', v_customer_link_events,
    'vip_table_staff_assignments', v_table_staff_assignments,
    'vip_waitlist_entries', v_waitlist_entries,
    'vip_staff_members', v_staff_members
  );
END;
$_$;

-- FUNCTION: commit_ticket_admission_v30(text, uuid, text, uuid, text, text, text)
CREATE FUNCTION public.commit_ticket_admission_v30(p_environment text, p_wallet_session_id uuid, p_session_token_verifier text, p_operation_id uuid, p_commit_idempotency_key_hash text, p_commit_request_hash text, p_challenge_token_verifier text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_operation public.ticket_admission_operations%ROWTYPE;
  v_wallet_session public.ticket_wallet_sessions%ROWTYPE;
  v_event_day public.event_days%ROWTYPE;
  v_event_session public.ticket_event_sessions%ROWTYPE;
  v_ticket_order public.ticket_orders%ROWTYPE;
  v_challenge public.ticket_admission_challenges%ROWTYPE;
  v_rejection_code text;
  v_selected integer := 0;
  v_issued integer := 0;
  v_admitted integer := 0;
  v_void integer := 0;
  v_updated integer := 0;
  v_committed_order_version bigint;
  v_original_admitted_at timestamptz;
  v_result jsonb;
BEGIN
  IF COALESCE(p_environment, '') NOT IN ('test', 'live')
    OR p_wallet_session_id IS NULL
    OR p_operation_id IS NULL
    OR NULLIF(btrim(COALESCE(p_session_token_verifier, '')), '') IS NULL
    OR char_length(p_session_token_verifier) > 512
    OR NULLIF(btrim(COALESCE(p_commit_idempotency_key_hash, '')), '') IS NULL
    OR char_length(p_commit_idempotency_key_hash) > 200
    OR NULLIF(btrim(COALESCE(p_commit_request_hash, '')), '') IS NULL
    OR char_length(p_commit_request_hash) > 200
    OR char_length(COALESCE(p_challenge_token_verifier, '')) > 512
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'admission_commit_invalid');
  END IF;

  -- The target Operation is always the first authority lock.
  SELECT * INTO v_operation
  FROM public.ticket_admission_operations
  WHERE id = p_operation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'not_found');
  END IF;
  IF v_operation.actor_type <> 'customer'
    OR v_operation.wallet_session_id IS NULL
    OR v_operation.wallet_session_id <> p_wallet_session_id
    OR v_operation.environment <> p_environment
  THEN
    RETURN jsonb_build_object('action', 'not_found');
  END IF;

  -- Wallet Session is always second. A valid bearer may replay a terminal
  -- result even after freshness/revocation or challenge expiry; this is the
  -- response-loss guarantee and never re-runs an Admission mutation.
  SELECT * INTO v_wallet_session
  FROM public.ticket_wallet_sessions
  WHERE id = v_operation.wallet_session_id
    AND environment = v_operation.environment
  FOR UPDATE;
  IF NOT FOUND
    OR v_wallet_session.identity_email_hash IS NULL
    OR NOT public.ticket_auth_digest_equal_v29(
      v_wallet_session.token_verifier, p_session_token_verifier)
  THEN
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;

  v_now := clock_timestamp();
  IF v_operation.commit_idempotency_key_hash IS NOT NULL
    AND (
      v_operation.commit_idempotency_key_hash <>
        btrim(p_commit_idempotency_key_hash)
      OR v_operation.commit_request_hash <> btrim(p_commit_request_hash)
    )
  THEN
    RETURN jsonb_build_object('action', 'conflict', 'reason', 'idempotency_mismatch');
  END IF;
  IF v_operation.state IN ('committed', 'rejected', 'expired') THEN
    RETURN jsonb_build_object('action', 'result', 'serverNow', v_now)
      || jsonb_set(v_operation.result_json, '{reused}', 'true'::jsonb, true);
  END IF;
  IF v_operation.state <> 'prepared' THEN
    RETURN jsonb_build_object('action', 'conflict', 'reason', 'operation_not_prepared');
  END IF;
  -- The challenge credential is optional only for the terminal replay above.
  IF NULLIF(btrim(COALESCE(p_challenge_token_verifier, '')), '') IS NULL THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'challenge_required');
  END IF;

  v_now := clock_timestamp();
  IF v_wallet_session.revoked_at IS NOT NULL
    OR v_wallet_session.expires_at <= v_now
  THEN
    v_rejection_code := 'session_expired';
  ELSIF v_wallet_session.fresh_until <= v_now THEN
    v_rejection_code := 'fresh_auth_required';
  ELSIF NOT public.consume_ticket_wallet_rate_limit_v29(
    'admission_commit', v_wallet_session.identity_email_hash, 600, 10)
  THEN
    v_rejection_code := 'rate_limited';
  END IF;

  SELECT * INTO v_event_day
  FROM public.event_days
  WHERE id = v_operation.event_day_id
  FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket Admission Event Day disappeared';
  END IF;

  SELECT * INTO v_event_session
  FROM public.ticket_event_sessions
  WHERE id = v_operation.event_session_id
    AND event_day_id = v_event_day.id
  FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket Admission Event Session disappeared';
  END IF;

  SELECT * INTO v_ticket_order
  FROM public.ticket_orders
  WHERE id = v_operation.ticket_order_id
    AND event_session_id = v_event_session.id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket Admission Ticket Order disappeared';
  END IF;

  PERFORM refund.id
  FROM public.ticket_refund_events AS refund
  WHERE refund.ticket_order_id = v_ticket_order.id
  ORDER BY refund.created_at, refund.id
  FOR UPDATE;
  PERFORM allocation.id
  FROM public.ticket_refund_allocations AS allocation
  WHERE allocation.ticket_order_id = v_ticket_order.id
  ORDER BY allocation.admission_serial, allocation.id
  FOR UPDATE;

  SELECT * INTO v_challenge
  FROM public.ticket_admission_challenges
  WHERE operation_id = v_operation.id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket Admission Challenge disappeared';
  END IF;

  PERFORM admission.id
  FROM public.ticket_admission_operation_items AS item
  JOIN public.ticket_admissions AS admission
    ON admission.id = item.ticket_admission_id
   AND admission.ticket_order_id = item.ticket_order_id
   AND admission.serial = item.admission_serial
  WHERE item.operation_id = v_operation.id
  ORDER BY admission.serial, admission.id
  FOR UPDATE OF admission;

  SELECT
    count(*)::integer,
    count(*) FILTER (WHERE admission.status = 'issued')::integer,
    count(*) FILTER (WHERE admission.status = 'admitted')::integer,
    count(*) FILTER (WHERE admission.status = 'void')::integer,
    min(admission.admitted_at) FILTER (WHERE admission.status = 'admitted')
  INTO v_selected, v_issued, v_admitted, v_void, v_original_admitted_at
  FROM public.ticket_admission_operation_items AS item
  JOIN public.ticket_admissions AS admission
    ON admission.id = item.ticket_admission_id
   AND admission.ticket_order_id = item.ticket_order_id
   AND admission.serial = item.admission_serial
  WHERE item.operation_id = v_operation.id;

  v_now := clock_timestamp();
  IF v_rejection_code IS NULL AND (
    v_event_day.business_date <> v_event_session.event_date
    OR v_event_day.business_date <> v_ticket_order.event_date
    OR v_event_day.operating_status <> 'open'
  ) THEN
    v_rejection_code := 'event_day_closed';
  END IF;
  IF v_rejection_code IS NULL AND (
    NOT v_event_session.enabled
    OR v_event_session.admission_state <> 'scheduled'
  ) THEN
    v_rejection_code := CASE WHEN v_event_session.admission_state = 'cancelled'
      THEN 'event_session_cancelled' ELSE 'event_session_closed' END;
  END IF;
  IF v_rejection_code IS NULL AND v_now < public.ticket_admission_execution_opens_v56(v_event_session.id) THEN
    v_rejection_code := 'admission_too_early';
  END IF;
  IF v_rejection_code IS NULL AND v_now >= public.ticket_admission_execution_closes_v56(v_event_session.id) THEN
    v_rejection_code := 'admission_too_late';
  END IF;
  IF v_rejection_code IS NULL
    AND NOT public.ticket_admission_policy_compatible_v30(
      v_event_session.id, v_operation.policy_version, v_event_session.policy_version)
  THEN
    v_rejection_code := 'policy_version_changed';
  END IF;
  IF v_rejection_code IS NULL AND (
    v_event_session.environment <> v_operation.environment
    OR v_ticket_order.environment <> v_operation.environment
    OR v_event_session.stripe_account_key <> v_operation.stripe_account_key
    OR v_ticket_order.stripe_account_key <> v_operation.stripe_account_key
    OR v_ticket_order.event_id <> v_event_session.catalog_event_id
    OR v_ticket_order.check_in_mode <> 'wallet_swipe'
  ) THEN
    v_rejection_code := 'authority_binding_mismatch';
  END IF;
  IF v_rejection_code IS NULL AND (
    v_ticket_order.purchaser_email_hash IS NULL
    OR NOT public.ticket_holder_has_order_v34(v_wallet_session.holder_id,v_ticket_order.id)
  ) THEN
    v_rejection_code := 'holder_mismatch';
  END IF;
  IF v_rejection_code IS NULL
    AND NOT public.ticket_order_has_settled_payment_v30(v_ticket_order.id)
  THEN
    v_rejection_code := 'payment_not_settled';
  END IF;
  IF v_rejection_code IS NULL AND EXISTS (
    SELECT 1 FROM public.ticket_refund_events AS refund
    WHERE refund.ticket_order_id = v_ticket_order.id
      AND refund.money_may_have_moved
      AND refund.resolution_status IN ('review_required', 'conflict_review')
      AND refund.resolved_at IS NULL
  ) THEN
    v_rejection_code := 'refund_review_required';
  END IF;

  IF v_challenge.state <> 'active' THEN
    RETURN jsonb_build_object('action', 'conflict', 'reason', 'challenge_terminal');
  ELSIF NOT public.ticket_auth_digest_equal_v29(
    v_challenge.challenge_token_verifier, p_challenge_token_verifier)
  THEN
    RETURN jsonb_build_object('action', 'conflict', 'reason', 'challenge_mismatch');
  ELSIF v_challenge.expires_at <= v_now THEN
    -- Only the holder of the one-time challenge may terminalize its expiry.
    v_rejection_code := COALESCE(v_rejection_code, 'challenge_expired');
  ELSIF v_challenge.wallet_session_id <> v_operation.wallet_session_id
    OR v_challenge.event_session_id <> v_operation.event_session_id
    OR v_challenge.ticket_order_id <> v_operation.ticket_order_id
    OR v_challenge.environment <> v_operation.environment
    OR v_challenge.stripe_account_key <> v_operation.stripe_account_key
    OR v_challenge.request_hash <> v_operation.request_hash
    OR v_challenge.policy_version <> v_operation.policy_version
    OR v_challenge.selected_count <> v_operation.selected_count
  THEN
    v_rejection_code := COALESCE(v_rejection_code, 'challenge_binding_mismatch');
  END IF;

  IF v_selected <> v_operation.selected_count THEN
    v_rejection_code := 'selection_row_count_mismatch';
  ELSIF v_admitted > 0 THEN
    -- This overrides a resulting order-version mismatch so a second tab gets
    -- the useful durable terminal fact and original server timestamp.
    v_rejection_code := 'already_admitted';
  ELSIF v_void > 0 THEN
    v_rejection_code := 'admission_void';
  ELSIF v_issued <> v_operation.selected_count THEN
    v_rejection_code := 'admission_not_issued';
  ELSIF v_rejection_code IS NULL
    AND v_ticket_order.admission_version <> v_operation.expected_order_version
  THEN
    v_rejection_code := 'version_conflict';
  END IF;

  -- Bind the first valid commit identity only after the one-time challenge has
  -- matched. A wrong token cannot reserve a victim Operation's commit key.
  IF v_operation.commit_idempotency_key_hash IS NULL THEN
    IF EXISTS (
      SELECT 1
      FROM public.ticket_admission_operations AS other_operation
      WHERE other_operation.wallet_session_id = v_operation.wallet_session_id
        AND other_operation.commit_idempotency_key_hash =
          btrim(p_commit_idempotency_key_hash)
        AND other_operation.id <> v_operation.id
    ) THEN
      RETURN jsonb_build_object('action', 'conflict', 'reason', 'idempotency_key_reused');
    END IF;
    BEGIN
      UPDATE public.ticket_admission_operations
      SET commit_idempotency_key_hash = btrim(p_commit_idempotency_key_hash),
          commit_request_hash = btrim(p_commit_request_hash),
          operation_version = operation_version + 1,
          updated_at = v_now
      WHERE id = v_operation.id
        AND commit_idempotency_key_hash IS NULL
      RETURNING * INTO v_operation;
    EXCEPTION WHEN unique_violation THEN
      RETURN jsonb_build_object('action', 'conflict', 'reason', 'idempotency_key_reused');
    END;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Ticket Admission commit identity claim failed';
    END IF;
  END IF;

  IF v_rejection_code IS NOT NULL THEN
    IF v_rejection_code = 'already_admitted' THEN
      v_result := public.complete_ticket_admission_operation_v30(
        v_operation.id, 'rejected', v_rejection_code,
        v_original_admitted_at, 0, NULL, 'customer', NULL,
        v_operation.wallet_session_id, v_rejection_code);
      UPDATE public.ticket_admission_challenges
      SET state = 'rejected', terminal_at = v_now, updated_at = v_now
      WHERE id = v_challenge.id AND state = 'active';
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Ticket Admission Challenge rejection failed';
      END IF;
    ELSE
      v_result := public.reject_ticket_admission_operation_v30(
        v_operation.id, v_challenge.id,
        CASE WHEN v_rejection_code = 'challenge_expired'
          THEN 'expired' ELSE 'rejected' END,
        v_rejection_code, 'customer', NULL,
        v_operation.wallet_session_id, v_rejection_code);
    END IF;
    RETURN jsonb_build_object('action', 'result', 'serverNow', v_now)
      || v_result;
  END IF;

  UPDATE public.ticket_admissions AS admission
  SET status = 'admitted',
      admitted_at = v_now,
      admitted_by_admin_id = NULL
  FROM public.ticket_admission_operation_items AS item
  WHERE item.operation_id = v_operation.id
    AND item.ticket_admission_id = admission.id
    AND item.ticket_order_id = admission.ticket_order_id
    AND item.admission_serial = admission.serial
    AND admission.ticket_order_id = v_ticket_order.id
    AND admission.status = 'issued';
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> v_operation.selected_count THEN
    RAISE EXCEPTION 'Ticket Admission update row-count mismatch: expected %, got %',
      v_operation.selected_count, v_updated;
  END IF;

  SELECT admission_version INTO v_committed_order_version
  FROM public.ticket_orders
  WHERE id = v_ticket_order.id;
  IF v_committed_order_version <= v_operation.expected_order_version THEN
    RAISE EXCEPTION 'Ticket Admission order version did not advance';
  END IF;

  UPDATE public.ticket_admission_challenges
  SET state = 'consumed',
      consumed_at = v_now,
      terminal_at = v_now,
      updated_at = v_now
  WHERE id = v_challenge.id
    AND state = 'active';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket Admission Challenge consume failed';
  END IF;

  v_result := public.complete_ticket_admission_operation_v30(
    v_operation.id, 'committed', NULL, v_now,
    v_operation.selected_count, v_committed_order_version,
    'customer', NULL, v_operation.wallet_session_id, NULL);
  RETURN jsonb_build_object('action', 'result', 'serverNow', v_now)
    || v_result;
END;
$$;

-- FUNCTION: commit_ticket_order_entry_v52(uuid, uuid, text, text, text, text, text, uuid, text, text, text)
CREATE FUNCTION public.commit_ticket_order_entry_v52(p_order uuid, p_session uuid, p_token text, p_csrf text, p_environment text, p_origin text, p_account text, p_operation uuid, p_commit_key text, p_request_hash text, p_challenge text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE locked jsonb; op public.ticket_order_entry_operations%ROWTYPE; error text; at timestamptz; n integer; result jsonb;
BEGIN
 IF p_csrf IS NULL OR p_commit_key IS NULL OR p_request_hash IS NULL OR p_challenge IS NULL THEN RETURN jsonb_build_object('action','rejected','reason','input_invalid'); END IF;
 IF public.read_ticket_order_entry_authority_v52(p_order,p_session,p_token,p_csrf,p_environment,p_origin,p_account) IS NULL
 THEN RETURN jsonb_build_object('action','unauthenticated'); END IF;
 locked:=public.lock_ticket_order_entry_v52(p_order);
 IF public.read_ticket_order_entry_authority_v52(p_order,p_session,p_token,p_csrf,p_environment,p_origin,p_account) IS NULL
 THEN RETURN jsonb_build_object('action','unauthenticated'); END IF;
 SELECT * INTO op FROM public.ticket_order_entry_operations WHERE id=p_operation AND ticket_order_id=p_order AND order_session_id=p_session FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('action','not_found'); END IF;
 IF op.commit_key IS NOT NULL AND (op.commit_key<>p_commit_key OR op.commit_request_hash<>p_request_hash)
 THEN RETURN jsonb_build_object('action','conflict','reason','idempotency_mismatch'); END IF;
 IF op.result_json IS NOT NULL THEN RETURN jsonb_build_object('action','result')||op.result_json||jsonb_build_object('reused',true,'serverNow',clock_timestamp()); END IF;
 IF NOT public.ticket_auth_digest_equal_v29(op.challenge_verifier,p_challenge) THEN RETURN jsonb_build_object('action','conflict','reason','challenge_mismatch'); END IF;
 error:=locked->>'error';
 IF op.expires_at<=clock_timestamp() THEN error:=coalesce(error,'challenge_expired'); END IF;
 IF (locked->>'version')::bigint<>op.expected_order_version THEN error:=coalesce(error,'version_conflict'); END IF;
 IF NOT public.ticket_admission_policy_compatible_v30((locked->>'eventSessionId')::uuid,op.policy_version,(locked->>'policyVersion')::bigint) THEN error:=coalesce(error,'policy_version_changed'); END IF;
 PERFORM id FROM public.ticket_admissions WHERE ticket_order_id=p_order ORDER BY serial,id FOR UPDATE;
 IF NOT COALESCE(public.ticket_group_entry_selection_v52(p_order,op.admission_ids),false) THEN error:=coalesce(error,'whole_order_selection_required'); END IF;
 IF EXISTS(SELECT 1 FROM public.ticket_order_entry_operations WHERE order_session_id=p_session AND commit_key=p_commit_key AND id<>op.id)
 THEN RETURN jsonb_build_object('action','conflict','reason','idempotency_key_reused'); END IF;
 at:=clock_timestamp();
 IF op.expires_at<=at THEN error:=coalesce(error,'challenge_expired'); END IF;
 IF public.read_ticket_order_entry_authority_v52(p_order,p_session,p_token,p_csrf,p_environment,p_origin,p_account) IS NULL THEN error:=coalesce(error,'admission_window_closed'); END IF;
 IF error IS NULL THEN
  UPDATE public.ticket_admissions SET status='admitted',admitted_at=at,admitted_by_admin_id=NULL
   WHERE ticket_order_id=p_order AND id=ANY(op.admission_ids) AND status='issued';
  GET DIAGNOSTICS n=ROW_COUNT;
  IF n<>cardinality(op.admission_ids) THEN RAISE EXCEPTION 'order_entry_update_count_mismatch'; END IF;
 END IF;
 result:=jsonb_build_object('operationId',op.id,'state',CASE WHEN error IS NULL THEN 'committed' ELSE 'rejected' END,
  'eventTitle',(SELECT event_title FROM public.ticket_orders WHERE id=p_order),'eventDate',(SELECT event_date FROM public.ticket_orders WHERE id=p_order),
  'admittedCount',CASE WHEN error IS NULL THEN cardinality(op.admission_ids) ELSE 0 END,'admittedAt',CASE WHEN error IS NULL THEN at ELSE NULL END,
  'serverNow',at,'errorCode',error);
 UPDATE public.ticket_order_entry_operations SET state=CASE WHEN error IS NULL THEN 'committed' ELSE 'rejected' END,
  commit_key=p_commit_key,commit_request_hash=p_request_hash,result_json=result WHERE id=op.id;
 INSERT INTO public.audit_logs(action,actor_type,target_table,target_id,entity_type,entity_id,operation,request_id,metadata_json)
 VALUES('ticket_admission.order_link_'||CASE WHEN error IS NULL THEN 'committed' ELSE 'rejected' END,'customer','ticket_orders',p_order,'ticket_order',p_order,'update',op.id::text,
  jsonb_build_object('admissionOperationId',op.id,'orderSessionId',p_session,'admissionIds',op.admission_ids,'admittedCount',result->'admittedCount','result',result));
 RETURN jsonb_build_object('action','result')||result;
END $$;

-- FUNCTION: complete_admin_action_request_v8(uuid, text, text, jsonb)
CREATE FUNCTION public.complete_admin_action_request_v8(p_actor_admin_id uuid, p_action text, p_idempotency_key text, p_response jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_updated int;
BEGIN
  IF p_response IS NULL
    OR jsonb_typeof(p_response) <> 'object'
    OR NOT COALESCE((p_response ->> 'ok')::boolean, false)
    OR p_response ->> 'action' IS NULL
    OR p_response -> 'boardRevision' IS NULL
    OR p_response -> 'auditLogId' IS NULL
  THEN
    RAISE EXCEPTION USING
      ERRCODE = 'XX000',
      MESSAGE = 'VIP floor action response is incomplete';
  END IF;

  UPDATE public.admin_action_requests
  SET response_json = p_response,
      updated_at = now()
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
    AND response_json IS NULL;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> 1 THEN
    RAISE EXCEPTION USING
      ERRCODE = 'XX000',
      MESSAGE = 'VIP floor action preclaim could not be completed';
  END IF;

  RETURN jsonb_build_object('action', 'completed');
END;
$$;

-- FUNCTION: complete_ticket_admission_operation_v30(uuid, text, text, timestamp with time zone, integer, bigint, text, uuid, uuid, text)
CREATE FUNCTION public.complete_ticket_admission_operation_v30(p_operation_id uuid, p_state text, p_error_code text, p_admitted_at timestamp with time zone, p_admitted_count integer, p_committed_order_version bigint, p_actor_type text, p_actor_admin_id uuid, p_wallet_session_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_operation public.ticket_admission_operations%ROWTYPE;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
  v_action text;
BEGIN
  IF p_state NOT IN ('committed', 'rejected', 'expired') THEN
    RAISE EXCEPTION 'invalid Ticket Admission terminal state';
  END IF;

  SELECT * INTO v_operation
  FROM public.ticket_admission_operations
  WHERE id = p_operation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket Admission Operation disappeared';
  END IF;

  IF v_operation.state IN ('committed', 'rejected', 'expired') THEN
    RETURN v_operation.result_json;
  END IF;

  v_result := jsonb_build_object(
    'operationId', v_operation.id,
    'reused', false,
    'state', p_state,
    'eventTitle', v_operation.event_title,
    'eventDate', v_operation.event_date,
    'eventSessionId', v_operation.event_session_id,
    'selectionGroupId', v_operation.ticket_order_id,
    'selectedCount', v_operation.selected_count,
    'admittedCount', CASE WHEN p_state = 'committed' THEN p_admitted_count ELSE 0 END,
    -- already_admitted rejection preserves the original server timestamp in
    -- the safe result without changing the Operation's admitted_at column.
    'admittedAt', p_admitted_at,
    'terminalAt', v_now,
    'operationVersion', v_operation.operation_version + 1
  );
  IF p_error_code IS NOT NULL THEN
    v_result := v_result || jsonb_build_object('errorCode', left(p_error_code, 80));
  END IF;

  UPDATE public.ticket_admission_operations
  SET state = p_state,
      result_json = v_result,
      admitted_at = CASE WHEN p_state = 'committed' THEN p_admitted_at ELSE NULL END,
      committed_order_version = CASE
        WHEN p_state = 'committed' THEN p_committed_order_version ELSE NULL END,
      terminal_at = v_now,
      operation_version = operation_version + 1,
      updated_at = v_now
  WHERE id = v_operation.id
    AND state IN ('initializing', 'prepared')
  RETURNING * INTO v_operation;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket Admission Operation terminal transition failed';
  END IF;

  v_action := CASE
    WHEN p_state = 'committed' AND p_actor_type = 'owner' THEN 'owner_committed'
    WHEN p_state = 'committed' THEN 'committed'
    WHEN p_state = 'expired' THEN 'expired'
    ELSE 'rejected'
  END;

  INSERT INTO public.ticket_admission_operation_audits(
    operation_id, actor_type, actor_admin_id, wallet_session_id,
    action, reason, operation_version, result_json
  ) VALUES (
    v_operation.id, p_actor_type, p_actor_admin_id, p_wallet_session_id,
    v_action, left(p_reason, 240), v_operation.operation_version, v_result
  );

  RETURN v_result;
END;
$$;

-- FUNCTION: complete_ticket_checkout_recovery_v28(uuid, uuid, text, text, text, text, timestamp with time zone, text, timestamp with time zone, timestamp with time zone)
CREATE FUNCTION public.complete_ticket_checkout_recovery_v28(p_checkout_action_id uuid, p_recovery_claim_token uuid, p_outcome text, p_provider_session_id text, p_provider_status text, p_provider_payment_status text, p_provider_expires_at timestamp with time zone, p_provider_evidence_hash text, p_provider_observed_at timestamp with time zone, p_next_attempt_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_action public.ticket_checkout_actions%ROWTYPE;
  v_order public.ticket_orders%ROWTYPE;
  v_review_reason text;
BEGIN
  IF p_checkout_action_id IS NULL
    OR p_recovery_claim_token IS NULL
    OR COALESCE(p_outcome, '') NOT IN (
      'provider_created', 'provider_open', 'provider_completion_review',
      'provider_unavailable', 'provider_binding_review',
      'provider_request_review', 'provider_outcome_unknown')
    OR COALESCE(p_provider_evidence_hash, '') !~ '^[0-9a-f]{64}$'
    OR p_provider_observed_at IS NULL
    OR p_provider_observed_at > clock_timestamp() + interval '5 minutes'
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'recovery_result_invalid');
  END IF;
  IF p_outcome IN ('provider_created', 'provider_open', 'provider_completion_review')
    AND (
      NULLIF(btrim(COALESCE(p_provider_session_id, '')), '') IS NULL
      OR COALESCE(p_provider_status, '') NOT IN ('open', 'complete', 'expired')
      OR COALESCE(p_provider_payment_status, '') NOT IN
        ('paid', 'unpaid', 'no_payment_required')
      OR p_provider_expires_at IS NULL
    )
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'recovery_provider_facts_invalid');
  END IF;
  IF p_outcome = 'provider_created'
    AND (p_provider_status = 'complete' OR p_provider_payment_status = 'paid')
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'provider_completion_review_required');
  END IF;
  IF p_outcome = 'provider_open'
    AND (p_provider_status <> 'open' OR p_provider_payment_status = 'paid')
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'provider_open_facts_invalid');
  END IF;
  IF p_outcome = 'provider_completion_review'
    AND p_provider_status <> 'complete' AND p_provider_payment_status <> 'paid'
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'provider_completion_facts_invalid');
  END IF;
  IF p_outcome IN ('provider_open', 'provider_unavailable')
    AND (
      p_next_attempt_at IS NULL
      OR p_next_attempt_at <= clock_timestamp()
      OR p_next_attempt_at > clock_timestamp() + interval '1 day'
    )
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'recovery_schedule_invalid');
  END IF;

  SELECT * INTO v_action
  FROM public.ticket_checkout_actions
  WHERE id = p_checkout_action_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('action', 'not_found'); END IF;
  IF v_action.recovery_claim_token IS DISTINCT FROM p_recovery_claim_token
    OR v_action.recovery_claim_expires_at <= clock_timestamp()
  THEN
    RETURN jsonb_build_object('action', 'fence_lost', 'reason', 'recovery_claim_lost');
  END IF;
  SELECT * INTO v_order
  FROM public.ticket_orders
  WHERE id = v_action.ticket_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'checkout_order_missing');
  END IF;
  IF p_provider_observed_at < v_action.created_at THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'provider_observation_predates_action');
  END IF;

  IF p_outcome = 'provider_unavailable' THEN
    UPDATE public.ticket_checkout_actions
    SET recovery_claim_token = NULL,
        recovery_claimed_by = NULL,
        recovery_claimed_at = NULL,
        recovery_claim_expires_at = NULL,
        recovery_next_attempt_at = p_next_attempt_at,
        recovery_last_outcome = p_outcome,
        reconciliation_count = reconciliation_count + 1,
        updated_at = now()
    WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'resolved', 'state', v_action.state,
      'nextAttemptAt', p_next_attempt_at);
  END IF;

  IF p_outcome IN (
    'provider_binding_review', 'provider_request_review', 'provider_outcome_unknown')
  THEN
    IF p_outcome = 'provider_outcome_unknown'
      AND (
        v_action.state <> 'claimed'
        OR v_action.checkout_session_id IS NOT NULL
        OR p_provider_observed_at < v_action.created_at + interval '23 hours'
      )
    THEN
      RETURN jsonb_build_object('action', 'rejected', 'reason', 'provider_retry_budget_active');
    END IF;
    v_review_reason := CASE p_outcome
      WHEN 'provider_binding_review' THEN 'provider_binding_mismatch'
      WHEN 'provider_request_review' THEN 'provider_request_unreproducible'
      ELSE 'provider_outcome_unknown' END;
    UPDATE public.ticket_checkout_actions
    SET state = 'review_required',
        review_reason = v_review_reason,
        provider_terminal_evidence_hash = p_provider_evidence_hash,
        provider_terminal_observed_at = p_provider_observed_at,
        recovery_claim_token = NULL,
        recovery_claimed_by = NULL,
        recovery_claimed_at = NULL,
        recovery_claim_expires_at = NULL,
        recovery_last_outcome = p_outcome,
        reconciliation_count = reconciliation_count + 1,
        updated_at = now()
    WHERE id = v_action.id;
    INSERT INTO public.audit_logs(
      action, actor_type, target_table, target_id,
      entity_type, entity_id, operation, reason, metadata_json
    ) VALUES (
      'ticket_checkout.reconciliation_review', 'system',
      'ticket_checkout_actions', v_action.id,
      'ticket_checkout_action', v_action.id, 'update', v_review_reason,
      jsonb_build_object(
        'orderId', v_order.id,
        'stripeAccountKey', v_action.stripe_account_key,
        'providerObservedAt', p_provider_observed_at,
        'providerEvidenceHash', p_provider_evidence_hash));
    RETURN jsonb_build_object('action', 'resolved', 'state', 'review_required',
      'reason', v_review_reason);
  END IF;

  IF p_outcome = 'provider_created' THEN
    IF v_action.state <> 'claimed' OR v_action.checkout_session_id IS NOT NULL
      OR v_order.status <> 'pending'
      OR (v_order.checkout_session_id IS NOT NULL
        AND v_order.checkout_session_id <> btrim(p_provider_session_id))
    THEN
      RETURN jsonb_build_object('action', 'rejected', 'reason', 'provider_create_state_mismatch');
    END IF;
    BEGIN
      UPDATE public.ticket_orders
      SET checkout_session_id = btrim(p_provider_session_id)
      WHERE id = v_order.id;
      UPDATE public.ticket_checkout_actions
      SET state = 'provider_created',
          checkout_session_id = btrim(p_provider_session_id),
          provider_response_hash = p_provider_evidence_hash,
          provider_expires_at = p_provider_expires_at,
          provider_attempt_count = provider_attempt_count + 1,
          recovery_claim_token = NULL,
          recovery_claimed_by = NULL,
          recovery_claimed_at = NULL,
          recovery_claim_expires_at = NULL,
          recovery_next_attempt_at = GREATEST(p_provider_expires_at, clock_timestamp()),
          recovery_last_outcome = p_outcome,
          updated_at = now()
      WHERE id = v_action.id;
    EXCEPTION WHEN unique_violation THEN
      UPDATE public.ticket_checkout_actions
      SET state = 'review_required',
          review_reason = 'provider_binding_mismatch',
          recovery_claim_token = NULL,
          recovery_claimed_by = NULL,
          recovery_claimed_at = NULL,
          recovery_claim_expires_at = NULL,
          recovery_last_outcome = 'provider_binding_review',
          updated_at = now()
      WHERE id = v_action.id;
      RETURN jsonb_build_object('action', 'resolved', 'state', 'review_required',
        'reason', 'provider_binding_mismatch');
    END;
    RETURN jsonb_build_object('action', 'resolved', 'state', 'provider_created');
  END IF;

  IF p_outcome = 'provider_open' THEN
    IF v_action.state <> 'provider_created'
      OR v_order.status <> 'pending'
      OR v_action.checkout_session_id <> btrim(p_provider_session_id)
      OR v_action.provider_expires_at <> p_provider_expires_at
    THEN
      RETURN jsonb_build_object('action', 'rejected', 'reason', 'provider_open_binding_mismatch');
    END IF;
    UPDATE public.ticket_checkout_actions
    SET recovery_claim_token = NULL,
        recovery_claimed_by = NULL,
        recovery_claimed_at = NULL,
        recovery_claim_expires_at = NULL,
        recovery_next_attempt_at = p_next_attempt_at,
        recovery_last_outcome = p_outcome,
        reconciliation_count = reconciliation_count + 1,
        updated_at = now()
    WHERE id = v_action.id;
    RETURN jsonb_build_object('action', 'resolved', 'state', 'provider_created',
      'nextAttemptAt', p_next_attempt_at);
  END IF;

  -- A complete/paid Session is never an expiry signal. Bind a newly recovered
  -- Session if necessary, then make the reconciliation obligation visible.
  IF v_action.state NOT IN ('claimed', 'provider_created')
    OR v_order.status <> 'pending'
    OR (v_action.checkout_session_id IS NOT NULL
      AND v_action.checkout_session_id <> btrim(p_provider_session_id))
    OR (v_action.provider_expires_at IS NOT NULL
      AND v_action.provider_expires_at <> p_provider_expires_at)
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'provider_completion_binding_mismatch');
  END IF;
  v_review_reason := 'provider_completion_reconciliation_required';
  BEGIN
    UPDATE public.ticket_orders
    SET checkout_session_id = COALESCE(checkout_session_id, btrim(p_provider_session_id))
    WHERE id = v_order.id
      AND (checkout_session_id IS NULL OR checkout_session_id = btrim(p_provider_session_id));
    IF NOT FOUND THEN RAISE EXCEPTION 'provider completion order binding changed'; END IF;
    UPDATE public.ticket_checkout_actions
    SET state = 'review_required',
        checkout_session_id = COALESCE(checkout_session_id, btrim(p_provider_session_id)),
        provider_response_hash = COALESCE(provider_response_hash, p_provider_evidence_hash),
        provider_expires_at = COALESCE(provider_expires_at, p_provider_expires_at),
        provider_terminal_status = p_provider_status,
        provider_terminal_evidence_hash = p_provider_evidence_hash,
        provider_terminal_observed_at = p_provider_observed_at,
        review_reason = 'provider_completion_reconciliation_required',
        recovery_claim_token = NULL,
        recovery_claimed_by = NULL,
        recovery_claimed_at = NULL,
        recovery_claim_expires_at = NULL,
        recovery_last_outcome = p_outcome,
        reconciliation_count = reconciliation_count + 1,
        updated_at = now()
    WHERE id = v_action.id;
  EXCEPTION WHEN unique_violation THEN
    v_review_reason := 'provider_binding_mismatch';
    UPDATE public.ticket_checkout_actions
    SET state = 'review_required',
        review_reason = 'provider_binding_mismatch',
        recovery_claim_token = NULL,
        recovery_claimed_by = NULL,
        recovery_claimed_at = NULL,
        recovery_claim_expires_at = NULL,
        recovery_last_outcome = 'provider_binding_review',
        updated_at = now()
    WHERE id = v_action.id;
  END;
  INSERT INTO public.audit_logs(
    action, actor_type, target_table, target_id,
    entity_type, entity_id, operation, reason, metadata_json
  ) VALUES (
    'ticket_checkout.reconciliation_review', 'system',
    'ticket_checkout_actions', v_action.id,
    'ticket_checkout_action', v_action.id, 'update',
    v_review_reason,
    jsonb_build_object(
      'orderId', v_order.id,
      'stripeAccountKey', v_action.stripe_account_key,
      'providerStatus', p_provider_status,
      'providerPaymentStatus', p_provider_payment_status,
      'providerObservedAt', p_provider_observed_at,
      'providerEvidenceHash', p_provider_evidence_hash));
  RETURN jsonb_build_object('action', 'resolved', 'state', 'review_required',
    'reason', v_review_reason);
END;
$_$;

-- FUNCTION: complete_ticket_checkout_review_action_v1(uuid, text, jsonb)
CREATE FUNCTION public.complete_ticket_checkout_review_action_v1(p_actor_admin_id uuid, p_idempotency_key text, p_response jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_updated integer;
BEGIN
  IF p_response IS NULL OR jsonb_typeof(p_response) <> 'object' THEN
    RAISE EXCEPTION 'ticket checkout review resolution response must be an object';
  END IF;

  UPDATE public.admin_action_requests
  SET response_json = p_response,
      updated_at = now()
  WHERE actor_admin_id = p_actor_admin_id
    AND action = 'resolve_ticket_checkout_review_v1'
    AND idempotency_key = btrim(p_idempotency_key)
    AND response_json IS NULL;
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> 1 THEN
    RAISE EXCEPTION 'ticket checkout review action request completion failed';
  END IF;
  RETURN p_response;
END;
$$;

