-- FUNCTION: complete_ticket_passkey_authentication_v34(uuid, uuid, text, text, text, text, bigint, bigint, uuid, text, text, text)
CREATE FUNCTION public.complete_ticket_passkey_authentication_v34(p_challenge_id uuid, p_flow_id uuid, p_flow_token text, p_flow_csrf text, p_environment text, p_credential_id text, p_expected_counter bigint, p_new_counter bigint, p_session_id uuid, p_session_token text, p_session_csrf text, p_auth_key_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c public.ticket_wallet_passkey_challenges%ROWTYPE; f public.ticket_wallet_preauth_flows%ROWTYPE; k public.ticket_wallet_credentials%ROWTYPE; h text; expiry timestamptz; at timestamptz:=clock_timestamp();
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('ticket-passkey-transition-v34',0));
 PERFORM public.ticket_wallet_gate_fence_v30();
 SELECT * INTO f FROM public.ticket_wallet_preauth_flows WHERE id=p_flow_id FOR UPDATE;
 IF NOT FOUND OR f.state<>'active' OR f.expires_at<=at OR NOT public.ticket_auth_digest_equal_v29(f.token_verifier,p_flow_token) OR NOT public.ticket_auth_digest_equal_v29(f.csrf_verifier,p_flow_csrf) THEN RETURN jsonb_build_object('action','rejected'); END IF;
 SELECT * INTO c FROM public.ticket_wallet_passkey_challenges WHERE id=p_challenge_id FOR UPDATE;
 IF NOT FOUND OR c.kind<>'authentication' OR c.preauth_flow_id<>f.id OR c.consumed_at IS NOT NULL OR c.expires_at<=at THEN RETURN jsonb_build_object('action','rejected'); END IF;
 SELECT * INTO k FROM public.ticket_wallet_credentials WHERE id=p_credential_id FOR UPDATE;
 IF NOT FOUND OR k.revoked_at IS NOT NULL OR k.rp_id<>c.rp_id OR k.counter<>p_expected_counter OR p_new_counter<k.counter THEN RETURN jsonb_build_object('action','rejected'); END IF;
 PERFORM 1 FROM public.ticket_wallet_holders WHERE id=k.holder_id AND environment=p_environment FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('action','rejected'); END IF;
 SELECT identity_email_hash INTO h FROM public.ticket_holder_email_identities WHERE holder_id=k.holder_id AND environment=p_environment;
 SELECT LEAST(at+interval '30 days',max(es.admission_closes_at+interval '8 days')) INTO expiry FROM public.ticket_holder_orders g JOIN public.ticket_orders o ON o.id=g.ticket_order_id JOIN public.ticket_event_sessions es ON es.id=o.event_session_id
 WHERE g.holder_id=k.holder_id AND o.environment=p_environment AND o.status='fulfilled' AND es.enabled AND es.admission_state<>'cancelled';
 IF h IS NULL OR expiry IS NULL OR expiry<=at THEN RETURN jsonb_build_object('action','rejected'); END IF;
 UPDATE public.ticket_wallet_credentials SET counter=p_new_counter,last_used_at=at WHERE id=k.id;
 INSERT INTO public.ticket_wallet_sessions(id,environment,identity_email_hash,auth_key_id,token_verifier,csrf_verifier,verified_at,fresh_until,expires_at,created_at,updated_at,holder_id,credential_id,auth_method)
 VALUES(p_session_id,p_environment,h,p_auth_key_id,p_session_token,p_session_csrf,at,LEAST(at+interval '12 hours',expiry),expiry,at,at,k.holder_id,k.id,'passkey');
 UPDATE public.ticket_wallet_passkey_challenges SET consumed_at=at WHERE id=c.id;
 UPDATE public.ticket_wallet_preauth_flows SET state='consumed',token_verifier=NULL,csrf_verifier=NULL,consumed_at=at,terminal_at=at,updated_at=at WHERE id=f.id;
 UPDATE public.ticket_wallet_sessions SET revoked_at=at,revocation_reason='session_limit',token_verifier=NULL,csrf_verifier=NULL,updated_at=at WHERE id IN
 (SELECT id FROM public.ticket_wallet_sessions WHERE holder_id=k.holder_id AND revoked_at IS NULL ORDER BY verified_at DESC,id DESC OFFSET 3);
 INSERT INTO public.ticket_wallet_credential_audits(holder_id,session_id,action) VALUES(k.holder_id,p_session_id,'authenticated');
 RETURN jsonb_build_object('action','authenticated','expiresAt',expiry,'freshUntil',LEAST(at+interval '12 hours',expiry));
END; $$;

-- FUNCTION: complete_ticket_passkey_registration_v34(uuid, uuid, text, text, text, bytea, bigint, text[], text, boolean)
CREATE FUNCTION public.complete_ticket_passkey_registration_v34(p_challenge_id uuid, p_session_id uuid, p_token text, p_csrf text, p_credential_id text, p_public_key bytea, p_counter bigint, p_transports text[], p_device_type text, p_backed_up boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c public.ticket_wallet_passkey_challenges%ROWTYPE; s public.ticket_wallet_sessions%ROWTYPE; at timestamptz:=clock_timestamp();
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('ticket-passkey-transition-v34',0));
 SELECT * INTO s FROM public.ticket_wallet_sessions WHERE id=p_session_id FOR UPDATE;
 IF NOT FOUND OR s.revoked_at IS NOT NULL OR s.expires_at<=at OR s.verified_at<at-interval '5 minutes'
 OR NOT public.ticket_auth_digest_equal_v29(s.token_verifier,p_token) OR NOT public.ticket_auth_digest_equal_v29(s.csrf_verifier,p_csrf) THEN RETURN jsonb_build_object('action','rejected'); END IF;
 SELECT * INTO c FROM public.ticket_wallet_passkey_challenges WHERE id=p_challenge_id FOR UPDATE;
 IF NOT FOUND OR c.kind<>'registration' OR c.session_id<>s.id OR c.holder_id<>s.holder_id OR c.consumed_at IS NOT NULL OR c.expires_at<=at THEN RETURN jsonb_build_object('action','rejected'); END IF;
 PERFORM 1 FROM public.ticket_wallet_holders WHERE id=s.holder_id FOR UPDATE;
 IF (SELECT count(*) FROM public.ticket_wallet_credentials WHERE holder_id=s.holder_id AND revoked_at IS NULL)>=10 THEN RETURN jsonb_build_object('action','credential_limit'); END IF;
 INSERT INTO public.ticket_wallet_credentials(id,holder_id,public_key,counter,transports,rp_id,device_type,backed_up)
 VALUES(p_credential_id,s.holder_id,p_public_key,p_counter,p_transports,c.rp_id,p_device_type,p_backed_up);
 UPDATE public.ticket_wallet_passkey_challenges SET consumed_at=at WHERE id=c.id;
 INSERT INTO public.ticket_wallet_credential_audits(holder_id,session_id,action) VALUES(s.holder_id,s.id,'registered');
 RETURN jsonb_build_object('action','registered');
END; $$;

