CREATE FUNCTION public.complete_ticket_wallet_manager_action_v29(p_actor_admin_id uuid, p_action text, p_idempotency_key text, p_response jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_updated integer;
BEGIN
  IF p_action NOT IN (
      'manager_revoke_ticket_wallet_session_v29',
      'manager_retry_transactional_email_job_v29'
    )
    OR p_response IS NULL OR jsonb_typeof(p_response) <> 'object'
    OR p_response ->> 'action' IS NULL
  THEN
