$$;

-- FUNCTION: confirm_admin_reservation_v7(uuid, text, text, text, text, uuid, text)
CREATE FUNCTION public.confirm_admin_reservation_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_reservation reservations%ROWTYPE;
  v_slot booking_slots%ROWTYPE;
  v_confirmed_count int := 0;
  v_response jsonb;
BEGIN
  SELECT * INTO v_admin FROM admin_users WHERE id = p_actor_admin_id FOR UPDATE;
  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;
  IF v_admin.role NOT IN ('manager','owner','engineer') THEN
    RAISE EXCEPTION 'admin role cannot confirm reservations';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;
    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  SELECT * INTO v_reservation FROM reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND OR v_reservation.status IN ('cancelled','hold_expired','payment_window_expired','failed','checked_in') THEN
    RAISE EXCEPTION 'reservation cannot be confirmed';
  END IF;

  SELECT * INTO v_slot FROM booking_slots WHERE id = v_reservation.booking_slot_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'booking slot not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM reservation_resources rr
    WHERE rr.reservation_id = v_reservation.id
      AND rr.lock_status IN ('held','payment_grace_locked','confirmed')
  ) THEN
    RAISE EXCEPTION 'reservation has no active resource assignment';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM reservation_resources rr
    JOIN reservations r ON r.id = rr.reservation_id
    JOIN booking_slots locked_slot ON locked_slot.id = r.booking_slot_id
    JOIN reservation_resources current_rr ON current_rr.seat_resource_id = rr.seat_resource_id
    WHERE current_rr.reservation_id = v_reservation.id
      AND rr.reservation_id <> v_reservation.id
      AND locked_slot.start_at < v_slot.end_at
      AND locked_slot.end_at > v_slot.start_at
      AND rr.lock_status IN ('held','payment_grace_locked','confirmed')
      AND r.status NOT IN ('cancelled','hold_expired','payment_window_expired','failed')
      AND (
        rr.lock_status = 'confirmed'
        OR COALESCE(rr.hold_expires_at, rr.admin_hold_expires_at, r.hold_expires_at, r.admin_hold_expires_at, 'infinity'::timestamptz) > now()
      )
  ) THEN
    RAISE EXCEPTION 'reservation resource conflict';
  END IF;

  UPDATE reservation_resources
  SET lock_status = 'confirmed',
      confirmed_at = COALESCE(confirmed_at, now()),
      released_at = NULL,
      updated_at = now()
  WHERE reservation_id = v_reservation.id
    AND lock_status IN ('held','payment_grace_locked','confirmed');

  GET DIAGNOSTICS v_confirmed_count = ROW_COUNT;

  UPDATE reservations
  SET status = 'confirmed',
      confirmed_at = COALESCE(confirmed_at, now()),
      updated_at = now()
  WHERE id = v_reservation.id;

  INSERT INTO notification_jobs(reservation_id, channel, payload_json)
  VALUES (
    v_reservation.id,
    'line',
    jsonb_build_object(
      'template', 'admin_reservation_confirmed',
      'reservationId', v_reservation.id,
      'confirmedResourceCount', v_confirmed_count
    )
  );

  v_response := jsonb_build_object('reservationId', v_reservation.id, 'confirmedResourceCount', v_confirmed_count);

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'reservations', v_reservation.id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'confirmed', 'response', v_response);
END;
$$;

-- FUNCTION: confirm_admin_reservation_v8(uuid, text, text, text, uuid, bigint, text)
CREATE FUNCTION public.confirm_admin_reservation_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_version bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation.confirmed';
  v_step jsonb;
  v_reservation public.reservations%ROWTYPE;
  v_assignment record;
  v_confirmed_count int;
  v_new_version bigint;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_warnings jsonb := '[]'::jsonb;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;
    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(p_actor_admin_id, 'reservation_assignment.write'),
      ARRAY['allowed']
    );
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'requestId')
        )), ARRAY['allowed']
      );
    END IF;
    v_step := public.assert_reservation_version_v8(p_reservation_id, p_expected_version);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
    SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id;
    IF v_reservation.status NOT IN (
      'draft', 'pending', 'pending_card_setup', 'pending_deposit',
      'admin_hold', 'admin_hold_review'
    )
      OR v_reservation.service_status IN ('completed', 'no_show')
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION',
          'details', jsonb_build_object('fromStatus', v_reservation.status, 'toStatus', 'confirmed')
        )), ARRAY['allowed']
      );
    END IF;

    PERFORM sr.id FROM public.seat_resources AS sr
    WHERE EXISTS (
      SELECT 1 FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id
        AND rr.seat_resource_id = sr.id
        AND public.active_reservation_assignment_v8(rr.id, now())
    )
    ORDER BY sr.id FOR UPDATE OF sr;
    PERFORM rr.id FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
       OR (
         rr.seat_resource_id IN (
           SELECT current_rr.seat_resource_id
           FROM public.reservation_resources AS current_rr
           WHERE current_rr.reservation_id = v_reservation.id
             AND public.active_reservation_assignment_v8(current_rr.id, now())
         )
         AND rr.assigned_start_at < v_reservation.expected_release_at
         AND rr.assigned_end_at > v_reservation.scheduled_start_at
       )
    ORDER BY rr.id FOR UPDATE OF rr;
    PERFORM rb.id
    FROM public.reservation_blocks AS rb
    WHERE rb.event_day_id = v_reservation.event_day_id
      AND rb.status = 'active'
      AND rb.start_at < v_reservation.expected_release_at
      AND rb.end_at > v_reservation.scheduled_start_at
      AND EXISTS (
        SELECT 1
        FROM public.reservation_block_targets AS rbt
        JOIN public.reservation_resources AS rr ON rr.reservation_id = v_reservation.id
        JOIN public.seat_resources AS sr ON sr.id = rr.seat_resource_id
        WHERE rbt.block_id = rb.id
          AND (rbt.seat_resource_id = sr.id OR rbt.floor_section_id = sr.floor_section_id OR rbt.venue_wide)
      )
    ORDER BY rb.id FOR UPDATE OF rb;
    IF NOT EXISTS (
      SELECT 1 FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id
        AND public.active_reservation_assignment_v8(rr.id, now())
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION', 'details', jsonb_build_object('reason', 'active_assignment_required')
        )), ARRAY['allowed']
      );
    END IF;
    FOR v_assignment IN
      SELECT rr.* FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id
        AND public.active_reservation_assignment_v8(rr.id, now())
      ORDER BY rr.id
    LOOP
      v_step := public.assert_assignment_conflict_free_v8(
        v_reservation.event_day_id, v_reservation.id, v_assignment.seat_resource_id,
        v_reservation.scheduled_start_at, v_reservation.expected_release_at, now()
      );
      PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
      SELECT COALESCE(jsonb_agg(warning ORDER BY warning::text), '[]'::jsonb)
      INTO v_warnings
      FROM (
        SELECT DISTINCT warning FROM jsonb_array_elements(
          v_warnings || COALESCE(v_step -> 'warnings', '[]'::jsonb)
        ) AS all_warnings(warning)
      ) AS deduplicated;
    END LOOP;

    UPDATE public.reservation_resources AS rr
    SET lock_status = 'confirmed', confirmed_at = COALESCE(confirmed_at, now()),
        released_at = NULL, version = rr.version + 1, updated_at = now()
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now());
    GET DIAGNOSTICS v_confirmed_count = ROW_COUNT;
    IF v_reservation.service_status IS DISTINCT FROM 'expected'::public.vip_service_status THEN
      INSERT INTO public.reservation_service_events(
        reservation_id, from_status, to_status, occurred_at,
        actor_admin_id, reason, request_id, metadata_json
      ) VALUES (
        v_reservation.id, v_reservation.service_status, 'expected', now(),
        p_actor_admin_id, p_reason, p_request_id, jsonb_build_object('source', 'confirm')
      );
    END IF;
    UPDATE public.reservations
    SET status = 'confirmed', confirmed_at = COALESCE(confirmed_at, now()),
        service_status = 'expected', service_status_changed_at = now(),
        service_completed_at = NULL,
        version = version + 1, updated_at = now()
    WHERE id = v_reservation.id RETURNING version INTO v_new_version;
    INSERT INTO public.notification_jobs(reservation_id, channel, payload_json)
    VALUES (
      v_reservation.id, 'line',
      jsonb_build_object('template', 'admin_reservation_confirmed', 'reservationId', v_reservation.id)
    );

    PERFORM ed.id FROM public.event_days AS ed
    WHERE ed.id = v_reservation.event_day_id FOR KEY SHARE OF ed;
    PERFORM public.lock_vip_floor_day_revision_v32(v_reservation.event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1 INTO v_predicted_revision
    FROM (SELECT 1) AS seed LEFT JOIN public.vip_floor_day_revisions AS vfr
      ON vfr.event_day_id = v_reservation.event_day_id;
    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, v_reservation.event_day_id, v_reservation.id,
      'reservation', v_reservation.id, v_action, p_request_id, p_reason,
      p_expected_version, v_reservation.version, v_new_version,
      ARRAY['status', 'confirmed_at', 'service_status', 'version'],
      jsonb_build_object('status', v_reservation.status, 'serviceStatus', v_reservation.service_status, 'version', v_reservation.version),
      jsonb_build_object('status', 'confirmed', 'serviceStatus', 'expected', 'version', v_new_version),
      jsonb_build_object('confirmedAssignmentCount', v_confirmed_count, 'warnings', v_warnings)
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_response := jsonb_build_object(
      'ok', true, 'action', v_action, 'reused', false,
      'reservationId', v_reservation.id, 'entityVersion', v_new_version,
      'boardRevision', v_predicted_revision, 'auditLogId', v_audit_id,
      'confirmedAssignmentCount', v_confirmed_count, 'warnings', v_warnings
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(v_reservation.event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'XX000', MESSAGE = 'VIP floor revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS v_error_detail = PG_EXCEPTION_DETAIL, v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN RETURN v_error_detail::jsonb; END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: confirm_reservation_locks_v7(text, text, text, text, text, jsonb)
CREATE FUNCTION public.confirm_reservation_locks_v7(p_environment text, p_stripe_account_id text, p_provider_object_type text, p_provider_object_id text, p_provider_status text, p_payload_json jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_binding stripe_intent_bindings%ROWTYPE;
  v_reservation reservations%ROWTYPE;
  v_payment payments%ROWTYPE;
  v_conflict_count int := 0;
  v_released_count int := 0;
  v_confirmed_count int := 0;
  v_late boolean := false;
  v_refund_case_id uuid;
  v_failure_status reservation_status;
  v_payment_method_id text;
  v_payment_method_row_id uuid;
  v_stripe_customer_id text;
  v_stripe_charge_id text;
BEGIN
  PERFORM expire_public_reservation_holds_v7();

  SELECT * INTO v_binding
  FROM stripe_intent_bindings
  WHERE environment = p_environment
    AND stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
    AND provider_object_type = p_provider_object_type
    AND provider_object_id = p_provider_object_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'action', 'ignored',
      'reason', 'stripe_intent_binding_not_found',
      'providerObjectType', p_provider_object_type,
      'providerObjectId', p_provider_object_id
    );
  END IF;

  SELECT * INTO v_reservation
  FROM reservations
  WHERE id = v_binding.reservation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'action', 'ignored',
      'reason', 'reservation_not_found',
      'bindingId', v_binding.id
    );
  END IF;

  SELECT * INTO v_payment
  FROM payments
  WHERE id = v_binding.payment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'action', 'ignored',
      'reason', 'payment_not_found',
      'bindingId', v_binding.id
    );
  END IF;

  PERFORM 1
  FROM reservation_resources rr
  JOIN seat_resources sr ON sr.id = rr.seat_resource_id
  WHERE rr.reservation_id = v_reservation.id
  FOR UPDATE OF sr;

  IF p_provider_status IN ('succeeded') THEN
    v_late := COALESCE(v_reservation.hold_expires_at <= now(), false)
      AND v_reservation.status <> 'confirmed';

    SELECT COUNT(*) INTO v_conflict_count
    FROM reservation_resources rr
    JOIN reservations r ON r.id = rr.reservation_id
    JOIN reservation_resources current_rr ON current_rr.seat_resource_id = rr.seat_resource_id
    WHERE current_rr.reservation_id = v_reservation.id
      AND rr.reservation_id <> v_reservation.id
      AND r.booking_slot_id = v_reservation.booking_slot_id
      AND rr.lock_status IN ('held','payment_grace_locked','confirmed')
      AND r.status NOT IN ('cancelled','hold_expired','payment_window_expired','failed')
      AND (
        rr.lock_status = 'confirmed'
        OR COALESCE(
          rr.hold_expires_at,
          rr.admin_hold_expires_at,
          r.hold_expires_at,
          r.admin_hold_expires_at,
          'infinity'::timestamptz
        ) > now()
      );

    v_payment_method_id := NULLIF(COALESCE(
      p_payload_json #>> '{data,object,payment_method}',
      p_payload_json ->> 'payment_method'
    ), '');

    v_stripe_charge_id := NULLIF(COALESCE(
      p_payload_json #>> '{data,object,latest_charge}',
      p_payload_json ->> 'latest_charge',
      v_payment.stripe_charge_id
    ), '');

    v_stripe_customer_id := COALESCE(
      v_payment.stripe_customer_id,
      (
        SELECT c.stripe_customer_id
        FROM customers c
        WHERE c.id = v_reservation.customer_id
      )
    );

    IF v_payment_method_id IS NOT NULL
      AND v_reservation.customer_id IS NOT NULL
      AND v_stripe_customer_id IS NOT NULL THEN
      INSERT INTO payment_methods(
        customer_id,
        environment,
        stripe_account_id,
        stripe_customer_id,
        stripe_payment_method_id,
        status
      )
      VALUES (
        v_reservation.customer_id,
        v_payment.environment,
        v_payment.stripe_account_id,
        v_stripe_customer_id,
        v_payment_method_id,
        'active'
      )
      ON CONFLICT (environment, stripe_account_key, stripe_payment_method_id)
      DO UPDATE
      SET status = 'active',
          stripe_customer_id = EXCLUDED.stripe_customer_id,
          updated_at = now()
      RETURNING id INTO v_payment_method_row_id;
    END IF;

    UPDATE payments
    SET status = 'succeeded',
        provider_object_type = p_provider_object_type,
        provider_object_id = p_provider_object_id,
        stripe_payment_method_id = COALESCE(v_payment_method_id, stripe_payment_method_id),
        stripe_charge_id = COALESCE(v_stripe_charge_id, stripe_charge_id),
        payment_method_id = COALESCE(v_payment_method_row_id, payment_method_id),
        updated_at = now()
    WHERE id = v_payment.id;

    IF v_conflict_count > 0 THEN
      UPDATE reservation_resources
      SET lock_status = 'released',
          released_at = now(),
          updated_at = now()
      WHERE reservation_id = v_reservation.id
        AND lock_status IN ('held','payment_grace_locked','expired');

      GET DIAGNOSTICS v_released_count = ROW_COUNT;

      IF v_payment.type = 'deposit' AND v_payment.amount_yen > 0 THEN
        UPDATE reservations
        SET status = 'refund_required',
            updated_at = now()
        WHERE id = v_reservation.id;

        INSERT INTO refund_cases(
          reservation_id,
          payment_id,
          amount_yen,
          currency,
          reason,
          status,
          environment,
          stripe_account_id,
          idempotency_key,
          stripe_idempotency_key
        )
        SELECT
          v_reservation.id,
          v_payment.id,
          v_payment.amount_yen,
          v_payment.currency,
          'inventory_lost_after_payment_success',
          'required',
          v_payment.environment,
          v_payment.stripe_account_id,
          'refund_required:' || v_payment.id,
          'stripe_refund:' || v_payment.id
        WHERE NOT EXISTS (
          SELECT 1
          FROM refund_cases rc
          WHERE rc.payment_id = v_payment.id
            AND rc.reason = 'inventory_lost_after_payment_success'
        )
        RETURNING id INTO v_refund_case_id;

        RETURN jsonb_build_object(
          'action', 'refund_required',
          'reservationId', v_reservation.id,
          'paymentId', v_payment.id,
          'conflictCount', v_conflict_count,
          'releasedResourceCount', v_released_count,
          'refundCaseId', v_refund_case_id
        );
      END IF;

      UPDATE reservations
      SET status = CASE
            WHEN v_payment.type = 'card_setup' THEN 'card_saved_inventory_lost'::reservation_status
            ELSE 'inventory_conflict_review'::reservation_status
          END,
          updated_at = now()
      WHERE id = v_reservation.id;

      RETURN jsonb_build_object(
        'action', 'inventory_lost',
        'reservationId', v_reservation.id,
        'paymentId', v_payment.id,
        'conflictCount', v_conflict_count,
        'releasedResourceCount', v_released_count
      );
    END IF;

    UPDATE reservation_resources
    SET lock_status = 'confirmed',
        confirmed_at = COALESCE(confirmed_at, now()),
        released_at = NULL,
        updated_at = now()
    WHERE reservation_id = v_reservation.id
      AND lock_status IN ('held','payment_grace_locked','expired');

    GET DIAGNOSTICS v_confirmed_count = ROW_COUNT;

    UPDATE reservations
    SET status = 'confirmed',
        confirmed_at = COALESCE(confirmed_at, now()),
        updated_at = now()
    WHERE id = v_reservation.id;

    INSERT INTO ledger_entries(reservation_id, payment_id, entry_type, amount_yen, currency)
    SELECT v_reservation.id, v_payment.id, 'deposit_succeeded', v_payment.amount_yen, v_payment.currency
    WHERE v_payment.type = 'deposit'
      AND v_payment.amount_yen > 0
      AND NOT EXISTS (
        SELECT 1
        FROM ledger_entries le
        WHERE le.payment_id = v_payment.id
          AND le.entry_type = 'deposit_succeeded'
      );

    INSERT INTO notification_jobs(reservation_id, channel, payload_json)
    VALUES (
      v_reservation.id,
      'line',
      jsonb_build_object(
        'template', 'reservation_confirmed',
        'reservationId', v_reservation.id,
        'paymentId', v_payment.id,
        'wasLate', v_late
      )
    );

    RETURN jsonb_build_object(
      'action', CASE WHEN v_late THEN 'late_relocked_confirmed' ELSE 'confirmed' END,
      'reservationId', v_reservation.id,
      'paymentId', v_payment.id,
      'confirmedResourceCount', v_confirmed_count,
      'wasLate', v_late
    );
  END IF;

  IF p_provider_status IN ('requires_payment_method','failed','setup_failed','canceled','cancelled') THEN
    UPDATE payments
    SET status = CASE
          WHEN p_provider_status IN ('canceled','cancelled') THEN 'cancelled'::payment_status
          ELSE 'failed'::payment_status
        END,
        provider_object_type = p_provider_object_type,
        provider_object_id = p_provider_object_id,
        updated_at = now()
    WHERE id = v_payment.id;

    UPDATE reservation_resources
    SET lock_status = 'released',
        released_at = now(),
        updated_at = now()
    WHERE reservation_id = v_reservation.id
      AND lock_status IN ('held','payment_grace_locked');

    GET DIAGNOSTICS v_released_count = ROW_COUNT;

    v_failure_status := CASE
      WHEN p_provider_status IN ('canceled','cancelled') THEN 'cancelled'::reservation_status
      ELSE 'failed'::reservation_status
    END;

    UPDATE reservations
    SET status = v_failure_status,
        updated_at = now()
    WHERE id = v_reservation.id
      AND status NOT IN ('confirmed','checked_in','cancelled');

    RETURN jsonb_build_object(
      'action', 'released_after_payment_failure',
      'reservationId', v_reservation.id,
      'paymentId', v_payment.id,
      'releasedResourceCount', v_released_count,
      'providerStatus', p_provider_status
    );
  END IF;

  RETURN jsonb_build_object(
    'action', 'ignored',
    'reason', 'provider_status_not_actionable',
    'reservationId', v_reservation.id,
    'paymentId', v_payment.id,
    'providerStatus', p_provider_status
  );
END;
$$;

-- FUNCTION: consume_ticket_checkout_rate_limit_v28(text, text, timestamp with time zone)
CREATE FUNCTION public.consume_ticket_checkout_rate_limit_v28(p_ip_hash text, p_user_agent_hash text, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_bucket record;
  v_window_started_at timestamptz;
  v_attempt_count integer;
  v_limited jsonb := NULL;
BEGIN
  IF COALESCE(p_ip_hash, '') !~ '^[0-9a-f]{64}$'
    OR COALESCE(p_user_agent_hash, '') !~ '^[0-9a-f]{64}$'
    OR p_now IS NULL
    OR p_now > clock_timestamp() + interval '5 minutes'
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'rate_limit_input_invalid');
  END IF;

  -- The ordinal is a global lock order. Every caller touches the same shared
  -- rows before the narrower rows, so concurrent boundaries cannot deadlock.
  FOR v_bucket IN
    SELECT * FROM (
      VALUES
        (1, 'global_minute'::text, 'global'::text, 60, 120),
        (2, 'global_day'::text, 'global'::text, 86400, 2000),
        (3, 'ip_ten_minutes'::text, p_ip_hash, 600, 20),
        (4, 'ip_day'::text, p_ip_hash, 86400, 100),
        (5, 'user_agent_ten_minutes'::text, p_user_agent_hash, 600, 60)
    ) AS policy(ordinal, bucket_type, bucket_key_hash, window_seconds, maximum_attempts)
    ORDER BY ordinal
  LOOP
    v_window_started_at := to_timestamp(
      floor(extract(epoch FROM p_now) / v_bucket.window_seconds)
        * v_bucket.window_seconds
    );
    INSERT INTO public.ticket_checkout_rate_limit_buckets(
      bucket_type, bucket_key_hash, window_started_at, window_seconds,
      attempt_count, updated_at
    ) VALUES (
      v_bucket.bucket_type, v_bucket.bucket_key_hash, v_window_started_at,
      v_bucket.window_seconds, 1, p_now
    )
    ON CONFLICT (bucket_type, bucket_key_hash, window_started_at, window_seconds)
    DO UPDATE SET
      attempt_count = public.ticket_checkout_rate_limit_buckets.attempt_count + 1,
      updated_at = EXCLUDED.updated_at
    RETURNING attempt_count INTO v_attempt_count;

    IF v_limited IS NULL AND v_attempt_count > v_bucket.maximum_attempts THEN
      v_limited := jsonb_build_object(
        'action', 'rate_limited',
        'bucketType', v_bucket.bucket_type,
        'retryAfterSeconds', GREATEST(
          1,
          v_bucket.window_seconds
            - floor(extract(epoch FROM (p_now - v_window_started_at)))::integer
        )
      );
    END IF;
  END LOOP;

  RETURN COALESCE(v_limited, jsonb_build_object('action', 'allowed'));
END;
$_$;

-- FUNCTION: consume_ticket_checkout_replay_budget_v1(text, text, text, text, text, timestamp with time zone)
CREATE FUNCTION public.consume_ticket_checkout_replay_budget_v1(p_environment text, p_stripe_account_key text, p_idempotency_key_hash text, p_ip_hash text, p_user_agent_hash text, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_bucket record;
  v_key_hash text;
  v_window_started_at timestamptz;
  v_attempt_count integer;
  v_limited jsonb := NULL;
BEGIN
  IF COALESCE(p_environment, '') NOT IN ('test', 'live')
    OR COALESCE(p_stripe_account_key, '') !~ '^(platform|acct_[A-Za-z0-9]{1,64})$'
    OR COALESCE(p_idempotency_key_hash, '') !~ '^[0-9a-f]{64}$'
    OR COALESCE(p_ip_hash, '') !~ '^[0-9a-f]{64}$'
    OR COALESCE(p_user_agent_hash, '') !~ '^[0-9a-f]{64}$'
    OR p_now IS NULL
    OR p_now > clock_timestamp() + interval '5 minutes'
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'replay_budget_input_invalid');
  END IF;

  -- The per-action digest derives from the triple the claim RPC binds, so a
  -- budget row can never collide across environment or Stripe account.
  v_key_hash := pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
    p_environment || ':' || p_stripe_account_key || ':' || p_idempotency_key_hash,
    'UTF8'), 'sha256'), 'hex');

  -- Ordinal keeps a global lock order: every caller touches the same shared
  -- rows before the narrower rows, so concurrent boundaries cannot deadlock.
  FOR v_bucket IN
    SELECT * FROM (
      VALUES
        (1, 'replay_global_minute'::text, 'global'::text, 60, 300),
        (2, 'replay_ip_ten_minutes'::text, p_ip_hash, 600, 60),
        (3, 'replay_ip_day'::text, p_ip_hash, 86400, 300),
        (4, 'replay_key_minute'::text, v_key_hash, 60, 12),
        (5, 'replay_key_hour'::text, v_key_hash, 3600, 120)
    ) AS policy(ordinal, bucket_type, bucket_key_hash, window_seconds, maximum_attempts)
    ORDER BY ordinal
  LOOP
    v_window_started_at := to_timestamp(
      floor(extract(epoch FROM p_now) / v_bucket.window_seconds)
        * v_bucket.window_seconds
    );
    INSERT INTO public.ticket_checkout_rate_limit_buckets(
      bucket_type, bucket_key_hash, window_started_at, window_seconds,
      attempt_count, updated_at
    ) VALUES (
      v_bucket.bucket_type, v_bucket.bucket_key_hash, v_window_started_at,
      v_bucket.window_seconds, 1, p_now
    )
    ON CONFLICT (bucket_type, bucket_key_hash, window_started_at, window_seconds)
    DO UPDATE SET
      attempt_count = public.ticket_checkout_rate_limit_buckets.attempt_count + 1,
      updated_at = EXCLUDED.updated_at
    RETURNING attempt_count INTO v_attempt_count;

    IF v_limited IS NULL AND v_attempt_count > v_bucket.maximum_attempts THEN
      v_limited := jsonb_build_object(
        'action', 'rate_limited',
        'bucketType', v_bucket.bucket_type,
        'retryAfterSeconds', GREATEST(
          1,
          v_bucket.window_seconds
            - floor(extract(epoch FROM (p_now - v_window_started_at)))::integer
        )
      );
    END IF;
  END LOOP;

  RETURN COALESCE(v_limited, jsonb_build_object('action', 'allowed'));
END;
$_$;

-- FUNCTION: consume_ticket_wallet_rate_limit_v29(text, text, integer, integer)
CREATE FUNCTION public.consume_ticket_wallet_rate_limit_v29(p_bucket_name text, p_bucket_hash text, p_window_seconds integer, p_maximum_count integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_bucket public.ticket_wallet_rate_limit_buckets%ROWTYPE;
BEGIN
  IF p_bucket_name IS NULL OR p_bucket_name !~ '^[a-z0-9_]{1,64}$'
    OR p_bucket_hash IS NULL OR char_length(p_bucket_hash) NOT BETWEEN 3 AND 256
    OR p_window_seconds NOT BETWEEN 1 AND 86400
    OR p_maximum_count NOT BETWEEN 1 AND 1000000
  THEN
    RAISE EXCEPTION 'invalid Ticket Wallet rate bucket';
  END IF;

  INSERT INTO public.ticket_wallet_rate_limit_buckets(
    bucket_name, bucket_hash, window_seconds, maximum_count, request_count,
    window_started_at, window_expires_at, blocked_until, created_at, updated_at
  ) VALUES (
    p_bucket_name, p_bucket_hash, p_window_seconds, p_maximum_count, 1,
    v_now, v_now + make_interval(secs => p_window_seconds), NULL, v_now, v_now
  )
  ON CONFLICT (bucket_name, bucket_hash) DO NOTHING;

  SELECT * INTO v_bucket
  FROM public.ticket_wallet_rate_limit_buckets
  WHERE bucket_name = p_bucket_name AND bucket_hash = p_bucket_hash
  FOR UPDATE;

  IF v_bucket.window_expires_at <= v_now THEN
    UPDATE public.ticket_wallet_rate_limit_buckets
    SET window_seconds = p_window_seconds,
        maximum_count = p_maximum_count,
        request_count = 1,
        window_started_at = v_now,
        window_expires_at = v_now + make_interval(secs => p_window_seconds),
        blocked_until = NULL,
        updated_at = v_now
    WHERE bucket_name = p_bucket_name AND bucket_hash = p_bucket_hash;
    RETURN true;
  END IF;

  IF v_bucket.window_seconds <> p_window_seconds
    OR v_bucket.maximum_count <> p_maximum_count
  THEN
    RAISE EXCEPTION 'active Ticket Wallet rate bucket configuration mismatch';
  END IF;

  -- The INSERT path has already consumed the first token.
  IF v_bucket.created_at = v_now AND v_bucket.request_count = 1 THEN
    RETURN true;
  END IF;

  UPDATE public.ticket_wallet_rate_limit_buckets
  SET request_count = request_count + 1,
      blocked_until = CASE WHEN request_count + 1 > maximum_count
        THEN window_expires_at ELSE blocked_until END,
      updated_at = v_now
  WHERE bucket_name = p_bucket_name AND bucket_hash = p_bucket_hash
  RETURNING * INTO v_bucket;

  RETURN v_bucket.request_count <= v_bucket.maximum_count;
END;
$_$;

-- FUNCTION: create_admin_late_cancel_case_v7(uuid, text, text, text, text, uuid, integer, jsonb, text)
CREATE FUNCTION public.create_admin_late_cancel_case_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_charge_amount_yen integer, p_evidence_json jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_reservation reservations%ROWTYPE;
  v_terms reservation_charge_terms%ROWTYPE;
  v_case_id uuid;
  v_amount int;
  v_released_count int := 0;
  v_response jsonb;
BEGIN
  SELECT * INTO v_admin FROM admin_users WHERE id = p_actor_admin_id FOR UPDATE;
  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;
  IF v_admin.role NOT IN ('staff','manager','owner','engineer') THEN
    RAISE EXCEPTION 'admin role cannot report late cancellations';
  END IF;

  -- W07-G-49: filing a money-affecting case requires a non-empty reason.
  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'reason is required to report a late-cancel case';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;
    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  IF p_charge_amount_yen < 0 THEN
    RAISE EXCEPTION 'invalid late-cancel charge amount';
  END IF;

  SELECT * INTO v_reservation FROM reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND OR v_reservation.status NOT IN ('confirmed','checked_in') THEN
    RAISE EXCEPTION 'reservation cannot be reported as late-cancel';
  END IF;

  SELECT * INTO v_terms FROM reservation_charge_terms WHERE reservation_id = v_reservation.id;
  v_amount := COALESCE(NULLIF(p_charge_amount_yen, 0), v_terms.agreed_late_cancel_fee_yen, 0);

  -- W07-G-01: cap at the consented snapshot; missing terms -> only 0.
  IF v_amount > COALESCE(v_terms.agreed_late_cancel_fee_yen, 0) THEN
    RAISE EXCEPTION 'charge amount exceeds consented late-cancel fee'
      USING ERRCODE = 'P0001',
            DETAIL = 'agreed_late_cancel_fee_yen=' || COALESCE(v_terms.agreed_late_cancel_fee_yen, 0);
  END IF;

  INSERT INTO late_cancel_cases(
    reservation_id,
    reported_by_admin_id,
    charge_amount_yen,
    evidence_json
  )
  VALUES (v_reservation.id, p_actor_admin_id, v_amount, COALESCE(p_evidence_json, '{}'::jsonb))
  RETURNING id INTO v_case_id;

  UPDATE reservation_resources
  SET lock_status = 'released',
      released_at = now(),
      updated_at = now()
  WHERE reservation_id = v_reservation.id
    AND lock_status IN ('held','payment_grace_locked','confirmed');

  GET DIAGNOSTICS v_released_count = ROW_COUNT;

  UPDATE reservations
  SET status = 'late_cancel_review',
      updated_at = now()
  WHERE id = v_reservation.id;

  INSERT INTO notification_jobs(reservation_id, channel, payload_json)
  VALUES (
    v_reservation.id,
    'line',
    jsonb_build_object(
      'template', 'late_cancel_reported',
      'reservationId', v_reservation.id,
      'caseId', v_case_id,
      'chargeAmountYen', v_amount
    )
  );

  v_response := jsonb_build_object(
    'reservationId', v_reservation.id,
    'caseId', v_case_id,
    'chargeAmountYen', v_amount,
    'releasedResourceCount', v_released_count
  );

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'late_cancel_cases', v_case_id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'reported', 'response', v_response);
END;
$$;

-- FUNCTION: create_admin_no_show_case_v7(uuid, text, text, text, text, uuid, integer, jsonb, text)
CREATE FUNCTION public.create_admin_no_show_case_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_charge_amount_yen integer, p_evidence_json jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_reservation reservations%ROWTYPE;
  v_terms reservation_charge_terms%ROWTYPE;
  v_case_id uuid;
  v_amount int;
  v_response jsonb;
BEGIN
  SELECT * INTO v_admin FROM admin_users WHERE id = p_actor_admin_id FOR UPDATE;
  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;
  IF v_admin.role NOT IN ('staff','manager','owner','engineer') THEN
    RAISE EXCEPTION 'admin role cannot report no-shows';
  END IF;

  -- W07-G-49: filing a money-affecting case is itself an important
  -- operation; the audit row must carry a non-empty reason.
  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'reason is required to report a no-show case';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;
    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  IF p_charge_amount_yen < 0 THEN
    RAISE EXCEPTION 'invalid no-show charge amount';
  END IF;

  SELECT * INTO v_reservation FROM reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND OR v_reservation.status NOT IN ('confirmed','checked_in') THEN
    RAISE EXCEPTION 'reservation cannot be reported as no-show';
  END IF;

  SELECT * INTO v_terms FROM reservation_charge_terms WHERE reservation_id = v_reservation.id;
  v_amount := COALESCE(NULLIF(p_charge_amount_yen, 0), v_terms.agreed_no_show_fee_yen, 0);

  -- W07-G-01: never store a charge above the consented snapshot. A missing
  -- terms row means there is no consent on file -> only a 0 (waivable)
  -- report may be filed.
  IF v_amount > COALESCE(v_terms.agreed_no_show_fee_yen, 0) THEN
    RAISE EXCEPTION 'charge amount exceeds consented no-show fee'
      USING ERRCODE = 'P0001',
            DETAIL = 'agreed_no_show_fee_yen=' || COALESCE(v_terms.agreed_no_show_fee_yen, 0);
  END IF;

  INSERT INTO no_show_cases(
    reservation_id,
    reported_by_admin_id,
    charge_amount_yen,
    evidence_json
  )
  VALUES (v_reservation.id, p_actor_admin_id, v_amount, COALESCE(p_evidence_json, '{}'::jsonb))
  RETURNING id INTO v_case_id;

  UPDATE reservations
  SET status = 'no_show_review',
      updated_at = now()
  WHERE id = v_reservation.id;

  INSERT INTO notification_jobs(reservation_id, channel, payload_json)
  VALUES (
    v_reservation.id,
    'line',
    jsonb_build_object(
      'template', 'no_show_reported',
      'reservationId', v_reservation.id,
      'caseId', v_case_id,
      'chargeAmountYen', v_amount
    )
  );

  v_response := jsonb_build_object('reservationId', v_reservation.id, 'caseId', v_case_id, 'chargeAmountYen', v_amount);

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'no_show_cases', v_case_id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'reported', 'response', v_response);
END;
$$;

-- FUNCTION: create_admin_reservation_block_series_v21(uuid, text, text, text, uuid, integer, text, text, timestamp with time zone, timestamp with time zone, text, uuid[], uuid[], boolean, text)
CREATE FUNCTION public.create_admin_reservation_block_series_v21(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_first_event_day_id uuid, p_repeat_days integer, p_scope text, p_kind text, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_memo text, p_seat_resource_ids uuid[], p_floor_section_ids uuid[], p_venue_wide boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_first_day public.event_days%ROWTYPE;
  v_event_day_id uuid;
  v_index int;
  v_child jsonb;
  v_last_child jsonb;
  v_results jsonb := '[]'::jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    IF p_repeat_days IS NULL OR p_repeat_days < 1 OR p_repeat_days > 14 THEN
      RETURN jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
        'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'repeatDays')
      ));
    END IF;

    SELECT * INTO v_first_day
    FROM public.event_days
    WHERE id = p_first_event_day_id
    FOR NO KEY UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
        'code', 'NOT_FOUND', 'details', jsonb_build_object('entityType', 'eventDay')
      ));
    END IF;

    -- Lock the full date range in a stable order before any child mutation.
    PERFORM ed.id
    FROM public.event_days AS ed
    WHERE ed.business_date BETWEEN v_first_day.business_date
      AND v_first_day.business_date + (p_repeat_days - 1)
    ORDER BY ed.business_date, ed.id
    FOR NO KEY UPDATE OF ed;

    FOR v_index IN 0..(p_repeat_days - 1) LOOP
      SELECT ed.id INTO v_event_day_id
      FROM public.event_days AS ed
      WHERE ed.business_date = v_first_day.business_date + v_index;
      IF NOT FOUND THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
            'code', 'NOT_FOUND',
            'details', jsonb_build_object(
              'entityType', 'eventDay',
              'businessDate', v_first_day.business_date + v_index
            )
          )),
          ARRAY['allowed']
        );
      END IF;

      v_child := public.create_admin_reservation_block_v8(
        p_actor_admin_id,
        p_request_id || ':series:' || (v_index + 1),
        'block-series-child:' || encode(
          digest(p_idempotency_key || ':' || (v_index + 1), 'sha256'), 'hex'
        ),
        encode(digest(p_request_hash || ':' || (v_index + 1), 'sha256'), 'hex'),
        v_event_day_id,
        p_scope,
        p_kind,
        p_start_at + make_interval(days => v_index),
        p_end_at + make_interval(days => v_index),
        p_memo,
        p_seat_resource_ids,
        p_floor_section_ids,
        p_venue_wide,
        p_reason
      );
      PERFORM public.assert_vip_floor_helper_success_v8(v_child, ARRAY[
        'reservation_block.created'
      ]);
      v_results := v_results || jsonb_build_array(v_child);
      v_last_child := v_child;
    END LOOP;

    RETURN jsonb_build_object(
      'ok', true,
      'action', 'reservation_block.series_created',
      'reused', COALESCE((v_results -> 0 ->> 'reused')::boolean, false),
      'entityVersion', (v_last_child ->> 'entityVersion')::bigint,
      'boardRevision', (v_last_child ->> 'boardRevision')::bigint,
      'auditLogId', v_last_child ->> 'auditLogId',
      'createdCount', p_repeat_days,
      'results', v_results
    );
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: create_admin_reservation_block_v8(uuid, text, text, text, uuid, text, text, timestamp with time zone, timestamp with time zone, text, uuid[], uuid[], boolean, text)
CREATE FUNCTION public.create_admin_reservation_block_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_day_id uuid, p_scope text, p_kind text, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_memo text, p_seat_resource_ids uuid[], p_floor_section_ids uuid[], p_venue_wide boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation_block.created';
  v_scope text := lower(btrim(COALESCE(p_scope, '')));
  v_kind text := lower(btrim(COALESCE(p_kind, '')));
  v_step jsonb;
  v_table_ids uuid[];
  v_section_ids uuid[];
  v_target_seat_ids uuid[];
  v_conflict record;
  v_block_id uuid;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;
    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(p_actor_admin_id, 'reservation_block.write'),
      ARRAY['allowed']
    );

    SELECT COALESCE(array_agg(DISTINCT id ORDER BY id), '{}'::uuid[])
    INTO v_table_ids
    FROM unnest(COALESCE(p_seat_resource_ids, '{}'::uuid[])) AS requested(id);
    SELECT COALESCE(array_agg(DISTINCT id ORDER BY id), '{}'::uuid[])
    INTO v_section_ids
    FROM unnest(COALESCE(p_floor_section_ids, '{}'::uuid[])) AS requested(id);
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_event_day_id IS NULL
      OR v_scope NOT IN ('online_only', 'all_operations')
      OR v_kind NOT IN ('manual', 'maintenance', 'owner_hold', 'event', 'unassignment_guard')
      OR p_start_at IS NULL OR p_end_at IS NULL OR p_start_at >= p_end_at
      OR EXISTS (SELECT 1 FROM unnest(COALESCE(p_seat_resource_ids, '{}'::uuid[])) AS t(id) WHERE id IS NULL)
      OR EXISTS (SELECT 1 FROM unnest(COALESCE(p_floor_section_ids, '{}'::uuid[])) AS s(id) WHERE id IS NULL)
      OR cardinality(v_table_ids) <> cardinality(COALESCE(p_seat_resource_ids, '{}'::uuid[]))
      OR cardinality(v_section_ids) <> cardinality(COALESCE(p_floor_section_ids, '{}'::uuid[]))
      OR (
        COALESCE(p_venue_wide, false)
        AND (cardinality(v_table_ids) > 0 OR cardinality(v_section_ids) > 0)
      )
      OR (
        NOT COALESCE(p_venue_wide, false)
        AND cardinality(v_table_ids) = 0
        AND cardinality(v_section_ids) = 0
      )
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'blockCommand')
          )
        ), ARRAY['allowed']
      );
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.event_days AS ed
      WHERE ed.id = p_event_day_id
        AND ed.sales_open_at <= p_start_at
        AND ed.sales_close_at >= p_end_at
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', CASE WHEN EXISTS (SELECT 1 FROM public.event_days WHERE id = p_event_day_id)
              THEN 'INVALID_COMMAND' ELSE 'NOT_FOUND' END,
            'details', jsonb_build_object('field', 'eventDayId', 'reason', 'missing_or_interval_outside_day')
          )
        ), ARRAY['allowed']
      );
    END IF;
    IF (SELECT count(*) FROM public.floor_sections WHERE id = ANY(v_section_ids))
      <> cardinality(v_section_ids)
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object('code', 'NOT_FOUND', 'details', jsonb_build_object('entityType', 'floor_section'))
        ), ARRAY['allowed']
      );
    END IF;

    SELECT COALESCE(array_agg(sr.id ORDER BY sr.id), '{}'::uuid[])
    INTO v_target_seat_ids
    FROM public.seat_resources AS sr
    WHERE COALESCE(p_venue_wide, false)
       OR sr.id = ANY(v_table_ids)
       OR sr.floor_section_id = ANY(v_section_ids);
    IF EXISTS (SELECT 1 FROM unnest(v_table_ids) AS t(id) WHERE NOT (id = ANY(v_target_seat_ids))) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object('code', 'NOT_FOUND', 'details', jsonb_build_object('entityType', 'table'))
        ), ARRAY['allowed']
      );
    END IF;

    -- Block-only flows begin with sorted seat locks after the preclaim.
    PERFORM sr.id FROM public.seat_resources AS sr
    WHERE sr.id = ANY(v_target_seat_ids)
    ORDER BY sr.id FOR UPDATE OF sr;
    PERFORM rr.id
    FROM public.reservation_resources AS rr
    WHERE rr.seat_resource_id = ANY(v_target_seat_ids)
      AND rr.assigned_start_at < p_end_at
      AND rr.assigned_end_at > p_start_at
    ORDER BY rr.id FOR UPDATE OF rr;
    PERFORM rb.id
    FROM public.reservation_blocks AS rb
    WHERE rb.event_day_id = p_event_day_id
      AND rb.status = 'active'
      AND rb.start_at < p_end_at
      AND rb.end_at > p_start_at
      AND EXISTS (
        SELECT 1
        FROM public.reservation_block_targets AS rbt
        JOIN public.seat_resources AS sr ON sr.id = ANY(v_target_seat_ids)
        WHERE rbt.block_id = rb.id
          AND (
            rbt.seat_resource_id = sr.id
            OR rbt.floor_section_id = sr.floor_section_id
            OR rbt.venue_wide
          )
      )
    ORDER BY rb.id FOR UPDATE OF rb;

    IF v_scope = 'all_operations' THEN
      SELECT rr.id, r.public_code, sr.display_code,
        rr.assigned_start_at, rr.assigned_end_at
      INTO v_conflict
      FROM public.reservation_resources AS rr
      JOIN public.reservations AS r ON r.id = rr.reservation_id
      JOIN public.seat_resources AS sr ON sr.id = rr.seat_resource_id
      WHERE rr.seat_resource_id = ANY(v_target_seat_ids)
        AND rr.assigned_start_at < p_end_at
        AND rr.assigned_end_at > p_start_at
        AND public.active_reservation_assignment_v8(rr.id, now())
      ORDER BY rr.id LIMIT 1;
      IF FOUND THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object(
            'action', 'rejected',
            'error', jsonb_build_object(
              'code', 'TABLE_TIME_CONFLICT',
              'details', jsonb_build_object(
                'tableDisplayCode', v_conflict.display_code,
                'conflictingReservationPublicCode', v_conflict.public_code,
                'conflictingStartAt', v_conflict.assigned_start_at,
                'conflictingEndAt', v_conflict.assigned_end_at
              )
            )
          ), ARRAY['allowed']
        );
      END IF;
    END IF;

    INSERT INTO public.reservation_blocks(
      event_day_id, scope, kind, start_at, end_at, memo, created_by_admin_id
    ) VALUES (
      p_event_day_id, v_scope, v_kind, p_start_at, p_end_at,
      NULLIF(btrim(COALESCE(p_memo, '')), ''), p_actor_admin_id
    ) RETURNING id INTO v_block_id;
    INSERT INTO public.reservation_block_targets(block_id, seat_resource_id)
    SELECT v_block_id, table_target.id
    FROM unnest(v_table_ids) AS table_target(id)
    ORDER BY table_target.id;
    INSERT INTO public.reservation_block_targets(block_id, floor_section_id)
    SELECT v_block_id, section_target.id
    FROM unnest(v_section_ids) AS section_target(id)
    ORDER BY section_target.id;
    IF COALESCE(p_venue_wide, false) THEN
      INSERT INTO public.reservation_block_targets(block_id, venue_wide)
      VALUES (v_block_id, true);
    END IF;

    PERFORM ed.id FROM public.event_days AS ed
    WHERE ed.id = p_event_day_id FOR KEY SHARE OF ed;
    PERFORM public.lock_vip_floor_day_revision_v32(p_event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1 INTO v_predicted_revision
    FROM (SELECT 1) AS seed
    LEFT JOIN public.vip_floor_day_revisions AS vfr ON vfr.event_day_id = p_event_day_id;
    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, p_event_day_id, NULL,
      'block', v_block_id, v_action, p_request_id, p_reason,
      NULL, NULL, 1,
      ARRAY['created'], NULL,
      jsonb_build_object(
        'scope', v_scope, 'kind', v_kind,
        'startAt', p_start_at, 'endAt', p_end_at, 'version', 1
      ),
      jsonb_build_object(
        'tableCount', cardinality(v_table_ids),
        'sectionCount', cardinality(v_section_ids),
        'venueWide', COALESCE(p_venue_wide, false)
      )
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_response := jsonb_build_object(
      'ok', true, 'action', v_action, 'reused', false,
      'blockId', v_block_id, 'entityVersion', 1,
      'boardRevision', v_predicted_revision, 'auditLogId', v_audit_id
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(p_event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'XX000', MESSAGE = 'VIP floor revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN RETURN v_error_detail::jsonb; END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: create_admin_reservation_hold_v7(uuid, text, text, text, text, text, text, integer, text, text, integer)
CREATE FUNCTION public.create_admin_reservation_hold_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_public_slot_id text, p_public_offering_id text, p_guest_count integer, p_public_resource_code text, p_reason text, p_hold_minutes integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_slot booking_slots%ROWTYPE;
  v_offering booking_offerings%ROWTYPE;
  v_resource_id uuid;
  v_reservation_id uuid;
  v_expires_at timestamptz;
  v_response jsonb;
BEGIN
  SELECT * INTO v_admin FROM admin_users WHERE id = p_actor_admin_id FOR UPDATE;
  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;
  IF v_admin.role NOT IN ('manager','owner','engineer') THEN
    RAISE EXCEPTION 'admin role cannot create holds';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;
    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  SELECT * INTO v_slot
  FROM booking_slots
  WHERE public_slot_id = p_public_slot_id
    AND active = true
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'booking slot not found';
  END IF;

  SELECT * INTO v_offering
  FROM booking_offerings
  WHERE public_offering_id = p_public_offering_id
    AND active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'booking offering not found';
  END IF;

  IF p_guest_count NOT BETWEEN v_offering.min_guests AND v_offering.max_guests THEN
    RAISE EXCEPTION 'guest count is outside offering limits';
  END IF;

  SELECT sr.id INTO v_resource_id
  FROM seat_resources sr
  WHERE sr.public_resource_code = p_public_resource_code
    AND sr.active = true
    AND p_guest_count BETWEEN sr.capacity_min AND sr.capacity_max
  FOR UPDATE;

  IF v_resource_id IS NULL THEN
    RAISE EXCEPTION 'seat resource not found';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM reservation_resources rr
    JOIN reservations r ON r.id = rr.reservation_id
    JOIN booking_slots locked_slot ON locked_slot.id = r.booking_slot_id
    WHERE rr.seat_resource_id = v_resource_id
      AND locked_slot.start_at < v_slot.end_at
      AND locked_slot.end_at > v_slot.start_at
      AND rr.lock_status IN ('held','payment_grace_locked','confirmed')
      AND r.status NOT IN ('cancelled','hold_expired','payment_window_expired','failed')
      AND COALESCE(rr.admin_hold_expires_at, rr.hold_expires_at, r.admin_hold_expires_at, r.hold_expires_at, 'infinity'::timestamptz) > now()
  ) THEN
    RAISE EXCEPTION 'seat resource is already locked';
  END IF;

  v_expires_at := CASE
    WHEN p_hold_minutes IS NULL THEN admin_hold_default_expires_at_v7(now())
    ELSE now() + make_interval(mins => p_hold_minutes)
  END;

  INSERT INTO reservations(
    public_code,
    status_token_hash,
    booking_slot_id,
    booking_offering_id,
    guest_count,
    status,
    admin_hold_expires_at,
    admin_hold_reason,
    intake_channel,
    created_by_admin_id
  )
  VALUES (
    upper('A' || encode(gen_random_bytes(5), 'hex')),
    encode(digest(gen_random_uuid()::text, 'sha256'), 'hex'),
    v_slot.id,
    v_offering.id,
    p_guest_count,
    'admin_hold',
    v_expires_at,
    p_reason,
    'admin_hold',
    p_actor_admin_id
  )
  RETURNING id INTO v_reservation_id;

  INSERT INTO reservation_resources(reservation_id, seat_resource_id, lock_status, admin_hold_expires_at)
  VALUES (v_reservation_id, v_resource_id, 'held', v_expires_at);

  v_response := jsonb_build_object(
    'reservationId', v_reservation_id,
    'resourceId', v_resource_id,
    'adminHoldExpiresAt', v_expires_at
  );

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'reservations', v_reservation_id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'created', 'response', v_response);
END;
$$;

-- FUNCTION: create_admin_reservation_v13(uuid, text, text, text, uuid, uuid, timestamp with time zone, timestamp with time zone, integer, uuid[], jsonb, uuid, bytea, bytea, bytea, text, text, text, text, text, text, public.vip_service_status, uuid, text, boolean, text)
CREATE FUNCTION public.create_admin_reservation_v13(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_day_id uuid, p_booking_offering_id uuid, p_scheduled_start_at timestamp with time zone, p_scheduled_end_at timestamp with time zone, p_guest_count integer, p_table_ids uuid[], p_expected_table_versions jsonb, p_existing_customer_id uuid, p_display_name_ciphertext bytea, p_phone_ciphertext bytea, p_email_ciphertext bytea, p_phone_search_token text, p_email_search_token text, p_language_code text, p_guest_label text, p_operator_note text, p_source_channel text, p_service_status public.vip_service_status, p_booking_staff_member_id uuid, p_notification_preference text, p_capacity_override boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_action constant text := 'reservation.created';
  v_step jsonb;
  v_offering public.booking_offerings%ROWTYPE;
  v_slot public.booking_slots%ROWTYPE;
  v_table_ids uuid[];
  v_table_id uuid;
  v_expected_version bigint;
  v_capacity int;
  v_customer_id uuid;
  v_customer_candidates uuid[];
  v_customer_resolution text := 'none';
  v_reservation_id uuid;
  v_public_code text;
  v_assignment_id uuid;
  v_note_id uuid;
  v_audit_id uuid;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    IF NOT EXISTS (
      SELECT 1 FROM public.admin_users
      WHERE id = p_actor_admin_id AND active = true AND role = 'owner'
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object('code', 'FORBIDDEN')
        ),
        ARRAY['allowed']
      );
    END IF;
    SELECT COALESCE(array_agg(DISTINCT id ORDER BY id), '{}'::uuid[])
    INTO v_table_ids
    FROM unnest(COALESCE(p_table_ids, '{}'::uuid[])) AS requested(id);
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_event_day_id IS NULL OR p_booking_offering_id IS NULL
      OR p_scheduled_start_at IS NULL OR p_scheduled_end_at IS NULL
      OR p_scheduled_start_at >= p_scheduled_end_at
      OR p_guest_count IS NULL OR p_guest_count < 1 OR p_guest_count > 99
      OR cardinality(v_table_ids) = 0 OR cardinality(v_table_ids) > 8
      OR cardinality(v_table_ids) <> cardinality(COALESCE(p_table_ids, '{}'::uuid[]))
      OR p_expected_table_versions IS NULL
      OR jsonb_typeof(p_expected_table_versions) <> 'array'
      OR jsonb_array_length(p_expected_table_versions) <> cardinality(v_table_ids)
      OR char_length(COALESCE(p_guest_label, '')) > 80
      OR char_length(COALESCE(p_operator_note, '')) > 500
      OR p_source_channel NOT IN ('admin_hold', 'online')
      OR p_service_status IS NULL
      OR p_notification_preference NOT IN ('none', 'email')
      OR p_reason <> '管理画面操作'
      OR char_length(COALESCE(p_language_code, '')) > 16
      OR char_length(COALESCE(p_phone_search_token, '')) > 255
      OR char_length(COALESCE(p_email_search_token, '')) > 255
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'reservationCreate')
          )
        ),
        ARRAY['allowed']
      );
    END IF;
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_expected_table_versions) AS item(value)
      WHERE jsonb_typeof(value) <> 'object'
         OR NOT (value ?& ARRAY['tableId', 'expectedVersion'])
         OR value - ARRAY['tableId', 'expectedVersion'] <> '{}'::jsonb
         OR value ->> 'tableId' !~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
         OR value ->> 'expectedVersion' !~ '^[1-9][0-9]*$'
    ) OR (
      SELECT count(DISTINCT (value ->> 'tableId')::uuid)
      FROM jsonb_array_elements(p_expected_table_versions) AS item(value)
    ) <> cardinality(v_table_ids)
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'expectedTableVersions')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;

    PERFORM id FROM public.event_days
    WHERE id = p_event_day_id
      AND sales_open_at <= p_scheduled_start_at
      AND sales_close_at >= p_scheduled_end_at
    FOR NO KEY UPDATE;
    IF NOT FOUND THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'eventDayId')
          )
        ),
        ARRAY['allowed']
      );
    END IF;
    SELECT * INTO v_offering
    FROM public.booking_offerings
    WHERE id = p_booking_offering_id AND active = true;
    IF NOT FOUND OR p_guest_count NOT BETWEEN v_offering.min_guests AND v_offering.max_guests THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'guestCount')
          )
        ),
        ARRAY['allowed']
      );
    END IF;
    SELECT * INTO v_slot
    FROM public.booking_slots
    WHERE event_day_id = p_event_day_id AND active = true
    ORDER BY abs(extract(epoch FROM (start_at - p_scheduled_start_at))), start_at, id
    LIMIT 1;
    IF NOT FOUND THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object('code', 'SLOT_COMPATIBILITY_MISSING')
        ),
        ARRAY['allowed']
      );
    END IF;
    IF p_booking_staff_member_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.vip_staff_members
      WHERE id = p_booking_staff_member_id AND active = true
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'NOT_FOUND',
            'details', jsonb_build_object('entityType', 'staff_member')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    PERFORM id FROM public.seat_resources
    WHERE id = ANY(v_table_ids)
    ORDER BY id FOR UPDATE;
    IF (SELECT count(*) FROM public.seat_resources
        WHERE id = ANY(v_table_ids) AND active = true) <> cardinality(v_table_ids)
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object('code', 'TABLE_LOCKED')
        ),
        ARRAY['allowed']
      );
    END IF;
    FOREACH v_table_id IN ARRAY v_table_ids LOOP
      SELECT (value ->> 'expectedVersion')::bigint
      INTO v_expected_version
      FROM jsonb_array_elements(p_expected_table_versions) AS item(value)
      WHERE (value ->> 'tableId')::uuid = v_table_id;
      IF NOT EXISTS (
        SELECT 1 FROM public.seat_resources
        WHERE id = v_table_id AND version = v_expected_version
      ) THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object(
            'action', 'rejected',
            'error', jsonb_build_object(
              'code', 'VERSION_CONFLICT',
              'currentVersion', (
                SELECT version FROM public.seat_resources WHERE id = v_table_id
              )
            )
          ),
          ARRAY['allowed']
        );
      END IF;
      v_step := public.assert_assignment_conflict_free_v8(
        p_event_day_id, NULL, v_table_id,
        p_scheduled_start_at, p_scheduled_end_at, now()
      );
      PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
    END LOOP;
    SELECT COALESCE(sum(capacity_max), 0)::int INTO v_capacity
    FROM public.seat_resources WHERE id = ANY(v_table_ids);
    IF v_capacity < p_guest_count AND NOT COALESCE(p_capacity_override, false) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'CAPACITY_WARNING_REQUIRES_OVERRIDE',
            'details', jsonb_build_object(
              'guestCount', p_guest_count, 'combinedCapacity', v_capacity
            )
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    IF p_existing_customer_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM public.customers WHERE id = p_existing_customer_id) THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object(
            'action', 'rejected',
            'error', jsonb_build_object('code', 'NOT_FOUND')
          ),
          ARRAY['allowed']
        );
      END IF;
      v_customer_id := p_existing_customer_id;
      v_customer_resolution := 'explicit';
    ELSIF NULLIF(p_phone_search_token, '') IS NOT NULL THEN
      SELECT array_agg(customer_id ORDER BY customer_id)
      INTO v_customer_candidates
      FROM public.customer_profiles
      WHERE phone_search_token = p_phone_search_token;
      IF cardinality(COALESCE(v_customer_candidates, '{}'::uuid[])) = 1 THEN
        v_customer_id := v_customer_candidates[1];
        v_customer_resolution := 'phone_exact';
      END IF;
    ELSIF NULLIF(p_email_search_token, '') IS NOT NULL THEN
      SELECT array_agg(customer_id ORDER BY customer_id)
      INTO v_customer_candidates
      FROM public.customer_profiles
      WHERE email_search_token = p_email_search_token;
      IF cardinality(COALESCE(v_customer_candidates, '{}'::uuid[])) = 1 THEN
        v_customer_id := v_customer_candidates[1];
        v_customer_resolution := 'email_exact';
      END IF;
    END IF;

    IF v_customer_id IS NULL AND (
      p_display_name_ciphertext IS NOT NULL
      OR p_phone_ciphertext IS NOT NULL
      OR p_email_ciphertext IS NOT NULL
    ) THEN
      INSERT INTO public.customers(email_hash, phone_hash, environment)
      VALUES (p_email_search_token, p_phone_search_token, 'live')
      RETURNING id INTO v_customer_id;
      v_customer_resolution := 'new';
    END IF;
    IF v_customer_id IS NOT NULL THEN
      INSERT INTO public.customer_profiles(
        customer_id, display_name_ciphertext, phone_ciphertext,
        email_ciphertext, phone_search_token, email_search_token,
        language_code, version
      )
      VALUES (
        v_customer_id, p_display_name_ciphertext, p_phone_ciphertext,
        p_email_ciphertext, p_phone_search_token, p_email_search_token,
        NULLIF(btrim(COALESCE(p_language_code, '')), ''), 1
      )
      ON CONFLICT (customer_id) DO UPDATE
      SET display_name_ciphertext = COALESCE(
            EXCLUDED.display_name_ciphertext,
            public.customer_profiles.display_name_ciphertext
          ),
          phone_ciphertext = COALESCE(
            EXCLUDED.phone_ciphertext,
            public.customer_profiles.phone_ciphertext
          ),
          email_ciphertext = COALESCE(
            EXCLUDED.email_ciphertext,
            public.customer_profiles.email_ciphertext
          ),
          phone_search_token = COALESCE(
            EXCLUDED.phone_search_token,
            public.customer_profiles.phone_search_token
          ),
          email_search_token = COALESCE(
            EXCLUDED.email_search_token,
            public.customer_profiles.email_search_token
          ),
          language_code = COALESCE(
            EXCLUDED.language_code,
            public.customer_profiles.language_code
          ),
          version = public.customer_profiles.version + 1,
          updated_at = now();
    END IF;

    v_public_code := upper('M' || left(replace(gen_random_uuid()::text, '-', ''), 10));
    INSERT INTO public.reservations(
      public_code, status_token_hash, customer_id,
      booking_slot_id, booking_offering_id, guest_count,
      status, intake_channel, guest_label, operator_note,
      created_by_admin_id, confirmed_at,
      event_day_id, scheduled_start_at, scheduled_end_at,
      expected_release_at, service_status, service_status_changed_at,
      version, booking_staff_member_id, manager_notification_preference
    )
    VALUES (
      v_public_code,
      md5(gen_random_uuid()::text || clock_timestamp()::text),
      v_customer_id, v_slot.id, v_offering.id, p_guest_count,
      'confirmed', p_source_channel,
      NULLIF(btrim(COALESCE(p_guest_label, '')), ''),
      NULLIF(btrim(COALESCE(p_operator_note, '')), ''),
      p_actor_admin_id, now(),
      p_event_day_id, p_scheduled_start_at, p_scheduled_end_at,
      p_scheduled_end_at, p_service_status, now(),
      1, p_booking_staff_member_id, p_notification_preference
    )
    RETURNING id INTO v_reservation_id;

    FOREACH v_table_id IN ARRAY v_table_ids LOOP
      INSERT INTO public.reservation_resources(
        reservation_id, seat_resource_id, lock_status, confirmed_at,
        assigned_start_at, assigned_end_at, assignment_role,
        assigned_by_admin_id, version
      )
      VALUES (
        v_reservation_id, v_table_id, 'confirmed', now(),
        p_scheduled_start_at, p_scheduled_end_at,
        CASE WHEN v_table_id = v_table_ids[1] THEN 'primary' ELSE 'additional' END,
        p_actor_admin_id, 1
      )
      RETURNING id INTO v_assignment_id;
      INSERT INTO public.reservation_assignment_events(
        reservation_id, reservation_resource_id, seat_resource_id,
        event_type, interval_before, interval_after,
        actor_admin_id, reason, request_id, occurred_at
      )
      VALUES (
        v_reservation_id, v_assignment_id, v_table_id,
        'assigned', NULL,
        jsonb_build_object(
          'startAt', p_scheduled_start_at,
          'endAt', p_scheduled_end_at
        ),
        p_actor_admin_id, p_reason, p_request_id, now()
      );
    END LOOP;
    IF NULLIF(btrim(COALESCE(p_operator_note, '')), '') IS NOT NULL THEN
      INSERT INTO public.reservation_notes(
        reservation_id, kind, body, pinned,
        author_admin_id, updated_by_admin_id
      )
      VALUES (
        v_reservation_id, 'floor', btrim(p_operator_note), false,
        p_actor_admin_id, p_actor_admin_id
      )
      RETURNING id INTO v_note_id;
    END IF;
    INSERT INTO public.reservation_service_events(
      reservation_id, from_status, to_status, occurred_at,
      actor_admin_id, reason, request_id, metadata_json
    )
    VALUES (
      v_reservation_id, NULL, p_service_status, now(),
      p_actor_admin_id, p_reason, p_request_id,
      jsonb_build_object('source', 'admin_reservation_create')
    );
    INSERT INTO public.reservation_customer_link_events(
      reservation_id, previous_customer_id, customer_id,
      resolution_method, actor_admin_id, request_id
    )
    VALUES (
      v_reservation_id, NULL, v_customer_id,
      v_customer_resolution, p_actor_admin_id, p_request_id
    );

    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, p_event_day_id, v_reservation_id,
      'reservation', v_reservation_id, v_action,
      p_request_id, p_reason, NULL, NULL, 1,
      ARRAY['created'], NULL,
      jsonb_build_object(
        'version', 1,
        'status', 'confirmed',
        'serviceStatus', p_service_status,
        'scheduledStartAt', p_scheduled_start_at,
        'scheduledEndAt', p_scheduled_end_at
      ),
      jsonb_build_object(
        'tableIds', to_jsonb(v_table_ids),
        'sourceChannel', p_source_channel,
        'notifyMode', p_notification_preference,
        'customerResolution', v_customer_resolution,
        'capacityOverride', COALESCE(p_capacity_override, false)
      )
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_step := public.bump_vip_floor_day_revision_v8(p_event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;

    v_response := jsonb_build_object(
      'ok', true,
      'action', v_action,
      'reused', false,
      'reservationId', v_reservation_id,
      'customerId', v_customer_id,
      'entityVersion', 1,
      'boardRevision', v_revision,
      'auditLogId', v_audit_id,
      'publicCode', v_public_code,
      'tableIds', to_jsonb(v_table_ids),
      'notificationPreference', p_notification_preference
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$_$;

-- FUNCTION: create_admin_reservation_v22(uuid, text, text, text, uuid, uuid, timestamp with time zone, timestamp with time zone, integer, uuid[], jsonb, uuid, bytea, bytea, bytea, text, text, text, text, text, text, public.vip_service_status, uuid, text, boolean, text)
CREATE FUNCTION public.create_admin_reservation_v22(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_day_id uuid, p_booking_offering_id uuid, p_scheduled_start_at timestamp with time zone, p_scheduled_end_at timestamp with time zone, p_guest_count integer, p_table_ids uuid[], p_expected_table_versions jsonb, p_existing_customer_id uuid, p_display_name_ciphertext bytea, p_phone_ciphertext bytea, p_email_ciphertext bytea, p_phone_search_token text, p_email_search_token text, p_language_code text, p_guest_label text, p_operator_note text, p_source_channel text, p_service_status public.vip_service_status, p_booking_staff_member_id uuid, p_notification_preference text, p_capacity_override boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_response jsonb;
  v_reservation_id uuid;
  v_legacy_source text;
BEGIN
  IF p_source_channel NOT IN ('online', 'phone', 'admin') THEN
    RETURN jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
      'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'sourceChannel')
    ));
  END IF;
  v_legacy_source := CASE WHEN p_source_channel = 'online' THEN 'online' ELSE 'admin_hold' END;
  v_response := public.create_admin_reservation_v13(
    p_actor_admin_id, p_request_id, p_idempotency_key, p_request_hash,
    p_event_day_id, p_booking_offering_id, p_scheduled_start_at, p_scheduled_end_at,
    p_guest_count, p_table_ids, p_expected_table_versions, p_existing_customer_id,
    p_display_name_ciphertext, p_phone_ciphertext, p_email_ciphertext,
    p_phone_search_token, p_email_search_token, p_language_code, p_guest_label,
    p_operator_note, v_legacy_source, p_service_status, p_booking_staff_member_id,
    p_notification_preference, p_capacity_override, p_reason
  );
  IF v_response ->> 'action' = 'rejected' THEN RETURN v_response; END IF;
  v_reservation_id := (v_response ->> 'reservationId')::uuid;
  UPDATE public.reservations SET origin_channel = p_source_channel WHERE id = v_reservation_id;
  PERFORM public.sync_reservation_floor_note_v22(p_actor_admin_id, v_reservation_id, p_operator_note);
  RETURN v_response || jsonb_build_object('sourceChannel', p_source_channel);
END;
$$;

-- FUNCTION: create_admin_reservation_v23(uuid, text, text, text, uuid, uuid, timestamp with time zone, timestamp with time zone, integer, uuid[], jsonb, uuid, bytea, bytea, bytea, text, text, text, text, text, text, public.vip_service_status, uuid, text, boolean, text)
CREATE FUNCTION public.create_admin_reservation_v23(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_day_id uuid, p_booking_offering_id uuid, p_scheduled_start_at timestamp with time zone, p_scheduled_end_at timestamp with time zone, p_guest_count integer, p_table_ids uuid[], p_expected_table_versions jsonb, p_existing_customer_id uuid, p_display_name_ciphertext bytea, p_phone_ciphertext bytea, p_email_ciphertext bytea, p_phone_search_token text, p_email_search_token text, p_language_code text, p_guest_label text, p_operator_note text, p_source_channel text, p_service_status public.vip_service_status, p_booking_staff_member_id uuid, p_notification_preference text, p_capacity_override boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.ensure_admin_booking_slots_v80(p_event_day_id);
  RETURN public.create_admin_reservation_v22(
    p_actor_admin_id, p_request_id, p_idempotency_key, p_request_hash,
    p_event_day_id, p_booking_offering_id, p_scheduled_start_at, p_scheduled_end_at,
    p_guest_count, p_table_ids, p_expected_table_versions, p_existing_customer_id,
    p_display_name_ciphertext, p_phone_ciphertext, p_email_ciphertext,
    p_phone_search_token, p_email_search_token, p_language_code, p_guest_label,
    p_operator_note, p_source_channel, p_service_status, p_booking_staff_member_id,
    p_notification_preference, p_capacity_override, p_reason
  );
END;
$$;

-- FUNCTION: create_admin_session_v7(text, text, text, text, timestamp with time zone, text)
CREATE FUNCTION public.create_admin_session_v7(p_email_hash text, p_display_name text, p_role text, p_session_token_hash text, p_expires_at timestamp with time zone, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_session_id uuid;
BEGIN
  IF p_email_hash IS NULL OR length(p_email_hash) < 32 THEN
    RAISE EXCEPTION 'invalid admin email hash';
  END IF;

  IF p_session_token_hash IS NULL OR length(p_session_token_hash) < 32 THEN
    RAISE EXCEPTION 'invalid admin session token hash';
  END IF;

  IF p_role NOT IN ('staff','manager','owner','engineer','accountant') THEN
    RAISE EXCEPTION 'invalid admin role';
  END IF;

  SELECT * INTO v_admin
  FROM admin_users
  WHERE email_hash = p_email_hash
  FOR UPDATE;

  IF FOUND THEN
    UPDATE admin_users
    SET display_name = COALESCE(p_display_name, display_name),
        role = p_role,
        active = true,
        updated_at = now()
    WHERE id = v_admin.id
    RETURNING * INTO v_admin;
  ELSE
    INSERT INTO admin_users(email_hash, display_name, role, active)
    VALUES (p_email_hash, p_display_name, p_role, true)
    RETURNING * INTO v_admin;
  END IF;

  INSERT INTO admin_sessions(admin_user_id, session_token_hash, expires_at)
  VALUES (v_admin.id, p_session_token_hash, p_expires_at)
  ON CONFLICT (session_token_hash)
  DO UPDATE
  SET admin_user_id = EXCLUDED.admin_user_id,
      active = true,
      expires_at = EXCLUDED.expires_at,
      retired_at = NULL,
      updated_at = now()
  RETURNING id INTO v_session_id;

  INSERT INTO audit_logs(
    actor_admin_id,
    actor_type,
    action,
    target_table,
    target_id,
    request_id,
    after_json
  )
  VALUES (
    v_admin.id,
    'admin',
    'admin_session.create',
    'admin_sessions',
    v_session_id,
    p_request_id,
    jsonb_build_object('role', v_admin.role, 'expiresAt', p_expires_at)
  );

  RETURN jsonb_build_object(
    'adminId', v_admin.id,
    'sessionId', v_session_id,
    'role', v_admin.role,
    'displayName', v_admin.display_name,
    'expiresAt', p_expires_at
  );
END;
$$;

-- FUNCTION: create_admin_session_v8(text, text, text, text, timestamp with time zone, text, boolean, text)
CREATE FUNCTION public.create_admin_session_v8(p_email_hash text, p_display_name text, p_role text, p_session_token_hash text, p_expires_at timestamp with time zone, p_request_id text, p_provision boolean DEFAULT false, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_session_id uuid;
  v_provisioned boolean := false;
BEGIN
  IF p_email_hash IS NULL OR length(p_email_hash) < 32 THEN
    RAISE EXCEPTION 'invalid admin email hash';
  END IF;

  IF p_session_token_hash IS NULL OR length(p_session_token_hash) < 32 THEN
    RAISE EXCEPTION 'invalid admin session token hash';
  END IF;

  IF p_role NOT IN ('staff','manager','owner','engineer','accountant') THEN
    RAISE EXCEPTION 'invalid admin role';
  END IF;

  -- Bound every minted session to the 12-hour contract; the shared bootstrap
  -- credential must never create effectively permanent sessions.
  IF p_expires_at IS NULL
     OR p_expires_at <= now()
     OR p_expires_at > now() + interval '12 hours' THEN
    RAISE EXCEPTION 'invalid admin session expiry';
  END IF;

  SELECT * INTO v_admin
  FROM admin_users
  WHERE email_hash = p_email_hash
  FOR UPDATE;

  IF FOUND THEN
    -- Never silently resurrect a retired admin or change a stored role. Those
    -- are explicit operator decisions that belong to the admin-management
    -- surface, not to a shared-secret bootstrap call.
    IF v_admin.active = false THEN
      RAISE EXCEPTION 'admin reactivation denied';
    END IF;

    IF v_admin.role <> p_role THEN
      RAISE EXCEPTION 'admin role change denied';
    END IF;

    UPDATE admin_users
    SET display_name = COALESCE(p_display_name, display_name),
        updated_at = now()
    WHERE id = v_admin.id
    RETURNING * INTO v_admin;
  ELSE
    IF p_provision IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'admin provisioning denied';
    END IF;

    INSERT INTO admin_users(email_hash, display_name, role, active)
    VALUES (p_email_hash, p_display_name, p_role, true)
    RETURNING * INTO v_admin;

    v_provisioned := true;
  END IF;

  INSERT INTO admin_sessions(admin_user_id, session_token_hash, expires_at)
  VALUES (v_admin.id, p_session_token_hash, p_expires_at)
  ON CONFLICT (session_token_hash)
  DO UPDATE
  SET admin_user_id = EXCLUDED.admin_user_id,
      active = true,
      expires_at = EXCLUDED.expires_at,
      retired_at = NULL,
      updated_at = now()
  RETURNING id INTO v_session_id;

  INSERT INTO audit_logs(
    actor_admin_id,
    actor_type,
    action,
    target_table,
    target_id,
    request_id,
    reason,
    after_json
  )
  VALUES (
    v_admin.id,
    'admin',
    'admin_session.create',
    'admin_sessions',
    v_session_id,
    p_request_id,
    left(p_reason, 500),
    jsonb_build_object(
      'role', v_admin.role,
      'expiresAt', p_expires_at,
      'provisioned', v_provisioned
    )
  );

  RETURN jsonb_build_object(
    'adminId', v_admin.id,
    'sessionId', v_session_id,
    'role', v_admin.role,
    'displayName', v_admin.display_name,
    'expiresAt', p_expires_at,
    'provisioned', v_provisioned
  );
END;
$$;

-- FUNCTION: create_admin_vip_staff_member_v12(uuid, text, text, text, text, text)
CREATE FUNCTION public.create_admin_vip_staff_member_v12(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_display_name text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'staff_member.created';
  v_step jsonb;
  v_staff_id uuid;
  v_audit_id uuid;
  v_response jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admin_users
    WHERE id = p_actor_admin_id AND active = true AND role = 'owner'
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object('code', 'FORBIDDEN')
    );
  END IF;
  IF NULLIF(btrim(COALESCE(p_display_name, '')), '') IS NULL
    OR char_length(btrim(p_display_name)) > 80
    OR p_reason <> '管理画面操作'
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object('field', 'staffMember')
      )
    );
  END IF;

  v_step := public.preclaim_admin_action_request_v8(
    p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
  );
  IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
  IF v_step ->> 'action' = 'reused' THEN
    RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
  END IF;

  INSERT INTO public.vip_staff_members(
    display_name, created_by_admin_id, updated_by_admin_id
  )
  VALUES (btrim(p_display_name), p_actor_admin_id, p_actor_admin_id)
  RETURNING id INTO v_staff_id;

  INSERT INTO public.audit_logs(
    actor_admin_id, actor_type, action, target_table, target_id,
    request_id, reason, entity_type, entity_id, operation,
    version_before, version_after, changed_fields,
    before_json, after_json, metadata_json, source_contract
  )
  VALUES (
    p_actor_admin_id, 'admin', v_action, 'vip_staff_members', v_staff_id,
    p_request_id, p_reason, 'staff_member', v_staff_id, v_action,
    NULL, 1, ARRAY['created'],
    NULL, jsonb_build_object('version', 1, 'active', true),
    jsonb_build_object('redaction', 'staff_name_omitted'),
    'ghost.vip-manager.v2'
  )
  RETURNING id INTO v_audit_id;

  v_response := jsonb_build_object(
    'ok', true,
    'action', v_action,
    'reused', false,
    'staffMemberId', v_staff_id,
    'entityVersion', 1,
    'boardRevision', 0,
    'auditLogId', v_audit_id
  );
  PERFORM public.complete_admin_action_request_v8(
    p_actor_admin_id, v_action, p_idempotency_key, v_response
  );
  RETURN v_response;
END;
$$;

-- FUNCTION: create_admin_waitlist_entry_v11(uuid, text, text, text, uuid, integer, bytea, bytea, text)
CREATE FUNCTION public.create_admin_waitlist_entry_v11(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_day_id uuid, p_guest_count integer, p_guest_label_ciphertext bytea, p_email_ciphertext bytea, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'waitlist.created';
  v_step jsonb;
  v_entry_id uuid;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.admin_users
      WHERE id = p_actor_admin_id AND active = true AND role = 'owner'
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', CASE WHEN EXISTS (
            SELECT 1 FROM public.admin_users WHERE id = p_actor_admin_id AND active = true
          ) THEN 'FORBIDDEN' ELSE 'UNAUTHENTICATED' END,
          'details', jsonb_build_object('capability', 'owner')
        )), ARRAY['allowed']
      );
    END IF;

    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_reason <> '管理画面操作'
      OR p_guest_count NOT BETWEEN 1 AND 99
      OR NOT EXISTS (SELECT 1 FROM public.event_days WHERE id = p_event_day_id)
      OR (p_guest_label_ciphertext IS NOT NULL AND octet_length(p_guest_label_ciphertext) = 0)
      OR (p_email_ciphertext IS NOT NULL AND octet_length(p_email_ciphertext) = 0)
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND',
          'details', jsonb_build_object('field', 'waitlistCommand')
        )), ARRAY['allowed']
      );
    END IF;

    INSERT INTO public.vip_waitlist_entries(
      event_day_id,
      guest_count,
      guest_label_ciphertext,
      email_ciphertext,
      created_by_admin_id,
      updated_by_admin_id
    )
    VALUES (
      p_event_day_id,
      p_guest_count,
      p_guest_label_ciphertext,
      p_email_ciphertext,
      p_actor_admin_id,
      p_actor_admin_id
    )
    RETURNING id INTO v_entry_id;

    INSERT INTO public.audit_logs(
      actor_admin_id, actor_type, action, target_table, target_id, request_id,
      before_json, after_json, reason, event_day_id, reservation_id,
      entity_type, entity_id, operation, expected_version, version_before,
      version_after, changed_fields, metadata_json, source_contract
    )
    VALUES (
      p_actor_admin_id, 'admin', v_action, 'vip_waitlist_entries', v_entry_id, p_request_id,
      NULL,
      jsonb_build_object('status', 'waiting', 'guestCount', p_guest_count, 'version', 1),
      p_reason, p_event_day_id, NULL,
      'waitlist', v_entry_id, v_action, NULL, NULL, 1,
      ARRAY['guest_count', 'status'],
      jsonb_build_object(
        'hasGuestLabel', p_guest_label_ciphertext IS NOT NULL,
        'hasEmail', p_email_ciphertext IS NOT NULL,
        'contactMaterialStoredInAudit', false
      ),
      'ghost.vip-manager.v2'
    )
    RETURNING id INTO v_audit_id;

    PERFORM public.lock_vip_floor_day_revision_v32(p_event_day_id);
    SELECT COALESCE(revision, 0) + 1
    INTO v_predicted_revision
    FROM public.vip_floor_day_revisions
    WHERE event_day_id = p_event_day_id;
    v_predicted_revision := COALESCE(v_predicted_revision, 1);

    v_response := jsonb_build_object(
      'ok', true,
      'action', v_action,
      'reused', false,
      'waitlistEntryId', v_entry_id,
      'entityVersion', 1,
      'boardRevision', v_predicted_revision,
      'auditLogId', v_audit_id,
      'status', 'waiting'
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(p_event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION 'waitlist revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: create_admin_walk_in_reservation_v19(uuid, text, text, text, uuid, uuid, timestamp with time zone, timestamp with time zone, integer, uuid[], text, text, jsonb, uuid, boolean, text)
CREATE FUNCTION public.create_admin_walk_in_reservation_v19(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_day_id uuid, p_booking_offering_id uuid, p_scheduled_start_at timestamp with time zone, p_scheduled_end_at timestamp with time zone, p_guest_count integer, p_table_ids uuid[], p_guest_label text, p_operator_note text, p_expected_table_versions jsonb, p_booking_staff_member_id uuid, p_capacity_override boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'walk_in.created';
  v_base_response jsonb;
  v_response jsonb;
  v_step jsonb;
  v_reservation_id uuid;
  v_audit_id uuid;
  v_revision bigint;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_base_response := public.create_admin_walk_in_reservation_v8(
      p_actor_admin_id,
      p_request_id,
      p_idempotency_key,
      p_request_hash,
      p_event_day_id,
      p_booking_offering_id,
      p_scheduled_start_at,
      p_scheduled_end_at,
      p_guest_count,
      p_table_ids,
      p_guest_label,
      p_operator_note,
      p_expected_table_versions,
      p_capacity_override,
      p_reason
    );

    IF v_base_response ->> 'action' = 'rejected' THEN
      RETURN v_base_response;
    END IF;
    IF COALESCE((v_base_response ->> 'reused')::boolean, false) THEN
      RETURN v_base_response;
    END IF;

    v_reservation_id := (v_base_response ->> 'reservationId')::uuid;
    IF p_booking_staff_member_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM public.vip_staff_members
      WHERE id = p_booking_staff_member_id
        AND active = true
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'NOT_FOUND',
            'details', jsonb_build_object('entityType', 'staff_member')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    UPDATE public.reservations
    SET booking_staff_member_id = p_booking_staff_member_id,
        updated_at = now()
    WHERE id = v_reservation_id
      AND event_day_id = p_event_day_id
      AND intake_channel = 'walk_in';
    IF NOT FOUND THEN
      RAISE EXCEPTION USING
        ERRCODE = 'XX000',
        MESSAGE = 'Walk-in attribution target was not created';
    END IF;

    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id,
      p_event_day_id,
      v_reservation_id,
      'reservation',
      v_reservation_id,
      'walk_in.attribution_recorded',
      p_request_id,
      p_reason,
      NULL,
      1,
      1,
      ARRAY['booking_staff_member_id'],
      jsonb_build_object('bookingStaffMemberId', NULL),
      jsonb_build_object('bookingStaffMemberId', p_booking_staff_member_id),
      jsonb_build_object(
        'sourceChannel', 'walk_in',
        'attribution', CASE
          WHEN p_booking_staff_member_id IS NULL THEN 'direct'
          ELSE 'staff'
        END
      )
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;

    v_step := public.bump_vip_floor_day_revision_v8(p_event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;

    v_response := v_base_response || jsonb_build_object(
      'boardRevision', v_revision,
      'auditLogId', v_audit_id,
      'bookingStaffMemberId', p_booking_staff_member_id,
      'attribution', CASE
        WHEN p_booking_staff_member_id IS NULL THEN 'direct'
        ELSE 'staff'
      END
    );

    UPDATE public.admin_action_requests
    SET response_json = v_response,
        updated_at = now()
    WHERE actor_admin_id = p_actor_admin_id
      AND action = v_action
      AND idempotency_key = p_idempotency_key
      AND request_hash = p_request_hash
      AND response_json IS NOT NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING
        ERRCODE = 'XX000',
        MESSAGE = 'Walk-in attribution idempotency response was not found';
    END IF;

    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: create_admin_walk_in_reservation_v20(uuid, text, text, text, uuid, uuid, timestamp with time zone, timestamp with time zone, integer, uuid[], text, text, jsonb, uuid, boolean, text)
CREATE FUNCTION public.create_admin_walk_in_reservation_v20(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_day_id uuid, p_booking_offering_id uuid, p_scheduled_start_at timestamp with time zone, p_scheduled_end_at timestamp with time zone, p_guest_count integer, p_table_ids uuid[], p_guest_label text, p_operator_note text, p_expected_table_versions jsonb, p_booking_staff_member_id uuid, p_capacity_override boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'walk_in.created';
  v_base_response jsonb;
  v_response jsonb;
  v_step jsonb;
  v_reservation_id uuid;
  v_audit_id uuid;
  v_revision bigint;
  v_new_version bigint;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    -- v8 owns request validation, idempotency, capacity/table conflict checks,
    -- reservation creation, its initial version-1 audit and day revision.
    v_base_response := public.create_admin_walk_in_reservation_v8(
      p_actor_admin_id,
      p_request_id,
      p_idempotency_key,
      p_request_hash,
      p_event_day_id,
      p_booking_offering_id,
      p_scheduled_start_at,
      p_scheduled_end_at,
      p_guest_count,
      p_table_ids,
      p_guest_label,
      p_operator_note,
      p_expected_table_versions,
      p_capacity_override,
      p_reason
    );

    IF v_base_response ->> 'action' = 'rejected' THEN
      RETURN v_base_response;
    END IF;
    IF COALESCE((v_base_response ->> 'reused')::boolean, false) THEN
      RETURN v_base_response;
    END IF;

    v_reservation_id := (v_base_response ->> 'reservationId')::uuid;

    -- Direct acquisition is already fully persisted and audited by v8. Do not
    -- manufacture a no-op audit tuple or advance the entity/day revision.
    IF p_booking_staff_member_id IS NULL THEN
      v_response := v_base_response || jsonb_build_object(
        'bookingStaffMemberId', NULL,
        'attribution', 'direct'
      );

      UPDATE public.admin_action_requests
      SET response_json = v_response,
          updated_at = now()
      WHERE actor_admin_id = p_actor_admin_id
        AND action = v_action
        AND idempotency_key = p_idempotency_key
        AND request_hash = p_request_hash
        AND response_json IS NOT NULL;
      IF NOT FOUND THEN
        RAISE EXCEPTION USING
          ERRCODE = 'XX000',
          MESSAGE = 'Walk-in direct attribution idempotency response was not found';
      END IF;

      RETURN v_response;
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.vip_staff_members
      WHERE id = p_booking_staff_member_id
        AND active = true
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'NOT_FOUND',
            'details', jsonb_build_object('entityType', 'staff_member')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    -- Staff attribution is a real second entity mutation. Advance from the
    -- freshly-created version 1 and use that exact transition in the audit.
    UPDATE public.reservations
    SET booking_staff_member_id = p_booking_staff_member_id,
        version = version + 1,
        updated_at = now()
    WHERE id = v_reservation_id
      AND event_day_id = p_event_day_id
      AND intake_channel = 'walk_in'
      AND version = 1
    RETURNING version INTO v_new_version;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING
        ERRCODE = 'XX000',
        MESSAGE = 'Walk-in staff attribution target was not at version 1';
    END IF;

    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id => p_actor_admin_id,
      p_event_day_id => p_event_day_id,
      p_reservation_id => v_reservation_id,
      p_entity_type => 'reservation',
      p_entity_id => v_reservation_id,
      p_operation => 'walk_in.attribution_recorded',
      p_request_id => p_request_id,
      p_reason => p_reason,
      p_expected_version => 1,
      p_version_before => 1,
      p_version_after => v_new_version,
      p_changed_fields => ARRAY['booking_staff_member_id'],
      p_before_json => jsonb_build_object('bookingStaffMemberId', NULL),
      p_after_json => jsonb_build_object(
        'bookingStaffMemberId', p_booking_staff_member_id
      ),
      p_metadata_json => jsonb_build_object(
        'sourceChannel', 'walk_in',
        'attribution', 'staff'
      )
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;

    v_step := public.bump_vip_floor_day_revision_v8(p_event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;

    v_response := v_base_response || jsonb_build_object(
      'boardRevision', v_revision,
      'auditLogId', v_audit_id,
      'entityVersion', v_new_version,
      'bookingStaffMemberId', p_booking_staff_member_id,
      'attribution', 'staff'
    );

    UPDATE public.admin_action_requests
    SET response_json = v_response,
        updated_at = now()
    WHERE actor_admin_id = p_actor_admin_id
      AND action = v_action
      AND idempotency_key = p_idempotency_key
      AND request_hash = p_request_hash
      AND response_json IS NOT NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING
        ERRCODE = 'XX000',
        MESSAGE = 'Walk-in staff attribution idempotency response was not found';
    END IF;

    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: create_admin_walk_in_reservation_v22(uuid, text, text, text, uuid, uuid, timestamp with time zone, timestamp with time zone, integer, uuid[], text, text, jsonb, uuid, boolean, text)
CREATE FUNCTION public.create_admin_walk_in_reservation_v22(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_day_id uuid, p_booking_offering_id uuid, p_scheduled_start_at timestamp with time zone, p_scheduled_end_at timestamp with time zone, p_guest_count integer, p_table_ids uuid[], p_guest_label text, p_operator_note text, p_expected_table_versions jsonb, p_booking_staff_member_id uuid, p_capacity_override boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_response jsonb;
  v_reservation_id uuid;
BEGIN
  v_response := public.create_admin_walk_in_reservation_v20(
    p_actor_admin_id, p_request_id, p_idempotency_key, p_request_hash,
    p_event_day_id, p_booking_offering_id, p_scheduled_start_at, p_scheduled_end_at,
    p_guest_count, p_table_ids, p_guest_label, p_operator_note,
    p_expected_table_versions, p_booking_staff_member_id, p_capacity_override, p_reason
  );
  IF v_response ->> 'action' = 'rejected' THEN RETURN v_response; END IF;
  v_reservation_id := (v_response ->> 'reservationId')::uuid;
  UPDATE public.reservations SET origin_channel = 'walk_in' WHERE id = v_reservation_id;
  PERFORM public.sync_reservation_floor_note_v22(p_actor_admin_id, v_reservation_id, p_operator_note);
  RETURN v_response || jsonb_build_object('sourceChannel', 'walk_in');
END;
$$;

-- FUNCTION: create_admin_walk_in_reservation_v23(uuid, text, text, text, uuid, uuid, timestamp with time zone, timestamp with time zone, integer, uuid[], text, text, jsonb, uuid, boolean, text)
CREATE FUNCTION public.create_admin_walk_in_reservation_v23(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_day_id uuid, p_booking_offering_id uuid, p_scheduled_start_at timestamp with time zone, p_scheduled_end_at timestamp with time zone, p_guest_count integer, p_table_ids uuid[], p_guest_label text, p_operator_note text, p_expected_table_versions jsonb, p_booking_staff_member_id uuid, p_capacity_override boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.ensure_admin_booking_slots_v80(p_event_day_id);
  RETURN public.create_admin_walk_in_reservation_v22(
    p_actor_admin_id, p_request_id, p_idempotency_key, p_request_hash,
    p_event_day_id, p_booking_offering_id, p_scheduled_start_at, p_scheduled_end_at,
    p_guest_count, p_table_ids, p_guest_label, p_operator_note,
    p_expected_table_versions, p_booking_staff_member_id, p_capacity_override, p_reason
  );
END;
$$;

-- FUNCTION: create_admin_walk_in_reservation_v7(uuid, text, text, text, text, text, text, integer, text, text, text, text)
CREATE FUNCTION public.create_admin_walk_in_reservation_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_public_slot_id text, p_public_offering_id text, p_guest_count integer, p_public_resource_code text, p_guest_label text, p_operator_note text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_slot booking_slots%ROWTYPE;
  v_offering booking_offerings%ROWTYPE;
  v_resource seat_resources%ROWTYPE;
  v_reservation_id uuid;
  v_public_code text;
  v_now timestamptz := now();
  v_due_at timestamptz;
  v_guest_label text := NULLIF(left(trim(COALESCE(p_guest_label, '')), 80), '');
  v_operator_note text := NULLIF(left(trim(COALESCE(p_operator_note, '')), 500), '');
  v_response jsonb;
BEGIN
  SELECT * INTO v_admin FROM admin_users WHERE id = p_actor_admin_id FOR UPDATE;
  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;
  IF v_admin.role NOT IN ('staff','manager','owner','engineer') THEN
    RAISE EXCEPTION 'admin role cannot create walk-in reservations';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;
    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  SELECT * INTO v_slot
  FROM booking_slots
  WHERE public_slot_id = p_public_slot_id
    AND active = true
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'booking slot not found';
  END IF;

  SELECT * INTO v_offering
  FROM booking_offerings
  WHERE public_offering_id = p_public_offering_id
    AND active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'booking offering not found';
  END IF;

  IF p_guest_count NOT BETWEEN v_offering.min_guests AND v_offering.max_guests THEN
    RAISE EXCEPTION 'guest count is outside offering limits';
  END IF;

  SELECT * INTO v_resource
  FROM seat_resources
  WHERE public_resource_code = p_public_resource_code
    AND active = true
    AND p_guest_count BETWEEN capacity_min AND capacity_max
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'seat resource not found';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM reservation_resources rr
    JOIN reservations r ON r.id = rr.reservation_id
    JOIN booking_slots locked_slot ON locked_slot.id = r.booking_slot_id
    WHERE rr.seat_resource_id = v_resource.id
      AND locked_slot.start_at < v_slot.end_at
      AND locked_slot.end_at > v_slot.start_at
      AND rr.lock_status IN ('held','payment_grace_locked','confirmed')
      AND r.status NOT IN ('cancelled','hold_expired','payment_window_expired','failed')
      AND (
        rr.lock_status = 'confirmed'
        OR COALESCE(rr.hold_expires_at, rr.admin_hold_expires_at, r.hold_expires_at, r.admin_hold_expires_at, 'infinity'::timestamptz) > v_now
      )
  ) THEN
    RAISE EXCEPTION 'seat resource is already locked';
  END IF;

  v_due_at := v_now + interval '120 minutes';
  v_public_code := upper('W' || encode(gen_random_bytes(5), 'hex'));

  INSERT INTO reservations(
    public_code,
    status_token_hash,
    booking_slot_id,
    booking_offering_id,
    guest_count,
    status,
    intake_channel,
    guest_label,
    operator_note,
    created_by_admin_id,
    confirmed_at,
    checked_in_at,
    seat_due_at,
    seat_extended_until_at,
    seat_extension_minutes
  )
  VALUES (
    v_public_code,
    encode(digest(gen_random_uuid()::text, 'sha256'), 'hex'),
    v_slot.id,
    v_offering.id,
    p_guest_count,
    'checked_in',
    'walk_in',
    v_guest_label,
    v_operator_note,
    p_actor_admin_id,
    v_now,
    v_now,
    v_due_at,
    v_due_at,
    0
  )
  RETURNING id INTO v_reservation_id;

  INSERT INTO reservation_resources(reservation_id, seat_resource_id, lock_status, confirmed_at)
  VALUES (v_reservation_id, v_resource.id, 'confirmed', v_now);

  INSERT INTO notification_jobs(reservation_id, channel, payload_json)
  VALUES (
    v_reservation_id,
    'line',
    jsonb_build_object(
      'template', 'admin_walk_in_checked_in',
      'reservationId', v_reservation_id,
      'publicCode', v_public_code,
      'guestCount', p_guest_count,
      'publicResourceCode', v_resource.public_resource_code
    )
  );

  v_response := jsonb_build_object(
    'reservationId', v_reservation_id,
    'publicCode', v_public_code,
    'publicResourceCode', v_resource.public_resource_code,
    'guestCount', p_guest_count,
    'status', 'checked_in',
    'sourceChannel', 'walk_in',
    'checkedInAt', v_now,
    'seatDueAt', v_due_at,
    'seatExtendedUntilAt', v_due_at,
    'seatExtensionMinutes', 0
  );

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'reservations', v_reservation_id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'created', 'response', v_response);
END;
$$;

-- FUNCTION: create_admin_walk_in_reservation_v8(uuid, text, text, text, uuid, uuid, timestamp with time zone, timestamp with time zone, integer, uuid[], text, text, jsonb, boolean, text)
CREATE FUNCTION public.create_admin_walk_in_reservation_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_day_id uuid, p_booking_offering_id uuid, p_scheduled_start_at timestamp with time zone, p_scheduled_end_at timestamp with time zone, p_guest_count integer, p_table_ids uuid[], p_guest_label text, p_operator_note text, p_expected_table_versions jsonb, p_capacity_override boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_action constant text := 'walk_in.created';
  v_step jsonb;
  v_offering public.booking_offerings%ROWTYPE;
  v_slot public.booking_slots%ROWTYPE;
  v_table_ids uuid[];
  v_table_id uuid;
  v_expected_version bigint;
  v_capacity int;
  v_reservation_id uuid;
  v_public_code text;
  v_checked_in_at timestamptz := now();
  v_release_at timestamptz;
  v_assignment_id uuid;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_warnings jsonb := '[]'::jsonb;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;
    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(p_actor_admin_id, 'walk_in.create'),
      ARRAY['allowed']
    );

    SELECT COALESCE(array_agg(DISTINCT id ORDER BY id), '{}'::uuid[])
    INTO v_table_ids
    FROM unnest(COALESCE(p_table_ids, '{}'::uuid[])) AS requested(id);
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_event_day_id IS NULL OR p_booking_offering_id IS NULL
      OR p_scheduled_start_at IS NULL OR p_scheduled_end_at IS NULL
      OR p_scheduled_start_at >= p_scheduled_end_at
      OR p_guest_count IS NULL OR p_guest_count < 1
      OR cardinality(v_table_ids) = 0
      OR cardinality(v_table_ids) <> cardinality(COALESCE(p_table_ids, '{}'::uuid[]))
      OR EXISTS (SELECT 1 FROM unnest(COALESCE(p_table_ids, '{}'::uuid[])) AS t(id) WHERE id IS NULL)
      OR p_expected_table_versions IS NULL
      OR jsonb_typeof(p_expected_table_versions) <> 'array'
      OR jsonb_array_length(p_expected_table_versions) <> cardinality(v_table_ids)
      OR char_length(COALESCE(p_guest_label, '')) > 80
      OR char_length(COALESCE(p_operator_note, '')) > 500
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'walkInCommand')
        )), ARRAY['allowed']
      );
    END IF;
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_expected_table_versions) AS item(value)
      WHERE jsonb_typeof(value) <> 'object'
         OR NOT (value ?& ARRAY['tableId', 'expectedVersion'])
         OR value - ARRAY['tableId', 'expectedVersion'] <> '{}'::jsonb
         OR jsonb_typeof(value -> 'tableId') <> 'string'
         OR jsonb_typeof(value -> 'expectedVersion') <> 'number'
         OR value ->> 'tableId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
         OR value ->> 'expectedVersion' !~ '^[1-9][0-9]*$'
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'expectedTableVersions')
        )), ARRAY['allowed']
      );
    END IF;
    IF (
      SELECT count(DISTINCT (value ->> 'tableId')::uuid)
      FROM jsonb_array_elements(p_expected_table_versions) AS item(value)
    ) <> cardinality(v_table_ids)
      OR EXISTS (
        SELECT 1 FROM unnest(v_table_ids) AS requested(id)
        WHERE NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(p_expected_table_versions) AS item(value)
          WHERE (value ->> 'tableId')::uuid = requested.id
        )
      )
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND',
          'details', jsonb_build_object('field', 'expectedTableVersions', 'reason', 'exact_table_set_required')
        )), ARRAY['allowed']
      );
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.event_days AS ed
      WHERE ed.id = p_event_day_id
        AND ed.sales_open_at <= p_scheduled_start_at
        AND ed.sales_close_at >= p_scheduled_end_at
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', CASE WHEN EXISTS (SELECT 1 FROM public.event_days WHERE id = p_event_day_id)
            THEN 'INVALID_COMMAND' ELSE 'NOT_FOUND' END,
          'details', jsonb_build_object('field', 'eventDayId', 'reason', 'missing_or_interval_outside_day')
        )), ARRAY['allowed']
      );
    END IF;
    SELECT * INTO v_offering
    FROM public.booking_offerings
    WHERE id = p_booking_offering_id AND active = true;
    IF NOT FOUND THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'NOT_FOUND', 'details', jsonb_build_object('entityType', 'booking_offering')
        )), ARRAY['allowed']
      );
    END IF;
    IF p_guest_count NOT BETWEEN v_offering.min_guests AND v_offering.max_guests THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'guestCount', 'reason', 'offering_limits')
        )), ARRAY['allowed']
      );
    END IF;

    -- Deterministic compatibility anchor only; canonical schedule remains the
    -- caller's exact interval and is never rounded to this slot.
    SELECT * INTO v_slot
    FROM public.booking_slots AS bs
    WHERE bs.event_day_id = p_event_day_id
      AND bs.active = true
    ORDER BY
      abs(extract(epoch FROM (bs.start_at - p_scheduled_start_at))),
      bs.start_at,
      bs.id
    LIMIT 1;
    IF NOT FOUND THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'SLOT_COMPATIBILITY_MISSING',
          'details', jsonb_build_object('entityType', 'compatibility_anchor_slot')
        )), ARRAY['allowed']
      );
    END IF;

    v_release_at := GREATEST(p_scheduled_end_at, v_checked_in_at + interval '120 minutes');
    PERFORM sr.id FROM public.seat_resources AS sr
    WHERE sr.id = ANY(v_table_ids)
    ORDER BY sr.id FOR UPDATE OF sr;
    IF (SELECT count(*) FROM public.seat_resources WHERE id = ANY(v_table_ids)) <> cardinality(v_table_ids) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'NOT_FOUND', 'details', jsonb_build_object('entityType', 'table')
        )), ARRAY['allowed']
      );
    END IF;
    FOREACH v_table_id IN ARRAY v_table_ids LOOP
      SELECT (value ->> 'expectedVersion')::bigint INTO v_expected_version
      FROM jsonb_array_elements(p_expected_table_versions) AS item(value)
      WHERE (value ->> 'tableId')::uuid = v_table_id;
      IF NOT EXISTS (
        SELECT 1 FROM public.seat_resources
        WHERE id = v_table_id AND active = true AND version = v_expected_version
      ) THEN
        IF EXISTS (SELECT 1 FROM public.seat_resources WHERE id = v_table_id AND version <> v_expected_version) THEN
          PERFORM public.assert_vip_floor_helper_success_v8(
            jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
              'code', 'VERSION_CONFLICT',
              'currentVersion', (SELECT version FROM public.seat_resources WHERE id = v_table_id),
              'details', jsonb_build_object('entityType', 'table')
            )), ARRAY['allowed']
          );
        ELSE
          PERFORM public.assert_vip_floor_helper_success_v8(
            jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
              'code', 'TABLE_LOCKED', 'details', jsonb_build_object('reason', 'inactive')
            )), ARRAY['allowed']
          );
        END IF;
      END IF;
    END LOOP;
    PERFORM rr.id
    FROM public.reservation_resources AS rr
    WHERE rr.seat_resource_id = ANY(v_table_ids)
      AND rr.assigned_start_at < v_release_at
      AND rr.assigned_end_at > p_scheduled_start_at
    ORDER BY rr.id FOR UPDATE OF rr;
    PERFORM rb.id
    FROM public.reservation_blocks AS rb
    WHERE rb.event_day_id = p_event_day_id
      AND rb.status = 'active'
      AND rb.start_at < v_release_at
      AND rb.end_at > p_scheduled_start_at
      AND EXISTS (
        SELECT 1
        FROM public.reservation_block_targets AS rbt
        JOIN public.seat_resources AS sr ON sr.id = ANY(v_table_ids)
        WHERE rbt.block_id = rb.id
          AND (
            rbt.seat_resource_id = sr.id
            OR rbt.floor_section_id = sr.floor_section_id
            OR rbt.venue_wide
          )
      )
    ORDER BY rb.id FOR UPDATE OF rb;
    FOREACH v_table_id IN ARRAY v_table_ids LOOP
      v_step := public.assert_assignment_conflict_free_v8(
        p_event_day_id, NULL, v_table_id,
        p_scheduled_start_at, v_release_at, now()
      );
      PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
      SELECT COALESCE(jsonb_agg(warning ORDER BY warning::text), '[]'::jsonb)
      INTO v_warnings
      FROM (
        SELECT DISTINCT warning FROM jsonb_array_elements(
          v_warnings || COALESCE(v_step -> 'warnings', '[]'::jsonb)
        ) AS all_warnings(warning)
      ) AS deduplicated;
    END LOOP;

    IF COALESCE(p_capacity_override, false) THEN
      IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'reason', 'reason', 'capacity_override')
          )), ARRAY['allowed']
        );
      END IF;
      PERFORM public.assert_vip_floor_helper_success_v8(
        public.require_admin_capability_v8(p_actor_admin_id, 'reservation_assignment.write'),
        ARRAY['allowed']
      );
    END IF;
    SELECT COALESCE(sum(capacity_max), 0)::int INTO v_capacity
    FROM public.seat_resources WHERE id = ANY(v_table_ids);
    IF v_capacity < p_guest_count THEN
      IF NOT COALESCE(p_capacity_override, false) THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
            'code', 'CAPACITY_WARNING_REQUIRES_OVERRIDE',
            'details', jsonb_build_object('guestCount', p_guest_count, 'combinedCapacity', v_capacity)
          )), ARRAY['allowed']
        );
      END IF;
    END IF;

    v_public_code := upper(
      'W' || left(replace(gen_random_uuid()::text, '-', ''), 10)
    );
    INSERT INTO public.reservations(
      public_code, status_token_hash, booking_slot_id, booking_offering_id,
      guest_count, status, intake_channel, guest_label, operator_note,
      created_by_admin_id, confirmed_at, checked_in_at, seat_due_at,
      seat_extended_until_at, seat_extension_minutes,
      event_day_id, scheduled_start_at, scheduled_end_at, expected_release_at,
      service_status, service_status_changed_at, arrived_at, version
    ) VALUES (
      v_public_code, md5(gen_random_uuid()::text || clock_timestamp()::text),
      v_slot.id, v_offering.id, p_guest_count, 'checked_in', 'walk_in',
      NULLIF(btrim(COALESCE(p_guest_label, '')), ''),
      NULLIF(btrim(COALESCE(p_operator_note, '')), ''),
      p_actor_admin_id, v_checked_in_at, v_checked_in_at, v_release_at,
      v_release_at, 0, p_event_day_id, p_scheduled_start_at,
      p_scheduled_end_at, v_release_at, 'seated', v_checked_in_at,
      v_checked_in_at, 1
    ) RETURNING id INTO v_reservation_id;

    FOREACH v_table_id IN ARRAY v_table_ids LOOP
      INSERT INTO public.reservation_resources(
        reservation_id, seat_resource_id, lock_status, confirmed_at,
        assigned_start_at, assigned_end_at, assignment_role,
        assigned_by_admin_id
      ) VALUES (
        v_reservation_id, v_table_id, 'confirmed', v_checked_in_at,
        p_scheduled_start_at, v_release_at,
        CASE WHEN v_table_id = v_table_ids[1] THEN 'primary' ELSE 'additional' END,
        p_actor_admin_id
      ) RETURNING id INTO v_assignment_id;
      INSERT INTO public.reservation_assignment_events(
        reservation_id, reservation_resource_id, seat_resource_id, event_type,
        interval_before, interval_after, actor_admin_id, reason, request_id,
        occurred_at
      ) VALUES (
        v_reservation_id, v_assignment_id, v_table_id, 'assigned', NULL,
        jsonb_build_object('startAt', p_scheduled_start_at, 'endAt', v_release_at),
        p_actor_admin_id, p_reason, p_request_id, v_checked_in_at
      );
    END LOOP;
    INSERT INTO public.reservation_service_events(
      reservation_id, from_status, to_status, occurred_at,
      actor_admin_id, reason, request_id, metadata_json
    ) VALUES (
      v_reservation_id, NULL, 'seated', v_checked_in_at,
      p_actor_admin_id, p_reason, p_request_id,
      jsonb_build_object('source', 'walk_in')
    );

    PERFORM ed.id FROM public.event_days AS ed
    WHERE ed.id = p_event_day_id FOR KEY SHARE OF ed;
    PERFORM public.lock_vip_floor_day_revision_v32(p_event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1 INTO v_predicted_revision
    FROM (SELECT 1) AS seed
    LEFT JOIN public.vip_floor_day_revisions AS vfr ON vfr.event_day_id = p_event_day_id;
    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, p_event_day_id, v_reservation_id,
      'reservation', v_reservation_id, v_action, p_request_id, p_reason,
      NULL, NULL, 1,
      ARRAY['created'], NULL,
      jsonb_build_object(
        'status', 'checked_in', 'serviceStatus', 'seated',
        'scheduledStartAt', p_scheduled_start_at,
        'scheduledEndAt', p_scheduled_end_at,
        'expectedReleaseAt', v_release_at, 'version', 1
      ),
      jsonb_build_object(
        'tableIds', to_jsonb(v_table_ids),
        'bookingOfferingId', v_offering.id,
        'capacityOverride', COALESCE(p_capacity_override, false),
        'warnings', v_warnings
      )
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_response := jsonb_build_object(
      'ok', true, 'action', v_action, 'reused', false,
      'reservationId', v_reservation_id, 'entityVersion', 1,
      'boardRevision', v_predicted_revision, 'auditLogId', v_audit_id,
      'publicCode', v_public_code, 'tableIds', to_jsonb(v_table_ids),
      'scheduledStartAt', p_scheduled_start_at,
      'scheduledEndAt', p_scheduled_end_at,
      'expectedReleaseAt', v_release_at,
      'warnings', v_warnings
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(p_event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'XX000', MESSAGE = 'VIP floor revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS v_error_detail = PG_EXCEPTION_DETAIL, v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN RETURN v_error_detail::jsonb; END IF;
    RAISE;
  END;
END;
$_$;

-- FUNCTION: create_ticket_order_v23(text, text, text, date, text, text, text, integer, integer, jsonb)
CREATE FUNCTION public.create_ticket_order_v23(p_public_code text, p_event_id text, p_event_slug text, p_event_date date, p_event_title text, p_environment text, p_stripe_account_id text, p_amount_yen integer, p_total_quantity integer, p_items_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order public.ticket_orders%ROWTYPE;
  v_event_session_id uuid;
  v_declared_quantity integer;
BEGIN
  IF p_items_json IS NULL OR jsonb_typeof(p_items_json) <> 'array'
    OR jsonb_array_length(p_items_json) = 0
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'items_invalid');
  END IF;
  SELECT COALESCE(sum((item ->> 'quantity')::integer), 0)
  INTO v_declared_quantity
  FROM jsonb_array_elements(p_items_json) AS item;
  IF v_declared_quantity <> p_total_quantity THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'quantity_mismatch');
  END IF;

  SELECT session.id INTO v_event_session_id
  FROM public.ticket_event_sessions AS session
  WHERE session.catalog_event_id = p_event_id
    AND session.event_date = p_event_date
    AND session.environment = p_environment
    AND session.stripe_account_key = COALESCE(p_stripe_account_id, 'platform');

  INSERT INTO public.ticket_orders(
    public_code, event_id, event_slug, event_date, event_title,
    status, environment, stripe_account_id, amount_yen, total_quantity,
    items_json, event_session_id, check_in_mode
  ) VALUES (
    p_public_code, p_event_id, p_event_slug, p_event_date, p_event_title,
    'pending', p_environment, p_stripe_account_id, p_amount_yen,
    p_total_quantity, p_items_json, v_event_session_id, 'legacy_qr'
  ) RETURNING * INTO v_order;

  RETURN jsonb_build_object(
    'action', 'created', 'orderId', v_order.id,
    'publicCode', v_order.public_code, 'status', v_order.status);
END;
$$;

-- FUNCTION: dedupe_legacy_ticket_notice_v33()
CREATE FUNCTION public.dedupe_legacy_ticket_notice_v33() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NEW.ticket_order_id IS NOT NULL AND NEW.channel='email' AND NEW.payload_json->>'template'='ticket_admission' THEN
  PERFORM 1 FROM public.ticket_orders WHERE id=NEW.ticket_order_id FOR UPDATE;
  IF EXISTS (SELECT 1 FROM public.notification_jobs WHERE ticket_order_id=NEW.ticket_order_id AND channel='email' AND payload_json->>'template'='ticket_admission' AND status NOT IN ('dead','cancelled')) THEN RETURN NULL; END IF;
 END IF;
 RETURN NEW;
END; $$;

-- FUNCTION: derive_vip_payment_refund_state_v8(uuid)
CREATE FUNCTION public.derive_vip_payment_refund_state_v8(p_payment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_payment public.payments%ROWTYPE;
  v_refunded bigint := 0;
  v_pending bigint := 0;
  v_reserved bigint := 0;
  v_derived text;
BEGIN
  SELECT * INTO v_payment FROM public.payments WHERE id = p_payment_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  SELECT
    COALESCE(SUM(sr.amount_yen) FILTER (WHERE lower(sr.status) = 'succeeded'), 0),
    COALESCE(SUM(sr.amount_yen) FILTER (WHERE lower(sr.status) IN ('pending','requires_action','created')), 0)
  INTO v_refunded, v_pending
  FROM public.stripe_refunds sr
  WHERE sr.payment_id = v_payment.id;

  -- In-flight internal reservations whose provider identity does not exist
  -- yet. Once stripe_refunds carries the row the provider amount rules and the
  -- case amount must not be counted twice.
  SELECT COALESCE(SUM(rc.amount_yen), 0)
  INTO v_reserved
  FROM public.refund_cases rc
  WHERE rc.payment_id = v_payment.id
    AND rc.status IN ('required','requested','approved','processing')
    AND NOT EXISTS (
      SELECT 1 FROM public.stripe_refunds sr WHERE sr.refund_case_id = rc.id
    );

  v_derived := CASE
    WHEN v_payment.status::text NOT IN ('succeeded','refund_pending','refunded','partially_refunded')
      THEN v_payment.status::text
    WHEN v_payment.amount_yen > 0 AND v_refunded >= v_payment.amount_yen THEN 'refunded'
    WHEN v_refunded > 0 THEN 'partially_refunded'
    WHEN v_pending > 0 OR v_reserved > 0 THEN 'refund_pending'
    ELSE 'succeeded'
  END;

  RETURN jsonb_build_object(
    'found', true,
    'paymentId', v_payment.id,
    'capturedYen', v_payment.amount_yen,
    'refundedYen', v_refunded,
    'pendingRefundYen', v_pending,
    'reservedYen', v_reserved,
    'remainingRefundableYen', GREATEST(v_payment.amount_yen - v_refunded - v_pending - v_reserved, 0),
    'currentStatus', v_payment.status,
    'derivedStatus', v_derived
  );
END;
$$;

-- FUNCTION: email_recipient_suppressed_v59(text)
CREATE FUNCTION public.email_recipient_suppressed_v59(p_recipient_email_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_recipient_email_hash IS NULL
    OR char_length(p_recipient_email_hash) NOT BETWEEN 16 AND 256
    OR p_recipient_email_hash ~ E'[\\r\\n\\0]'
  THEN
    RAISE EXCEPTION 'invalid recipient email hash';
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.transactional_email_suppressions AS suppression
    WHERE suppression.recipient_email_hash = p_recipient_email_hash
      AND suppression.active
  );
END;
$$;

-- FUNCTION: enforce_refund_case_binding_v8()
CREATE FUNCTION public.enforce_refund_case_binding_v8() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.stripe_refund_id IS NOT NULL
    AND NEW.stripe_refund_id IS DISTINCT FROM OLD.stripe_refund_id THEN
    RAISE EXCEPTION 'refund_case_stripe_refund_id_immutable'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: enforce_stripe_dispute_identity_v8()
CREATE FUNCTION public.enforce_stripe_dispute_identity_v8() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.environment IS DISTINCT FROM NEW.environment
    OR COALESCE(OLD.stripe_account_id, 'platform') IS DISTINCT FROM COALESCE(NEW.stripe_account_id, 'platform')
    OR OLD.stripe_dispute_id IS DISTINCT FROM NEW.stripe_dispute_id
    OR (OLD.reservation_id IS NOT NULL AND NEW.reservation_id IS DISTINCT FROM OLD.reservation_id)
    OR (OLD.payment_id IS NOT NULL AND NEW.payment_id IS DISTINCT FROM OLD.payment_id) THEN
    RAISE EXCEPTION 'stripe_dispute_identity_immutable'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: enforce_stripe_refund_identity_v8()
CREATE FUNCTION public.enforce_stripe_refund_identity_v8() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Generated columns are computed after BEFORE triggers, so NEW's
  -- stripe_account_key is not reliable here; compare the source column
  -- with the same NULL->'platform' normalisation instead.
  IF OLD.environment IS DISTINCT FROM NEW.environment
    OR COALESCE(OLD.stripe_account_id, 'platform') IS DISTINCT FROM COALESCE(NEW.stripe_account_id, 'platform')
    OR OLD.stripe_refund_id IS DISTINCT FROM NEW.stripe_refund_id
    OR OLD.reservation_id IS DISTINCT FROM NEW.reservation_id
    OR OLD.payment_id IS DISTINCT FROM NEW.payment_id
    OR (OLD.refund_case_id IS NOT NULL AND NEW.refund_case_id IS DISTINCT FROM OLD.refund_case_id) THEN
    RAISE EXCEPTION 'stripe_refund_identity_immutable'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: enqueue_admin_reservation_email_v10(uuid, text, text, text, uuid, bigint, text, text)
CREATE FUNCTION public.enqueue_admin_reservation_email_v10(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_version bigint, p_template text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation.email.enqueued';
  v_template text := lower(btrim(COALESCE(p_template, '')));
  v_step jsonb;
  v_actor public.admin_users%ROWTYPE;
  v_reservation public.reservations%ROWTYPE;
  v_job_id uuid;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;

    SELECT *
    INTO v_actor
    FROM public.admin_users
    WHERE id = p_actor_admin_id
      AND active = true;

    IF NOT FOUND OR v_actor.role <> 'owner' THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', CASE WHEN NOT FOUND THEN 'UNAUTHENTICATED' ELSE 'FORBIDDEN' END,
            'details', jsonb_build_object('capability', 'owner')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_expected_version IS NULL
      OR p_expected_version < 1
      OR v_template NOT IN (
        'reservation_created',
        'reservation_changed',
        'waitlist_called',
        'waitlist_recalled'
      )
      OR p_reason <> '管理画面操作'
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'emailCommand')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    v_step := public.assert_reservation_version_v8(
      p_reservation_id, p_expected_version
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);

    SELECT *
    INTO v_reservation
    FROM public.reservations
    WHERE id = p_reservation_id;

    IF v_reservation.status <> 'confirmed'
      OR v_reservation.customer_id IS NULL
      OR NOT EXISTS (
        SELECT 1
        FROM public.customer_profiles AS cp
        WHERE cp.customer_id = v_reservation.customer_id
          AND cp.email_ciphertext IS NOT NULL
      )
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_STATE_TRANSITION',
            'details', jsonb_build_object(
              'reason', 'confirmed_reservation_with_customer_email_required'
            )
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    INSERT INTO public.notification_jobs(
      reservation_id,
      channel,
      status,
      payload_json,
      attempt_count,
      next_attempt_at
    )
    VALUES (
      v_reservation.id,
      'email',
      'pending',
      jsonb_build_object(
        'schemaVersion', 'ghost.vip-email.v1',
        'template', v_template
      ),
      0,
      now()
    )
    RETURNING id INTO v_job_id;

    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id,
      v_reservation.event_day_id,
      v_reservation.id,
      'reservation',
      v_reservation.id,
      v_action,
      p_request_id,
      p_reason,
      NULL,
      NULL,
      NULL,
      '{}'::text[],
      jsonb_build_object(
        'outboxStatus', 'not_enqueued',
        'version', v_reservation.version
      ),
      jsonb_build_object(
        'outboxStatus', 'pending',
        'version', v_reservation.version
      ),
      jsonb_build_object(
        'notificationJobId', v_job_id,
        'template', v_template,
        'maxAttempts', 3
      )
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;

    PERFORM public.lock_vip_floor_day_revision_v32(v_reservation.event_day_id);
    SELECT COALESCE(revision, 0) + 1
    INTO v_predicted_revision
    FROM public.vip_floor_day_revisions
    WHERE event_day_id = v_reservation.event_day_id;
    v_predicted_revision := COALESCE(v_predicted_revision, 1);

    v_response := jsonb_build_object(
      'ok', true,
      'action', v_action,
      'reused', false,
      'reservationId', v_reservation.id,
      'entityVersion', v_reservation.version,
      'boardRevision', v_predicted_revision,
      'auditLogId', v_audit_id,
      'notificationJobId', v_job_id,
      'notificationStatus', 'pending',
      'maxAttempts', 3
    );

    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );

    v_step := public.bump_vip_floor_day_revision_v8(
      v_reservation.event_day_id, v_audit_id
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING
        ERRCODE = 'XX000',
        MESSAGE = 'VIP email outbox revision prediction diverged';
    END IF;

    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: enqueue_ticket_alerts_v42(text, jsonb, jsonb)
CREATE FUNCTION public.enqueue_ticket_alerts_v42(p_line_target_id text, p_alerts jsonb, p_metrics jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_now timestamptz:=clock_timestamp();
  v_state public.ticket_alert_dispatch_state%ROWTYPE;
  v_alerts jsonb; v_metrics jsonb; v_job uuid; v_status text; v_kind text;
BEGIN
  IF p_line_target_id IS NULL OR p_line_target_id !~ '^C[0-9a-f]{32}$'
    OR p_alerts IS NULL OR jsonb_typeof(p_alerts)<>'array' OR jsonb_array_length(p_alerts)>20
    OR p_metrics IS NULL OR jsonb_typeof(p_metrics)<>'object' THEN
    RAISE EXCEPTION 'ticket_alert_input_invalid';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_alerts) a WHERE jsonb_typeof(a)<>'string'
    OR a#>>'{}' NOT IN ('metrics_invalid','otp_queue_aged','purchase_notice_aged','delivery_needs_review',
      'email_circuit_open','checkout_review_pending','refund_review_pending','email_dispatcher_missing',
      'checkout_recovery_missing','revision_evidence_unavailable','revision_evidence_expiring',
      'resend_attestation_unavailable','resend_attestation_expiring','notification_delivery_aged',
      'notification_delivery_failed','monitoring_heartbeat_missing','notification_configuration_missing','email_capacity_low','email_capacity_unverified')) THEN
    RAISE EXCEPTION 'ticket_alert_code_invalid';
  END IF;
  SELECT COALESCE(jsonb_agg(code ORDER BY code),'[]') INTO v_alerts FROM (SELECT DISTINCT value AS code FROM jsonb_array_elements_text(p_alerts)) a;
  -- Store only bounded numeric metrics. No customer values, opaque error text or secrets.
  SELECT COALESCE(jsonb_object_agg(key,value),'{}') INTO v_metrics FROM jsonb_each(p_metrics)
  WHERE key IN ('otpOldestSeconds','purchaseOldestSeconds','deliveryDead','openCircuits',
    'checkoutReviewCount','refundReviewCount','emailHeartbeatAgeSeconds','checkoutHeartbeatAgeSeconds')
    AND CASE WHEN jsonb_typeof(value)='number' THEN (value#>>'{}')::numeric BETWEEN 0 AND 1000000000000 ELSE false END;
  IF NOT pg_try_advisory_xact_lock(hashtextextended('ticket_alert_dispatch_v42',0)) THEN
    RETURN jsonb_build_object('action','busy');
  END IF;
  INSERT INTO public.ticket_alert_dispatch_state(id,line_target_id) VALUES(true,p_line_target_id) ON CONFLICT(id) DO NOTHING;
  SELECT * INTO v_state FROM public.ticket_alert_dispatch_state WHERE id FOR UPDATE;
  IF v_state.line_target_id<>p_line_target_id THEN RETURN jsonb_build_object('action','review_required','reason','target_changed'); END IF;
  UPDATE public.ticket_alert_dispatch_state SET observed_alerts=v_alerts,last_observed_at=v_now WHERE id;
  IF v_state.notification_job_id IS NOT NULL THEN
    SELECT status INTO v_status FROM public.notification_jobs WHERE id=v_state.notification_job_id;
    IF v_status IS NULL OR v_status='dead' THEN RETURN jsonb_build_object('action','review_required','reason','delivery_failed'); END IF;
    IF v_status<>'sent' THEN RETURN jsonb_build_object('action','delivery_pending'); END IF;
    -- Coalesce flapping and repeated cron invocations. At most four new jobs/hour.
    IF v_now<v_state.last_enqueued_at+interval '15 minutes' THEN RETURN jsonb_build_object('action','coalescing'); END IF;
  END IF;
  IF v_alerts=v_state.enqueued_alerts THEN
    IF v_alerts='[]' OR v_now<v_state.last_enqueued_at+interval '1 hour' THEN RETURN jsonb_build_object('action','unchanged'); END IF;
    v_kind:='reminder';
  ELSE v_kind:=CASE WHEN v_alerts='[]' THEN 'recovery' ELSE 'alert' END;
  END IF;
  INSERT INTO public.notification_jobs(channel,payload_json)
  VALUES('line',jsonb_build_object('template','ticket_health_v42','lineTargetId',p_line_target_id,
    'alert',jsonb_build_object('alerts',v_alerts,'metrics',v_metrics,'status',v_kind))) RETURNING id INTO v_job;
  UPDATE public.ticket_alert_dispatch_state SET enqueued_alerts=v_alerts,notification_job_id=v_job,last_enqueued_at=v_now WHERE id;
  RETURN jsonb_build_object('action','enqueued','status',v_kind);
END;
$_$;

-- FUNCTION: enqueue_ticket_daily_line_report_v41(text, date)
CREATE FUNCTION public.enqueue_ticket_daily_line_report_v41(p_line_target_id text, p_start_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_now timestamptz:=clock_timestamp();
  v_date date;
  v_cutoff timestamptz;
  v_previous public.ticket_daily_line_reports%ROWTYPE;
  v_report jsonb;
  v_job uuid;
  v_revision integer;
  v_job_status text;
BEGIN
  IF p_line_target_id IS NULL OR p_line_target_id !~ '^C[0-9a-f]{32}$' OR p_start_date IS NULL THEN
    RAISE EXCEPTION 'ticket_daily_line_configuration_invalid';
  END IF;
  v_date:=public.ticket_daily_line_service_date_v41(v_now);
  IF v_date<p_start_date THEN RETURN jsonb_build_object('action','not_due'); END IF;
  v_cutoff:=(v_date+time '23:30') AT TIME ZONE 'Asia/Tokyo';
  -- This lock serializes this report only; it does not lock orders or admissions.
  PERFORM pg_advisory_xact_lock(hashtextextended('ticket_daily_line_v41:'||v_date::text,0));
  SELECT * INTO v_previous FROM public.ticket_daily_line_reports WHERE service_date=v_date FOR UPDATE;
  IF FOUND THEN
    IF v_previous.line_target_id<>p_line_target_id THEN
      RETURN jsonb_build_object('action','review_required','reason','target_changed');
    END IF;
    SELECT status INTO v_job_status FROM public.notification_jobs WHERE id=v_previous.notification_job_id;
    IF v_job_status IS NULL OR v_job_status='dead' THEN RETURN jsonb_build_object('action','review_required','reason','delivery_failed'); END IF;
    IF v_job_status<>'sent' THEN RETURN jsonb_build_object('action','delivery_pending','revision',v_previous.revision); END IF;
    IF v_now<v_previous.updated_at+interval '5 minutes' THEN RETURN jsonb_build_object('action','coalescing'); END IF;
  END IF;

  -- One MVCC statement: admissions and unresolved orders are observed together.
  -- Existing canary runtime uses test; live/platform excludes it and Connect accounts.
  WITH orders AS MATERIALIZED (
    SELECT id,status,total_quantity,COALESCE((to_jsonb(o)->>'provider_paid_at')::timestamptz,paid_at) AS payment_at
    FROM public.ticket_orders o
    WHERE event_date=v_date AND environment='live' AND stripe_account_key='platform'
  ), units AS MATERIALIZED (
    SELECT a.ticket_type_id,a.status,o.status AS order_status,o.payment_at
    FROM orders o JOIN public.ticket_admissions a ON a.ticket_order_id=o.id
  ), counts AS (
    SELECT count(*) FILTER (WHERE status IN ('issued','admitted') AND order_status IN ('paid','fulfilled') AND payment_at<v_cutoff) AS total,
      count(*) FILTER (WHERE status IN ('issued','admitted') AND order_status IN ('paid','fulfilled') AND payment_at<v_cutoff AND ticket_type_id IN ('general-men','fast-entry-unlimited-drink-men')) AS male,
      count(*) FILTER (WHERE status IN ('issued','admitted') AND order_status IN ('paid','fulfilled') AND payment_at<v_cutoff AND ticket_type_id IN ('general-women','fast-entry-unlimited-drink-women')) AS female,
      count(*) FILTER (WHERE status IN ('issued','admitted') AND order_status IN ('paid','fulfilled') AND payment_at<v_cutoff AND ticket_type_id='fast-entry-unlimited-drink-men') AS fast_male,
      count(*) FILTER (WHERE status IN ('issued','admitted') AND order_status IN ('paid','fulfilled') AND payment_at<v_cutoff AND ticket_type_id='fast-entry-unlimited-drink-women') AS fast_female,
      count(*) FILTER (WHERE status='void' OR order_status='refunded') AS voided
    FROM units
  ), unresolved AS (
    SELECT COALESCE(sum(CASE
      WHEN o.status='pending' THEN o.total_quantity
      WHEN o.status IN ('paid','fulfilled') AND (o.payment_at IS NULL OR o.payment_at>=v_cutoff) THEN o.total_quantity
      WHEN o.status IN ('paid','fulfilled') THEN GREATEST(0,o.total_quantity-(SELECT count(*) FROM public.ticket_admissions a WHERE a.ticket_order_id=o.id))
      ELSE 0 END),0) AS pending FROM orders o
  )
  SELECT jsonb_build_object('serviceDate',v_date::text,'total',c.total,'male',c.male,'female',c.female,
    'unclassified',c.total-c.male-c.female,'fastEntryMale',c.fast_male,'fastEntryFemale',c.fast_female,
    'voided',c.voided,'pending',u.pending)
  INTO v_report FROM counts c CROSS JOIN unresolved u;

  IF v_previous.snapshot=v_report THEN RETURN jsonb_build_object('action','unchanged','revision',v_previous.revision); END IF;
  IF v_previous.revision>=24 THEN RETURN jsonb_build_object('action','review_required','reason','revision_limit'); END IF;
  v_revision:=COALESCE(v_previous.revision,0)+1;
  INSERT INTO public.notification_jobs(channel,payload_json)
  VALUES('line',jsonb_build_object('template','ticket_daily_sales_v41','lineTargetId',p_line_target_id,
    'report',v_report,'revision',v_revision,'asOf',v_now)) RETURNING id INTO v_job;
  INSERT INTO public.ticket_daily_line_reports(service_date,line_target_id,revision,snapshot,notification_job_id)
  VALUES(v_date,p_line_target_id,v_revision,v_report,v_job)
  ON CONFLICT(service_date) DO UPDATE SET revision=EXCLUDED.revision,snapshot=EXCLUDED.snapshot,
    notification_job_id=EXCLUDED.notification_job_id,updated_at=v_now;
  RETURN jsonb_build_object('action','enqueued','revision',v_revision);
END;
$_$;

-- FUNCTION: ensure_admin_booking_slots_v80(uuid)
CREATE FUNCTION public.ensure_admin_booking_slots_v80(p_event_day_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_day public.event_days%ROWTYPE;
  v_inserted int;
BEGIN
  SELECT * INTO v_day
  FROM public.event_days
  WHERE id = p_event_day_id;
  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.booking_slots
    WHERE event_day_id = p_event_day_id
      AND active = true
  ) THEN
    RETURN 0;
  END IF;

  -- Same transaction-local marker the v8 commands set in preclaim. The v23
  -- wrappers call this helper before the delegated command claims its
  -- request, so the marker must be present here to keep the legacy compat
  -- triggers from attributing this write to v7_compat when dual-write is on.
  PERFORM set_config('ghost.vip_floor_v8_writer', 'on', true);

  INSERT INTO public.booking_slots(
    event_day_id, public_slot_id, start_at, end_at,
    bookable_until_at, cancel_free_until_at,
    no_show_fee_yen, late_cancel_fee_yen, admin_only, active
  )
  SELECT
    v_day.id,
    'ghost-osaka-' || to_char(v_day.business_date, 'YYYYMMDD')
      || '-' || template.slot_suffix || '-admin',
    (v_day.business_date::timestamp + make_interval(hours => template.start_hour))
      AT TIME ZONE v_day.venue_timezone,
    (v_day.business_date::timestamp + make_interval(hours => template.start_hour + 2))
      AT TIME ZONE v_day.venue_timezone,
    (v_day.business_date + time '21:00') AT TIME ZONE v_day.venue_timezone,
    (v_day.business_date::timestamp + make_interval(hours => template.start_hour - 2))
      AT TIME ZONE v_day.venue_timezone,
    10000,
    5000,
    true,
    true
  FROM (
    VALUES
      (22, '2200'),
      (23, '2300'),
      (24, '0000'),
      (25, '0100'),
      (26, '0200'),
      (27, '0300')
  ) AS template(start_hour, slot_suffix)
  ON CONFLICT (public_slot_id) DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN v_inserted;
END;
$$;

-- FUNCTION: ensure_admin_event_day_v80(uuid, text, text, text, date, text)
CREATE FUNCTION public.ensure_admin_event_day_v80(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_business_date date, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'business_day.ensured';
  v_step jsonb;
  v_day public.event_days%ROWTYPE;
  v_created boolean := false;
  v_slots_created int := 0;
  v_audit_id uuid;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    IF p_actor_admin_id IS NULL
      OR NOT EXISTS (
        SELECT 1
        FROM public.admin_users
        WHERE id = p_actor_admin_id
          AND active = true
      )
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'UNAUTHENTICATED',
            'details', jsonb_build_object('reason', 'actor_unavailable')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.admin_users
      WHERE id = p_actor_admin_id
        AND active = true
        AND role = 'owner'
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'FORBIDDEN',
            'details', jsonb_build_object('reason', 'owner_required')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    IF p_business_date IS NULL
      OR NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL
      OR char_length(p_reason) > 240
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object(
              'field', CASE
                WHEN p_business_date IS NULL THEN 'businessDate'
                WHEN NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL
                  OR char_length(COALESCE(p_reason, '')) > 240 THEN 'reason'
                ELSE 'requestId'
              END
            )
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;

    SELECT * INTO v_day
    FROM public.event_days
    WHERE business_date = p_business_date
    FOR NO KEY UPDATE;

    IF NOT FOUND THEN
      INSERT INTO public.event_days(
        business_date, venue_timezone, sales_open_at, sales_close_at, operating_status
      )
      VALUES (
        p_business_date,
        'Asia/Tokyo',
        (p_business_date + time '12:00') AT TIME ZONE 'Asia/Tokyo',
        ((p_business_date + 1) + time '05:00') AT TIME ZONE 'Asia/Tokyo',
        'open'
      )
      ON CONFLICT (business_date) DO NOTHING
      RETURNING * INTO v_day;
      v_created := v_day.id IS NOT NULL;
      IF v_day.id IS NULL THEN
        SELECT * INTO v_day
        FROM public.event_days
        WHERE business_date = p_business_date
        FOR NO KEY UPDATE;
      END IF;
    END IF;

    IF v_day.id IS NULL THEN
      RAISE EXCEPTION USING
        ERRCODE = 'XX000',
        MESSAGE = 'VIP floor business day could not be resolved';
    END IF;

    v_slots_created := public.ensure_admin_booking_slots_v80(v_day.id);

    INSERT INTO public.audit_logs(
      actor_admin_id, actor_type, action, target_table, target_id,
      request_id, reason, event_day_id, entity_type, entity_id, operation,
      version_before, version_after, changed_fields,
      before_json, after_json, metadata_json, source_contract
    )
    VALUES (
      p_actor_admin_id, 'admin', v_action, 'event_days', v_day.id,
      p_request_id, p_reason, v_day.id, 'event_day', v_day.id, v_action,
      NULL, NULL,
      CASE
        WHEN v_created OR v_slots_created > 0
          THEN ARRAY['business_date', 'sales_window', 'booking_slots']
        ELSE '{}'::text[]
      END,
      CASE WHEN v_created THEN NULL ELSE jsonb_build_object(
        'operatingStatus', v_day.operating_status
      ) END,
      jsonb_build_object(
        'businessDate', v_day.business_date,
        'operatingStatus', v_day.operating_status,
        'created', v_created,
        'slotsCreated', v_slots_created
      ),
      '{}'::jsonb,
      'ghost.vip-manager.v2'
    )
    RETURNING id INTO v_audit_id;

    IF v_created OR v_slots_created > 0 THEN
      v_step := public.bump_vip_floor_day_revision_v8(v_day.id, v_audit_id);
      PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
      v_revision := (v_step ->> 'revision')::bigint;
    ELSE
      SELECT revision INTO v_revision
      FROM public.vip_floor_day_revisions
      WHERE event_day_id = v_day.id;
      v_revision := COALESCE(v_revision, 0);
    END IF;

    v_response := jsonb_build_object(
      'ok', true,
      'action', v_action,
      'reused', false,
      'eventDayId', v_day.id,
      'businessDate', v_day.business_date,
      'created', v_created,
      'slotsCreated', v_slots_created,
      'operatingStatus', v_day.operating_status,
      'entityVersion', 1,
      'boardRevision', v_revision,
      'auditLogId', v_audit_id
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: exchange_public_reservation_status_capability_v21(text, text, timestamp with time zone)
CREATE FUNCTION public.exchange_public_reservation_status_capability_v21(p_exchange_token text, p_status_token text, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_reservation_id uuid;
BEGIN
  IF p_exchange_token !~ '^[a-fA-F0-9]{48}$'
    OR p_status_token !~ '^[a-fA-F0-9]{48}$'
    OR p_exchange_token = p_status_token
    OR p_expires_at <= now()
    OR p_expires_at > now() + interval '2 hours 1 minute'
  THEN
    RETURN jsonb_build_object('exchanged', false);
  END IF;

  SELECT r.id
  INTO v_reservation_id
  FROM public.reservations AS r
  WHERE r.status_token_hash = encode(digest(p_exchange_token, 'sha256'), 'hex')
    AND (
      r.status_token_expires_at IS NULL
      OR r.status_token_expires_at > now()
    )
  FOR UPDATE;

  IF v_reservation_id IS NULL THEN
    RETURN jsonb_build_object('exchanged', false);
  END IF;

  UPDATE public.reservations
  SET status_token_hash = encode(digest(p_status_token, 'sha256'), 'hex'),
      status_token_expires_at = p_expires_at,
      updated_at = now()
  WHERE id = v_reservation_id;

  RETURN jsonb_build_object('exchanged', true);
END;
$_$;

-- FUNCTION: exchange_ticket_order_entry_v52(uuid, text, text, text, text, uuid, text, text)
CREATE FUNCTION public.exchange_ticket_order_entry_v52(p_link uuid, p_token text, p_environment text, p_origin text, p_account text, p_session uuid, p_session_token text, p_csrf text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE l public.ticket_order_entry_links%ROWTYPE; o public.ticket_orders%ROWTYPE; closing timestamptz;
BEGIN
 PERFORM public.ticket_wallet_gate_fence_v30();
 SELECT * INTO l FROM public.ticket_order_entry_links WHERE id=p_link;
 IF NOT FOUND OR NOT public.ticket_auth_digest_equal_v29(l.token_verifier,p_token) THEN RETURN jsonb_build_object('action','unauthenticated'); END IF;
 SELECT * INTO o FROM public.ticket_orders WHERE id=l.ticket_order_id FOR UPDATE;
 SELECT * INTO l FROM public.ticket_order_entry_links WHERE id=p_link FOR UPDATE;
 SELECT public.ticket_admission_execution_closes_v56(id) INTO closing FROM public.ticket_event_sessions WHERE id=o.event_session_id;
 IF l.revoked_at IS NOT NULL OR l.expires_at<=clock_timestamp() OR closing<=clock_timestamp()
  OR l.environment IS DISTINCT FROM p_environment OR l.public_origin IS DISTINCT FROM p_origin OR l.stripe_account_key IS DISTINCT FROM p_account
  OR o.environment<>l.environment OR o.event_session_id<>l.event_session_id OR o.stripe_account_key<>l.stripe_account_key
  OR o.admission_policy<>'order_together_v1' OR NOT public.ticket_order_has_settled_payment_v30(o.id)
 THEN RETURN jsonb_build_object('action','unauthenticated'); END IF;
 IF NOT public.consume_ticket_wallet_rate_limit_v29('order_link_exchange',l.id::text,60,60)
 THEN RETURN jsonb_build_object('action','rejected','reason','rate_limited'); END IF;
 INSERT INTO public.ticket_order_entry_sessions(id,link_id,ticket_order_id,token_verifier,csrf_verifier,expires_at)
  VALUES(p_session,l.id,o.id,p_session_token,p_csrf,least(l.expires_at,closing));
 RETURN jsonb_build_object('action','exchanged','orderId',o.id,'expiresAt',least(l.expires_at,closing));
END $$;

-- FUNCTION: expire_admin_holds_v7()
CREATE FUNCTION public.expire_admin_holds_v7() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count int;
BEGIN
  UPDATE reservations
  SET status = 'admin_hold_review',
      updated_at = now()
  WHERE status = 'admin_hold'
    AND admin_hold_expires_at <= now();

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

-- FUNCTION: expire_public_reservation_holds_v7()
CREATE FUNCTION public.expire_public_reservation_holds_v7() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count int;
BEGIN
  WITH expired AS (
    UPDATE reservations r
    SET status = 'hold_expired',
        updated_at = now()
    WHERE r.status IN ('pending','pending_card_setup','pending_deposit')
      AND r.hold_expires_at IS NOT NULL
      AND r.hold_expires_at <= now()
    RETURNING r.id
  )
  UPDATE reservation_resources rr
  SET lock_status = 'expired',
      released_at = now(),
      updated_at = now()
  FROM expired e
  WHERE rr.reservation_id = e.id
    AND rr.lock_status IN ('held','payment_grace_locked');

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

-- FUNCTION: expire_stale_ticket_orders_v23(integer)
CREATE FUNCTION public.expire_stale_ticket_orders_v23(p_older_than_minutes integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_expired integer;
BEGIN
  -- Action-backed orders require explicit provider terminal evidence through
  -- expire_ticket_checkout_action_v28. The legacy sweep never guesses.
  UPDATE public.ticket_orders AS ticket_order
  SET status = 'expired', cancelled_at = now()
  WHERE ticket_order.status = 'pending'
    AND ticket_order.created_at <
      now() - make_interval(mins => GREATEST(p_older_than_minutes, 30))
    AND NOT EXISTS (
      SELECT 1 FROM public.ticket_checkout_actions AS action
      WHERE action.ticket_order_id = ticket_order.id
    );
  GET DIAGNOSTICS v_expired = ROW_COUNT;
  RETURN jsonb_build_object('action', 'expired', 'count', v_expired);
END;
$$;

-- FUNCTION: expire_ticket_checkout_action_v28(uuid, text, text, timestamp with time zone)
CREATE FUNCTION public.expire_ticket_checkout_action_v28(p_checkout_action_id uuid, p_provider_terminal_status text, p_provider_terminal_evidence_hash text, p_provider_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'action', 'rejected',
    'reason', 'verified_provider_evidence_required'
  );
$$;

-- FUNCTION: expire_ticket_checkout_action_verified_v28(uuid, uuid, text, text, text, text, timestamp with time zone, text, uuid, uuid, text, boolean, text, timestamp with time zone)
CREATE FUNCTION public.expire_ticket_checkout_action_verified_v28(p_checkout_action_id uuid, p_recovery_claim_token uuid, p_provider_idempotency_key text, p_checkout_session_id text, p_provider_status text, p_provider_payment_status text, p_provider_expires_at timestamp with time zone, p_provider_client_reference_id text, p_provider_checkout_action_id uuid, p_provider_event_session_id uuid, p_provider_check_in_mode text, p_provider_livemode boolean, p_provider_terminal_evidence_hash text, p_provider_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_action public.ticket_checkout_actions%ROWTYPE;
  v_order public.ticket_orders%ROWTYPE;
BEGIN
  -- No negative lookup, cancellation guess, completed Session, or paid Session
  -- is expiry authority. Stripe's literal expired+unpaid state is mandatory.
  IF p_checkout_action_id IS NULL
    OR p_recovery_claim_token IS NULL
    OR NULLIF(btrim(COALESCE(p_provider_idempotency_key, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_checkout_session_id, '')), '') IS NULL
    OR p_provider_status <> 'expired'
    OR p_provider_payment_status <> 'unpaid'
    OR p_provider_expires_at IS NULL
    OR NULLIF(btrim(COALESCE(p_provider_client_reference_id, '')), '') IS NULL
    OR p_provider_checkout_action_id IS NULL
    OR p_provider_event_session_id IS NULL
    OR COALESCE(p_provider_check_in_mode, '') NOT IN ('legacy_qr', 'wallet_swipe')
    OR p_provider_livemode IS NULL
    OR COALESCE(p_provider_terminal_evidence_hash, '') !~ '^[0-9a-f]{64}$'
    OR p_provider_observed_at IS NULL
    OR p_provider_observed_at > clock_timestamp() + interval '5 minutes'
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reason', 'verified_provider_expiry_evidence_invalid');
  END IF;

  SELECT * INTO v_action
  FROM public.ticket_checkout_actions
  WHERE id = p_checkout_action_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('action', 'not_found'); END IF;
  IF v_action.recovery_claim_token IS DISTINCT FROM p_recovery_claim_token
    OR v_action.recovery_claim_expires_at <= clock_timestamp()
  THEN
    RETURN jsonb_build_object('action', 'fence_lost', 'reason', 'recovery_claim_lost');
  END IF;
  SELECT * INTO v_order
  FROM public.ticket_orders
  WHERE id = v_action.ticket_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'checkout_order_missing');
  END IF;

  IF v_action.provider_idempotency_key <> btrim(p_provider_idempotency_key)
    OR v_action.checkout_session_id <> btrim(p_checkout_session_id)
    OR v_order.checkout_session_id <> btrim(p_checkout_session_id)
    OR v_action.provider_expires_at <> p_provider_expires_at
    OR v_order.id::text <> btrim(p_provider_client_reference_id)
    OR v_action.id <> p_provider_checkout_action_id
    OR v_action.event_session_id <> p_provider_event_session_id
    OR v_action.check_in_mode <> p_provider_check_in_mode
    OR (v_action.environment = 'live') IS DISTINCT FROM p_provider_livemode
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reason', 'provider_session_expiry_authority_mismatch');
  END IF;
  -- W09 G-19: accept terminal evidence for 'cancelled'/'expired' orders too.
  -- Their status is left untouched (the order UPDATE below stays
  -- pending-only); recording provider_terminal_status='expired' on the action
  -- is what releases the reserved slot and the purchase-mail reservation.
  -- Literal expired+unpaid authority above is unchanged, and paid/fulfilled/
  -- refunded orders still cannot gain expiry evidence here.
  IF v_action.state <> 'provider_created'
    OR v_order.status NOT IN ('pending', 'cancelled', 'expired') THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'order_not_expirable');
  END IF;
  -- Manual provider expiry can precede the original expires_at timestamp.
  -- Bound literal expired+unpaid evidence, not elapsed time, is authority.
  IF p_provider_observed_at < v_action.created_at
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'provider_session_not_expired');
  END IF;

  UPDATE public.ticket_checkout_actions
  SET state = 'expired',
      provider_terminal_status = 'expired',
      provider_terminal_evidence_hash = p_provider_terminal_evidence_hash,
      provider_terminal_observed_at = p_provider_observed_at,
      expired_at = now(),
      recovery_claim_token = NULL,
      recovery_claimed_by = NULL,
      recovery_claimed_at = NULL,
      recovery_claim_expires_at = NULL,
      recovery_last_outcome = 'provider_expired',
      reconciliation_count = reconciliation_count + 1,
      updated_at = now()
  WHERE id = v_action.id;
  UPDATE public.ticket_orders
  SET status = 'expired', cancelled_at = COALESCE(cancelled_at, now())
  WHERE id = v_order.id AND status = 'pending';

  INSERT INTO public.audit_logs(
    action, actor_type, target_table, target_id,
    entity_type, entity_id, operation, reason, metadata_json
  ) VALUES (
    'ticket_checkout.expire', 'system', 'ticket_checkout_actions', v_action.id,
    'ticket_checkout_action', v_action.id, 'update', 'expired',
    jsonb_build_object(
      'orderId', v_order.id,
      'checkoutSessionId', v_action.checkout_session_id,
      'stripeAccountKey', v_action.stripe_account_key,
      'providerExpiresAt', p_provider_expires_at,
      'providerStatus', p_provider_status,
      'providerPaymentStatus', p_provider_payment_status,
      'providerObservedAt', p_provider_observed_at,
      'providerEvidenceHash', p_provider_terminal_evidence_hash));

  RETURN jsonb_build_object(
    'action', 'expired', 'checkoutActionId', v_action.id,
    'orderId', v_order.id, 'providerTerminalStatus', 'expired');
END;
$_$;

-- FUNCTION: extend_admin_reservation_hold_v7(uuid, text, text, text, text, uuid, integer, text)
CREATE FUNCTION public.extend_admin_reservation_hold_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_extend_minutes integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_reservation reservations%ROWTYPE;
  v_expires_at timestamptz;
  v_response jsonb;
BEGIN
  SELECT * INTO v_admin
  FROM admin_users
  WHERE id = p_actor_admin_id
  FOR UPDATE;

  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;

  IF v_admin.role NOT IN ('manager','owner','engineer') THEN
    RAISE EXCEPTION 'admin role cannot extend holds';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;

    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  IF p_extend_minutes <= 0 OR p_extend_minutes > 10080 THEN
    RAISE EXCEPTION 'invalid hold extension minutes';
  END IF;

  SELECT * INTO v_reservation
  FROM reservations
  WHERE id = p_reservation_id
  FOR UPDATE;

  IF NOT FOUND OR v_reservation.status <> 'admin_hold' THEN
    RAISE EXCEPTION 'reservation is not an active admin hold';
  END IF;

  v_expires_at := GREATEST(v_reservation.admin_hold_expires_at, now()) + make_interval(mins => p_extend_minutes);

  UPDATE reservations
  SET admin_hold_expires_at = v_expires_at,
      admin_hold_reason = COALESCE(p_reason, admin_hold_reason),
      updated_at = now()
  WHERE id = p_reservation_id;

  UPDATE reservation_resources
  SET admin_hold_expires_at = v_expires_at,
      updated_at = now()
  WHERE reservation_id = p_reservation_id
    AND lock_status = 'held';

  v_response := jsonb_build_object('reservationId', p_reservation_id, 'adminHoldExpiresAt', v_expires_at);

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'reservations', p_reservation_id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'extended', 'response', v_response);
END;
$$;

-- FUNCTION: extend_checked_in_reservation_seat_legacy_v8(uuid, text, text, text, uuid, bigint, integer, text)
CREATE FUNCTION public.extend_checked_in_reservation_seat_legacy_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_version bigint, p_extend_minutes integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation.seat_extended';
  v_step jsonb;
  v_reservation public.reservations%ROWTYPE;
  v_assignment record;
  v_previous_due_at timestamptz;
  v_new_due_at timestamptz;
  v_new_version bigint;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_warnings jsonb := '[]'::jsonb;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;
    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(
        p_actor_admin_id,
        CASE WHEN COALESCE(p_extend_minutes, 0) <= 120
          THEN 'seat_extension.standard' ELSE 'seat_extension.extended' END
      ), ARRAY['allowed']
    );
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_extend_minutes IS NULL
      OR p_extend_minutes < 15 OR p_extend_minutes > 240
      OR p_extend_minutes % 15 <> 0
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'extendMinutes')
        )), ARRAY['allowed']
      );
    END IF;
    v_step := public.assert_reservation_version_v8(p_reservation_id, p_expected_version);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
    SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id;
    IF v_reservation.status <> 'checked_in'
      OR v_reservation.service_status IN ('completed', 'no_show')
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION', 'details', jsonb_build_object('reason', 'reservation_not_extendable')
        )), ARRAY['allowed']
      );
    END IF;
    v_previous_due_at := COALESCE(
      v_reservation.expected_release_at,
      v_reservation.seat_extended_until_at,
      v_reservation.seat_due_at,
      v_reservation.checked_in_at + interval '120 minutes'
    );
    v_new_due_at := GREATEST(v_previous_due_at, now()) + make_interval(mins => p_extend_minutes);

    PERFORM sr.id FROM public.seat_resources AS sr
    WHERE EXISTS (
      SELECT 1 FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id
        AND rr.seat_resource_id = sr.id
        AND public.active_reservation_assignment_v8(rr.id, now())
    )
    ORDER BY sr.id FOR UPDATE OF sr;
    PERFORM rr.id FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
       OR (
         rr.seat_resource_id IN (
           SELECT current_rr.seat_resource_id
           FROM public.reservation_resources AS current_rr
           WHERE current_rr.reservation_id = v_reservation.id
             AND public.active_reservation_assignment_v8(current_rr.id, now())
         )
         AND rr.assigned_start_at < v_new_due_at
         AND rr.assigned_end_at > v_reservation.scheduled_start_at
       )
    ORDER BY rr.id FOR UPDATE OF rr;
    IF NOT EXISTS (
      SELECT 1 FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id
        AND public.active_reservation_assignment_v8(rr.id, now())
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION',
          'details', jsonb_build_object('reason', 'active_assignment_required')
        )), ARRAY['allowed']
      );
    END IF;
    PERFORM rb.id
    FROM public.reservation_blocks AS rb
    WHERE rb.event_day_id = v_reservation.event_day_id
      AND rb.status = 'active'
      AND rb.start_at < v_new_due_at
      AND rb.end_at > v_reservation.scheduled_start_at
      AND EXISTS (
        SELECT 1
        FROM public.reservation_block_targets AS rbt
        JOIN public.reservation_resources AS rr ON rr.reservation_id = v_reservation.id
        JOIN public.seat_resources AS sr ON sr.id = rr.seat_resource_id
        WHERE rbt.block_id = rb.id
          AND (rbt.seat_resource_id = sr.id OR rbt.floor_section_id = sr.floor_section_id OR rbt.venue_wide)
      )
    ORDER BY rb.id FOR UPDATE OF rb;
    FOR v_assignment IN
      SELECT rr.* FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id
        AND public.active_reservation_assignment_v8(rr.id, now())
      ORDER BY rr.id
    LOOP
      v_step := public.assert_assignment_conflict_free_v8(
        v_reservation.event_day_id, v_reservation.id,
        v_assignment.seat_resource_id,
        v_assignment.assigned_start_at, v_new_due_at, now()
      );
      PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
      SELECT COALESCE(jsonb_agg(warning ORDER BY warning::text), '[]'::jsonb)
      INTO v_warnings
      FROM (
        SELECT DISTINCT warning
        FROM jsonb_array_elements(v_warnings || COALESCE(v_step -> 'warnings', '[]'::jsonb)) AS all_warnings(warning)
      ) AS deduplicated;
    END LOOP;

    INSERT INTO public.reservation_assignment_events(
      reservation_id, reservation_resource_id, seat_resource_id, event_type,
      interval_before, interval_after, actor_admin_id, reason, request_id
    )
    SELECT rr.reservation_id, rr.id, rr.seat_resource_id, 'interval_changed',
      jsonb_build_object('startAt', rr.assigned_start_at, 'endAt', rr.assigned_end_at),
      jsonb_build_object('startAt', rr.assigned_start_at, 'endAt', v_new_due_at),
      p_actor_admin_id, p_reason, p_request_id
    FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now())
      AND rr.assigned_end_at IS DISTINCT FROM v_new_due_at;
    UPDATE public.reservation_resources AS rr
    SET assigned_end_at = v_new_due_at,
        version = rr.version + 1,
        updated_at = now()
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now())
      AND rr.assigned_end_at IS DISTINCT FROM v_new_due_at;
    INSERT INTO public.reservation_seat_extensions(
      reservation_id, actor_admin_id, extend_minutes,
      previous_due_at, new_due_at, reason
    ) VALUES (
      v_reservation.id, p_actor_admin_id, p_extend_minutes,
      v_previous_due_at, v_new_due_at, p_reason
    );
    UPDATE public.reservations
    SET expected_release_at = v_new_due_at,
        seat_due_at = v_new_due_at,
        seat_extended_until_at = v_new_due_at,
        seat_extension_minutes = COALESCE(seat_extension_minutes, 0) + p_extend_minutes,
        version = version + 1,
        updated_at = now()
    WHERE id = v_reservation.id
    RETURNING version INTO v_new_version;

    PERFORM ed.id FROM public.event_days AS ed
    WHERE ed.id = v_reservation.event_day_id FOR KEY SHARE OF ed;
    PERFORM public.lock_vip_floor_day_revision_v32(v_reservation.event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1 INTO v_predicted_revision
    FROM (SELECT 1) AS seed LEFT JOIN public.vip_floor_day_revisions AS vfr
      ON vfr.event_day_id = v_reservation.event_day_id;
    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, v_reservation.event_day_id, v_reservation.id,
      'reservation', v_reservation.id, v_action, p_request_id, p_reason,
      p_expected_version, v_reservation.version, v_new_version,
      ARRAY['expected_release_at', 'seat_due_at', 'seat_extended_until_at', 'seat_extension_minutes', 'version'],
      jsonb_build_object('expectedReleaseAt', v_previous_due_at, 'version', v_reservation.version),
      jsonb_build_object('expectedReleaseAt', v_new_due_at, 'version', v_new_version),
      jsonb_build_object('extendMinutes', p_extend_minutes, 'warnings', v_warnings)
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_response := jsonb_build_object(
      'ok', true, 'action', v_action, 'reused', false,
      'reservationId', v_reservation.id, 'entityVersion', v_new_version,
      'boardRevision', v_predicted_revision, 'auditLogId', v_audit_id,
      'extendMinutes', p_extend_minutes,
      'previousDueAt', v_previous_due_at, 'newDueAt', v_new_due_at,
      'warnings', v_warnings
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(v_reservation.event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'XX000', MESSAGE = 'VIP floor revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS v_error_detail = PG_EXCEPTION_DETAIL, v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN RETURN v_error_detail::jsonb; END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: extend_checked_in_reservation_seat_v7(uuid, text, text, text, text, uuid, integer, text)
CREATE FUNCTION public.extend_checked_in_reservation_seat_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_extend_minutes integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_reservation reservations%ROWTYPE;
  v_checked_in_at timestamptz;
  v_previous_due_at timestamptz;
  v_new_due_at timestamptz;
  v_total_extension_minutes int;
  v_response jsonb;
BEGIN
  SELECT * INTO v_admin FROM admin_users WHERE id = p_actor_admin_id FOR UPDATE;
  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;
  IF v_admin.role NOT IN ('staff','manager','owner','engineer') THEN
    RAISE EXCEPTION 'admin role cannot extend seated reservations';
  END IF;

  IF p_extend_minutes NOT IN (15, 30, 60, 120) THEN
    RAISE EXCEPTION 'invalid seated extension minutes';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;
    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  SELECT * INTO v_reservation
  FROM reservations
  WHERE id = p_reservation_id
  FOR UPDATE;

  IF NOT FOUND OR v_reservation.status <> 'checked_in' THEN
    RAISE EXCEPTION 'reservation is not checked in';
  END IF;

  v_checked_in_at := COALESCE(v_reservation.checked_in_at, v_reservation.confirmed_at, v_reservation.updated_at, v_reservation.created_at);
  v_previous_due_at := COALESCE(
    v_reservation.seat_extended_until_at,
    v_reservation.seat_due_at,
    v_checked_in_at + interval '120 minutes'
  );
  v_new_due_at := GREATEST(v_previous_due_at, now()) + make_interval(mins => p_extend_minutes);
  v_total_extension_minutes := COALESCE(v_reservation.seat_extension_minutes, 0) + p_extend_minutes;

  UPDATE reservations
  SET checked_in_at = v_checked_in_at,
      seat_due_at = v_new_due_at,
      seat_extended_until_at = v_new_due_at,
      seat_extension_minutes = v_total_extension_minutes,
      updated_at = now()
  WHERE id = v_reservation.id;

  INSERT INTO reservation_seat_extensions(
    reservation_id,
    actor_admin_id,
    extend_minutes,
    previous_due_at,
    new_due_at,
    reason
  )
  VALUES (
    v_reservation.id,
    p_actor_admin_id,
    p_extend_minutes,
    v_previous_due_at,
    v_new_due_at,
    p_reason
  );

  v_response := jsonb_build_object(
    'reservationId', v_reservation.id,
    'extendMinutes', p_extend_minutes,
    'previousDueAt', v_previous_due_at,
    'newDueAt', v_new_due_at,
    'checkedInAt', v_checked_in_at,
    'seatDueAt', v_new_due_at,
    'seatExtendedUntilAt', v_new_due_at,
    'seatExtensionMinutes', v_total_extension_minutes
  );

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'reservations', v_reservation.id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'extended', 'response', v_response);
END;
$$;

-- FUNCTION: extend_checked_in_reservation_seat_v8(uuid, text, text, text, uuid, bigint, integer, text)
CREATE FUNCTION public.extend_checked_in_reservation_seat_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_version bigint, p_extend_minutes integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_extend_minutes IS NULL
    OR p_extend_minutes < 15
    OR p_extend_minutes > 120
    OR p_extend_minutes % 15 <> 0
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object('field', 'extendMinutes')
      )
    );
  END IF;

  RETURN public.extend_checked_in_reservation_seat_legacy_v8(
    p_actor_admin_id,
    p_request_id,
    p_idempotency_key,
    p_request_hash,
    p_reservation_id,
    p_expected_version,
    p_extend_minutes,
    p_reason
  );
END;
$$;

-- FUNCTION: finalize_public_reservation_hold_stripe_v7(text, text, text, text, text, text, text, text, text, text, jsonb)
CREATE FUNCTION public.finalize_public_reservation_hold_stripe_v7(p_source_system text, p_idempotency_key text, p_request_hash text, p_stripe_customer_id text, p_environment text, p_stripe_account_id text, p_provider_object_type text, p_provider_object_id text, p_provider_status text, p_client_secret_ciphertext text, p_response_snapshot_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_hold reservation_hold_requests%ROWTYPE;
  v_reservation reservations%ROWTYPE;
  v_payment payments%ROWTYPE;
  v_payment_status payment_status;
  v_response jsonb;
  v_status_token text;
  v_checkout_session_id text;
BEGIN
  SELECT * INTO v_hold
  FROM reservation_hold_requests
  WHERE source_system = p_source_system
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'reservation hold request not found';
  END IF;

  IF v_hold.request_hash <> p_request_hash THEN
    RETURN jsonb_build_object(
      'action', 'mismatch',
      'error', 'idempotency_key_reused_with_different_request'
    );
  END IF;

  SELECT * INTO v_reservation
  FROM reservations
  WHERE id = v_hold.reservation_id
  FOR UPDATE;

  SELECT * INTO v_payment
  FROM payments
  WHERE reservation_id = v_hold.reservation_id
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment row not found for reservation hold';
  END IF;

  v_payment_status := CASE
    WHEN p_provider_status = 'succeeded' THEN 'succeeded'::payment_status
    WHEN p_provider_status = 'processing' THEN 'processing'::payment_status
    WHEN p_provider_status = 'requires_action' THEN 'requires_action'::payment_status
    WHEN p_provider_status = 'canceled' THEN 'cancelled'::payment_status
    ELSE v_payment.status
  END;

  UPDATE customers
  SET stripe_customer_id = p_stripe_customer_id,
      environment = p_environment,
      stripe_account_id = p_stripe_account_id,
      updated_at = now()
  WHERE id = v_reservation.customer_id;

  UPDATE payments
  SET status = v_payment_status,
      environment = p_environment,
      stripe_account_id = p_stripe_account_id,
      stripe_customer_id = p_stripe_customer_id,
      provider_object_type = p_provider_object_type,
      provider_object_id = p_provider_object_id,
      updated_at = now()
  WHERE id = v_payment.id;

  INSERT INTO stripe_intent_bindings(
    reservation_id,
    payment_id,
    expected_payment_type,
    environment,
    stripe_account_id,
    provider_object_type,
    provider_object_id,
    idempotency_key,
    request_snapshot_json
  )
  VALUES (
    v_hold.reservation_id,
    v_payment.id,
    v_payment.type,
    p_environment,
    p_stripe_account_id,
    p_provider_object_type,
    p_provider_object_id,
    v_hold.stripe_idempotency_key,
    jsonb_build_object(
      'sourceSystem', p_source_system,
      'reservationId', v_hold.reservation_id,
      'paymentId', v_payment.id
    )
  )
  ON CONFLICT (environment, stripe_account_key, idempotency_key)
  DO UPDATE
  SET provider_object_type = EXCLUDED.provider_object_type,
      provider_object_id = EXCLUDED.provider_object_id,
      payment_id = EXCLUDED.payment_id,
      updated_at = now();

  v_status_token := COALESCE(
    p_response_snapshot_json->>'statusToken',
    v_hold.response_snapshot_json->>'statusToken'
  );
  v_checkout_session_id := COALESCE(
    p_response_snapshot_json #>> '{checkoutSession,id}',
    p_response_snapshot_json->>'checkoutSessionId',
    v_hold.response_snapshot_json->>'checkoutSessionId'
  );

  v_response := jsonb_build_object(
    'reservationId', v_hold.reservation_id,
    'paymentId', v_payment.id,
    'publicCode', v_reservation.public_code,
    'statusToken', v_status_token,
    'providerObjectType', p_provider_object_type,
    'providerObjectId', p_provider_object_id,
    'providerStatus', p_provider_status,
    'checkoutSessionId', v_checkout_session_id,
    'holdExpiresAt', v_reservation.hold_expires_at
  );

  UPDATE reservation_hold_requests
  SET status = 'finalized',
      provider_object_type = p_provider_object_type,
      provider_object_id = p_provider_object_id,
      client_secret_ciphertext = NULL,
      response_snapshot_json = v_response,
      last_error_code = NULL,
      last_error_message = NULL,
      updated_at = now()
  WHERE id = v_hold.id;

  RETURN jsonb_build_object(
    'action', 'finalized',
    'response', v_response
  );
END;
$$;

-- FUNCTION: freeze_ticket_entry_records_v53()
CREATE FUNCTION public.freeze_ticket_entry_records_v53() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
 IF TG_TABLE_NAME='ticket_order_entry_operations' AND TG_OP='UPDATE' THEN
  IF OLD.state='prepared' AND NEW.state IN ('committed','rejected') AND (to_jsonb(NEW)-ARRAY['state','commit_key','commit_request_hash','result_json'])=(to_jsonb(OLD)-ARRAY['state','commit_key','commit_request_hash','result_json'])
   THEN RETURN NEW; END IF;
 ELSIF TG_TABLE_NAME='ticket_order_entry_links' AND TG_OP='UPDATE' THEN
  IF OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL AND (to_jsonb(NEW)-'revoked_at')=(to_jsonb(OLD)-'revoked_at') THEN RETURN NEW; END IF;
 END IF;
 RAISE EXCEPTION 'ticket_entry_record_immutable';
END $$;

-- FUNCTION: fulfill_ticket_order_v23(uuid, text, text, text, text, integer, text, bytea, text[])
CREATE FUNCTION public.fulfill_ticket_order_v23(p_order_id uuid, p_environment text, p_stripe_account_id text, p_payment_intent_id text, p_checkout_session_id text, p_amount_yen integer, p_purchaser_email_hash text, p_purchaser_email_ciphertext bytea, p_admission_codes text[]) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT public.fulfill_ticket_order_v35(p_order_id,p_environment,p_stripe_account_id,p_payment_intent_id,p_checkout_session_id,p_amount_yen,p_purchaser_email_hash,p_purchaser_email_ciphertext,p_admission_codes,NULL);
$$;

-- FUNCTION: fulfill_ticket_order_v35(uuid, text, text, text, text, integer, text, bytea, text[], timestamp with time zone)
CREATE FUNCTION public.fulfill_ticket_order_v35(p_order_id uuid, p_environment text, p_stripe_account_id text, p_payment_intent_id text, p_checkout_session_id text, p_amount_yen integer, p_purchaser_email_hash text, p_purchaser_email_ciphertext bytea, p_admission_codes text[], p_provider_paid_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order public.ticket_orders%ROWTYPE;
  v_mode text;
  v_action public.ticket_checkout_actions%ROWTYPE;
  v_has_action boolean := false;
  v_replay boolean := false;
  v_admissions jsonb;
  v_issued integer;
  v_day uuid; v_session uuid; v_reason text;
BEGIN
  SELECT event_session_id INTO v_session FROM public.ticket_orders WHERE id=p_order_id;
  SELECT event_day_id INTO v_day FROM public.ticket_event_sessions WHERE id=v_session;
  PERFORM 1 FROM public.event_days WHERE id=v_day FOR UPDATE;
  PERFORM 1 FROM public.ticket_event_sessions WHERE id=v_session FOR UPDATE;
  SELECT check_in_mode INTO v_mode
  FROM public.ticket_orders
  WHERE id = p_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('action', 'not_found'); END IF;

  -- Every v28 action-backed path shares Action -> Order lock order with
  -- provider-result, verified refund, and verified revocation RPCs.
  SELECT * INTO v_action
  FROM public.ticket_checkout_actions
  WHERE ticket_order_id = p_order_id
  FOR UPDATE;
  v_has_action := FOUND;
  IF v_mode = 'wallet_swipe' AND NOT v_has_action THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'wallet_checkout_action_required');
  END IF;

  SELECT * INTO v_order
  FROM public.ticket_orders
  WHERE id = p_order_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('action', 'not_found'); END IF;

  IF v_order.environment <> p_environment THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'environment_mismatch');
  END IF;
  IF COALESCE(v_order.stripe_account_id, 'platform')
     <> COALESCE(p_stripe_account_id, 'platform') THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'stripe_account_mismatch');
  END IF;
  IF v_order.payment_hold_reason IS NOT NULL THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reason', 'payment_hold_required',
      'paymentHoldReason', v_order.payment_hold_reason,
      'orderId', v_order.id, 'publicCode', v_order.public_code);
  END IF;
  IF v_order.status='refunded' OR (v_order.status IN ('cancelled','expired') AND v_order.sales_close_at_snapshot IS NULL) THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'order_not_payable',
                              'status', v_order.status);
  END IF;

  IF v_order.check_in_mode = 'wallet_swipe' THEN
    IF v_action.environment <> v_order.environment
      OR v_action.stripe_account_key <> v_order.stripe_account_key
      OR v_action.event_session_id <> v_order.event_session_id
      OR v_action.check_in_mode <> v_order.check_in_mode
    THEN
      RETURN jsonb_build_object('action', 'rejected', 'reason', 'wallet_checkout_binding_mismatch');
    END IF;
    IF v_action.state = 'review_required'
      AND v_action.review_reason NOT IN ('wallet_purchaser_email_required','payment_time_unverified')
    THEN
      RETURN jsonb_build_object('action', 'rejected', 'reason', 'wallet_checkout_review_required');
    END IF;
    IF v_action.state NOT IN ('provider_created', 'completed', 'review_required','expired') THEN
      RETURN jsonb_build_object('action', 'rejected', 'reason', 'wallet_provider_session_required');
    END IF;
    IF NULLIF(btrim(COALESCE(p_checkout_session_id, '')), '') IS NULL
      OR v_action.checkout_session_id <> p_checkout_session_id
    THEN
      RETURN jsonb_build_object('action', 'rejected', 'reason', 'checkout_session_mismatch');
    END IF;
    IF NULLIF(btrim(COALESCE(p_payment_intent_id, '')), '') IS NULL THEN
      RETURN jsonb_build_object('action', 'rejected', 'reason', 'payment_object_missing');
    END IF;
    IF NULLIF(btrim(COALESCE(p_purchaser_email_hash, '')), '') IS NULL
      OR p_purchaser_email_ciphertext IS NULL
    THEN
      UPDATE public.ticket_checkout_actions
      SET state = 'review_required',
          review_reason = 'wallet_purchaser_email_required',
          updated_at = now()
      WHERE id = v_action.id;
      RETURN jsonb_build_object(
        'action', 'rejected', 'reason', 'wallet_purchaser_email_required',
        'checkoutActionId', v_action.id, 'orderId', v_order.id);
    END IF;
  ELSIF v_has_action THEN
    -- G-63: legacy_qr orders created through the v28 action lane satisfy the
    -- same SQL-side binding the wallet branch enforces. Pre-v28 orders carry
    -- no action row and keep the compatibility path below unchanged.
    IF v_action.environment <> v_order.environment
      OR v_action.stripe_account_key <> v_order.stripe_account_key
      OR v_action.event_session_id <> v_order.event_session_id
      OR v_action.check_in_mode <> v_order.check_in_mode
    THEN
      RETURN jsonb_build_object('action', 'rejected', 'reason', 'checkout_binding_mismatch');
    END IF;
    IF v_action.checkout_session_id IS NOT NULL
      AND v_action.checkout_session_id IS DISTINCT FROM btrim(COALESCE(p_checkout_session_id, ''))
    THEN
      RETURN jsonb_build_object('action', 'rejected', 'reason', 'checkout_session_mismatch');
    END IF;
    IF v_action.state = 'review_required'
      AND v_action.review_reason = 'payment_dispute_open'
    THEN
      RETURN jsonb_build_object(
        'action', 'rejected', 'reason', 'checkout_payment_dispute_open',
        'checkoutActionId', v_action.id, 'orderId', v_order.id);
    END IF;
  END IF;

  -- A verified refund bridge may record money movement before admissions
  -- exist. Holding Action -> Order, lock unresolved refund facts next so
  -- fulfillment can never issue between provider binding and review.
  PERFORM 1
  FROM public.ticket_refund_events AS refund
  WHERE refund.ticket_order_id = v_order.id
    AND refund.money_may_have_moved
    AND refund.resolution_status IN ('review_required', 'conflict_review')
    AND refund.resolved_at IS NULL
  ORDER BY refund.created_at, refund.id
  FOR UPDATE;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reason', 'refund_review_required',
      'orderId', v_order.id, 'publicCode', v_order.public_code);
  END IF;

  IF v_order.payment_intent_id IS NOT NULL
    AND p_payment_intent_id IS NOT NULL
    AND v_order.payment_intent_id <> p_payment_intent_id
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'payment_object_mismatch');
  END IF;

  -- W09 G-37 price floor (fulfil path): a zero or negative order amount can
  -- never correspond to legitimate payment evidence. Reject before any paid
  -- or admission state change; this also closes the NULL-amount bypass of the
  -- amount_mismatch comparison below. Companion to the
  -- ticket_sale_products.price_yen > 0 check in v70.
  IF v_order.amount_yen IS NULL OR v_order.amount_yen <= 0 THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'amount_floor_violation');
  END IF;
  IF p_amount_yen IS NULL OR p_amount_yen <> v_order.amount_yen THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'reason', CASE WHEN p_amount_yen IS NULL THEN 'amount_unknown' ELSE 'amount_mismatch' END);
  END IF;
  IF array_length(p_admission_codes, 1) IS DISTINCT FROM v_order.total_quantity THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'admission_code_count_mismatch');
  END IF;

  -- Do not infer payment time from receipt time. Existing pre-deadline orders
  -- retain their compatibility path, while new sales require signed evidence.
  IF v_order.sales_close_at_snapshot IS NOT NULL AND v_order.status NOT IN ('paid','fulfilled') THEN
    v_reason := CASE
      WHEN v_order.status IN ('cancelled','expired') THEN 'payment_after_order_closed'
      WHEN p_provider_paid_at IS NULL OR p_provider_paid_at>clock_timestamp()+interval '1 minute' OR p_provider_paid_at<v_order.created_at-interval '1 minute' THEN 'payment_time_unverified'
      WHEN p_provider_paid_at>=v_order.sales_close_at_snapshot THEN 'payment_after_sales_close'
      WHEN EXISTS(SELECT 1 FROM public.ticket_event_sessions WHERE id=v_session AND admission_state='cancelled') THEN 'payment_event_cancelled'
      WHEN EXISTS(SELECT 1 FROM public.ticket_sale_interruptions WHERE (event_day_id=v_day OR event_session_id=v_session) AND p_provider_paid_at>=stopped_at AND (resumed_at IS NULL OR p_provider_paid_at<resumed_at)) THEN 'payment_during_sales_stop'
      ELSE NULL END;
    IF v_reason IS NOT NULL THEN
      UPDATE public.ticket_orders SET payment_intent_id=COALESCE(payment_intent_id,p_payment_intent_id),checkout_session_id=COALESCE(checkout_session_id,p_checkout_session_id),purchaser_email_hash=COALESCE(purchaser_email_hash,p_purchaser_email_hash),purchaser_email_ciphertext=COALESCE(purchaser_email_ciphertext,p_purchaser_email_ciphertext),provider_paid_at=p_provider_paid_at,payment_observed_at=clock_timestamp() WHERE id=v_order.id;
      UPDATE public.ticket_checkout_actions SET state='review_required',review_reason=v_reason,updated_at=clock_timestamp() WHERE id=v_action.id;
      RETURN jsonb_build_object('action','rejected','reason',v_reason,'orderId',v_order.id);
    END IF;
  END IF;
  -- A verified replay may repair a missing encrypted delivery address, but can
  -- never transfer ownership to a different email identity.
  IF v_order.status='fulfilled' AND p_purchaser_email_ciphertext IS NOT NULL
    AND (v_order.purchaser_email_hash IS NULL OR v_order.purchaser_email_hash=p_purchaser_email_hash) THEN
    UPDATE public.ticket_orders SET purchaser_email_ciphertext=COALESCE(purchaser_email_ciphertext,p_purchaser_email_ciphertext),purchaser_email_hash=COALESCE(purchaser_email_hash,p_purchaser_email_hash) WHERE id=v_order.id;
    INSERT INTO public.ticket_purchase_notices(ticket_order_id) VALUES(v_order.id) ON CONFLICT DO NOTHING;
  END IF;
  v_replay := v_order.status IN ('paid', 'fulfilled');
  IF NOT v_replay THEN
    UPDATE public.ticket_orders
    SET status = 'paid',
        payment_intent_id = COALESCE(p_payment_intent_id, payment_intent_id),
        checkout_session_id = COALESCE(p_checkout_session_id, checkout_session_id),
        purchaser_email_hash = COALESCE(p_purchaser_email_hash, purchaser_email_hash),
        purchaser_email_ciphertext = COALESCE(p_purchaser_email_ciphertext, purchaser_email_ciphertext),
        paid_at = COALESCE(paid_at, p_provider_paid_at, now()),
        provider_paid_at = COALESCE(provider_paid_at,p_provider_paid_at),
        payment_observed_at = COALESCE(payment_observed_at,clock_timestamp())
    WHERE id = v_order.id
    RETURNING * INTO v_order;
  END IF;

  INSERT INTO public.ticket_admissions(
    ticket_order_id, serial, ticket_type_id, ticket_type_label, admission_code
  )
  SELECT v_order.id, expanded.serial, expanded.ticket_type_id,
         expanded.ticket_type_label, p_admission_codes[expanded.serial]
  FROM (
    SELECT row_number() OVER (ORDER BY item.ordinality, unit.n) AS serial,
           item.value ->> 'ticketTypeId' AS ticket_type_id,
           COALESCE(item.value ->> 'label', item.value ->> 'ticketTypeId') AS ticket_type_label
    FROM jsonb_array_elements(v_order.items_json) WITH ORDINALITY AS item(value, ordinality)
    CROSS JOIN LATERAL generate_series(1, (item.value ->> 'quantity')::integer) AS unit(n)
  ) AS expanded
  ON CONFLICT ON CONSTRAINT uq_ticket_admissions_order_serial DO NOTHING;

  SELECT count(*) INTO v_issued
  FROM public.ticket_admissions
  WHERE ticket_order_id = v_order.id;
  IF v_issued <> v_order.total_quantity THEN
    RAISE EXCEPTION 'ticket_admission_issue_incomplete: expected %, issued %',
      v_order.total_quantity, v_issued;
  END IF;

  IF v_order.status <> 'fulfilled' THEN
    UPDATE public.ticket_orders
    SET status = 'fulfilled', fulfilled_at = COALESCE(fulfilled_at, now())
    WHERE id = v_order.id RETURNING * INTO v_order;
  END IF;

  IF v_order.check_in_mode = 'wallet_swipe' THEN
    UPDATE public.ticket_checkout_actions
    SET state = 'completed',
        completed_at = COALESCE(completed_at, now()),
        review_reason = NULL,
        updated_at = now()
    WHERE id = v_action.id
      AND state IN ('provider_created', 'completed', 'review_required');
    IF NOT FOUND THEN
      RAISE EXCEPTION 'wallet checkout action completion failed';
    END IF;
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'serial', admission.serial,
      'ticketTypeId', admission.ticket_type_id,
      'ticketTypeLabel', admission.ticket_type_label,
      'status', admission.status,
      'admittedAt', admission.admitted_at
    ) || CASE WHEN v_order.check_in_mode = 'legacy_qr'
      THEN jsonb_build_object('admissionCode', admission.admission_code)
      ELSE '{}'::jsonb
    END ORDER BY admission.serial
  ) INTO v_admissions
  FROM public.ticket_admissions AS admission
  WHERE ticket_order_id = v_order.id;

  RETURN jsonb_build_object(
    'action', CASE WHEN v_replay THEN 'reused' ELSE 'fulfilled' END,
    'orderId', v_order.id, 'publicCode', v_order.public_code,
    'checkInMode', v_order.check_in_mode,
    'status', v_order.status, 'totalQuantity', v_order.total_quantity,
    'admissions', COALESCE(v_admissions, '[]'::jsonb)
  );
END;
$$;

-- FUNCTION: get_admin_customer_profile_v14(uuid, uuid)
CREATE FUNCTION public.get_admin_customer_profile_v14(p_actor_admin_id uuid, p_customer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_base jsonb;
  v_customer jsonb;
BEGIN
  v_base := public.get_admin_customer_profile_v8(
    p_actor_admin_id, p_customer_id
  );
  IF v_base ->> 'action' <> 'resolved' THEN
    RETURN v_base;
  END IF;

  v_customer := (v_base -> 'customer') || jsonb_build_object(
    'attributes', (
      SELECT jsonb_build_object(
        'nationalityCode', cp.nationality_code,
        'birthDate', cp.birth_date,
        'anniversaryDate', cp.anniversary_date,
        'vipRank', cp.vip_rank
      )
      FROM public.customer_profiles AS cp
      WHERE cp.customer_id = p_customer_id
    ),
    'reservationHistory', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'reservationId', history.id,
          'publicCode', history.public_code,
          'businessDate', ed.business_date,
          'scheduledStartAt', history.scheduled_start_at,
          'guestCount', history.guest_count,
          'lifecycleStatus', history.status,
          'serviceStatus', history.service_status
        )
        ORDER BY history.scheduled_start_at DESC, history.id
      )
      FROM (
        SELECT r.*
        FROM public.reservations AS r
        WHERE r.customer_id = p_customer_id
        ORDER BY r.scheduled_start_at DESC, r.id
        LIMIT 50
      ) AS history
      LEFT JOIN public.event_days AS ed ON ed.id = history.event_day_id
    ), '[]'::jsonb),
    'linkHistory', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'eventId', link.id,
          'reservationId', link.reservation_id,
          'linked', link.customer_id = p_customer_id,
          'unlinked', link.previous_customer_id = p_customer_id
            AND link.customer_id IS DISTINCT FROM p_customer_id,
          'resolutionMethod', link.resolution_method,
          'createdAt', link.created_at
        )
        ORDER BY link.created_at DESC, link.id
      )
      FROM (
        SELECT e.*
        FROM public.reservation_customer_link_events AS e
        WHERE e.customer_id = p_customer_id
           OR e.previous_customer_id = p_customer_id
        ORDER BY e.created_at DESC, e.id
        LIMIT 50
      ) AS link
    ), '[]'::jsonb)
  );

  RETURN jsonb_set(v_base, '{customer}', v_customer, true);
END;
$$;

-- FUNCTION: get_admin_customer_profile_v8(uuid, uuid)
CREATE FUNCTION public.get_admin_customer_profile_v8(p_actor_admin_id uuid, p_customer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_authorization jsonb;
  v_profile public.customer_profiles%ROWTYPE;
  v_profile_present boolean;
BEGIN
  v_authorization := public.require_admin_capability_v8(
    p_actor_admin_id,
    'customer.contact.read'
  );

  IF v_authorization ->> 'action' <> 'allowed' THEN
    RETURN v_authorization;
  END IF;

  IF p_customer_id IS NULL THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object('field', 'customerId')
      )
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.customers AS c
    WHERE c.id = p_customer_id
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'NOT_FOUND',
        'details', jsonb_build_object('entityType', 'customer')
      )
    );
  END IF;

  SELECT cp.*
  INTO v_profile
  FROM public.customer_profiles AS cp
  WHERE cp.customer_id = p_customer_id;

  v_profile_present := FOUND;

  INSERT INTO public.audit_logs(
    actor_admin_id,
    actor_type,
    action,
    target_table,
    target_id,
    request_id,
    before_json,
    after_json,
    reason,
    event_day_id,
    reservation_id,
    entity_type,
    entity_id,
    operation,
    expected_version,
    version_before,
    version_after,
    changed_fields,
    metadata_json
  )
  VALUES (
    p_actor_admin_id,
    'admin',
    'customer_profile.read',
    'customer_profiles',
    p_customer_id,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    'customer',
    p_customer_id,
    'customer_profile.read',
    NULL,
    NULL,
    NULL,
    ARRAY[]::text[],
    jsonb_build_object(
      'accessType', 'ciphertext_for_server_decrypt',
      'profilePresent', v_profile_present
    )
  );

  RETURN jsonb_build_object(
    'action', 'resolved',
    'schemaVersion', 'vip-customer.v2',
    'generatedAt', now(),
    'customer', jsonb_build_object(
      'id', p_customer_id,
      'profilePresent', v_profile_present,
      'profileVersion', CASE WHEN v_profile_present THEN v_profile.version ELSE NULL END,
      'languageCode', CASE WHEN v_profile_present THEN v_profile.language_code ELSE NULL END,
      'ciphertext', jsonb_build_object(
        'displayName', CASE
          WHEN v_profile_present AND v_profile.display_name_ciphertext IS NOT NULL
            THEN encode(v_profile.display_name_ciphertext, 'base64')
          ELSE NULL
        END,
        'nameKana', CASE
          WHEN v_profile_present AND v_profile.name_kana_ciphertext IS NOT NULL
            THEN encode(v_profile.name_kana_ciphertext, 'base64')
          ELSE NULL
        END,
        'phone', CASE
          WHEN v_profile_present AND v_profile.phone_ciphertext IS NOT NULL
            THEN encode(v_profile.phone_ciphertext, 'base64')
          ELSE NULL
        END,
        'email', CASE
          WHEN v_profile_present AND v_profile.email_ciphertext IS NOT NULL
            THEN encode(v_profile.email_ciphertext, 'base64')
          ELSE NULL
        END,
        'allergies', CASE
          WHEN v_profile_present AND v_profile.allergies_ciphertext IS NOT NULL
            THEN encode(v_profile.allergies_ciphertext, 'base64')
          ELSE NULL
        END,
        'preferences', CASE
          WHEN v_profile_present AND v_profile.preferences_ciphertext IS NOT NULL
            THEN encode(v_profile.preferences_ciphertext, 'base64')
          ELSE NULL
        END
      ),
      'tags', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', ct.id,
            'code', ct.tag_code,
            'label', ct.label,
            'category', ct.category,
            'createdAt', ct.created_at
          )
          ORDER BY ct.category NULLS LAST, ct.tag_code, ct.id
        )
        FROM public.customer_tags AS ct
        WHERE ct.customer_id = p_customer_id
      ), '[]'::jsonb),
      'aggregates', jsonb_build_object(
        'reservationCount', (
          SELECT count(*)
          FROM public.reservations AS r
          WHERE r.customer_id = p_customer_id
        ),
        'completedReservationCount', (
          SELECT count(*)
          FROM public.reservations AS r
          WHERE r.customer_id = p_customer_id
            AND r.service_status = 'completed'
        ),
        'cancelledReservationCount', (
          SELECT count(*)
          FROM public.reservations AS r
          WHERE r.customer_id = p_customer_id
            AND r.status = 'cancelled'
        ),
        'noShowCount', (
          SELECT count(*)
          FROM public.reservations AS r
          WHERE r.customer_id = p_customer_id
            AND (
              r.service_status = 'no_show'
              OR r.status = 'no_show_review'
            )
        ),
        'totalGuestCount', COALESCE((
          SELECT sum(r.guest_count)
          FROM public.reservations AS r
          WHERE r.customer_id = p_customer_id
        ), 0),
        'lastReservationAt', (
          SELECT max(r.scheduled_start_at)
          FROM public.reservations AS r
          WHERE r.customer_id = p_customer_id
        )
      )
    ),
    'accessAuditRecorded', true
  );
END;
$$;

-- FUNCTION: get_admin_vip_floor_board_v14(uuid, date)
CREATE FUNCTION public.get_admin_vip_floor_board_v14(p_actor_admin_id uuid, p_business_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_board jsonb;
  v_reservations jsonb;
BEGIN
  v_board := public.get_admin_vip_floor_board_v8(
    p_actor_admin_id, p_business_date
  );
  IF v_board ->> 'action' <> 'resolved' THEN
    RETURN v_board;
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      item.value || jsonb_build_object(
        'bookingOfferingId', r.booking_offering_id,
        'bookingStaffMemberId', r.booking_staff_member_id,
        'notificationPreference', r.manager_notification_preference,
        'operatorNote', r.operator_note
      )
      ORDER BY item.ordinality
    ),
    '[]'::jsonb
  )
  INTO v_reservations
  FROM jsonb_array_elements(v_board -> 'reservations')
    WITH ORDINALITY AS item(value, ordinality)
  JOIN public.reservations AS r
    ON r.id = (item.value ->> 'id')::uuid;

  RETURN jsonb_set(v_board, '{reservations}', v_reservations, true);
END;
$$;

-- FUNCTION: get_admin_vip_floor_board_v22(uuid, date)
CREATE FUNCTION public.get_admin_vip_floor_board_v22(p_actor_admin_id uuid, p_business_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_day public.event_days%ROWTYPE;
  v_board jsonb;
  v_reservations jsonb;
BEGIN
  SELECT * INTO v_day FROM public.event_days WHERE business_date = p_business_date;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'action', 'day_state', 'schemaVersion', 'vip-floor-day-state.v1',
      'businessDate', p_business_date, 'state', 'missing', 'reason', NULL
    );
  END IF;
  IF v_day.operating_status = 'closed' THEN
    RETURN jsonb_build_object(
      'action', 'day_state', 'schemaVersion', 'vip-floor-day-state.v1',
      'businessDate', p_business_date, 'state', 'closed', 'reason', v_day.closed_reason
    );
  END IF;

  v_board := public.get_admin_vip_floor_board_v14(p_actor_admin_id, p_business_date);
  IF v_board ->> 'action' <> 'resolved' THEN RETURN v_board; END IF;

  SELECT COALESCE(jsonb_agg(
    item.value || jsonb_build_object(
      'sourceChannel', r.origin_channel,
      'operatorNote', (
        SELECT rn.body FROM public.reservation_notes AS rn
        WHERE rn.reservation_id = r.id AND rn.kind = 'floor' AND rn.archived_at IS NULL
        ORDER BY rn.updated_at DESC, rn.id LIMIT 1
      )
    ) ORDER BY item.ordinality
  ), '[]'::jsonb)
  INTO v_reservations
  FROM jsonb_array_elements(v_board -> 'reservations') WITH ORDINALITY AS item(value, ordinality)
  JOIN public.reservations AS r ON r.id = (item.value ->> 'id')::uuid;

  RETURN jsonb_set(v_board, '{reservations}', v_reservations, true);
END;
$$;

-- FUNCTION: get_admin_vip_floor_board_v8(uuid, date)
CREATE FUNCTION public.get_admin_vip_floor_board_v8(p_actor_admin_id uuid, p_business_date date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH capability_check AS (
    SELECT public.require_admin_capability_v8(
      p_actor_admin_id,
      'floor.read'
    ) AS result
  ),
  actor AS (
    SELECT au.id, au.role
    FROM public.admin_users AS au
    WHERE au.id = p_actor_admin_id
      AND au.active = true
  ),
  requested_day AS (
    SELECT
      ed.id,
      ed.business_date,
      ed.venue_timezone,
      ed.sales_open_at,
      ed.sales_close_at
    FROM public.event_days AS ed
    WHERE ed.business_date = p_business_date
  ),
  day_revision AS (
    SELECT COALESCE(vfdr.revision, 0) AS revision
    FROM requested_day AS rd
    LEFT JOIN public.vip_floor_day_revisions AS vfdr
      ON vfdr.event_day_id = rd.id
  ),
  day_reservations AS (
    SELECT
      r.*,
      (
        r.event_day_id IS NULL
        OR r.scheduled_start_at IS NULL
        OR r.scheduled_end_at IS NULL
        OR r.expected_release_at IS NULL
      ) AS used_legacy_fallback,
      (
        r.status NOT IN (
          'cancelled',
          'hold_expired',
          'payment_window_expired',
          'failed'
        )
        AND r.service_status IS DISTINCT FROM 'completed'
        AND r.service_status IS DISTINCT FROM 'no_show'
      ) AS is_operationally_active,
      COALESCE(r.scheduled_start_at, bs.start_at) AS effective_start_at,
      COALESCE(r.scheduled_end_at, bs.end_at) AS effective_scheduled_end_at,
      COALESCE(
        r.expected_release_at,
        r.seat_extended_until_at,
        r.seat_due_at,
        bs.end_at
      ) AS effective_release_at
    FROM public.reservations AS r
    JOIN public.booking_slots AS bs
      ON bs.id = r.booking_slot_id
    WHERE COALESCE(r.event_day_id, bs.event_day_id) = (
      SELECT rd.id
      FROM requested_day AS rd
    )
  ),
  latest_payments AS (
    SELECT DISTINCT ON (p.reservation_id)
      p.id,
      p.reservation_id,
      p.status,
      p.type,
      p.amount_yen,
      p.environment,
      p.stripe_account_key,
      p.payment_method_id,
      p.stripe_payment_method_id,
      p.provider_object_type,
      p.provider_object_id,
      p.updated_at
    FROM public.payments AS p
    JOIN day_reservations AS r
      ON r.id = p.reservation_id
    ORDER BY p.reservation_id, p.updated_at DESC, p.id DESC
  ),
  payment_evidence AS (
    SELECT
      lp.reservation_id,
      lp.status,
      lp.type,
      lp.amount_yen,
      (lp.payment_method_id IS NOT NULL OR lp.stripe_payment_method_id IS NOT NULL)
        AS payment_method_saved,
      webhook.processing_status AS webhook_processing_status,
      object_state.stripe_status AS stripe_object_status,
      lp.updated_at
    FROM latest_payments AS lp
    LEFT JOIN LATERAL (
      SELECT we.processing_status
      FROM public.webhook_events AS we
      WHERE lp.provider_object_id IS NOT NULL
        AND we.environment = lp.environment
        AND we.stripe_account_key = lp.stripe_account_key
        AND we.provider_object_type IS NOT DISTINCT FROM lp.provider_object_type
        AND we.provider_object_id = lp.provider_object_id
      ORDER BY we.updated_at DESC, we.id DESC
      LIMIT 1
    ) AS webhook ON true
    LEFT JOIN LATERAL (
      SELECT sos.stripe_status
      FROM public.stripe_object_states AS sos
      WHERE lp.provider_object_id IS NOT NULL
        AND sos.environment = lp.environment
        AND sos.stripe_account_key = lp.stripe_account_key
        AND sos.object_type = lp.provider_object_type
        AND sos.object_id = lp.provider_object_id
      ORDER BY sos.updated_at DESC, sos.id DESC
      LIMIT 1
    ) AS object_state ON true
  ),
  active_assignments AS (
    SELECT
      rr.id,
      rr.reservation_id,
      rr.seat_resource_id,
      rr.lock_status,
      rr.assigned_start_at,
      rr.assigned_end_at,
      rr.assignment_role,
      rr.version,
      rr.created_at,
      rr.updated_at
    FROM public.reservation_resources AS rr
    JOIN day_reservations AS r
      ON r.id = rr.reservation_id
    WHERE r.is_operationally_active
      AND public.active_reservation_assignment_v8(rr.id, now())
  ),
  active_blocks AS (
    SELECT rb.*
    FROM public.reservation_blocks AS rb
    WHERE rb.event_day_id = (
        SELECT rd.id
        FROM requested_day AS rd
      )
      AND rb.status = 'active'
  ),
  visible_notes AS (
    SELECT rn.*
    FROM public.reservation_notes AS rn
    JOIN day_reservations AS r
      ON r.id = rn.reservation_id
    WHERE rn.archived_at IS NULL
  ),
  ordered_unassigned AS (
    SELECT r.id, r.effective_start_at, r.public_code
    FROM day_reservations AS r
    WHERE r.is_operationally_active
      AND NOT EXISTS (
        SELECT 1
        FROM active_assignments AS aa
        WHERE aa.reservation_id = r.id
      )
  )
  SELECT CASE
    WHEN capability_check.result ->> 'action' <> 'allowed'
      THEN capability_check.result
    WHEN p_business_date IS NULL THEN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object('field', 'businessDate')
      )
    )
    WHEN NOT EXISTS (SELECT 1 FROM requested_day) THEN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'NOT_FOUND',
        'details', jsonb_build_object(
          'entityType', 'event_day',
          'businessDate', p_business_date
        )
      )
    )
    ELSE jsonb_build_object(
      'action', 'resolved',
      'schemaVersion', 'vip-floor.v2',
      'generatedAt', now(),
      'revision', (SELECT dr.revision FROM day_revision AS dr),
      'boardRevision', (SELECT dr.revision FROM day_revision AS dr),
      'legacyFallbackCount', (
        SELECT count(*)
        FROM day_reservations AS r
        WHERE r.used_legacy_fallback
      ),
      'businessDay', (
        SELECT jsonb_build_object(
          'id', rd.id,
          'businessDate', rd.business_date,
          'venueTimezone', rd.venue_timezone,
          'operatingStartAt', rd.sales_open_at,
          'operatingEndAt', rd.sales_close_at
        )
        FROM requested_day AS rd
      ),
      'capabilities', (
        SELECT jsonb_build_object(
          'readCustomerPii', a.role IN ('manager', 'owner', 'engineer'),
          'changeServiceStatus', a.role IN ('staff', 'manager', 'owner', 'engineer'),
          'changeAssignments', a.role IN ('manager', 'owner', 'engineer'),
          'changeSchedule', a.role IN ('manager', 'owner', 'engineer'),
          'manageBlocks', a.role IN ('manager', 'owner', 'engineer'),
          'cancelReservation', a.role IN ('manager', 'owner', 'engineer')
        )
        FROM actor AS a
      ),
      'sections', (
        SELECT COALESCE(
          jsonb_agg(
            jsonb_build_object(
              'id', fs.id,
              'code', fs.code,
              'name', fs.name,
              'sortOrder', fs.sort_order
            )
            ORDER BY fs.sort_order, fs.code, fs.id
          ),
          '[]'::jsonb
        )
        FROM public.floor_sections AS fs
        WHERE fs.active = true
      ),
      'tables', (
        SELECT COALESCE(
          jsonb_agg(
            jsonb_build_object(
              'id', sr.id,
              'version', sr.version,
              'publicResourceCode', sr.public_resource_code,
              'displayCode', sr.display_code,
              'name', sr.name,
              'sectionId', sr.floor_section_id,
              'capacityMin', sr.capacity_min,
              'capacityMax', sr.capacity_max,
              'onlineEligible', sr.online_eligible,
              'geometry', jsonb_build_object(
                'shape', sr.shape,
                'xPercent', sr.x_percent,
                'yPercent', sr.y_percent,
                'widthPercent', sr.width_percent,
                'heightPercent', sr.height_percent,
                'rotationDegrees', sr.rotation_degrees
              ),
              'operationalLocked', sr.operational_locked,
              'lockReason', sr.lock_reason,
              'reservationIds', COALESCE((
                SELECT jsonb_agg(
                  aa.reservation_id
                  ORDER BY aa.assigned_start_at, r.public_code, aa.id
                )
                FROM active_assignments AS aa
                JOIN day_reservations AS r
                  ON r.id = aa.reservation_id
                WHERE aa.seat_resource_id = sr.id
              ), '[]'::jsonb),
              'blockIds', COALESCE((
                SELECT jsonb_agg(ab.id ORDER BY ab.start_at, ab.id)
                FROM active_blocks AS ab
                WHERE EXISTS (
                  SELECT 1
                  FROM public.reservation_block_targets AS rbt
                  WHERE rbt.block_id = ab.id
                    AND (
                      rbt.seat_resource_id = sr.id
                      OR rbt.floor_section_id = sr.floor_section_id
                      OR rbt.venue_wide
                    )
                )
              ), '[]'::jsonb)
            )
            ORDER BY fs.sort_order, sr.sort_order, sr.display_code, sr.id
          ),
          '[]'::jsonb
        )
        FROM public.seat_resources AS sr
        JOIN public.floor_sections AS fs
          ON fs.id = sr.floor_section_id
        WHERE sr.active = true
          AND fs.active = true
      ),
      'reservations', (
        SELECT COALESCE(
          jsonb_agg(
            jsonb_build_object(
              'id', r.id,
              'version', r.version,
              'publicCode', r.public_code,
              'businessDate', p_business_date,
              'lifecycleStatus', CASE r.status
                WHEN 'checked_in' THEN 'confirmed'
                WHEN 'hold_expired' THEN 'expired'
                WHEN 'payment_window_expired' THEN 'expired'
                ELSE r.status::text
              END,
              'serviceStatus', r.service_status,
              'sourceChannel', r.intake_channel,
              'scheduledStartAt', r.effective_start_at,
              'scheduledEndAt', r.effective_scheduled_end_at,
              'expectedReleaseAt', r.effective_release_at,
              'actualSeatedAt', r.checked_in_at,
              'completedAt', r.service_completed_at,
              'guestCount', jsonb_build_object(
                'total', r.guest_count,
                'adults', NULL,
                'children', NULL
              ),
              'assignmentIds', COALESCE((
                SELECT jsonb_agg(
                  aa.id
                  ORDER BY aa.assigned_start_at, sr.sort_order, aa.id
                )
                FROM active_assignments AS aa
                JOIN public.seat_resources AS sr
                  ON sr.id = aa.seat_resource_id
                WHERE aa.reservation_id = r.id
              ), '[]'::jsonb),
              'tableIds', COALESCE((
                SELECT jsonb_agg(
                  aa.seat_resource_id
                  ORDER BY aa.assigned_start_at, sr.sort_order, aa.id
                )
                FROM active_assignments AS aa
                JOIN public.seat_resources AS sr
                  ON sr.id = aa.seat_resource_id
                WHERE aa.reservation_id = r.id
              ), '[]'::jsonb),
              'customer', CASE
                WHEN r.customer_id IS NULL
                  AND NULLIF(btrim(r.guest_label), '') IS NULL
                  THEN NULL
                ELSE jsonb_build_object(
                  'customerId', r.customer_id,
                  'displayLabel', CASE
                    WHEN (SELECT a.role FROM actor AS a) = 'staff' THEN
                      CASE
                        WHEN NULLIF(btrim(r.guest_label), '') IS NULL
                          THEN 'Guest ***' || right(r.public_code, 2)
                        ELSE left(btrim(r.guest_label), 1) || '***'
                      END
                    ELSE COALESCE(
                      NULLIF(btrim(r.guest_label), ''),
                      'Guest ' || right(r.public_code, 4)
                    )
                  END,
                  'masked', (SELECT a.role FROM actor AS a) = 'staff'
                )
              END,
              'payment', (
                SELECT jsonb_build_object(
                  'status', pe.status,
                  'type', pe.type,
                  'amountYen', pe.amount_yen,
                  'paymentMethodSaved', pe.payment_method_saved,
                  'webhookProcessingStatus', pe.webhook_processing_status,
                  'stripeObjectStatus', pe.stripe_object_status,
                  'updatedAt', pe.updated_at
                )
                FROM payment_evidence AS pe
                WHERE pe.reservation_id = r.id
              ),
              'notes', COALESCE((
                SELECT jsonb_agg(
                  jsonb_build_object(
                    'id', vn.id,
                    'kind', vn.kind,
                    'body', vn.body,
                    'pinned', vn.pinned,
                    'version', vn.version,
                    'updatedAt', vn.updated_at
                  )
                  ORDER BY vn.pinned DESC, vn.created_at, vn.id
                )
                FROM visible_notes AS vn
                WHERE vn.reservation_id = r.id
              ), '[]'::jsonb),
              'flags', (
                SELECT COALESCE(
                  jsonb_agg(flag ORDER BY ordinal),
                  '[]'::jsonb
                )
                FROM (VALUES
                  (1, CASE WHEN r.used_legacy_fallback THEN 'legacy_fallback' END),
                  (2, CASE
                    WHEN r.is_operationally_active AND NOT EXISTS (
                      SELECT 1
                      FROM active_assignments AS aa
                      WHERE aa.reservation_id = r.id
                    ) THEN 'unassigned'
                  END),
                  (3, CASE WHEN r.status IN (
                    'late_cancel_review',
                    'no_show_review',
                    'refund_required',
                    'payment_binding_review',
                    'card_saved_inventory_lost',
                    'inventory_conflict_review',
                    'admin_hold_review'
                  ) THEN 'review_required' END)
                ) AS derived_flags(ordinal, flag)
                WHERE flag IS NOT NULL
              ),
              'updatedAt', r.updated_at
            )
            ORDER BY r.effective_start_at, r.public_code, r.id
          ),
          '[]'::jsonb
        )
        FROM day_reservations AS r
      ),
      'assignments', (
        SELECT COALESCE(
          jsonb_agg(
            jsonb_build_object(
              'id', aa.id,
              'version', aa.version,
              'reservationId', aa.reservation_id,
              'tableId', aa.seat_resource_id,
              'lockStatus', aa.lock_status,
              'assignmentRole', aa.assignment_role,
              'startAt', aa.assigned_start_at,
              'endAt', aa.assigned_end_at,
              'updatedAt', aa.updated_at
            )
            ORDER BY aa.assigned_start_at, r.public_code, sr.sort_order, aa.id
          ),
          '[]'::jsonb
        )
        FROM active_assignments AS aa
        JOIN day_reservations AS r
          ON r.id = aa.reservation_id
        JOIN public.seat_resources AS sr
          ON sr.id = aa.seat_resource_id
      ),
      'unassignedReservationIds', (
        SELECT COALESCE(
          jsonb_agg(
            ou.id
            ORDER BY ou.effective_start_at, ou.public_code, ou.id
          ),
          '[]'::jsonb
        )
        FROM ordered_unassigned AS ou
      ),
      'blocks', (
        SELECT COALESCE(
          jsonb_agg(
            jsonb_build_object(
              'id', ab.id,
              'version', ab.version,
              'scope', ab.scope,
              'kind', ab.kind,
              'startAt', ab.start_at,
              'endAt', ab.end_at,
              'memo', ab.memo,
              'targets', jsonb_build_object(
                'venueWide', EXISTS (
                  SELECT 1
                  FROM public.reservation_block_targets AS rbt
                  WHERE rbt.block_id = ab.id
                    AND rbt.venue_wide
                ),
                'sectionIds', COALESCE((
                  SELECT jsonb_agg(rbt.floor_section_id ORDER BY rbt.floor_section_id)
                  FROM public.reservation_block_targets AS rbt
                  WHERE rbt.block_id = ab.id
                    AND rbt.floor_section_id IS NOT NULL
                ), '[]'::jsonb),
                'tableIds', COALESCE((
                  SELECT jsonb_agg(rbt.seat_resource_id ORDER BY rbt.seat_resource_id)
                  FROM public.reservation_block_targets AS rbt
                  WHERE rbt.block_id = ab.id
                    AND rbt.seat_resource_id IS NOT NULL
                ), '[]'::jsonb)
              ),
              'updatedAt', ab.updated_at
            )
            ORDER BY ab.start_at, ab.end_at, ab.id
          ),
          '[]'::jsonb
        )
        FROM active_blocks AS ab
      ),
      'notes', (
        SELECT COALESCE(
          jsonb_agg(
            jsonb_build_object(
              'id', vn.id,
              'reservationId', vn.reservation_id,
              'kind', vn.kind,
              'body', vn.body,
              'pinned', vn.pinned,
              'version', vn.version,
              'updatedAt', vn.updated_at
            )
            ORDER BY r.effective_start_at, vn.pinned DESC, vn.created_at, vn.id
          ),
          '[]'::jsonb
        )
        FROM visible_notes AS vn
        JOIN day_reservations AS r
          ON r.id = vn.reservation_id
      ),
      'totals', jsonb_build_object(
        'tableCount', (
          SELECT count(*)
          FROM public.seat_resources AS sr
          JOIN public.floor_sections AS fs
            ON fs.id = sr.floor_section_id
          WHERE sr.active = true
            AND fs.active = true
        ),
        'reservationCount', (SELECT count(*) FROM day_reservations),
        'activeReservationCount', (
          SELECT count(*)
          FROM day_reservations AS r
          WHERE r.is_operationally_active
        ),
        'assignmentCount', (SELECT count(*) FROM active_assignments),
        'unassignedReservationCount', (SELECT count(*) FROM ordered_unassigned),
        'activeBlockCount', (SELECT count(*) FROM active_blocks),
        'noteCount', (SELECT count(*) FROM visible_notes),
        'guestCount', COALESCE((
          SELECT sum(r.guest_count)
          FROM day_reservations AS r
          WHERE r.is_operationally_active
        ), 0),
        'serviceStatusCounts', COALESCE((
          SELECT jsonb_object_agg(status_key, status_count ORDER BY status_key)
          FROM (
            SELECT
              COALESCE(r.service_status::text, 'not_set') AS status_key,
              count(*) AS status_count
            FROM day_reservations AS r
            GROUP BY COALESCE(r.service_status::text, 'not_set')
          ) AS counts
        ), '{}'::jsonb)
      )
    )
  END
  FROM capability_check;
$$;

-- FUNCTION: get_admin_vip_floor_revision_v20(uuid, date)
CREATE FUNCTION public.get_admin_vip_floor_revision_v20(p_actor_admin_id uuid, p_business_date date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_step jsonb;
  v_event_day_id uuid;
  v_revision bigint;
BEGIN
  v_step := public.require_admin_capability_v8(
    p_actor_admin_id,
    'floor.read'
  );
  IF v_step ->> 'action' <> 'allowed' THEN
    RETURN v_step;
  END IF;

  IF p_business_date IS NULL THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object('field', 'businessDate')
      )
    );
  END IF;

  SELECT id
  INTO v_event_day_id
  FROM public.event_days
  WHERE business_date = p_business_date;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'NOT_FOUND',
        'details', jsonb_build_object(
          'entityType', 'event_day',
          'businessDate', p_business_date
        )
      )
    );
  END IF;

  SELECT COALESCE(revision, 0)
  INTO v_revision
  FROM public.vip_floor_day_revisions
  WHERE event_day_id = v_event_day_id;

  RETURN jsonb_build_object(
    'action', 'resolved',
    'schemaVersion', 'vip-floor-revision.v1',
    'businessDate', p_business_date,
    'revision', COALESCE(v_revision, 0)
  );
END;
$$;

-- FUNCTION: get_admin_vip_floor_revision_v22(uuid, date)
CREATE FUNCTION public.get_admin_vip_floor_revision_v22(p_actor_admin_id uuid, p_business_date date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_day public.event_days%ROWTYPE;
BEGIN
  SELECT * INTO v_day FROM public.event_days WHERE business_date = p_business_date;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'action', 'day_state', 'schemaVersion', 'vip-floor-day-state.v1',
      'businessDate', p_business_date, 'state', 'missing', 'reason', NULL
    );
  END IF;
  IF v_day.operating_status = 'closed' THEN
    RETURN jsonb_build_object(
      'action', 'day_state', 'schemaVersion', 'vip-floor-day-state.v1',
      'businessDate', p_business_date, 'state', 'closed', 'reason', v_day.closed_reason
    );
  END IF;
  RETURN public.get_admin_vip_floor_revision_v20(p_actor_admin_id, p_business_date);
END;
$$;

-- FUNCTION: get_public_reservation_status_v21(text)
CREATE FUNCTION public.get_public_reservation_status_v21(p_status_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
BEGIN
  IF p_status_token !~ '^[a-fA-F0-9]{48}$'
    OR NOT EXISTS (
      SELECT 1
      FROM public.reservations AS r
      WHERE r.status_token_hash = encode(digest(p_status_token, 'sha256'), 'hex')
        AND r.status_token_expires_at > now()
    )
  THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  RETURN public.get_public_reservation_status_v7(p_status_token);
END;
$_$;

-- FUNCTION: get_public_reservation_status_v7(text)
CREATE FUNCTION public.get_public_reservation_status_v7(p_status_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  PERFORM public.expire_public_reservation_holds_v7();

  SELECT COALESCE(
    (
      SELECT jsonb_build_object(
        'found', true,
        'publicCode', r.public_code,
        'status', r.status,
        'guestCount', r.guest_count,
        'holdExpiresAt', r.hold_expires_at,
        'confirmedAt', r.confirmed_at,
        'payment', jsonb_build_object(
          'status', p.status,
          'type', p.type,
          'providerObjectType', p.provider_object_type,
          'providerObjectId', p.provider_object_id,
          'stripePaymentMethodId', p.stripe_payment_method_id,
          'hasStripePaymentMethodId', p.stripe_payment_method_id IS NOT NULL,
          'paymentMethodSaved', p.payment_method_id IS NOT NULL
            OR EXISTS (
              SELECT 1
              FROM public.payment_methods AS pm
              WHERE pm.environment = p.environment
                AND pm.stripe_account_key = p.stripe_account_key
                AND pm.stripe_payment_method_id = p.stripe_payment_method_id
                AND pm.status = 'active'
            ),
          'webhookProcessingStatus', wh.processing_status,
          'stripeObjectStatus', sos.stripe_status
        ),
        'slot', jsonb_build_object(
          'publicSlotId', bs.public_slot_id,
          'startAt', bs.start_at,
          'endAt', bs.end_at
        ),
        'offering', jsonb_build_object(
          'publicOfferingId', bo.public_offering_id,
          'name', bo.name
        ),
        'seat', jsonb_build_object(
          'publicResourceCode', seat.public_resource_code,
          'name', seat.name
        )
      )
      FROM public.reservations AS r
      JOIN public.booking_slots AS bs ON bs.id = r.booking_slot_id
      JOIN public.booking_offerings AS bo ON bo.id = r.booking_offering_id
      LEFT JOIN LATERAL (
        SELECT payment.*
        FROM public.payments AS payment
        WHERE payment.reservation_id = r.id
        ORDER BY payment.created_at DESC
        LIMIT 1
      ) AS p ON true
      LEFT JOIN LATERAL (
        SELECT sr.public_resource_code, sr.name
        FROM public.reservation_resources AS rr
        JOIN public.seat_resources AS sr ON sr.id = rr.seat_resource_id
        WHERE rr.reservation_id = r.id
        ORDER BY rr.created_at, rr.id
        LIMIT 1
      ) AS seat ON true
      LEFT JOIN LATERAL (
        SELECT event.processing_status
        FROM public.webhook_events AS event
        WHERE event.environment = p.environment
          AND event.stripe_account_key = p.stripe_account_key
          AND event.provider_object_type = p.provider_object_type
          AND event.provider_object_id = p.provider_object_id
        ORDER BY event.created_at DESC
        LIMIT 1
      ) AS wh ON true
      LEFT JOIN public.stripe_object_states AS sos
        ON sos.environment = p.environment
       AND sos.stripe_account_key = p.stripe_account_key
       AND sos.object_type = p.provider_object_type
       AND sos.object_id = p.provider_object_id
      WHERE r.status_token_hash = encode(digest(p_status_token, 'sha256'), 'hex')
      LIMIT 1
    ),
    jsonb_build_object('found', false)
  )
  INTO v_result;

  RETURN v_result;
END;
$$;

-- FUNCTION: get_vip_manager_slo_v15(uuid, integer)
CREATE FUNCTION public.get_vip_manager_slo_v15(p_actor_admin_id uuid, p_window_minutes integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_window int := LEAST(GREATEST(COALESCE(p_window_minutes, 60), 5), 1440);
  v_total_commands bigint;
  v_failed_commands bigint;
  v_p95_command_ms numeric;
  v_p95_board_ms numeric;
  v_outbox_dead bigint;
  v_realtime_gaps bigint;
  v_realtime_unavailable bigint;
  v_error_rate numeric;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admin_users
    WHERE id = p_actor_admin_id AND active = true AND role = 'owner'
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object('code', 'FORBIDDEN')
    );
  END IF;

  SELECT
    count(*) FILTER (WHERE metric_name IN ('command', 'command_error')),
    count(*) FILTER (
      WHERE metric_name = 'command_error' OR outcome = 'error'
    ),
    percentile_cont(0.95) WITHIN GROUP (ORDER BY duration_ms)
      FILTER (WHERE metric_name IN ('command', 'command_error')),
    percentile_cont(0.95) WITHIN GROUP (ORDER BY duration_ms)
      FILTER (WHERE metric_name = 'board_read'),
    count(*) FILTER (WHERE metric_name = 'outbox_dead'),
    count(*) FILTER (WHERE metric_name = 'realtime_gap'),
    count(*) FILTER (WHERE metric_name = 'realtime_unavailable')
  INTO
    v_total_commands,
    v_failed_commands,
    v_p95_command_ms,
    v_p95_board_ms,
    v_outbox_dead,
    v_realtime_gaps,
    v_realtime_unavailable
  FROM public.vip_manager_metrics
  WHERE occurred_at >= now() - make_interval(mins => v_window);

  v_error_rate := CASE
    WHEN v_total_commands = 0 THEN 0
    ELSE v_failed_commands::numeric / v_total_commands
  END;

  RETURN jsonb_build_object(
    'action', 'resolved',
    'schemaVersion', 'vip-manager-slo.v1',
    'generatedAt', now(),
    'windowMinutes', v_window,
    'metrics', jsonb_build_object(
      'commandCount', v_total_commands,
      'commandErrorCount', v_failed_commands,
      'commandErrorRate', round(v_error_rate, 4),
      'commandP95Ms', COALESCE(round(v_p95_command_ms), 0),
      'boardReadP95Ms', COALESCE(round(v_p95_board_ms), 0),
      'outboxDeadCount', v_outbox_dead,
      'realtimeGapCount', v_realtime_gaps,
      'realtimeUnavailableCount', v_realtime_unavailable
    ),
    'targets', jsonb_build_object(
      'commandErrorRateMax', 0.01,
      'commandP95MsMax', 1000,
      'boardReadP95MsMax', 1000,
      'outboxDeadCountMax', 0,
      'realtimeGapCountMax', 3
    ),
    'alerts', jsonb_strip_nulls(jsonb_build_object(
      'commandErrorRate', CASE
        WHEN v_error_rate > 0.01 THEN 'critical' ELSE NULL
      END,
      'commandLatency', CASE
        WHEN COALESCE(v_p95_command_ms, 0) > 1000 THEN 'warning' ELSE NULL
      END,
      'boardReadLatency', CASE
        WHEN COALESCE(v_p95_board_ms, 0) > 1000 THEN 'warning' ELSE NULL
      END,
      'outboxDead', CASE
        WHEN v_outbox_dead > 0 THEN 'critical' ELSE NULL
      END,
      'realtimeGap', CASE
        WHEN v_realtime_gaps > 3 THEN 'warning' ELSE NULL
      END
    ))
  );
END;
$$;

-- FUNCTION: ghost_vip_stamp_trial_run_id_v16()
CREATE FUNCTION public.ghost_vip_stamp_trial_run_id_v16() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.trial_run_id IS NULL THEN NEW.trial_run_id := public.ghost_vip_trial_run_id_v16(); END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: ghost_vip_trial_run_id_v16()
CREATE FUNCTION public.ghost_vip_trial_run_id_v16() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_headers jsonb := current_setting('request.headers', true)::jsonb;
  v_run_id text := NULLIF(v_headers ->> 'x-ghost-vip-trial-run-id', '');
BEGIN
  IF v_run_id IS NULL THEN RETURN NULL; END IF;
  IF v_run_id !~ '^trial-[a-z0-9][a-z0-9-]{7,80}$' THEN
    RAISE EXCEPTION 'invalid_trial_run_id';
  END IF;
  INSERT INTO public.vip_manager_trial_runs(trial_run_id) VALUES (v_run_id)
  ON CONFLICT (trial_run_id) DO NOTHING;
  RETURN v_run_id;
END;
$_$;

-- FUNCTION: grant_ticket_order_to_verified_holder_v34()
CREATE FUNCTION public.grant_ticket_order_to_verified_holder_v34() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NEW.check_in_mode='wallet_swipe' AND NEW.status='fulfilled' AND NEW.paid_at IS NOT NULL AND NEW.fulfilled_at IS NOT NULL THEN
  INSERT INTO public.ticket_holder_orders(holder_id,ticket_order_id,grant_method)
  SELECT holder_id,NEW.id,'email_otp' FROM public.ticket_holder_email_identities WHERE environment=NEW.environment AND identity_email_hash=NEW.purchaser_email_hash ON CONFLICT DO NOTHING;
 END IF;
 RETURN NEW;
END; $$;

-- FUNCTION: guard_ticket_commercial_snapshot_v39()
CREATE FUNCTION public.guard_ticket_commercial_snapshot_v39() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
 IF OLD.items_json->0 ? 'commercial' AND NEW.items_json IS DISTINCT FROM OLD.items_json THEN
  RAISE EXCEPTION 'ticket commercial snapshot is immutable';
 END IF;
 RETURN NEW;
END; $$;

-- FUNCTION: guard_ticket_entry_obligation_v53()
CREATE FUNCTION public.guard_ticket_entry_obligation_v53() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 PERFORM public.ticket_wallet_gate_fence_v30();
 IF NOT EXISTS(SELECT 1 FROM public.ticket_orders o JOIN public.ticket_event_sessions e ON e.id=o.event_session_id
  WHERE o.id=NEW.ticket_order_id AND o.admission_policy='order_together_v1' AND e.enabled AND e.admission_state<>'cancelled'
  AND e.admission_closes_at>clock_timestamp()) THEN RAISE EXCEPTION 'ticket_order_entry_gate_closed'; END IF;
 RETURN NEW;
END $$;

-- FUNCTION: guard_ticket_group_consumption_v52()
CREATE FUNCTION public.guard_ticket_group_consumption_v52() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r record; issued integer; admitted integer;
BEGIN
 FOR r IN SELECT n.ticket_order_id,count(*)::integer used FROM entry_new n JOIN entry_old previous USING(id)
  JOIN public.ticket_orders o ON o.id=n.ticket_order_id
  WHERE n.status='admitted' AND previous.status<>'admitted' AND o.admission_policy='order_together_v1'
  GROUP BY n.ticket_order_id LOOP
  SELECT count(*) FILTER(WHERE status='issued'),count(*) FILTER(WHERE status='admitted') INTO issued,admitted
   FROM public.ticket_admissions WHERE ticket_order_id=r.ticket_order_id;
  IF issued<>0 OR admitted<>r.used THEN RAISE EXCEPTION 'whole_order_consumption_required'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM entry_new n JOIN entry_old previous USING(id) JOIN public.ticket_orders o ON o.id=n.ticket_order_id
  WHERE o.admission_policy='order_together_v1' AND previous.status='admitted' AND n.status<>'admitted')
 THEN RAISE EXCEPTION 'used_ticket_cannot_be_reset'; END IF;
 RETURN NULL;
END $$;

-- FUNCTION: guard_ticket_group_prepare_v52()
CREATE FUNCTION public.guard_ticket_group_prepare_v52() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NEW.state='prepared' AND OLD.state='initializing' AND NOT COALESCE(public.ticket_group_entry_selection_v52(
  NEW.ticket_order_id,ARRAY(SELECT ticket_admission_id FROM public.ticket_admission_operation_items WHERE operation_id=NEW.id)),false)
 THEN RAISE EXCEPTION 'whole_order_selection_required'; END IF;
 RETURN NEW;
END $$;

-- FUNCTION: guard_ticket_mail_capacity_v47()
CREATE FUNCTION public.guard_ticket_mail_capacity_v47() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE browser text:=current_setting('ghost.ticket_purchase_browser_v47',true);
BEGIN
 IF NEW.check_in_mode<>'wallet_swipe' THEN RETURN NEW; END IF;
 IF browser IS NULL OR browser !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'mail_capacity_browser_required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('ghost.ticket.purchase.browser.v79:'||browser,0));
 IF EXISTS(SELECT 1 FROM public.ticket_purchase_browser_bindings b
   JOIN public.ticket_checkout_actions a ON a.id=b.checkout_action_id
   JOIN public.ticket_orders o ON o.id=a.ticket_order_id
   WHERE b.browser_verifier=browser AND b.expires_at>clock_timestamp() AND o.environment=NEW.environment
    AND o.status='pending'
    AND NOT COALESCE(a.provider_terminal_status='expired' AND o.paid_at IS NULL AND o.provider_paid_at IS NULL,false))
 THEN RAISE EXCEPTION 'ticket_pending_checkout_exists'; END IF;
 NEW.checkout_expires_at:=date_trunc('second',LEAST(NEW.checkout_expires_at,clock_timestamp()+interval '45 minutes'));
 RETURN NEW;
END; $_$;

-- FUNCTION: guard_ticket_order_entry_policy_v52()
CREATE FUNCTION public.guard_ticket_order_entry_policy_v52() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE item jsonb; version text;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.admission_policy IS DISTINCT FROM OLD.admission_policy THEN RAISE EXCEPTION 'ticket_entry_policy_immutable'; END IF;
  RETURN NEW;
 END IF;
 version:=NEW.items_json->0->'commercial'->>'version';
 FOR item IN SELECT value FROM jsonb_array_elements(NEW.items_json) LOOP
  IF item->'commercial'->>'version' IS DISTINCT FROM version
   OR (version IS NULL AND item ? 'commercial') THEN RAISE EXCEPTION 'ticket_terms_mixed_or_invalid'; END IF;
 END LOOP;
 IF version IN ('2026-09-13.1','2026-09-14.1') THEN
  IF NEW.check_in_mode<>'wallet_swipe' THEN RAISE EXCEPTION 'group_wallet_required'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(NEW.items_json) LOOP
   IF item->'commercial'->>'version' IS DISTINCT FROM version
    OR item->'commercial'->>'admissionPolicy' IS DISTINCT FROM 'order_together_v1'
   THEN RAISE EXCEPTION 'group_terms_invalid'; END IF;
  END LOOP;
  NEW.admission_policy:='order_together_v1';
 ELSIF version IS NULL OR version='2026-09-08.1' THEN
  NEW.admission_policy:='individual_v1';
 ELSE RAISE EXCEPTION 'ticket_terms_unknown'; END IF;
 RETURN NEW;
END $$;

-- FUNCTION: guard_ticket_wallet_auth_obligation_v30()
CREATE FUNCTION public.guard_ticket_wallet_auth_obligation_v30() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_environment text;
  v_identity_email_hash text;
  v_is_decoy boolean := false;
  v_creates_obligation boolean := false;
BEGIN
  PERFORM public.ticket_wallet_gate_fence_v30();

  IF TG_TABLE_NAME = 'ticket_wallet_otp_challenges' THEN
    v_environment := NEW.environment;
    v_identity_email_hash := NEW.identity_email_hash;
    v_is_decoy := NEW.is_decoy;
    v_creates_obligation := NEW.state IN ('pending', 'sending', 'sent');
  ELSIF TG_TABLE_NAME = 'ticket_wallet_sessions' THEN
    v_environment := NEW.environment;
    v_identity_email_hash := NEW.identity_email_hash;
    v_creates_obligation := NEW.revoked_at IS NULL;
  ELSIF TG_TABLE_NAME = 'transactional_email_jobs' THEN
    IF NEW.purpose='ticket_wallet_purchase' THEN
      IF NOT EXISTS(SELECT 1 FROM public.ticket_orders o WHERE o.id=NEW.ticket_order_id
        AND o.check_in_mode='wallet_swipe' AND o.status IN ('fulfilled','refunded')
        AND o.paid_at IS NOT NULL AND o.fulfilled_at IS NOT NULL
        AND o.purchaser_email_hash=NEW.recipient_email_hash) THEN
        RAISE EXCEPTION 'purchase notice order authority is missing';
      END IF;
      RETURN NEW;
    END IF;
    SELECT challenge.environment, challenge.identity_email_hash, challenge.is_decoy
    INTO v_environment, v_identity_email_hash, v_is_decoy
    FROM public.ticket_wallet_otp_challenges AS challenge
    WHERE challenge.id = NEW.otp_challenge_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING
        ERRCODE = '23503',
        MESSAGE = 'ticket wallet email challenge authority is missing';
    END IF;
    v_creates_obligation := NEW.state IN ('pending', 'processing', 'retry');
  ELSE
    RAISE EXCEPTION 'unsupported Ticket Wallet auth fence relation';
  END IF;

  IF v_creates_obligation AND NOT v_is_decoy AND NOT EXISTS (
    SELECT 1
    FROM public.ticket_orders AS ticket_order
    JOIN public.ticket_event_sessions AS event_session
      ON event_session.id = ticket_order.event_session_id
     AND event_session.environment = ticket_order.environment
     AND event_session.stripe_account_key = ticket_order.stripe_account_key
    WHERE ticket_order.environment = v_environment
      AND ticket_order.check_in_mode = 'wallet_swipe'
      AND ticket_order.purchaser_email_hash = v_identity_email_hash
      AND ticket_order.status = 'fulfilled'
      AND ticket_order.paid_at IS NOT NULL
      AND ticket_order.fulfilled_at IS NOT NULL
      AND ticket_order.payment_hold_reason IS NULL
      AND event_session.enabled
      AND event_session.admission_state <> 'cancelled'
      AND event_session.admission_closes_at + interval '8 days' > clock_timestamp()
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'ticket wallet customer gate is closed';
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: guard_ticket_wallet_legacy_email_obligation_v30()
CREATE FUNCTION public.guard_ticket_wallet_legacy_email_obligation_v30() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_check_in_mode text;
  v_event_session_id uuid;
  v_enabled boolean;
  v_admission_state text;
BEGIN
  IF NEW.channel <> 'email'
    OR NEW.ticket_order_id IS NULL
    OR NEW.status NOT IN ('pending', 'processing', 'retry', 'dead')
  THEN
    RETURN NEW;
  END IF;

  SELECT ticket_order.check_in_mode, ticket_order.event_session_id,
         event_session.enabled, event_session.admission_state
  INTO v_check_in_mode, v_event_session_id, v_enabled, v_admission_state
  FROM public.ticket_orders AS ticket_order
  LEFT JOIN public.ticket_event_sessions AS event_session
    ON event_session.id = ticket_order.event_session_id
   AND event_session.environment = ticket_order.environment
   AND event_session.stripe_account_key = ticket_order.stripe_account_key
  WHERE ticket_order.id = NEW.ticket_order_id;

  IF FOUND AND v_check_in_mode = 'wallet_swipe'
    AND (
      v_event_session_id IS NULL
      OR v_enabled IS DISTINCT FROM true
      OR v_admission_state IN ('closed', 'cancelled')
    )
  THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'ticket wallet customer gate is closed';
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: guard_transactional_email_job_immutability_v29()
CREATE FUNCTION public.guard_transactional_email_job_immutability_v29() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF ROW(
      NEW.id, NEW.otp_challenge_id, NEW.ticket_order_id, NEW.purpose,
      NEW.provider_idempotency_key, NEW.recipient_email_ciphertext,
      NEW.render_data_json, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.id, OLD.otp_challenge_id, OLD.ticket_order_id, OLD.purpose,
      OLD.provider_idempotency_key, OLD.recipient_email_ciphertext,
      OLD.render_data_json, OLD.created_at
    )
  THEN
    RAISE EXCEPTION 'transactional email immutable snapshot cannot change';
  END IF;
  IF OLD.payload_hash IS NOT NULL AND NEW.payload_hash IS DISTINCT FROM OLD.payload_hash THEN
    RAISE EXCEPTION 'transactional email payload hash is write-once';
  END IF;
  IF OLD.first_send_at IS NOT NULL AND NEW.first_send_at IS DISTINCT FROM OLD.first_send_at THEN RAISE EXCEPTION 'first send clock is write-once'; END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: guarded_disable_ticket_wallet_event_session_v30(uuid, text, text, text, uuid, bigint, text)
CREATE FUNCTION public.guarded_disable_ticket_wallet_event_session_v30(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_session_id uuid, p_expected_policy_version bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_claim jsonb;
  v_response jsonb;
  v_event_day_id uuid;
  v_session public.ticket_event_sessions%ROWTYPE;
  v_before jsonb;
  v_after jsonb;
  v_obligations jsonb;
  v_obligation_total bigint;
  v_policy_audit_id uuid;
  v_audit_id uuid;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admin_users AS admin_user
    WHERE admin_user.id = p_actor_admin_id
      AND admin_user.active
      AND admin_user.role = 'owner'
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'owner_role_required');
  END IF;
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR char_length(btrim(p_request_id)) > 200
    OR NULLIF(btrim(COALESCE(p_idempotency_key, '')), '') IS NULL
    OR char_length(btrim(p_idempotency_key)) > 200
    OR NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL
    OR char_length(btrim(p_request_hash)) > 200
    OR p_event_session_id IS NULL
    OR p_expected_policy_version IS NULL OR p_expected_policy_version < 1
    OR NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL
    OR char_length(btrim(p_reason)) > 240
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'gate_disable_input_invalid');
  END IF;

  -- The durable admin idempotency row is first. A response-loss retry returns
  -- the exact stored zero-obligation receipt with only reused overlaid true.
  v_claim := public.preclaim_admin_action_request_v8(
    p_actor_admin_id, 'guarded_disable_ticket_wallet_event_session_v30',
    btrim(p_idempotency_key), btrim(p_request_hash));
  IF v_claim ->> 'action' = 'reused' THEN
    RETURN (v_claim -> 'response') || jsonb_build_object('reused', true);
  ELSIF v_claim ->> 'action' <> 'claimed' THEN
    RETURN CASE v_claim #>> '{error,code}'
      WHEN 'IDEMPOTENCY_MISMATCH' THEN jsonb_build_object(
        'action', 'conflict', 'reused', false, 'reason', 'idempotency_mismatch')
      WHEN 'IDEMPOTENCY_IN_PROGRESS' THEN jsonb_build_object(
        'action', 'conflict', 'reused', false, 'reason', 'idempotency_in_progress')
      ELSE jsonb_build_object(
        'action', 'rejected', 'reused', false, 'reason', 'gate_disable_input_invalid')
    END;
  END IF;

  PERFORM public.ticket_wallet_gate_fence_v30();
  SELECT event_session.event_day_id INTO v_event_day_id
  FROM public.ticket_event_sessions AS event_session
  WHERE event_session.id = p_event_session_id;
  IF v_event_day_id IS NULL THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'event_session_not_found',
      'serverNow', v_now);
    RETURN public.complete_ticket_wallet_gate_disable_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  -- Established acquisition order: operation -> Wallet Session -> Checkout
  -- Action -> Event Day -> Event Session -> Order -> refund -> allocation ->
  -- admission challenge -> Admission. Auth/provider phantoms are fenced above.
  PERFORM operation.id
  FROM public.ticket_admission_operations AS operation
  WHERE operation.event_session_id = p_event_session_id
  ORDER BY operation.id FOR UPDATE;
  PERFORM wallet_session.id
  FROM public.ticket_wallet_sessions AS wallet_session
  WHERE EXISTS (
    SELECT 1 FROM public.ticket_orders AS ticket_order
    WHERE ticket_order.event_session_id = p_event_session_id
      AND ticket_order.check_in_mode = 'wallet_swipe'
      AND ticket_order.environment = wallet_session.environment
      AND ticket_order.purchaser_email_hash = wallet_session.identity_email_hash)
  ORDER BY wallet_session.id FOR UPDATE;
  PERFORM checkout_action.id
  FROM public.ticket_checkout_actions AS checkout_action
  WHERE checkout_action.event_session_id = p_event_session_id
  ORDER BY checkout_action.id FOR UPDATE;
  PERFORM 1 FROM public.event_days
  WHERE id = v_event_day_id FOR NO KEY UPDATE;
  SELECT * INTO v_session
  FROM public.ticket_event_sessions
  WHERE id = p_event_session_id FOR NO KEY UPDATE;

  IF v_session.policy_version <> p_expected_policy_version THEN
    v_response := jsonb_build_object(
      'action', 'version_conflict', 'reused', false,
      'reason', 'policy_version_mismatch',
      'eventSessionId', v_session.id,
      'policyVersion', v_session.policy_version,
      'serverNow', clock_timestamp());
    RETURN public.complete_ticket_wallet_gate_disable_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;
  IF v_session.sales_check_in_mode <> 'wallet_swipe' THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'check_in_mode_mismatch',
      'eventSessionId', v_session.id, 'policyVersion', v_session.policy_version,
      'serverNow', clock_timestamp());
    RETURN public.complete_ticket_wallet_gate_disable_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;
  IF NOT v_session.enabled THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'event_session_disabled',
      'eventSessionId', v_session.id, 'policyVersion', v_session.policy_version,
      'serverNow', clock_timestamp());
    RETURN public.complete_ticket_wallet_gate_disable_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;
  IF v_session.sales_state <> 'draining' THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'begin_drain_required',
      'eventSessionId', v_session.id, 'policyVersion', v_session.policy_version,
      'serverNow', clock_timestamp());
    RETURN public.complete_ticket_wallet_gate_disable_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;
  IF v_session.admission_state <> 'scheduled' THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false,
      'reason', 'admission_state_not_scheduled',
      'eventSessionId', v_session.id, 'policyVersion', v_session.policy_version,
      'serverNow', clock_timestamp());
    RETURN public.complete_ticket_wallet_gate_disable_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  PERFORM ticket_order.id
  FROM public.ticket_orders AS ticket_order
  WHERE ticket_order.event_session_id = p_event_session_id
  ORDER BY ticket_order.id FOR UPDATE;
  PERFORM refund.id
  FROM public.ticket_refund_events AS refund
  JOIN public.ticket_orders AS ticket_order ON ticket_order.id = refund.ticket_order_id
  WHERE ticket_order.event_session_id = p_event_session_id
  ORDER BY refund.id FOR UPDATE;
  PERFORM allocation.ticket_refund_event_id
  FROM public.ticket_refund_allocations AS allocation
  JOIN public.ticket_orders AS ticket_order ON ticket_order.id = allocation.ticket_order_id
  WHERE ticket_order.event_session_id = p_event_session_id
  ORDER BY allocation.ticket_refund_event_id, allocation.admission_serial FOR UPDATE;
  PERFORM challenge.id
  FROM public.ticket_admission_challenges AS challenge
  WHERE challenge.event_session_id = p_event_session_id
  ORDER BY challenge.id FOR UPDATE;
  PERFORM admission.id
  FROM public.ticket_admissions AS admission
  JOIN public.ticket_orders AS ticket_order ON ticket_order.id = admission.ticket_order_id
  WHERE ticket_order.event_session_id = p_event_session_id
  ORDER BY admission.id FOR UPDATE;
  -- Statement-level fencing on legacy email writers guarantees that workers
  -- acquire the advisory fence before these rows. Lock them before the final
  -- count so an in-flight drain transition is either wholly before or after
  -- this zero-obligation decision.
  PERFORM job.id
  FROM public.notification_jobs AS job
  JOIN public.ticket_orders AS ticket_order ON ticket_order.id = job.ticket_order_id
  WHERE ticket_order.event_session_id = p_event_session_id
    AND ticket_order.check_in_mode = 'wallet_swipe'
    AND job.channel = 'email'
    AND job.status IN ('pending', 'processing', 'retry', 'dead')
  ORDER BY job.id FOR UPDATE OF job;
  -- Workers may clear these obligations while this function waits. Lock and
  -- then fresh-read them; new ingress is held by the provider fence trigger.
  PERFORM webhook_event.id
  FROM public.webhook_events AS webhook_event
  WHERE webhook_event.environment = v_session.environment
    AND webhook_event.processing_status IN ('received', 'processing', 'retry', 'dead')
  ORDER BY webhook_event.id FOR UPDATE;

  v_obligations := public.ticket_wallet_gate_obligations_v30(v_session.id);
  SELECT COALESCE(sum(value::text::bigint), 0)
  INTO v_obligation_total
  FROM jsonb_each(v_obligations);
  IF v_obligation_total <> 0 THEN
    v_response := jsonb_build_object(
      'action', 'blocked', 'reused', false,
      'reason', 'ticket_wallet_obligations_remaining',
      'eventSessionId', v_session.id,
      'policyVersion', v_session.policy_version,
      'obligationTotal', v_obligation_total,
      'obligations', v_obligations,
      'serverNow', clock_timestamp());
    RETURN public.complete_ticket_wallet_gate_disable_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.ticket_event_session_policy_audits AS policy_audit
    WHERE policy_audit.ticket_event_session_id = v_session.id
      AND policy_audit.request_id = btrim(p_request_id)
  ) THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'request_id_reused',
      'eventSessionId', v_session.id, 'policyVersion', v_session.policy_version,
      'serverNow', clock_timestamp());
    RETURN public.complete_ticket_wallet_gate_disable_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  v_before := jsonb_build_object(
    'salesCheckInMode', v_session.sales_check_in_mode,
    'salesState', v_session.sales_state,
    'admissionState', v_session.admission_state,
    'enabled', v_session.enabled,
    'doorAt', v_session.door_at,
    'closeAt', v_session.close_at,
    'admissionOpensAt', v_session.admission_opens_at,
    'admissionClosesAt', v_session.admission_closes_at,
    'policyVersion', v_session.policy_version);

  UPDATE public.ticket_event_sessions
  SET sales_state = 'closed',
      admission_state = 'closed',
      enabled = false,
      disabled_at = COALESCE(disabled_at, clock_timestamp()),
      policy_version = policy_version + 1,
      updated_at = clock_timestamp()
  WHERE id = v_session.id
    AND policy_version = p_expected_policy_version
  RETURNING * INTO v_session;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket Wallet gate policy CAS changed under held lock';
  END IF;

  v_after := jsonb_build_object(
    'salesCheckInMode', v_session.sales_check_in_mode,
    'salesState', v_session.sales_state,
    'admissionState', v_session.admission_state,
    'enabled', v_session.enabled,
    'doorAt', v_session.door_at,
    'closeAt', v_session.close_at,
    'admissionOpensAt', v_session.admission_opens_at,
    'admissionClosesAt', v_session.admission_closes_at,
    'policyVersion', v_session.policy_version);

  INSERT INTO public.ticket_event_session_policy_audits(
    ticket_event_session_id, actor_admin_id, request_id, reason,
    previous_policy_version, new_policy_version, before_json, after_json,
    authority_action
  ) VALUES (
    v_session.id, p_actor_admin_id, btrim(p_request_id), left(btrim(p_reason), 240),
    p_expected_policy_version, v_session.policy_version, v_before, v_after,
    'guarded_gate_disable_v30'
  ) RETURNING id INTO v_policy_audit_id;

  INSERT INTO public.audit_logs(
    action, actor_type, actor_admin_id, target_table, target_id,
    entity_type, entity_id, operation, request_id, reason, metadata_json
  ) VALUES (
    'ticket_event_session.guarded_gate_disable', 'admin', p_actor_admin_id,
    'ticket_event_sessions', v_session.id,
    'ticket_event_session', v_session.id, 'update', btrim(p_request_id),
    left(btrim(p_reason), 240),
    jsonb_build_object(
      'policyVersion', v_session.policy_version,
      'policyAuditId', v_policy_audit_id,
      'obligationTotal', 0,
      'obligations', v_obligations)
  ) RETURNING id INTO v_audit_id;

  v_response := jsonb_build_object(
    'action', 'disabled', 'reused', false,
    'eventSessionId', v_session.id,
    'policyVersion', v_session.policy_version,
    'policyAuditId', v_policy_audit_id,
    'auditLogId', v_audit_id,
    'obligationTotal', 0,
    'obligations', v_obligations,
    'salesState', v_session.sales_state,
    'admissionState', v_session.admission_state,
    'enabled', v_session.enabled,
    'serverNow', clock_timestamp());
  RETURN public.complete_ticket_wallet_gate_disable_v30(
    p_actor_admin_id, p_idempotency_key, v_response);
END;
$$;

-- FUNCTION: import_stripe_balance_transaction_v7(text, text, text, text, text, text, integer, integer, integer, jsonb)
CREATE FUNCTION public.import_stripe_balance_transaction_v7(p_environment text, p_stripe_account_id text, p_stripe_balance_transaction_id text, p_stripe_charge_id text, p_stripe_refund_id text, p_stripe_dispute_id text, p_amount_yen integer, p_fee_yen integer, p_net_yen integer, p_payload_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_balance_transaction_id uuid;
  v_payment payments%ROWTYPE;
  v_refund stripe_refunds%ROWTYPE;
  v_linked_ledger_count int := 0;
BEGIN
  INSERT INTO stripe_balance_transactions(
    environment,
    stripe_account_id,
    stripe_balance_transaction_id,
    stripe_charge_id,
    stripe_refund_id,
    stripe_dispute_id,
    amount_yen,
    fee_yen,
    net_yen,
    payload_json
  )
  VALUES (
    p_environment,
    p_stripe_account_id,
    p_stripe_balance_transaction_id,
    p_stripe_charge_id,
    p_stripe_refund_id,
    p_stripe_dispute_id,
    p_amount_yen,
    p_fee_yen,
    p_net_yen,
    COALESCE(p_payload_json, '{}'::jsonb)
  )
  ON CONFLICT (environment, stripe_account_key, stripe_balance_transaction_id)
  DO UPDATE
  SET stripe_charge_id = EXCLUDED.stripe_charge_id,
      stripe_refund_id = EXCLUDED.stripe_refund_id,
      stripe_dispute_id = EXCLUDED.stripe_dispute_id,
      amount_yen = EXCLUDED.amount_yen,
      fee_yen = EXCLUDED.fee_yen,
      net_yen = EXCLUDED.net_yen,
      payload_json = EXCLUDED.payload_json
  RETURNING id INTO v_balance_transaction_id;

  IF p_stripe_charge_id IS NOT NULL THEN
    SELECT * INTO v_payment
    FROM payments
    WHERE environment = p_environment
      AND stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND stripe_charge_id = p_stripe_charge_id
    ORDER BY created_at DESC
    LIMIT 1;

    IF FOUND THEN
      INSERT INTO ledger_entries(reservation_id, payment_id, entry_type, amount_yen, currency, stripe_balance_transaction_id)
      VALUES (
        v_payment.reservation_id,
        v_payment.id,
        CASE
          WHEN v_payment.type = 'no_show_charge' THEN 'no_show_charge_succeeded'
          WHEN v_payment.type = 'late_cancel_charge' THEN 'late_cancel_charge_succeeded'
          ELSE 'deposit_succeeded'
        END,
        v_payment.amount_yen,
        v_payment.currency,
        v_balance_transaction_id
      )
      ON CONFLICT (payment_id, entry_type)
      WHERE payment_id IS NOT NULL
        AND refund_case_id IS NULL
      DO UPDATE
      SET stripe_balance_transaction_id = EXCLUDED.stripe_balance_transaction_id;

      GET DIAGNOSTICS v_linked_ledger_count = ROW_COUNT;
    END IF;
  END IF;

  IF p_stripe_refund_id IS NOT NULL THEN
    SELECT * INTO v_refund
    FROM stripe_refunds
    WHERE environment = p_environment
      AND stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND stripe_refund_id = p_stripe_refund_id
    ORDER BY created_at DESC
    LIMIT 1;

    IF FOUND THEN
      INSERT INTO ledger_entries(reservation_id, payment_id, refund_case_id, entry_type, amount_yen, currency, stripe_balance_transaction_id)
      VALUES (
        v_refund.reservation_id,
        v_refund.payment_id,
        v_refund.refund_case_id,
        'refund_succeeded',
        -v_refund.amount_yen,
        'jpy',
        v_balance_transaction_id
      )
      ON CONFLICT (refund_case_id, entry_type)
      WHERE refund_case_id IS NOT NULL
      DO UPDATE
      SET stripe_balance_transaction_id = EXCLUDED.stripe_balance_transaction_id;

      GET DIAGNOSTICS v_linked_ledger_count = ROW_COUNT;
    END IF;
  END IF;

  IF p_stripe_dispute_id IS NOT NULL THEN
    INSERT INTO ledger_entries(entry_type, amount_yen, stripe_balance_transaction_id)
    SELECT 'dispute_adjustment', p_amount_yen, v_balance_transaction_id
    WHERE NOT EXISTS (
      SELECT 1
      FROM ledger_entries le
      WHERE le.stripe_balance_transaction_id = v_balance_transaction_id
        AND le.entry_type = 'dispute_adjustment'
    );

    GET DIAGNOSTICS v_linked_ledger_count = ROW_COUNT;
  END IF;

  RETURN jsonb_build_object(
    'balanceTransactionId', v_balance_transaction_id,
    'stripeBalanceTransactionId', p_stripe_balance_transaction_id,
    'linkedLedgerCount', v_linked_ledger_count
  );
END;
$$;

-- FUNCTION: import_stripe_balance_transaction_v8(text, text, text, text, text, text, integer, integer, integer, jsonb)
CREATE FUNCTION public.import_stripe_balance_transaction_v8(p_environment text, p_stripe_account_id text, p_stripe_balance_transaction_id text, p_stripe_charge_id text, p_stripe_refund_id text, p_stripe_dispute_id text, p_amount_yen integer, p_fee_yen integer, p_net_yen integer, p_payload_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_balance_transaction_id uuid;
  v_payment payments%ROWTYPE;
  v_refund stripe_refunds%ROWTYPE;
  v_dispute stripe_disputes%ROWTYPE;
  v_linked_ledger_count int := 0;
  v_currency text := lower(NULLIF(btrim(COALESCE(p_payload_json ->> 'currency', '')), ''));
  v_type text := NULLIF(btrim(COALESCE(p_payload_json ->> 'type', '')), '');
  v_pi text := NULL;
  v_domain text := NULL;
BEGIN
  -- Resolve the PaymentIntent for domain classification:
  --  * charge txns: via the PI-succeeded webhook payload (latest_charge) or a
  --    payment_intent watermark row, then payments/ticket_orders.
  --  * refund txns: via the stripe_refunds row (VIP) or ticket refund tables.
  --  * dispute txns: via the stripe_disputes row.
  IF p_stripe_charge_id IS NOT NULL THEN
    SELECT * INTO v_payment
    FROM payments
    WHERE environment = p_environment
      AND stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND stripe_charge_id = p_stripe_charge_id
    ORDER BY created_at DESC
    LIMIT 1;
    IF FOUND THEN
      v_pi := v_payment.provider_object_id;
    END IF;
    IF v_pi IS NULL THEN
      SELECT we.payload_json #>> '{data,object,id}' INTO v_pi
      FROM webhook_events we
      WHERE we.environment = p_environment
        AND we.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
        AND we.event_type = 'payment_intent.succeeded'
        AND we.payload_json #>> '{data,object,latest_charge}' = p_stripe_charge_id
      ORDER BY we.created_at DESC
      LIMIT 1;
    END IF;
    IF v_pi IS NULL THEN
      SELECT sos.payload_json ->> 'payment_intent' INTO v_pi
      FROM stripe_object_states sos
      WHERE sos.environment = p_environment
        AND sos.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
        AND sos.object_type = 'charge'
        AND sos.object_id = p_stripe_charge_id
      LIMIT 1;
    END IF;
  END IF;

  IF p_stripe_refund_id IS NOT NULL THEN
    SELECT * INTO v_refund
    FROM stripe_refunds
    WHERE environment = p_environment
      AND stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND stripe_refund_id = p_stripe_refund_id
    ORDER BY created_at DESC
    LIMIT 1;
    IF FOUND THEN
      SELECT p.provider_object_id INTO v_pi FROM payments p WHERE p.id = v_refund.payment_id;
    END IF;
    IF v_pi IS NULL THEN
      SELECT sos.payload_json ->> 'payment_intent' INTO v_pi
      FROM stripe_object_states sos
      WHERE sos.environment = p_environment
        AND sos.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
        AND sos.object_type = 'refund'
        AND sos.object_id = p_stripe_refund_id
      LIMIT 1;
    END IF;
  END IF;

  IF p_stripe_dispute_id IS NOT NULL THEN
    SELECT * INTO v_dispute
    FROM stripe_disputes
    WHERE environment = p_environment
      AND stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
      AND stripe_dispute_id = p_stripe_dispute_id
    ORDER BY created_at DESC
    LIMIT 1;
    IF FOUND THEN
      v_pi := v_dispute.stripe_payment_intent_id;
    END IF;
    IF v_pi IS NULL THEN
      SELECT sos.payload_json ->> 'payment_intent' INTO v_pi
      FROM stripe_object_states sos
      WHERE sos.environment = p_environment
        AND sos.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
        AND sos.object_type = 'dispute'
        AND sos.object_id = p_stripe_dispute_id
      LIMIT 1;
    END IF;
  END IF;

  v_domain := CASE
    WHEN v_payment.id IS NOT NULL THEN 'vip'
    WHEN v_refund.id IS NOT NULL THEN 'vip'
    WHEN v_dispute.id IS NOT NULL AND v_dispute.payment_id IS NOT NULL THEN 'vip'
    WHEN v_pi IS NOT NULL AND EXISTS (
      SELECT 1 FROM payments p
      WHERE p.environment = p_environment
        AND p.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
        AND p.provider_object_type = 'payment_intent'
        AND p.provider_object_id = v_pi
    ) THEN 'vip'
    WHEN v_pi IS NOT NULL AND EXISTS (
      SELECT 1 FROM ticket_orders o
      WHERE o.environment = p_environment
        AND o.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
        AND o.payment_intent_id = v_pi
    ) THEN 'ticket'
    WHEN p_stripe_refund_id IS NOT NULL AND (
      EXISTS (SELECT 1 FROM ticket_refund_allocations a
              WHERE a.environment = p_environment
                AND a.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
                AND a.stripe_refund_id = p_stripe_refund_id)
      OR EXISTS (SELECT 1 FROM ticket_refund_observations o
              JOIN ticket_refund_events e ON e.id = o.ticket_refund_event_id
              WHERE e.environment = p_environment
                AND e.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
                AND e.stripe_refund_id = p_stripe_refund_id)
    ) THEN 'ticket'
    ELSE 'unclassified'
  END;

  INSERT INTO stripe_balance_transactions(
    environment,
    stripe_account_id,
    stripe_balance_transaction_id,
    stripe_charge_id,
    stripe_refund_id,
    stripe_dispute_id,
    amount_yen,
    fee_yen,
    net_yen,
    currency,
    transaction_type,
    stripe_payment_intent_id,
    reporting_domain,
    payload_json
  )
  VALUES (
    p_environment,
    p_stripe_account_id,
    p_stripe_balance_transaction_id,
    p_stripe_charge_id,
    p_stripe_refund_id,
    p_stripe_dispute_id,
    p_amount_yen,
    p_fee_yen,
    p_net_yen,
    v_currency,
    v_type,
    v_pi,
    v_domain,
    COALESCE(p_payload_json, '{}'::jsonb)
  )
  ON CONFLICT (environment, stripe_account_key, stripe_balance_transaction_id)
  DO UPDATE
  SET stripe_charge_id = EXCLUDED.stripe_charge_id,
      stripe_refund_id = EXCLUDED.stripe_refund_id,
      stripe_dispute_id = EXCLUDED.stripe_dispute_id,
      amount_yen = EXCLUDED.amount_yen,
      fee_yen = EXCLUDED.fee_yen,
      net_yen = EXCLUDED.net_yen,
      currency = EXCLUDED.currency,
      transaction_type = EXCLUDED.transaction_type,
      stripe_payment_intent_id = EXCLUDED.stripe_payment_intent_id,
      reporting_domain = EXCLUDED.reporting_domain,
      payload_json = EXCLUDED.payload_json
  RETURNING id INTO v_balance_transaction_id;

  -- Unclassified money movement is a divergence source; never drop it.
  -- W08/v75: the allowlist now includes every Stripe reporting type observed
  -- queueing zero reviews (payout, contribution, stripe_fee, transfer, topup).
  IF v_domain = 'unclassified' AND COALESCE(v_type, '') IN (
    'charge','refund','dispute','adjustment',
    'payout','contribution','stripe_fee','transfer','topup'
  ) THEN
    INSERT INTO public.external_finance_reviews(
      environment, stripe_account_id, event_kind, provider_object_id,
      amount_yen, currency, reason, payload_json
    ) VALUES (
      p_environment, p_stripe_account_id, 'unclassified_balance_transaction',
      p_stripe_balance_transaction_id, p_amount_yen, COALESCE(v_currency, 'jpy'),
      'domain_unresolved', COALESCE(p_payload_json, '{}'::jsonb)
    )
    ON CONFLICT (environment, stripe_account_key, event_kind, provider_object_id, reason)
    DO UPDATE SET payload_json = EXCLUDED.payload_json, updated_at = now();
  END IF;

  IF p_stripe_charge_id IS NOT NULL AND v_payment.id IS NOT NULL THEN
    INSERT INTO ledger_entries(reservation_id, payment_id, entry_type, amount_yen, currency, stripe_balance_transaction_id)
    VALUES (
      v_payment.reservation_id,
      v_payment.id,
      CASE
        WHEN v_payment.type = 'no_show_charge' THEN 'no_show_charge_succeeded'
        WHEN v_payment.type = 'late_cancel_charge' THEN 'late_cancel_charge_succeeded'
        ELSE 'deposit_succeeded'
      END,
      v_payment.amount_yen,
      v_payment.currency,
      v_balance_transaction_id
    )
    ON CONFLICT (payment_id, entry_type)
    WHERE payment_id IS NOT NULL
      AND refund_case_id IS NULL
    DO UPDATE
    SET stripe_balance_transaction_id = EXCLUDED.stripe_balance_transaction_id;

    GET DIAGNOSTICS v_linked_ledger_count = ROW_COUNT;
  END IF;

  IF p_stripe_refund_id IS NOT NULL AND v_refund.id IS NOT NULL THEN
    -- Case-less (external) refunds have no refund_case_id; their ledger rows
    -- are keyed on the provider refund id and keep payment_id NULL so the
    -- legacy (payment_id, entry_type) partial index cannot collapse two
    -- distinct refunds on the same payment.
    INSERT INTO ledger_entries(reservation_id, payment_id, refund_case_id, entry_type, amount_yen, currency, stripe_balance_transaction_id, stripe_refund_id)
    VALUES (
      v_refund.reservation_id,
      CASE WHEN v_refund.refund_case_id IS NULL THEN NULL ELSE v_refund.payment_id END,
      v_refund.refund_case_id,
      'refund_succeeded',
      -v_refund.amount_yen,
      'jpy',
      v_balance_transaction_id,
      p_stripe_refund_id
    )
    ON CONFLICT DO NOTHING;

    -- v7-era ledger rows carry only refund_case_id; match through the case's
    -- bound provider refund id as well as the direct column.
    UPDATE ledger_entries le
    SET stripe_balance_transaction_id = v_balance_transaction_id
    WHERE le.stripe_balance_transaction_id IS NULL
      AND (
        le.stripe_refund_id = p_stripe_refund_id
        OR EXISTS (
          SELECT 1 FROM refund_cases rc
          WHERE rc.id = le.refund_case_id
            AND rc.stripe_refund_id = p_stripe_refund_id
        )
      );

    SELECT count(*)::int INTO v_linked_ledger_count
    FROM ledger_entries le
    WHERE le.stripe_refund_id = p_stripe_refund_id
       OR EXISTS (
         SELECT 1 FROM refund_cases rc
         WHERE rc.id = le.refund_case_id
           AND rc.stripe_refund_id = p_stripe_refund_id
       );
  END IF;

  IF p_stripe_dispute_id IS NOT NULL THEN
    INSERT INTO ledger_entries(reservation_id, entry_type, amount_yen, currency, stripe_balance_transaction_id, stripe_dispute_id)
    SELECT v_dispute.reservation_id, 'dispute_adjustment', p_amount_yen, 'jpy', v_balance_transaction_id, p_stripe_dispute_id
    WHERE v_dispute.id IS NOT NULL
    ON CONFLICT DO NOTHING;

    IF NOT FOUND OR v_dispute.id IS NULL THEN
      INSERT INTO ledger_entries(entry_type, amount_yen, currency, stripe_balance_transaction_id, stripe_dispute_id)
      SELECT 'dispute_adjustment', p_amount_yen, 'jpy', v_balance_transaction_id, p_stripe_dispute_id
      WHERE NOT EXISTS (
        SELECT 1
        FROM ledger_entries le
        WHERE le.stripe_balance_transaction_id = v_balance_transaction_id
          AND le.entry_type = 'dispute_adjustment'
      )
      ON CONFLICT DO NOTHING;
    END IF;

    SELECT count(*)::int INTO v_linked_ledger_count
    FROM ledger_entries
    WHERE stripe_balance_transaction_id = v_balance_transaction_id
      AND entry_type = 'dispute_adjustment';
  END IF;

  RETURN jsonb_build_object(
    'balanceTransactionId', v_balance_transaction_id,
    'stripeBalanceTransactionId', p_stripe_balance_transaction_id,
    'linkedLedgerCount', v_linked_ledger_count,
    'reportingDomain', v_domain,
    'currency', v_currency,
    'stripePaymentIntentId', v_pi
  );
END;
$$;

-- FUNCTION: list_reconciliation_differences_v8(text, text, timestamp with time zone, timestamp with time zone, boolean, integer)
CREATE FUNCTION public.list_reconciliation_differences_v8(p_environment text DEFAULT NULL::text, p_stripe_account_id text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_scope_all boolean DEFAULT false, p_limit integer DEFAULT 200) RETURNS TABLE(kind text, ref_id text, amount_yen bigint, detail jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF COALESCE(p_scope_all, false) IS DISTINCT FROM true
    AND NULLIF(btrim(COALESCE(p_environment, '')), '') IS NULL THEN
    RAISE EXCEPTION 'reconciliation_environment_scope_required';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 500 THEN
    RAISE EXCEPTION 'invalid difference listing bound';
  END IF;

  RETURN QUERY
  SELECT * FROM (
    -- VIP ledger entries not yet reconciled to a balance transaction.
    SELECT 'ledger_unlinked'::text AS kind, le.id::text AS ref_id, le.amount_yen::bigint,
           jsonb_build_object(
             'entryType', le.entry_type, 'reservationId', le.reservation_id,
             'paymentId', le.payment_id, 'refundCaseId', le.refund_case_id,
             'stripeRefundId', le.stripe_refund_id, 'stripeDisputeId', le.stripe_dispute_id,
             'createdAt', le.created_at
           ) AS detail
    FROM ledger_entries le
    LEFT JOIN payments pay ON pay.id = le.payment_id
    LEFT JOIN stripe_refunds srf ON srf.stripe_refund_id = le.stripe_refund_id
    LEFT JOIN stripe_disputes sd ON sd.stripe_dispute_id = le.stripe_dispute_id
    LEFT JOIN stripe_balance_transactions sbt ON sbt.id = le.stripe_balance_transaction_id
    WHERE le.stripe_balance_transaction_id IS NULL
      AND le.amount_yen <> 0
      AND (COALESCE(p_scope_all, false) OR
           COALESCE(pay.environment, srf.environment, sd.environment, sbt.environment) = p_environment)
      AND (p_stripe_account_id IS NULL OR
           COALESCE(pay.stripe_account_key, srf.stripe_account_key, sd.stripe_account_key, sbt.stripe_account_key)
             = COALESCE(p_stripe_account_id, 'platform'))
      AND (p_from IS NULL OR le.created_at >= p_from)
      AND (p_to IS NULL OR le.created_at < p_to)
    UNION ALL
    -- VIP-domain balance transactions with no ledger entry at all.
    SELECT 'stripe_unlinked'::text, sbt.id::text, sbt.amount_yen::bigint,
           jsonb_build_object(
             'stripeBalanceTransactionId', sbt.stripe_balance_transaction_id,
             'transactionType', sbt.transaction_type, 'currency', sbt.currency,
             'stripeChargeId', sbt.stripe_charge_id, 'stripeRefundId', sbt.stripe_refund_id,
             'stripeDisputeId', sbt.stripe_dispute_id, 'createdAt', sbt.created_at
           )
    FROM stripe_balance_transactions sbt
    WHERE sbt.reporting_domain = 'vip'
      AND NOT EXISTS (SELECT 1 FROM ledger_entries le WHERE le.stripe_balance_transaction_id = sbt.id)
      AND (COALESCE(p_scope_all, false) OR sbt.environment = p_environment)
      AND (p_stripe_account_id IS NULL OR sbt.stripe_account_key = COALESCE(p_stripe_account_id, 'platform'))
      AND (p_from IS NULL OR sbt.created_at >= p_from)
      AND (p_to IS NULL OR sbt.created_at < p_to)
    UNION ALL
    -- Open exception queue items inside this scope.
    SELECT 'review_open'::text, r.id::text, r.amount_yen,
           jsonb_build_object(
             'eventKind', r.event_kind, 'providerObjectId', r.provider_object_id,
             'reason', r.reason, 'paymentId', r.payment_id, 'reservationId', r.reservation_id,
             'createdAt', r.created_at
           )
    FROM external_finance_reviews r
    WHERE r.status = 'review_required'
      AND (COALESCE(p_scope_all, false) OR r.environment = p_environment)
      AND (p_stripe_account_id IS NULL OR r.stripe_account_key = COALESCE(p_stripe_account_id, 'platform'))
  ) diffs
  ORDER BY diffs.kind, diffs.ref_id
  LIMIT p_limit;
END;
$$;

-- FUNCTION: list_ticket_checkout_review_queue_v1(text, integer)
CREATE FUNCTION public.list_ticket_checkout_review_queue_v1(p_environment text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_items jsonb;
BEGIN
  IF COALESCE(p_environment, '') NOT IN ('test', 'live')
    OR NOT (p_limit BETWEEN 1 AND 200)
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'queue_input_invalid');
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'checkoutActionId', action.id,
    'orderId', ticket_order.id,
    'publicCode', ticket_order.public_code,
    'orderStatus', ticket_order.status,
    'orderAmountYen', ticket_order.amount_yen,
    'totalQuantity', ticket_order.total_quantity,
    'eventId', ticket_order.event_id,
    'eventDate', ticket_order.event_date,
    'checkInMode', action.check_in_mode,
    'eventSessionId', action.event_session_id,
    'environment', action.environment,
    'stripeAccountId', action.stripe_account_id,
    'stripeAccountKey', action.stripe_account_key,
    'reviewReason', action.review_reason,
    'lastOutcome', action.recovery_last_outcome,
    'checkoutSessionId', action.checkout_session_id,
    'providerExpiresAt', CASE WHEN action.provider_expires_at IS NULL
      THEN NULL ELSE to_char(action.provider_expires_at AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
    'providerEvidenceHash', action.provider_terminal_evidence_hash,
    'providerObservedAt', CASE WHEN action.provider_terminal_observed_at IS NULL
      THEN NULL ELSE to_char(action.provider_terminal_observed_at AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
    'conflictCount', action.conflict_count,
    'reconciliationCount', action.reconciliation_count,
    'createdAt', to_char(action.created_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'reviewEnteredAt', to_char(action.updated_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'deadlineAt', to_char((action.updated_at + interval '4 hours') AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'slaBreached', action.updated_at + interval '4 hours' <= v_now
  ) ORDER BY action.updated_at, action.id), '[]'::jsonb)
  INTO v_items
  FROM (
    SELECT * FROM public.ticket_checkout_actions
    WHERE state = 'review_required'
      AND environment = p_environment
    ORDER BY updated_at, id
    LIMIT p_limit
  ) AS action
  JOIN public.ticket_orders AS ticket_order
    ON ticket_order.id = action.ticket_order_id;

  RETURN jsonb_build_object(
    'action', 'listed',
    'count', COALESCE(jsonb_array_length(v_items), 0),
    'items', v_items,
    'serverNow', to_char(v_now AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
END;
$$;

-- FUNCTION: lock_ticket_order_entry_v52(uuid)
CREATE FUNCTION public.lock_ticket_order_entry_v52(p_order uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o public.ticket_orders%ROWTYPE; e public.ticket_event_sessions%ROWTYPE; d public.event_days%ROWTYPE;
BEGIN
 PERFORM public.ticket_wallet_gate_fence_v30();
 SELECT * INTO o FROM public.ticket_orders WHERE id=p_order;
 IF NOT FOUND THEN RETURN jsonb_build_object('error','not_found'); END IF;
 SELECT * INTO e FROM public.ticket_event_sessions WHERE id=o.event_session_id;
 SELECT * INTO d FROM public.event_days WHERE id=e.event_day_id FOR NO KEY UPDATE;
 SELECT * INTO e FROM public.ticket_event_sessions WHERE id=e.id FOR NO KEY UPDATE;
 SELECT * INTO o FROM public.ticket_orders WHERE id=p_order FOR UPDATE;
 PERFORM id FROM public.ticket_refund_events WHERE ticket_order_id=o.id ORDER BY created_at,id FOR UPDATE;
 PERFORM id FROM public.ticket_refund_allocations WHERE ticket_order_id=o.id ORDER BY admission_serial,id FOR UPDATE;
 IF o.admission_policy<>'order_together_v1' OR o.check_in_mode<>'wallet_swipe'
  OR o.environment<>e.environment OR o.stripe_account_key<>e.stripe_account_key OR o.event_id<>e.catalog_event_id
  OR o.event_date<>e.event_date OR d.business_date<>e.event_date THEN RETURN jsonb_build_object('error','authority_binding_mismatch'); END IF;
 IF d.operating_status<>'open' OR NOT e.enabled OR e.admission_state<>'scheduled' THEN RETURN jsonb_build_object('error','event_session_closed'); END IF;
 IF clock_timestamp()<public.ticket_admission_execution_opens_v56(e.id) THEN RETURN jsonb_build_object('error','admission_not_open'); END IF;
 IF clock_timestamp()>=public.ticket_admission_execution_closes_v56(e.id) THEN RETURN jsonb_build_object('error','admission_window_closed'); END IF;
 IF NOT public.ticket_order_has_settled_payment_v30(o.id) THEN RETURN jsonb_build_object('error','payment_not_settled'); END IF;
 IF EXISTS(SELECT 1 FROM public.ticket_refund_events WHERE ticket_order_id=o.id AND money_may_have_moved
  AND resolution_status IN ('review_required','conflict_review') AND resolved_at IS NULL)
 THEN RETURN jsonb_build_object('error','refund_review_required'); END IF;
 RETURN jsonb_build_object('version',o.admission_version,'policyVersion',e.policy_version,'eventTitle',o.event_title,'eventDate',o.event_date,'eventSessionId',e.id);
END $$;


SET default_tablespace = '';

SET default_table_access_method = heap;

-- TABLE: transactional_email_jobs
CREATE TABLE public.transactional_email_jobs (
    id uuid NOT NULL,
    otp_challenge_id uuid,
    purpose text DEFAULT 'ticket_wallet_otp'::text NOT NULL,
    provider_name text,
    provider_idempotency_key text NOT NULL,
    provider_message_id text,
    recipient_email_hash text,
    recipient_email_ciphertext bytea NOT NULL,
    render_data_json jsonb NOT NULL,
    payload_hash text,
    state text DEFAULT 'pending'::text NOT NULL,
    provider_delivery_state text DEFAULT 'pending'::text NOT NULL,
    provider_state_precedence integer DEFAULT 0 NOT NULL,
    provider_state_occurred_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    maximum_attempts integer DEFAULT 8 NOT NULL,
    next_attempt_at timestamp with time zone NOT NULL,
    claimed_by uuid,
    claim_token uuid,
    claimed_at timestamp with time zone,
    lease_expires_at timestamp with time zone,
    accepted_at timestamp with time zone,
    completed_at timestamp with time zone,
    terminal_at timestamp with time zone,
    safe_error_category text,
    manager_recovery_count integer DEFAULT 0 NOT NULL,
    last_manager_recovery_at timestamp with time zone,
    entity_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    ticket_order_id uuid,
    first_send_at timestamp with time zone,
    CONSTRAINT transactional_email_job_subject_v33 CHECK ((((purpose = 'ticket_wallet_otp'::text) AND (otp_challenge_id IS NOT NULL) AND (ticket_order_id IS NULL)) OR ((purpose = 'ticket_wallet_purchase'::text) AND (otp_challenge_id IS NULL) AND (ticket_order_id IS NOT NULL)))),
    CONSTRAINT transactional_email_jobs_attempt_check_v29 CHECK ((((attempt_count >= 0) AND (attempt_count <= maximum_attempts)) AND ((maximum_attempts >= 1) AND (maximum_attempts <= 20)))),
    CONSTRAINT transactional_email_jobs_claim_shape_v29 CHECK ((((state = 'processing'::text) AND (claimed_by IS NOT NULL) AND (claim_token IS NOT NULL) AND (claimed_at IS NOT NULL) AND (lease_expires_at IS NOT NULL)) OR ((state <> 'processing'::text) AND (claimed_by IS NULL) AND (claim_token IS NULL) AND (claimed_at IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT transactional_email_jobs_delivery_check_v29 CHECK (((provider_delivery_state = ANY (ARRAY['pending'::text, 'accepted'::text, 'delayed'::text, 'delivered'::text, 'failed'::text, 'bounced'::text, 'complained'::text, 'suppressed'::text, 'unknown'::text])) AND ((provider_state_precedence >= 0) AND (provider_state_precedence <= 100)))),
    CONSTRAINT transactional_email_jobs_idempotency_check_v29 CHECK ((((char_length(provider_idempotency_key) >= 1) AND (char_length(provider_idempotency_key) <= 256)) AND (provider_idempotency_key ~ '^[A-Za-z0-9._:/-]+$'::text))),
    CONSTRAINT transactional_email_jobs_payload_hash_check_v29 CHECK (((payload_hash IS NULL) OR (payload_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT transactional_email_jobs_provider_check_v29 CHECK (((provider_name IS NULL) OR (provider_name = ANY (ARRAY['fake'::text, 'resend'::text])))),
    CONSTRAINT transactional_email_jobs_provider_message_check_v29 CHECK (((provider_message_id IS NULL) OR (((char_length(provider_message_id) >= 1) AND (char_length(provider_message_id) <= 256)) AND (provider_message_id !~ '[\r\n]'::text)))),
    CONSTRAINT transactional_email_jobs_recipient_check_v29 CHECK ((((recipient_email_hash IS NULL) OR ((char_length(recipient_email_hash) >= 16) AND (char_length(recipient_email_hash) <= 256))) AND ((octet_length(recipient_email_ciphertext) >= 2) AND (octet_length(recipient_email_ciphertext) <= 8192)))),
    CONSTRAINT transactional_email_jobs_recovery_check_v29 CHECK (((manager_recovery_count >= 0) AND (((manager_recovery_count = 0) AND (last_manager_recovery_at IS NULL)) OR ((manager_recovery_count > 0) AND (last_manager_recovery_at IS NOT NULL))))),
    CONSTRAINT transactional_email_jobs_render_check_v33 CHECK ((((purpose = 'ticket_wallet_otp'::text) AND ((jsonb_typeof(render_data_json) = 'object'::text) AND ((render_data_json ->> 'template'::text) = 'ticket_wallet_otp'::text) AND ((render_data_json ->> 'templateVersion'::text) = 'ghost.ticket-wallet-otp.v1'::text) AND (NULLIF((render_data_json ->> 'notificationJobId'::text), ''::text) IS NOT NULL) AND (NULLIF((render_data_json ->> 'renderReferenceAt'::text), ''::text) IS NOT NULL) AND (NULLIF((render_data_json ->> 'expiresAt'::text), ''::text) IS NOT NULL) AND (NULLIF((render_data_json ->> 'from'::text), ''::text) IS NOT NULL) AND (NULLIF((render_data_json ->> 'walletUrl'::text), ''::text) IS NOT NULL) AND ((render_data_json -> 'tags'::text) = jsonb_build_array(jsonb_build_object('name', 'purpose', 'value', 'ticket_wallet_otp'), jsonb_build_object('name', 'notification_job_id', 'value', (render_data_json ->> 'notificationJobId'::text)))) AND (NOT (render_data_json ? 'otp'::text)) AND (NOT (render_data_json ? 'recipient'::text)))) OR ((purpose = 'ticket_wallet_purchase'::text) AND ((render_data_json ->> 'template'::text) = 'ticket_wallet_purchase'::text) AND ((render_data_json ->> 'templateVersion'::text) = ANY (ARRAY['ghost.ticket-wallet-purchase.v1'::text, 'ghost.ticket-wallet-purchase.v2'::text])) AND ((render_data_json ->> 'notificationJobId'::text) = (id)::text) AND (NULLIF((render_data_json ->> 'renderReferenceAt'::text), ''::text) IS NOT NULL) AND (NULLIF((render_data_json ->> 'expiresAt'::text), ''::text) IS NOT NULL) AND (NULLIF((render_data_json ->> 'from'::text), ''::text) IS NOT NULL) AND (NULLIF((render_data_json ->> 'walletUrl'::text), ''::text) IS NOT NULL) AND (NOT (render_data_json ? 'otp'::text)) AND (NOT (render_data_json ? 'recipient'::text))))),
    CONSTRAINT transactional_email_jobs_state_check_v29 CHECK ((state = ANY (ARRAY['pending'::text, 'processing'::text, 'retry'::text, 'accepted'::text, 'dead'::text, 'configuration'::text, 'cancelled'::text]))),
    CONSTRAINT transactional_email_jobs_terminal_shape_v29 CHECK ((((state = ANY (ARRAY['dead'::text, 'configuration'::text, 'cancelled'::text])) AND (terminal_at IS NOT NULL)) OR ((state <> ALL (ARRAY['dead'::text, 'configuration'::text, 'cancelled'::text])) AND (terminal_at IS NULL)))),
    CONSTRAINT transactional_email_jobs_version_check_v29 CHECK ((entity_version > 0))
);

ALTER TABLE ONLY public.transactional_email_jobs FORCE ROW LEVEL SECURITY;

-- FUNCTION: lock_transactional_email_job_v33(uuid)
CREATE FUNCTION public.lock_transactional_email_job_v33(p_id uuid) RETURNS SETOF public.transactional_email_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c uuid; o uuid;
BEGIN
 SELECT otp_challenge_id,ticket_order_id INTO c,o FROM public.transactional_email_jobs WHERE id=p_id;
 IF c IS NOT NULL THEN PERFORM 1 FROM public.ticket_wallet_otp_challenges WHERE id=c FOR UPDATE;
 ELSIF o IS NOT NULL THEN PERFORM 1 FROM public.ticket_orders WHERE id=o FOR UPDATE;
 ELSE RETURN; END IF;
 RETURN QUERY SELECT * FROM public.transactional_email_jobs WHERE id=p_id FOR UPDATE;
END; $$;

-- FUNCTION: lock_vip_floor_day_revision_v32(uuid)
CREATE FUNCTION public.lock_vip_floor_day_revision_v32(p_event_day_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.vip_floor_day_revisions(event_day_id, revision)
  VALUES (p_event_day_id, 0)
  ON CONFLICT (event_day_id) DO NOTHING;
  PERFORM revision FROM public.vip_floor_day_revisions
  WHERE event_day_id = p_event_day_id FOR UPDATE;
END;
$$;

-- FUNCTION: manager_admit_ticket_admissions_v30(uuid, text, text, text, text, uuid, uuid, uuid[], bigint, text)
CREATE FUNCTION public.manager_admit_ticket_admissions_v30(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_environment text, p_event_session_id uuid, p_ticket_order_id uuid, p_admission_ids uuid[], p_expected_version bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_claim jsonb;
  v_response jsonb;
  v_result jsonb;
  v_admission_ids uuid[];
  v_input_count integer;
  v_distinct_count integer;
  v_candidate record;
  v_operation public.ticket_admission_operations%ROWTYPE;
  v_event_day public.event_days%ROWTYPE;
  v_event_session public.ticket_event_sessions%ROWTYPE;
  v_ticket_order public.ticket_orders%ROWTYPE;
  v_selected integer := 0;
  v_issued integer := 0;
  v_admitted integer := 0;
  v_void integer := 0;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_committed_order_version bigint;
  v_error_code text;
  v_audit_id uuid;
BEGIN
  SELECT
    COALESCE(array_agg(admission_id ORDER BY admission_id), '{}'::uuid[]),
    count(*)::integer,
    count(DISTINCT admission_id)::integer
  INTO v_admission_ids, v_input_count, v_distinct_count
  FROM unnest(COALESCE(p_admission_ids, '{}'::uuid[])) AS selected(admission_id);

  IF p_actor_admin_id IS NULL
    OR NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR char_length(p_request_id) > 200
    OR NULLIF(btrim(COALESCE(p_idempotency_key, '')), '') IS NULL
    OR char_length(p_idempotency_key) > 200
    OR NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL
    OR char_length(p_request_hash) > 200
    OR COALESCE(p_environment, '') NOT IN ('test', 'live')
    OR p_event_session_id IS NULL
    OR p_ticket_order_id IS NULL
    OR p_expected_version IS NULL OR p_expected_version < 1
    OR NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL
    OR char_length(btrim(p_reason)) > 240
    OR v_input_count NOT BETWEEN 1 AND 20
    OR v_distinct_count <> v_input_count
    OR array_position(v_admission_ids, NULL) IS NOT NULL
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reused', false,
      'reason', 'manager_admission_invalid');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.admin_users AS admin_user
    WHERE admin_user.id = p_actor_admin_id
      AND admin_user.active
      AND admin_user.role = 'owner'
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reused', false,
      'reason', 'owner_role_required');
  END IF;

  -- admin_action_requests is the first serialization row for every Owner retry.
  v_claim := public.preclaim_admin_action_request_v8(
    p_actor_admin_id, 'manager_admit_ticket_admissions_v30',
    btrim(p_idempotency_key), btrim(p_request_hash));
  IF v_claim ->> 'action' = 'reused' THEN
    RETURN jsonb_set(
      v_claim -> 'response', '{reused}', 'true'::jsonb, true);
  ELSIF v_claim ->> 'action' <> 'claimed' THEN
    RETURN CASE v_claim #>> '{error,code}'
      WHEN 'IDEMPOTENCY_MISMATCH' THEN jsonb_build_object(
        'action', 'conflict', 'reused', false,
        'reason', 'idempotency_mismatch')
      WHEN 'IDEMPOTENCY_IN_PROGRESS' THEN jsonb_build_object(
        'action', 'conflict', 'reused', false,
        'reason', 'idempotency_in_progress')
      WHEN 'INVALID_COMMAND' THEN jsonb_build_object(
        'action', 'rejected', 'reused', false,
        'reason', 'input_invalid')
      ELSE jsonb_build_object(
        'action', 'rejected', 'reused', false,
        'reason', 'manager_action_claim_failed')
    END;
  END IF;

  -- Hold the Owner row after the action claim so deactivation cannot race the
  -- bounded recovery mutation.
  PERFORM 1 FROM public.admin_users AS admin_user
  WHERE admin_user.id = p_actor_admin_id
    AND admin_user.active
    AND admin_user.role = 'owner'
  FOR KEY SHARE;
  IF NOT FOUND THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'owner_role_required');
    RETURN public.complete_ticket_manager_admission_action_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  -- Candidate facts let the Operation row be created first. They are re-read
  -- only after the Operation -> Event Day -> Event Session -> Order locks.
  SELECT
    ticket_order.event_session_id,
    event_session.event_day_id,
    ticket_order.environment,
    ticket_order.stripe_account_id,
    ticket_order.check_in_mode,
    event_session.policy_version,
    ticket_order.event_title,
    ticket_order.event_date
  INTO v_candidate
  FROM public.ticket_orders AS ticket_order
  JOIN public.ticket_event_sessions AS event_session
    ON event_session.id = ticket_order.event_session_id
   AND event_session.environment = ticket_order.environment
   AND event_session.stripe_account_key = ticket_order.stripe_account_key
  WHERE ticket_order.id = p_ticket_order_id;

  IF NOT FOUND
    OR v_candidate.event_session_id <> p_event_session_id
    OR v_candidate.environment <> p_environment
    OR v_candidate.check_in_mode <> 'wallet_swipe'
  THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false,
      'reason', CASE WHEN NOT FOUND THEN 'order_not_found'
        WHEN v_candidate.environment <> p_environment THEN 'environment_mismatch'
        WHEN v_candidate.check_in_mode <> 'wallet_swipe' THEN 'wallet_order_required'
        ELSE 'event_session_mismatch' END);
    RETURN public.complete_ticket_manager_admission_action_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  BEGIN
    INSERT INTO public.ticket_admission_operations(
      wallet_session_id, event_day_id, event_session_id, ticket_order_id,
      environment, stripe_account_id, check_in_mode, actor_type,
      actor_admin_id, manager_reason, prepare_idempotency_key_hash,
      request_hash, policy_version, expected_order_version,
      selected_count, event_title, event_date
    ) VALUES (
      NULL, v_candidate.event_day_id, v_candidate.event_session_id,
      p_ticket_order_id, p_environment, v_candidate.stripe_account_id,
      'wallet_swipe', 'owner', p_actor_admin_id, left(btrim(p_reason), 240),
      btrim(p_idempotency_key), btrim(p_request_hash), v_candidate.policy_version,
      p_expected_version, v_input_count, v_candidate.event_title,
      v_candidate.event_date
    ) RETURNING * INTO v_operation;
  EXCEPTION WHEN unique_violation THEN
    v_response := jsonb_build_object(
      'action', 'conflict', 'reused', false, 'reason', 'request_hash_reused');
    RETURN public.complete_ticket_manager_admission_action_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END;
  -- INSERT owns the new Operation row lock; no other aggregate lock preceded it.

  SELECT * INTO v_event_day
  FROM public.event_days
  WHERE id = v_operation.event_day_id
  FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Manager Ticket Admission Event Day disappeared';
  END IF;
  SELECT * INTO v_event_session
  FROM public.ticket_event_sessions
  WHERE id = v_operation.event_session_id
    AND event_day_id = v_event_day.id
  FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Manager Ticket Admission Event Session disappeared';
  END IF;
  SELECT * INTO v_ticket_order
  FROM public.ticket_orders
  WHERE id = v_operation.ticket_order_id
    AND event_session_id = v_event_session.id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Manager Ticket Admission Order disappeared';
  END IF;

  PERFORM refund.id
  FROM public.ticket_refund_events AS refund
  WHERE refund.ticket_order_id = v_ticket_order.id
  ORDER BY refund.created_at, refund.id
  FOR UPDATE;
  PERFORM allocation.id
  FROM public.ticket_refund_allocations AS allocation
  WHERE allocation.ticket_order_id = v_ticket_order.id
  ORDER BY allocation.admission_serial, allocation.id
  FOR UPDATE;
  PERFORM admission.id
  FROM public.ticket_admissions AS admission
  WHERE admission.id = ANY(v_admission_ids)
    AND admission.ticket_order_id = v_ticket_order.id
  ORDER BY admission.serial, admission.id
  FOR UPDATE;

  SELECT
    count(*)::integer,
    count(*) FILTER (WHERE admission.status = 'issued')::integer,
    count(*) FILTER (WHERE admission.status = 'admitted')::integer,
    count(*) FILTER (WHERE admission.status = 'void')::integer
  INTO v_selected, v_issued, v_admitted, v_void
  FROM public.ticket_admissions AS admission
  WHERE admission.id = ANY(v_admission_ids)
    AND admission.ticket_order_id = v_ticket_order.id;

  v_now := clock_timestamp();
  IF v_event_day.business_date <> v_event_session.event_date
    OR v_event_day.business_date <> v_ticket_order.event_date
    OR v_event_day.operating_status <> 'open'
  THEN
    v_error_code := 'event_day_closed';
  ELSIF NOT v_event_session.enabled
    OR v_event_session.admission_state <> 'scheduled'
  THEN
    v_error_code := CASE WHEN v_event_session.admission_state = 'cancelled'
      THEN 'event_session_cancelled' ELSE 'event_session_closed' END;
  ELSIF v_now < public.ticket_admission_execution_opens_v56(v_event_session.id) THEN
    v_error_code := 'admission_too_early';
  ELSIF v_now >= public.ticket_admission_execution_closes_v56(v_event_session.id) THEN
    v_error_code := 'admission_too_late';
  ELSIF NOT public.ticket_admission_policy_compatible_v30(
    v_event_session.id, v_operation.policy_version, v_event_session.policy_version)
  THEN
    v_error_code := 'policy_version_changed';
  ELSIF v_event_session.id <> p_event_session_id
    OR v_event_session.environment <> p_environment
    OR v_ticket_order.environment <> p_environment
    OR v_event_session.stripe_account_key <> v_operation.stripe_account_key
    OR v_ticket_order.stripe_account_key <> v_operation.stripe_account_key
    OR v_ticket_order.event_id <> v_event_session.catalog_event_id
    OR v_ticket_order.check_in_mode <> 'wallet_swipe'
  THEN
    v_error_code := 'authority_binding_mismatch';
  ELSIF v_ticket_order.admission_version <> p_expected_version THEN
    v_error_code := 'version_conflict';
  ELSIF NOT public.ticket_order_has_settled_payment_v30(v_ticket_order.id) THEN
    v_error_code := 'payment_not_settled';
  ELSIF EXISTS (
    SELECT 1 FROM public.ticket_refund_events AS refund
    WHERE refund.ticket_order_id = v_ticket_order.id
      AND refund.money_may_have_moved
      AND refund.resolution_status IN ('review_required', 'conflict_review')
      AND refund.resolved_at IS NULL
  ) THEN
    v_error_code := 'refund_review_required';
  ELSIF v_selected <> v_operation.selected_count THEN
    v_error_code := 'same_order_selection_required';
  ELSIF v_admitted > 0 THEN
    v_error_code := 'already_admitted';
  ELSIF v_void > 0 THEN
    v_error_code := 'admission_void';
  ELSIF v_issued <> v_operation.selected_count THEN
    v_error_code := 'admission_not_issued';
  END IF;

  IF v_error_code IS NOT NULL THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', v_error_code,
      'owner', p_actor_admin_id, NULL, p_reason);
    v_response := jsonb_build_object(
      'action', CASE WHEN v_error_code = 'version_conflict'
        THEN 'version_conflict' ELSE 'rejected' END,
      'reason', v_error_code
    ) || v_result || CASE WHEN v_error_code = 'version_conflict'
      THEN jsonb_build_object('entityVersion', v_ticket_order.admission_version)
      ELSE '{}'::jsonb END;
    RETURN public.complete_ticket_manager_admission_action_v30(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  INSERT INTO public.ticket_admission_operation_items(
    operation_id, ticket_order_id, ticket_admission_id, admission_serial
  )
  SELECT v_operation.id, v_ticket_order.id, admission.id, admission.serial
  FROM public.ticket_admissions AS admission
  WHERE admission.id = ANY(v_admission_ids)
    AND admission.ticket_order_id = v_ticket_order.id
  ORDER BY admission.serial, admission.id;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted <> v_operation.selected_count THEN
    RAISE EXCEPTION 'Manager Ticket Admission item row-count mismatch';
  END IF;

  UPDATE public.ticket_admission_operations
  SET state = 'prepared',
      prepared_at = v_now,
      operation_version = operation_version + 1,
      updated_at = v_now
  WHERE id = v_operation.id
    AND state = 'initializing'
  RETURNING * INTO v_operation;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Manager Ticket Admission prepare transition failed';
  END IF;
  INSERT INTO public.ticket_admission_operation_audits(
    operation_id, actor_type, actor_admin_id, action, reason,
    operation_version, result_json
  ) VALUES (
    v_operation.id, 'owner', p_actor_admin_id, 'prepared',
    left(btrim(p_reason), 240), v_operation.operation_version,
    jsonb_build_object('selectedCount', v_operation.selected_count,
                       'eventSessionId', v_operation.event_session_id)
  );

  UPDATE public.ticket_admissions AS admission
  SET status = 'admitted',
      admitted_at = v_now,
      admitted_by_admin_id = p_actor_admin_id
  FROM public.ticket_admission_operation_items AS item
  WHERE item.operation_id = v_operation.id
    AND item.ticket_admission_id = admission.id
    AND item.ticket_order_id = admission.ticket_order_id
    AND item.admission_serial = admission.serial
    AND admission.ticket_order_id = v_ticket_order.id
    AND admission.status = 'issued';
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> v_operation.selected_count THEN
    RAISE EXCEPTION 'Manager Ticket Admission update row-count mismatch';
  END IF;

  SELECT admission_version INTO v_committed_order_version
  FROM public.ticket_orders WHERE id = v_ticket_order.id;
  IF v_committed_order_version <= p_expected_version THEN
    RAISE EXCEPTION 'Manager Ticket Admission order version did not advance';
  END IF;

  v_result := public.complete_ticket_admission_operation_v30(
    v_operation.id, 'committed', NULL, v_now, v_operation.selected_count,
    v_committed_order_version, 'owner', p_actor_admin_id, NULL, p_reason);

  INSERT INTO public.audit_logs(
    action, actor_type, actor_admin_id, target_table, target_id,
    entity_type, entity_id, operation, request_id, reason, metadata_json
  ) VALUES (
    'ticket_admission.owner_committed', 'admin', p_actor_admin_id,
    'ticket_orders', v_ticket_order.id, 'ticket_order', v_ticket_order.id,
    'update', left(btrim(p_request_id), 200), left(btrim(p_reason), 240),
    jsonb_build_object(
      'admissionOperationId', v_operation.id,
      'eventSessionId', v_event_session.id,
      'admissionIds', to_jsonb(v_admission_ids),
      'admittedCount', v_operation.selected_count,
      'previousAdmissionVersion', p_expected_version,
      'admissionVersion', v_committed_order_version)
  ) RETURNING id INTO v_audit_id;

  v_response := jsonb_build_object(
    'action', 'committed', 'auditLogId', v_audit_id,
    'entityVersion', v_committed_order_version
  ) || v_result;
  RETURN public.complete_ticket_manager_admission_action_v30(
    p_actor_admin_id, p_idempotency_key, v_response);
END;
$$;

-- FUNCTION: manager_retry_transactional_email_job_v29(uuid, text, text, text, uuid, boolean, bigint, text)
CREATE FUNCTION public.manager_retry_transactional_email_job_v29(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_email_job_id uuid, p_issue_recovery_mail boolean, p_expected_version bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_claim jsonb;
  v_response jsonb;
  v_job public.transactional_email_jobs%ROWTYPE;
  v_challenge public.ticket_wallet_otp_challenges%ROWTYPE;
  v_previous_version bigint;
  v_previous_state text;
  v_audit_id uuid;
  v_queued_job_id uuid;
  v_render jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admin_users AS admin_user
    WHERE admin_user.id = p_actor_admin_id
      AND admin_user.active AND admin_user.role = 'owner'
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'owner_role_required');
  END IF;
  IF p_email_job_id IS NULL OR p_issue_recovery_mail IS NULL
    OR p_expected_version IS NULL OR p_expected_version < 1
    OR NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR char_length(p_request_id) > 200
    OR NULLIF(btrim(COALESCE(p_idempotency_key, '')), '') IS NULL
    OR char_length(p_idempotency_key) > 200
    OR NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL
    OR char_length(p_request_hash) > 200
    OR NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL
    OR char_length(p_reason) > 240
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'manager_retry_invalid');
  END IF;

  v_claim := public.preclaim_admin_action_request_v8(
    p_actor_admin_id, 'manager_retry_transactional_email_job_v29',
    btrim(p_idempotency_key), btrim(p_request_hash));
  IF v_claim ->> 'action' = 'reused' THEN
    RETURN (v_claim -> 'response') || jsonb_build_object('reused', true);
  ELSIF v_claim #>> '{error,code}' = 'IDEMPOTENCY_MISMATCH' THEN
    RETURN jsonb_build_object(
      'action', 'conflict', 'reused', false,
      'reason', 'idempotency_mismatch');
  ELSIF v_claim #>> '{error,code}' = 'IDEMPOTENCY_IN_PROGRESS' THEN
    RETURN jsonb_build_object(
      'action', 'conflict', 'reused', false,
      'reason', 'idempotency_in_progress');
  ELSIF v_claim #>> '{error,code}' = 'INVALID_COMMAND' THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'input_invalid');
  ELSIF v_claim ->> 'action' <> 'claimed' THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'input_invalid');
  END IF;

  PERFORM 1 FROM public.admin_users AS admin_user
  WHERE admin_user.id = p_actor_admin_id
    AND admin_user.active AND admin_user.role = 'owner'
  FOR KEY SHARE;
  IF NOT FOUND THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'owner_role_required');
    RETURN public.complete_ticket_wallet_manager_action_v29(
      p_actor_admin_id, 'manager_retry_transactional_email_job_v29',
      p_idempotency_key, v_response);
  END IF;

  SELECT job.* INTO v_job
  FROM public.ticket_wallet_otp_challenges AS challenge
  JOIN public.transactional_email_jobs AS job
    ON job.otp_challenge_id = challenge.id
  WHERE job.id = p_email_job_id
  FOR UPDATE OF challenge, job;
  IF NOT FOUND THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false,
      'reason', 'email_job_not_found', 'emailJobId', p_email_job_id);
    RETURN public.complete_ticket_wallet_manager_action_v29(
      p_actor_admin_id, 'manager_retry_transactional_email_job_v29',
      p_idempotency_key, v_response);
  END IF;
  IF v_job.entity_version <> p_expected_version THEN
    v_response := jsonb_build_object(
      'action', 'version_conflict', 'reused', false,
      'reason', 'entity_version_mismatch', 'emailJobId', v_job.id,
      'entityVersion', v_job.entity_version);
    RETURN public.complete_ticket_wallet_manager_action_v29(
      p_actor_admin_id, 'manager_retry_transactional_email_job_v29',
      p_idempotency_key, v_response);
  END IF;
  IF v_job.state NOT IN ('retry', 'dead') THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false,
      'reason', 'email_job_not_retryable', 'emailJobId', v_job.id,
      'entityVersion', v_job.entity_version);
    RETURN public.complete_ticket_wallet_manager_action_v29(
      p_actor_admin_id, 'manager_retry_transactional_email_job_v29',
      p_idempotency_key, v_response);
  END IF;
  IF NOT p_issue_recovery_mail
    AND v_job.attempt_count >= v_job.maximum_attempts
  THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false,
      'reason', 'email_job_attempts_exhausted', 'emailJobId', v_job.id,
      'entityVersion', v_job.entity_version);
    RETURN public.complete_ticket_wallet_manager_action_v29(
      p_actor_admin_id, 'manager_retry_transactional_email_job_v29',
      p_idempotency_key, v_response);
  END IF;
  IF v_job.recipient_email_hash IS NULL OR EXISTS (
    SELECT 1 FROM public.transactional_email_suppressions AS suppression
    WHERE suppression.recipient_email_hash = v_job.recipient_email_hash
      AND suppression.active
  ) THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false,
      'reason', 'recipient_suppressed', 'emailJobId', v_job.id,
      'entityVersion', v_job.entity_version);
    RETURN public.complete_ticket_wallet_manager_action_v29(
      p_actor_admin_id, 'manager_retry_transactional_email_job_v29',
      p_idempotency_key, v_response);
  END IF;

  SELECT * INTO v_challenge
  FROM public.ticket_wallet_otp_challenges
  WHERE id = v_job.otp_challenge_id;
  IF NOT FOUND OR v_challenge.state NOT IN ('pending', 'sending', 'sent')
    OR v_challenge.expires_at <= v_now OR v_challenge.code_ciphertext IS NULL
  THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false,
      'reason', 'recovery_mail_impossible', 'emailJobId', v_job.id,
      'entityVersion', v_job.entity_version);
    RETURN public.complete_ticket_wallet_manager_action_v29(
      p_actor_admin_id, 'manager_retry_transactional_email_job_v29',
      p_idempotency_key, v_response);
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.ticket_wallet_manager_audits
    WHERE actor_admin_id = p_actor_admin_id
      AND action = 'manager_retry_transactional_email_job_v29'
      AND request_id = btrim(p_request_id)
  ) THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'request_id_reused');
    RETURN public.complete_ticket_wallet_manager_action_v29(
      p_actor_admin_id, 'manager_retry_transactional_email_job_v29',
      p_idempotency_key, v_response);
  END IF;

  v_previous_version := v_job.entity_version;
  v_previous_state := v_job.state;
  IF p_issue_recovery_mail THEN
    v_queued_job_id := gen_random_uuid();
    v_render := jsonb_set(
      v_job.render_data_json, '{notificationJobId}',
      to_jsonb(v_queued_job_id::text), false);
    v_render := jsonb_set(
      v_render, '{tags}',
      jsonb_build_array(
        jsonb_build_object('name', 'purpose', 'value', 'ticket_wallet_otp'),
        jsonb_build_object(
          'name', 'notification_job_id', 'value', v_queued_job_id)
      ), false);
    INSERT INTO public.transactional_email_jobs(
      id, otp_challenge_id, purpose, provider_idempotency_key,
      recipient_email_hash, recipient_email_ciphertext, render_data_json,
      state, next_attempt_at, created_at, updated_at
    ) VALUES (
      v_queued_job_id, v_job.otp_challenge_id, v_job.purpose,
      'ghost-ticket-wallet-recovery-v1-' || v_queued_job_id::text,
      v_job.recipient_email_hash, v_job.recipient_email_ciphertext,
      v_render, 'pending', v_now, v_now, v_now
    );
    UPDATE public.transactional_email_jobs
    SET state = CASE WHEN state = 'retry' THEN 'cancelled' ELSE state END,
        terminal_at = CASE WHEN state = 'retry' THEN v_now ELSE terminal_at END,
        manager_recovery_count = manager_recovery_count + 1,
        last_manager_recovery_at = v_now, updated_at = v_now
    WHERE id = v_job.id
    RETURNING * INTO v_job;
  ELSE
    v_queued_job_id := v_job.id;
    UPDATE public.transactional_email_jobs
    SET state = 'pending', provider_delivery_state = 'pending',
        provider_state_precedence = 0, provider_state_occurred_at = NULL,
        completed_at = NULL, terminal_at = NULL, safe_error_category = NULL,
        next_attempt_at = v_now,
        claimed_by = NULL, claim_token = NULL, claimed_at = NULL,
        lease_expires_at = NULL,
        manager_recovery_count = manager_recovery_count + 1,
        last_manager_recovery_at = v_now, updated_at = v_now
    WHERE id = v_job.id
    RETURNING * INTO v_job;
  END IF;

  INSERT INTO public.ticket_wallet_manager_audits(
    actor_admin_id, action, request_id, idempotency_key, request_hash,
    entity_type, entity_id, previous_version, new_version, reason,
    issue_recovery_mail, safe_before_json, safe_after_json
  ) VALUES (
    p_actor_admin_id, 'manager_retry_transactional_email_job_v29',
    btrim(p_request_id), btrim(p_idempotency_key), btrim(p_request_hash),
    'transactional_email_job', v_job.id,
    v_previous_version, v_job.entity_version, btrim(p_reason),
    p_issue_recovery_mail,
    jsonb_build_object(
      'emailJobId', v_job.id, 'state', v_previous_state,
      'entityVersion', v_previous_version),
    jsonb_build_object(
      'emailJobId', v_job.id, 'state', v_job.state,
      'entityVersion', v_job.entity_version,
      'queuedJobId', v_queued_job_id,
      'issueRecoveryMail', p_issue_recovery_mail)
  ) RETURNING id INTO v_audit_id;

  v_response := jsonb_build_object(
    'action', 'requeued', 'reused', false,
    'emailJobId', v_job.id, 'queuedJobId', v_queued_job_id,
    'issueRecoveryMail', p_issue_recovery_mail,
    'entityVersion', v_job.entity_version, 'auditId', v_audit_id
  );
  RETURN public.complete_ticket_wallet_manager_action_v29(
    p_actor_admin_id, 'manager_retry_transactional_email_job_v29',
    p_idempotency_key, v_response);
END;
$$;

-- FUNCTION: manager_revoke_ticket_wallet_session_v29(uuid, text, text, text, text, uuid, bigint, text)
CREATE FUNCTION public.manager_revoke_ticket_wallet_session_v29(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_order_public_code text, p_session_id uuid, p_expected_version bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_claim jsonb;
  v_response jsonb;
  v_session public.ticket_wallet_sessions%ROWTYPE;
  v_previous_version bigint;
  v_audit_id uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admin_users AS admin_user
    WHERE admin_user.id = p_actor_admin_id
      AND admin_user.active AND admin_user.role = 'owner'
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'owner_role_required');
  END IF;
  IF p_session_id IS NULL OR p_expected_version IS NULL OR p_expected_version < 1
    OR p_order_public_code IS NULL
    OR p_order_public_code !~ '^GT-[0-9A-HJ-NP-Z]{10}$'
    OR NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR char_length(p_request_id) > 200
    OR NULLIF(btrim(COALESCE(p_idempotency_key, '')), '') IS NULL
    OR char_length(p_idempotency_key) > 200
    OR NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL
    OR char_length(p_request_hash) > 200
    OR NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL
    OR char_length(p_reason) > 240
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'manager_revoke_invalid');
  END IF;

  -- This idempotency row is the first serialization/lock authority.
  v_claim := public.preclaim_admin_action_request_v8(
    p_actor_admin_id, 'manager_revoke_ticket_wallet_session_v29',
    btrim(p_idempotency_key), btrim(p_request_hash));
  IF v_claim ->> 'action' = 'reused' THEN
    RETURN (v_claim -> 'response') || jsonb_build_object('reused', true);
  ELSIF v_claim #>> '{error,code}' = 'IDEMPOTENCY_MISMATCH' THEN
    RETURN jsonb_build_object(
      'action', 'conflict', 'reused', false,
      'reason', 'idempotency_mismatch');
  ELSIF v_claim #>> '{error,code}' = 'IDEMPOTENCY_IN_PROGRESS' THEN
    RETURN jsonb_build_object(
      'action', 'conflict', 'reused', false,
      'reason', 'idempotency_in_progress');
  ELSIF v_claim #>> '{error,code}' = 'INVALID_COMMAND' THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'input_invalid');
  ELSIF v_claim ->> 'action' <> 'claimed' THEN
    RETURN jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'input_invalid');
  END IF;

  PERFORM 1 FROM public.admin_users AS admin_user
  WHERE admin_user.id = p_actor_admin_id
    AND admin_user.active AND admin_user.role = 'owner'
  FOR KEY SHARE;
  IF NOT FOUND THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'owner_role_required');
    RETURN public.complete_ticket_wallet_manager_action_v29(
      p_actor_admin_id, 'manager_revoke_ticket_wallet_session_v29',
      p_idempotency_key, v_response);
  END IF;

  SELECT * INTO v_session
  FROM public.ticket_wallet_sessions
  WHERE id = p_session_id
  FOR UPDATE;
  IF NOT FOUND THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false,
      'reason', 'wallet_session_not_found', 'sessionId', p_session_id);
    RETURN public.complete_ticket_wallet_manager_action_v29(
      p_actor_admin_id, 'manager_revoke_ticket_wallet_session_v29',
      p_idempotency_key, v_response);
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.ticket_orders AS ticket_order
    WHERE ticket_order.public_code = p_order_public_code
      AND ticket_order.environment = v_session.environment
      AND ticket_order.check_in_mode = 'wallet_swipe'
      AND ticket_order.purchaser_email_hash = v_session.identity_email_hash
  ) THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false,
      'reason', 'wallet_session_not_found', 'sessionId', p_session_id);
    RETURN public.complete_ticket_wallet_manager_action_v29(
      p_actor_admin_id, 'manager_revoke_ticket_wallet_session_v29',
      p_idempotency_key, v_response);
  END IF;
  IF v_session.entity_version <> p_expected_version THEN
    v_response := jsonb_build_object(
      'action', 'version_conflict', 'reused', false,
      'reason', 'entity_version_mismatch', 'sessionId', v_session.id,
      'entityVersion', v_session.entity_version);
    RETURN public.complete_ticket_wallet_manager_action_v29(
      p_actor_admin_id, 'manager_revoke_ticket_wallet_session_v29',
      p_idempotency_key, v_response);
  END IF;
  IF v_session.revoked_at IS NOT NULL THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false,
      'reason', 'wallet_session_already_revoked', 'sessionId', v_session.id,
      'entityVersion', v_session.entity_version);
    RETURN public.complete_ticket_wallet_manager_action_v29(
      p_actor_admin_id, 'manager_revoke_ticket_wallet_session_v29',
      p_idempotency_key, v_response);
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.ticket_wallet_manager_audits
    WHERE actor_admin_id = p_actor_admin_id
      AND action = 'manager_revoke_ticket_wallet_session_v29'
      AND request_id = btrim(p_request_id)
  ) THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reused', false, 'reason', 'request_id_reused');
    RETURN public.complete_ticket_wallet_manager_action_v29(
      p_actor_admin_id, 'manager_revoke_ticket_wallet_session_v29',
      p_idempotency_key, v_response);
  END IF;

  v_previous_version := v_session.entity_version;
  UPDATE public.ticket_wallet_sessions
  SET revoked_at = v_now, revocation_reason = 'operator_recovery',
      token_verifier = NULL, csrf_verifier = NULL, updated_at = v_now
  WHERE id = v_session.id
  RETURNING * INTO v_session;

  INSERT INTO public.ticket_wallet_manager_audits(
    actor_admin_id, action, request_id, idempotency_key, request_hash,
    entity_type, entity_id, previous_version, new_version, reason,
    issue_recovery_mail, safe_before_json, safe_after_json
  ) VALUES (
    p_actor_admin_id, 'manager_revoke_ticket_wallet_session_v29',
    btrim(p_request_id), btrim(p_idempotency_key), btrim(p_request_hash),
    'wallet_session', v_session.id, v_previous_version, v_session.entity_version,
    btrim(p_reason), NULL,
    jsonb_build_object(
      'sessionId', v_session.id, 'environment', v_session.environment,
      'state', 'active', 'entityVersion', v_previous_version,
      'expiresAt', v_session.expires_at),
    jsonb_build_object(
      'sessionId', v_session.id, 'environment', v_session.environment,
      'state', 'revoked', 'entityVersion', v_session.entity_version,
      'revokedAt', v_session.revoked_at,
      'revocationReason', v_session.revocation_reason)
  ) RETURNING id INTO v_audit_id;

  v_response := jsonb_build_object(
    'action', 'revoked', 'reused', false,
    'sessionId', v_session.id, 'entityVersion', v_session.entity_version,
    'auditId', v_audit_id
  );
  RETURN public.complete_ticket_wallet_manager_action_v29(
    p_actor_admin_id, 'manager_revoke_ticket_wallet_session_v29',
    p_idempotency_key, v_response);
END;
$_$;

-- FUNCTION: manager_ticket_entry_v53(uuid, text, text, text, uuid, text, bigint, text, text, text, uuid, integer, integer, text, text, uuid, text, text, text, text)
CREATE FUNCTION public.manager_ticket_entry_v53(p_actor uuid, p_request_id text, p_key text, p_hash text, p_order uuid, p_environment text, p_expected_version bigint, p_action text, p_reason text, p_confirmation text, p_original_operation uuid, p_count integer, p_expected_generation integer, p_origin text, p_account text, p_link uuid, p_verifier text, p_ciphertext text, p_from text, p_reply text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c jsonb; r jsonb; o public.ticket_orders%ROWTYPE; l public.ticket_order_entry_links%ROWTYPE;
 locked jsonb; generation integer; n integer; original uuid; audit uuid; j uuid; at timestamptz; closing timestamptz;
BEGIN
 PERFORM public.ticket_wallet_gate_fence_v30();
 IF NOT EXISTS(SELECT 1 FROM public.admin_users WHERE id=p_actor AND active AND role='owner') THEN RETURN jsonb_build_object('action','rejected','reason','owner_role_required'); END IF;
 IF p_action NOT IN ('entry_rotate','entry_revoke','entry_resend','entry_exception') OR p_action IS NULL
  OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 8 AND 240 OR p_expected_version IS NULL OR p_expected_version<1
  OR p_request_id IS NULL OR length(p_request_id) NOT BETWEEN 1 AND 200
 THEN RETURN jsonb_build_object('action','rejected','reason','input_invalid'); END IF;
 c:=public.preclaim_admin_action_request_v8(p_actor,'manager_ticket_entry_v53',p_key,p_hash);
 IF c->>'action'='reused' THEN RETURN (c->'response')||jsonb_build_object('reused',true); END IF;
 IF c->>'action'<>'claimed' THEN RETURN jsonb_build_object('action','conflict','reason','idempotency_mismatch'); END IF;
 PERFORM 1 FROM public.admin_users WHERE id=p_actor AND active AND role='owner' FOR SHARE;
 IF NOT FOUND THEN r:=jsonb_build_object('action','rejected','reason','owner_role_required'); ELSE
  -- Recovery of a compromised link is permitted outside the entry window;
  -- an exception admission requires every normal event/payment check.
  IF p_action='entry_exception' THEN locked:=public.lock_ticket_order_entry_v52(p_order); END IF;
  SELECT * INTO o FROM public.ticket_orders WHERE id=p_order FOR UPDATE;
  SELECT * INTO l FROM public.ticket_order_entry_links WHERE ticket_order_id=p_order ORDER BY generation DESC LIMIT 1 FOR UPDATE;
  SELECT public.ticket_admission_execution_closes_v56(id) INTO closing FROM public.ticket_event_sessions WHERE id=o.event_session_id;
  IF o.id IS NULL OR o.environment IS DISTINCT FROM p_environment OR o.stripe_account_key IS DISTINCT FROM p_account
   OR o.admission_policy<>'order_together_v1' THEN r:=jsonb_build_object('action','rejected','reason','authority_binding_mismatch');
  ELSIF o.admission_version<>p_expected_version OR (p_action<>'entry_exception' AND l.generation IS DISTINCT FROM p_expected_generation)
   THEN r:=jsonb_build_object('action','conflict','reason','version_conflict');
  ELSIF p_action='entry_exception' THEN
   PERFORM id FROM public.ticket_admissions WHERE ticket_order_id=o.id ORDER BY serial,id FOR UPDATE;
   SELECT count(*) INTO n FROM public.ticket_admissions WHERE ticket_order_id=o.id AND status='admitted';
   SELECT coalesce((SELECT id FROM public.ticket_order_entry_operations WHERE ticket_order_id=o.id AND state='committed' ORDER BY created_at LIMIT 1),
    (SELECT id FROM public.ticket_admission_operations WHERE ticket_order_id=o.id AND state='committed' ORDER BY created_at LIMIT 1)) INTO original;
   IF locked ? 'error' THEN r:=jsonb_build_object('action','rejected','reason',locked->>'error');
   ELSIF EXISTS(SELECT 1 FROM public.ticket_entry_exceptions WHERE ticket_order_id=o.id) THEN r:=jsonb_build_object('action','rejected','reason','exception_already_recorded');
   ELSIF original IS NULL OR original IS DISTINCT FROM p_original_operation OR n IS DISTINCT FROM p_count OR n NOT BETWEEN 1 AND 20
    OR (SELECT count(*) FROM public.ticket_admissions WHERE ticket_order_id=o.id)<>o.total_quantity
    OR EXISTS(SELECT 1 FROM public.ticket_admissions WHERE ticket_order_id=o.id AND status NOT IN ('admitted','void'))
    OR p_confirmation IS NULL OR length(btrim(p_confirmation)) NOT BETWEEN 8 AND 400
    THEN r:=jsonb_build_object('action','rejected','reason','whole_order_confirmation_required'); END IF;
  ELSIF p_action='entry_revoke' THEN
   IF l.id IS NULL OR l.revoked_at IS NOT NULL THEN r:=jsonb_build_object('action','rejected','reason','link_already_revoked'); END IF;
  ELSIF l.id IS NULL OR closing<=clock_timestamp() OR NOT public.ticket_order_has_settled_payment_v30(o.id)
   OR (p_action='entry_resend' AND l.revoked_at IS NOT NULL) OR l.public_origin IS DISTINCT FROM p_origin
   THEN r:=jsonb_build_object('action','rejected','reason','entry_recovery_unavailable');
  ELSIF p_action='entry_resend' AND NOT public.consume_ticket_wallet_rate_limit_v29('entry_owner_resend',o.id::text,3600,2)
   THEN r:=jsonb_build_object('action','rejected','reason','rate_limited'); END IF;
  IF r IS NULL THEN
   at:=clock_timestamp();
   IF p_action IN ('entry_revoke','entry_rotate') AND l.revoked_at IS NULL THEN UPDATE public.ticket_order_entry_links SET revoked_at=at WHERE id=l.id; END IF;
   IF p_action='entry_rotate' THEN
    generation:=l.generation+1;
    INSERT INTO public.ticket_order_entry_links(id,ticket_order_id,generation,environment,public_origin,stripe_account_key,event_session_id,token_verifier,secret_ciphertext,expires_at)
     VALUES(p_link,o.id,generation,o.environment,p_origin,o.stripe_account_key,o.event_session_id,p_verifier,p_ciphertext,closing);
    j:=public.queue_ticket_entry_delivery_v53(p_link,p_from,p_reply);
   ELSIF p_action='entry_resend' THEN j:=public.queue_ticket_entry_delivery_v53(l.id,p_from,p_reply); END IF;
   INSERT INTO public.audit_logs(action,actor_type,actor_admin_id,target_table,target_id,entity_type,entity_id,operation,request_id,reason,metadata_json)
    VALUES('ticket_order.'||p_action,'admin',p_actor,'ticket_orders',o.id,'ticket_order',o.id,'update',p_request_id,p_reason,
     jsonb_build_object('originalOperationId',original,'admittedCount',n,'confirmation',p_confirmation,
      'previousLinkId',l.id,'linkId',CASE WHEN p_action='entry_rotate' THEN p_link ELSE l.id END,'generation',coalesce(generation,l.generation),'emailJobId',j)) RETURNING id INTO audit;
   IF p_action='entry_exception' THEN INSERT INTO public.ticket_entry_exceptions(ticket_order_id,original_operation_id,actor_admin_id,admitted_count,reason,confirmation,audit_log_id,created_at)
    VALUES(o.id,original,p_actor,n,p_reason,p_confirmation,audit,at); END IF;
   r:=jsonb_build_object('action','committed','auditLogId',audit,'entityVersion',o.admission_version,'emailJobId',j,'reused',false);
  END IF;
 END IF;
 IF r IS NULL OR r->>'action' IS NULL THEN RAISE EXCEPTION 'ticket_entry_manager_result_invalid'; END IF;
 UPDATE public.admin_action_requests SET response_json=r,updated_at=clock_timestamp()
  WHERE actor_admin_id=p_actor AND action='manager_ticket_entry_v53' AND idempotency_key=btrim(p_key) AND response_json IS NULL;
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'ticket_entry_manager_completion_failed'; END IF;
 RETURN r;
END $$;

-- FUNCTION: mark_email_notification_job_result_v10(uuid, uuid, boolean, integer, text, text)
CREATE FUNCTION public.mark_email_notification_job_result_v10(p_notification_job_id uuid, p_claim_token uuid, p_sent boolean, p_provider_status integer, p_provider_receipt_hash text, p_error_code text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_attempt int;
  v_next_status text;
BEGIN
  SELECT attempt_count
  INTO v_attempt
  FROM public.notification_jobs
  WHERE id = p_notification_job_id
    AND channel = 'email'
    AND status = 'processing'
    AND claim_token = p_claim_token
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stale email notification claim';
  END IF;

  v_next_status := CASE
    WHEN p_sent THEN 'sent'
    -- NEW (G-23): suppression is a terminal policy outcome, not a retryable
    -- delivery failure. Lands 'dead' so it stays visible in dead-items.
    WHEN p_error_code = 'recipient_suppressed' THEN 'dead'
    -- W11 (v75): same fenced terminal state as the LINE channel — the
    -- first-send window lapsed or is unknowable; retry is not safe.
    WHEN p_error_code = 'provider_request_reconciliation_required' THEN 'dead'
    WHEN v_attempt >= 3 THEN 'dead'
    ELSE 'retry'
  END;

  UPDATE public.notification_jobs
  SET status = v_next_status,
      payload_json = CASE
        WHEN p_sent THEN payload_json || jsonb_build_object(
          'providerStatus', p_provider_status,
          'providerReceiptHash', NULLIF(btrim(COALESCE(p_provider_receipt_hash, '')), '')
        )
        ELSE payload_json
      END,
      error_json = CASE
        WHEN p_sent THEN NULL
        ELSE jsonb_build_object(
          'code', left(COALESCE(NULLIF(btrim(p_error_code), ''), 'delivery_failed'), 120)
        )
      END,
      next_attempt_at = CASE
        WHEN p_sent OR v_next_status = 'dead' THEN next_attempt_at
        ELSE now() + make_interval(secs => CASE v_attempt
          WHEN 1 THEN 60
          ELSE 300
        END)
      END,
      locked_by = NULL,
      locked_at = NULL,
      claim_token = NULL,
      updated_at = now()
  WHERE id = p_notification_job_id
    AND channel = 'email'
    AND status = 'processing'
    AND claim_token = p_claim_token;

  RETURN v_next_status;
END;
$$;

-- FUNCTION: mark_notification_job_result_v7(uuid, text, jsonb, jsonb, uuid)
CREATE FUNCTION public.mark_notification_job_result_v7(p_notification_job_id uuid, p_status text, p_response_json jsonb, p_error_json jsonb, p_claim_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_attempt int;
BEGIN
  SELECT attempt_count INTO v_attempt
  FROM notification_jobs
  WHERE id = p_notification_job_id
    AND status = 'processing'
    AND claim_token = p_claim_token
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stale notification job claim for job %', p_notification_job_id;
  END IF;

  UPDATE notification_jobs
  SET status = CASE
        WHEN p_status = 'sent' THEN 'sent'
        WHEN p_status = 'review_required' THEN 'dead'
        WHEN v_attempt >= 5 THEN 'dead'
        ELSE 'retry'
      END,
      payload_json = CASE
        WHEN p_status = 'sent' THEN payload_json || jsonb_build_object('lineResponse', COALESCE(p_response_json, '{}'::jsonb))
        ELSE payload_json
      END,
      error_json = p_error_json,
      next_attempt_at = CASE
        WHEN p_status = 'sent' THEN next_attempt_at
        ELSE now() + make_interval(secs => LEAST((60 * (2 ^ LEAST(GREATEST(v_attempt, 0), 4)))::int, 900))
      END,
      locked_by = NULL,
      locked_at = NULL,
      claim_token = NULL,
      updated_at = now()
  WHERE id = p_notification_job_id
    AND status = 'processing'
    AND claim_token = p_claim_token;
END;
$$;

-- FUNCTION: mark_off_session_charge_attempt_result_v7(uuid, text, text, jsonb, jsonb, uuid)
CREATE FUNCTION public.mark_off_session_charge_attempt_result_v7(p_attempt_id uuid, p_status text, p_provider_object_id text, p_response_snapshot_json jsonb, p_error_json jsonb, p_claim_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_attempt_row off_session_charge_attempts%ROWTYPE;
  v_outcome text := p_status;
  v_provider_status text := p_response_snapshot_json->>'status';
  v_entry_type text;
BEGIN
  SELECT * INTO v_attempt_row
  FROM off_session_charge_attempts
  WHERE id = p_attempt_id
    AND status = 'processing'
    AND claim_token = p_claim_token
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stale off-session charge claim for attempt %', p_attempt_id;
  END IF;

  IF p_status IS NULL OR p_status NOT IN ('succeeded', 'pending', 'failed') THEN
    RAISE EXCEPTION 'invalid worker result status';
  END IF;
  IF p_status IN ('succeeded', 'pending') AND (p_provider_object_id IS NULL OR p_provider_object_id = '') THEN
    RAISE EXCEPTION 'provider identity required for observed result';
  END IF;

  -- A DB-first rollout can still receive terminal claims from an old worker.
  -- Provider snapshots determine that outcome; a caller label alone can never
  -- create a successful payment or ledger entry. Keep known pending identities
  -- pollable even when the old caller incorrectly reported success.
  IF p_status = 'succeeded' THEN
    IF jsonb_typeof(p_response_snapshot_json) IS DISTINCT FROM 'object'
      OR jsonb_typeof(p_response_snapshot_json->'status') IS DISTINCT FROM 'string'
      OR v_provider_status NOT IN ('requires_payment_method','requires_confirmation','requires_action','processing','requires_capture','canceled','succeeded') THEN
      RAISE EXCEPTION 'provider status evidence required for success claim';
    END IF;
    v_outcome := CASE
      WHEN v_provider_status = 'succeeded' THEN 'succeeded'
      WHEN v_provider_status IN ('canceled','requires_payment_method') THEN 'failed'
      ELSE 'pending'
    END;
  END IF;

  UPDATE off_session_charge_attempts
  SET status = CASE
        WHEN v_outcome = 'succeeded' THEN 'succeeded'
        WHEN v_outcome = 'pending' OR (v_outcome = 'failed' AND p_response_snapshot_json IS NULL
          AND v_attempt_row.provider_object_id IS NOT NULL
          AND v_attempt_row.response_snapshot_json->>'status' NOT IN ('succeeded','canceled','requires_payment_method')) THEN 'approved'
        WHEN p_error_json->>'code' = 'provider_request_reconciliation_required' THEN 'dead'
        WHEN v_outcome = 'failed' AND p_response_snapshot_json->>'status' IN ('canceled','requires_payment_method') THEN 'failed'
        WHEN v_attempt_row.attempt_count >= 5 THEN 'dead'
        ELSE 'approved'
      END,
      provider_object_id = COALESCE(p_provider_object_id, provider_object_id),
      response_snapshot_json = COALESCE(p_response_snapshot_json, response_snapshot_json),
      error_json = p_error_json,
      next_attempt_at = CASE
        WHEN v_outcome = 'succeeded' THEN next_attempt_at
        WHEN v_outcome = 'pending' OR (v_outcome = 'failed' AND p_response_snapshot_json IS NULL
          AND v_attempt_row.provider_object_id IS NOT NULL
          AND v_attempt_row.response_snapshot_json->>'status' NOT IN ('succeeded','canceled','requires_payment_method')) THEN now() + interval '60 seconds'
        ELSE now() + make_interval(secs => LEAST((60 * (2 ^ LEAST(GREATEST(v_attempt_row.attempt_count, 0), 4)))::int, 900))
      END,
      locked_by = NULL,
      locked_at = NULL,
      claim_token = NULL,
      updated_at = now()
  WHERE id = p_attempt_id
    AND status = 'processing'
    AND claim_token = p_claim_token;

  IF v_outcome = 'succeeded' THEN
    v_entry_type := CASE
      WHEN v_attempt_row.case_type = 'no_show' THEN 'no_show_charge_succeeded'
      ELSE 'late_cancel_charge_succeeded'
    END;

    UPDATE payments
    SET status = 'succeeded',
        provider_object_type = 'payment_intent',
        provider_object_id = COALESCE(p_provider_object_id, provider_object_id),
        updated_at = now()
    WHERE id = v_attempt_row.payment_id;

    IF v_attempt_row.case_type = 'no_show' THEN
      UPDATE no_show_cases
      SET status = 'charged',
          updated_at = now()
      WHERE id = v_attempt_row.case_id;
    ELSE
      UPDATE late_cancel_cases
      SET status = 'charged',
          updated_at = now()
      WHERE id = v_attempt_row.case_id;
    END IF;

    INSERT INTO ledger_entries(reservation_id, payment_id, entry_type, amount_yen, currency)
    VALUES (
      v_attempt_row.reservation_id,
      v_attempt_row.payment_id,
      v_entry_type,
      v_attempt_row.amount_yen,
      v_attempt_row.currency
    )
    ON CONFLICT (payment_id, entry_type)
    WHERE payment_id IS NOT NULL
      AND refund_case_id IS NULL
    DO NOTHING;
  END IF;
END;
$$;

-- FUNCTION: mark_public_reservation_hold_stripe_unknown_v7(text, text, text, text, text)
CREATE FUNCTION public.mark_public_reservation_hold_stripe_unknown_v7(p_source_system text, p_idempotency_key text, p_request_hash text, p_error_code text, p_error_message text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_hold reservation_hold_requests%ROWTYPE;
BEGIN
  SELECT * INTO v_hold
  FROM reservation_hold_requests
  WHERE source_system = p_source_system
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'reservation hold request not found';
  END IF;

  IF v_hold.request_hash <> p_request_hash THEN
    RETURN jsonb_build_object(
      'action', 'mismatch',
      'error', 'idempotency_key_reused_with_different_request'
    );
  END IF;

  UPDATE reservation_hold_requests
  SET status = CASE
        WHEN finalize_attempts >= 5 THEN 'manual_review'::reservation_hold_request_status
        ELSE 'stripe_unknown'::reservation_hold_request_status
      END,
      finalize_attempts = finalize_attempts + 1,
      next_attempt_at = now() + make_interval(secs => LEAST((30 * (2 ^ GREATEST(finalize_attempts, 0)))::int, 900)),
      last_error_code = p_error_code,
      last_error_message = p_error_message,
      updated_at = now()
  WHERE id = v_hold.id;

  RETURN jsonb_build_object(
    'action', 'marked_unknown',
    'reservationId', v_hold.reservation_id
  );
END;
$$;

-- FUNCTION: mark_refund_case_result_v7(uuid, text, text, jsonb, jsonb, uuid)
CREATE FUNCTION public.mark_refund_case_result_v7(p_refund_case_id uuid, p_status text, p_stripe_refund_id text, p_response_snapshot_json jsonb, p_error_json jsonb, p_claim_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_case refund_cases%ROWTYPE;
  v_outcome text := p_status;
  v_provider_status text := p_response_snapshot_json->>'status';
BEGIN
  SELECT * INTO v_case
  FROM refund_cases
  WHERE id = p_refund_case_id
    AND status = 'processing'
    AND claim_token = p_claim_token
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stale refund claim for case %', p_refund_case_id;
  END IF;

  IF p_status IS NULL OR p_status NOT IN ('refunded', 'pending', 'failed') THEN
    RAISE EXCEPTION 'invalid worker result status';
  END IF;
  IF p_status IN ('refunded', 'pending') AND (p_stripe_refund_id IS NULL OR p_stripe_refund_id = '') THEN
    RAISE EXCEPTION 'provider identity required for observed result';
  END IF;

  -- A DB-first rollout can still receive terminal claims from an old worker.
  -- Provider snapshots determine that outcome; a caller label alone can never
  -- create a successful payment or ledger entry. Keep known pending identities
  -- pollable even when the old caller incorrectly reported success.
  IF p_status = 'refunded' THEN
    IF jsonb_typeof(p_response_snapshot_json) IS DISTINCT FROM 'object'
      OR jsonb_typeof(p_response_snapshot_json->'status') IS DISTINCT FROM 'string'
      OR v_provider_status NOT IN ('pending','requires_action','succeeded','failed','canceled') THEN
      RAISE EXCEPTION 'provider status evidence required for success claim';
    END IF;
    v_outcome := CASE
      WHEN v_provider_status = 'succeeded' THEN 'refunded'
      WHEN v_provider_status IN ('failed','canceled') THEN 'failed'
      ELSE 'pending'
    END;
  END IF;

  UPDATE refund_cases
  SET status = CASE
        WHEN v_outcome = 'refunded' THEN 'refunded'
        WHEN v_outcome = 'pending' OR (v_outcome = 'failed' AND p_response_snapshot_json IS NULL
          AND v_case.stripe_refund_id IS NOT NULL
          AND v_case.response_snapshot_json->>'status' NOT IN ('succeeded','failed','canceled')) THEN 'approved'
        WHEN p_error_json->>'code' = 'provider_request_reconciliation_required' THEN 'dead'
        WHEN v_outcome = 'failed' AND p_response_snapshot_json->>'status' IN ('failed','canceled') THEN 'failed'
        WHEN v_case.attempt_count >= 5 THEN 'dead'
        ELSE 'approved'
      END,
      stripe_refund_id = COALESCE(p_stripe_refund_id, stripe_refund_id),
      response_snapshot_json = COALESCE(p_response_snapshot_json, response_snapshot_json),
      error_json = p_error_json,
      next_attempt_at = CASE
        WHEN v_outcome = 'refunded' THEN next_attempt_at
        WHEN v_outcome = 'pending' OR (v_outcome = 'failed' AND p_response_snapshot_json IS NULL
          AND v_case.stripe_refund_id IS NOT NULL
          AND v_case.response_snapshot_json->>'status' NOT IN ('succeeded','failed','canceled')) THEN now() + interval '60 seconds'
        ELSE now() + make_interval(secs => LEAST((60 * (2 ^ LEAST(GREATEST(v_case.attempt_count, 0), 4)))::int, 900))
      END,
      locked_by = NULL,
      locked_at = NULL,
      claim_token = NULL,
      updated_at = now()
  WHERE id = p_refund_case_id
    AND status = 'processing'
    AND claim_token = p_claim_token;

  IF v_outcome = 'refunded' AND p_stripe_refund_id IS NOT NULL THEN
    INSERT INTO stripe_refunds(
      reservation_id,
      payment_id,
      refund_case_id,
      environment,
      stripe_account_id,
      stripe_refund_id,
      stripe_idempotency_key,
      amount_yen,
      status,
      payload_json
    )
    VALUES (
      v_case.reservation_id,
      v_case.payment_id,
      v_case.id,
      v_case.environment,
      v_case.stripe_account_id,
      p_stripe_refund_id,
      v_case.stripe_idempotency_key,
      v_case.amount_yen,
      'created',
      COALESCE(p_response_snapshot_json, '{}'::jsonb)
    )
    ON CONFLICT (environment, stripe_account_key, stripe_refund_id)
    DO UPDATE
    SET status = EXCLUDED.status,
        payload_json = EXCLUDED.payload_json,
        updated_at = now();

    UPDATE payments
    SET status = 'refunded',
        updated_at = now()
    WHERE id = v_case.payment_id;

    INSERT INTO ledger_entries(reservation_id, payment_id, refund_case_id, entry_type, amount_yen, currency)
    VALUES (
      v_case.reservation_id,
      v_case.payment_id,
      v_case.id,
      'refund_succeeded',
      -v_case.amount_yen,
      v_case.currency
    )
    ON CONFLICT (refund_case_id, entry_type)
    WHERE refund_case_id IS NOT NULL
    DO NOTHING;
  END IF;
END;
$$;

-- FUNCTION: mark_refund_case_result_v8(uuid, text, text, jsonb, jsonb, uuid)
CREATE FUNCTION public.mark_refund_case_result_v8(p_refund_case_id uuid, p_status text, p_stripe_refund_id text, p_response_snapshot_json jsonb, p_error_json jsonb, p_claim_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_case refund_cases%ROWTYPE;
  v_outcome text := p_status;
  v_provider_status text := lower(p_response_snapshot_json ->> 'status');
  v_existing_refund public.stripe_refunds%ROWTYPE;
  v_derived jsonb;
BEGIN
  SELECT * INTO v_case
  FROM refund_cases
  WHERE id = p_refund_case_id
    AND status = 'processing'
    AND claim_token = p_claim_token
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stale refund claim for case %', p_refund_case_id;
  END IF;

  IF p_status IS NULL OR p_status NOT IN ('refunded', 'pending', 'failed') THEN
    RAISE EXCEPTION 'invalid worker result status';
  END IF;
  IF p_status IN ('refunded', 'pending') AND (p_stripe_refund_id IS NULL OR p_stripe_refund_id = '') THEN
    RAISE EXCEPTION 'provider identity required for observed result';
  END IF;

  -- A DB-first rollout can still receive terminal claims from an old worker.
  -- Provider snapshots determine that outcome; a caller label alone can never
  -- create a successful payment or ledger entry. Keep known pending identities
  -- pollable even when the old caller incorrectly reported success.
  IF p_status = 'refunded' THEN
    IF jsonb_typeof(p_response_snapshot_json) IS DISTINCT FROM 'object'
      OR jsonb_typeof(p_response_snapshot_json->'status') IS DISTINCT FROM 'string'
      OR v_provider_status NOT IN ('pending','requires_action','succeeded','failed','canceled') THEN
      RAISE EXCEPTION 'provider status evidence required for success claim';
    END IF;
    v_outcome := CASE
      WHEN v_provider_status = 'succeeded' THEN 'refunded'
      WHEN v_provider_status IN ('failed','canceled') THEN 'failed'
      ELSE 'pending'
    END;
  END IF;

  -- ---------------------------------------------------------------------
  -- Provider refund identity is immutable. Two conflict shapes, both fatal
  -- to the case but never silent:
  --   a) the case is already bound to a different refund id (rebind attempt)
  --   b) the reported refund id is already bound to a different
  --      payment/reservation/case (cross-case absorb attempt)
  -- The case dies as 'dead' with a review row; payments/ledger stay untouched.
  -- ---------------------------------------------------------------------
  IF p_stripe_refund_id IS NOT NULL THEN
    IF v_case.stripe_refund_id IS NOT NULL AND v_case.stripe_refund_id <> p_stripe_refund_id THEN
      UPDATE refund_cases
      SET status = 'dead',
          error_json = jsonb_build_object(
            'code', 'refund_identity_conflict',
            'boundStripeRefundId', v_case.stripe_refund_id,
            'reportedStripeRefundId', p_stripe_refund_id
          ),
          locked_by = NULL, locked_at = NULL, claim_token = NULL, updated_at = now()
      WHERE id = v_case.id;
      INSERT INTO public.external_finance_reviews(
        environment, stripe_account_id, event_kind, provider_object_id,
        payment_id, reservation_id, amount_yen, currency, reason, payload_json
      ) VALUES (
        v_case.environment, v_case.stripe_account_id, 'refund_identity_conflict', p_stripe_refund_id,
        v_case.payment_id, v_case.reservation_id, v_case.amount_yen, v_case.currency,
        'case_rebind_attempt',
        jsonb_build_object(
          'refundCaseId', v_case.id,
          'boundStripeRefundId', v_case.stripe_refund_id,
          'reportedStripeRefundId', p_stripe_refund_id,
          'observedPayload', COALESCE(p_response_snapshot_json, '{}'::jsonb)
        )
      )
      ON CONFLICT (environment, stripe_account_key, event_kind, provider_object_id, reason)
      DO UPDATE SET payload_json = EXCLUDED.payload_json, updated_at = now();
      RETURN;
    END IF;

    SELECT * INTO v_existing_refund
    FROM public.stripe_refunds sr
    WHERE sr.environment = v_case.environment
      AND sr.stripe_account_key = v_case.stripe_account_key
      AND sr.stripe_refund_id = p_stripe_refund_id
    FOR UPDATE;

    IF FOUND AND (
      v_existing_refund.payment_id <> v_case.payment_id
      OR v_existing_refund.reservation_id <> v_case.reservation_id
      OR (v_existing_refund.refund_case_id IS NOT NULL AND v_existing_refund.refund_case_id <> v_case.id)
    ) THEN
      UPDATE refund_cases
      SET status = 'dead',
          error_json = jsonb_build_object(
            'code', 'refund_identity_conflict',
            'boundPaymentId', v_existing_refund.payment_id,
            'boundRefundCaseId', v_existing_refund.refund_case_id,
            'reportedStripeRefundId', p_stripe_refund_id
          ),
          locked_by = NULL, locked_at = NULL, claim_token = NULL, updated_at = now()
      WHERE id = v_case.id;
      INSERT INTO public.external_finance_reviews(
        environment, stripe_account_id, event_kind, provider_object_id,
        payment_id, reservation_id, amount_yen, currency, reason, payload_json
      ) VALUES (
        v_case.environment, v_case.stripe_account_id, 'refund_identity_conflict', p_stripe_refund_id,
        v_case.payment_id, v_case.reservation_id, v_case.amount_yen, v_case.currency,
        'case_conflict_absorb_attempt',
        jsonb_build_object(
          'refundCaseId', v_case.id,
          'boundPaymentId', v_existing_refund.payment_id,
          'boundReservationId', v_existing_refund.reservation_id,
          'boundRefundCaseId', v_existing_refund.refund_case_id,
          'reportedStripeRefundId', p_stripe_refund_id,
          'observedPayload', COALESCE(p_response_snapshot_json, '{}'::jsonb)
        )
      )
      ON CONFLICT (environment, stripe_account_key, event_kind, provider_object_id, reason)
      DO UPDATE SET payload_json = EXCLUDED.payload_json, updated_at = now();
      RETURN;
    END IF;
  END IF;

  UPDATE refund_cases
  SET status = CASE
        WHEN v_outcome = 'refunded' THEN 'refunded'
        WHEN v_outcome = 'pending' OR (v_outcome = 'failed' AND p_response_snapshot_json IS NULL
          AND v_case.stripe_refund_id IS NOT NULL
          AND v_case.response_snapshot_json->>'status' NOT IN ('succeeded','failed','canceled')) THEN 'approved'
        WHEN p_error_json->>'code' = 'provider_request_reconciliation_required' THEN 'dead'
        WHEN v_outcome = 'failed' AND p_response_snapshot_json->>'status' IN ('failed','canceled') THEN 'failed'
        WHEN v_case.attempt_count >= 5 THEN 'dead'
        ELSE 'approved'
      END,
      stripe_refund_id = COALESCE(p_stripe_refund_id, stripe_refund_id),
      response_snapshot_json = COALESCE(p_response_snapshot_json, response_snapshot_json),
      error_json = p_error_json,
      next_attempt_at = CASE
        WHEN v_outcome = 'refunded' THEN next_attempt_at
        WHEN v_outcome = 'pending' OR (v_outcome = 'failed' AND p_response_snapshot_json IS NULL
          AND v_case.stripe_refund_id IS NOT NULL
          AND v_case.response_snapshot_json->>'status' NOT IN ('succeeded','failed','canceled')) THEN now() + interval '60 seconds'
        ELSE now() + make_interval(secs => LEAST((60 * (2 ^ LEAST(GREATEST(v_case.attempt_count, 0), 4)))::int, 900))
      END,
      locked_by = NULL,
      locked_at = NULL,
      claim_token = NULL,
      updated_at = now()
  WHERE id = p_refund_case_id
    AND status = 'processing'
    AND claim_token = p_claim_token;

  -- ---------------------------------------------------------------------
  -- Persist the provider-observed refund row for every state that carries a
  -- provider identity: succeeded, pending (in-flight reservation of funds)
  -- and provider-confirmed failed/canceled. Status mirrors the snapshot.
  -- ---------------------------------------------------------------------
  IF p_stripe_refund_id IS NOT NULL AND (
    v_outcome = 'refunded'
    OR v_outcome = 'pending'
    OR (v_outcome = 'failed' AND v_provider_status IN ('failed','canceled'))
  ) THEN
    INSERT INTO stripe_refunds(
      reservation_id,
      payment_id,
      refund_case_id,
      environment,
      stripe_account_id,
      stripe_refund_id,
      stripe_idempotency_key,
      stripe_charge_id,
      amount_yen,
      status,
      origin,
      payload_json
    )
    SELECT
      v_case.reservation_id,
      v_case.payment_id,
      v_case.id,
      v_case.environment,
      v_case.stripe_account_id,
      p_stripe_refund_id,
      v_case.stripe_idempotency_key,
      NULLIF(btrim(COALESCE(p_response_snapshot_json ->> 'charge', '')), ''),
      v_case.amount_yen,
      COALESCE(v_provider_status, CASE WHEN v_outcome = 'refunded' THEN 'succeeded' ELSE v_outcome END),
      'internal',
      COALESCE(p_response_snapshot_json, '{}'::jsonb)
    ON CONFLICT (environment, stripe_account_key, stripe_refund_id)
    DO UPDATE
    SET status = EXCLUDED.status,
        payload_json = EXCLUDED.payload_json,
        refund_case_id = COALESCE(stripe_refunds.refund_case_id, EXCLUDED.refund_case_id),
        stripe_charge_id = COALESCE(stripe_refunds.stripe_charge_id, EXCLUDED.stripe_charge_id),
        updated_at = now();
    -- Identity was pre-verified above, so this conflict update can only touch
    -- a row owned by this same case/payment (trigger enforces immutability).
  END IF;

  IF v_outcome = 'refunded' AND v_provider_status = 'succeeded' AND p_stripe_refund_id IS NOT NULL THEN
    INSERT INTO ledger_entries(reservation_id, payment_id, refund_case_id, entry_type, amount_yen, currency, stripe_refund_id)
    VALUES (
      v_case.reservation_id,
      v_case.payment_id,
      v_case.id,
      'refund_succeeded',
      -v_case.amount_yen,
      v_case.currency,
      p_stripe_refund_id
    )
    ON CONFLICT DO NOTHING;
    -- Dedupes on uq_ledger_refund_entry (refund_case_id, entry_type) and on
    -- uq_ledger_stripe_refund_v8 (provider identity) — whichever fires first.
  END IF;

  -- payments.status is derived from the whole provider refund set, never set
  -- to a flat 'refunded'. A provider-confirmed failure re-derives (e.g. back
  -- to 'partially_refunded' or 'succeeded') instead of leaving stale state.
  v_derived := public.derive_vip_payment_refund_state_v8(v_case.payment_id);
  UPDATE payments
  SET status = (v_derived ->> 'derivedStatus')::public.payment_status,
      updated_at = now()
  WHERE id = v_case.payment_id
    AND status::text IN ('succeeded','refund_pending','refunded','partially_refunded')
    AND status::text IS DISTINCT FROM v_derived ->> 'derivedStatus';
END;
$$;

-- FUNCTION: mark_reservation_hold_finalized_v7(uuid, text, text, text, text, text, text, text, jsonb, uuid)
CREATE FUNCTION public.mark_reservation_hold_finalized_v7(p_hold_request_id uuid, p_provider_object_type text, p_provider_object_id text, p_provider_status text, p_environment text, p_stripe_customer_id text, p_stripe_account_id text, p_client_secret_ciphertext text, p_response_snapshot_json jsonb, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_hold reservation_hold_requests%ROWTYPE;
  v_result jsonb;
BEGIN
  SELECT * INTO v_hold
  FROM reservation_hold_requests
  WHERE id = p_hold_request_id
    AND status = 'finalize_retry'
    AND claim_token = p_claim_token
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stale reservation hold finalizer claim for hold request %', p_hold_request_id;
  END IF;

  SELECT finalize_public_reservation_hold_stripe_v7(
    v_hold.source_system,
    v_hold.idempotency_key,
    v_hold.request_hash,
    p_stripe_customer_id,
    p_environment,
    p_stripe_account_id,
    p_provider_object_type,
    p_provider_object_id,
    p_provider_status,
    p_client_secret_ciphertext,
    p_response_snapshot_json
  )
  INTO v_result;

  UPDATE reservation_hold_requests
  SET locked_by = NULL,
      locked_at = NULL,
      claim_token = NULL,
      updated_at = now()
  WHERE id = p_hold_request_id;

  RETURN v_result;
END;
$$;

-- FUNCTION: mark_reservation_hold_finalizer_retry_v7(uuid, text, text, uuid)
CREATE FUNCTION public.mark_reservation_hold_finalizer_retry_v7(p_hold_request_id uuid, p_error_code text, p_error_message text, p_claim_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_attempt int;
  v_delay_seconds int;
BEGIN
  SELECT finalize_attempts INTO v_attempt
  FROM reservation_hold_requests
  WHERE id = p_hold_request_id
    AND status = 'finalize_retry'
    AND claim_token = p_claim_token
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stale reservation hold finalizer claim for hold request %', p_hold_request_id;
  END IF;

  IF v_attempt >= 6 THEN
    UPDATE reservation_hold_requests
    SET status = 'manual_review',
        last_error_code = p_error_code,
        last_error_message = p_error_message,
        locked_by = NULL,
        locked_at = NULL,
        claim_token = NULL,
        next_attempt_at = NULL,
        updated_at = now()
    WHERE id = p_hold_request_id
      AND status = 'finalize_retry'
      AND claim_token = p_claim_token;
  ELSE
    v_delay_seconds := LEAST((30 * (2 ^ GREATEST(v_attempt, 0)))::int, 900);

    UPDATE reservation_hold_requests
    SET status = 'finalize_retry',
        last_error_code = p_error_code,
        last_error_message = p_error_message,
        locked_by = NULL,
        locked_at = NULL,
        claim_token = NULL,
        next_attempt_at = now() + make_interval(secs => v_delay_seconds),
        updated_at = now()
    WHERE id = p_hold_request_id
      AND status = 'finalize_retry'
      AND claim_token = p_claim_token;
  END IF;
END;
$$;

-- FUNCTION: mark_transactional_email_job_outcome_v29(uuid, uuid, text, text, text, text, text, integer)
CREATE FUNCTION public.mark_transactional_email_job_outcome_v29(p_job_id uuid, p_claim_token uuid, p_provider_name text, p_payload_hash text, p_outcome text, p_provider_message_id text, p_safe_category text, p_retry_after_ms integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_job public.transactional_email_jobs%ROWTYPE;
  v_action text;
BEGIN
  IF p_job_id IS NULL OR p_claim_token IS NULL
    OR p_provider_name NOT IN ('fake', 'resend')
    OR p_payload_hash !~ '^[0-9a-f]{64}$'
    OR p_outcome NOT IN ('accepted', 'retryable', 'permanent', 'configuration')
    OR p_safe_category IS NULL OR char_length(p_safe_category) NOT BETWEEN 1 AND 128
    OR p_safe_category ~ E'[\\r\\n]'
    OR (p_retry_after_ms IS NOT NULL AND p_retry_after_ms NOT BETWEEN 0 AND 86400000)
  THEN
    RAISE EXCEPTION 'invalid transactional email outcome';
  END IF;
  SELECT * INTO v_job FROM public.lock_transactional_email_job_v33(p_job_id);
  IF NOT FOUND OR v_job.state <> 'processing'
    OR v_job.claim_token <> p_claim_token
    OR v_job.lease_expires_at <= v_now
    OR v_job.provider_name <> p_provider_name
    OR v_job.payload_hash IS DISTINCT FROM p_payload_hash
  THEN
    RAISE EXCEPTION 'stale transactional email claim';
  END IF;

  IF p_outcome = 'accepted' THEN
    IF p_provider_message_id IS NULL OR char_length(p_provider_message_id) NOT BETWEEN 1 AND 256
      OR p_provider_message_id ~ E'[\\r\\n]'
    THEN
      RAISE EXCEPTION 'accepted transactional email lacks safe provider message id';
    END IF;
    UPDATE public.transactional_email_jobs
    SET state = 'accepted', provider_message_id = p_provider_message_id,
        provider_delivery_state = 'accepted', provider_state_precedence = 40,
        provider_state_occurred_at = v_now, accepted_at = v_now,
        safe_error_category = NULL,
        claimed_by = NULL, claim_token = NULL, claimed_at = NULL,
        lease_expires_at = NULL, updated_at = v_now
    WHERE id = v_job.id;
    UPDATE public.ticket_wallet_otp_challenges
    SET state = 'sent', sent_at = COALESCE(sent_at, v_now), updated_at = v_now
    WHERE id = v_job.otp_challenge_id AND state IN ('pending', 'sending', 'sent');
    v_action := 'accepted';
  ELSIF p_outcome = 'retryable' THEN
    IF v_job.attempt_count >= v_job.maximum_attempts THEN
      UPDATE public.transactional_email_jobs
      SET state = 'dead', safe_error_category = p_safe_category,
          terminal_at = v_now, completed_at = v_now,
          claimed_by = NULL, claim_token = NULL, claimed_at = NULL,
          lease_expires_at = NULL, updated_at = v_now
      WHERE id = v_job.id;
      IF NOT EXISTS (
        SELECT 1 FROM public.transactional_email_jobs AS other_job
        WHERE other_job.otp_challenge_id = v_job.otp_challenge_id
          AND other_job.id <> v_job.id
          AND (
            other_job.state = 'accepted'
            OR other_job.state IN ('pending', 'processing')
            OR (other_job.state = 'retry'
              AND other_job.attempt_count < other_job.maximum_attempts)
          )
      ) THEN
        UPDATE public.ticket_wallet_otp_challenges
        SET state = 'failed', code_ciphertext = NULL,
            terminal_at = v_now, updated_at = v_now
        WHERE id = v_job.otp_challenge_id
          AND state IN ('pending', 'sending', 'sent');
      ELSIF EXISTS (
        SELECT 1 FROM public.transactional_email_jobs AS accepted_job
        WHERE accepted_job.otp_challenge_id = v_job.otp_challenge_id
          AND accepted_job.id <> v_job.id
          AND accepted_job.state = 'accepted'
      ) THEN
        UPDATE public.ticket_wallet_otp_challenges
        SET state = 'sent', updated_at = v_now
        WHERE id = v_job.otp_challenge_id
          AND state IN ('pending', 'sending', 'sent');
      ELSE
        UPDATE public.ticket_wallet_otp_challenges
        SET state = 'pending', updated_at = v_now
        WHERE id = v_job.otp_challenge_id
          AND state IN ('pending', 'sending', 'sent');
      END IF;
      v_action := 'dead';
    ELSE
      UPDATE public.transactional_email_jobs
      SET state = 'retry', safe_error_category = p_safe_category,
          next_attempt_at = v_now + make_interval(
            secs => GREATEST(1, CEIL(COALESCE(p_retry_after_ms, 1000) / 1000.0)::integer)),
          claimed_by = NULL, claim_token = NULL, claimed_at = NULL,
          lease_expires_at = NULL, updated_at = v_now
      WHERE id = v_job.id;
      UPDATE public.ticket_wallet_otp_challenges
      SET state = 'pending', updated_at = v_now
      WHERE id = v_job.otp_challenge_id AND state IN ('pending', 'sending', 'sent');
      v_action := 'retry';
    END IF;
  ELSE
    v_action := CASE WHEN p_outcome = 'permanent' THEN 'dead' ELSE 'configuration' END;
    UPDATE public.transactional_email_jobs
    SET state = v_action, safe_error_category = p_safe_category,
        terminal_at = v_now, completed_at = v_now,
        claimed_by = NULL, claim_token = NULL, claimed_at = NULL,
        lease_expires_at = NULL, updated_at = v_now
    WHERE id = v_job.id;
    IF NOT EXISTS (
      SELECT 1 FROM public.transactional_email_jobs AS other_job
      WHERE other_job.otp_challenge_id = v_job.otp_challenge_id
        AND other_job.id <> v_job.id
        AND (
          other_job.state = 'accepted'
          OR other_job.state IN ('pending', 'processing')
          OR (other_job.state = 'retry'
            AND other_job.attempt_count < other_job.maximum_attempts)
        )
    ) THEN
      UPDATE public.ticket_wallet_otp_challenges
      SET state = 'failed', code_ciphertext = NULL,
          terminal_at = v_now, updated_at = v_now
      WHERE id = v_job.otp_challenge_id
        AND state IN ('pending', 'sending', 'sent');
    ELSIF EXISTS (
      SELECT 1 FROM public.transactional_email_jobs AS accepted_job
      WHERE accepted_job.otp_challenge_id = v_job.otp_challenge_id
        AND accepted_job.id <> v_job.id
        AND accepted_job.state = 'accepted'
    ) THEN
      UPDATE public.ticket_wallet_otp_challenges
      SET state = 'sent', updated_at = v_now
      WHERE id = v_job.otp_challenge_id
        AND state IN ('pending', 'sending', 'sent');
    ELSE
      UPDATE public.ticket_wallet_otp_challenges
      SET state = 'pending', updated_at = v_now
      WHERE id = v_job.otp_challenge_id
        AND state IN ('pending', 'sending', 'sent');
    END IF;
    IF p_outcome = 'configuration' THEN
      INSERT INTO public.transactional_email_provider_circuits(
        provider_name, is_open, safe_reason, opened_at, open_until, updated_at
      ) VALUES (
        p_provider_name, true, p_safe_category, v_now, v_now + interval '15 minutes', v_now
      )
      ON CONFLICT (provider_name) DO UPDATE
      SET is_open = true, safe_reason = EXCLUDED.safe_reason,
          opened_at = EXCLUDED.opened_at, open_until = EXCLUDED.open_until,
          updated_at = EXCLUDED.updated_at;
    END IF;
  END IF;
  -- Daily quota is not a per-second throttle. Stop every dispatcher until
  -- the provider's UTC day resets; monthly exhaustion requires operator review.
  -- Preserve longer/indefinite circuits opened by another in-flight result.
  IF p_provider_name = 'resend'
    AND ((p_outcome = 'retryable' AND p_safe_category = 'daily_quota_exceeded')
      OR (p_outcome = 'configuration' AND p_safe_category = 'monthly_quota_exceeded'))
  THEN
    INSERT INTO public.transactional_email_provider_circuits(
      provider_name, is_open, safe_reason, opened_at, open_until, updated_at
    ) VALUES (
      p_provider_name, true, p_safe_category, v_now,
      CASE WHEN p_safe_category = 'monthly_quota_exceeded' THEN NULL
        ELSE (date_trunc('day', v_now AT TIME ZONE 'UTC') + interval '1 day') AT TIME ZONE 'UTC' END,
      v_now
    )
    ON CONFLICT (provider_name) DO UPDATE
    SET is_open = true, safe_reason = EXCLUDED.safe_reason,
        opened_at = EXCLUDED.opened_at,
        open_until = CASE
          WHEN EXCLUDED.open_until IS NULL OR
            (transactional_email_provider_circuits.is_open AND transactional_email_provider_circuits.open_until IS NULL)
          THEN NULL
          ELSE GREATEST(transactional_email_provider_circuits.open_until, EXCLUDED.open_until) END,
        updated_at = EXCLUDED.updated_at;
  END IF;
  RETURN jsonb_build_object('action', v_action);
END;
$_$;

-- FUNCTION: mark_webhook_event_ignored_v7(uuid, text, uuid)
CREATE FUNCTION public.mark_webhook_event_ignored_v7(p_event_id uuid, p_ignored_reason text, p_claim_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE webhook_events
  SET processing_status = 'ignored',
      ignored_reason = p_ignored_reason,
      locked_by = NULL,
      locked_at = NULL,
      claim_token = NULL,
      updated_at = now()
  WHERE id = p_event_id
    AND processing_status = 'processing'
    AND claim_token = p_claim_token;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stale webhook claim for event %', p_event_id;
  END IF;
END;
$$;

-- FUNCTION: mark_webhook_event_processed_v7(uuid, uuid)
CREATE FUNCTION public.mark_webhook_event_processed_v7(p_event_id uuid, p_claim_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE webhook_events
  SET processing_status = 'processed',
      locked_by = NULL,
      locked_at = NULL,
      claim_token = NULL,
      updated_at = now()
  WHERE id = p_event_id
    AND processing_status = 'processing'
    AND claim_token = p_claim_token;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stale webhook claim for event %', p_event_id;
  END IF;
END;
$$;

-- FUNCTION: mark_webhook_event_retry_v7(uuid, text, jsonb, uuid)
CREATE FUNCTION public.mark_webhook_event_retry_v7(p_event_id uuid, p_error_code text, p_error_json jsonb, p_claim_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_attempt int;
  v_delay_seconds int;
BEGIN
  SELECT attempt_count INTO v_attempt
  FROM webhook_events
  WHERE id = p_event_id
    AND processing_status = 'processing'
    AND claim_token = p_claim_token
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stale webhook claim for event %', p_event_id;
  END IF;

  IF v_attempt >= 10 THEN
    UPDATE webhook_events
    SET processing_status = 'dead',
        last_error_code = p_error_code,
        error_json = p_error_json,
        locked_by = NULL,
        locked_at = NULL,
        claim_token = NULL,
        updated_at = now()
    WHERE id = p_event_id
      AND processing_status = 'processing'
      AND claim_token = p_claim_token;
  ELSE
    v_delay_seconds := LEAST((30 * (2 ^ GREATEST(v_attempt, 0)))::int, 900);

    UPDATE webhook_events
    SET processing_status = 'retry',
        last_error_code = p_error_code,
        error_json = p_error_json,
        next_attempt_at = now() + make_interval(secs => v_delay_seconds),
        locked_by = NULL,
        locked_at = NULL,
        claim_token = NULL,
        updated_at = now()
    WHERE id = p_event_id
      AND processing_status = 'processing'
      AND claim_token = p_claim_token;
  END IF;
END;
$$;

-- FUNCTION: materialize_ticket_entry_v53(uuid, uuid, text, text, text, uuid, text, text, text, text)
CREATE FUNCTION public.materialize_ticket_entry_v53(p_order uuid, p_event uuid, p_environment text, p_origin text, p_account text, p_link uuid, p_verifier text, p_ciphertext text, p_from text, p_reply text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o public.ticket_orders%ROWTYPE; closing timestamptz; j uuid;
BEGIN
 PERFORM public.ticket_wallet_gate_fence_v30();
 SELECT * INTO o FROM public.ticket_orders WHERE id=p_order FOR UPDATE;
 IF NOT FOUND OR o.admission_policy<>'order_together_v1' OR o.environment IS DISTINCT FROM p_environment
  OR o.event_session_id IS DISTINCT FROM p_event OR o.stripe_account_key IS DISTINCT FROM p_account
  OR NOT public.ticket_order_has_settled_payment_v30(o.id) THEN RETURN jsonb_build_object('action','rejected'); END IF;
 PERFORM 1 FROM public.ticket_purchase_notices WHERE ticket_order_id=o.id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('action','rejected'); END IF;
 IF EXISTS(SELECT 1 FROM public.ticket_purchase_notices WHERE ticket_order_id=o.id AND materialized_at IS NOT NULL)
  OR EXISTS(SELECT 1 FROM public.ticket_order_entry_links WHERE ticket_order_id=o.id)
 THEN RETURN jsonb_build_object('action','reused'); END IF;
 SELECT public.ticket_admission_execution_closes_v56(id) INTO closing FROM public.ticket_event_sessions WHERE id=o.event_session_id;
 IF closing<=clock_timestamp() THEN RETURN jsonb_build_object('action','rejected'); END IF;
 INSERT INTO public.ticket_order_entry_links(id,ticket_order_id,generation,environment,public_origin,stripe_account_key,event_session_id,token_verifier,secret_ciphertext,expires_at)
 VALUES(p_link,o.id,1,o.environment,p_origin,o.stripe_account_key,o.event_session_id,p_verifier,p_ciphertext,closing);
 j:=public.queue_ticket_entry_delivery_v53(p_link,p_from,p_reply);
 UPDATE public.ticket_purchase_notices SET materialized_at=clock_timestamp() WHERE ticket_order_id=o.id;
 RETURN jsonb_build_object('action','materialized','emailJobId',j);
END $$;

-- FUNCTION: materialize_ticket_event_session_v27(uuid, text, date, text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, text)
CREATE FUNCTION public.materialize_ticket_event_session_v27(p_event_day_id uuid, p_catalog_event_id text, p_event_date date, p_environment text, p_stripe_account_id text, p_venue_timezone text, p_door_at timestamp with time zone, p_close_at timestamp with time zone, p_admission_opens_at timestamp with time zone, p_admission_closes_at timestamp with time zone, p_sales_check_in_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_event_day public.event_days%ROWTYPE;
  v_session public.ticket_event_sessions%ROWTYPE;
  v_inserted integer := 0;
  v_bound integer := 0;
BEGIN
  IF p_event_day_id IS NULL
    OR NULLIF(btrim(COALESCE(p_catalog_event_id, '')), '') IS NULL
    OR p_event_date IS NULL
    OR COALESCE(p_environment, '') NOT IN ('test', 'live')
    OR p_venue_timezone <> 'Asia/Tokyo'
    OR p_door_at IS NULL OR p_close_at IS NULL
    OR p_admission_opens_at IS NULL OR p_admission_closes_at IS NULL
    OR NOT (
      p_admission_opens_at <= p_door_at
      AND p_door_at < p_close_at
      AND p_close_at <= p_admission_closes_at
    )
    OR COALESCE(p_sales_check_in_mode, '') NOT IN ('legacy_qr', 'wallet_swipe')
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'event_session_input_invalid');
  END IF;

  SELECT * INTO v_event_day
  FROM public.event_days
  WHERE id = p_event_day_id
  FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'not_found', 'reason', 'event_day_not_found');
  END IF;
  IF v_event_day.business_date <> p_event_date
    OR v_event_day.venue_timezone <> p_venue_timezone
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'event_day_mismatch');
  END IF;

  -- Read the common replay path before attempting an INSERT. An unconditional
  -- INSERT ... ON CONFLICT takes a stronger conflicting tuple lock even when
  -- the Event Session already exists; that can deadlock with a checkout that
  -- holds the Session's FK KEY SHARE while waiting for this Event Day. The Day
  -- lock serializes materializers, while NO KEY UPDATE remains compatible with
  -- checkout/action FK validation.
  SELECT * INTO v_session
  FROM public.ticket_event_sessions AS session
  WHERE session.environment = p_environment
    AND session.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
    AND session.catalog_event_id = btrim(p_catalog_event_id)
  FOR NO KEY UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.ticket_event_sessions(
      event_day_id, catalog_event_id, event_date, environment,
      stripe_account_id, venue_timezone, door_at, close_at,
      admission_opens_at, admission_closes_at, sales_check_in_mode
    ) VALUES (
      p_event_day_id, btrim(p_catalog_event_id), p_event_date, p_environment,
      p_stripe_account_id, p_venue_timezone, p_door_at, p_close_at,
      p_admission_opens_at, p_admission_closes_at, p_sales_check_in_mode
    )
    ON CONFLICT ON CONSTRAINT uq_ticket_event_sessions_natural_v27 DO NOTHING
    RETURNING * INTO v_session;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;

    -- Defensive fallback for a writer outside this Day-serialized RPC.
    IF v_inserted = 0 THEN
      SELECT * INTO v_session
      FROM public.ticket_event_sessions AS session
      WHERE session.environment = p_environment
        AND session.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
        AND session.catalog_event_id = btrim(p_catalog_event_id)
      FOR NO KEY UPDATE;
    END IF;
  END IF;

  IF v_session.id IS NULL THEN
    RAISE EXCEPTION 'Ticket Event Session materialization conflict disappeared';
  END IF;

  IF v_inserted = 0 THEN
    IF v_session.event_day_id IS DISTINCT FROM p_event_day_id THEN
      RETURN jsonb_build_object('action', 'conflict', 'reason', 'event_session_facts_conflict');
    END IF;

    IF v_session.event_day_id <> p_event_day_id
      OR v_session.event_date <> p_event_date
      OR v_session.venue_timezone <> p_venue_timezone
      OR v_session.door_at <> p_door_at
      OR v_session.close_at <> p_close_at
      OR v_session.admission_opens_at <> p_admission_opens_at
      OR v_session.admission_closes_at <> p_admission_closes_at
      OR v_session.sales_check_in_mode <> p_sales_check_in_mode
    THEN
      RETURN jsonb_build_object(
        'action', 'conflict', 'reason', 'event_session_facts_conflict',
        'eventSessionId', v_session.id,
        'policyVersion', v_session.policy_version
      );
    END IF;
  END IF;

  -- Materialization may bind pre-v27 legacy orders with an exact immutable
  -- tuple. It never changes their sold mode snapshot.
  PERFORM 1
  FROM public.ticket_orders AS ticket_order
  WHERE ticket_order.event_session_id IS NULL
    AND ticket_order.check_in_mode = 'legacy_qr'
    AND ticket_order.event_id = v_session.catalog_event_id
    AND ticket_order.event_date = v_session.event_date
    AND ticket_order.environment = v_session.environment
    AND ticket_order.stripe_account_key = v_session.stripe_account_key
  ORDER BY ticket_order.id
  FOR UPDATE;

  UPDATE public.ticket_orders AS ticket_order
  SET event_session_id = v_session.id
  WHERE ticket_order.event_session_id IS NULL
    AND ticket_order.check_in_mode = 'legacy_qr'
    AND ticket_order.event_id = v_session.catalog_event_id
    AND ticket_order.event_date = v_session.event_date
    AND ticket_order.environment = v_session.environment
    AND ticket_order.stripe_account_key = v_session.stripe_account_key;
  GET DIAGNOSTICS v_bound = ROW_COUNT;

  RETURN jsonb_build_object(
    'action', CASE WHEN v_inserted = 1 THEN 'created' ELSE 'reused' END,
    'eventSessionId', v_session.id,
    'policyVersion', v_session.policy_version,
    'salesCheckInMode', v_session.sales_check_in_mode,
    'salesState', v_session.sales_state,
    'admissionState', v_session.admission_state,
    'enabled', v_session.enabled,
    'legacyOrdersBound', v_bound
  );
END;
$$;

-- FUNCTION: materialize_ticket_purchase_notices_v33(text, text, text, integer)
CREATE FUNCTION public.materialize_ticket_purchase_notices_v33(p_from text, p_reply_to text, p_wallet_url text, p_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE r record; j uuid; n integer:=0; at timestamptz:=clock_timestamp();
BEGIN
 IF p_limit NOT BETWEEN 1 AND 100 OR NULLIF(btrim(p_from),'') IS NULL OR char_length(p_from)>320 OR p_from ~ E'[\r\n]'
 OR (p_reply_to IS NOT NULL AND (char_length(p_reply_to) NOT BETWEEN 1 AND 320 OR p_reply_to ~ E'[\r\n]'))
 OR p_wallet_url !~ '^https://[^[:space:]?#]+/tickets/wallet$' THEN RAISE EXCEPTION 'invalid purchase notice configuration'; END IF;
 FOR r IN SELECT o.*,i.created_at AS notice_created_at FROM public.ticket_orders o JOIN public.ticket_purchase_notices i ON i.ticket_order_id=o.id
 WHERE o.admission_policy='individual_v1' AND i.materialized_at IS NULL AND o.purchaser_email_ciphertext IS NOT NULL AND o.purchaser_email_hash IS NOT NULL
 ORDER BY i.created_at,o.id LIMIT p_limit FOR UPDATE OF o,i SKIP LOCKED LOOP
  IF r.check_in_mode='legacy_qr' THEN
   INSERT INTO public.notification_jobs(ticket_order_id,channel,status,payload_json)
   VALUES(r.id,'email','pending','{"template":"ticket_admission","schemaVersion":"ghost.ticket-email.v1"}');
  ELSE
   j:=gen_random_uuid();
   INSERT INTO public.transactional_email_jobs(id,ticket_order_id,purpose,provider_idempotency_key,recipient_email_hash,recipient_email_ciphertext,render_data_json,next_attempt_at,created_at,updated_at)
   VALUES(j,r.id,'ticket_wallet_purchase','ghost-ticket-purchase-v1-'||r.id,r.purchaser_email_hash,r.purchaser_email_ciphertext,
    jsonb_build_object('template','ticket_wallet_purchase','templateVersion','ghost.ticket-wallet-purchase.v2','notificationJobId',j,
     'renderReferenceAt',to_char(at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
     'expiresAt',to_char((r.notice_created_at+interval '7 days') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
     'from',p_from,'replyTo',p_reply_to,'walletUrl',p_wallet_url,'publicCode',r.public_code,
     'eventTitle',r.event_title,'demoAdmissionTest',EXISTS(SELECT 1 FROM public.ticket_demo_admission_windows_v56 w WHERE w.event_session_id=r.event_session_id AND r.environment='test'),
   'eventDate',r.event_date,'totalQuantity',r.total_quantity,'commercial',r.items_json->0->'commercial'),at,at,at) ON CONFLICT DO NOTHING;
  END IF;
  UPDATE public.ticket_purchase_notices SET materialized_at=at WHERE ticket_order_id=r.id;
  n:=n+1;
 END LOOP;
 RETURN n;
END; $_$;

-- FUNCTION: persist_ticket_purchase_notice_v33()
CREATE FUNCTION public.persist_ticket_purchase_notice_v33() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NEW.status='fulfilled' AND NEW.fulfilled_at IS NOT NULL THEN
  INSERT INTO public.ticket_purchase_notices(ticket_order_id) VALUES (NEW.id) ON CONFLICT DO NOTHING;
  IF NEW.check_in_mode='legacy_qr' AND NEW.purchaser_email_ciphertext IS NOT NULL THEN
   INSERT INTO public.notification_jobs(ticket_order_id,channel,status,payload_json)
   VALUES(NEW.id,'email','pending','{"template":"ticket_admission","schemaVersion":"ghost.ticket-email.v1"}');
   UPDATE public.ticket_purchase_notices SET materialized_at=clock_timestamp() WHERE ticket_order_id=NEW.id;
  END IF;
 END IF;
 RETURN NEW;
END; $$;

-- FUNCTION: preclaim_admin_action_request_v8(uuid, text, text, text)
CREATE FUNCTION public.preclaim_admin_action_request_v8(p_actor_admin_id uuid, p_action text, p_idempotency_key text, p_request_hash text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action text := btrim(COALESCE(p_action, ''));
  v_idempotency_key text := btrim(COALESCE(p_idempotency_key, ''));
  v_request_hash text := btrim(COALESCE(p_request_hash, ''));
  v_existing public.admin_action_requests%ROWTYPE;
  v_inserted int;
BEGIN
  IF p_actor_admin_id IS NULL
    OR v_action = ''
    OR v_idempotency_key = ''
    OR v_request_hash = ''
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object(
          'field', CASE
            WHEN p_actor_admin_id IS NULL THEN 'actorAdminId'
            WHEN v_action = '' THEN 'action'
            WHEN v_idempotency_key = '' THEN 'idempotencyKey'
            ELSE 'requestHash'
          END
        )
      )
    );
  END IF;

  -- Compatibility triggers use this transaction-local marker to avoid
  -- duplicating the explicit history/audit rows written by v8 commands.
  PERFORM set_config('ghost.vip_floor_v8_writer', 'on', true);

  INSERT INTO public.admin_action_requests(
    actor_admin_id,
    action,
    idempotency_key,
    request_hash,
    response_json
  )
  VALUES (
    p_actor_admin_id,
    v_action,
    v_idempotency_key,
    v_request_hash,
    NULL
  )
  ON CONFLICT (actor_admin_id, action, idempotency_key) DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted = 1 THEN
    RETURN jsonb_build_object('action', 'claimed');
  END IF;

  SELECT *
  INTO v_existing
  FROM public.admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = v_action
    AND idempotency_key = v_idempotency_key
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = 'XX000',
      MESSAGE = 'VIP floor idempotency row disappeared after conflict';
  END IF;

  IF v_existing.request_hash <> v_request_hash THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'IDEMPOTENCY_MISMATCH',
        'details', jsonb_build_object('reason', 'request_hash_mismatch')
      )
    );
  END IF;

  IF v_existing.response_json IS NULL THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'IDEMPOTENCY_IN_PROGRESS',
        'details', jsonb_build_object('reason', 'response_not_committed')
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'action', 'reused',
    'response', jsonb_set(v_existing.response_json, '{reused}', 'true'::jsonb, true)
  );
END;
$$;

-- FUNCTION: prepare_ticket_admission_v30(text, uuid, text, text, text, uuid[], text)
CREATE FUNCTION public.prepare_ticket_admission_v30(p_environment text, p_wallet_session_id uuid, p_session_token_verifier text, p_prepare_idempotency_key_hash text, p_request_hash text, p_admission_ids uuid[], p_challenge_token_verifier text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_admission_ids uuid[];
  v_input_count integer;
  v_distinct_count integer;
  v_existing_operation_id uuid;
  v_candidate record;
  v_operation public.ticket_admission_operations%ROWTYPE;
  v_wallet_session public.ticket_wallet_sessions%ROWTYPE;
  v_event_day public.event_days%ROWTYPE;
  v_event_session public.ticket_event_sessions%ROWTYPE;
  v_ticket_order public.ticket_orders%ROWTYPE;
  v_challenge public.ticket_admission_challenges%ROWTYPE;
  v_is_new boolean := false;
  v_inserted integer := 0;
  v_selected integer := 0;
  v_wrong_order integer := 0;
  v_not_issued integer := 0;
  v_result jsonb;
BEGIN
  SELECT
    COALESCE(array_agg(admission_id ORDER BY admission_id), '{}'::uuid[]),
    count(*)::integer,
    count(DISTINCT admission_id)::integer
  INTO v_admission_ids, v_input_count, v_distinct_count
  FROM unnest(COALESCE(p_admission_ids, '{}'::uuid[])) AS selected(admission_id);

  IF COALESCE(p_environment, '') NOT IN ('test', 'live')
    OR p_wallet_session_id IS NULL
    OR NULLIF(btrim(COALESCE(p_session_token_verifier, '')), '') IS NULL
    OR char_length(p_session_token_verifier) > 512
    OR NULLIF(btrim(COALESCE(p_prepare_idempotency_key_hash, '')), '') IS NULL
    OR char_length(p_prepare_idempotency_key_hash) > 200
    OR NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL
    OR char_length(p_request_hash) > 200
    OR NULLIF(btrim(COALESCE(p_challenge_token_verifier, '')), '') IS NULL
    OR char_length(p_challenge_token_verifier) > 512
    OR v_input_count NOT BETWEEN 1 AND 20
    OR v_distinct_count <> v_input_count
    OR array_position(v_admission_ids, NULL) IS NOT NULL
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'admission_prepare_invalid');
  END IF;

  -- Authentication is checked non-lockingly before an Operation is created so
  -- an invalid bearer cannot leave an orphan initializing row. Authority is
  -- checked again after Operation -> Wallet Session locks are held.
  SELECT * INTO v_wallet_session
  FROM public.ticket_wallet_sessions
  WHERE id = p_wallet_session_id
    AND environment = p_environment;
  IF NOT FOUND
    OR v_wallet_session.identity_email_hash IS NULL
    OR v_wallet_session.revoked_at IS NOT NULL
    OR v_wallet_session.expires_at <= v_now
    OR NOT public.ticket_auth_digest_equal_v29(
      v_wallet_session.token_verifier, p_session_token_verifier)
  THEN
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;

  -- Resolve an existing idempotency aggregate before looking at caller-selected
  -- Admissions. This makes same-key/different-request a conflict even when the
  -- retry payload contains unknown IDs.
  SELECT operation.id INTO v_existing_operation_id
  FROM public.ticket_admission_operations AS operation
  WHERE operation.wallet_session_id = p_wallet_session_id
    AND operation.prepare_idempotency_key_hash = btrim(p_prepare_idempotency_key_hash);

  IF v_existing_operation_id IS NOT NULL THEN
    SELECT * INTO v_operation
    FROM public.ticket_admission_operations
    WHERE id = v_existing_operation_id
    FOR UPDATE;
  ELSE
    -- This lookup selects only a candidate serialization aggregate. It is never
    -- admission authority; all values are re-read after the Operation lock.
    SELECT
      ticket_order.id AS ticket_order_id,
      ticket_order.event_session_id,
      event_session.event_day_id,
      ticket_order.environment,
      ticket_order.stripe_account_id,
      ticket_order.check_in_mode,
      ticket_order.admission_version,
      ticket_order.event_title,
      ticket_order.event_date,
      event_session.policy_version
    INTO v_candidate
    FROM public.ticket_admissions AS admission
    JOIN public.ticket_orders AS ticket_order
      ON ticket_order.id = admission.ticket_order_id
    JOIN public.ticket_event_sessions AS event_session
      ON event_session.id = ticket_order.event_session_id
     AND event_session.environment = ticket_order.environment
     AND event_session.stripe_account_key = ticket_order.stripe_account_key
    WHERE admission.id = v_admission_ids[1];

    IF NOT FOUND THEN
      RETURN jsonb_build_object('action', 'rejected', 'reason', 'admission_selection_invalid');
    END IF;
    IF v_candidate.environment <> p_environment THEN
      RETURN jsonb_build_object('action', 'rejected', 'reason', 'environment_mismatch');
    END IF;
    IF v_candidate.check_in_mode <> 'wallet_swipe' THEN
      RETURN jsonb_build_object('action', 'rejected', 'reason', 'wallet_order_required');
    END IF;

    INSERT INTO public.ticket_admission_operations(
      wallet_session_id, event_day_id, event_session_id, ticket_order_id,
      environment, stripe_account_id, check_in_mode, actor_type,
      prepare_idempotency_key_hash, request_hash, policy_version,
      expected_order_version, selected_count, event_title, event_date
    ) VALUES (
      p_wallet_session_id, v_candidate.event_day_id,
      v_candidate.event_session_id, v_candidate.ticket_order_id,
      p_environment, v_candidate.stripe_account_id, 'wallet_swipe', 'customer',
      btrim(p_prepare_idempotency_key_hash), btrim(p_request_hash),
      v_candidate.policy_version, v_candidate.admission_version,
      v_input_count, v_candidate.event_title, v_candidate.event_date
    )
    ON CONFLICT (wallet_session_id, prepare_idempotency_key_hash) DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    v_is_new := v_inserted = 1;

    SELECT * INTO v_operation
    FROM public.ticket_admission_operations
    WHERE wallet_session_id = p_wallet_session_id
      AND prepare_idempotency_key_hash = btrim(p_prepare_idempotency_key_hash)
    FOR UPDATE;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket Admission Operation claim disappeared';
  END IF;
  IF v_operation.actor_type <> 'customer'
    OR v_operation.wallet_session_id IS NULL
    OR v_operation.wallet_session_id <> p_wallet_session_id
    OR v_operation.environment <> p_environment
    OR v_operation.request_hash <> btrim(p_request_hash)
    OR v_operation.selected_count <> v_input_count
  THEN
    RETURN jsonb_build_object('action', 'conflict', 'reason', 'idempotency_mismatch');
  END IF;

  -- Operation is already locked. Wallet Session is always the second lock.
  SELECT * INTO v_wallet_session
  FROM public.ticket_wallet_sessions
  WHERE id = v_operation.wallet_session_id
    AND environment = v_operation.environment
  FOR UPDATE;
  v_now := clock_timestamp();
  IF NOT FOUND
    OR v_wallet_session.identity_email_hash IS NULL
    OR NOT public.ticket_auth_digest_equal_v29(
      v_wallet_session.token_verifier, p_session_token_verifier)
  THEN
    IF v_is_new THEN
      v_result := public.reject_ticket_admission_operation_v30(
        v_operation.id, NULL, 'rejected', 'session_invalid',
        'customer', NULL, v_operation.wallet_session_id, 'session_invalid');
      RETURN jsonb_build_object('action', 'rejected') || v_result;
    END IF;
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;

  IF v_operation.state IN ('committed', 'rejected', 'expired') THEN
    RETURN jsonb_build_object('action', 'result')
      || jsonb_set(v_operation.result_json, '{reused}', 'true'::jsonb, true)
      || jsonb_build_object('serverNow', v_now);
  END IF;
  IF v_wallet_session.revoked_at IS NOT NULL
    OR v_wallet_session.expires_at <= v_now
  THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', 'session_expired',
      'customer', NULL, v_operation.wallet_session_id, 'session_expired');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;
  IF v_wallet_session.fresh_until <= v_now THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', 'fresh_auth_required',
      'customer', NULL, v_operation.wallet_session_id, 'fresh_auth_required');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;
  IF v_is_new AND NOT public.consume_ticket_wallet_rate_limit_v29(
    'admission_prepare', v_wallet_session.identity_email_hash, 60, 20)
  THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', 'rate_limited',
      'customer', NULL, v_operation.wallet_session_id, 'rate_limited');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;

  SELECT * INTO v_event_day
  FROM public.event_days
  WHERE id = v_operation.event_day_id
  FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', 'event_day_missing',
      'customer', NULL, v_operation.wallet_session_id, 'event_day_missing');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;

  SELECT * INTO v_event_session
  FROM public.ticket_event_sessions
  WHERE id = v_operation.event_session_id
    AND event_day_id = v_event_day.id
  FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', 'event_session_missing',
      'customer', NULL, v_operation.wallet_session_id, 'event_session_missing');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;

  SELECT * INTO v_ticket_order
  FROM public.ticket_orders
  WHERE id = v_operation.ticket_order_id
    AND event_session_id = v_event_session.id
  FOR UPDATE;
  IF NOT FOUND THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', 'order_missing',
      'customer', NULL, v_operation.wallet_session_id, 'order_missing');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;

  PERFORM refund.id
  FROM public.ticket_refund_events AS refund
  WHERE refund.ticket_order_id = v_ticket_order.id
  ORDER BY refund.created_at, refund.id
  FOR UPDATE;
  PERFORM allocation.id
  FROM public.ticket_refund_allocations AS allocation
  WHERE allocation.ticket_order_id = v_ticket_order.id
  ORDER BY allocation.admission_serial, allocation.id
  FOR UPDATE;

  v_now := clock_timestamp();
  IF v_event_day.business_date <> v_event_session.event_date
    OR v_event_day.business_date <> v_ticket_order.event_date
    OR v_event_day.operating_status <> 'open'
  THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', 'event_day_closed',
      'customer', NULL, v_operation.wallet_session_id, 'event_day_closed');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;
  IF NOT v_event_session.enabled
    OR v_event_session.admission_state <> 'scheduled'
  THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected',
      CASE WHEN v_event_session.admission_state = 'cancelled'
        THEN 'event_session_cancelled' ELSE 'event_session_closed' END,
      'customer', NULL, v_operation.wallet_session_id, 'event_session_unavailable');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;
  IF v_now < public.ticket_admission_execution_opens_v56(v_event_session.id)
    OR v_now >= public.ticket_admission_execution_closes_v56(v_event_session.id)
  THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected',
      CASE WHEN v_now < public.ticket_admission_execution_opens_v56(v_event_session.id)
        THEN 'admission_too_early' ELSE 'admission_too_late' END,
      'customer', NULL, v_operation.wallet_session_id, 'admission_window_closed');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;
  IF NOT public.ticket_admission_policy_compatible_v30(
    v_event_session.id, v_operation.policy_version, v_event_session.policy_version)
  THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', 'policy_version_changed',
      'customer', NULL, v_operation.wallet_session_id, 'policy_version_changed');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;
  IF v_event_session.environment <> v_operation.environment
    OR v_ticket_order.environment <> v_operation.environment
    OR v_event_session.stripe_account_key <> v_operation.stripe_account_key
    OR v_ticket_order.stripe_account_key <> v_operation.stripe_account_key
    OR v_ticket_order.event_id <> v_event_session.catalog_event_id
    OR v_ticket_order.check_in_mode <> 'wallet_swipe'
  THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', 'authority_binding_mismatch',
      'customer', NULL, v_operation.wallet_session_id, 'authority_binding_mismatch');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;
  IF v_ticket_order.purchaser_email_hash IS NULL
    OR NOT public.ticket_holder_has_order_v34(v_wallet_session.holder_id,v_ticket_order.id)
  THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', 'holder_mismatch',
      'customer', NULL, v_operation.wallet_session_id, 'holder_mismatch');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;
  IF v_ticket_order.admission_version <> v_operation.expected_order_version THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', 'version_conflict',
      'customer', NULL, v_operation.wallet_session_id, 'order_version_changed');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;
  IF NOT public.ticket_order_has_settled_payment_v30(v_ticket_order.id) THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', 'payment_not_settled',
      'customer', NULL, v_operation.wallet_session_id, 'payment_not_settled');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.ticket_refund_events AS refund
    WHERE refund.ticket_order_id = v_ticket_order.id
      AND refund.money_may_have_moved
      AND refund.resolution_status IN ('review_required', 'conflict_review')
      AND refund.resolved_at IS NULL
  ) THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', 'refund_review_required',
      'customer', NULL, v_operation.wallet_session_id, 'refund_review_required');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;
  IF v_is_new AND EXISTS (
    SELECT 1
    FROM public.ticket_admissions AS admission
    WHERE admission.id = ANY(v_admission_ids)
      AND admission.ticket_order_id <> v_ticket_order.id
  ) THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, NULL, 'rejected', 'same_order_selection_required',
      'customer', NULL, v_operation.wallet_session_id,
      'same_order_selection_required');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;

  IF v_is_new THEN
    BEGIN
      INSERT INTO public.ticket_admission_challenges(
        operation_id, wallet_session_id, event_session_id, ticket_order_id,
        environment, stripe_account_key, request_hash, policy_version,
        selected_count, challenge_token_verifier, state, expires_at,
        created_at, updated_at
      ) VALUES (
        v_operation.id, v_operation.wallet_session_id,
        v_operation.event_session_id, v_operation.ticket_order_id,
        v_operation.environment, v_operation.stripe_account_key,
        v_operation.request_hash, v_operation.policy_version,
        v_operation.selected_count, btrim(p_challenge_token_verifier),
        'active', least(v_now + interval '300 seconds', public.ticket_admission_execution_closes_v56(v_event_session.id)), v_now, v_now
      ) RETURNING * INTO v_challenge;
    EXCEPTION WHEN unique_violation THEN
      v_result := public.reject_ticket_admission_operation_v30(
        v_operation.id, NULL, 'rejected', 'challenge_conflict',
        'customer', NULL, v_operation.wallet_session_id, 'challenge_conflict');
      RETURN jsonb_build_object('action', 'rejected') || v_result;
    END;
  ELSE
    SELECT * INTO v_challenge
    FROM public.ticket_admission_challenges
    WHERE operation_id = v_operation.id
    FOR UPDATE;
    IF NOT FOUND THEN
      v_result := public.reject_ticket_admission_operation_v30(
        v_operation.id, NULL, 'rejected', 'challenge_missing',
        'customer', NULL, v_operation.wallet_session_id, 'challenge_missing');
      RETURN jsonb_build_object('action', 'rejected') || v_result;
    END IF;
    IF v_challenge.state <> 'active'
      OR v_challenge.expires_at <= v_now
    THEN
      IF v_challenge.state = 'active' THEN
        v_result := public.reject_ticket_admission_operation_v30(
          v_operation.id, v_challenge.id, 'expired', 'challenge_expired',
          'customer', NULL, v_operation.wallet_session_id, 'challenge_expired');
        RETURN jsonb_build_object('action', 'result', 'serverNow', v_now)
          || v_result;
      END IF;
      RETURN jsonb_build_object('action', 'conflict', 'reason', 'challenge_terminal');
    END IF;
    IF NOT public.ticket_auth_digest_equal_v29(
      v_challenge.challenge_token_verifier, p_challenge_token_verifier)
    THEN
      RETURN jsonb_build_object('action', 'conflict', 'reason', 'challenge_mismatch');
    END IF;
  END IF;

  IF v_is_new THEN
    PERFORM admission.id
    FROM public.ticket_admissions AS admission
    WHERE admission.id = ANY(v_admission_ids)
      AND admission.ticket_order_id = v_operation.ticket_order_id
    ORDER BY admission.serial, admission.id
    FOR UPDATE;
    SELECT
      count(*)::integer,
      count(*) FILTER (
        WHERE admission.ticket_order_id <> v_operation.ticket_order_id)::integer,
      count(*) FILTER (WHERE admission.status <> 'issued')::integer
    INTO v_selected, v_wrong_order, v_not_issued
    FROM public.ticket_admissions AS admission
    WHERE admission.id = ANY(v_admission_ids)
      AND admission.ticket_order_id = v_operation.ticket_order_id;
  ELSE
    PERFORM admission.id
    FROM public.ticket_admission_operation_items AS item
    JOIN public.ticket_admissions AS admission
      ON admission.id = item.ticket_admission_id
     AND admission.ticket_order_id = item.ticket_order_id
     AND admission.serial = item.admission_serial
    WHERE item.operation_id = v_operation.id
    ORDER BY admission.serial, admission.id
    FOR UPDATE OF admission;
    SELECT
      count(*)::integer,
      count(*) FILTER (
        WHERE admission.ticket_order_id <> v_operation.ticket_order_id)::integer,
      count(*) FILTER (WHERE admission.status <> 'issued')::integer
    INTO v_selected, v_wrong_order, v_not_issued
    FROM public.ticket_admission_operation_items AS item
    JOIN public.ticket_admissions AS admission
      ON admission.id = item.ticket_admission_id
     AND admission.ticket_order_id = item.ticket_order_id
     AND admission.serial = item.admission_serial
    WHERE item.operation_id = v_operation.id;
  END IF;

  IF v_selected <> v_operation.selected_count
    OR v_wrong_order <> 0
    OR v_not_issued <> 0
  THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, v_challenge.id, 'rejected',
      CASE
        WHEN v_selected <> v_operation.selected_count OR v_wrong_order <> 0
          THEN 'same_order_selection_required'
        ELSE 'admission_not_issued'
      END,
      'customer', NULL, v_operation.wallet_session_id,
      'admission_selection_changed');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;

  IF v_is_new THEN
    INSERT INTO public.ticket_admission_operation_items(
      operation_id, ticket_order_id, ticket_admission_id, admission_serial
    )
    SELECT v_operation.id, v_operation.ticket_order_id,
           admission.id, admission.serial
    FROM public.ticket_admissions AS admission
    WHERE admission.id = ANY(v_admission_ids)
      AND admission.ticket_order_id = v_operation.ticket_order_id
    ORDER BY admission.serial, admission.id;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted <> v_operation.selected_count THEN
      RAISE EXCEPTION 'Ticket Admission fixed selection row-count mismatch';
    END IF;

    UPDATE public.ticket_admission_operations
    SET state = 'prepared',
        prepared_at = v_now,
        operation_version = operation_version + 1,
        updated_at = v_now
    WHERE id = v_operation.id
      AND state = 'initializing'
    RETURNING * INTO v_operation;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Ticket Admission prepare transition failed';
    END IF;

    INSERT INTO public.ticket_admission_operation_audits(
      operation_id, actor_type, wallet_session_id, action,
      operation_version, result_json
    ) VALUES (
      v_operation.id, 'customer', v_operation.wallet_session_id, 'prepared',
      v_operation.operation_version,
      jsonb_build_object(
        'eventSessionId', v_operation.event_session_id,
        'selectedCount', v_operation.selected_count,
        'challengeExpiresAt', v_challenge.expires_at)
    );
  ELSIF v_operation.state <> 'prepared' THEN
    v_result := public.reject_ticket_admission_operation_v30(
      v_operation.id, v_challenge.id, 'rejected', 'operation_not_prepared',
      'customer', NULL, v_operation.wallet_session_id, 'operation_not_prepared');
    RETURN jsonb_build_object('action', 'rejected') || v_result;
  END IF;

  RETURN jsonb_build_object(
    'action', CASE WHEN v_is_new THEN 'prepared' ELSE 'reused' END,
    'operationId', v_operation.id,
    'operationVersion', v_operation.operation_version,
    'expectedVersion', v_operation.expected_order_version,
    'eventSessionId', v_operation.event_session_id,
    'eventTitle', v_operation.event_title,
    'eventDate', v_operation.event_date,
    'selectionGroupId', v_operation.ticket_order_id,
    'selectedCount', v_operation.selected_count,
    'challengeId', v_challenge.id,
    'challengeExpiresAt', v_challenge.expires_at,
    'serverNow', v_now
  );
END;
$$;

-- FUNCTION: prepare_ticket_order_entry_v52(uuid, uuid, text, text, text, text, text, uuid[], text, text, text, uuid)
CREATE FUNCTION public.prepare_ticket_order_entry_v52(p_order uuid, p_session uuid, p_token text, p_csrf text, p_environment text, p_origin text, p_account text, p_ids uuid[], p_prepare_key text, p_request_hash text, p_challenge text, p_operation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE locked jsonb; link uuid; op public.ticket_order_entry_operations%ROWTYPE; ids uuid[]; at timestamptz;
BEGIN
 IF p_csrf IS NULL OR p_prepare_key IS NULL OR p_request_hash IS NULL OR p_challenge IS NULL OR p_operation IS NULL THEN RETURN jsonb_build_object('action','rejected','reason','input_invalid'); END IF;
 IF public.read_ticket_order_entry_authority_v52(p_order,p_session,p_token,p_csrf,p_environment,p_origin,p_account) IS NULL
 THEN RETURN jsonb_build_object('action','unauthenticated'); END IF;
 locked:=public.lock_ticket_order_entry_v52(p_order);
 link:=public.read_ticket_order_entry_authority_v52(p_order,p_session,p_token,p_csrf,p_environment,p_origin,p_account);
 IF link IS NULL THEN RETURN jsonb_build_object('action','unauthenticated'); END IF;
 SELECT * INTO op FROM public.ticket_order_entry_operations WHERE order_session_id=p_session AND prepare_key=p_prepare_key FOR UPDATE;
 IF FOUND THEN
  IF op.ticket_order_id<>p_order OR op.request_hash<>p_request_hash THEN RETURN jsonb_build_object('action','conflict','reason','idempotency_mismatch'); END IF;
  IF op.result_json IS NOT NULL THEN RETURN jsonb_build_object('action','result')||op.result_json||jsonb_build_object('reused',true,'serverNow',clock_timestamp()); END IF;
  IF locked ? 'error' THEN RETURN jsonb_build_object('action','rejected','reason',locked->>'error'); END IF;
  IF op.expires_at<=clock_timestamp() THEN RETURN jsonb_build_object('action','rejected','reason','challenge_expired'); END IF;
 ELSE
  IF locked ? 'error' THEN RETURN jsonb_build_object('action','rejected','reason',locked->>'error'); END IF;
  PERFORM id FROM public.ticket_admissions WHERE ticket_order_id=p_order ORDER BY serial,id FOR UPDATE;
  SELECT array_agg(id ORDER BY id) INTO ids FROM public.ticket_admissions WHERE ticket_order_id=p_order AND status='issued';
  IF NOT COALESCE(public.ticket_group_entry_selection_v52(p_order,p_ids),false) THEN RETURN jsonb_build_object('action','rejected','reason','whole_order_selection_required'); END IF;
  IF NOT public.consume_ticket_wallet_rate_limit_v29('order_entry_prepare',p_order::text,60,20)
  THEN RETURN jsonb_build_object('action','rejected','reason','rate_limited'); END IF;
  at:=clock_timestamp();
  INSERT INTO public.ticket_order_entry_operations(id,ticket_order_id,order_session_id,prepare_key,request_hash,admission_ids,
   expected_order_version,policy_version,challenge_verifier,expires_at,created_at)
  VALUES(p_operation,p_order,p_session,p_prepare_key,p_request_hash,ids,(locked->>'version')::bigint,(locked->>'policyVersion')::bigint,p_challenge,least(at+interval '300 seconds',public.ticket_admission_execution_closes_v56((locked->>'eventSessionId')::uuid)),at) RETURNING * INTO op;
 END IF;
 RETURN jsonb_build_object('action','prepared','operationId',op.id,'eventSessionId',locked->>'eventSessionId',
  'eventTitle',locked->>'eventTitle','eventDate',locked->>'eventDate','selectedCount',cardinality(op.admission_ids),'expectedVersion',op.expected_order_version,'challengeExpiresAt',op.expires_at,'serverNow',clock_timestamp());
END $$;

-- FUNCTION: prepare_transactional_email_payload_v29(uuid, uuid, text)
CREATE FUNCTION public.prepare_transactional_email_payload_v29(p_job_id uuid, p_claim_token uuid, p_payload_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_job public.transactional_email_jobs%ROWTYPE;
BEGIN
  IF p_job_id IS NULL OR p_claim_token IS NULL
    OR p_payload_hash !~ '^[0-9a-f]{64}$'
  THEN
    RAISE EXCEPTION 'invalid transactional email payload preparation';
  END IF;
  SELECT * INTO v_job FROM public.lock_transactional_email_job_v33(p_job_id);
  IF NOT FOUND OR v_job.state <> 'processing'
    OR v_job.claim_token <> p_claim_token
    OR v_job.lease_expires_at <= clock_timestamp()
  THEN
    RETURN jsonb_build_object('action', 'stale_claim');
  END IF;
  IF v_job.payload_hash IS NULL THEN
    UPDATE public.transactional_email_jobs
    SET payload_hash = p_payload_hash, updated_at = clock_timestamp()
    WHERE id = v_job.id;
    RETURN jsonb_build_object('action', 'prepared');
  END IF;
  IF v_job.payload_hash = p_payload_hash THEN
    RETURN jsonb_build_object('action', 'reused');
  END IF;
  RETURN jsonb_build_object('action', 'conflict');
END;
$_$;

-- FUNCTION: project_vip_floor_legacy_version_write()
CREATE FUNCTION public.project_vip_floor_legacy_version_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_changed_fields text[];
BEGIN
  IF NOT public.vip_floor_v2_dual_write_enabled()
    OR current_setting('ghost.vip_floor_v8_writer', true) = 'on'
  THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF (to_jsonb(NEW) ->> 'version')::bigint <> 1 THEN
      RAISE EXCEPTION USING
        ERRCODE = '22023',
        MESSAGE = 'legacy VIP Floor insert version must be 1';
    END IF;
    NEW := jsonb_populate_record(NEW, jsonb_build_object('version', 1));
    RETURN NEW;
  END IF;

  IF (to_jsonb(NEW) ->> 'version')::bigint
    IS DISTINCT FROM (to_jsonb(OLD) ->> 'version')::bigint
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'legacy VIP Floor writer cannot set version';
  END IF;

  v_changed_fields := public.vip_floor_compat_changed_fields(
    TG_TABLE_NAME,
    to_jsonb(OLD),
    to_jsonb(NEW)
  );
  NEW := jsonb_populate_record(
    NEW,
    jsonb_build_object(
      'version',
      (to_jsonb(OLD) ->> 'version')::bigint
        + CASE WHEN cardinality(v_changed_fields) > 0 THEN 1 ELSE 0 END
    )
  );
  RETURN NEW;
END;
$$;

-- FUNCTION: project_vip_floor_v1_assignment_history()
CREATE FUNCTION public.project_vip_floor_v1_assignment_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old_active boolean := false;
  v_new_active boolean;
  v_event_type text;
  v_interval_before jsonb;
  v_interval_after jsonb;
BEGIN
  IF current_setting('ghost.vip_floor_v8_writer', true) = 'on' THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    v_old_active := OLD.released_at IS NULL
      AND OLD.lock_status IN ('held', 'payment_grace_locked', 'confirmed');
    v_interval_before := jsonb_build_object(
      'startAt', OLD.assigned_start_at,
      'endAt', OLD.assigned_end_at
    );
  END IF;

  v_new_active := NEW.released_at IS NULL
    AND NEW.lock_status IN ('held', 'payment_grace_locked', 'confirmed');
  v_interval_after := jsonb_build_object(
    'startAt', NEW.assigned_start_at,
    'endAt', NEW.assigned_end_at
  );

  IF TG_OP = 'INSERT' AND v_new_active THEN
    v_event_type := 'assigned';
    v_interval_before := NULL;
  ELSIF TG_OP = 'UPDATE' AND v_old_active AND NOT v_new_active THEN
    v_event_type := 'released';
    v_interval_after := NULL;
  ELSIF TG_OP = 'UPDATE' AND NOT v_old_active AND v_new_active THEN
    v_event_type := 'reactivated';
  ELSIF TG_OP = 'UPDATE'
    AND v_new_active
    AND (OLD.assigned_start_at, OLD.assigned_end_at)
      IS DISTINCT FROM (NEW.assigned_start_at, NEW.assigned_end_at)
  THEN
    v_event_type := 'interval_changed';
  ELSIF TG_OP = 'UPDATE'
    AND v_new_active
    AND OLD.assignment_role IS DISTINCT FROM NEW.assignment_role
  THEN
    v_event_type := 'role_changed';
  ELSIF TG_OP = 'UPDATE'
    AND v_new_active
    AND (
      OLD.lock_status IS DISTINCT FROM NEW.lock_status
      OR OLD.released_at IS DISTINCT FROM NEW.released_at
    )
  THEN
    v_event_type := 'reactivated';
  ELSE
    RETURN NULL;
  END IF;

  INSERT INTO public.reservation_assignment_events(
    reservation_id,
    reservation_resource_id,
    seat_resource_id,
    event_type,
    interval_before,
    interval_after,
    actor_admin_id,
    reason,
    request_id
  )
  VALUES (
    NEW.reservation_id,
    NEW.id,
    NEW.seat_resource_id,
    v_event_type,
    v_interval_before,
    v_interval_after,
    NULL,
    'legacy_v7_projection',
    NULL
  );

  RETURN NULL;
END;
$$;

-- FUNCTION: project_vip_floor_v1_assignment_interval()
CREATE FUNCTION public.project_vip_floor_v1_assignment_interval() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.scheduled_start_at IS DISTINCT FROM OLD.scheduled_start_at
    OR NEW.expected_release_at IS DISTINCT FROM OLD.expected_release_at
  THEN
    UPDATE public.reservation_resources AS rr
    SET assigned_start_at = CASE
          WHEN rr.assigned_start_at IS NOT DISTINCT FROM OLD.scheduled_start_at
            THEN NEW.scheduled_start_at
          ELSE rr.assigned_start_at
        END,
        assigned_end_at = CASE
          WHEN rr.assigned_end_at IS NOT DISTINCT FROM OLD.expected_release_at
            THEN NEW.expected_release_at
          ELSE rr.assigned_end_at
        END
    WHERE rr.reservation_id = NEW.id
      AND rr.released_at IS NULL
      AND rr.lock_status IN ('held', 'payment_grace_locked', 'confirmed');
  END IF;

  RETURN NULL;
END;
$$;

-- FUNCTION: project_vip_floor_v1_assignment_write()
CREATE FUNCTION public.project_vip_floor_v1_assignment_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_scheduled_start_at timestamptz;
  v_expected_release_at timestamptz;
  v_changed_fields text[];
  v_manage_legacy_version boolean;
BEGIN
  IF NEW.assigned_start_at IS NULL
    OR NEW.assigned_end_at IS NULL
    OR NEW.assignment_role IS NULL
  THEN
    SELECT r.scheduled_start_at, r.expected_release_at
    INTO v_scheduled_start_at, v_expected_release_at
    FROM public.reservations AS r
    WHERE r.id = NEW.reservation_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION USING
        ERRCODE = '23503',
        MESSAGE = 'assignment reservation does not exist';
    END IF;

    NEW.assigned_start_at := COALESCE(NEW.assigned_start_at, v_scheduled_start_at);
    NEW.assigned_end_at := COALESCE(NEW.assigned_end_at, v_expected_release_at);
    IF NEW.assignment_role IS NULL THEN
      NEW.assignment_role := CASE
        WHEN EXISTS (
          SELECT 1
          FROM public.reservation_resources AS existing
          WHERE existing.reservation_id = NEW.reservation_id
            AND existing.id IS DISTINCT FROM NEW.id
            AND existing.assignment_role = 'primary'
        ) THEN 'additional'
        ELSE 'primary'
      END;
    END IF;
  END IF;

  v_manage_legacy_version := public.vip_floor_v2_dual_write_enabled()
    AND current_setting('ghost.vip_floor_v8_writer', true) IS DISTINCT FROM 'on';

  IF NOT v_manage_legacy_version THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.version IS NOT NULL AND NEW.version <> 1 THEN
      RAISE EXCEPTION USING
        ERRCODE = '22023',
        MESSAGE = 'legacy assignment insert version must be 1';
    END IF;
    NEW.version := 1;
    RETURN NEW;
  END IF;

  IF NEW.version IS DISTINCT FROM OLD.version THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'legacy assignment writer cannot set version';
  END IF;

  v_changed_fields := public.vip_floor_compat_changed_fields(
    'reservation_resources',
    to_jsonb(OLD),
    to_jsonb(NEW)
  );
  NEW.version := OLD.version + CASE WHEN cardinality(v_changed_fields) > 0 THEN 1 ELSE 0 END;
  RETURN NEW;
END;
$$;

-- FUNCTION: project_vip_floor_v1_reservation_write()
CREATE FUNCTION public.project_vip_floor_v1_reservation_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_event_day_id uuid;
  v_slot_start_at timestamptz;
  v_slot_end_at timestamptz;
  v_changed_fields text[];
  v_manage_legacy_version boolean;
BEGIN
  IF TG_OP = 'UPDATE'
    AND NEW.expected_release_at IS NOT DISTINCT FROM OLD.expected_release_at
    AND (
      NEW.seat_extended_until_at IS DISTINCT FROM OLD.seat_extended_until_at
      OR NEW.seat_due_at IS DISTINCT FROM OLD.seat_due_at
    )
  THEN
    NEW.expected_release_at := COALESCE(
      NEW.seat_extended_until_at,
      NEW.seat_due_at,
      NEW.scheduled_end_at
    );
  END IF;

  IF NEW.event_day_id IS NULL
    OR NEW.scheduled_start_at IS NULL
    OR NEW.scheduled_end_at IS NULL
    OR NEW.expected_release_at IS NULL
  THEN
    SELECT bs.event_day_id, bs.start_at, bs.end_at
    INTO v_event_day_id, v_slot_start_at, v_slot_end_at
    FROM public.booking_slots AS bs
    WHERE bs.id = NEW.booking_slot_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION USING
        ERRCODE = '23503',
        MESSAGE = 'reservation booking slot does not exist';
    END IF;

    NEW.event_day_id := COALESCE(NEW.event_day_id, v_event_day_id);
    IF NEW.intake_channel = 'walk_in' THEN
      NEW.scheduled_start_at := COALESCE(
        NEW.scheduled_start_at,
        NEW.checked_in_at,
        NEW.confirmed_at,
        NEW.created_at,
        now()
      );
      NEW.scheduled_end_at := COALESCE(
        NEW.scheduled_end_at,
        NEW.seat_extended_until_at,
        NEW.seat_due_at,
        v_slot_end_at
      );
      NEW.expected_release_at := COALESCE(
        NEW.expected_release_at,
        NEW.seat_extended_until_at,
        NEW.seat_due_at,
        NEW.scheduled_end_at
      );
    ELSE
      NEW.scheduled_start_at := COALESCE(NEW.scheduled_start_at, v_slot_start_at);
      NEW.scheduled_end_at := COALESCE(NEW.scheduled_end_at, v_slot_end_at);
      NEW.expected_release_at := COALESCE(
        NEW.expected_release_at,
        NEW.seat_extended_until_at,
        NEW.seat_due_at,
        v_slot_end_at
      );
    END IF;
  END IF;

  IF NEW.status = 'checked_in'
    AND (
      NEW.service_status IS NULL
      OR (
        (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status)
        AND NEW.service_status = 'expected'::public.vip_service_status
      )
    )
  THEN
    NEW.service_status := 'seated'::public.vip_service_status;
    NEW.service_status_changed_at := COALESCE(
      NEW.checked_in_at,
      NEW.service_status_changed_at,
      NEW.updated_at,
      now()
    );
  ELSIF NEW.status = 'confirmed' AND NEW.service_status IS NULL THEN
    NEW.service_status := 'expected'::public.vip_service_status;
    NEW.service_status_changed_at := COALESCE(
      NEW.confirmed_at,
      NEW.updated_at,
      now()
    );
  END IF;

  v_manage_legacy_version := public.vip_floor_v2_dual_write_enabled()
    AND current_setting('ghost.vip_floor_v8_writer', true) IS DISTINCT FROM 'on';

  IF NOT v_manage_legacy_version THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.version IS NOT NULL AND NEW.version <> 1 THEN
      RAISE EXCEPTION USING
        ERRCODE = '22023',
        MESSAGE = 'legacy reservation insert version must be 1';
    END IF;
    NEW.version := 1;
    RETURN NEW;
  END IF;

  IF NEW.version IS DISTINCT FROM OLD.version THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'legacy reservation writer cannot set version';
  END IF;

  v_changed_fields := public.vip_floor_compat_changed_fields(
    'reservations',
    to_jsonb(OLD),
    to_jsonb(NEW)
  );
  NEW.version := OLD.version + CASE WHEN cardinality(v_changed_fields) > 0 THEN 1 ELSE 0 END;
  RETURN NEW;
END;
$$;

-- FUNCTION: protect_ticket_admission_challenge_v30()
CREATE FUNCTION public.protect_ticket_admission_challenge_v30() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Ticket Admission Challenge is immutable';
  END IF;
  -- Follow the parent Operation's FK-driven privacy unlink and preserve every
  -- remaining challenge fact. Direct callers cannot invoke this exception.
  IF OLD.wallet_session_id IS NOT NULL
    AND NEW.wallet_session_id IS NULL
    AND (
      NOT EXISTS (
        SELECT 1
        FROM public.ticket_wallet_sessions AS wallet_session
        WHERE wallet_session.id = OLD.wallet_session_id
          AND wallet_session.environment = OLD.environment
      )
      OR EXISTS (
        SELECT 1
        FROM public.ticket_wallet_sessions AS wallet_session
        WHERE wallet_session.id = OLD.wallet_session_id
          AND wallet_session.environment = OLD.environment
          AND wallet_session.revoked_at <=
            clock_timestamp() - interval '30 days'
          AND wallet_session.token_verifier IS NULL
          AND wallet_session.csrf_verifier IS NULL
      )
    )
    AND (to_jsonb(NEW) - 'wallet_session_id')
      IS NOT DISTINCT FROM (to_jsonb(OLD) - 'wallet_session_id')
  THEN
    RETURN NEW;
  END IF;
  IF OLD.state IN ('consumed', 'rejected', 'expired')
    AND NEW IS DISTINCT FROM OLD
  THEN
    RAISE EXCEPTION 'terminal Ticket Admission Challenge is immutable';
  END IF;
  IF ROW(
      NEW.operation_id, NEW.wallet_session_id, NEW.event_session_id,
      NEW.ticket_order_id, NEW.environment, NEW.stripe_account_key,
      NEW.request_hash, NEW.policy_version, NEW.selected_count,
      NEW.challenge_token_verifier, NEW.expires_at, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.operation_id, OLD.wallet_session_id, OLD.event_session_id,
      OLD.ticket_order_id, OLD.environment, OLD.stripe_account_key,
      OLD.request_hash, OLD.policy_version, OLD.selected_count,
      OLD.challenge_token_verifier, OLD.expires_at, OLD.created_at
    )
  THEN
    RAISE EXCEPTION 'Ticket Admission Challenge authority is immutable';
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: protect_ticket_admission_operation_v30()
CREATE FUNCTION public.protect_ticket_admission_operation_v30() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Ticket Admission Operation is immutable';
  END IF;
  -- The only permitted redaction is the FK-driven unlink after v29 deletes a
  -- Wallet Session 30 days after revocation. No terminal/result fact changes.
  IF OLD.wallet_session_id IS NOT NULL
    AND NEW.wallet_session_id IS NULL
    AND (
      NOT EXISTS (
        SELECT 1
        FROM public.ticket_wallet_sessions AS wallet_session
        WHERE wallet_session.id = OLD.wallet_session_id
          AND wallet_session.environment = OLD.environment
      )
      OR EXISTS (
        SELECT 1
        FROM public.ticket_wallet_sessions AS wallet_session
        WHERE wallet_session.id = OLD.wallet_session_id
          AND wallet_session.environment = OLD.environment
          AND wallet_session.revoked_at <=
            clock_timestamp() - interval '30 days'
          AND wallet_session.token_verifier IS NULL
          AND wallet_session.csrf_verifier IS NULL
      )
    )
    -- Stored generated columns are recomputed after BEFORE triggers, so NEW's
    -- generated stripe_account_key is transiently NULL at this point.
    AND (to_jsonb(NEW) - 'wallet_session_id' - 'stripe_account_key')
      IS NOT DISTINCT FROM
        (to_jsonb(OLD) - 'wallet_session_id' - 'stripe_account_key')
  THEN
    RETURN NEW;
  END IF;
  IF OLD.state IN ('committed', 'rejected', 'expired')
    AND NEW IS DISTINCT FROM OLD
  THEN
    RAISE EXCEPTION 'terminal Ticket Admission Operation is immutable';
  END IF;
  IF OLD.result_json IS NOT NULL
    AND NEW.result_json IS DISTINCT FROM OLD.result_json
  THEN
    RAISE EXCEPTION 'Ticket Admission Result is immutable';
  END IF;
  IF ROW(
      NEW.wallet_session_id, NEW.event_day_id, NEW.event_session_id,
      NEW.ticket_order_id, NEW.environment, NEW.stripe_account_id,
      NEW.check_in_mode, NEW.actor_type, NEW.actor_admin_id,
      NEW.manager_reason, NEW.prepare_idempotency_key_hash,
      NEW.request_hash, NEW.policy_version, NEW.expected_order_version,
      NEW.selected_count, NEW.event_title, NEW.event_date, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.wallet_session_id, OLD.event_day_id, OLD.event_session_id,
      OLD.ticket_order_id, OLD.environment, OLD.stripe_account_id,
      OLD.check_in_mode, OLD.actor_type, OLD.actor_admin_id,
      OLD.manager_reason, OLD.prepare_idempotency_key_hash,
      OLD.request_hash, OLD.policy_version, OLD.expected_order_version,
      OLD.selected_count, OLD.event_title, OLD.event_date, OLD.created_at
    )
  THEN
    RAISE EXCEPTION 'Ticket Admission Operation authority is immutable';
  END IF;
  IF OLD.commit_idempotency_key_hash IS NOT NULL
    AND ROW(NEW.commit_idempotency_key_hash, NEW.commit_request_hash)
      IS DISTINCT FROM ROW(OLD.commit_idempotency_key_hash, OLD.commit_request_hash)
  THEN
    RAISE EXCEPTION 'Ticket Admission commit identity is immutable';
  END IF;
  IF NEW.operation_version <= OLD.operation_version THEN
    RAISE EXCEPTION 'Ticket Admission Operation version must increase';
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: purge_vip_manager_metrics_v15(integer)
CREATE FUNCTION public.purge_vip_manager_metrics_v15(p_retention_days integer DEFAULT 30) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_deleted bigint;
  v_days int := LEAST(GREATEST(COALESCE(p_retention_days, 30), 7), 90);
BEGIN
  DELETE FROM public.vip_manager_metrics
  WHERE occurred_at < now() - make_interval(days => v_days);
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;

-- FUNCTION: purge_webhook_event_payloads_v1(interval)
CREATE FUNCTION public.purge_webhook_event_payloads_v1(p_keep_interval interval DEFAULT '30 days'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count int;
BEGIN
  UPDATE public.webhook_events
  SET payload_json = '{}'::jsonb,
      updated_at = now()
  WHERE processing_status IN ('processed', 'ignored', 'dead')
    AND created_at < now() - p_keep_interval
    AND payload_json <> '{}'::jsonb;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

-- FUNCTION: purge_webhook_event_payloads_v2(interval, integer)
CREATE FUNCTION public.purge_webhook_event_payloads_v2(p_keep_interval interval DEFAULT '30 days'::interval, p_batch_size integer DEFAULT 500) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET lock_timeout TO '2s'
    SET statement_timeout TO '15s'
    AS $$
DECLARE
  v_count int;
BEGIN
  IF p_keep_interval IS NULL
    OR p_keep_interval < interval '7 days'
    OR p_keep_interval > interval '400 days' THEN
    RAISE EXCEPTION 'p_keep_interval must be between 7 days and 400 days'
      USING ERRCODE = '22023';
  END IF;

  IF p_batch_size IS NULL OR p_batch_size < 1 OR p_batch_size > 5000 THEN
    RAISE EXCEPTION 'p_batch_size must be between 1 and 5000'
      USING ERRCODE = '22023';
  END IF;

  WITH purgeable AS (
    SELECT we.id
    FROM public.webhook_events we
    WHERE we.processing_status IN ('processed', 'ignored', 'dead')
      AND we.created_at < now() - p_keep_interval
      AND we.payload_purged_at IS NULL
      AND we.payload_json <> '{}'::jsonb
      -- Open internal refund cases keyed on the provider refund object.
      AND NOT EXISTS (
        SELECT 1
        FROM public.refund_cases rc
        WHERE rc.environment = we.environment
          AND rc.stripe_account_key = we.stripe_account_key
          AND rc.stripe_refund_id = we.provider_object_id
          AND rc.status IN ('required', 'requested', 'approved', 'processing', 'failed', 'dead')
      )
      -- Live disputes hold both the dispute object event and the event row
      -- whose application recorded the dispute (last_event_id watermark).
      AND NOT EXISTS (
        SELECT 1
        FROM public.stripe_disputes sd
        WHERE sd.environment = we.environment
          AND sd.stripe_account_key = we.stripe_account_key
          AND sd.status IN ('needs_response', 'warning_needs_response', 'under_review', 'warning_under_review')
          AND (sd.stripe_dispute_id = we.provider_object_id OR sd.last_event_id = we.stripe_event_id)
      )
      -- Unresolved external finance exceptions pinned to this provider object.
      AND NOT EXISTS (
        SELECT 1
        FROM public.external_finance_reviews efr
        WHERE efr.environment = we.environment
          AND efr.stripe_account_key = we.stripe_account_key
          AND efr.provider_object_id = we.provider_object_id
          AND efr.status = 'review_required'
      )
      -- Armed or unsettled off-session charge attempts on this intent.
      AND NOT EXISTS (
        SELECT 1
        FROM public.off_session_charge_attempts osca
        WHERE osca.environment = we.environment
          AND osca.stripe_account_key = we.stripe_account_key
          AND osca.provider_object_id = we.provider_object_id
          AND osca.status IN ('approved', 'processing', 'failed', 'dead')
      )
      -- Reservation holds still reconciling against Stripe (no env/account
      -- columns on this table; the provider object id is globally unique).
      AND NOT EXISTS (
        SELECT 1
        FROM public.reservation_hold_requests rhr
        WHERE rhr.provider_object_id = we.provider_object_id
          AND rhr.status IN ('stripe_unknown', 'finalize_retry', 'retry_exhausted', 'manual_review')
      )
      -- Ticket orders awaiting checkout completion or fulfilment on this
      -- checkout session / payment intent.
      AND NOT EXISTS (
        SELECT 1
        FROM public.ticket_orders t
        WHERE t.environment = we.environment
          AND t.stripe_account_key = we.stripe_account_key
          AND (t.payment_intent_id = we.provider_object_id OR t.checkout_session_id = we.provider_object_id)
          AND (t.status = 'pending' OR (t.status = 'paid' AND t.fulfilled_at IS NULL))
      )
    ORDER BY we.created_at
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.webhook_events we
  SET payload_json = '{}'::jsonb,
      payload_purged_at = now()
  FROM purgeable p
  WHERE we.id = p.id;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

-- FUNCTION: queue_ticket_entry_delivery_v53(uuid, text, text)
CREATE FUNCTION public.queue_ticket_entry_delivery_v53(p_link uuid, p_from text, p_reply text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE l public.ticket_order_entry_links%ROWTYPE; o public.ticket_orders%ROWTYPE; j uuid:=gen_random_uuid(); at timestamptz:=clock_timestamp();
BEGIN
 IF p_from IS NULL OR length(p_from) NOT BETWEEN 1 AND 320 OR p_from ~ E'[\r\n]'
  OR (p_reply IS NOT NULL AND (length(p_reply) NOT BETWEEN 1 AND 320 OR p_reply ~ E'[\r\n]')) THEN RAISE EXCEPTION 'entry_delivery_configuration_invalid'; END IF;
 SELECT * INTO l FROM public.ticket_order_entry_links WHERE id=p_link;
 SELECT * INTO o FROM public.ticket_orders WHERE id=l.ticket_order_id;
 IF l.id IS NULL OR l.revoked_at IS NOT NULL OR l.expires_at<=at OR o.purchaser_email_ciphertext IS NULL
  OR o.admission_policy<>'order_together_v1' OR NOT public.ticket_order_has_settled_payment_v30(o.id)
 THEN RAISE EXCEPTION 'entry_delivery_authority_invalid'; END IF;
 INSERT INTO public.transactional_email_jobs(id,ticket_order_id,purpose,provider_idempotency_key,recipient_email_hash,recipient_email_ciphertext,render_data_json,next_attempt_at,created_at,updated_at)
 VALUES(j,o.id,'ticket_wallet_purchase','ghost-ticket-entry-v1-'||j,o.purchaser_email_hash,o.purchaser_email_ciphertext,
  jsonb_build_object('template','ticket_wallet_purchase','templateVersion','ghost.ticket-wallet-purchase.v2','notificationJobId',j,
   'renderReferenceAt',to_char(at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
   'expiresAt',to_char(l.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
   'from',p_from,'replyTo',p_reply,'walletUrl',l.public_origin||'/tickets/wallet','publicCode',o.public_code,
   'eventTitle',o.event_title,'demoAdmissionTest',EXISTS(SELECT 1 FROM public.ticket_demo_admission_windows_v56 w WHERE w.event_session_id=o.event_session_id AND o.environment='test'),
   'eventDate',o.event_date,'totalQuantity',o.total_quantity,'commercial',o.items_json->0->'commercial',
   'orderEntry',jsonb_build_object('linkId',l.id,'orderId',o.id,'eventSessionId',l.event_session_id,'generation',l.generation,
    'environment',l.environment,'account',l.stripe_account_key,'origin',l.public_origin,'ciphertext',l.secret_ciphertext)),at,at,at);
 RETURN j;
END $$;

-- FUNCTION: read_ticket_admission_readiness_v30(text, uuid, text, uuid)
CREATE FUNCTION public.read_ticket_admission_readiness_v30(p_environment text, p_wallet_session_id uuid, p_session_token_verifier text, p_event_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_session public.ticket_wallet_sessions%ROWTYPE;
  v_event_session public.ticket_event_sessions%ROWTYPE;
  v_event_day public.event_days%ROWTYPE;
  v_event_session_id uuid := p_event_session_id;
  v_now timestamptz := clock_timestamp();
  v_maximum integer := 0;
  v_state text;
BEGIN
  IF COALESCE(p_environment, '') NOT IN ('test', 'live')
    OR p_wallet_session_id IS NULL
    OR NULLIF(btrim(COALESCE(p_session_token_verifier, '')), '') IS NULL
  THEN
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;

  SELECT * INTO v_session
  FROM public.ticket_wallet_sessions
  WHERE id = p_wallet_session_id
    AND environment = p_environment;
  IF NOT FOUND
    OR v_session.revoked_at IS NOT NULL
    OR v_session.expires_at <= v_now
    OR v_session.identity_email_hash IS NULL
    OR NOT public.ticket_auth_digest_equal_v29(
      v_session.token_verifier, p_session_token_verifier)
  THEN
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;

  IF v_event_session_id IS NULL THEN
    SELECT event_session.id INTO v_event_session_id
    FROM public.ticket_orders AS ticket_order
    JOIN public.ticket_event_sessions AS event_session
      ON event_session.id = ticket_order.event_session_id
    WHERE ticket_order.environment = p_environment
      AND ticket_order.check_in_mode = 'wallet_swipe'
      AND public.ticket_holder_has_order_v34(v_session.holder_id,ticket_order.id)
      AND ticket_order.fulfilled_at IS NOT NULL
      AND event_session.admission_closes_at + interval '8 days' > v_now
    ORDER BY event_session.admission_opens_at, event_session.id
    LIMIT 1;
  END IF;

  SELECT * INTO v_event_session
  FROM public.ticket_event_sessions
  WHERE id = v_event_session_id
    AND environment = p_environment;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'action', 'read', 'state', 'feature_unavailable',
      'serverNow', v_now, 'eventSessionId', NULL,
      'opensAt', NULL, 'closesAt', NULL, 'maximumSelection', 0
    );
  END IF;

  SELECT * INTO v_event_day
  FROM public.event_days
  WHERE id = v_event_session.event_day_id
    AND business_date = v_event_session.event_date;

  SELECT COALESCE(max(eligible.issued_count), 0)::integer
  INTO v_maximum
  FROM (
    SELECT ticket_order.id, count(*)::integer AS issued_count
    FROM public.ticket_orders AS ticket_order
    JOIN public.ticket_admissions AS admission
      ON admission.ticket_order_id = ticket_order.id
     AND admission.status = 'issued'
    JOIN public.ticket_checkout_actions AS checkout_action
      ON checkout_action.ticket_order_id = ticket_order.id
     AND checkout_action.state = 'completed'
     AND checkout_action.event_session_id = ticket_order.event_session_id
     AND checkout_action.environment = ticket_order.environment
     AND checkout_action.stripe_account_key = ticket_order.stripe_account_key
     AND checkout_action.check_in_mode = ticket_order.check_in_mode
    WHERE ticket_order.event_session_id = v_event_session.id
      AND ticket_order.environment = p_environment
      AND ticket_order.check_in_mode = 'wallet_swipe'
      AND public.ticket_holder_has_order_v34(v_session.holder_id,ticket_order.id)
      AND ticket_order.status = 'fulfilled'
      AND ticket_order.paid_at IS NOT NULL
      AND ticket_order.fulfilled_at IS NOT NULL
      AND NULLIF(ticket_order.payment_intent_id, '') IS NOT NULL
      AND NULLIF(ticket_order.checkout_session_id, '') IS NOT NULL
      AND ticket_order.payment_hold_reason IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.ticket_refund_events AS refund
        WHERE refund.ticket_order_id = ticket_order.id
          AND refund.money_may_have_moved
          AND refund.resolution_status IN ('review_required', 'conflict_review')
          AND refund.resolved_at IS NULL
      )
    GROUP BY ticket_order.id
  ) AS eligible;

  v_state := CASE
    WHEN v_event_day.id IS NULL OR v_event_day.operating_status <> 'open'
      OR NOT v_event_session.enabled
      OR v_event_session.admission_state IN ('closed', 'cancelled')
      THEN 'manager_recovery'
    WHEN v_now < public.ticket_admission_execution_opens_v56(v_event_session.id) THEN 'not_open'
    WHEN v_now >= public.ticket_admission_execution_closes_v56(v_event_session.id) THEN 'closed'
    WHEN v_session.fresh_until <= v_now THEN 'fresh_auth_required'
    WHEN v_maximum < 1 THEN 'manager_recovery'
    ELSE 'open'
  END;

  RETURN jsonb_build_object(
    'action', 'read',
    'state', v_state,
    'serverNow', v_now,
    'eventSessionId', v_event_session.id,
    'opensAt', public.ticket_admission_execution_opens_v56(v_event_session.id),
    'closesAt', public.ticket_admission_execution_closes_v56(v_event_session.id),
    'maximumSelection', LEAST(v_maximum, 20)
  );
END;
$$;

-- FUNCTION: read_ticket_admission_result_v30(text, uuid, text, uuid)
CREATE FUNCTION public.read_ticket_admission_result_v30(p_environment text, p_wallet_session_id uuid, p_session_token_verifier text, p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_session public.ticket_wallet_sessions%ROWTYPE;
  v_operation public.ticket_admission_operations%ROWTYPE;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF COALESCE(p_environment, '') NOT IN ('test', 'live')
    OR p_wallet_session_id IS NULL
    OR p_operation_id IS NULL
    OR NULLIF(btrim(COALESCE(p_session_token_verifier, '')), '') IS NULL
  THEN
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;

  SELECT * INTO v_session
  FROM public.ticket_wallet_sessions
  WHERE id = p_wallet_session_id
    AND environment = p_environment;
  IF NOT FOUND
    OR v_session.revoked_at IS NOT NULL
    OR v_session.expires_at <= v_now
    OR v_session.identity_email_hash IS NULL
    OR NOT public.ticket_auth_digest_equal_v29(
      v_session.token_verifier, p_session_token_verifier)
  THEN
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;

  SELECT * INTO v_operation
  FROM public.ticket_admission_operations
  WHERE id = p_operation_id
    AND wallet_session_id = v_session.id
    AND environment = p_environment;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'not_found');
  END IF;

  IF NOT public.consume_ticket_wallet_rate_limit_v29(
    'admission_result', v_session.identity_email_hash, 60, 30)
  THEN
    RETURN jsonb_build_object('action', 'rate_limited');
  END IF;

  IF v_operation.result_json IS NOT NULL THEN
    RETURN jsonb_build_object('action', 'result')
      || v_operation.result_json
      || jsonb_build_object('serverNow', v_now);
  END IF;

  RETURN jsonb_build_object(
    'action', 'result',
    'operationId', v_operation.id,
    'state', 'pending',
    'reused', false,
    'eventSessionId', v_operation.event_session_id,
    'eventTitle', v_operation.event_title,
    'eventDate', v_operation.event_date,
    'selectionGroupId', v_operation.ticket_order_id,
    'selectedCount', v_operation.selected_count,
    'admittedCount', 0,
    'admittedAt', NULL,
    'operationVersion', v_operation.operation_version,
    'serverNow', v_now
  );
END;
$$;

-- FUNCTION: read_ticket_alert_delivery_health_v42()
CREATE FUNCTION public.read_ticket_alert_delivery_health_v42() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'heartbeatAgeSeconds',(SELECT greatest(0,extract(epoch FROM clock_timestamp()-last_observed_at)) FROM public.ticket_alert_dispatch_state WHERE id),
    'pendingOldestSeconds',COALESCE((SELECT greatest(0,extract(epoch FROM clock_timestamp()-j.created_at)) FROM public.ticket_alert_dispatch_state s
      JOIN public.notification_jobs j ON j.id=s.notification_job_id WHERE j.status NOT IN ('sent','dead')),0),
    'deliveryFailed',EXISTS(SELECT 1 FROM public.ticket_alert_dispatch_state s LEFT JOIN public.notification_jobs j ON j.id=s.notification_job_id
      WHERE s.notification_job_id IS NOT NULL AND (j.id IS NULL OR j.status='dead')))
$$;

-- FUNCTION: read_ticket_delivery_health_v38()
CREATE FUNCTION public.read_ticket_delivery_health_v38() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT jsonb_build_object(
 'serverNow',clock_timestamp(),
 'otpOldestSeconds',COALESCE((SELECT greatest(0,extract(epoch FROM clock_timestamp()-min(created_at))) FROM public.transactional_email_jobs WHERE purpose='ticket_wallet_otp' AND state IN ('pending','processing','retry')),0),
 'purchaseOldestSeconds',COALESCE((SELECT greatest(0,extract(epoch FROM clock_timestamp()-min(created_at))) FROM (SELECT created_at FROM public.ticket_purchase_notices WHERE materialized_at IS NULL UNION ALL SELECT created_at FROM public.transactional_email_jobs WHERE purpose='ticket_wallet_purchase' AND state IN ('pending','retry','processing')) AS outstanding),0),
 'deliveryDead',(SELECT count(*) FROM public.transactional_email_jobs WHERE state IN ('dead','configuration')),
 'openCircuits',(SELECT count(*) FROM public.transactional_email_provider_circuits WHERE is_open AND (open_until IS NULL OR open_until>clock_timestamp())),
 'checkoutReviewCount',(SELECT count(*) FROM public.ticket_checkout_actions WHERE state='review_required'),
 'refundReviewCount',(SELECT count(*) FROM public.ticket_refund_events WHERE resolved_at IS NULL AND resolution_status IN ('review_required','conflict_review')),
 'emailHeartbeatAgeSeconds',(SELECT greatest(0,extract(epoch FROM clock_timestamp()-observed_at)) FROM public.ticket_worker_heartbeats WHERE worker='email_dispatcher' AND succeeded),
 'checkoutHeartbeatAgeSeconds',(SELECT greatest(0,extract(epoch FROM clock_timestamp()-observed_at)) FROM public.ticket_worker_heartbeats WHERE worker='checkout_recovery' AND succeeded)
 );
$$;

-- FUNCTION: read_ticket_entry_manager_v53(uuid, text)
CREATE FUNCTION public.read_ticket_entry_manager_v53(p_order uuid, p_environment text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT jsonb_build_object('admissionPolicy',o.admission_policy,'originalCount',o.total_quantity,
  'currentLink', (SELECT jsonb_build_object('id',l.id,'generation',l.generation,'revokedAt',l.revoked_at,'expiresAt',l.expires_at)
    FROM public.ticket_order_entry_links l WHERE l.ticket_order_id=o.id ORDER BY generation DESC LIMIT 1),
  'committedOperationId',coalesce((SELECT id FROM public.ticket_order_entry_operations WHERE ticket_order_id=o.id AND state='committed' ORDER BY created_at LIMIT 1),
    (SELECT id FROM public.ticket_admission_operations WHERE ticket_order_id=o.id AND state='committed' ORDER BY created_at LIMIT 1)),
  'exception',(SELECT jsonb_build_object('originalOperationId',x.original_operation_id,'admittedCount',x.admitted_count,'createdAt',x.created_at,'auditLogId',x.audit_log_id)
    FROM public.ticket_entry_exceptions x WHERE x.ticket_order_id=o.id))
 FROM public.ticket_orders o WHERE o.id=p_order AND o.environment=p_environment;
$$;

-- FUNCTION: read_ticket_entry_pending_v53(text, text, integer)
CREATE FUNCTION public.read_ticket_entry_pending_v53(p_environment text, p_account text, p_limit integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('orderId',o.id,'eventSessionId',o.event_session_id,
  'environment',o.environment,'account',o.stripe_account_key,'generation',1,'expiresAt',public.ticket_admission_execution_closes_v56(e.id)) ORDER BY n.created_at,o.id),'[]')
 FROM (SELECT ticket_order_id,created_at FROM public.ticket_purchase_notices WHERE materialized_at IS NULL ORDER BY created_at,ticket_order_id LIMIT greatest(0,least(p_limit,100))) n
 JOIN public.ticket_orders o ON o.id=n.ticket_order_id JOIN public.ticket_event_sessions e ON e.id=o.event_session_id
 WHERE o.admission_policy='order_together_v1' AND o.environment=p_environment AND o.stripe_account_key=p_account
  AND public.ticket_admission_execution_closes_v56(e.id)>clock_timestamp() AND public.ticket_order_has_settled_payment_v30(o.id);
$$;

-- FUNCTION: read_ticket_mail_capacity_v47(text)
CREATE FUNCTION public.read_ticket_mail_capacity_v47(p_provider text DEFAULT 'resend'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF p_provider NOT IN ('resend','fake') THEN RAISE EXCEPTION 'invalid mail capacity provider'; END IF;
 RETURN jsonb_build_object('allowed',true,'reason',NULL,'serverNow',clock_timestamp(),'unlimited',true);
END; $$;

-- FUNCTION: read_ticket_order_entry_authority_v52(uuid, uuid, text, text, text, text, text)
CREATE FUNCTION public.read_ticket_order_entry_authority_v52(p_order uuid, p_session uuid, p_token text, p_csrf text, p_environment text, p_origin text, p_account text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT s.link_id FROM public.ticket_order_entry_sessions s
 JOIN public.ticket_order_entry_links l ON l.id=s.link_id AND l.ticket_order_id=s.ticket_order_id
 JOIN public.ticket_orders o ON o.id=l.ticket_order_id
 JOIN public.ticket_event_sessions e ON e.id=l.event_session_id
 WHERE s.id=p_session AND s.ticket_order_id=p_order
  AND public.ticket_auth_digest_equal_v29(s.token_verifier,p_token)
  AND (p_csrf IS NULL OR public.ticket_auth_digest_equal_v29(s.csrf_verifier,p_csrf))
  AND l.environment=p_environment AND l.public_origin=p_origin AND l.stripe_account_key=p_account
  AND o.environment=l.environment AND o.stripe_account_key=l.stripe_account_key AND o.event_session_id=l.event_session_id
  AND o.admission_policy='order_together_v1' AND l.revoked_at IS NULL
  AND s.expires_at>clock_timestamp() AND l.expires_at>clock_timestamp() AND public.ticket_admission_execution_closes_v56(e.id)>clock_timestamp();
$$;

-- FUNCTION: read_ticket_order_entry_result_v52(uuid, uuid, text, text, text, text, uuid)
CREATE FUNCTION public.read_ticket_order_entry_result_v52(p_order uuid, p_session uuid, p_token text, p_environment text, p_origin text, p_account text, p_operation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE op public.ticket_order_entry_operations%ROWTYPE;
BEGIN
 IF public.read_ticket_order_entry_authority_v52(p_order,p_session,p_token,NULL,p_environment,p_origin,p_account) IS NULL
 THEN RETURN jsonb_build_object('action','unauthenticated'); END IF;
 SELECT * INTO op FROM public.ticket_order_entry_operations WHERE id=p_operation AND ticket_order_id=p_order AND order_session_id=p_session;
 IF NOT FOUND THEN RETURN jsonb_build_object('action','not_found'); END IF;
 IF op.result_json IS NOT NULL THEN RETURN jsonb_build_object('action','result')||op.result_json||jsonb_build_object('reused',true,'serverNow',clock_timestamp()); END IF;
 RETURN jsonb_build_object('action','result','operationId',op.id,'state','pending','admittedCount',0,'admittedAt',NULL,
  'eventTitle',(SELECT event_title FROM public.ticket_orders WHERE id=p_order),'eventDate',(SELECT event_date FROM public.ticket_orders WHERE id=p_order),'serverNow',clock_timestamp());
END $$;

-- FUNCTION: read_ticket_order_entry_v52(uuid, uuid, text, text, text, text)
CREATE FUNCTION public.read_ticket_order_entry_v52(p_order uuid, p_session uuid, p_token text, p_environment text, p_origin text, p_account text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o public.ticket_orders%ROWTYPE; e public.ticket_event_sessions%ROWTYPE; items jsonb; result jsonb;
BEGIN
 IF public.read_ticket_order_entry_authority_v52(p_order,p_session,p_token,NULL,p_environment,p_origin,p_account) IS NULL
 THEN RETURN jsonb_build_object('action','unauthenticated'); END IF;
 SELECT * INTO o FROM public.ticket_orders WHERE id=p_order;
 SELECT * INTO e FROM public.ticket_event_sessions WHERE id=o.event_session_id;
 SELECT jsonb_agg(jsonb_build_object('admissionId',a.id,'eventSessionId',o.event_session_id,'selectionGroupId',o.id,
  'admissionPolicy',o.admission_policy,'serial',a.serial,'label',a.ticket_type_label,'status',
   CASE WHEN o.payment_hold_reason='payment_dispute_open' THEN 'disputed'
    WHEN o.status='refunded' OR o.payment_hold_reason='charge_refunded' OR EXISTS(SELECT 1 FROM public.ticket_refund_events WHERE ticket_order_id=o.id AND resolution_status IN ('review_required','conflict_review') AND resolved_at IS NULL) THEN 'refunded'
    ELSE a.status END,'admittedAt',a.admitted_at) ORDER BY a.serial) INTO items
  FROM public.ticket_admissions a WHERE a.ticket_order_id=o.id;
 SELECT result_json INTO result FROM public.ticket_order_entry_operations WHERE ticket_order_id=o.id AND state='committed' ORDER BY created_at LIMIT 1;
 IF result IS NULL THEN SELECT result_json INTO result FROM public.ticket_admission_operations WHERE ticket_order_id=o.id AND state='committed' ORDER BY created_at LIMIT 1; END IF;
 RETURN jsonb_build_object('action','read','orderId',o.id,'publicCode',o.public_code,'originalCount',o.total_quantity,
  'termsVersion',o.items_json->0->'commercial'->>'version','orderVersion',o.admission_version,'serverNow',clock_timestamp(),
  'event',jsonb_build_object('eventSessionId',e.id,'eventTitle',o.event_title,'eventDate',o.event_date,'doorsAt',e.door_at,
   'demoAdmissionTest',EXISTS(SELECT 1 FROM public.ticket_demo_admission_windows_v56 w WHERE w.event_session_id=e.id AND e.environment='test'),
   'admissionOpensAt',e.admission_opens_at,'admissionClosesAt',e.admission_closes_at,'admissions',coalesce(items,'[]')),
  'result',CASE WHEN result IS NULL THEN NULL ELSE result||jsonb_build_object('serverNow',clock_timestamp()) END);
END $$;

-- FUNCTION: read_ticket_public_sales_v33(text, text)
CREATE FUNCTION public.read_ticket_public_sales_v33(p_environment text, p_stripe_account_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
SELECT jsonb_build_object('serverNow',statement_timestamp(),'days',COALESCE((
 SELECT jsonb_agg(jsonb_build_object(
  'date',d.business_date,'operatingStatus',d.operating_status,'salesOpenAt',d.sales_open_at,'salesCloseAt',d.sales_close_at,
  'sessions',COALESCE((SELECT jsonb_agg(jsonb_build_object(
   'eventId',s.catalog_event_id,'checkInMode',s.sales_check_in_mode,'enabled',s.enabled,'salesState',s.sales_state,
   'admissionState',s.admission_state,'closeAt',s.close_at,'salesLaunchAt',p.sales_launch_at,
   'published',COALESCE(p.published,false),'inventoryMode',COALESCE(p.inventory_mode,'pending'),
   'remaining',CASE WHEN p.inventory_mode='finite' THEN GREATEST(0,p.capacity-(SELECT COALESCE(sum(o.total_quantity),0) FROM public.ticket_orders o LEFT JOIN public.ticket_checkout_actions a ON a.ticket_order_id=o.id WHERE o.event_session_id=s.id AND NOT COALESCE((o.status IN ('expired','cancelled') AND o.paid_at IS NULL AND o.provider_paid_at IS NULL AND (a.provider_terminal_status='expired' OR (a.checkout_session_id IS NULL AND o.checkout_session_id IS NULL AND a.state IS DISTINCT FROM 'review_required')) AND NOT EXISTS(SELECT 1 FROM public.ticket_admissions ad WHERE ad.ticket_order_id=o.id AND ad.status<>'void')),false))) ELSE NULL END,
   'products',COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'id',t.ticket_type_id,'labelJa',t.label_ja,'labelEn',t.label_en,
    'descriptionJa',t.description_ja,'descriptionEn',t.description_en,
    'priceYen',t.price_yen,'enabled',t.enabled,'salesEndsAt',LEAST(t.sales_close_at,d.sales_close_at))
    ORDER BY t.ticket_type_id) FROM public.ticket_sale_products t WHERE t.event_session_id=s.id),'[]'::jsonb)
  ) ORDER BY s.catalog_event_id) FROM public.ticket_event_sessions s
   LEFT JOIN public.ticket_sale_publications p ON p.event_session_id=s.id
   WHERE s.event_day_id=d.id AND s.environment=p_environment
   AND s.stripe_account_key=COALESCE(p_stripe_account_id,'platform')),'[]'::jsonb)
 ) ORDER BY d.business_date)
 FROM public.event_days d WHERE d.business_date BETWEEN
 (statement_timestamp() AT TIME ZONE 'Asia/Tokyo')::date AND
 ((statement_timestamp() AT TIME ZONE 'Asia/Tokyo')::date + interval '1 month')::date
),'[]'::jsonb));
$$;

-- FUNCTION: read_ticket_purchase_deliveries_v55(text, text, text)
CREATE FUNCTION public.read_ticket_purchase_deliveries_v55(p_browser_verifier text, p_environment text, p_session_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('ticket_order_id',authorized.row->>'orderId',
  'state',j.state,'provider_delivery_state',j.provider_delivery_state,'accepted_at',j.accepted_at)), '[]'::jsonb)
 FROM jsonb_array_elements(public.read_ticket_purchase_receipts_v36(p_browser_verifier,p_environment,p_session_id)->'orders') authorized(row)
 LEFT JOIN LATERAL (
  SELECT state,provider_delivery_state,accepted_at
  FROM public.transactional_email_jobs
  WHERE ticket_order_id=(authorized.row->>'orderId')::uuid AND purpose='ticket_wallet_purchase'
  ORDER BY created_at DESC,id DESC LIMIT 1
 ) j ON true;
$$;

-- FUNCTION: read_ticket_purchase_entry_v53(text, uuid, text, text, text)
CREATE FUNCTION public.read_ticket_purchase_entry_v53(p_browser_verifier text, p_order uuid, p_environment text, p_origin text, p_account text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT jsonb_build_object('linkId',l.id,'orderId',o.id,'eventSessionId',l.event_session_id,'generation',l.generation,
 'environment',l.environment,'origin',l.public_origin,'account',l.stripe_account_key,'ciphertext',l.secret_ciphertext)
 FROM public.ticket_purchase_browser_bindings b JOIN public.ticket_checkout_actions a ON a.id=b.checkout_action_id
 JOIN public.ticket_orders o ON o.id=a.ticket_order_id JOIN public.ticket_order_entry_links l ON l.ticket_order_id=o.id
 JOIN public.ticket_event_sessions e ON e.id=l.event_session_id
 WHERE b.browser_verifier=p_browser_verifier AND b.expires_at>clock_timestamp() AND o.id=p_order
 AND o.admission_policy='order_together_v1' AND public.ticket_order_has_settled_payment_v30(o.id)
 AND o.environment=p_environment AND l.environment=o.environment AND o.stripe_account_key=p_account AND l.stripe_account_key=p_account
 AND l.public_origin=p_origin AND l.revoked_at IS NULL AND l.expires_at>clock_timestamp() AND public.ticket_admission_execution_closes_v56(e.id)>clock_timestamp()
 LIMIT 1;
$$;

-- FUNCTION: read_ticket_purchase_receipts_v36(text, text, text)
CREATE FUNCTION public.read_ticket_purchase_receipts_v36(p_browser_verifier text, p_environment text, p_session_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT jsonb_build_object('orders',COALESCE(jsonb_agg(row),'[]'::jsonb)) FROM (
 SELECT o.id AS "orderId",o.public_code AS "publicCode",o.event_title AS "eventTitle",o.event_date AS "eventDate",o.total_quantity AS quantity,o.admission_policy AS "admissionPolicy",
 CASE WHEN a.state='review_required' OR o.payment_hold_reason IS NOT NULL THEN 'review_required'
 WHEN o.status='fulfilled' THEN 'fulfilled' WHEN o.status='paid' THEN 'issuing'
 WHEN o.status IN ('cancelled','expired','refunded') THEN o.status ELSE 'payment_pending' END AS state
 FROM public.ticket_purchase_browser_bindings b JOIN public.ticket_checkout_actions a ON a.id=b.checkout_action_id JOIN public.ticket_orders o ON o.id=a.ticket_order_id
 WHERE b.browser_verifier=p_browser_verifier AND b.expires_at>clock_timestamp() AND o.environment=p_environment
 AND (p_session_id IS NULL OR a.checkout_session_id=p_session_id)
 ORDER BY b.created_at DESC,b.checkout_action_id DESC LIMIT 10
 ) row;
$$;

-- FUNCTION: read_ticket_wallet_manager_order_v29(text, text, uuid)
CREATE FUNCTION public.read_ticket_wallet_manager_order_v29(p_environment text, p_identity_email_hash text, p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_sessions jsonb;
  v_jobs jsonb;
  v_challenges jsonb;
  v_audits jsonb;
  v_events jsonb;
  v_circuits jsonb;
BEGIN
  IF p_environment NOT IN ('test', 'live') OR p_order_id IS NULL
    OR (p_identity_email_hash IS NOT NULL
      AND char_length(p_identity_email_hash) NOT BETWEEN 16 AND 256)
  THEN
    RAISE EXCEPTION 'invalid Ticket Wallet manager order projection';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.ticket_orders AS ticket_order
    WHERE ticket_order.id = p_order_id
      AND ticket_order.environment = p_environment
      AND ticket_order.check_in_mode = 'wallet_swipe'
      AND ticket_order.purchaser_email_hash IS NOT DISTINCT FROM p_identity_email_hash
  ) THEN
    RETURN jsonb_build_object('action', 'not_found');
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(projected)), '[]'::jsonb)
  INTO v_sessions
  FROM (
    SELECT session.id, session.verified_at, session.fresh_until,
      session.expires_at, session.revoked_at, session.entity_version,
      session.created_at, session.updated_at
    FROM public.ticket_wallet_sessions AS session
    WHERE session.environment = p_environment
      AND session.identity_email_hash = p_identity_email_hash
    ORDER BY session.created_at DESC, session.id
    LIMIT 20
  ) AS projected;

  SELECT COALESCE(jsonb_agg(to_jsonb(projected)), '[]'::jsonb)
  INTO v_jobs
  FROM (
    SELECT job.id, job.purpose, job.ticket_order_id, job.state, job.provider_delivery_state,
      job.attempt_count, job.next_attempt_at, job.entity_version,
      job.created_at, job.updated_at
    FROM public.transactional_email_jobs AS job
    LEFT JOIN public.ticket_wallet_otp_challenges AS challenge
      ON challenge.id = job.otp_challenge_id
    LEFT JOIN public.ticket_orders AS purchase ON purchase.id=job.ticket_order_id
    WHERE COALESCE(challenge.environment,purchase.environment) = p_environment
      AND job.recipient_email_hash = p_identity_email_hash
      AND (job.ticket_order_id IS NULL OR job.ticket_order_id=p_order_id)
    ORDER BY job.created_at DESC, job.id
    LIMIT 20
  ) AS projected;

  SELECT COALESCE(jsonb_agg(to_jsonb(projected)), '[]'::jsonb)
  INTO v_challenges
  FROM (
    SELECT challenge.state, challenge.requested_at,
      challenge.resend_available_at, challenge.expires_at
    FROM public.ticket_wallet_otp_challenges AS challenge
    WHERE challenge.environment = p_environment
      AND challenge.identity_email_hash = p_identity_email_hash
    ORDER BY challenge.requested_at DESC, challenge.id
    LIMIT 1
  ) AS projected;

  SELECT COALESCE(jsonb_agg(to_jsonb(projected)), '[]'::jsonb)
  INTO v_audits
  FROM (
    SELECT audit.id, audit.action, audit.reason, audit.created_at
    FROM public.ticket_wallet_manager_audits AS audit
    WHERE (
        audit.entity_type = 'wallet_session'
        AND EXISTS (
          SELECT 1 FROM public.ticket_wallet_sessions AS session
          WHERE session.id = audit.entity_id
            AND session.environment = p_environment
            AND session.identity_email_hash = p_identity_email_hash
        )
      ) OR (
        audit.entity_type = 'transactional_email_job'
        AND EXISTS (
          SELECT 1
          FROM public.transactional_email_jobs AS job
          JOIN public.ticket_wallet_otp_challenges AS challenge
            ON challenge.id = job.otp_challenge_id
          WHERE job.id = audit.entity_id
            AND challenge.environment = p_environment
            AND job.recipient_email_hash = p_identity_email_hash
      AND (job.ticket_order_id IS NULL OR job.ticket_order_id=p_order_id)
        )
      )
    ORDER BY audit.created_at DESC, audit.id
    LIMIT 100
  ) AS projected;

  SELECT COALESCE(jsonb_agg(to_jsonb(projected)), '[]'::jsonb)
  INTO v_events
  FROM (
    SELECT event.occurred_at
    FROM public.transactional_email_provider_events AS event
    WHERE event.provider_name = 'resend'
    ORDER BY event.occurred_at DESC, event.id
    LIMIT 1
  ) AS projected;

  SELECT COALESCE(jsonb_agg(to_jsonb(projected)), '[]'::jsonb)
  INTO v_circuits
  FROM (
    SELECT circuit.is_open
    FROM public.transactional_email_provider_circuits AS circuit
    WHERE circuit.provider_name = 'resend'
    LIMIT 1
  ) AS projected;

  RETURN jsonb_build_object(
    'action', 'read',
    'sessions', v_sessions,
    'emailJobs', v_jobs,
    'otpChallenges', v_challenges,
    'managerAudits', v_audits,
    'providerEvents', v_events,
    'providerCircuits', v_circuits
  );
END;
$$;

-- FUNCTION: read_ticket_wallet_manager_queue_v29(text, text[])
CREATE FUNCTION public.read_ticket_wallet_manager_queue_v29(p_environment text, p_identity_email_hashes text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_sessions jsonb;
  v_jobs jsonb;
  v_events jsonb;
  v_circuits jsonb;
BEGIN
  IF p_environment NOT IN ('test', 'live')
    OR p_identity_email_hashes IS NULL
    OR cardinality(p_identity_email_hashes) > 100
    OR EXISTS (
      SELECT 1 FROM unnest(p_identity_email_hashes) AS identity_hash
      WHERE identity_hash IS NULL
        OR char_length(identity_hash) NOT BETWEEN 16 AND 256
    )
  THEN
    RAISE EXCEPTION 'invalid Ticket Wallet manager queue projection';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(projected)), '[]'::jsonb)
  INTO v_sessions
  FROM (
    SELECT session.id, session.identity_email_hash, session.verified_at,
      session.fresh_until, session.expires_at, session.revoked_at,
      session.entity_version, session.created_at, session.updated_at
    FROM public.ticket_wallet_sessions AS session
    WHERE session.environment = p_environment
      AND session.identity_email_hash = ANY(p_identity_email_hashes)
    ORDER BY session.updated_at DESC, session.id
    LIMIT 200
  ) AS projected;

  SELECT COALESCE(jsonb_agg(to_jsonb(projected)), '[]'::jsonb)
  INTO v_jobs
  FROM (
    SELECT job.id, job.purpose, job.ticket_order_id, job.recipient_email_hash, job.state,
      job.provider_delivery_state, job.attempt_count, job.next_attempt_at,
      job.entity_version, job.created_at, job.updated_at
    FROM public.transactional_email_jobs AS job
    LEFT JOIN public.ticket_wallet_otp_challenges AS challenge
      ON challenge.id = job.otp_challenge_id
    LEFT JOIN public.ticket_orders AS purchase ON purchase.id=job.ticket_order_id
    WHERE COALESCE(challenge.environment,purchase.environment) = p_environment
      AND job.recipient_email_hash = ANY(p_identity_email_hashes)
    ORDER BY job.updated_at DESC, job.id
    LIMIT 200
  ) AS projected;

  SELECT COALESCE(jsonb_agg(to_jsonb(projected)), '[]'::jsonb)
  INTO v_events
  FROM (
    SELECT event.occurred_at
    FROM public.transactional_email_provider_events AS event
    WHERE event.provider_name = 'resend'
    ORDER BY event.occurred_at DESC, event.id
    LIMIT 1
  ) AS projected;

  SELECT COALESCE(jsonb_agg(to_jsonb(projected)), '[]'::jsonb)
  INTO v_circuits
  FROM (
    SELECT circuit.is_open
    FROM public.transactional_email_provider_circuits AS circuit
    WHERE circuit.provider_name = 'resend'
    LIMIT 1
  ) AS projected;

  RETURN jsonb_build_object(
    'action', 'read',
    'sessions', v_sessions,
    'emailJobs', v_jobs,
    'providerEvents', v_events,
    'providerCircuits', v_circuits
  );
END;
$$;

-- FUNCTION: read_ticket_wallet_session_v29(text, timestamp with time zone, uuid, text, text)
CREATE FUNCTION public.read_ticket_wallet_session_v29(p_environment text, p_now timestamp with time zone, p_session_id uuid, p_session_token_verifier text, p_session_csrf_verifier text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_session public.ticket_wallet_sessions%ROWTYPE;
BEGIN
  IF p_environment NOT IN ('test', 'live') OR p_session_id IS NULL
    OR p_now IS NULL OR abs(extract(epoch FROM (p_now - v_now))) > 300
  THEN
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;
  SELECT * INTO v_session
  FROM public.ticket_wallet_sessions
  WHERE id = p_session_id AND environment = p_environment
  FOR UPDATE;
  IF NOT FOUND OR v_session.revoked_at IS NOT NULL
    OR NOT public.ticket_auth_digest_equal_v29(v_session.token_verifier, p_session_token_verifier)
    OR NOT public.ticket_auth_digest_equal_v29(v_session.csrf_verifier, p_session_csrf_verifier)
  THEN
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;
  IF v_session.expires_at <= v_now THEN
    UPDATE public.ticket_wallet_sessions
    SET revoked_at = v_now, revocation_reason = 'expired',
        token_verifier = NULL, csrf_verifier = NULL, updated_at = v_now
    WHERE id = v_session.id;
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;
  RETURN jsonb_build_object(
    'action', 'authenticated', 'sessionId', v_session.id,
    'expiresAt', v_session.expires_at, 'freshUntil', v_session.fresh_until
  );
END;
$$;

-- FUNCTION: read_ticket_wallet_v30(text, uuid, text)
CREATE FUNCTION public.read_ticket_wallet_v30(p_environment text, p_wallet_session_id uuid, p_session_token_verifier text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_session public.ticket_wallet_sessions%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_events jsonb;
BEGIN
  IF COALESCE(p_environment, '') NOT IN ('test', 'live')
    OR p_wallet_session_id IS NULL
    OR NULLIF(btrim(COALESCE(p_session_token_verifier, '')), '') IS NULL
  THEN
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;

  SELECT * INTO v_session
  FROM public.ticket_wallet_sessions
  WHERE id = p_wallet_session_id
    AND environment = p_environment;

  IF NOT FOUND
    OR v_session.revoked_at IS NOT NULL
    OR v_session.expires_at <= v_now
    OR v_session.identity_email_hash IS NULL
    OR NOT public.ticket_auth_digest_equal_v29(
      v_session.token_verifier, p_session_token_verifier)
  THEN
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'eventSessionId', grouped.event_session_id,
      'eventTitle', grouped.event_title,
      'eventDate', grouped.event_date,
      'doorsAt', grouped.door_at,
      'demoAdmissionTest',EXISTS(SELECT 1 FROM public.ticket_demo_admission_windows_v56 w WHERE w.event_session_id=grouped.event_session_id AND p_environment='test'),
      'admissionOpensAt', grouped.admission_opens_at,
      'admissionClosesAt', grouped.admission_closes_at,
      'admissions', grouped.admissions
    ) ORDER BY grouped.admission_opens_at, grouped.event_session_id
  ), '[]'::jsonb)
  INTO v_events
  FROM (
    SELECT
      event_session.id AS event_session_id,
      min(ticket_order.event_title) AS event_title,
      event_session.event_date,
      event_session.door_at,
      event_session.admission_opens_at,
      event_session.admission_closes_at,
      jsonb_agg(
        jsonb_build_object(
          'admissionId', admission.id,
          'eventSessionId', event_session.id,
          -- Public UUID groups Admissions for selection UX only. The prepare
          -- RPC ignores it and re-derives/locks Ticket Order authority.
          'selectionGroupId', ticket_order.id,
          'admissionPolicy', ticket_order.admission_policy,
          'serial', admission.serial,
          'label', admission.ticket_type_label,
          'status', CASE
            WHEN ticket_order.payment_hold_reason = 'payment_dispute_open'
              THEN 'disputed'
            WHEN EXISTS (
              SELECT 1
              FROM public.ticket_refund_events AS unresolved_refund
              WHERE unresolved_refund.ticket_order_id = ticket_order.id
                AND unresolved_refund.money_may_have_moved
                AND unresolved_refund.resolution_status IN (
                  'review_required', 'conflict_review')
                AND unresolved_refund.resolved_at IS NULL
            ) THEN 'refunded'
            WHEN ticket_order.status = 'refunded'
              OR ticket_order.payment_hold_reason = 'charge_refunded'
              THEN 'refunded'
            ELSE admission.status
          END,
          'admittedAt', admission.admitted_at
        ) ORDER BY ticket_order.created_at, ticket_order.id, admission.serial
      ) AS admissions
    FROM public.ticket_orders AS ticket_order
    JOIN public.ticket_event_sessions AS event_session
      ON event_session.id = ticket_order.event_session_id
     AND event_session.environment = ticket_order.environment
     AND event_session.stripe_account_key = ticket_order.stripe_account_key
    JOIN public.ticket_admissions AS admission
      ON admission.ticket_order_id = ticket_order.id
    WHERE ticket_order.environment = p_environment
      AND ticket_order.check_in_mode = 'wallet_swipe'
      AND public.ticket_holder_has_order_v34(v_session.holder_id,ticket_order.id)
      AND ticket_order.fulfilled_at IS NOT NULL
      AND ticket_order.status IN ('fulfilled', 'refunded')
      AND event_session.admission_closes_at + interval '8 days' > v_now
    GROUP BY event_session.id, event_session.event_date, event_session.door_at,
             event_session.admission_opens_at, event_session.admission_closes_at
  ) AS grouped;

  RETURN jsonb_build_object(
    'action', 'read',
    'serverNow', v_now,
    'events', v_events
  );
END;
$$;

-- FUNCTION: read_transactional_email_dead_items_v59(integer)
CREATE FUNCTION public.read_transactional_email_dead_items_v59(p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'invalid transactional email dead items limit';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(item ORDER BY item.updated_at DESC)
    FROM (
      SELECT
        job.id,
        job.purpose,
        job.state,
        job.provider_delivery_state,
        job.attempt_count,
        job.next_attempt_at,
        job.claimed_at,
        job.lease_expires_at,
        job.safe_error_category,
        job.manager_recovery_count,
        right(job.recipient_email_hash, 4) AS recipient_hash_last4,
        job.created_at,
        job.updated_at
      FROM public.transactional_email_jobs AS job
      WHERE job.state IN ('retry', 'dead', 'configuration', 'cancelled')
        OR job.provider_delivery_state IN ('bounced', 'complained', 'suppressed', 'failed')
        -- R-12 "processing aged": a claim whose lease lapsed without a mark
        -- is operationally dead-lettered even though its state still reads
        -- 'processing'; surface it instead of leaving it invisible.
        OR (job.state = 'processing' AND job.lease_expires_at IS NOT NULL AND job.lease_expires_at < now())
      ORDER BY job.updated_at DESC
      LIMIT p_limit
    ) AS item
  ), '[]'::jsonb);
END;
$$;

-- FUNCTION: reconcile_ticket_checkout_action_v28(uuid, text, text, text, text, timestamp with time zone)
CREATE FUNCTION public.reconcile_ticket_checkout_action_v28(p_checkout_action_id uuid, p_request_hash text, p_provider_idempotency_key text, p_checkout_session_id text, p_provider_response_hash text, p_provider_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_provider_key text;
  v_result jsonb;
BEGIN
  SELECT provider_idempotency_key INTO v_provider_key
  FROM public.ticket_checkout_actions
  WHERE id = p_checkout_action_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('action', 'not_found'); END IF;
  IF v_provider_key <> btrim(COALESCE(p_provider_idempotency_key, '')) THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'provider_idempotency_key_mismatch');
  END IF;

  v_result := public.record_ticket_checkout_provider_result_v28(
    p_checkout_action_id, p_request_hash, p_checkout_session_id,
    p_provider_response_hash, p_provider_expires_at);
  UPDATE public.ticket_checkout_actions
  SET reconciliation_count = reconciliation_count + 1,
      updated_at = now()
  WHERE id = p_checkout_action_id;
  RETURN v_result;
END;
$$;

-- FUNCTION: reconcile_vip_floor_v2_phase_c_v8(uuid, text, boolean)
CREATE FUNCTION public.reconcile_vip_floor_v2_phase_c_v8(p_actor_admin_id uuid, p_request_id text, p_apply boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor public.admin_users%ROWTYPE;
  v_run_id uuid := gen_random_uuid();
  v_request_id text := NULLIF(btrim(COALESCE(p_request_id, '')), '');
  v_before jsonb;
  v_after jsonb;
  v_repaired_reservations bigint := 0;
  v_seeded_revisions bigint := 0;
  v_issue_count bigint := 0;
BEGIN
  SELECT *
  INTO v_actor
  FROM public.admin_users
  WHERE id = p_actor_admin_id
  FOR UPDATE;

  IF NOT FOUND OR NOT v_actor.active OR v_actor.role NOT IN ('owner', 'engineer') THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'FORBIDDEN',
        'details', jsonb_build_object('capability', 'vip_floor.reconcile')
      )
    );
  END IF;

  IF v_request_id IS NULL OR char_length(v_request_id) > 255 THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object('field', 'requestId')
      )
    );
  END IF;

  IF COALESCE(p_apply, false) AND NOT public.vip_floor_v2_dual_write_enabled() THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'FLAG_MISALIGNED',
        'details', jsonb_build_object(
          'requiredDatabaseSetting', 'vip_floor_v2_dual_write=true'
        )
      )
    );
  END IF;

  v_before := public.vip_floor_reconciliation_counts_v8();

  IF COALESCE(p_apply, false) THEN
    -- A revision row represents current observable state, not invented
    -- historical increments. Seed it at zero before any repaired semantic row
    -- is allowed to generate a real Phase C revision.
    INSERT INTO public.vip_floor_day_revisions(event_day_id, revision)
    SELECT ed.id, 0
    FROM public.event_days AS ed
    LEFT JOIN public.vip_floor_day_revisions AS existing
      ON existing.event_day_id = ed.id
    WHERE existing.event_day_id IS NULL
    ON CONFLICT (event_day_id) DO NOTHING;
    GET DIAGNOSTICS v_seeded_revisions = ROW_COUNT;

    -- These lifecycle projections are deterministic. Advanced service states
    -- are never collapsed back to expected/seated.
    UPDATE public.reservations AS reservation
    SET service_status = CASE reservation.status
          WHEN 'checked_in' THEN 'seated'::public.vip_service_status
          ELSE 'expected'::public.vip_service_status
        END,
        service_status_changed_at = COALESCE(
          reservation.service_status_changed_at,
          reservation.checked_in_at,
          reservation.confirmed_at,
          reservation.updated_at,
          now()
        )
    WHERE (reservation.status = 'confirmed' AND reservation.service_status IS NULL)
       OR (
         reservation.status = 'checked_in'
         AND (
           reservation.service_status IS NULL
           OR reservation.service_status = 'expected'::public.vip_service_status
         )
       );
    GET DIAGNOSTICS v_repaired_reservations = ROW_COUNT;
  END IF;

  -- Ambiguous cases are protected internal evidence. Only issue codes and
  -- internal references are stored; no PII, note text, ciphertext, or provider
  -- identifier is copied.
  INSERT INTO public.audit_logs(
    actor_admin_id,
    actor_type,
    action,
    target_table,
    target_id,
    request_id,
    entity_type,
    entity_id,
    operation,
    metadata_json
  )
  SELECT
    p_actor_admin_id,
    'admin',
    'vip_floor.reconciliation.issue',
    issue.entity_type,
    issue.entity_id,
    v_request_id,
    issue.entity_type,
    issue.entity_id,
    'reconciliation_issue',
    jsonb_build_object(
      'runId', v_run_id,
      'issueCode', issue.issue_code,
      'redaction', 'internal_reference_only'
    )
  FROM (
    SELECT
      'reservation_resources'::text AS entity_type,
      rr.id AS entity_id,
      'ASSIGNMENT_OUTSIDE_RESERVATION_INTERVAL'::text AS issue_code
    FROM public.reservation_resources AS rr
    JOIN public.reservations AS r ON r.id = rr.reservation_id
    WHERE rr.released_at IS NULL
      AND rr.lock_status IN ('held', 'payment_grace_locked', 'confirmed')
      AND (
        rr.assigned_start_at < r.scheduled_start_at
        OR rr.assigned_end_at > r.expected_release_at
      )

    UNION ALL

    SELECT
      'reservation_resources',
      left_assignment.id,
      'ACTIVE_RESOURCE_OVERLAP'
    FROM public.reservation_resources AS left_assignment
    JOIN public.reservations AS left_reservation
      ON left_reservation.id = left_assignment.reservation_id
    JOIN public.reservation_resources AS right_assignment
      ON right_assignment.id > left_assignment.id
     AND right_assignment.seat_resource_id = left_assignment.seat_resource_id
     AND right_assignment.assigned_start_at < left_assignment.assigned_end_at
     AND right_assignment.assigned_end_at > left_assignment.assigned_start_at
    JOIN public.reservations AS right_reservation
      ON right_reservation.id = right_assignment.reservation_id
    WHERE left_assignment.released_at IS NULL
      AND right_assignment.released_at IS NULL
      AND left_assignment.lock_status IN ('held', 'payment_grace_locked', 'confirmed')
      AND right_assignment.lock_status IN ('held', 'payment_grace_locked', 'confirmed')
      AND left_reservation.status NOT IN ('cancelled', 'hold_expired', 'payment_window_expired', 'failed')
      AND right_reservation.status NOT IN ('cancelled', 'hold_expired', 'payment_window_expired', 'failed')

    UNION ALL

    SELECT
      'customer_profiles',
      profile.customer_id,
      'CUSTOMER_CIPHERTEXT_SEARCH_HASH_INCONSISTENT'
    FROM public.customer_profiles AS profile
    WHERE (
      profile.display_name_ciphertext IS NOT NULL
      AND NULLIF(profile.display_name_search_token, '') IS NULL
    ) OR (
      profile.display_name_ciphertext IS NULL
      AND profile.display_name_search_token IS NOT NULL
    )
  ) AS issue;
  GET DIAGNOSTICS v_issue_count = ROW_COUNT;

  v_after := public.vip_floor_reconciliation_counts_v8();

  INSERT INTO public.audit_logs(
    actor_admin_id,
    actor_type,
    action,
    request_id,
    operation,
    metadata_json
  )
  VALUES (
    p_actor_admin_id,
    'admin',
    CASE WHEN COALESCE(p_apply, false)
      THEN 'vip_floor.reconciliation.apply'
      ELSE 'vip_floor.reconciliation.dry_run'
    END,
    v_request_id,
    'reconciliation',
    jsonb_build_object(
      'runId', v_run_id,
      'applied', COALESCE(p_apply, false),
      'repairedReservations', v_repaired_reservations,
      'seededRevisionRows', v_seeded_revisions,
      'issueCount', v_issue_count,
      'before', v_before,
      'after', v_after,
      'redaction', 'aggregate_only'
    )
  );

  RETURN jsonb_build_object(
    'action', CASE WHEN COALESCE(p_apply, false) THEN 'reconciled' ELSE 'dry_run' END,
    'runId', v_run_id,
    'applied', COALESCE(p_apply, false),
    'repairedReservations', v_repaired_reservations,
    'seededRevisionRows', v_seeded_revisions,
    'issueCount', v_issue_count,
    'before', v_before,
    'after', v_after
  );
END;
$$;

-- FUNCTION: record_admin_audit_event_v1(uuid, text, text, text, jsonb, text, uuid)
CREATE FUNCTION public.record_admin_audit_event_v1(p_actor_admin_id uuid, p_action text, p_request_id text, p_reason text, p_after_json jsonb, p_target_table text, p_target_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_action IS NULL OR p_action NOT IN (
    'admin_worker.run',
    'admin_session.bootstrap_issue',
    'admin_session.service_issue'
  ) THEN
    RETURN false;
  END IF;

  INSERT INTO public.audit_logs (
    actor_admin_id,
    actor_type,
    action,
    request_id,
    reason,
    after_json,
    target_table,
    target_id
  ) VALUES (
    p_actor_admin_id,
    'admin',
    p_action,
    p_request_id,
    p_reason,
    COALESCE(p_after_json, '{}'::jsonb),
    p_target_table,
    p_target_id
  );

  RETURN true;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$$;

-- FUNCTION: record_external_stripe_money_event_v8(text, text, text, text, text, text, timestamp with time zone, jsonb)
CREATE FUNCTION public.record_external_stripe_money_event_v8(p_environment text, p_stripe_account_id text, p_object_type text, p_object_id text, p_stripe_status text, p_last_event_id text, p_last_event_created_at timestamp with time zone, p_payload_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb := '[]'::jsonb;
  v_step jsonb;
  v_refund_json jsonb;
  v_amount_refunded bigint;
  v_review_id uuid;
BEGIN
  IF p_object_type = 'refund' THEN
    v_step := public.apply_external_refund_fact_v8(
      p_environment, p_stripe_account_id, p_object_id, p_stripe_status,
      COALESCE((p_payload_json ->> 'amount')::bigint, 0),
      p_payload_json ->> 'currency',
      p_payload_json ->> 'charge',
      p_payload_json ->> 'payment_intent',
      p_payload_json -> 'metadata',
      p_payload_json,
      p_last_event_id, p_last_event_created_at
    );
    RETURN v_step;
  END IF;

  IF p_object_type = 'dispute' THEN
    RETURN public.apply_external_dispute_fact_v8(
      p_environment, p_stripe_account_id, p_object_id, p_stripe_status,
      COALESCE((p_payload_json ->> 'amount')::bigint, 0),
      p_payload_json ->> 'currency',
      p_payload_json ->> 'reason',
      p_payload_json ->> 'charge',
      p_payload_json ->> 'payment_intent',
      p_payload_json,
      p_last_event_id, p_last_event_created_at
    );
  END IF;

  -- charge.refunded / charge.refund.updated deliver the aggregate charge; each
  -- embedded refund object is applied as its own fact. An aggregate with no
  -- refund detail cannot be decomposed and goes to review instead of being
  -- silently trusted.
  IF p_object_type = 'charge' THEN
    FOR v_refund_json IN
      SELECT value FROM jsonb_array_elements(COALESCE(p_payload_json -> 'refunds' -> 'data', '[]'::jsonb))
    LOOP
      v_step := public.apply_external_refund_fact_v8(
        p_environment, p_stripe_account_id,
        v_refund_json ->> 'id', v_refund_json ->> 'status',
        COALESCE((v_refund_json ->> 'amount')::bigint, 0),
        v_refund_json ->> 'currency',
        COALESCE(v_refund_json ->> 'charge', p_object_id),
        COALESCE(v_refund_json ->> 'payment_intent', p_payload_json ->> 'payment_intent'),
        v_refund_json -> 'metadata',
        v_refund_json,
        p_last_event_id, p_last_event_created_at
      );
      v_result := v_result || jsonb_build_array(v_step);
    END LOOP;

    v_amount_refunded := COALESCE((p_payload_json ->> 'amount_refunded')::bigint, 0);
    IF jsonb_array_length(v_result) = 0 AND v_amount_refunded > 0 THEN
      INSERT INTO public.external_finance_reviews(
        environment, stripe_account_id, event_kind, provider_object_id,
        amount_yen, currency, reason, payload_json
      ) VALUES (
        p_environment, p_stripe_account_id, 'charge_refund_aggregate', p_object_id,
        v_amount_refunded, lower(btrim(COALESCE(p_payload_json ->> 'currency', 'jpy'))),
        'refund_detail_missing', COALESCE(p_payload_json, '{}'::jsonb)
      )
      ON CONFLICT (environment, stripe_account_key, event_kind, provider_object_id, reason)
      DO UPDATE SET payload_json = EXCLUDED.payload_json, updated_at = now()
      RETURNING id INTO v_review_id;
      RETURN jsonb_build_object('applied', false, 'reason', 'refund_detail_missing', 'reviewId', v_review_id);
    END IF;

    RETURN jsonb_build_object('applied', jsonb_array_length(v_result) > 0, 'refundResults', v_result);
  END IF;

  RETURN jsonb_build_object('applied', false, 'reason', 'unsupported_object_type');
END;
$$;

-- FUNCTION: record_public_hold_abuse_audit_v7(text, text, text, text, text, text, text, text, text)
CREATE FUNCTION public.record_public_hold_abuse_audit_v7(p_ip_hash text, p_ua_hash text, p_email_hash text, p_phone_hash text, p_public_slot_id text, p_request_hash text, p_decision text, p_turnstile_result text, p_request_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_booking_slot_id uuid;
BEGIN
  SELECT id INTO v_booking_slot_id
  FROM booking_slots
  WHERE public_slot_id = p_public_slot_id
  LIMIT 1;

  INSERT INTO abuse_audit_events(
    ip_hash,
    ua_hash,
    email_hash,
    phone_hash,
    booking_slot_id,
    request_hash,
    decision,
    turnstile_result,
    request_id
  )
  VALUES (
    p_ip_hash,
    p_ua_hash,
    p_email_hash,
    p_phone_hash,
    v_booking_slot_id,
    p_request_hash,
    left(COALESCE(p_decision, 'unknown'), 80),
    left(COALESCE(p_turnstile_result, 'unknown'), 80),
    left(COALESCE(p_request_id, ''), 160)
  );
END;
$$;

-- FUNCTION: record_public_reservation_hold_stripe_created_v7(text, text, text, text, text, text, jsonb)
CREATE FUNCTION public.record_public_reservation_hold_stripe_created_v7(p_source_system text, p_idempotency_key text, p_request_hash text, p_provider_object_type text, p_provider_object_id text, p_client_secret_ciphertext text, p_response_snapshot_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_hold reservation_hold_requests%ROWTYPE;
BEGIN
  SELECT * INTO v_hold
  FROM reservation_hold_requests
  WHERE source_system = p_source_system
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'reservation hold request not found';
  END IF;

  IF v_hold.request_hash <> p_request_hash THEN
    RETURN jsonb_build_object(
      'action', 'mismatch',
      'error', 'idempotency_key_reused_with_different_request'
    );
  END IF;

  UPDATE reservation_hold_requests
  SET status = 'stripe_created',
      provider_object_type = p_provider_object_type,
      provider_object_id = p_provider_object_id,
      client_secret_ciphertext = NULL,
      response_snapshot_json = COALESCE(p_response_snapshot_json, '{}'::jsonb)
        #- '{clientSecret}'
        #- '{stripe,client_secret}',
      last_error_code = NULL,
      last_error_message = NULL,
      updated_at = now()
  WHERE id = v_hold.id
    AND status <> 'finalized';

  RETURN jsonb_build_object(
    'action', 'recorded',
    'reservationId', v_hold.reservation_id
  );
END;
$$;

-- FUNCTION: record_stripe_object_state_v7(text, text, text, text, text, text, timestamp with time zone, jsonb)
CREATE FUNCTION public.record_stripe_object_state_v7(p_environment text, p_stripe_account_id text, p_object_type text, p_object_id text, p_stripe_status text, p_last_event_id text, p_last_event_created_at timestamp with time zone, p_payload_json jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO stripe_object_states(
    environment,
    stripe_account_id,
    object_type,
    object_id,
    stripe_status,
    last_event_id,
    last_event_created_at,
    terminal_at,
    payload_json
  )
  VALUES (
    p_environment,
    p_stripe_account_id,
    p_object_type,
    p_object_id,
    p_stripe_status,
    p_last_event_id,
    p_last_event_created_at,
    CASE
      WHEN p_stripe_status IN ('succeeded','canceled','failed','refunded','lost','won') THEN now()
      ELSE NULL
    END,
    p_payload_json
  )
  ON CONFLICT (environment, stripe_account_key, object_type, object_id)
  DO UPDATE
  SET stripe_status = EXCLUDED.stripe_status,
      last_event_id = EXCLUDED.last_event_id,
      last_event_created_at = EXCLUDED.last_event_created_at,
      terminal_at = COALESCE(stripe_object_states.terminal_at, EXCLUDED.terminal_at),
      payload_json = EXCLUDED.payload_json,
      updated_at = now()
  WHERE stripe_object_states.last_event_created_at <= EXCLUDED.last_event_created_at;
END;
$$;

-- FUNCTION: record_ticket_checkout_provider_result_v28(uuid, text, text, text, timestamp with time zone)
CREATE FUNCTION public.record_ticket_checkout_provider_result_v28(p_checkout_action_id uuid, p_request_hash text, p_checkout_session_id text, p_provider_response_hash text, p_provider_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action public.ticket_checkout_actions%ROWTYPE;
  v_order public.ticket_orders%ROWTYPE;
  v_conflict boolean := false;
BEGIN
  IF NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_checkout_session_id, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_provider_response_hash, '')), '') IS NULL
    OR p_provider_expires_at IS NULL
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'provider_result_invalid');
  END IF;

  SELECT * INTO v_action
  FROM public.ticket_checkout_actions
  WHERE id = p_checkout_action_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('action', 'not_found'); END IF;
  IF v_action.request_hash <> btrim(p_request_hash) THEN
    RETURN jsonb_build_object('action', 'conflict', 'reason', 'request_hash_mismatch');
  END IF;

  SELECT * INTO v_order
  FROM public.ticket_orders
  WHERE id = v_action.ticket_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'checkout_order_missing');
  END IF;

  IF v_action.state IN ('failed', 'expired') THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'checkout_action_terminal');
  END IF;

  IF v_action.checkout_session_id IS NOT NULL THEN
    IF v_action.checkout_session_id = btrim(p_checkout_session_id)
      AND v_action.provider_response_hash = btrim(p_provider_response_hash)
      AND v_action.provider_expires_at = p_provider_expires_at
    THEN
      RETURN jsonb_build_object(
        'action', 'reused', 'checkoutActionId', v_action.id,
        'orderId', v_order.id, 'checkoutSessionId', v_action.checkout_session_id,
        'state', v_action.state);
    END IF;
    v_conflict := true;
  ELSIF v_order.checkout_session_id IS NOT NULL
    AND v_order.checkout_session_id <> btrim(p_checkout_session_id)
  THEN
    v_conflict := true;
  ELSIF EXISTS (
    SELECT 1 FROM public.ticket_checkout_actions AS other
    WHERE other.id <> v_action.id
      AND other.environment = v_action.environment
      AND other.stripe_account_key = v_action.stripe_account_key
      AND other.checkout_session_id = btrim(p_checkout_session_id)
  ) OR EXISTS (
    SELECT 1 FROM public.ticket_orders AS other_order
    WHERE other_order.id <> v_order.id
      AND other_order.environment = v_action.environment
      AND other_order.stripe_account_key = v_action.stripe_account_key
      AND other_order.checkout_session_id = btrim(p_checkout_session_id)
  ) THEN
    v_conflict := true;
  END IF;

  IF v_conflict THEN
    UPDATE public.ticket_checkout_actions
    SET state = 'review_required',
        review_reason = 'provider_result_conflict',
        conflict_count = conflict_count + 1,
        conflict_facts_json = jsonb_build_object(
          'checkoutSessionId', btrim(p_checkout_session_id),
          'providerResponseHash', btrim(p_provider_response_hash),
          'providerExpiresAt', p_provider_expires_at
        ),
        updated_at = now()
    WHERE id = v_action.id;
    RETURN jsonb_build_object(
      'action', 'conflict_review', 'reason', 'provider_result_conflict',
      'checkoutActionId', v_action.id, 'orderId', v_order.id,
      'checkoutSessionId', v_action.checkout_session_id);
  END IF;

  BEGIN
    UPDATE public.ticket_orders
    SET checkout_session_id = btrim(p_checkout_session_id)
    WHERE id = v_order.id
      AND (checkout_session_id IS NULL OR checkout_session_id = btrim(p_checkout_session_id));
    IF NOT FOUND THEN
      RAISE EXCEPTION 'checkout order provider session changed';
    END IF;

    UPDATE public.ticket_checkout_actions
    SET state = 'provider_created',
        checkout_session_id = btrim(p_checkout_session_id),
        provider_response_hash = btrim(p_provider_response_hash),
        provider_expires_at = p_provider_expires_at,
        provider_attempt_count = provider_attempt_count + 1,
        recovery_next_attempt_at = p_provider_expires_at,
        recovery_last_outcome = 'provider_created',
        review_reason = NULL,
        updated_at = now()
    WHERE id = v_action.id;
  EXCEPTION WHEN unique_violation THEN
    UPDATE public.ticket_checkout_actions
    SET state = 'review_required',
        review_reason = 'provider_result_conflict',
        conflict_count = conflict_count + 1,
        conflict_facts_json = jsonb_build_object(
          'checkoutSessionId', btrim(p_checkout_session_id),
          'providerResponseHash', btrim(p_provider_response_hash),
          'providerExpiresAt', p_provider_expires_at
        ),
        updated_at = now()
    WHERE id = v_action.id;
    RETURN jsonb_build_object(
      'action', 'conflict_review', 'reason', 'provider_result_conflict',
      'checkoutActionId', v_action.id, 'orderId', v_order.id);
  END;

  RETURN jsonb_build_object(
    'action', 'provider_created', 'checkoutActionId', v_action.id,
    'orderId', v_order.id, 'checkoutSessionId', btrim(p_checkout_session_id),
    'providerExpiresAt', p_provider_expires_at
  );
END;
$$;

-- FUNCTION: record_ticket_sales_interruption_v35()
CREATE FUNCTION public.record_ticket_sales_interruption_v35() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE was_open boolean; is_open boolean;
BEGIN
 IF TG_TABLE_NAME='event_days' THEN
  was_open:=OLD.operating_status='open'; is_open:=NEW.operating_status='open';
  IF was_open AND NOT is_open THEN INSERT INTO public.ticket_sale_interruptions(event_day_id) VALUES(NEW.id);
  ELSIF NOT was_open AND is_open THEN UPDATE public.ticket_sale_interruptions SET resumed_at=clock_timestamp() WHERE event_day_id=NEW.id AND resumed_at IS NULL; END IF;
 ELSE
  was_open:=OLD.enabled AND OLD.sales_state='active' AND OLD.admission_state NOT IN ('closed','cancelled');
  is_open:=NEW.enabled AND NEW.sales_state='active' AND NEW.admission_state NOT IN ('closed','cancelled');
  IF was_open AND NOT is_open THEN INSERT INTO public.ticket_sale_interruptions(event_session_id) VALUES(NEW.id);
  ELSIF NOT was_open AND is_open THEN UPDATE public.ticket_sale_interruptions SET resumed_at=clock_timestamp() WHERE event_session_id=NEW.id AND resumed_at IS NULL; END IF;
 END IF;
 RETURN NEW;
END; $$;

-- FUNCTION: record_ticket_worker_heartbeat_v38(text, boolean)
CREATE FUNCTION public.record_ticket_worker_heartbeat_v38(p_worker text, p_succeeded boolean) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 INSERT INTO public.ticket_worker_heartbeats(worker,succeeded) VALUES(p_worker,p_succeeded)
 ON CONFLICT(worker) DO UPDATE SET observed_at=clock_timestamp(),succeeded=excluded.succeeded;
$$;

-- FUNCTION: record_transactional_email_provider_event_v29(text, text, text, boolean, timestamp with time zone, text, text, uuid, text)
CREATE FUNCTION public.record_transactional_email_provider_event_v29(p_provider_name text, p_provider_event_id text, p_event_type text, p_recognized boolean, p_occurred_at timestamp with time zone, p_provider_message_id text, p_recipient_email_hash text, p_notification_job_id uuid, p_correlation_state text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_job public.transactional_email_jobs%ROWTYPE;
  v_existing public.transactional_email_provider_events%ROWTYPE;
  v_state text;
  v_precedence integer;
  v_security_review boolean := false;
  v_apply boolean := false;
  v_action text := 'stored';
  v_event_id uuid;
BEGIN
  IF p_provider_name <> 'resend'
    OR p_provider_event_id IS NULL OR char_length(p_provider_event_id) NOT BETWEEN 1 AND 256
    OR p_provider_event_id ~ E'[\\r\\n]'
    OR p_event_type IS NULL OR char_length(p_event_type) NOT BETWEEN 1 AND 128
    OR p_event_type ~ E'[\\r\\n]'
    OR p_recognized IS NULL OR p_occurred_at IS NULL
    OR p_occurred_at < v_now - interval '7 days'
    OR p_occurred_at > v_now + interval '5 minutes'
    OR (p_provider_message_id IS NOT NULL AND (
      char_length(p_provider_message_id) NOT BETWEEN 1 AND 256
      OR p_provider_message_id ~ E'[\\r\\n]'))
    OR (p_recipient_email_hash IS NOT NULL
      AND char_length(p_recipient_email_hash) NOT BETWEEN 16 AND 256)
    OR p_correlation_state NOT IN ('valid', 'missing', 'invalid')
  THEN
    RAISE EXCEPTION 'invalid transactional email provider event';
  END IF;

  SELECT * INTO v_existing
  FROM public.transactional_email_provider_events
  WHERE provider_name = p_provider_name AND provider_event_id = p_provider_event_id;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'action', 'duplicate', 'deliveryState', v_existing.normalized_delivery_state);
  END IF;

  CASE lower(p_event_type)
    WHEN 'email.sent' THEN v_state := 'accepted'; v_precedence := 40;
    WHEN 'sent' THEN v_state := 'accepted'; v_precedence := 40;
    WHEN 'email.delivery_delayed' THEN v_state := 'delayed'; v_precedence := 50;
    WHEN 'delayed' THEN v_state := 'delayed'; v_precedence := 50;
    WHEN 'email.failed' THEN v_state := 'failed'; v_precedence := 60;
    WHEN 'failed' THEN v_state := 'failed'; v_precedence := 60;
    WHEN 'email.delivered' THEN v_state := 'delivered'; v_precedence := 70;
    WHEN 'delivered' THEN v_state := 'delivered'; v_precedence := 70;
    WHEN 'email.suppressed' THEN v_state := 'suppressed'; v_precedence := 80;
    WHEN 'suppressed' THEN v_state := 'suppressed'; v_precedence := 80;
    WHEN 'email.bounced' THEN v_state := 'bounced'; v_precedence := 90;
    WHEN 'bounced' THEN v_state := 'bounced'; v_precedence := 90;
    WHEN 'email.complained' THEN v_state := 'complained'; v_precedence := 100;
    WHEN 'complained' THEN v_state := 'complained'; v_precedence := 100;
    ELSE v_state := 'unknown'; v_precedence := 0;
  END CASE;
  IF NOT p_recognized THEN v_state := 'unknown'; v_precedence := 0; END IF;

  IF p_notification_job_id IS NOT NULL THEN
    SELECT * INTO v_job FROM public.lock_transactional_email_job_v33(p_notification_job_id);
    IF NOT FOUND OR p_correlation_state <> 'valid'
      OR p_recipient_email_hash IS NULL
      OR v_job.recipient_email_hash IS DISTINCT FROM p_recipient_email_hash
      OR (v_job.provider_name IS NOT NULL AND v_job.provider_name <> p_provider_name)
      OR (v_job.provider_message_id IS NOT NULL
        AND p_provider_message_id IS DISTINCT FROM v_job.provider_message_id)
    THEN
      v_security_review := true;
      v_job.id := NULL;
    END IF;
  ELSIF p_correlation_state = 'invalid' THEN
    v_security_review := true;
  END IF;

  INSERT INTO public.transactional_email_provider_events(
    provider_name, provider_event_id, notification_job_id,
    provider_message_id, event_type, normalized_delivery_state,
    state_precedence, recognized, occurred_at, recipient_email_hash,
    correlation_state, security_review_required, safe_metadata_json
  ) VALUES (
    p_provider_name, p_provider_event_id, v_job.id,
    p_provider_message_id, p_event_type, v_state,
    v_precedence, p_recognized, p_occurred_at, p_recipient_email_hash,
    p_correlation_state, v_security_review, '{}'::jsonb
  )
  ON CONFLICT (provider_name, provider_event_id) DO NOTHING
  RETURNING id INTO v_event_id;

  -- The fast-path SELECT above avoids needless work for ordinary webhook
  -- retries. The conflict branch closes the concurrent duplicate race after
  -- another transaction wins the provider-event uniqueness key.
  IF v_event_id IS NULL THEN
    SELECT * INTO v_existing
    FROM public.transactional_email_provider_events
    WHERE provider_name = p_provider_name
      AND provider_event_id = p_provider_event_id;
    RETURN jsonb_build_object(
      'action', 'duplicate',
      'deliveryState', v_existing.normalized_delivery_state);
  END IF;

  IF v_security_review THEN
    RETURN jsonb_build_object('action', 'security_review', 'deliveryState', v_state);
  END IF;

  IF v_job.id IS NOT NULL AND p_recognized THEN
    v_apply := v_precedence > v_job.provider_state_precedence
      OR (v_precedence = v_job.provider_state_precedence
        AND (v_job.provider_state_occurred_at IS NULL
          OR p_occurred_at >= v_job.provider_state_occurred_at));
    IF v_apply THEN
      UPDATE public.transactional_email_jobs
      SET provider_name = p_provider_name,
          provider_message_id = COALESCE(provider_message_id, p_provider_message_id),
          state = CASE WHEN state IN ('pending', 'processing', 'retry') THEN 'accepted' ELSE state END,
          provider_delivery_state = v_state,
          provider_state_precedence = v_precedence,
          provider_state_occurred_at = p_occurred_at,
          accepted_at = COALESCE(accepted_at, v_now),
          completed_at = CASE WHEN v_state IN (
            'delivered', 'failed', 'bounced', 'complained', 'suppressed')
            THEN COALESCE(completed_at, v_now) ELSE completed_at END,
          claimed_by = NULL, claim_token = NULL, claimed_at = NULL,
          lease_expires_at = NULL, updated_at = v_now
      WHERE id = v_job.id;
      UPDATE public.ticket_wallet_otp_challenges
      SET state = CASE WHEN v_state IN ('failed', 'bounced', 'complained', 'suppressed')
          THEN 'failed' ELSE 'sent' END,
          code_ciphertext = CASE WHEN v_state IN ('failed', 'bounced', 'complained', 'suppressed')
            THEN NULL ELSE code_ciphertext END,
          sent_at = COALESCE(sent_at, v_now),
          terminal_at = CASE WHEN v_state IN ('failed', 'bounced', 'complained', 'suppressed')
            THEN COALESCE(terminal_at, v_now) ELSE terminal_at END,
          updated_at = v_now
      WHERE id = v_job.otp_challenge_id
        AND state IN ('pending', 'sending', 'sent');
    END IF;
  END IF;

  IF v_job.id IS NOT NULL AND p_recipient_email_hash IS NOT NULL
    AND v_state IN ('bounced', 'complained', 'suppressed')
  THEN
    INSERT INTO public.transactional_email_suppressions(
      provider_name, recipient_email_hash, reason, active,
      safe_provider_reference, activated_at, updated_at
    ) VALUES (
      p_provider_name, p_recipient_email_hash,
      CASE v_state WHEN 'bounced' THEN 'hard_bounce'
        WHEN 'complained' THEN 'complaint' ELSE 'provider_suppressed' END,
      true, p_provider_message_id, v_now, v_now
    )
    ON CONFLICT (provider_name, recipient_email_hash) DO UPDATE
    SET reason = EXCLUDED.reason, active = true,
        safe_provider_reference = EXCLUDED.safe_provider_reference,
        activated_at = EXCLUDED.activated_at, deactivated_at = NULL,
        updated_at = EXCLUDED.updated_at;
  END IF;

  RETURN jsonb_build_object('action', v_action, 'deliveryState', v_state);
END;
$$;

-- FUNCTION: record_vip_floor_legacy_compat_audit()
CREATE FUNCTION public.record_vip_floor_legacy_compat_audit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old jsonb := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END;
  v_new jsonb := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END;
  v_changed_fields text[];
  v_event_day_ids uuid[];
  v_event_day_id uuid;
  v_target_id uuid;
  v_version_before bigint;
  v_version_after bigint;
BEGIN
  IF NOT public.vip_floor_v2_dual_write_enabled()
    OR current_setting('ghost.vip_floor_v8_writer', true) = 'on'
  THEN
    RETURN NULL;
  END IF;

  v_changed_fields := public.vip_floor_compat_changed_fields(TG_TABLE_NAME, v_old, v_new);
  IF cardinality(v_changed_fields) = 0 THEN
    RETURN NULL;
  END IF;

  v_event_day_ids := public.vip_floor_compat_event_day_ids(TG_TABLE_NAME, v_old, v_new);
  IF cardinality(v_event_day_ids) = 1 THEN
    v_event_day_id := v_event_day_ids[1];
  END IF;

  v_target_id := COALESCE(
    NULLIF(v_new ->> 'id', '')::uuid,
    NULLIF(v_old ->> 'id', '')::uuid
  );
  v_version_before := NULLIF(v_old ->> 'version', '')::bigint;
  v_version_after := NULLIF(v_new ->> 'version', '')::bigint;

  INSERT INTO public.audit_logs(
    actor_type,
    action,
    target_table,
    target_id,
    event_day_id,
    entity_type,
    entity_id,
    operation,
    version_before,
    version_after,
    changed_fields,
    metadata_json,
    source_contract
  )
  VALUES (
    'system',
    'vip_floor.compat.' || TG_TABLE_NAME || '.' || lower(TG_OP),
    TG_TABLE_NAME,
    v_target_id,
    v_event_day_id,
    TG_TABLE_NAME,
    v_target_id,
    lower(TG_OP),
    v_version_before,
    v_version_after,
    v_changed_fields,
    jsonb_build_object(
      'sourceContract', 'v7_compat',
      'redaction', 'field_names_only',
      'affectedEventDayCount', cardinality(v_event_day_ids)
    ),
    'v7_compat'
  );

  RETURN NULL;
END;
$$;

-- FUNCTION: record_vip_manager_metric_v15(text, text, integer, text, text, jsonb)
CREATE FUNCTION public.record_vip_manager_metric_v15(p_metric_name text, p_outcome text, p_duration_ms integer, p_action_name text, p_request_id text, p_dimensions jsonb DEFAULT '{}'::jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id bigint;
  v_dimensions jsonb := COALESCE(p_dimensions, '{}'::jsonb);
BEGIN
  IF p_metric_name NOT IN (
      'board_read', 'command', 'command_error', 'outbox_dead',
      'realtime_gap', 'realtime_unavailable'
    )
    OR p_outcome NOT IN ('success', 'rejected', 'error', 'observed')
    OR (p_duration_ms IS NOT NULL AND p_duration_ms NOT BETWEEN 0 AND 600000)
    OR jsonb_typeof(v_dimensions) <> 'object'
    OR octet_length(v_dimensions::text) > 2048
    OR v_dimensions::text ~* '(name|email|phone|contact|note|memo|cipher|token|cookie|authorization|payload)'
  THEN
    RAISE EXCEPTION 'invalid vip manager metric';
  END IF;

  INSERT INTO public.vip_manager_metrics(
    metric_name, outcome, duration_ms, action_name, request_id, dimensions
  )
  VALUES (
    p_metric_name,
    p_outcome,
    p_duration_ms,
    NULLIF(left(btrim(COALESCE(p_action_name, '')), 120), ''),
    NULLIF(left(btrim(COALESCE(p_request_id, '')), 160), ''),
    v_dimensions
  )
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;

