-- FUNCTION: reject_ticket_admission_operation_v30(uuid, uuid, text, text, text, uuid, uuid, text)
CREATE FUNCTION public.reject_ticket_admission_operation_v30(p_operation_id uuid, p_challenge_id uuid, p_terminal_state text, p_error_code text, p_actor_type text, p_actor_admin_id uuid, p_wallet_session_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_challenge_state text;
BEGIN
  IF p_terminal_state NOT IN ('rejected', 'expired') THEN
    RAISE EXCEPTION 'invalid Ticket Admission rejection state';
  END IF;

  IF p_challenge_id IS NOT NULL THEN
    v_challenge_state := CASE
      WHEN p_terminal_state = 'expired' THEN 'expired' ELSE 'rejected' END;
    UPDATE public.ticket_admission_challenges
    SET state = v_challenge_state,
        terminal_at = v_now,
        updated_at = v_now
    WHERE id = p_challenge_id
      AND operation_id = p_operation_id
      AND state = 'active';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Ticket Admission Challenge terminal transition failed';
    END IF;
  END IF;

  RETURN public.complete_ticket_admission_operation_v30(
    p_operation_id, p_terminal_state, p_error_code,
    NULL, 0, NULL, p_actor_type, p_actor_admin_id,
    p_wallet_session_id, p_reason
  );
END;
$$;

