-- FUNCTION: release_admin_reservation_hold_v7(uuid, text, text, text, text, uuid, text)
CREATE FUNCTION public.release_admin_reservation_hold_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_reservation reservations%ROWTYPE;
  v_response jsonb;
  v_released_count int;
BEGIN
  SELECT * INTO v_admin
  FROM admin_users
  WHERE id = p_actor_admin_id
  FOR UPDATE;

  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;

  IF v_admin.role NOT IN ('manager','owner','engineer') THEN
    RAISE EXCEPTION 'admin role cannot release holds';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;

    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  SELECT * INTO v_reservation
  FROM reservations
  WHERE id = p_reservation_id
  FOR UPDATE;

  IF NOT FOUND OR v_reservation.status NOT IN ('admin_hold','admin_hold_review') THEN
    RAISE EXCEPTION 'reservation is not an admin hold';
  END IF;

  UPDATE reservation_resources
  SET lock_status = 'released',
      released_at = now(),
      updated_at = now()
  WHERE reservation_id = p_reservation_id
    AND lock_status = 'held';

  GET DIAGNOSTICS v_released_count = ROW_COUNT;

  UPDATE reservations
  SET status = 'cancelled',
      updated_at = now()
  WHERE id = p_reservation_id;

  v_response := jsonb_build_object('reservationId', p_reservation_id, 'releasedResourceCount', v_released_count);

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'reservations', p_reservation_id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'released', 'response', v_response);
END;
$$;

-- FUNCTION: relink_admin_reservation_customer_v14(uuid, text, text, text, uuid, bigint, uuid, text)
CREATE FUNCTION public.relink_admin_reservation_customer_v14(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_version bigint, p_customer_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation.customer_relinked';
  v_step jsonb;
  v_reservation public.reservations%ROWTYPE;
  v_new_version bigint;
  v_audit_id uuid;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    IF NOT EXISTS (
      SELECT 1 FROM public.admin_users
      WHERE id = p_actor_admin_id AND active = true AND role = 'owner'
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object('code', 'FORBIDDEN')
        ),
        ARRAY['allowed']
      );
    END IF;
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_reservation_id IS NULL
      OR p_expected_version IS NULL OR p_expected_version < 1
      OR p_reason <> '管理画面操作'
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'customerRelink')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;

    SELECT * INTO v_reservation
    FROM public.reservations
    WHERE id = p_reservation_id
    FOR UPDATE;
    IF NOT FOUND THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object('code', 'NOT_FOUND')
        ),
        ARRAY['allowed']
      );
    END IF;
    IF v_reservation.version <> p_expected_version THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'VERSION_CONFLICT',
            'currentVersion', v_reservation.version
          )
        ),
        ARRAY['allowed']
      );
    END IF;
    IF p_customer_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.customers WHERE id = p_customer_id
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'NOT_FOUND',
            'details', jsonb_build_object('entityType', 'customer')
          )
        ),
        ARRAY['allowed']
      );
    END IF;
    IF v_reservation.customer_id IS NOT DISTINCT FROM p_customer_id THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'customerId')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    UPDATE public.reservations
    SET customer_id = p_customer_id,
        version = version + 1,
        updated_at = now()
    WHERE id = v_reservation.id
    RETURNING version INTO v_new_version;

    INSERT INTO public.reservation_customer_link_events(
      reservation_id, previous_customer_id, customer_id,
      resolution_method, actor_admin_id, request_id
    )
    VALUES (
      v_reservation.id, v_reservation.customer_id, p_customer_id,
      'manual_relink', p_actor_admin_id, p_request_id
    );

    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, v_reservation.event_day_id, v_reservation.id,
      'reservation', v_reservation.id, v_action,
      p_request_id, p_reason,
      p_expected_version, v_reservation.version, v_new_version,
      ARRAY['customer_id', 'version'],
      jsonb_build_object(
        'version', v_reservation.version,
        'linked', v_reservation.customer_id IS NOT NULL
      ),
      jsonb_build_object(
        'version', v_new_version,
        'linked', p_customer_id IS NOT NULL
      ),
      jsonb_build_object('manual', true)
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_step := public.bump_vip_floor_day_revision_v8(
      v_reservation.event_day_id, v_audit_id
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;

    v_response := jsonb_build_object(
      'ok', true,
      'action', v_action,
      'reused', false,
      'reservationId', v_reservation.id,
      'customerId', p_customer_id,
      'entityVersion', v_new_version,
      'boardRevision', v_revision,
      'auditLogId', v_audit_id
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: request_ticket_wallet_otp_v29(text, timestamp with time zone, uuid, text, text, text, text, text, text, uuid, text, bytea, timestamp with time zone, timestamp with time zone, integer, text, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, text, text, text, text)
CREATE FUNCTION public.request_ticket_wallet_otp_v29(p_environment text, p_now timestamp with time zone, p_preauth_flow_id uuid, p_preauth_token_verifier text, p_preauth_csrf_verifier text, p_identity_email_hash text, p_abuse_email_hash text, p_abuse_ip_hash text, p_abuse_user_agent_hash text, p_candidate_challenge_id uuid, p_candidate_code_verifier text, p_candidate_code_ciphertext bytea, p_candidate_expires_at timestamp with time zone, p_candidate_resend_at timestamp with time zone, p_maximum_attempts integer, p_provider_idempotency_key text, p_minimum_preauth_remaining_seconds integer, p_minimum_resend_remaining_seconds integer, p_email_per_minute integer, p_email_per_hour integer, p_email_per_day integer, p_ip_per_ten_minutes integer, p_ip_per_day integer, p_user_agent_per_ten_minutes integer, p_global_per_ten_minutes integer, p_global_per_day integer, p_template_version text, p_from_address text, p_reply_to text, p_wallet_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_flow public.ticket_wallet_preauth_flows%ROWTYPE;
  v_challenge public.ticket_wallet_otp_challenges%ROWTYPE;
  v_previous_job public.transactional_email_jobs%ROWTYPE;
  v_recipient_ciphertext bytea;
  v_job_id uuid;
  v_is_decoy boolean;
  v_key_id text;
  v_render jsonb;
BEGIN
  IF p_environment NOT IN ('test', 'live')
    OR p_now IS NULL OR abs(extract(epoch FROM (p_now - v_now))) > 300
    OR p_preauth_flow_id IS NULL
    OR p_identity_email_hash IS NULL OR char_length(p_identity_email_hash) NOT BETWEEN 16 AND 256
    OR p_abuse_email_hash IS NULL OR char_length(p_abuse_email_hash) NOT BETWEEN 16 AND 256
    OR p_abuse_ip_hash IS NULL OR char_length(p_abuse_ip_hash) NOT BETWEEN 16 AND 256
    OR p_abuse_user_agent_hash IS NULL OR char_length(p_abuse_user_agent_hash) NOT BETWEEN 16 AND 256
    OR p_candidate_challenge_id IS NULL
    OR p_candidate_code_verifier IS NULL OR char_length(p_candidate_code_verifier) NOT BETWEEN 16 AND 256
    OR p_candidate_code_ciphertext IS NULL
    OR octet_length(p_candidate_code_ciphertext) NOT BETWEEN 32 AND 2048
    OR char_length(p_provider_idempotency_key) NOT BETWEEN 1 AND 256
    OR p_provider_idempotency_key !~ '^[A-Za-z0-9._:/-]+$'
    OR ROW(
      p_maximum_attempts, p_minimum_preauth_remaining_seconds,
      p_minimum_resend_remaining_seconds, p_email_per_minute,
      p_email_per_hour, p_email_per_day, p_ip_per_ten_minutes,
      p_ip_per_day, p_user_agent_per_ten_minutes,
      p_global_per_ten_minutes, p_global_per_day
    ) IS DISTINCT FROM ROW(5, 720, 120, 1, 5, 10, 100, 500, 20, 300, 2000)
    OR p_template_version <> 'ghost.ticket-wallet-otp.v1'
    OR NULLIF(btrim(COALESCE(p_from_address, '')), '') IS NULL
    OR char_length(p_from_address) > 320 OR p_from_address ~ E'[\\r\\n]'
    OR (p_reply_to IS NOT NULL AND (
      char_length(p_reply_to) NOT BETWEEN 1 AND 320 OR p_reply_to ~ E'[\\r\\n]'))
    OR char_length(p_wallet_url) NOT BETWEEN 9 AND 2048
    OR p_wallet_url !~ '^https://[^[:space:]]+$'
  THEN
    RETURN jsonb_build_object('action', 'rejected');
  END IF;

  SELECT * INTO v_flow
  FROM public.ticket_wallet_preauth_flows
  WHERE id = p_preauth_flow_id
  FOR UPDATE;

  IF NOT FOUND OR v_flow.state <> 'active' OR v_flow.expires_at <= v_now
    OR NOT public.ticket_auth_digest_equal_v29(v_flow.token_verifier, p_preauth_token_verifier)
    OR NOT public.ticket_auth_digest_equal_v29(v_flow.csrf_verifier, p_preauth_csrf_verifier)
  THEN
    RETURN jsonb_build_object('action', 'rejected');
  END IF;

  IF v_flow.expires_at < v_now + make_interval(secs => p_minimum_preauth_remaining_seconds) THEN
    RETURN jsonb_build_object('action', 'preauth_refresh_required');
  END IF;

  -- All rate keys are already purpose-separated keyed hashes. Fixed names keep
  -- independent windows from sharing counters.
  IF NOT public.consume_ticket_wallet_rate_limit_v29('otp_email_60s', p_abuse_email_hash, 60, p_email_per_minute)
    OR NOT public.consume_ticket_wallet_rate_limit_v29('otp_email_1h', p_abuse_email_hash, 3600, p_email_per_hour)
    OR NOT public.consume_ticket_wallet_rate_limit_v29('otp_email_1d', p_abuse_email_hash, 86400, p_email_per_day)
    OR NOT public.consume_ticket_wallet_rate_limit_v29('otp_ip_10m', p_abuse_ip_hash, 600, p_ip_per_ten_minutes)
    OR NOT public.consume_ticket_wallet_rate_limit_v29('otp_ip_1d', p_abuse_ip_hash, 86400, p_ip_per_day)
    OR NOT public.consume_ticket_wallet_rate_limit_v29('otp_flow_10m', p_preauth_flow_id::text, 600, p_user_agent_per_ten_minutes)
    OR NOT public.consume_ticket_wallet_rate_limit_v29('otp_global_10m', 'global', 600, p_global_per_ten_minutes)
    OR NOT public.consume_ticket_wallet_rate_limit_v29('otp_global_1d', 'global', 86400, p_global_per_day)
  THEN
    RETURN jsonb_build_object('action', 'rate_limited');
  END IF;

  SELECT * INTO v_challenge
  FROM public.ticket_wallet_otp_challenges
  WHERE preauth_flow_id = v_flow.id
    AND state IN ('pending', 'sending', 'sent')
  FOR UPDATE;

  IF FOUND AND v_challenge.expires_at <= v_now THEN
    UPDATE public.ticket_wallet_otp_challenges
    SET state = 'expired', code_ciphertext = NULL,
        terminal_at = v_now, updated_at = v_now
    WHERE id = v_challenge.id;
    UPDATE public.transactional_email_jobs
    SET state = 'cancelled', terminal_at = v_now,
        claimed_by = NULL, claim_token = NULL, claimed_at = NULL,
        lease_expires_at = NULL, updated_at = v_now
    WHERE otp_challenge_id = v_challenge.id
      AND state IN ('pending', 'processing', 'retry');
    v_challenge.id := NULL;
  END IF;

  IF v_challenge.id IS NOT NULL THEN
    IF v_challenge.expires_at < v_now + make_interval(secs => p_minimum_resend_remaining_seconds) THEN
      RETURN jsonb_build_object('action', 'restart_required');
    END IF;

    IF v_challenge.resend_available_at > v_now THEN
      RETURN jsonb_build_object(
        'action', 'accepted', 'challengeId', v_challenge.id,
        'expiresAt', v_challenge.expires_at,
        'resendAvailableAt', v_challenge.resend_available_at,
        'attemptsRemaining', v_challenge.maximum_attempts - v_challenge.attempt_count,
        'deliveryJobId', NULL
      );
    END IF;

    IF NOT v_challenge.is_decoy THEN
      SELECT * INTO v_previous_job
      FROM public.transactional_email_jobs
      WHERE otp_challenge_id = v_challenge.id
      ORDER BY created_at, id
      LIMIT 1;
      IF NOT FOUND THEN
        RETURN jsonb_build_object('action', 'restart_required');
      END IF;

      v_job_id := gen_random_uuid();
      v_render := jsonb_set(
        v_previous_job.render_data_json,
        '{notificationJobId}', to_jsonb(v_job_id::text), false
      );
      v_render := jsonb_set(
        v_render,
        '{tags}',
        jsonb_build_array(
          jsonb_build_object('name', 'purpose', 'value', 'ticket_wallet_otp'),
          jsonb_build_object('name', 'notification_job_id', 'value', v_job_id)
        ),
        false
      );
      INSERT INTO public.transactional_email_jobs(
        id, otp_challenge_id, provider_idempotency_key,
        recipient_email_hash, recipient_email_ciphertext, render_data_json,
        state, next_attempt_at, created_at, updated_at
      ) VALUES (
        v_job_id, v_challenge.id, p_provider_idempotency_key,
        v_challenge.identity_email_hash, v_previous_job.recipient_email_ciphertext,
        v_render, 'pending', v_now, v_now, v_now
      );
    END IF;

    UPDATE public.ticket_wallet_otp_challenges
    SET state = 'pending', delivery_attempt_count = delivery_attempt_count + 1,
        resend_available_at = v_now + interval '60 seconds', updated_at = v_now
    WHERE id = v_challenge.id
    RETURNING * INTO v_challenge;

    RETURN jsonb_build_object(
      'action', 'accepted', 'challengeId', v_challenge.id,
      'expiresAt', v_challenge.expires_at,
      'resendAvailableAt', v_challenge.resend_available_at,
      'attemptsRemaining', v_challenge.maximum_attempts - v_challenge.attempt_count,
      'deliveryJobId', v_job_id
    );
  END IF;

  IF p_candidate_expires_at <= v_now + interval '9 minutes'
    OR p_candidate_expires_at > v_now + interval '10 minutes 5 seconds'
    OR p_candidate_expires_at > v_flow.expires_at
    OR p_candidate_resend_at < v_now + interval '55 seconds'
    OR p_candidate_resend_at > v_now + interval '65 seconds'
  THEN
    RETURN jsonb_build_object('action', 'rejected');
  END IF;

  v_key_id := split_part(p_candidate_code_verifier, ':', 2);
  IF v_key_id !~ '^[A-Za-z0-9._-]{1,64}$' THEN
    RETURN jsonb_build_object('action', 'rejected');
  END IF;

  SELECT ticket_order.purchaser_email_ciphertext
  INTO v_recipient_ciphertext
  FROM public.ticket_orders AS ticket_order
  JOIN public.ticket_event_sessions AS event_session
    ON event_session.id = ticket_order.event_session_id
   AND event_session.environment = ticket_order.environment
   AND event_session.stripe_account_key = ticket_order.stripe_account_key
  WHERE ticket_order.environment = p_environment
    AND ticket_order.check_in_mode = 'wallet_swipe'
    AND ticket_order.purchaser_email_hash = p_identity_email_hash
    AND ticket_order.purchaser_email_ciphertext IS NOT NULL
    AND ticket_order.status = 'fulfilled'
    AND ticket_order.paid_at IS NOT NULL
    AND ticket_order.fulfilled_at IS NOT NULL
    AND ticket_order.payment_hold_reason IS NULL
    AND event_session.enabled
    AND event_session.admission_state <> 'cancelled'
    AND event_session.admission_closes_at + interval '8 days' > v_now
  ORDER BY event_session.admission_closes_at DESC, ticket_order.created_at DESC, ticket_order.id
  LIMIT 1;

  v_is_decoy := v_recipient_ciphertext IS NULL OR EXISTS (
    SELECT 1
    FROM public.transactional_email_suppressions AS suppression
    WHERE suppression.recipient_email_hash = p_identity_email_hash
      AND suppression.active
  );

  INSERT INTO public.ticket_wallet_otp_challenges(
    id, preauth_flow_id, preauth_expires_at, environment,
    identity_email_hash, abuse_email_hash, abuse_ip_hash,
    abuse_user_agent_hash, is_decoy, auth_key_id,
    code_verifier, code_ciphertext, state, maximum_attempts,
    requested_at, expires_at, resend_available_at, updated_at
  ) VALUES (
    p_candidate_challenge_id, v_flow.id, v_flow.expires_at, p_environment,
    p_identity_email_hash, p_abuse_email_hash, p_abuse_ip_hash,
    p_abuse_user_agent_hash, v_is_decoy, v_key_id,
    p_candidate_code_verifier, p_candidate_code_ciphertext, 'pending', 5,
    v_now, p_candidate_expires_at, p_candidate_resend_at, v_now
  ) RETURNING * INTO v_challenge;

  IF NOT v_is_decoy THEN
    v_job_id := gen_random_uuid();
    v_render := jsonb_build_object(
      'template', 'ticket_wallet_otp',
      'templateVersion', p_template_version,
      'notificationJobId', v_job_id,
      'renderReferenceAt', v_now,
      'expiresAt', p_candidate_expires_at,
      'from', p_from_address,
      'replyTo', p_reply_to,
      'walletUrl', p_wallet_url,
      'tags', jsonb_build_array(
        jsonb_build_object('name', 'purpose', 'value', 'ticket_wallet_otp'),
        jsonb_build_object('name', 'notification_job_id', 'value', v_job_id)
      )
    );
    INSERT INTO public.transactional_email_jobs(
      id, otp_challenge_id, provider_idempotency_key,
      recipient_email_hash, recipient_email_ciphertext, render_data_json,
      state, next_attempt_at, created_at, updated_at
    ) VALUES (
      v_job_id, v_challenge.id, p_provider_idempotency_key,
      p_identity_email_hash, v_recipient_ciphertext, v_render,
      'pending', v_now, v_now, v_now
    );
    UPDATE public.ticket_wallet_otp_challenges
    SET delivery_attempt_count = 1, updated_at = v_now
    WHERE id = v_challenge.id
    RETURNING * INTO v_challenge;
  END IF;

  RETURN jsonb_build_object(
    'action', 'accepted', 'challengeId', v_challenge.id,
    'expiresAt', v_challenge.expires_at,
    'resendAvailableAt', v_challenge.resend_available_at,
    'attemptsRemaining', v_challenge.maximum_attempts,
    'deliveryJobId', v_job_id
  );
END;
$_$;

-- FUNCTION: request_ticket_wallet_otp_v33(text, timestamp with time zone, uuid, text, text, text, text, text, text, uuid, text, bytea, timestamp with time zone, timestamp with time zone, integer, text, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, text, text, text, text)
CREATE FUNCTION public.request_ticket_wallet_otp_v33(p_environment text, p_now timestamp with time zone, p_preauth_flow_id uuid, p_preauth_token_verifier text, p_preauth_csrf_verifier text, p_identity_email_hash text, p_abuse_email_hash text, p_abuse_ip_hash text, p_abuse_user_agent_hash text, p_candidate_challenge_id uuid, p_candidate_code_verifier text, p_candidate_code_ciphertext bytea, p_candidate_expires_at timestamp with time zone, p_candidate_resend_at timestamp with time zone, p_maximum_attempts integer, p_provider_idempotency_key text, p_minimum_preauth_remaining_seconds integer, p_minimum_resend_remaining_seconds integer, p_email_per_minute integer, p_email_per_hour integer, p_email_per_day integer, p_ip_per_ten_minutes integer, p_ip_per_day integer, p_preauth_per_ten_minutes integer, p_global_per_ten_minutes integer, p_global_per_day integer, p_template_version text, p_from_address text, p_reply_to text, p_wallet_url text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
SELECT public.request_ticket_wallet_otp_v29(p_environment, p_now, p_preauth_flow_id, p_preauth_token_verifier, p_preauth_csrf_verifier, p_identity_email_hash, p_abuse_email_hash, p_abuse_ip_hash, p_abuse_user_agent_hash, p_candidate_challenge_id, p_candidate_code_verifier, p_candidate_code_ciphertext, p_candidate_expires_at, p_candidate_resend_at, p_maximum_attempts, p_provider_idempotency_key, p_minimum_preauth_remaining_seconds, p_minimum_resend_remaining_seconds, p_email_per_minute, p_email_per_hour, p_email_per_day, p_ip_per_ten_minutes, p_ip_per_day, p_preauth_per_ten_minutes, p_global_per_ten_minutes, p_global_per_day, p_template_version, p_from_address, p_reply_to, p_wallet_url);
$$;

-- FUNCTION: requeue_stale_webhook_events_v7()
CREATE FUNCTION public.requeue_stale_webhook_events_v7() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count int;
BEGIN
  UPDATE webhook_events
  SET processing_status = 'retry',
      locked_at = NULL,
      locked_by = NULL,
      claim_token = NULL,
      next_attempt_at = now(),
      error_json = COALESCE(error_json, '{}'::jsonb)
        || jsonb_build_object('requeued_by','stale_reaper','requeued_at',now()),
      updated_at = now()
  WHERE processing_status = 'processing'
    AND locked_at < now() - interval '5 minutes';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

-- FUNCTION: requeue_worker_dead_item_v7(uuid, text, text, text, text, text, uuid, text)
CREATE FUNCTION public.requeue_worker_dead_item_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_queue_name text, p_item_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_updated_count int := 0;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR length(trim(p_idempotency_key)) < 8 THEN
    RAISE EXCEPTION 'invalid idempotency key';
  END IF;

  IF p_request_hash IS NULL OR length(trim(p_request_hash)) < 16 THEN
    RAISE EXCEPTION 'invalid request hash';
  END IF;

  -- W07-G-49 (merged by W04C): requeue revives money-moving work items; a
  -- reason is mandatory for every queue, including email-notifications.
  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'reason is required to requeue worker items';
  END IF;

  SELECT * INTO v_admin
  FROM admin_users
  WHERE id = p_actor_admin_id
  FOR UPDATE;

  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;

  IF v_admin.role NOT IN ('manager','owner','engineer') THEN
    RAISE EXCEPTION 'admin role cannot requeue worker items';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object(
        'action', 'mismatch',
        'error', 'idempotency_key_reused_with_different_request'
      );
    END IF;

    RETURN jsonb_build_object(
      'action', 'reused',
      'response', v_existing.response_json
    );
  END IF;

  CASE p_queue_name
    WHEN 'stripe-webhooks' THEN
      -- RR-02 (v74, restored after the v75 rebase dropped it): a payload-purged
      -- webhook event is a tombstone. Replaying it would process '{}' with no
      -- provider identity, so it can never be re-armed -- the operator must
      -- re-fetch the event from the provider.
      IF EXISTS (
        SELECT 1
        FROM webhook_events
        WHERE id = p_item_id
          AND (payload_purged_at IS NOT NULL OR payload_json = '{}'::jsonb)
      ) THEN
        RAISE EXCEPTION 'payload_purged';
      END IF;

      UPDATE webhook_events
      SET processing_status = 'retry',
          next_attempt_at = now(),
          locked_by = NULL,
          locked_at = NULL,
          claim_token = NULL,
          last_error_code = NULL,
          error_json = NULL,
          updated_at = now()
      WHERE id = p_item_id
        AND processing_status IN ('retry','dead')
        AND payload_purged_at IS NULL;

      GET DIAGNOSTICS v_updated_count = ROW_COUNT;
    WHEN 'reservation-holds' THEN
      UPDATE reservation_hold_requests
      SET status = 'finalize_retry',
          next_attempt_at = now(),
          locked_by = NULL,
          locked_at = NULL,
          claim_token = NULL,
          last_error_code = NULL,
          last_error_message = NULL,
          updated_at = now()
      WHERE id = p_item_id
        AND status IN ('stripe_unknown','finalize_retry','retry_exhausted','manual_review');

      GET DIAGNOSTICS v_updated_count = ROW_COUNT;
    WHEN 'off-session' THEN
      UPDATE off_session_charge_attempts a
      SET status = 'approved',
          next_attempt_at = now(),
          locked_by = NULL,
          locked_at = NULL,
          claim_token = NULL,
          error_json = NULL,
          updated_at = now()
      WHERE a.id = p_item_id
        AND a.status IN ('approved','failed','dead')
        -- W07-N2 (v75): never re-arm an attempt whose parent case already left
        -- the approved state (rejected, waived, charged, dead).
        AND (
          (a.case_type = 'no_show' AND EXISTS (
            SELECT 1 FROM no_show_cases c
            WHERE c.id = a.case_id AND c.status = 'approved'))
          OR (a.case_type = 'late_cancel' AND EXISTS (
            SELECT 1 FROM late_cancel_cases c
            WHERE c.id = a.case_id AND c.status = 'approved'))
        );

      GET DIAGNOSTICS v_updated_count = ROW_COUNT;
    WHEN 'refunds' THEN
      UPDATE refund_cases
      SET status = 'approved',
          next_attempt_at = now(),
          locked_by = NULL,
          locked_at = NULL,
          claim_token = NULL,
          error_json = NULL,
          updated_at = now()
      WHERE id = p_item_id
        AND status IN ('approved','failed','dead');

      GET DIAGNOSTICS v_updated_count = ROW_COUNT;
    WHEN 'line-notifications' THEN
      UPDATE notification_jobs
      SET status = 'retry',
          next_attempt_at = now(),
          locked_by = NULL,
          locked_at = NULL,
          claim_token = NULL,
          error_json = NULL,
          updated_at = now()
      WHERE id = p_item_id
        AND channel = 'line'
        AND status IN ('retry','dead');

      GET DIAGNOSTICS v_updated_count = ROW_COUNT;
    -- R-12 (v71) branch, hardened by W11/v75: attempt_count resets so a
    -- dead-at-attempt-limit row is claimable again; the first-send window is
    -- enforced so a requeue can never push a send outside the provider dedupe
    -- horizon; a lease-expired 'processing' row may be recovered manually.
    WHEN 'email-notifications' THEN
      UPDATE notification_jobs
      SET status = 'retry',
          attempt_count = 0,
          next_attempt_at = now(),
          locked_by = NULL,
          locked_at = NULL,
          claim_token = NULL,
          error_json = NULL,
          updated_at = now()
      WHERE id = p_item_id
        AND channel = 'email'
        AND (
          status IN ('retry','dead')
          OR (status = 'processing'
            AND locked_at < now() - make_interval(secs => 300))
        )
        AND (first_send_at IS NULL OR first_send_at > now() - interval '23 hours');

      GET DIAGNOSTICS v_updated_count = ROW_COUNT;

      -- A row that only failed the window check is not "not requeueable" — it
      -- is permanently out of retries. Fail loudly so the operator sees the
      -- boundary instead of a silent no-op.
      IF v_updated_count = 0 AND EXISTS (
        SELECT 1 FROM notification_jobs
        WHERE id = p_item_id
          AND channel = 'email'
          AND status IN ('retry','dead','processing')
          AND first_send_at <= now() - interval '23 hours'
      ) THEN
        RAISE EXCEPTION 'email notification first-send window expired; provider dedupe horizon exceeded';
      END IF;
    ELSE
      RAISE EXCEPTION 'unknown worker queue %', p_queue_name;
  END CASE;

  IF v_updated_count = 0 THEN
    RAISE EXCEPTION 'worker item is not requeueable';
  END IF;

  v_response := jsonb_build_object(
    'queueName', p_queue_name,
    'itemId', p_item_id,
    'requeuedCount', v_updated_count,
    'idempotencyKey', p_idempotency_key,
    'requestId', p_request_id,
    'actorAdminId', p_actor_admin_id,
    'reason', p_reason,
    'requeuedAt', now()
  );

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, p_queue_name, p_item_id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'requeued', 'response', v_response);
END;
$$;

-- FUNCTION: require_admin_capability_v8(uuid, text)
CREATE FUNCTION public.require_admin_capability_v8(p_actor_admin_id uuid, p_capability text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin public.admin_users%ROWTYPE;
  v_capability text := lower(btrim(COALESCE(p_capability, '')));
  v_known_capabilities constant text[] := ARRAY[
    'floor.read',
    'customer.summary.masked',
    'customer.contact.read',
    'service_status.write',
    'reservation_note.write',
    'walk_in.create',
    'seat_extension.standard',
    'seat_extension.extended',
    'reservation_schedule.write',
    'reservation_assignment.write',
    'reservation_block.write',
    'reservation_cancel.write',
    'customer_profile.write'
  ];
  v_staff_capabilities constant text[] := ARRAY[
    'floor.read',
    'customer.summary.masked',
    'service_status.write',
    'reservation_note.write',
    'walk_in.create',
    'seat_extension.standard'
  ];
  v_allowed boolean := false;
BEGIN
  IF p_actor_admin_id IS NULL THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'UNAUTHENTICATED',
        'details', jsonb_build_object('reason', 'actor_required')
      )
    );
  END IF;

  IF v_capability = '' OR NOT (v_capability = ANY(v_known_capabilities)) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object(
          'field', 'capability',
          'capability', NULLIF(v_capability, '')
        )
      )
    );
  END IF;

  SELECT *
  INTO v_admin
  FROM public.admin_users
  WHERE id = p_actor_admin_id;

  IF NOT FOUND OR v_admin.active = false THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'UNAUTHENTICATED',
        'details', jsonb_build_object('reason', 'actor_unavailable')
      )
    );
  END IF;

  v_allowed := CASE
    WHEN v_admin.role = 'staff' THEN v_capability = ANY(v_staff_capabilities)
    WHEN v_admin.role IN ('manager', 'owner', 'engineer') THEN true
    -- accountant is intentionally fail-closed for every VIP Floor capability.
    ELSE false
  END;

  IF NOT v_allowed THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'FORBIDDEN',
        'details', jsonb_build_object(
          'capability', v_capability,
          'role', v_admin.role
        )
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'action', 'allowed',
    'actor', jsonb_build_object(
      'id', v_admin.id,
      'role', v_admin.role
    ),
    'capability', v_capability
  );
END;
$$;

-- FUNCTION: reservation_effective_interval_v8(uuid)
CREATE FUNCTION public.reservation_effective_interval_v8(p_reservation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_reservation public.reservations%ROWTYPE;
BEGIN
  IF p_reservation_id IS NULL THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object('field', 'reservationId')
      )
    );
  END IF;

  SELECT *
  INTO v_reservation
  FROM public.reservations
  WHERE id = p_reservation_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'NOT_FOUND',
        'details', jsonb_build_object(
          'entityType', 'reservation'
        )
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'action', 'resolved',
    'reservationId', v_reservation.id,
    'eventDayId', v_reservation.event_day_id,
    'interval', jsonb_build_object(
      'startAt', v_reservation.scheduled_start_at,
      'scheduledEndAt', v_reservation.scheduled_end_at,
      'endAt', v_reservation.expected_release_at
    )
  );
END;
$$;

-- FUNCTION: resolve_admin_refund_review_v7(uuid, text, text, text, text, uuid, text, integer, text)
CREATE FUNCTION public.resolve_admin_refund_review_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_refund_case_id uuid, p_decision text, p_amount_yen integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_existing admin_action_requests%ROWTYPE;
  v_case refund_cases%ROWTYPE;
  v_payment payments%ROWTYPE;
  v_reserved_amount bigint := 0;
  v_unlinked_refund_amount bigint := 0;
  v_remaining_amount bigint := 0;
  v_final_amount int;
  v_response jsonb;
BEGIN
  SELECT * INTO v_admin FROM admin_users WHERE id = p_actor_admin_id FOR UPDATE;
  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;
  IF v_admin.role NOT IN ('manager','owner','engineer','accountant') THEN
    RAISE EXCEPTION 'admin role cannot resolve refund reviews';
  END IF;

  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'reason is required for refund review resolution';
  END IF;

  IF lower(btrim(COALESCE(p_decision, ''))) NOT IN ('approve','waive') THEN
    RAISE EXCEPTION 'invalid refund review decision';
  END IF;

  SELECT * INTO v_existing
  FROM admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object('action', 'mismatch', 'error', 'idempotency_key_reused_with_different_request');
    END IF;
    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  SELECT * INTO v_case
  FROM refund_cases
  WHERE id = p_refund_case_id
  FOR UPDATE;

  IF NOT FOUND OR v_case.status <> 'requested' THEN
    RAISE EXCEPTION 'refund review case cannot be resolved';
  END IF;

  -- Maker-checker: the admin who filed the review (the cancelling admin)
  -- may not resolve it. W07-N3 (v75): system-filed reviews
  -- (requested_by_admin_id IS NULL) previously skipped every requester check;
  -- mirror the approve-side rule so only owner/accountant may resolve them.
  IF v_case.requested_by_admin_id IS NOT NULL THEN
    IF v_case.requested_by_admin_id = p_actor_admin_id THEN
      RAISE EXCEPTION 'requesting admin cannot resolve own refund review';
    END IF;
  ELSIF v_admin.role NOT IN ('owner','accountant') THEN
    RAISE EXCEPTION 'system-filed refund review requires owner or accountant resolution';
  END IF;

  IF lower(btrim(p_decision)) = 'waive' THEN
    UPDATE refund_cases
    SET status = 'waived',
        approved_by_admin_id = p_actor_admin_id,
        approved_at = now(),
        error_json = jsonb_build_object('waivedReason', p_reason, 'resolvedFrom', 'requested'),
        updated_at = now()
    WHERE id = v_case.id;
    v_final_amount := 0;
  ELSE
    SELECT * INTO v_payment FROM payments WHERE id = v_case.payment_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'refund case payment not found';
    END IF;

    -- Remaining excludes this case (still 'requested' at this point) but
    -- counts every other open/terminal case plus unlinked external refunds.
    SELECT COALESCE(sum(rc.amount_yen), 0)
    INTO v_reserved_amount
    FROM refund_cases rc
    WHERE rc.payment_id = v_payment.id
      AND rc.id <> v_case.id
      AND rc.status IN ('required','requested','approved','processing','refunded');

    SELECT COALESCE(sum(sr.amount_yen), 0)
    INTO v_unlinked_refund_amount
    FROM stripe_refunds sr
    WHERE sr.payment_id = v_payment.id
      AND sr.refund_case_id IS NULL
      AND lower(sr.status) IN ('created','pending','succeeded');

    v_remaining_amount := v_payment.amount_yen - v_reserved_amount - v_unlinked_refund_amount;
    v_final_amount := COALESCE(p_amount_yen, v_case.amount_yen);

    IF v_final_amount <= 0 OR v_final_amount > v_remaining_amount THEN
      RAISE EXCEPTION 'refund review amount exceeds remaining refundable balance'
        USING ERRCODE = 'P0001',
              DETAIL = 'remaining_refundable_yen=' || v_remaining_amount;
    END IF;

    UPDATE refund_cases
    SET status = 'approved',
        amount_yen = v_final_amount,
        approved_by_admin_id = p_actor_admin_id,
        approved_at = now(),
        error_json = jsonb_build_object('resolvedFrom', 'requested', 'resolveReason', p_reason),
        updated_at = now()
    WHERE id = v_case.id;
  END IF;

  v_response := jsonb_build_object(
    'refundCaseId', v_case.id,
    'reservationId', v_case.reservation_id,
    'paymentId', v_case.payment_id,
    'decision', lower(btrim(p_decision)),
    'amountYen', v_final_amount,
    'workerEligible', lower(btrim(p_decision)) = 'approve'
  );

  INSERT INTO admin_action_requests(actor_admin_id, action, idempotency_key, request_hash, response_json)
  VALUES (p_actor_admin_id, p_action, p_idempotency_key, p_request_hash, v_response);

  INSERT INTO audit_logs(actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason)
  VALUES (p_actor_admin_id, 'admin', p_action, 'refund_cases', v_case.id, p_request_id, v_response, p_reason);

  RETURN jsonb_build_object('action', 'resolved', 'response', v_response);
END;
$$;

-- FUNCTION: resolve_business_day_for_timestamp_v8(timestamp with time zone)
CREATE FUNCTION public.resolve_business_day_for_timestamp_v8(p_occurred_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_match_count int;
  v_event_day public.event_days%ROWTYPE;
BEGIN
  IF p_occurred_at IS NULL THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object('field', 'occurredAt')
      )
    );
  END IF;

  -- Absolute half-open windows correctly retain the preceding business date
  -- when its local sales window closes after midnight.
  SELECT count(*)
  INTO v_match_count
  FROM public.event_days
  WHERE sales_open_at <= p_occurred_at
    AND sales_close_at > p_occurred_at;

  IF v_match_count = 0 THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'NOT_FOUND',
        'details', jsonb_build_object(
          'entityType', 'business_day',
          'occurredAt', p_occurred_at
        )
      )
    );
  END IF;

  IF v_match_count > 1 THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object(
          'field', 'occurredAt',
          'reason', 'ambiguous_business_day',
          'candidateCount', v_match_count
        )
      )
    );
  END IF;

  SELECT *
  INTO v_event_day
  FROM public.event_days
  WHERE sales_open_at <= p_occurred_at
    AND sales_close_at > p_occurred_at
  ORDER BY sales_open_at DESC, id
  LIMIT 1;

  RETURN jsonb_build_object(
    'action', 'resolved',
    'eventDayId', v_event_day.id,
    'businessDate', v_event_day.business_date,
    'venueTimezone', v_event_day.venue_timezone,
    'localTimestamp', p_occurred_at AT TIME ZONE v_event_day.venue_timezone,
    'salesOpenAt', v_event_day.sales_open_at,
    'salesCloseAt', v_event_day.sales_close_at,
    'crossesLocalMidnight',
      (v_event_day.sales_close_at AT TIME ZONE v_event_day.venue_timezone)::date
      > (v_event_day.sales_open_at AT TIME ZONE v_event_day.venue_timezone)::date
  );
END;
$$;

-- FUNCTION: resolve_external_finance_review_v8(uuid, uuid, text, text, uuid, text)
CREATE FUNCTION public.resolve_external_finance_review_v8(p_actor_admin_id uuid, p_review_id uuid, p_resolution text, p_note text, p_link_payment_id uuid DEFAULT NULL::uuid, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin public.admin_users%ROWTYPE;
  v_review public.external_finance_reviews%ROWTYPE;
  v_payment public.payments%ROWTYPE;
  v_apply jsonb := NULL;
BEGIN
  SELECT * INTO v_admin FROM public.admin_users WHERE id = p_actor_admin_id;
  IF NOT FOUND OR v_admin.active IS DISTINCT FROM true
    OR v_admin.role NOT IN ('manager','owner','engineer','accountant') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF p_resolution NOT IN ('resolved','dismissed')
    OR NULLIF(btrim(COALESCE(p_note, '')), '') IS NULL THEN
    RAISE EXCEPTION 'invalid review resolution';
  END IF;

  SELECT * INTO v_review
  FROM public.external_finance_reviews
  WHERE id = p_review_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'review not found';
  END IF;
  IF v_review.status <> 'review_required' THEN
    RETURN jsonb_build_object('action', 'reused', 'status', v_review.status);
  END IF;

  IF p_link_payment_id IS NOT NULL THEN
    SELECT * INTO v_payment
    FROM public.payments p
    WHERE p.id = p_link_payment_id
      AND p.environment = v_review.environment
      AND p.stripe_account_key = v_review.stripe_account_key;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'linked payment not in review scope';
    END IF;
    UPDATE public.external_finance_reviews
    SET payment_id = v_payment.id,
        reservation_id = v_payment.reservation_id,
        updated_at = now()
    WHERE id = v_review.id;

    -- A linked refund fact can now be applied for real.
    IF p_resolution = 'resolved' AND v_review.event_kind = 'refund' THEN
      v_apply := public.apply_external_refund_fact_v8(
        v_review.environment,
        v_review.stripe_account_id,
        v_review.provider_object_id,
        v_review.payload_json ->> 'status',
        COALESCE((v_review.payload_json ->> 'amount')::bigint, v_review.amount_yen),
        v_review.payload_json ->> 'currency',
        v_review.payload_json ->> 'charge',
        v_review.payload_json ->> 'payment_intent',
        v_review.payload_json -> 'metadata',
        v_review.payload_json,
        v_review.payload_json ->> '_lastEventId',
        NULLIF(v_review.payload_json ->> '_lastEventCreatedAt', '')::timestamptz,
        v_payment.id
      );
    END IF;
  END IF;

  UPDATE public.external_finance_reviews
  SET status = p_resolution,
      resolved_by_admin_id = p_actor_admin_id,
      resolved_at = now(),
      resolution_note = p_note,
      updated_at = now()
  WHERE id = v_review.id;

  INSERT INTO public.audit_logs(
    actor_admin_id, actor_type, action, target_table, target_id, request_id, after_json, reason
  ) VALUES (
    p_actor_admin_id, 'admin', 'external_finance_review.resolve', 'external_finance_reviews',
    v_review.id, p_request_id,
    jsonb_build_object(
      'status', p_resolution,
      'linkedPaymentId', p_link_payment_id,
      'applyResult', v_apply
    ),
    p_note
  );

  RETURN jsonb_build_object(
    'action', 'resolved',
    'status', p_resolution,
    'reviewId', v_review.id,
    'applyResult', v_apply
  );
END;
$$;

-- FUNCTION: resolve_ticket_checkout_dispute_v1(uuid, uuid, uuid, text, text, text, text, text, text, text, text, timestamp with time zone, text, text, text, timestamp with time zone, jsonb)
CREATE FUNCTION public.resolve_ticket_checkout_dispute_v1(p_ticket_order_id uuid, p_provider_checkout_action_id uuid, p_provider_event_session_id uuid, p_provider_check_in_mode text, p_environment text, p_stripe_account_id text, p_checkout_session_id text, p_client_reference_id text, p_payment_intent_id text, p_provider_flow text, p_provider_response_hash text, p_provider_expires_at timestamp with time zone, p_dispute_id text, p_dispute_status text, p_last_event_id text, p_last_event_created_at timestamp with time zone, p_payload_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_binding jsonb;
BEGIN
  v_binding := public.bind_verified_ticket_checkout_payment_v28(
    p_ticket_order_id,
    p_provider_checkout_action_id,
    p_provider_event_session_id,
    p_provider_check_in_mode,
    p_environment,
    p_stripe_account_id,
    p_checkout_session_id,
    p_client_reference_id,
    p_payment_intent_id,
    p_provider_flow,
    p_provider_response_hash,
    p_provider_expires_at);
  IF v_binding ->> 'action' NOT IN ('bound', 'reused') THEN
    RETURN v_binding;
  END IF;

  RETURN public.resolve_ticket_dispute_closed_v1(
    p_ticket_order_id,
    p_environment,
    p_stripe_account_id,
    p_payment_intent_id,
    p_dispute_id,
    p_dispute_status,
    p_last_event_id,
    p_last_event_created_at,
    p_payload_json)
    || jsonb_build_object('checkoutActionId', v_binding ->> 'checkoutActionId');
END;
$$;

-- FUNCTION: resolve_ticket_checkout_review_v1(uuid, text, text, uuid, text, text, text, timestamp with time zone, text, timestamp with time zone, integer)
CREATE FUNCTION public.resolve_ticket_checkout_review_v1(p_actor_admin_id uuid, p_idempotency_key text, p_request_hash text, p_checkout_action_id uuid, p_decision text, p_reason text, p_provider_session_id text DEFAULT NULL::text, p_provider_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_provider_evidence_hash text DEFAULT NULL::text, p_provider_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_provider_amount_yen integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_claim jsonb;
  v_response jsonb;
  v_action public.ticket_checkout_actions%ROWTYPE;
  v_order public.ticket_orders%ROWTYPE;
  v_target_state text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admin_users AS admin_user
    WHERE admin_user.id = p_actor_admin_id
      AND admin_user.active
      AND admin_user.role = 'owner'
  ) THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'owner_role_required');
  END IF;

  IF NULLIF(btrim(COALESCE(p_idempotency_key, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL
    OR p_checkout_action_id IS NULL
    OR COALESCE(p_decision, '') NOT IN ('requeue', 'acknowledge', 'mark_provider_paid', 'escalate')
    OR NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL
    OR char_length(btrim(p_reason)) > 240
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'resolution_input_invalid');
  END IF;

  IF p_decision = 'mark_provider_paid'
    AND (
      COALESCE(btrim(p_provider_session_id), '') !~ '^cs_(test|live)_[A-Za-z0-9_]{1,240}$'
      OR p_provider_expires_at IS NULL
      OR COALESCE(p_provider_evidence_hash, '') !~ '^[0-9a-f]{64}$'
      OR p_provider_observed_at IS NULL
      OR p_provider_observed_at > clock_timestamp() + interval '5 minutes'
      OR p_provider_amount_yen IS NULL
      OR p_provider_amount_yen < 0
    )
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'provider_facts_invalid');
  END IF;

  -- admin_action_requests is always the first locked/created authority row.
  v_claim := public.preclaim_admin_action_request_v8(
    p_actor_admin_id,
    'resolve_ticket_checkout_review_v1',
    btrim(p_idempotency_key),
    btrim(p_request_hash)
  );
  IF v_claim ->> 'action' = 'reused' THEN
    RETURN (v_claim -> 'response') || jsonb_build_object('reused', true);
  ELSIF v_claim ->> 'action' <> 'claimed' THEN
    RETURN CASE v_claim #>> '{error,code}'
      WHEN 'IDEMPOTENCY_MISMATCH' THEN jsonb_build_object(
        'action', 'conflict', 'reused', false, 'reason', 'idempotency_mismatch')
      WHEN 'IDEMPOTENCY_IN_PROGRESS' THEN jsonb_build_object(
        'action', 'conflict', 'reused', false, 'reason', 'idempotency_in_progress')
      ELSE jsonb_build_object('action', 'rejected', 'reused', false, 'reason', 'input_invalid')
    END;
  END IF;

  -- Lock order matches every other checkout writer: Action -> Order.
  SELECT * INTO v_action
  FROM public.ticket_checkout_actions
  WHERE id = p_checkout_action_id
  FOR UPDATE;
  IF NOT FOUND THEN
    v_response := jsonb_build_object('action', 'rejected', 'reason', 'checkout_action_not_found');
    RETURN public.complete_ticket_checkout_review_action_v1(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  SELECT * INTO v_order
  FROM public.ticket_orders
  WHERE id = v_action.ticket_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    v_response := jsonb_build_object('action', 'rejected', 'reason', 'checkout_order_missing');
    RETURN public.complete_ticket_checkout_review_action_v1(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  IF v_action.state <> 'review_required' THEN
    -- Idempotent repair: the row already left review (operator retry, worker
    -- race). Report the current state instead of failing closed.
    v_response := jsonb_build_object(
      'action', 'reused',
      'checkoutActionId', v_action.id,
      'orderId', v_order.id,
      'state', v_action.state,
      'orderStatus', v_order.status);
    RETURN public.complete_ticket_checkout_review_action_v1(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  IF p_decision = 'requeue' THEN
    IF v_order.status <> 'pending' THEN
      v_response := jsonb_build_object(
        'action', 'rejected', 'reason', 'order_not_pending',
        'orderStatus', v_order.status);
      RETURN public.complete_ticket_checkout_review_action_v1(
        p_actor_admin_id, p_idempotency_key, v_response);
    END IF;
    -- provider_shape_check requires provider_created rows to carry a recorded
    -- Session id, response hash and expiry. A review row that has a Session id
    -- but no provider facts is requeued as 'claimed': the immutable seal plus
    -- the durable provider idempotency key make the next create call converge
    -- on the same Stripe Session, and readBoundProviderFacts re-verifies the
    -- binding. If the seal is also absent the seal CAS rejects (a Session id
    -- already exists) and the row lands back in review — never a new Session.
    UPDATE public.ticket_checkout_actions
    SET state = CASE
          WHEN checkout_session_id IS NOT NULL
            AND provider_response_hash IS NOT NULL
            AND provider_expires_at IS NOT NULL
          THEN 'provider_created' ELSE 'claimed' END,
        review_reason = NULL,
        recovery_claim_token = NULL,
        recovery_claimed_by = NULL,
        recovery_claimed_at = NULL,
        recovery_claim_expires_at = NULL,
        recovery_next_attempt_at = clock_timestamp(),
        recovery_last_outcome = 'operator_requeue',
        updated_at = now()
    WHERE id = v_action.id
      AND state = 'review_required';
    v_target_state := CASE
      WHEN v_action.checkout_session_id IS NOT NULL
        AND v_action.provider_response_hash IS NOT NULL
        AND v_action.provider_expires_at IS NOT NULL
      THEN 'provider_created' ELSE 'claimed' END;

  ELSIF p_decision = 'acknowledge' THEN
    -- Only a terminal order fact may close the review; a pending order must be
    -- re-queued or evidence-resolved instead.
    v_target_state := CASE v_order.status
      WHEN 'fulfilled' THEN 'completed'
      WHEN 'paid' THEN 'completed'
      WHEN 'expired' THEN 'expired'
      WHEN 'refunded' THEN 'failed'
      WHEN 'cancelled' THEN 'failed'
      ELSE NULL END;
    IF v_target_state IS NULL THEN
      v_response := jsonb_build_object(
        'action', 'rejected', 'reason', 'order_not_terminal',
        'orderStatus', v_order.status);
      RETURN public.complete_ticket_checkout_review_action_v1(
        p_actor_admin_id, p_idempotency_key, v_response);
    END IF;
    -- provider_shape_check / expired_shape_check make 'completed' and
    -- 'expired' evidence-carrying states. A review row that lacks the durable
    -- provider facts cannot adopt them; the operator must supply facts via
    -- mark_provider_paid or requeue for the worker to collect them.
    IF (
      v_target_state = 'completed'
      AND (
        NULLIF(btrim(COALESCE(v_action.checkout_session_id, '')), '') IS NULL
        OR NULLIF(btrim(COALESCE(v_action.provider_response_hash, '')), '') IS NULL
        OR v_action.provider_expires_at IS NULL
      )
    ) OR (
      v_target_state = 'expired'
      AND (
        v_action.provider_terminal_status IS DISTINCT FROM 'expired'
        OR NULLIF(btrim(COALESCE(v_action.provider_terminal_evidence_hash, '')), '') IS NULL
        OR v_action.provider_terminal_observed_at IS NULL
      )
    ) THEN
      v_response := jsonb_build_object(
        'action', 'rejected', 'reason', 'provider_facts_required',
        'orderStatus', v_order.status);
      RETURN public.complete_ticket_checkout_review_action_v1(
        p_actor_admin_id, p_idempotency_key, v_response);
    END IF;
    UPDATE public.ticket_checkout_actions
    SET state = v_target_state,
        review_reason = NULL,
        completed_at = CASE WHEN v_target_state = 'completed'
          THEN COALESCE(completed_at, now()) ELSE completed_at END,
        recovery_claim_token = NULL,
        recovery_claimed_by = NULL,
        recovery_claimed_at = NULL,
        recovery_claim_expires_at = NULL,
        recovery_last_outcome = 'operator_acknowledge',
        updated_at = now()
    WHERE id = v_action.id
      AND state = 'review_required';

  ELSIF p_decision = 'escalate' THEN
    -- Terminal operator path for a binding that can never produce reconciling
    -- provider evidence. Only a pending order may escalate; a terminal order
    -- is closed by 'acknowledge' instead. No provider-evidence params are
    -- required — the point is that evidence can never be produced.
    IF v_order.status <> 'pending' THEN
      v_response := jsonb_build_object(
        'action', 'rejected', 'reason', 'order_terminal_use_acknowledge',
        'orderStatus', v_order.status);
      RETURN public.complete_ticket_checkout_review_action_v1(
        p_actor_admin_id, p_idempotency_key, v_response);
    END IF;
    -- 'failed' is in ticket_checkout_actions_state_check (v28:99-103) and
    -- carries no shape-check obligations; worker/recovery lanes only scan
    -- 'claimed'/'provider_created'/'review_required', so the row exits the
    -- review loop permanently. recovery_next_attempt_at is NOT NULL (v28:62)
    -- and is left untouched: the stale value is inert once state='failed'
    -- (matching the acknowledge branch, which also leaves it).
    UPDATE public.ticket_checkout_actions
    SET state = 'failed',
        review_reason = 'escalated_owner',
        recovery_claim_token = NULL,
        recovery_claimed_by = NULL,
        recovery_claimed_at = NULL,
        recovery_claim_expires_at = NULL,
        recovery_last_outcome = 'operator_escalated',
        updated_at = now()
    WHERE id = v_action.id
      AND state = 'review_required';
    -- Preserve the unresolved obligation (pending order vs possibly-paid
    -- provider Session) on the bounded owner surface
    -- resolve_external_finance_review_v8 instead of dropping it.
    -- 'provider_state_contradiction' is an existing event_kind (v67:117-121);
    -- ticket_orders is deliberately untouched so a possibly-paid order is
    -- never voided/cancelled without refund evidence.
    INSERT INTO public.external_finance_reviews (
      environment, stripe_account_id, event_kind, provider_object_id,
      amount_yen, currency, reason, payload_json
    ) VALUES (
      v_action.environment,
      v_action.stripe_account_id,
      'provider_state_contradiction',
      COALESCE(v_action.checkout_session_id, 'action:' || v_action.id::text),
      v_order.amount_yen,
      'JPY',
      'checkout_review_escalated',
      jsonb_build_object(
        'checkoutActionId', v_action.id,
        'ticketOrderId', v_order.id,
        'operatorReason', p_reason,
        'reviewReason', v_action.review_reason)
    )
    ON CONFLICT (environment, stripe_account_key, event_kind,
                 provider_object_id, reason) DO NOTHING;
    v_target_state := 'failed';

  ELSE -- mark_provider_paid
    -- The caller re-fetched the provider Session and verified payment_status=
    -- 'paid' plus metadata binding; the RPC re-checks every durable fact it
    -- can see: pending order, matching amount, matching recorded Session.
    IF v_order.status <> 'pending' THEN
      v_response := jsonb_build_object(
        'action', 'rejected', 'reason', 'order_not_pending',
        'orderStatus', v_order.status);
      RETURN public.complete_ticket_checkout_review_action_v1(
        p_actor_admin_id, p_idempotency_key, v_response);
    END IF;
    IF p_provider_amount_yen <> v_order.amount_yen
      OR (v_action.checkout_session_id IS NOT NULL
        AND v_action.checkout_session_id <> btrim(p_provider_session_id))
      OR (v_order.checkout_session_id IS NOT NULL
        AND v_order.checkout_session_id <> btrim(p_provider_session_id))
      OR EXISTS (
        SELECT 1 FROM public.ticket_checkout_actions AS other
        WHERE other.id <> v_action.id
          AND other.checkout_session_id = btrim(p_provider_session_id)
      ) OR EXISTS (
        SELECT 1 FROM public.ticket_orders AS other_order
        WHERE other_order.id <> v_order.id
          AND other_order.checkout_session_id = btrim(p_provider_session_id)
      )
    THEN
      v_response := jsonb_build_object(
        'action', 'rejected', 'reason', 'provider_facts_mismatch');
      RETURN public.complete_ticket_checkout_review_action_v1(
        p_actor_admin_id, p_idempotency_key, v_response);
    END IF;
    UPDATE public.ticket_orders
    SET checkout_session_id = btrim(p_provider_session_id)
    WHERE id = v_order.id
      AND checkout_session_id IS NULL;
    UPDATE public.ticket_checkout_actions
    SET state = 'provider_created',
        checkout_session_id = btrim(p_provider_session_id),
        provider_response_hash = btrim(p_provider_evidence_hash),
        provider_expires_at = p_provider_expires_at,
        provider_terminal_evidence_hash = btrim(p_provider_evidence_hash),
        provider_terminal_observed_at = p_provider_observed_at,
        review_reason = NULL,
        recovery_claim_token = NULL,
        recovery_claimed_by = NULL,
        recovery_claimed_at = NULL,
        recovery_claim_expires_at = NULL,
        recovery_next_attempt_at = clock_timestamp() + interval '15 minutes',
        recovery_last_outcome = 'operator_marked_paid',
        updated_at = now()
    WHERE id = v_action.id
      AND state = 'review_required';
    v_target_state := 'provider_created';
  END IF;

  INSERT INTO public.audit_logs(
    action, actor_type, actor_admin_id, target_table, target_id,
    entity_type, entity_id, operation, reason, metadata_json
  ) VALUES (
    'ticket_checkout.review_resolved', 'admin', p_actor_admin_id,
    'ticket_checkout_actions', v_action.id,
    'ticket_checkout_action', v_action.id, 'update', left(btrim(p_reason), 240),
    jsonb_build_object(
      'decision', p_decision,
      'orderId', v_order.id,
      'previousReviewReason', v_action.review_reason,
      'targetState', v_target_state,
      'providerEvidenceHash', p_provider_evidence_hash,
      'providerObservedAt', p_provider_observed_at));

  v_response := jsonb_build_object(
    'action', 'resolved',
    'decision', p_decision,
    'checkoutActionId', v_action.id,
    'orderId', v_order.id,
    'state', v_target_state,
    'orderStatus', v_order.status);
  RETURN public.complete_ticket_checkout_review_action_v1(
    p_actor_admin_id, p_idempotency_key, v_response);
END;
$_$;

-- FUNCTION: resolve_ticket_dispute_closed_v1(uuid, text, text, text, text, text, text, timestamp with time zone, jsonb)
CREATE FUNCTION public.resolve_ticket_dispute_closed_v1(p_ticket_order_id uuid, p_environment text, p_stripe_account_id text, p_payment_intent_id text, p_dispute_id text, p_dispute_status text, p_last_event_id text, p_last_event_created_at timestamp with time zone, p_payload_json jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order public.ticket_orders%ROWTYPE;
  v_venue_timezone text;
  v_event_ended boolean;
  v_hold_cleared boolean := false;
  v_unvoided integer := 0;
  v_actions_cleared integer := 0;
BEGIN
  IF p_ticket_order_id IS NULL
    OR COALESCE(p_environment, '') NOT IN ('test', 'live')
    OR NULLIF(btrim(COALESCE(p_payment_intent_id, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_dispute_id, '')), '') IS NULL
    OR COALESCE(p_dispute_status, '') NOT IN ('won', 'lost')
    OR NULLIF(btrim(COALESCE(p_last_event_id, '')), '') IS NULL
    OR p_last_event_created_at IS NULL
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'dispute_facts_invalid');
  END IF;

  -- Serialise against fulfilment, refund allocation and revocation replays of
  -- the same order; the order row is the single lock for all of them.
  SELECT * INTO v_order
  FROM public.ticket_orders
  WHERE id = p_ticket_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'not_found');
  END IF;

  IF v_order.environment <> p_environment
    OR v_order.stripe_account_key <> COALESCE(p_stripe_account_id, 'platform')
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'environment_mismatch');
  END IF;

  -- Re-verify the caller's PaymentIntent→order binding under the lock: a
  -- dispute event must never release a hold on an order whose payment it
  -- does not belong to, even if the TS-side lookup raced a re-bind.
  IF v_order.payment_intent_id IS DISTINCT FROM btrim(p_payment_intent_id) THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'payment_intent_mismatch');
  END IF;

  -- Durable provider fact first: even when nothing below mutates, the dispute
  -- object's terminal state is now recorded so a late dispute.created cannot
  -- silently re-apply the hold (the worker reads it before holding).
  PERFORM public.record_stripe_object_state_v7(
    p_environment,
    p_stripe_account_id,
    'dispute',
    btrim(p_dispute_id),
    p_dispute_status,
    btrim(p_last_event_id),
    p_last_event_created_at,
    COALESCE(p_payload_json, '{}'::jsonb)
  );

  IF p_dispute_status = 'lost' THEN
    -- The chargeback is final. Keep the hold exactly as it is; the order and
    -- its admissions stay unreachable. Only the audit gains the outcome.
    INSERT INTO public.audit_logs(
      action, actor_type, target_table, target_id,
      entity_type, entity_id, operation, reason, metadata_json
    ) VALUES (
      'ticket_dispute.lost_hold_kept', 'system', 'ticket_orders', v_order.id,
      'ticket_order', v_order.id, 'update', 'stripe_dispute_lost',
      jsonb_build_object('disputeId', btrim(p_dispute_id),
                         'orderStatus', v_order.status,
                         'paymentHoldReason', v_order.payment_hold_reason,
                         'lastEventId', btrim(p_last_event_id))
    );
    RETURN jsonb_build_object(
      'action', 'held',
      'reason', 'dispute_lost_hold_retained',
      'orderId', v_order.id,
      'orderStatus', v_order.status,
      'holdCleared', false,
      'unvoided', 0);
  END IF;

  -- p_dispute_status = 'won' below.

  -- Never resurrect entry for an event whose business date already passed in
  -- the venue timezone. The dispute state above is still recorded.
  SELECT COALESCE(
      (
        SELECT event_day.venue_timezone
        FROM public.event_days AS event_day
        WHERE event_day.business_date = v_order.event_date
      ),
      'Asia/Tokyo')
  INTO v_venue_timezone;
  v_event_ended :=
    (now() AT TIME ZONE v_venue_timezone)::date > v_order.event_date;
  IF v_event_ended THEN
    INSERT INTO public.audit_logs(
      action, actor_type, target_table, target_id,
      entity_type, entity_id, operation, reason, metadata_json
    ) VALUES (
      'ticket_dispute.won_after_event', 'system', 'ticket_orders', v_order.id,
      'ticket_order', v_order.id, 'update', 'stripe_dispute_won_event_ended',
      jsonb_build_object('disputeId', btrim(p_dispute_id),
                         'orderStatus', v_order.status,
                         'eventDate', v_order.event_date,
                         'lastEventId', btrim(p_last_event_id))
    );
    RETURN jsonb_build_object(
      'action', 'reused',
      'reason', 'dispute_won_event_ended',
      'orderId', v_order.id,
      'orderStatus', v_order.status,
      'holdCleared', false,
      'unvoided', 0);
  END IF;

  -- A refunded, cancelled or expired order never comes back; a paid/fulfilled
  -- one is the only shape that can hold usable entry. The status check runs
  -- before any mutation so a full refund decided elsewhere always wins.
  IF v_order.status NOT IN ('pending', 'paid', 'fulfilled') THEN
    INSERT INTO public.audit_logs(
      action, actor_type, target_table, target_id,
      entity_type, entity_id, operation, reason, metadata_json
    ) VALUES (
      'ticket_dispute.won_no_restore', 'system', 'ticket_orders', v_order.id,
      'ticket_order', v_order.id, 'update', 'stripe_dispute_won_terminal_order',
      jsonb_build_object('disputeId', btrim(p_dispute_id),
                         'orderStatus', v_order.status,
                         'paymentHoldReason', v_order.payment_hold_reason,
                         'lastEventId', btrim(p_last_event_id))
    );
    RETURN jsonb_build_object(
      'action', 'reused',
      'reason', 'dispute_won_order_terminal',
      'orderId', v_order.id,
      'orderStatus', v_order.status,
      'holdCleared', false,
      'unvoided', 0);
  END IF;

  -- Release exactly this dispute's hold. 'charge_refunded' and any other
  -- hold reason are left untouched by the conditional WHERE.
  UPDATE public.ticket_orders
  SET payment_hold_reason = NULL,
      payment_hold_at = NULL
  WHERE id = v_order.id
    AND payment_hold_reason = 'payment_dispute_open';
  v_hold_cleared := FOUND;

  -- Legacy-path repair: only admissions voided by THIS dispute come back.
  -- New revocations tag the reason with the dispute id
  -- (stripe_dispute_opened:<dp_id>); the bare marker covers rows voided before
  -- that attribution existed. 'admitted' admissions were never voided, and
  -- voids written for any other reason (refund allocation, operator
  -- revocation, a different dispute) keep their door record.
  UPDATE public.ticket_admissions
  SET status = 'issued',
      voided_at = NULL,
      void_reason = NULL
  WHERE ticket_order_id = v_order.id
    AND status = 'void'
    AND (
      void_reason = 'stripe_dispute_opened'
      OR void_reason = 'stripe_dispute_opened:' || p_dispute_id
    );
  GET DIAGNOSTICS v_unvoided = ROW_COUNT;

  -- The checkout action's review marker clears only for the dispute reason;
  -- 'charge_refunded' and unrelated review reasons stay for their own owners.
  UPDATE public.ticket_checkout_actions
  SET state = CASE WHEN completed_at IS NOT NULL
        THEN 'completed' ELSE 'provider_created' END,
      review_reason = NULL,
      updated_at = now()
  WHERE ticket_order_id = v_order.id
    AND review_reason = 'payment_dispute_open';
  GET DIAGNOSTICS v_actions_cleared = ROW_COUNT;

  INSERT INTO public.audit_logs(
    action, actor_type, target_table, target_id,
    entity_type, entity_id, operation, reason, metadata_json
  ) VALUES (
    'ticket_dispute.won_hold_released', 'system', 'ticket_orders', v_order.id,
    'ticket_order', v_order.id, 'update', 'stripe_dispute_won',
    jsonb_build_object('disputeId', btrim(p_dispute_id),
                       'holdCleared', v_hold_cleared,
                       'unvoided', v_unvoided,
                       'checkoutActionsCleared', v_actions_cleared,
                       'lastEventId', btrim(p_last_event_id))
  );

  RETURN jsonb_build_object(
    'action', CASE WHEN v_hold_cleared OR v_unvoided > 0 OR v_actions_cleared > 0
        THEN 'released' ELSE 'reused' END,
    'reason', 'dispute_won',
    'orderId', v_order.id,
    'orderStatus', v_order.status,
    'holdCleared', v_hold_cleared,
    'unvoided', v_unvoided,
    'checkoutActionsCleared', v_actions_cleared);
END;
$$;

-- FUNCTION: resolve_ticket_refund_review_v26(uuid, text, text, text, uuid, bigint, bigint, text, text, integer[], text)
CREATE FUNCTION public.resolve_ticket_refund_review_v26(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_refund_event_id uuid, p_expected_version bigint, p_expected_observation_version bigint, p_expected_observation_hash text, p_decision text, p_admission_serials integer[], p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_claim jsonb;
  v_response jsonb;
  v_order_id uuid;
  v_order public.ticket_orders%ROWTYPE;
  v_event public.ticket_refund_events%ROWTYPE;
  v_serials integer[];
  v_selected integer;
  v_missing_price integer;
  v_allocated_amount bigint;
  v_admitted integer;
  v_issued integer;
  v_void integer;
  v_cross_allocated integer;
  v_same_allocated integer;
  v_same_state_bad integer;
  v_same_amount_bad integer;
  v_unallocated_void integer;
  v_unallocated_state_bad integer;
  v_new_allocations integer;
  v_authority_amount bigint;
  v_authority_serials integer[] := '{}'::integer[];
  v_succeeded_observations integer := 0;
  v_invalid_succeeded_observations integer := 0;
  v_full_refund_observed boolean := false;
  v_existing_allocation_terminal boolean := false;
  v_voided integer := 0;
  v_inserted integer := 0;
  v_terminal_status text;
  v_audit_id uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admin_users AS admin_user
    WHERE admin_user.id = p_actor_admin_id
      AND admin_user.active
      AND admin_user.role = 'owner'
  ) THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'owner_role_required');
  END IF;

  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_idempotency_key, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL
    OR p_expected_observation_version IS NULL
    OR p_expected_observation_version < 1
    OR COALESCE(p_expected_observation_hash, '') !~ '^[0-9a-f]{64}$'
    OR NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL
    OR char_length(btrim(p_reason)) > 240
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'resolution_input_invalid');
  END IF;

  -- admin_action_requests is always the first locked/created authority row.
  v_claim := public.preclaim_admin_action_request_v8(
    p_actor_admin_id,
    'resolve_ticket_refund_review_v26',
    btrim(p_idempotency_key),
    btrim(p_request_hash)
  );
  IF v_claim ->> 'action' = 'reused' THEN
    RETURN (v_claim -> 'response') || jsonb_build_object('reused', true);
  ELSIF v_claim ->> 'action' <> 'claimed' THEN
    RETURN CASE v_claim #>> '{error,code}'
      WHEN 'IDEMPOTENCY_MISMATCH' THEN jsonb_build_object(
        'action', 'conflict', 'reused', false,
        'reason', 'idempotency_mismatch')
      WHEN 'IDEMPOTENCY_IN_PROGRESS' THEN jsonb_build_object(
        'action', 'conflict', 'reused', false,
        'reason', 'idempotency_in_progress')
      ELSE jsonb_build_object(
        'action', 'rejected', 'reused', false,
        'reason', 'input_invalid')
    END;
  END IF;

  SELECT e.ticket_order_id INTO v_order_id
  FROM public.ticket_refund_events AS e
  WHERE e.id = p_refund_event_id;
  IF v_order_id IS NULL THEN
    v_response := jsonb_build_object('action', 'rejected', 'reason', 'refund_event_not_found');
    RETURN public.complete_ticket_refund_review_action_v26(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  SELECT * INTO v_order
  FROM public.ticket_orders
  WHERE id = v_order_id
  FOR UPDATE;

  SELECT * INTO v_event
  FROM public.ticket_refund_events
  WHERE id = p_refund_event_id
    AND ticket_order_id = v_order.id
  FOR UPDATE;
  IF NOT FOUND THEN
    v_response := jsonb_build_object('action', 'rejected', 'reason', 'refund_event_not_found');
    RETURN public.complete_ticket_refund_review_action_v26(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  IF v_event.observation_history_state = 'legacy_incomplete' THEN
    v_response := jsonb_build_object(
      'action', 'rejected',
      'reason', 'refund_observation_history_incomplete',
      'resolutionStatus', v_event.resolution_status,
      'resolutionVersion', v_event.resolution_version,
      'observationVersion', v_event.observation_version,
      'observationHash', v_event.observation_set_hash,
      'observationHistoryState', v_event.observation_history_state,
      'observationHistoryReason', v_event.observation_history_reason);
    RETURN public.complete_ticket_refund_review_action_v26(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  PERFORM 1
  FROM public.ticket_refund_allocations AS allocation
  WHERE allocation.ticket_refund_event_id = v_event.id
  ORDER BY allocation.admission_serial
  FOR UPDATE;

  IF v_event.resolution_version <> p_expected_version THEN
    v_response := jsonb_build_object(
      'action', 'version_conflict', 'reason', 'resolution_version_mismatch',
      'resolutionVersion', v_event.resolution_version,
      'observationVersion', v_event.observation_version,
      'observationHash', v_event.observation_set_hash);
    RETURN public.complete_ticket_refund_review_action_v26(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  IF v_event.observation_version <> p_expected_observation_version
    OR v_event.observation_set_hash <> p_expected_observation_hash
  THEN
    v_response := jsonb_build_object(
      'action', 'version_conflict', 'reason', 'refund_observation_set_mismatch',
      'resolutionVersion', v_event.resolution_version,
      'observationVersion', v_event.observation_version,
      'observationHash', v_event.observation_set_hash);
    RETURN public.complete_ticket_refund_review_action_v26(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  IF v_event.resolution_status NOT IN ('review_required', 'conflict_review')
    OR v_event.resolved_at IS NOT NULL
  THEN
    v_response := jsonb_build_object(
      'action', 'rejected', 'reason', 'refund_review_already_terminal',
      'resolutionStatus', v_event.resolution_status);
    RETURN public.complete_ticket_refund_review_action_v26(
      p_actor_admin_id, p_idempotency_key, v_response);
  END IF;

  SELECT
    count(*) FILTER (WHERE observation.provider_status = 'succeeded'),
    max(observation.amount_yen) FILTER (WHERE observation.provider_status = 'succeeded'),
    count(*) FILTER (
      WHERE observation.provider_status = 'succeeded'
        AND NOT observation.input_valid),
    COALESCE(bool_or(
      observation.provider_status = 'succeeded'
      AND observation.amount_yen = v_order.amount_yen), false)
  INTO v_succeeded_observations, v_authority_amount,
       v_invalid_succeeded_observations, v_full_refund_observed
  FROM public.ticket_refund_observations AS observation
  WHERE observation.ticket_refund_event_id = v_event.id;

  IF v_succeeded_observations = 0 AND NOT v_event.money_may_have_moved THEN
    IF p_decision <> 'dismiss_no_money_moved' THEN
      v_response := jsonb_build_object(
        'action', 'rejected', 'reason', 'no_money_moved_requires_dismissal');
      RETURN public.complete_ticket_refund_review_action_v26(
        p_actor_admin_id, p_idempotency_key, v_response);
    END IF;

    UPDATE public.ticket_refund_events
    SET resolution_status = 'dismissed_no_money_moved',
        resolution_version = resolution_version + 1,
        resolved_at = now(),
        resolved_by_admin_id = p_actor_admin_id,
        resolution_reason = left(btrim(p_reason), 240),
        resolution_request_hash = btrim(p_request_hash),
        updated_at = now()
    WHERE id = v_event.id
    RETURNING * INTO v_event;
    v_terminal_status := 'dismissed_no_money_moved';
  ELSE
    IF p_decision <> 'apply' THEN
      v_response := jsonb_build_object(
        'action', 'rejected', 'reason', 'successful_refund_requires_allocation');
      RETURN public.complete_ticket_refund_review_action_v26(
        p_actor_admin_id, p_idempotency_key, v_response);
    END IF;

    IF v_succeeded_observations = 0
      OR (v_invalid_succeeded_observations > 0 AND NOT v_full_refund_observed)
      OR v_authority_amount IS NULL
      OR v_authority_amount > v_order.amount_yen
    THEN
      v_response := jsonb_build_object(
        'action', 'rejected', 'reason', 'refund_observation_authority_ambiguous');
      RETURN public.complete_ticket_refund_review_action_v26(
        p_actor_admin_id, p_idempotency_key, v_response);
    END IF;

    IF v_full_refund_observed THEN
      SELECT COALESCE(array_agg(admission.serial ORDER BY admission.serial), '{}'::integer[])
      INTO v_authority_serials
      FROM public.ticket_admissions AS admission
      WHERE admission.ticket_order_id = v_order.id;
    ELSE
      SELECT COALESCE(array_agg(DISTINCT serial ORDER BY serial), '{}'::integer[])
      INTO v_authority_serials
      FROM public.ticket_refund_observations AS observation
      CROSS JOIN LATERAL unnest(observation.input_admission_serials) AS serial
      WHERE observation.ticket_refund_event_id = v_event.id
        AND observation.provider_status = 'succeeded'
        AND observation.input_valid;
    END IF;

    SELECT COALESCE(array_agg(serial ORDER BY serial), '{}'::integer[])
    INTO v_serials
    FROM unnest(COALESCE(p_admission_serials, '{}'::integer[])) AS serial;
    IF cardinality(v_serials) < 1 OR cardinality(v_serials) > 20
      OR EXISTS (SELECT 1 FROM unnest(v_serials) AS serial WHERE serial < 1 OR serial > 20)
      OR cardinality(v_serials) <>
         (SELECT count(DISTINCT serial) FROM unnest(v_serials) AS serial)
    THEN
      v_response := jsonb_build_object('action', 'rejected', 'reason', 'admission_selection_invalid');
      RETURN public.complete_ticket_refund_review_action_v26(
        p_actor_admin_id, p_idempotency_key, v_response);
    END IF;

    IF v_serials <> v_authority_serials THEN
      v_response := jsonb_build_object(
        'action', 'rejected', 'reason', 'refund_observation_selection_mismatch',
        'observationVersion', v_event.observation_version,
        'observationHash', v_event.observation_set_hash);
      RETURN public.complete_ticket_refund_review_action_v26(
        p_actor_admin_id, p_idempotency_key, v_response);
    END IF;

    PERFORM 1
    FROM public.ticket_admissions AS admission
    WHERE admission.ticket_order_id = v_order.id
      AND admission.serial = ANY(v_serials)
    ORDER BY admission.serial
    FOR UPDATE;

    SELECT
      count(*),
      count(*) FILTER (WHERE price.unit_price_yen IS NULL),
      COALESCE(sum(price.unit_price_yen), 0),
      count(*) FILTER (WHERE admission.status = 'admitted'),
      count(*) FILTER (WHERE admission.status = 'issued'),
      count(*) FILTER (WHERE admission.status = 'void'),
      count(*) FILTER (
        WHERE allocation.ticket_admission_id IS NOT NULL
          AND allocation.ticket_refund_event_id <> v_event.id
      ),
      count(*) FILTER (WHERE allocation.ticket_refund_event_id = v_event.id),
      count(*) FILTER (
        WHERE allocation.ticket_refund_event_id = v_event.id
          AND (
            (allocation.outcome = 'voided' AND admission.status <> 'void')
            OR (allocation.outcome = 'admitted_exception' AND admission.status <> 'admitted')
          )
      ),
      count(*) FILTER (
        WHERE allocation.ticket_refund_event_id = v_event.id
          AND allocation.amount_yen IS DISTINCT FROM price.unit_price_yen
      ),
      count(*) FILTER (
        WHERE allocation.ticket_admission_id IS NULL
          AND admission.status = 'void'
      ),
      count(*) FILTER (
        WHERE allocation.ticket_admission_id IS NULL
          AND admission.status NOT IN ('issued', 'admitted')
      ),
      count(*) FILTER (WHERE allocation.ticket_admission_id IS NULL)
    INTO v_selected, v_missing_price, v_allocated_amount, v_admitted,
         v_issued, v_void, v_cross_allocated, v_same_allocated,
         v_same_state_bad, v_same_amount_bad, v_unallocated_void,
         v_unallocated_state_bad, v_new_allocations
    FROM public.ticket_admissions AS admission
    LEFT JOIN LATERAL (
      SELECT CASE
        WHEN item.value ->> 'unitPriceYen' ~ '^[1-9][0-9]*$'
          THEN (item.value ->> 'unitPriceYen')::integer
        ELSE NULL
      END AS unit_price_yen
      FROM jsonb_array_elements(v_order.items_json) WITH ORDINALITY AS item(value, ordinality)
      WHERE item.value ->> 'ticketTypeId' = admission.ticket_type_id
      ORDER BY item.ordinality
      LIMIT 1
    ) AS price ON true
    LEFT JOIN public.ticket_refund_allocations AS allocation
      ON allocation.ticket_admission_id = admission.id
    WHERE admission.ticket_order_id = v_order.id
      AND admission.serial = ANY(v_serials);

    IF v_selected <> cardinality(v_serials) THEN
      v_response := jsonb_build_object('action', 'rejected', 'reason', 'admission_not_found');
    ELSIF v_cross_allocated > 0 THEN
      v_response := jsonb_build_object('action', 'rejected', 'reason', 'cross_refund_allocation_conflict');
    ELSIF v_same_state_bad > 0 OR v_same_amount_bad > 0 THEN
      v_response := jsonb_build_object(
        'action', 'rejected', 'reason', 'existing_allocation_incomplete');
    ELSIF v_unallocated_void > 0 THEN
      v_response := jsonb_build_object('action', 'rejected', 'reason', 'admission_already_void');
    ELSIF v_missing_price > 0 OR v_allocated_amount <> v_authority_amount THEN
      v_response := jsonb_build_object('action', 'rejected', 'reason', 'allocation_amount_mismatch');
    ELSIF v_unallocated_state_bad > 0 THEN
      v_response := jsonb_build_object('action', 'rejected', 'reason', 'admission_state_invalid');
    END IF;
    IF v_response IS NOT NULL THEN
      RETURN public.complete_ticket_refund_review_action_v26(
        p_actor_admin_id, p_idempotency_key, v_response);
    END IF;

    v_existing_allocation_terminal := v_same_allocated = v_selected;
    IF NOT v_existing_allocation_terminal THEN
      INSERT INTO public.ticket_refund_allocations(
        ticket_refund_event_id, ticket_order_id, ticket_admission_id,
        admission_serial, environment, stripe_account_key, stripe_refund_id,
        amount_yen, outcome
      )
      SELECT
        v_event.id, v_order.id, admission.id, admission.serial,
        v_event.environment, v_event.stripe_account_key, v_event.stripe_refund_id,
        price.unit_price_yen,
        CASE WHEN admission.status = 'admitted'
          THEN 'admitted_exception' ELSE 'voided' END
      FROM public.ticket_admissions AS admission
      JOIN LATERAL (
        SELECT (item.value ->> 'unitPriceYen')::integer AS unit_price_yen
        FROM jsonb_array_elements(v_order.items_json) WITH ORDINALITY AS item(value, ordinality)
        WHERE item.value ->> 'ticketTypeId' = admission.ticket_type_id
        ORDER BY item.ordinality
        LIMIT 1
      ) AS price ON true
      WHERE admission.ticket_order_id = v_order.id
        AND admission.serial = ANY(v_serials)
        AND NOT EXISTS (
          SELECT 1 FROM public.ticket_refund_allocations AS existing
          WHERE existing.ticket_admission_id = admission.id
        )
      ORDER BY admission.serial;
      GET DIAGNOSTICS v_inserted = ROW_COUNT;
      IF v_inserted <> v_new_allocations THEN
        RAISE EXCEPTION 'refund resolver allocation row-count mismatch: expected %, got %',
          v_new_allocations, v_inserted;
      END IF;

      UPDATE public.ticket_admissions
      SET status = 'void',
          voided_at = now(),
          void_reason = left('owner_refund_resolution:' || v_event.stripe_refund_id, 240)
      WHERE ticket_order_id = v_order.id
        AND serial = ANY(v_serials)
        AND status = 'issued';
      GET DIAGNOSTICS v_voided = ROW_COUNT;
      IF v_voided <> v_issued THEN
        RAISE EXCEPTION 'refund resolver void row-count mismatch: expected %, got %',
          v_issued, v_voided;
      END IF;
    END IF;

    v_terminal_status := CASE WHEN v_admitted > 0
      THEN 'resolved_admitted_exception' ELSE 'resolved_voided' END;
    UPDATE public.ticket_refund_events
    SET resolution_status = v_terminal_status,
        admission_serials = v_serials,
        resolution_version = resolution_version + 1,
        resolved_at = now(),
        resolved_by_admin_id = p_actor_admin_id,
        resolution_reason = left(btrim(p_reason), 240),
        resolution_request_hash = btrim(p_request_hash),
        updated_at = now()
    WHERE id = v_event.id
    RETURNING * INTO v_event;

    IF v_authority_amount = v_order.amount_yen THEN
      UPDATE public.ticket_orders
      SET status = 'refunded',
          cancelled_at = COALESCE(cancelled_at, now())
      WHERE id = v_order.id
        AND status IN ('pending', 'paid', 'fulfilled');
    END IF;
  END IF;

  INSERT INTO public.audit_logs(
    action, actor_type, actor_admin_id, target_table, target_id,
    entity_type, entity_id, operation, request_id, reason, metadata_json
  ) VALUES (
    'ticket_refund.resolve', 'admin', p_actor_admin_id,
    'ticket_refund_events', v_event.id,
    'ticket_refund_event', v_event.id, 'update', left(p_request_id, 200),
    left(btrim(p_reason), 240),
    jsonb_build_object(
      'decision', p_decision,
      'resolutionStatus', v_terminal_status,
      'resolutionVersion', v_event.resolution_version,
      'observationVersion', v_event.observation_version,
      'observationHash', v_event.observation_set_hash,
      'authoritativeAmountYen', v_authority_amount,
      'admissionSerials', to_jsonb(COALESCE(v_serials, '{}'::integer[])),
      'voided', v_voided,
      'admittedExceptions', COALESCE(v_admitted, 0)
    )
  ) RETURNING id INTO v_audit_id;

  v_response := jsonb_build_object(
    'action', v_terminal_status,
    'reused', false,
    'refundEventId', v_event.id,
    'orderId', v_order.id,
    'resolutionStatus', v_terminal_status,
    'resolutionVersion', v_event.resolution_version,
    'observationVersion', v_event.observation_version,
    'observationHash', v_event.observation_set_hash,
    'voided', v_voided,
    'admittedExceptions', COALESCE(v_admitted, 0),
    'auditLogId', v_audit_id
  );
  RETURN public.complete_ticket_refund_review_action_v26(
    p_actor_admin_id, p_idempotency_key, v_response);
END;
$_$;

-- FUNCTION: resolve_vip_service_transition_v8(uuid, public.vip_service_status, public.vip_service_status, text)
CREATE FUNCTION public.resolve_vip_service_transition_v8(p_actor_admin_id uuid, p_from_status public.vip_service_status, p_to_status public.vip_service_status, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_capability_result jsonb;
  v_role text;
  v_standard_transition boolean := false;
BEGIN
  v_capability_result := public.require_admin_capability_v8(
    p_actor_admin_id,
    'service_status.write'
  );
  IF v_capability_result ->> 'action' <> 'allowed' THEN
    RETURN v_capability_result;
  END IF;
  IF p_to_status IS NULL OR p_from_status IS NOT DISTINCT FROM p_to_status THEN
    RETURN jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
      'code', 'INVALID_STATE_TRANSITION',
      'details', jsonb_build_object(
        'fromStatus', p_from_status, 'toStatus', p_to_status, 'reason', 'target_must_differ'
      )
    ));
  END IF;

  v_standard_transition := CASE
    WHEN p_from_status IS NULL THEN p_to_status IN ('expected', 'seated')
    WHEN p_from_status = 'expected' THEN p_to_status IN ('late', 'no_contact', 'arrived', 'seated', 'no_show')
    WHEN p_from_status = 'late' THEN p_to_status IN ('no_contact', 'arrived', 'no_show')
    WHEN p_from_status = 'no_contact' THEN p_to_status IN ('arrived', 'no_show')
    WHEN p_from_status = 'arrived' THEN p_to_status IN ('partial_arrival', 'seated')
    WHEN p_from_status = 'partial_arrival' THEN p_to_status = 'seated'
    WHEN p_from_status = 'seated' THEN p_to_status IN ('bottle_pending', 'bill_requested')
    WHEN p_from_status = 'bottle_pending' THEN p_to_status = 'bottle_served'
    WHEN p_from_status = 'bottle_served' THEN p_to_status = 'bill_requested'
    WHEN p_from_status = 'bill_requested' THEN p_to_status = 'paid'
    WHEN p_from_status = 'paid' THEN p_to_status = 'resetting'
    WHEN p_from_status = 'resetting' THEN p_to_status = 'completed'
    ELSE false
  END;
  IF v_standard_transition THEN
    RETURN jsonb_build_object('action', 'allowed', 'transition', jsonb_build_object(
      'fromStatus', p_from_status, 'toStatus', p_to_status, 'override', false
    ));
  END IF;

  v_role := v_capability_result #>> '{actor,role}';
  IF v_role = 'owner'
    AND p_reason LIKE 'Owner explicit override: %'
    AND length(btrim(substr(p_reason, length('Owner explicit override: ') + 1))) BETWEEN 1 AND 240
  THEN
    RETURN jsonb_build_object('action', 'allowed', 'transition', jsonb_build_object(
      'fromStatus', p_from_status, 'toStatus', p_to_status, 'override', true
    ));
  END IF;

  RETURN jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
    'code', 'INVALID_STATE_TRANSITION',
    'details', jsonb_build_object(
      'fromStatus', p_from_status,
      'toStatus', p_to_status,
      'overrideAllowed', v_role = 'owner',
      'explicitOwnerConfirmationRequired', true
    )
  ));
END;
$$;

-- FUNCTION: retire_admin_session_v7(text, text)
CREATE FUNCTION public.retire_admin_session_v7(p_session_token_hash text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_session admin_sessions%ROWTYPE;
BEGIN
  UPDATE admin_sessions
  SET active = false,
      retired_at = COALESCE(retired_at, now()),
      updated_at = now()
  WHERE session_token_hash = p_session_token_hash
  RETURNING * INTO v_session;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'ignored', 'reason', 'session_not_found');
  END IF;

  INSERT INTO audit_logs(
    actor_admin_id,
    actor_type,
    action,
    target_table,
    target_id,
    request_id
  )
  VALUES (
    v_session.admin_user_id,
    'admin',
    'admin_session.retire',
    'admin_sessions',
    v_session.id,
    p_request_id
  );

  RETURN jsonb_build_object('action', 'retired', 'sessionId', v_session.id);
END;
$$;

-- FUNCTION: retire_ticket_purchase_delivery_v38(integer)
CREATE FUNCTION public.retire_ticket_purchase_delivery_v38(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j public.transactional_email_jobs%ROWTYPE; category text; n integer:=0;
BEGIN
 IF p_limit NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'invalid retirement batch'; END IF;
 FOR j IN SELECT job.* FROM public.ticket_orders o JOIN public.transactional_email_jobs job ON job.ticket_order_id=o.id
 WHERE job.purpose='ticket_wallet_purchase' AND (job.state IN ('pending','retry') OR(job.state='processing' AND job.lease_expires_at<=clock_timestamp()))
 AND (NOT public.ticket_entry_delivery_active_v53(job.ticket_order_id,job.render_data_json) OR (job.render_data_json->>'expiresAt')::timestamptz<=clock_timestamp() OR job.first_send_at<=clock_timestamp()-interval '23 hours' OR job.attempt_count>=job.maximum_attempts
 OR EXISTS(SELECT 1 FROM public.transactional_email_suppressions s WHERE s.recipient_email_hash=job.recipient_email_hash AND s.active AND (job.provider_name IS NULL OR s.provider_name=job.provider_name)))
 ORDER BY job.created_at,job.id LIMIT p_limit FOR UPDATE OF o,job SKIP LOCKED LOOP
  category:=CASE WHEN NOT public.ticket_entry_delivery_active_v53(j.ticket_order_id,j.render_data_json) THEN 'order_link_revoked' WHEN j.first_send_at<=clock_timestamp()-interval '23 hours' THEN 'purchase_acceptance_unknown'
   WHEN EXISTS(SELECT 1 FROM public.transactional_email_suppressions s WHERE s.recipient_email_hash=j.recipient_email_hash AND s.active) THEN 'purchase_suppressed' ELSE 'purchase_delivery_expired' END;
  UPDATE public.transactional_email_jobs SET state='dead',safe_error_category=category,terminal_at=clock_timestamp(),completed_at=clock_timestamp(),claimed_by=NULL,claim_token=NULL,claimed_at=NULL,lease_expires_at=NULL,updated_at=clock_timestamp() WHERE id=j.id;
  n:=n+1;
 END LOOP;
 RETURN n;
END; $$;

-- FUNCTION: reuse_ticket_order_entry_session_v53(uuid, uuid, uuid, text, text, text, text)
CREATE FUNCTION public.reuse_ticket_order_entry_session_v53(p_order uuid, p_link uuid, p_session uuid, p_token text, p_environment text, p_origin text, p_account text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT jsonb_build_object('action',CASE WHEN public.read_ticket_order_entry_authority_v52(
 p_order,p_session,p_token,NULL,p_environment,p_origin,p_account)=p_link THEN 'reused' ELSE 'unauthenticated' END);
$$;

-- FUNCTION: revoke_ticket_admissions_v25(uuid, text, integer[], text, uuid)
CREATE FUNCTION public.revoke_ticket_admissions_v25(p_order_id uuid, p_environment text, p_admission_serials integer[], p_reason text, p_actor_admin_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order public.ticket_orders%ROWTYPE;
  v_serials integer[];
  v_selected integer;
  v_admitted integer;
  v_voided integer := 0;
BEGIN
  SELECT COALESCE(array_agg(serial ORDER BY serial), '{}'::integer[])
  INTO v_serials
  FROM unnest(COALESCE(p_admission_serials, '{}'::integer[])) AS serial;
  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL
    OR cardinality(v_serials) < 1 OR cardinality(v_serials) > 20
    OR EXISTS (SELECT 1 FROM unnest(v_serials) AS serial WHERE serial < 1 OR serial > 20)
    OR cardinality(v_serials) <>
       (SELECT count(DISTINCT serial) FROM unnest(v_serials) AS serial)
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'admission_selection_invalid');
  END IF;

  SELECT * INTO v_order FROM public.ticket_orders
  WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('action', 'not_found'); END IF;
  IF v_order.environment <> p_environment THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'environment_mismatch');
  END IF;
  -- See revoke_ticket_order_v24: this migration predates the v27 mode column,
  -- while its compatibility function remains callable at the expanded head.
  IF COALESCE(to_jsonb(v_order) ->> 'check_in_mode', 'legacy_qr') = 'wallet_swipe' THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'reason', 'wallet_swipe_requires_versioned_manager_action');
  END IF;

  PERFORM 1 FROM public.ticket_admissions AS admission
  WHERE admission.ticket_order_id = v_order.id
    AND admission.serial = ANY(v_serials)
  ORDER BY admission.serial FOR UPDATE;
  SELECT count(*), count(*) FILTER (WHERE status = 'admitted')
  INTO v_selected, v_admitted
  FROM public.ticket_admissions
  WHERE ticket_order_id = v_order.id AND serial = ANY(v_serials);
  IF v_selected <> cardinality(v_serials) THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'admission_not_found');
  END IF;
  IF v_admitted > 0 THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'admission_already_admitted');
  END IF;

  UPDATE public.ticket_admissions
  SET status = 'void', voided_at = now(), void_reason = left(p_reason, 240)
  WHERE ticket_order_id = v_order.id
    AND serial = ANY(v_serials) AND status = 'issued';
  GET DIAGNOSTICS v_voided = ROW_COUNT;
  IF v_voided > 0 THEN
    INSERT INTO public.audit_logs(
      action, actor_type, actor_admin_id, target_table, target_id,
      entity_type, entity_id, operation, reason, metadata_json
    ) VALUES (
      'ticket_admission.revoke',
      CASE WHEN p_actor_admin_id IS NULL THEN 'system' ELSE 'admin' END,
      p_actor_admin_id, 'ticket_orders', v_order.id,
      'ticket_order', v_order.id, 'update', left(p_reason, 240),
      jsonb_build_object('admissionSerials', to_jsonb(v_serials), 'voided', v_voided)
    );
  END IF;

  RETURN jsonb_build_object(
    'action', CASE WHEN v_voided > 0 THEN 'revoked' ELSE 'reused' END,
    'orderId', v_order.id, 'publicCode', v_order.public_code,
    'admissionSerials', to_jsonb(v_serials), 'voided', v_voided
  );
END;
$$;

-- FUNCTION: revoke_ticket_checkout_payment_v28(uuid, uuid, uuid, text, text, text, text, text, text, text, text, timestamp with time zone, text, text)
CREATE FUNCTION public.revoke_ticket_checkout_payment_v28(p_ticket_order_id uuid, p_provider_checkout_action_id uuid, p_provider_event_session_id uuid, p_provider_check_in_mode text, p_environment text, p_stripe_account_id text, p_checkout_session_id text, p_client_reference_id text, p_payment_intent_id text, p_provider_flow text, p_provider_response_hash text, p_provider_expires_at timestamp with time zone, p_revocation_kind text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_binding jsonb;
  v_order public.ticket_orders%ROWTYPE;
  v_hold_active boolean := true;
  v_dispute_id text;
BEGIN
  IF COALESCE(p_revocation_kind, '') NOT IN ('charge_refunded', 'dispute')
    OR NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'revocation_input_invalid');
  END IF;

  v_binding := public.bind_verified_ticket_checkout_payment_v28(
    p_ticket_order_id, p_provider_checkout_action_id,
    p_provider_event_session_id, p_provider_check_in_mode,
    p_environment, p_stripe_account_id,
    p_checkout_session_id, p_client_reference_id, p_payment_intent_id,
    p_provider_flow, p_provider_response_hash, p_provider_expires_at);
  IF v_binding ->> 'action' NOT IN ('bound', 'reused') THEN
    RETURN v_binding;
  END IF;

  -- [W06-G08] Terminal-state recheck under the order lock that
  -- bind_verified_ticket_checkout_payment_v28 already took in this
  -- transaction. A dispute recorded 'won' by resolve_ticket_dispute_closed_v1
  -- can never open a hold, even when charge.dispute.created is delivered or
  -- claimed after charge.dispute.closed. A 'lost' record keeps applying the
  -- hold — the chargeback is final.
  IF p_revocation_kind = 'dispute' THEN
    v_dispute_id := substring(btrim(p_reason) from 'stripe_dispute_opened:(.+)');
    IF v_dispute_id IS NOT NULL AND EXISTS (
      SELECT 1
      FROM public.stripe_object_states AS state
      WHERE state.environment = p_environment
        AND state.stripe_account_key = COALESCE(p_stripe_account_id, 'platform')
        AND state.object_type = 'dispute'
        AND state.object_id = v_dispute_id
        AND state.stripe_status = 'won'
    ) THEN
      INSERT INTO public.audit_logs(
        action, actor_type, target_table, target_id,
        entity_type, entity_id, operation, reason, metadata_json
      ) VALUES (
        'ticket_checkout.payment_hold_skipped', 'system', 'ticket_orders',
        (v_binding ->> 'orderId')::uuid,
        'ticket_order', (v_binding ->> 'orderId')::uuid, 'update',
        'stripe_dispute_already_won',
        jsonb_build_object('disputeId', v_dispute_id,
                           'checkoutActionId', v_binding ->> 'checkoutActionId')
      );
      RETURN jsonb_build_object(
        'action', 'reused', 'reason', 'dispute_already_won',
        'orderId', (v_binding ->> 'orderId')::uuid,
        'checkoutActionId', (v_binding ->> 'checkoutActionId')::uuid,
        'revocationKind', p_revocation_kind, 'voided', 0);
    END IF;
  END IF;

  -- Do not generically void admissions here. charge.refunded is a coarse
  -- payment hold until its Refund objects produce normalized allocations;
  -- dispute is a reversible provider-risk hold. Admission and fulfillment
  -- read this order fact under the same Order lock.
  UPDATE public.ticket_orders
  SET status = CASE
        WHEN p_revocation_kind = 'charge_refunded'
          AND status IN ('pending', 'paid', 'fulfilled') THEN 'refunded'
        ELSE status
      END,
      cancelled_at = CASE WHEN p_revocation_kind = 'charge_refunded'
        THEN COALESCE(cancelled_at, now()) ELSE cancelled_at END,
      payment_hold_reason = CASE WHEN p_revocation_kind = 'charge_refunded'
        THEN 'charge_refunded' ELSE 'payment_dispute_open' END,
      payment_hold_at = now()
  WHERE id = p_ticket_order_id
  RETURNING * INTO v_order;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'verified payment hold failed after binding';
  END IF;

  IF p_revocation_kind = 'charge_refunded'
    AND (
      SELECT COALESCE(sum(allocation.amount_yen), 0)
      FROM public.ticket_refund_allocations AS allocation
      WHERE allocation.ticket_order_id = v_order.id
    ) >= v_order.amount_yen
    AND NOT EXISTS (
      SELECT 1 FROM public.ticket_refund_events AS refund
      WHERE refund.ticket_order_id = v_order.id
        AND refund.money_may_have_moved
        AND refund.resolution_status IN ('review_required', 'conflict_review')
        AND refund.resolved_at IS NULL
    )
  THEN
    UPDATE public.ticket_orders
    SET payment_hold_reason = NULL, payment_hold_at = NULL
    WHERE id = v_order.id
    RETURNING * INTO v_order;
    v_hold_active := false;
  END IF;

  UPDATE public.ticket_checkout_actions
  SET state = CASE WHEN v_hold_active THEN 'review_required'
        WHEN completed_at IS NOT NULL THEN 'completed' ELSE 'provider_created' END,
      review_reason = CASE WHEN v_hold_active
        THEN CASE WHEN p_revocation_kind = 'charge_refunded'
          THEN 'charge_refunded' ELSE 'payment_dispute_open' END
        ELSE NULL END,
      updated_at = now()
  WHERE id = (v_binding ->> 'checkoutActionId')::uuid;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'verified payment action hold failed after binding';
  END IF;

  INSERT INTO public.audit_logs(
    action, actor_type, target_table, target_id,
    entity_type, entity_id, operation, reason, metadata_json
  ) VALUES (
    'ticket_checkout.payment_hold', 'system', 'ticket_orders', v_order.id,
    'ticket_order', v_order.id, 'update', left(btrim(p_reason), 240),
    jsonb_build_object('revocationKind', p_revocation_kind,
                       'paymentHoldActive', v_hold_active,
                       'checkoutActionId', v_binding ->> 'checkoutActionId')
  );

  RETURN jsonb_build_object(
    'action', CASE WHEN v_hold_active THEN 'held' ELSE 'reused' END,
    'orderId', v_order.id, 'publicCode', v_order.public_code,
    'orderStatus', v_order.status, 'voided', 0,
    'checkoutActionId', v_binding ->> 'checkoutActionId',
    'revocationKind', p_revocation_kind,
    'paymentHoldReason', v_order.payment_hold_reason);
END;
$$;

-- FUNCTION: revoke_ticket_order_v24(uuid, text, text, boolean, uuid)
CREATE FUNCTION public.revoke_ticket_order_v24(p_order_id uuid, p_environment text, p_reason text, p_set_order_refunded boolean, p_actor_admin_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_order public.ticket_orders%ROWTYPE;
  v_voided integer := 0;
  v_already_admitted integer := 0;
  v_already_void integer := 0;
  v_dispute_id text;
BEGIN
  IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'revocation_reason_required');
  END IF;
  SELECT * INTO v_order FROM public.ticket_orders
  WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('action', 'not_found'); END IF;
  IF v_order.environment <> p_environment THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'environment_mismatch');
  END IF;
  -- v26 is installed before v27 adds check_in_mode, so inspect the row as JSON
  -- to keep this compatibility RPC callable at both schema heads. Wallet orders
  -- require the versioned manager/refund lanes and must never reach this legacy
  -- non-CAS mutation.
  IF COALESCE(to_jsonb(v_order) ->> 'check_in_mode', 'legacy_qr') = 'wallet_swipe' THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'reason', 'wallet_swipe_requires_versioned_manager_action');
  END IF;

  -- [W06-G08] Terminal-state recheck under the order lock taken above. A
  -- dispute recorded 'won' can never void admissions, even when its
  -- charge.dispute.created is delivered or claimed after
  -- charge.dispute.closed. Refund/operator reasons never match the
  -- stripe_dispute_opened pattern, so their behaviour is unchanged.
  v_dispute_id := substring(p_reason from 'stripe_dispute_opened:(.+)');
  IF v_dispute_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.stripe_object_states AS state
    WHERE state.environment = p_environment
      AND state.stripe_account_key = v_order.stripe_account_key
      AND state.object_type = 'dispute'
      AND state.object_id = v_dispute_id
      AND state.stripe_status = 'won'
  ) THEN
    INSERT INTO public.audit_logs(
      action, actor_type, target_table, target_id,
      entity_type, entity_id, operation, reason, metadata_json
    ) VALUES (
      'ticket_order.revoke_skipped', 'system', 'ticket_orders', v_order.id,
      'ticket_order', v_order.id, 'update', 'stripe_dispute_already_won',
      jsonb_build_object('disputeId', v_dispute_id)
    );
    RETURN jsonb_build_object(
      'action', 'reused', 'reason', 'dispute_already_won',
      'orderId', v_order.id, 'publicCode', v_order.public_code,
      'orderStatus', v_order.status, 'voided', 0);
  END IF;

  PERFORM 1 FROM public.ticket_admissions AS admission
  WHERE admission.ticket_order_id = v_order.id
  ORDER BY admission.serial FOR UPDATE;
  SELECT count(*) FILTER (WHERE status = 'admitted'),
         count(*) FILTER (WHERE status = 'void')
  INTO v_already_admitted, v_already_void
  FROM public.ticket_admissions WHERE ticket_order_id = v_order.id;

  UPDATE public.ticket_admissions
  SET status = 'void', voided_at = now(), void_reason = left(p_reason, 240)
  WHERE ticket_order_id = v_order.id AND status = 'issued';
  GET DIAGNOSTICS v_voided = ROW_COUNT;

  IF p_set_order_refunded AND v_order.status IN ('pending', 'paid', 'fulfilled') THEN
    UPDATE public.ticket_orders
    SET status = 'refunded', cancelled_at = COALESCE(cancelled_at, now())
    WHERE id = v_order.id RETURNING * INTO v_order;
  END IF;

  IF p_actor_admin_id IS NOT NULL OR v_voided > 0 THEN
    INSERT INTO public.audit_logs(
      action, actor_type, actor_admin_id, target_table, target_id,
      entity_type, entity_id, operation, reason
    ) VALUES (
      'ticket_order.revoke',
      CASE WHEN p_actor_admin_id IS NULL THEN 'system' ELSE 'admin' END,
      p_actor_admin_id, 'ticket_orders', v_order.id,
      'ticket_order', v_order.id, 'update', left(p_reason, 240)
    );
  END IF;

  RETURN jsonb_build_object(
    'action', CASE WHEN v_voided > 0 THEN 'revoked' ELSE 'reused' END,
    'orderId', v_order.id, 'publicCode', v_order.public_code,
    'orderStatus', v_order.status, 'voided', v_voided,
    'alreadyVoid', v_already_void, 'alreadyAdmitted', v_already_admitted
  );
END;
$$;

-- FUNCTION: revoke_ticket_wallet_credentials_v34(uuid, text, text, text, boolean)
CREATE FUNCTION public.revoke_ticket_wallet_credentials_v34(p_session_id uuid, p_token text, p_csrf text, p_credential_id text, p_recover_all boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s public.ticket_wallet_sessions%ROWTYPE; at timestamptz:=clock_timestamp(); n integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('ticket-passkey-transition-v34',0));
 PERFORM public.ticket_wallet_gate_fence_v30();
 SELECT * INTO s FROM public.ticket_wallet_sessions WHERE id=p_session_id FOR UPDATE;
 IF NOT FOUND OR s.revoked_at IS NOT NULL OR s.expires_at<=at OR s.verified_at<at-interval '5 minutes'
 OR NOT public.ticket_auth_digest_equal_v29(s.token_verifier,p_token) OR NOT public.ticket_auth_digest_equal_v29(s.csrf_verifier,p_csrf)
 OR (p_recover_all AND s.auth_method<>'email_otp') THEN RETURN jsonb_build_object('action','rejected'); END IF;
 UPDATE public.ticket_wallet_credentials SET revoked_at=at WHERE holder_id=s.holder_id AND revoked_at IS NULL AND (p_recover_all OR id=p_credential_id);
 GET DIAGNOSTICS n=ROW_COUNT;
 UPDATE public.ticket_wallet_sessions SET revoked_at=at,revocation_reason='security_response',token_verifier=NULL,csrf_verifier=NULL,updated_at=at
 WHERE holder_id=s.holder_id AND revoked_at IS NULL AND ((p_recover_all AND id<>s.id) OR credential_id IN(SELECT id FROM public.ticket_wallet_credentials WHERE holder_id=s.holder_id AND revoked_at IS NOT NULL));
 UPDATE public.ticket_wallet_passkey_challenges SET consumed_at=at WHERE holder_id=s.holder_id AND consumed_at IS NULL;
 INSERT INTO public.ticket_wallet_credential_audits(holder_id,session_id,action) VALUES(s.holder_id,s.id,CASE WHEN p_recover_all THEN 'credentials_recovered' ELSE 'credential_revoked' END);
 RETURN jsonb_build_object('action','revoked','count',n);
END; $$;

-- FUNCTION: revoke_ticket_wallet_session_v29(text, timestamp with time zone, uuid, text, text, text)
CREATE FUNCTION public.revoke_ticket_wallet_session_v29(p_environment text, p_now timestamp with time zone, p_session_id uuid, p_session_token_verifier text, p_session_csrf_verifier text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_session public.ticket_wallet_sessions%ROWTYPE;
BEGIN
  IF p_environment NOT IN ('test', 'live') OR p_session_id IS NULL
    OR p_now IS NULL OR abs(extract(epoch FROM (p_now - v_now))) > 300
    OR p_reason <> 'customer_logout'
  THEN
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;
  SELECT * INTO v_session
  FROM public.ticket_wallet_sessions
  WHERE id = p_session_id AND environment = p_environment
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;
  IF v_session.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('action', 'reused');
  END IF;
  IF NOT public.ticket_auth_digest_equal_v29(v_session.token_verifier, p_session_token_verifier)
    OR NOT public.ticket_auth_digest_equal_v29(v_session.csrf_verifier, p_session_csrf_verifier)
  THEN
    RETURN jsonb_build_object('action', 'unauthenticated');
  END IF;
  UPDATE public.ticket_wallet_sessions
  SET revoked_at = v_now, revocation_reason = p_reason,
      token_verifier = NULL, csrf_verifier = NULL, updated_at = v_now
  WHERE id = v_session.id;
  RETURN jsonb_build_object('action', 'revoked');
END;
$$;

-- FUNCTION: seal_ticket_checkout_provider_request_v28(uuid, text, text, text, timestamp with time zone, text)
CREATE FUNCTION public.seal_ticket_checkout_provider_request_v28(p_checkout_action_id uuid, p_request_hash text, p_provider_request_version text, p_provider_request_origin text, p_provider_request_created_at timestamp with time zone, p_provider_request_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_action public.ticket_checkout_actions%ROWTYPE;
  v_order_id uuid;
BEGIN
  IF p_checkout_action_id IS NULL
    OR NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL
    OR p_provider_request_version <> 'ghost.ticket-checkout-provider.v28'
    OR NULLIF(btrim(COALESCE(p_provider_request_origin, '')), '') IS NULL
    OR char_length(p_provider_request_origin) > 512
    OR (
      p_provider_request_origin !~ '^https://[^/?#]+$'
      AND p_provider_request_origin !~
        '^http://(localhost|127[.]0[.]0[.]1|\[::1\])(:[0-9]+)?$'
    )
    OR p_provider_request_created_at IS NULL
    OR p_provider_request_created_at > clock_timestamp() + interval '5 minutes'
    OR COALESCE(p_provider_request_hash, '') !~ '^[0-9a-f]{64}$'
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'provider_request_seal_invalid');
  END IF;

  SELECT * INTO v_action
  FROM public.ticket_checkout_actions
  WHERE id = p_checkout_action_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('action', 'not_found'); END IF;

  SELECT id INTO v_order_id
  FROM public.ticket_orders
  WHERE id = v_action.ticket_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'checkout_order_missing');
  END IF;
  IF v_action.request_hash <> btrim(p_request_hash)
    OR v_action.state <> 'claimed'
    OR v_action.checkout_session_id IS NOT NULL
    OR p_provider_request_created_at < v_action.created_at - interval '30 minutes'
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'provider_request_state_mismatch');
  END IF;

  IF v_action.provider_request_version IS NOT NULL THEN
    IF v_action.provider_request_version = p_provider_request_version
      AND v_action.provider_request_origin = p_provider_request_origin
      AND v_action.provider_request_created_at = p_provider_request_created_at
      AND v_action.provider_request_hash = p_provider_request_hash
    THEN
      RETURN jsonb_build_object(
        'action', 'reused',
        'providerRequestVersion', v_action.provider_request_version,
        'providerRequestOrigin', v_action.provider_request_origin,
        'providerRequestCreatedAt', to_char(
          v_action.provider_request_created_at AT TIME ZONE 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
        'providerRequestHash', v_action.provider_request_hash);
    END IF;
    RETURN jsonb_build_object('action', 'conflict', 'reason', 'provider_request_seal_mismatch');
  END IF;

  UPDATE public.ticket_checkout_actions
  SET provider_request_version = p_provider_request_version,
      provider_request_origin = p_provider_request_origin,
      provider_request_created_at = p_provider_request_created_at,
      provider_request_hash = p_provider_request_hash,
      updated_at = now()
  WHERE id = v_action.id
  RETURNING * INTO v_action;

  RETURN jsonb_build_object(
    'action', 'sealed',
    'providerRequestVersion', v_action.provider_request_version,
    'providerRequestOrigin', v_action.provider_request_origin,
    'providerRequestCreatedAt', to_char(
      v_action.provider_request_created_at AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'providerRequestHash', v_action.provider_request_hash);
END;
$_$;

-- FUNCTION: search_ticket_orders_v37(uuid, text, text, text, date, date, text, timestamp with time zone, uuid)
CREATE FUNCTION public.search_ticket_orders_v37(p_actor_admin_id uuid, p_request_id text, p_environment text, p_email_hash text, p_from date, p_through date, p_reason text, p_cursor_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE rows jsonb; result jsonb; next_cursor jsonb; audit uuid; more boolean;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.admin_users WHERE id=p_actor_admin_id AND active AND role='owner') THEN RETURN jsonb_build_object('action','forbidden'); END IF;
 IF p_environment NOT IN ('live','test') OR p_email_hash IS NULL OR p_email_hash !~ '^[0-9a-f]{64}$' OR p_from IS NULL OR p_through IS NULL OR p_through<p_from OR p_through-p_from>366 OR p_reason NOT IN ('email_not_received','order_code_unknown','reconciliation') OR (p_cursor_id IS NULL)<>(p_cursor_created_at IS NULL) THEN RETURN jsonb_build_object('action','rejected'); END IF;
 IF NOT public.consume_ticket_wallet_rate_limit_v29('manager_search_60s',p_actor_admin_id::text,60,30) THEN RETURN jsonb_build_object('action','rate_limited'); END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(r)),'[]'::jsonb) INTO rows FROM (
 SELECT id,created_at,public_code AS "publicCode",event_date AS "eventDate",event_title AS "eventTitle",status,total_quantity AS quantity
 FROM public.ticket_orders WHERE environment=p_environment AND purchaser_email_hash=p_email_hash AND event_date BETWEEN p_from AND p_through
 AND (p_cursor_id IS NULL OR (created_at,id)<(p_cursor_created_at,p_cursor_id))
 ORDER BY created_at DESC,id DESC LIMIT 26) r;
 more:=jsonb_array_length(rows)>25;
 SELECT COALESCE(jsonb_agg(value-'id'-'created_at' ORDER BY n),'[]'::jsonb) INTO result FROM jsonb_array_elements(rows) WITH ORDINALITY r(value,n) WHERE n<=25;
 IF more THEN next_cursor:=jsonb_build_object('id',rows->24->>'id','createdAt',rows->24->>'created_at'); END IF;
 INSERT INTO public.ticket_manager_search_audits(actor_admin_id,request_id,reason,date_from,date_through,result_count) VALUES(p_actor_admin_id,p_request_id,p_reason,p_from,p_through,jsonb_array_length(result)) RETURNING id INTO audit;
 RETURN jsonb_build_object('ok',true,'orders',result,'hasMore',more,'nextCursor',next_cursor,'auditId',audit);
END; $_$;

-- FUNCTION: seat_admin_waitlist_entry_v21(uuid, text, text, text, uuid, bigint, text, uuid, text)
CREATE FUNCTION public.seat_admin_waitlist_entry_v21(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_waitlist_entry_id uuid, p_expected_version bigint, p_to_status text, p_seated_reservation_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_entry public.vip_waitlist_entries%ROWTYPE;
  v_reservation public.reservations%ROWTYPE;
  v_occurred_at timestamptz := clock_timestamp();
  v_step jsonb;
  v_response jsonb;
  v_service_result jsonb;
  v_waitlist_result jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, 'waitlist.seated', p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;

    IF lower(btrim(COALESCE(p_to_status, ''))) <> 'seated'
      OR p_seated_reservation_id IS NULL THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object('field', 'waitlistSeating')
      )), ARRAY['allowed']);
    END IF;

    SELECT * INTO v_entry
    FROM public.vip_waitlist_entries
    WHERE id = p_waitlist_entry_id
    FOR UPDATE;
    IF NOT FOUND OR v_entry.status <> 'called' OR v_entry.version <> p_expected_version THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
        'code', CASE WHEN NOT FOUND THEN 'NOT_FOUND'
          WHEN v_entry.version <> p_expected_version THEN 'VERSION_CONFLICT'
          ELSE 'INVALID_STATE_TRANSITION' END,
        'details', jsonb_build_object('entityType', 'waitlist')
      )), ARRAY['allowed']);
    END IF;

    SELECT * INTO v_reservation
    FROM public.reservations
    WHERE id = p_seated_reservation_id
      AND event_day_id = v_entry.event_day_id
      AND status = 'confirmed'
    FOR UPDATE;
    IF NOT FOUND THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
        'code', 'NOT_FOUND',
        'details', jsonb_build_object('entityType', 'confirmedReservation')
      )), ARRAY['allowed']);
    END IF;

    PERFORM sr.id
    FROM public.reservation_resources AS rr
    JOIN public.seat_resources AS sr ON sr.id = rr.seat_resource_id
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, v_occurred_at)
    ORDER BY sr.id
    FOR UPDATE OF sr;
    IF NOT FOUND THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
        'code', 'INVALID_STATE_TRANSITION',
        'details', jsonb_build_object('reason', 'active_table_assignment_required')
      )), ARRAY['allowed']);
    END IF;

    IF v_reservation.service_status IS DISTINCT FROM 'seated'::public.vip_service_status THEN
      v_service_result := public.set_admin_reservation_service_status_v8(
        p_actor_admin_id,
        p_request_id || ':waitlist-service',
        'waitlist-seat-service:' || encode(digest(p_idempotency_key, 'sha256'), 'hex'),
        encode(digest(p_request_hash || ':waitlist-service', 'sha256'), 'hex'),
        v_reservation.id,
        v_reservation.version,
        'seated'::public.vip_service_status,
        v_occurred_at,
        p_reason
      );
      PERFORM public.assert_vip_floor_helper_success_v8(v_service_result, ARRAY[
        'reservation.service_status.updated'
      ]);
    END IF;

    v_waitlist_result := public.transition_claimed_waitlist_entry_v32(
      p_actor_admin_id,
      p_request_id,
      p_idempotency_key,
      p_request_hash,
      p_waitlist_entry_id,
      p_expected_version,
      'seated',
      p_seated_reservation_id,
      p_reason
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_waitlist_result, ARRAY[
      'waitlist.seated'
    ]);

    v_response := v_waitlist_result || jsonb_build_object(
      'reservationId', v_reservation.id,
      'serviceStatus', 'seated',
      'seatedAt', v_occurred_at,
      'serviceTransition', v_service_result
    );
    UPDATE public.admin_action_requests
    SET response_json = v_response, updated_at = now()
    WHERE actor_admin_id = p_actor_admin_id
      AND action = 'waitlist.seated'
      AND idempotency_key = btrim(p_idempotency_key)
      AND request_hash = btrim(p_request_hash)
      AND response_json IS NOT NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'v32 seating response completion disappeared';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: seat_resource_satisfies_offering_requirement_v7(uuid, uuid)
CREATE FUNCTION public.seat_resource_satisfies_offering_requirement_v7(p_booking_offering_id uuid, p_seat_resource_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    CASE
      WHEN NOT EXISTS (
        SELECT 1
        FROM offering_resource_requirements req
        WHERE req.booking_offering_id = p_booking_offering_id
      ) THEN true
      ELSE EXISTS (
        SELECT 1
        FROM offering_resource_requirements req
        LEFT JOIN resource_group_members rgm
          ON rgm.resource_group_id = req.resource_group_id
        WHERE req.booking_offering_id = p_booking_offering_id
          AND (
            req.seat_resource_id = p_seat_resource_id
            OR rgm.seat_resource_id = p_seat_resource_id
          )
      )
    END;
$$;

