-- FUNCTION: set_admin_pin_v7(text, text, text, text, text)
CREATE FUNCTION public.set_admin_pin_v7(p_email_hash text, p_display_name text, p_role text, p_pin text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_admin admin_users%ROWTYPE;
  v_credential admin_pin_credentials%ROWTYPE;
  v_pin_salt text;
  v_pin_hash text;
BEGIN
  IF p_email_hash IS NULL OR length(p_email_hash) < 32 THEN
    RAISE EXCEPTION 'invalid admin email hash';
  END IF;

  IF p_role NOT IN ('staff','manager','owner','engineer','accountant') THEN
    RAISE EXCEPTION 'invalid admin role';
  END IF;

  IF p_pin IS NULL OR p_pin !~ '^[0-9]{4,8}$' THEN
    RAISE EXCEPTION 'invalid admin pin';
  END IF;

  SELECT * INTO v_admin
  FROM admin_users
  WHERE email_hash = p_email_hash
  FOR UPDATE;

  IF FOUND THEN
    UPDATE admin_users
    SET display_name = COALESCE(p_display_name, display_name),
        role = p_role,
        active = true,
        updated_at = now()
    WHERE id = v_admin.id
    RETURNING * INTO v_admin;
  ELSE
    INSERT INTO admin_users(email_hash, display_name, role, active)
    VALUES (p_email_hash, p_display_name, p_role, true)
    RETURNING * INTO v_admin;
  END IF;

  FOR v_credential IN
    SELECT c.*
    FROM admin_pin_credentials c
    JOIN admin_users a ON a.id = c.admin_user_id
    WHERE c.admin_user_id <> v_admin.id
      AND c.active = true
      AND a.active = true
  LOOP
    IF admin_constant_time_text_equal_v7(
      admin_pin_hash_v7(v_credential.pin_salt, p_pin),
      v_credential.pin_hash
    ) THEN
      RAISE EXCEPTION 'duplicate admin pin';
    END IF;
  END LOOP;

  v_pin_salt := encode(gen_random_bytes(16), 'hex');
  v_pin_hash := admin_pin_hash_v7(v_pin_salt, p_pin);

  INSERT INTO admin_pin_credentials(
    admin_user_id,
    pin_salt,
    pin_hash,
    active,
    failed_attempt_count,
    locked_until
  )
  VALUES (v_admin.id, v_pin_salt, v_pin_hash, true, 0, NULL)
  ON CONFLICT (admin_user_id)
  DO UPDATE
  SET pin_salt = EXCLUDED.pin_salt,
      pin_hash = EXCLUDED.pin_hash,
      active = true,
      attempt_window_started_at = NULL,
      attempt_count = 0,
      failed_attempt_count = 0,
      locked_until = NULL,
      updated_at = now()
  RETURNING * INTO v_credential;

  INSERT INTO audit_logs(
    actor_admin_id,
    actor_type,
    action,
    target_table,
    target_id,
    request_id,
    after_json
  )
  VALUES (
    v_admin.id,
    'admin',
    'admin_pin.set',
    'admin_pin_credentials',
    v_credential.id,
    p_request_id,
    jsonb_build_object('role', v_admin.role)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'adminId', v_admin.id,
    'role', v_admin.role,
    'displayName', v_admin.display_name,
    'pinSetAt', now()
  );
END;
$_$;

-- FUNCTION: set_admin_reservation_arrival_time_v9(uuid, text, text, text, uuid, bigint, timestamp with time zone, text)
CREATE FUNCTION public.set_admin_reservation_arrival_time_v9(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_version bigint, p_arrived_at timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation.arrival_time.updated';
  v_step jsonb;
  v_reservation public.reservations%ROWTYPE;
  v_new_version bigint;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id,
      v_action,
      p_idempotency_key,
      p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN
      RETURN v_step;
    END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;

    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(
        p_actor_admin_id,
        'service_status.write'
      ),
      ARRAY['allowed']
    );

    IF NOT EXISTS (
      SELECT 1
      FROM public.admin_users
      WHERE id = p_actor_admin_id
        AND active = true
        AND role = 'owner'
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'FORBIDDEN',
            'details', jsonb_build_object('capability', 'owner')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_arrived_at IS NULL
      OR p_reason IS DISTINCT FROM '管理画面操作'
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object(
              'field',
              CASE
                WHEN NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
                  THEN 'requestId'
                WHEN p_arrived_at IS NULL
                  THEN 'arrivedAt'
                ELSE 'reason'
              END
            )
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    v_step := public.assert_reservation_version_v8(
      p_reservation_id,
      p_expected_version
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);

    SELECT *
    INTO v_reservation
    FROM public.reservations
    WHERE id = p_reservation_id;

    IF v_reservation.arrived_at IS NULL
      OR v_reservation.service_status IS NULL
      OR v_reservation.service_status IN (
        'expected',
        'late',
        'no_contact',
        'no_show',
        'completed'
      )
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_STATE_TRANSITION',
            'details', jsonb_build_object(
              'reason', 'arrival_time_not_editable',
              'fromStatus', v_reservation.service_status
            )
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    v_step := public.resolve_business_day_for_timestamp_v8(p_arrived_at);
    PERFORM public.assert_vip_floor_helper_success_v8(
      v_step,
      ARRAY['resolved']
    );

    IF (v_step ->> 'eventDayId')::uuid <> v_reservation.event_day_id THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object(
              'field', 'arrivedAt',
              'reason', 'business_day_mismatch'
            )
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    UPDATE public.reservations
    SET arrived_at = p_arrived_at,
        version = version + 1,
        updated_at = now()
    WHERE id = v_reservation.id
    RETURNING version INTO v_new_version;

    PERFORM ed.id
    FROM public.event_days AS ed
    WHERE ed.id = v_reservation.event_day_id
    FOR KEY SHARE OF ed;

    PERFORM public.lock_vip_floor_day_revision_v32(v_reservation.event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1
    INTO v_predicted_revision
    FROM (SELECT 1) AS seed
    LEFT JOIN public.vip_floor_day_revisions AS vfr
      ON vfr.event_day_id = v_reservation.event_day_id;

    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id,
      v_reservation.event_day_id,
      v_reservation.id,
      'reservation',
      v_reservation.id,
      v_action,
      p_request_id,
      p_reason,
      p_expected_version,
      v_reservation.version,
      v_new_version,
      ARRAY['arrived_at', 'version'],
      jsonb_build_object(
        'arrivedAt', v_reservation.arrived_at,
        'version', v_reservation.version
      ),
      jsonb_build_object(
        'arrivedAt', p_arrived_at,
        'version', v_new_version
      ),
      '{}'::jsonb
    );
    PERFORM public.assert_vip_floor_helper_success_v8(
      v_step,
      ARRAY['appended']
    );
    v_audit_id := (v_step ->> 'auditLogId')::uuid;

    v_response := jsonb_build_object(
      'ok', true,
      'action', v_action,
      'reused', false,
      'reservationId', v_reservation.id,
      'entityVersion', v_new_version,
      'boardRevision', v_predicted_revision,
      'auditLogId', v_audit_id,
      'arrivedAt', p_arrived_at
    );

    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id,
      v_action,
      p_idempotency_key,
      v_response
    );

    v_step := public.bump_vip_floor_day_revision_v8(
      v_reservation.event_day_id,
      v_audit_id
    );
    PERFORM public.assert_vip_floor_helper_success_v8(
      v_step,
      ARRAY['bumped']
    );
    v_revision := (v_step ->> 'revision')::bigint;

    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING
        ERRCODE = 'XX000',
        MESSAGE = 'VIP floor revision prediction diverged';
    END IF;

    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: set_admin_reservation_schedule_v8(uuid, text, text, text, uuid, bigint, timestamp with time zone, timestamp with time zone, text)
CREATE FUNCTION public.set_admin_reservation_schedule_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_version bigint, p_scheduled_start_at timestamp with time zone, p_scheduled_end_at timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation.schedule.updated';
  v_step jsonb;
  v_reservation public.reservations%ROWTYPE;
  v_assignment record;
  v_new_release_at timestamptz;
  v_new_version bigint;
  v_audit_id uuid;
  v_revision bigint;
  v_predicted_revision bigint;
  v_warnings jsonb := '[]'::jsonb;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;

    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(p_actor_admin_id, 'reservation_schedule.write'),
      ARRAY['allowed']
    );
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_scheduled_start_at IS NULL
      OR p_scheduled_end_at IS NULL
      OR p_scheduled_start_at >= p_scheduled_end_at
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object(
              'field', CASE
                WHEN NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL THEN 'requestId'
                ELSE 'schedule'
              END
            )
          )
        ), ARRAY['allowed']
      );
    END IF;

    v_step := public.assert_reservation_version_v8(p_reservation_id, p_expected_version);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
    SELECT * INTO v_reservation
    FROM public.reservations
    WHERE id = p_reservation_id;

    IF v_reservation.status IN ('cancelled', 'hold_expired', 'payment_window_expired', 'failed')
      OR v_reservation.service_status IN ('completed', 'no_show')
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION',
          'details', jsonb_build_object('reason', 'reservation_terminal')
        )), ARRAY['allowed']
      );
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.event_days AS ed
      WHERE ed.id = v_reservation.event_day_id
        AND ed.sales_open_at <= p_scheduled_start_at
        AND ed.sales_close_at >= p_scheduled_end_at
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'schedule', 'reason', 'outside_business_day')
          )
        ), ARRAY['allowed']
      );
    END IF;

    v_new_release_at := CASE
      WHEN v_reservation.expected_release_at > v_reservation.scheduled_end_at
        THEN p_scheduled_end_at
          + (v_reservation.expected_release_at - v_reservation.scheduled_end_at)
      ELSE p_scheduled_end_at
    END;

    -- Existing seats, then relation rows, are locked in stable UUID order.
    PERFORM sr.id
    FROM public.seat_resources AS sr
    WHERE EXISTS (
      SELECT 1 FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id
        AND rr.seat_resource_id = sr.id
        AND rr.released_at IS NULL
        AND rr.lock_status IN ('held', 'payment_grace_locked', 'confirmed')
    )
    ORDER BY sr.id
    FOR UPDATE OF sr;

    PERFORM rr.id
    FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
       OR (
         rr.seat_resource_id IN (
           SELECT current_rr.seat_resource_id
           FROM public.reservation_resources AS current_rr
           WHERE current_rr.reservation_id = v_reservation.id
             AND public.active_reservation_assignment_v8(current_rr.id, now())
         )
         AND rr.assigned_start_at < v_new_release_at
         AND rr.assigned_end_at > p_scheduled_start_at
       )
    ORDER BY rr.id
    FOR UPDATE OF rr;

    PERFORM rb.id
    FROM public.reservation_blocks AS rb
    WHERE rb.event_day_id = v_reservation.event_day_id
      AND rb.status = 'active'
      AND rb.start_at < v_new_release_at
      AND rb.end_at > p_scheduled_start_at
      AND EXISTS (
        SELECT 1
        FROM public.reservation_block_targets AS rbt
        JOIN public.reservation_resources AS rr
          ON rr.reservation_id = v_reservation.id
        JOIN public.seat_resources AS sr
          ON sr.id = rr.seat_resource_id
        WHERE rbt.block_id = rb.id
          AND (
            rbt.seat_resource_id = sr.id
            OR rbt.floor_section_id = sr.floor_section_id
            OR rbt.venue_wide
          )
      )
    ORDER BY rb.id
    FOR UPDATE OF rb;

    FOR v_assignment IN
      SELECT rr.*
      FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id
        AND public.active_reservation_assignment_v8(rr.id, now())
      ORDER BY rr.id
    LOOP
      v_step := public.assert_assignment_conflict_free_v8(
        v_reservation.event_day_id,
        v_reservation.id,
        v_assignment.seat_resource_id,
        p_scheduled_start_at,
        v_new_release_at,
        now()
      );
      PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
      SELECT COALESCE(jsonb_agg(warning ORDER BY warning::text), '[]'::jsonb)
      INTO v_warnings
      FROM (
        SELECT DISTINCT warning FROM jsonb_array_elements(
          v_warnings || COALESCE(v_step -> 'warnings', '[]'::jsonb)
        ) AS all_warnings(warning)
      ) AS deduplicated;
    END LOOP;

    IF (v_reservation.scheduled_start_at, v_reservation.scheduled_end_at, v_reservation.expected_release_at)
      IS NOT DISTINCT FROM (p_scheduled_start_at, p_scheduled_end_at, v_new_release_at)
      AND NOT EXISTS (
        SELECT 1 FROM public.reservation_resources AS rr
        WHERE rr.reservation_id = v_reservation.id
          AND public.active_reservation_assignment_v8(rr.id, now())
          AND (rr.assigned_start_at, rr.assigned_end_at)
            IS DISTINCT FROM (p_scheduled_start_at, v_new_release_at)
      )
    THEN
      PERFORM ed.id FROM public.event_days AS ed
      WHERE ed.id = v_reservation.event_day_id FOR KEY SHARE OF ed;
      PERFORM public.lock_vip_floor_day_revision_v32(v_reservation.event_day_id);
    SELECT COALESCE(vfr.revision, 0) INTO v_predicted_revision
      FROM (SELECT 1) AS seed
      LEFT JOIN public.vip_floor_day_revisions AS vfr
        ON vfr.event_day_id = v_reservation.event_day_id;
      v_step := public.append_vip_floor_audit_v8(
        p_actor_admin_id, v_reservation.event_day_id, v_reservation.id,
        'reservation', v_reservation.id, v_action || '.noop', p_request_id, p_reason,
        NULL, NULL, NULL, '{}'::text[],
        jsonb_build_object(
          'scheduledStartAt', v_reservation.scheduled_start_at,
          'scheduledEndAt', v_reservation.scheduled_end_at,
          'expectedReleaseAt', v_reservation.expected_release_at,
          'version', v_reservation.version
        ),
        jsonb_build_object(
          'scheduledStartAt', v_reservation.scheduled_start_at,
          'scheduledEndAt', v_reservation.scheduled_end_at,
          'expectedReleaseAt', v_reservation.expected_release_at,
          'version', v_reservation.version
        ),
        jsonb_build_object('warnings', v_warnings)
      );
      PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
      v_audit_id := (v_step ->> 'auditLogId')::uuid;
      v_response := jsonb_build_object(
        'ok', true, 'action', v_action, 'reused', false,
        'reservationId', v_reservation.id,
        'entityVersion', v_reservation.version,
        'boardRevision', v_predicted_revision,
        'auditLogId', v_audit_id,
        'scheduledStartAt', v_reservation.scheduled_start_at,
        'scheduledEndAt', v_reservation.scheduled_end_at,
        'expectedReleaseAt', v_reservation.expected_release_at,
        'warnings', v_warnings,
        'noOp', true
      );
      PERFORM public.complete_admin_action_request_v8(
        p_actor_admin_id, v_action, p_idempotency_key, v_response
      );
      RETURN v_response;
    END IF;

    INSERT INTO public.reservation_assignment_events(
      reservation_id, reservation_resource_id, seat_resource_id, event_type,
      interval_before, interval_after, actor_admin_id, reason, request_id
    )
    SELECT
      rr.reservation_id,
      rr.id,
      rr.seat_resource_id,
      'interval_changed',
      jsonb_build_object('startAt', rr.assigned_start_at, 'endAt', rr.assigned_end_at),
      jsonb_build_object('startAt', p_scheduled_start_at, 'endAt', v_new_release_at),
      p_actor_admin_id,
      p_reason,
      p_request_id
    FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now())
      AND (rr.assigned_start_at, rr.assigned_end_at)
        IS DISTINCT FROM (p_scheduled_start_at, v_new_release_at);

    UPDATE public.reservation_resources AS rr
    SET assigned_start_at = p_scheduled_start_at,
        assigned_end_at = v_new_release_at,
        version = rr.version + 1,
        updated_at = now()
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now())
      AND (rr.assigned_start_at, rr.assigned_end_at)
        IS DISTINCT FROM (p_scheduled_start_at, v_new_release_at);

    UPDATE public.reservations
    SET scheduled_start_at = p_scheduled_start_at,
        scheduled_end_at = p_scheduled_end_at,
        expected_release_at = v_new_release_at,
        version = version + 1,
        updated_at = now()
    WHERE id = v_reservation.id
    RETURNING version INTO v_new_version;

    -- Serialize the predicted response revision without modifying it; the
    -- helper performs the actual atomic increment as the final write.
    PERFORM ed.id FROM public.event_days AS ed
    WHERE ed.id = v_reservation.event_day_id
    FOR KEY SHARE OF ed;
    PERFORM public.lock_vip_floor_day_revision_v32(v_reservation.event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1
    INTO v_predicted_revision
    FROM (SELECT 1) AS seed
    LEFT JOIN public.vip_floor_day_revisions AS vfr
      ON vfr.event_day_id = v_reservation.event_day_id;

    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id,
      v_reservation.event_day_id,
      v_reservation.id,
      'reservation',
      v_reservation.id,
      v_action,
      p_request_id,
      p_reason,
      p_expected_version,
      v_reservation.version,
      v_new_version,
      ARRAY['scheduled_start_at', 'scheduled_end_at', 'expected_release_at', 'version'],
      jsonb_build_object(
        'scheduledStartAt', v_reservation.scheduled_start_at,
        'scheduledEndAt', v_reservation.scheduled_end_at,
        'expectedReleaseAt', v_reservation.expected_release_at,
        'version', v_reservation.version
      ),
      jsonb_build_object(
        'scheduledStartAt', p_scheduled_start_at,
        'scheduledEndAt', p_scheduled_end_at,
        'expectedReleaseAt', v_new_release_at,
        'version', v_new_version
      ),
      jsonb_build_object('warnings', v_warnings)
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;

    v_response := jsonb_build_object(
      'ok', true,
      'action', v_action,
      'reused', false,
      'reservationId', v_reservation.id,
      'entityVersion', v_new_version,
      'boardRevision', v_predicted_revision,
      'auditLogId', v_audit_id,
      'scheduledStartAt', p_scheduled_start_at,
      'scheduledEndAt', p_scheduled_end_at,
      'expectedReleaseAt', v_new_release_at,
      'warnings', v_warnings
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );

    v_step := public.bump_vip_floor_day_revision_v8(
      v_reservation.event_day_id, v_audit_id
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'XX000',
        MESSAGE = 'VIP floor revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: set_admin_reservation_service_status_v8(uuid, text, text, text, uuid, bigint, public.vip_service_status, timestamp with time zone, text)
CREATE FUNCTION public.set_admin_reservation_service_status_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_version bigint, p_to_status public.vip_service_status, p_occurred_at timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation.service_status.updated';
  v_step jsonb;
  v_reservation public.reservations%ROWTYPE;
  v_new_version bigint;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;

    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(p_actor_admin_id, 'service_status.write'),
      ARRAY['allowed']
    );

    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL OR p_occurred_at IS NULL THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', CASE WHEN p_occurred_at IS NULL THEN 'occurredAt' ELSE 'requestId' END)
          )
        ), ARRAY['allowed']
      );
    END IF;
    v_step := public.assert_reservation_version_v8(p_reservation_id, p_expected_version);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
    SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id;

    IF v_reservation.status IN ('cancelled', 'hold_expired', 'payment_window_expired', 'failed')
      OR v_reservation.service_status IN ('completed', 'no_show')
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION',
          'details', jsonb_build_object('reason', 'reservation_terminal')
        )), ARRAY['allowed']
      );
    END IF;

    v_step := public.resolve_business_day_for_timestamp_v8(p_occurred_at);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['resolved']);
    IF (v_step ->> 'eventDayId')::uuid <> v_reservation.event_day_id THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'occurredAt', 'reason', 'business_day_mismatch')
          )
        ), ARRAY['allowed']
      );
    END IF;
    v_step := public.resolve_vip_service_transition_v8(
      p_actor_admin_id, v_reservation.service_status, p_to_status, p_reason
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);

    PERFORM sr.id
    FROM public.seat_resources AS sr
    WHERE EXISTS (
      SELECT 1 FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id
        AND rr.seat_resource_id = sr.id
        AND rr.released_at IS NULL
    )
    ORDER BY sr.id FOR UPDATE OF sr;
    PERFORM rr.id
    FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
    ORDER BY rr.id FOR UPDATE OF rr;
    PERFORM rb.id
    FROM public.reservation_blocks AS rb
    WHERE rb.event_day_id = v_reservation.event_day_id
      AND rb.status = 'active'
      AND rb.start_at < v_reservation.expected_release_at
      AND rb.end_at > v_reservation.scheduled_start_at
      AND EXISTS (
        SELECT 1
        FROM public.reservation_block_targets AS rbt
        JOIN public.reservation_resources AS rr ON rr.reservation_id = v_reservation.id
        JOIN public.seat_resources AS sr ON sr.id = rr.seat_resource_id
        WHERE rbt.block_id = rb.id
          AND (
            rbt.seat_resource_id = sr.id
            OR rbt.floor_section_id = sr.floor_section_id
            OR rbt.venue_wide
          )
      )
    ORDER BY rb.id FOR UPDATE OF rb;

    IF p_to_status IN ('completed', 'no_show') THEN
      INSERT INTO public.reservation_assignment_events(
        reservation_id, reservation_resource_id, seat_resource_id, event_type,
        interval_before, interval_after, actor_admin_id, reason, request_id, occurred_at
      )
      SELECT rr.reservation_id, rr.id, rr.seat_resource_id, 'released',
        jsonb_build_object('startAt', rr.assigned_start_at, 'endAt', rr.assigned_end_at),
        NULL, p_actor_admin_id, p_reason, p_request_id, p_occurred_at
      FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id
        AND public.active_reservation_assignment_v8(rr.id, p_occurred_at);

      UPDATE public.reservation_resources AS rr
      SET lock_status = 'released',
          released_at = p_occurred_at,
          released_by_admin_id = p_actor_admin_id,
          release_reason = p_reason,
          version = rr.version + 1,
          updated_at = now()
      WHERE rr.reservation_id = v_reservation.id
        AND public.active_reservation_assignment_v8(rr.id, p_occurred_at);
    END IF;

    INSERT INTO public.reservation_service_events(
      reservation_id, from_status, to_status, occurred_at,
      actor_admin_id, reason, request_id, metadata_json
    ) VALUES (
      v_reservation.id, v_reservation.service_status, p_to_status, p_occurred_at,
      p_actor_admin_id, p_reason, p_request_id,
      jsonb_build_object('override', COALESCE((v_step #>> '{transition,override}')::boolean, false))
    );

    UPDATE public.reservations
    SET service_status = p_to_status,
        service_status_changed_at = p_occurred_at,
        arrived_at = CASE
          WHEN p_to_status IN ('arrived', 'partial_arrival', 'seated')
            THEN COALESCE(arrived_at, p_occurred_at)
          ELSE arrived_at
        END,
        service_completed_at = CASE WHEN p_to_status = 'completed' THEN p_occurred_at ELSE NULL END,
        version = version + 1,
        updated_at = now()
    WHERE id = v_reservation.id
    RETURNING version INTO v_new_version;

    PERFORM ed.id FROM public.event_days AS ed
    WHERE ed.id = v_reservation.event_day_id FOR KEY SHARE OF ed;
    PERFORM public.lock_vip_floor_day_revision_v32(v_reservation.event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1 INTO v_predicted_revision
    FROM (SELECT 1) AS seed
    LEFT JOIN public.vip_floor_day_revisions AS vfr
      ON vfr.event_day_id = v_reservation.event_day_id;

    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, v_reservation.event_day_id, v_reservation.id,
      'reservation', v_reservation.id, v_action, p_request_id, p_reason,
      p_expected_version, v_reservation.version, v_new_version,
      ARRAY['service_status', 'service_status_changed_at', 'version'],
      jsonb_build_object('serviceStatus', v_reservation.service_status, 'version', v_reservation.version),
      jsonb_build_object('serviceStatus', p_to_status, 'version', v_new_version),
      jsonb_build_object('occurredAt', p_occurred_at)
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_response := jsonb_build_object(
      'ok', true, 'action', v_action, 'reused', false,
      'reservationId', v_reservation.id,
      'entityVersion', v_new_version,
      'boardRevision', v_predicted_revision,
      'auditLogId', v_audit_id,
      'serviceStatus', p_to_status,
      'occurredAt', p_occurred_at
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(v_reservation.event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'XX000', MESSAGE = 'VIP floor revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: set_admin_vip_table_staff_assignment_v12(uuid, text, text, text, uuid, uuid, uuid, bigint, text)
CREATE FUNCTION public.set_admin_vip_table_staff_assignment_v12(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_day_id uuid, p_seat_resource_id uuid, p_staff_member_id uuid, p_expected_assignment_version bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'table_staff_assignment.set';
  v_step jsonb;
  v_current public.vip_table_staff_assignments%ROWTYPE;
  v_current_exists boolean := false;
  v_assignment_id uuid;
  v_entity_version bigint;
  v_audit_id uuid;
  v_revision bigint;
  v_response jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admin_users
    WHERE id = p_actor_admin_id AND active = true AND role = 'owner'
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object('code', 'FORBIDDEN')
    );
  END IF;
  IF p_event_day_id IS NULL
    OR p_seat_resource_id IS NULL
    OR p_reason <> '管理画面操作'
    OR (p_expected_assignment_version IS NOT NULL AND p_expected_assignment_version < 1)
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object('field', 'tableStaffAssignment')
      )
    );
  END IF;

  v_step := public.preclaim_admin_action_request_v8(
    p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
  );
  IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
  IF v_step ->> 'action' = 'reused' THEN
    RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
  END IF;

  PERFORM id FROM public.event_days
  WHERE id = p_event_day_id
  FOR NO KEY UPDATE;
  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM public.seat_resources
    WHERE id = p_seat_resource_id AND active = true
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object('code', 'NOT_FOUND')
    );
  END IF;
  IF p_staff_member_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.vip_staff_members
    WHERE id = p_staff_member_id AND active = true
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'NOT_FOUND',
        'details', jsonb_build_object('entityType', 'staff_member')
      )
    );
  END IF;

  SELECT * INTO v_current
  FROM public.vip_table_staff_assignments
  WHERE event_day_id = p_event_day_id
    AND seat_resource_id = p_seat_resource_id
    AND released_at IS NULL
  FOR UPDATE;
  v_current_exists := FOUND;

  IF v_current_exists <> (p_expected_assignment_version IS NOT NULL)
    OR (
      v_current_exists
      AND v_current.version <> p_expected_assignment_version
    )
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'VERSION_CONFLICT',
        'currentVersion', CASE WHEN v_current_exists THEN v_current.version ELSE 0 END
      )
    );
  END IF;

  IF v_current_exists THEN
    UPDATE public.vip_table_staff_assignments
    SET released_at = now(),
        released_by_admin_id = p_actor_admin_id,
        version = version + 1,
        updated_at = now()
    WHERE id = v_current.id;
  END IF;

  IF p_staff_member_id IS NULL THEN
    v_assignment_id := COALESCE(v_current.id, gen_random_uuid());
    v_entity_version := COALESCE(v_current.version + 1, 1);
  ELSE
    INSERT INTO public.vip_table_staff_assignments(
      event_day_id, seat_resource_id, staff_member_id,
      assigned_by_admin_id
    )
    VALUES (
      p_event_day_id, p_seat_resource_id, p_staff_member_id,
      p_actor_admin_id
    )
    RETURNING id, version INTO v_assignment_id, v_entity_version;
  END IF;

  INSERT INTO public.audit_logs(
    actor_admin_id, actor_type, action, target_table, target_id,
    request_id, reason, event_day_id, entity_type, entity_id, operation,
    expected_version, version_before, version_after, changed_fields,
    before_json, after_json, metadata_json, source_contract
  )
  VALUES (
    p_actor_admin_id, 'admin', v_action,
    'vip_table_staff_assignments', v_assignment_id,
    p_request_id, p_reason, p_event_day_id,
    'table_staff_assignment', v_assignment_id, v_action,
    p_expected_assignment_version,
    CASE WHEN v_current_exists THEN v_current.version ELSE NULL END,
    v_entity_version,
    ARRAY['staff_member_id', 'released_at', 'version'],
    CASE WHEN v_current_exists THEN jsonb_build_object(
      'version', v_current.version,
      'staffMemberId', v_current.staff_member_id
    ) ELSE NULL END,
    jsonb_build_object(
      'version', v_entity_version,
      'staffMemberId', p_staff_member_id,
      'released', p_staff_member_id IS NULL
    ),
    jsonb_build_object('seatResourceId', p_seat_resource_id),
    'ghost.vip-manager.v2'
  )
  RETURNING id INTO v_audit_id;

  v_step := public.bump_vip_floor_day_revision_v8(p_event_day_id, v_audit_id);
  IF v_step ->> 'action' <> 'bumped' THEN
    RAISE EXCEPTION 'VIP table staff revision bump failed';
  END IF;
  v_revision := (v_step ->> 'revision')::bigint;

  v_response := jsonb_build_object(
    'ok', true,
    'action', v_action,
    'reused', false,
    'assignmentId', v_assignment_id,
    'entityVersion', v_entity_version,
    'boardRevision', v_revision,
    'auditLogId', v_audit_id
  );
  PERFORM public.complete_admin_action_request_v8(
    p_actor_admin_id, v_action, p_idempotency_key, v_response
  );
  RETURN v_response;
END;
$$;

-- FUNCTION: set_ticket_event_session_policy_v27(uuid, text, uuid, bigint, text, text, text, boolean, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, text)
CREATE FUNCTION public.set_ticket_event_session_policy_v27(p_actor_admin_id uuid, p_request_id text, p_event_session_id uuid, p_expected_policy_version bigint, p_sales_check_in_mode text, p_sales_state text, p_admission_state text, p_enabled boolean, p_door_at timestamp with time zone, p_close_at timestamp with time zone, p_admission_opens_at timestamp with time zone, p_admission_closes_at timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_event_day_id uuid;
  v_session public.ticket_event_sessions%ROWTYPE;
  v_before jsonb;
  v_after jsonb;
  v_audit_id uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admin_users AS admin_user
    WHERE admin_user.id = p_actor_admin_id
      AND admin_user.active
      AND admin_user.role = 'owner'
  ) THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'owner_role_required');
  END IF;
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL
    OR char_length(btrim(p_reason)) > 240
    OR p_expected_policy_version IS NULL OR p_expected_policy_version < 1
    OR COALESCE(p_sales_check_in_mode, '') NOT IN ('legacy_qr', 'wallet_swipe')
    OR COALESCE(p_sales_state, '') NOT IN ('active', 'draining', 'closed')
    OR COALESCE(p_admission_state, '') NOT IN ('scheduled', 'closed', 'cancelled')
    OR p_enabled IS NULL
    OR p_door_at IS NULL OR p_close_at IS NULL
    OR p_admission_opens_at IS NULL OR p_admission_closes_at IS NULL
    OR NOT (
      p_admission_opens_at <= p_door_at
      AND p_door_at < p_close_at
      AND p_close_at <= p_admission_closes_at
    )
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'policy_input_invalid');
  END IF;

  SELECT session.event_day_id INTO v_event_day_id
  FROM public.ticket_event_sessions AS session
  WHERE session.id = p_event_session_id;
  IF v_event_day_id IS NULL THEN
    RETURN jsonb_build_object('action', 'not_found');
  END IF;

  PERFORM 1 FROM public.event_days
  WHERE id = v_event_day_id FOR NO KEY UPDATE;
  SELECT * INTO v_session
  FROM public.ticket_event_sessions
  WHERE id = p_event_session_id FOR NO KEY UPDATE;

  IF v_session.policy_version <> p_expected_policy_version THEN
    RETURN jsonb_build_object(
      'action', 'version_conflict', 'reason', 'policy_version_mismatch',
      'policyVersion', v_session.policy_version);
  END IF;

  v_before := jsonb_build_object(
    'salesCheckInMode', v_session.sales_check_in_mode,
    'salesState', v_session.sales_state,
    'admissionState', v_session.admission_state,
    'enabled', v_session.enabled,
    'doorAt', v_session.door_at,
    'closeAt', v_session.close_at,
    'admissionOpensAt', v_session.admission_opens_at,
    'admissionClosesAt', v_session.admission_closes_at,
    'policyVersion', v_session.policy_version
  );

  UPDATE public.ticket_event_sessions
  SET sales_check_in_mode = p_sales_check_in_mode,
      sales_state = p_sales_state,
      admission_state = p_admission_state,
      enabled = p_enabled,
      disabled_at = CASE WHEN p_enabled THEN NULL ELSE now() END,
      door_at = p_door_at,
      close_at = p_close_at,
      admission_opens_at = p_admission_opens_at,
      admission_closes_at = p_admission_closes_at,
      policy_version = policy_version + 1,
      updated_at = now()
  WHERE id = v_session.id
    AND policy_version = p_expected_policy_version
  RETURNING * INTO v_session;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'version_conflict', 'reason', 'policy_version_mismatch');
  END IF;

  v_after := jsonb_build_object(
    'salesCheckInMode', v_session.sales_check_in_mode,
    'salesState', v_session.sales_state,
    'admissionState', v_session.admission_state,
    'enabled', v_session.enabled,
    'doorAt', v_session.door_at,
    'closeAt', v_session.close_at,
    'admissionOpensAt', v_session.admission_opens_at,
    'admissionClosesAt', v_session.admission_closes_at,
    'policyVersion', v_session.policy_version
  );

  INSERT INTO public.ticket_event_session_policy_audits(
    ticket_event_session_id, actor_admin_id, request_id, reason,
    previous_policy_version, new_policy_version, before_json, after_json
  ) VALUES (
    v_session.id, p_actor_admin_id, left(btrim(p_request_id), 200),
    left(btrim(p_reason), 240), p_expected_policy_version,
    v_session.policy_version, v_before, v_after
  ) RETURNING id INTO v_audit_id;

  INSERT INTO public.audit_logs(
    action, actor_type, actor_admin_id, target_table, target_id,
    entity_type, entity_id, operation, request_id, reason, metadata_json
  ) VALUES (
    'ticket_event_session.policy_update', 'admin', p_actor_admin_id,
    'ticket_event_sessions', v_session.id,
    'ticket_event_session', v_session.id, 'update', left(btrim(p_request_id), 200),
    left(btrim(p_reason), 240),
    jsonb_build_object('policyVersion', v_session.policy_version,
                       'policyAuditId', v_audit_id)
  );

  RETURN jsonb_build_object(
    'action', 'updated', 'eventSessionId', v_session.id,
    'policyVersion', v_session.policy_version, 'policyAuditId', v_audit_id,
    'salesCheckInMode', v_session.sales_check_in_mode,
    'salesState', v_session.sales_state,
    'admissionState', v_session.admission_state,
    'enabled', v_session.enabled
  );
END;
$$;

-- FUNCTION: set_ticket_mail_capacity_policy_v47(uuid, text, bigint, timestamp with time zone, timestamp with time zone, integer, integer, integer, integer, integer, text)
CREATE FUNCTION public.set_ticket_mail_capacity_policy_v47(p_actor_admin_id uuid, p_provider text, p_expected_version bigint, p_observed_at timestamp with time zone, p_valid_until timestamp with time zone, p_provider_daily_used integer, p_provider_monthly_used integer, p_local_counter_before_observation integer, p_external_daily_reserve integer, p_external_monthly_reserve integer, p_evidence_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE prior public.ticket_mail_capacity_policy%ROWTYPE;
 current_policy public.ticket_mail_capacity_policy%ROWTYPE;
 n integer; day date := (clock_timestamp() AT TIME ZONE 'UTC')::date;
BEGIN
 PERFORM 1 FROM public.admin_users WHERE id=p_actor_admin_id AND active AND role='owner' FOR SHARE;
 IF NOT FOUND THEN RETURN jsonb_build_object('action','forbidden'); END IF;
 IF p_provider NOT IN ('resend','fake') OR p_expected_version IS NULL OR p_expected_version<0
  OR p_observed_at IS NULL OR p_observed_at>clock_timestamp()
  OR (p_observed_at AT TIME ZONE 'UTC')::date<>day
  OR p_valid_until IS NULL OR p_valid_until<=clock_timestamp()
 THEN RETURN jsonb_build_object('action','rejected'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('ghost.ticket.mail.capacity.v47',0));
 SELECT * INTO prior FROM public.ticket_mail_capacity_policy WHERE provider_name=p_provider FOR UPDATE;
 IF COALESCE(prior.version,0)<>p_expected_version THEN RETURN jsonb_build_object('action','conflict'); END IF;
 SELECT LEAST(80,request_count) INTO n FROM public.ticket_wallet_rate_limit_buckets
  WHERE bucket_name='provider_free_day_v40_'||p_provider AND bucket_hash=day::text;
 IF p_local_counter_before_observation IS NULL OR p_local_counter_before_observation>COALESCE(n,0)
 THEN RETURN jsonb_build_object('action','rejected'); END IF;
 INSERT INTO public.ticket_mail_capacity_policy VALUES
  (p_provider,p_expected_version+1,day,p_observed_at,p_valid_until,p_provider_daily_used,p_provider_monthly_used,
   p_local_counter_before_observation,p_external_daily_reserve,p_external_monthly_reserve,p_evidence_sha256,p_actor_admin_id,clock_timestamp())
 ON CONFLICT(provider_name) DO UPDATE SET version=excluded.version,utc_day=excluded.utc_day,
  observed_at=excluded.observed_at,valid_until=excluded.valid_until,provider_daily_used=excluded.provider_daily_used,
  provider_monthly_used=excluded.provider_monthly_used,local_counter_before_observation=excluded.local_counter_before_observation,
  external_daily_reserve=excluded.external_daily_reserve,external_monthly_reserve=excluded.external_monthly_reserve,
  evidence_sha256=excluded.evidence_sha256,actor_admin_id=excluded.actor_admin_id,updated_at=excluded.updated_at
 RETURNING * INTO current_policy;
 INSERT INTO public.ticket_mail_capacity_audits(actor_admin_id,provider_name,version,previous_policy,policy)
 VALUES(p_actor_admin_id,p_provider,current_policy.version,CASE WHEN prior.version IS NULL THEN NULL ELSE to_jsonb(prior) END,to_jsonb(current_policy));
 RETURN jsonb_build_object('action','updated','version',current_policy.version);
END; $$;

-- FUNCTION: set_transactional_email_provider_circuit_v29(text, boolean, text, timestamp with time zone)
CREATE FUNCTION public.set_transactional_email_provider_circuit_v29(p_provider_name text, p_is_open boolean, p_safe_reason text, p_open_until timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_provider_name NOT IN ('fake', 'resend') OR p_is_open IS NULL
    OR (p_is_open AND (
      NULLIF(btrim(COALESCE(p_safe_reason, '')), '') IS NULL
      OR char_length(p_safe_reason) > 128 OR p_safe_reason ~ E'[\\r\\n]'
      OR (p_open_until IS NOT NULL AND p_open_until <= v_now)))
    OR (NOT p_is_open AND (p_safe_reason IS NOT NULL OR p_open_until IS NOT NULL))
  THEN
    RAISE EXCEPTION 'invalid transactional email circuit change';
  END IF;
  INSERT INTO public.transactional_email_provider_circuits(
    provider_name, is_open, safe_reason, opened_at, open_until, updated_at
  ) VALUES (
    p_provider_name, p_is_open,
    CASE WHEN p_is_open THEN p_safe_reason END,
    CASE WHEN p_is_open THEN v_now END,
    CASE WHEN p_is_open THEN p_open_until END,
    v_now
  )
  ON CONFLICT (provider_name) DO UPDATE
  SET is_open = EXCLUDED.is_open, safe_reason = EXCLUDED.safe_reason,
      opened_at = EXCLUDED.opened_at, open_until = EXCLUDED.open_until,
      updated_at = EXCLUDED.updated_at;
  RETURN jsonb_build_object('action', CASE WHEN p_is_open THEN 'opened' ELSE 'closed' END);
END;
$$;

-- FUNCTION: set_updated_at()
CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

-- FUNCTION: store_stripe_webhook_event_v7(text, text, text, text, text, text, text, text, text, jsonb, text, text)
CREATE FUNCTION public.store_stripe_webhook_event_v7(p_stripe_event_id text, p_event_type text, p_environment text, p_stripe_account_id text, p_provider_object_type text, p_provider_object_id text, p_api_version text, p_raw_body_hash text, p_received_signature_header_hash text, p_payload_json jsonb, p_processing_status text DEFAULT 'received'::text, p_ignored_reason text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_status webhook_processing_status;
BEGIN
  INSERT INTO webhook_events(
    stripe_event_id,
    event_type,
    environment,
    stripe_account_id,
    provider_object_type,
    provider_object_id,
    api_version,
    raw_body_hash,
    received_signature_header_hash,
    payload_json,
    processing_status,
    ignored_reason
  )
  VALUES (
    p_stripe_event_id,
    p_event_type,
    p_environment,
    p_stripe_account_id,
    p_provider_object_type,
    p_provider_object_id,
    p_api_version,
    p_raw_body_hash,
    p_received_signature_header_hash,
    p_payload_json,
    p_processing_status::webhook_processing_status,
    p_ignored_reason
  )
  ON CONFLICT (environment, stripe_account_key, stripe_event_id)
  DO UPDATE
  SET duplicate_count = webhook_events.duplicate_count + 1,
      updated_at = now()
  RETURNING processing_status INTO v_status;

  RETURN v_status::text;
END;
$$;

-- FUNCTION: summarize_reconciliation_v7(text, text)
CREATE FUNCTION public.summarize_reconciliation_v7(p_environment text DEFAULT NULL::text, p_stripe_account_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
WITH ledger AS (
  SELECT
    COALESCE(SUM(amount_yen), 0)::int AS gross_amount_yen,
    COUNT(*) FILTER (WHERE stripe_balance_transaction_id IS NULL AND amount_yen <> 0)::int AS unlinked_ledger_count
  FROM ledger_entries le
  WHERE p_environment IS NULL
    OR EXISTS (
      SELECT 1
      FROM payments p
      WHERE p.id = le.payment_id
        AND p.environment = p_environment
        AND p.stripe_account_key = COALESCE(p_stripe_account_id, p.stripe_account_key)
    )
    OR le.stripe_balance_transaction_id IN (
      SELECT sbt.id
      FROM stripe_balance_transactions sbt
      WHERE sbt.environment = p_environment
        AND sbt.stripe_account_key = COALESCE(p_stripe_account_id, sbt.stripe_account_key)
    )
),
balance AS (
  SELECT
    COALESCE(SUM(amount_yen), 0)::int AS gross_amount_yen,
    COALESCE(SUM(fee_yen), 0)::int AS fee_amount_yen,
    COALESCE(SUM(net_yen), 0)::int AS net_amount_yen,
    COUNT(*)::int AS imported_balance_transaction_count
  FROM stripe_balance_transactions
  WHERE p_environment IS NULL
    OR (
      environment = p_environment
      AND stripe_account_key = COALESCE(p_stripe_account_id, stripe_account_key)
    )
)
SELECT jsonb_build_object(
  'ledgerGrossAmountYen', ledger.gross_amount_yen,
  'stripeGrossAmountYen', balance.gross_amount_yen,
  'stripeFeeAmountYen', balance.fee_amount_yen,
  'stripeNetAmountYen', balance.net_amount_yen,
  'grossDifferenceYen', ledger.gross_amount_yen - balance.gross_amount_yen,
  'unlinkedLedgerCount', ledger.unlinked_ledger_count,
  'importedBalanceTransactionCount', balance.imported_balance_transaction_count
)
FROM ledger, balance;
$$;

-- FUNCTION: summarize_reconciliation_v8(text, text, timestamp with time zone, timestamp with time zone, text, boolean)
CREATE FUNCTION public.summarize_reconciliation_v8(p_environment text DEFAULT NULL::text, p_stripe_account_id text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_currency text DEFAULT NULL::text, p_scope_all boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ledger_gross bigint;
  v_unlinked int;
  v_open_reviews int;
  v_domains jsonb;
  v_currency text := lower(btrim(COALESCE(p_currency, '')));
  v_vip_gross bigint := 0;
  v_vip_fee bigint := 0;
  v_vip_net bigint := 0;
  v_vip_count int := 0;
  v_total_count int := 0;
BEGIN
  IF COALESCE(p_scope_all, false) IS DISTINCT FROM true
    AND NULLIF(btrim(COALESCE(p_environment, '')), '') IS NULL THEN
    RAISE EXCEPTION 'reconciliation_environment_scope_required';
  END IF;

  -- VIP ledger scope. A ledger row's environment resolves through its payment,
  -- its provider refund/dispute identity, or the balance transaction it was
  -- reconciled against (case-less external rows keep payment_id NULL by
  -- design; the refund/dispute identity carries the scope).
  SELECT COALESCE(SUM(le.amount_yen), 0)::bigint,
         COUNT(*) FILTER (WHERE le.stripe_balance_transaction_id IS NULL AND le.amount_yen <> 0)::int
  INTO v_ledger_gross, v_unlinked
  FROM ledger_entries le
  LEFT JOIN payments pay ON pay.id = le.payment_id
  LEFT JOIN stripe_refunds srf ON srf.stripe_refund_id = le.stripe_refund_id
  LEFT JOIN stripe_disputes sd ON sd.stripe_dispute_id = le.stripe_dispute_id
  LEFT JOIN stripe_balance_transactions sbt ON sbt.id = le.stripe_balance_transaction_id
  WHERE (COALESCE(p_scope_all, false) OR
         COALESCE(pay.environment, srf.environment, sd.environment, sbt.environment) = p_environment)
    AND (p_stripe_account_id IS NULL OR
         COALESCE(pay.stripe_account_key, srf.stripe_account_key, sd.stripe_account_key, sbt.stripe_account_key)
           = COALESCE(p_stripe_account_id, 'platform'))
    AND (p_from IS NULL OR le.created_at >= p_from)
    AND (p_to IS NULL OR le.created_at < p_to)
    AND (v_currency = '' OR lower(COALESCE(pay.currency, 'jpy')) = v_currency);

  -- Stripe side, split by reporting domain and currency. Ticket sales and
  -- other-domain movements stay visible but can never pollute the VIP books.
  WITH agg AS (
    SELECT COALESCE(sbt.reporting_domain, 'unclassified') AS domain,
           COALESCE(sbt.currency, 'jpy') AS currency,
           SUM(sbt.amount_yen)::bigint AS gross,
           SUM(sbt.fee_yen)::bigint AS fee,
           SUM(sbt.net_yen)::bigint AS net,
           COUNT(*)::int AS n
    FROM stripe_balance_transactions sbt
    WHERE (COALESCE(p_scope_all, false) OR sbt.environment = p_environment)
      AND (p_stripe_account_id IS NULL OR sbt.stripe_account_key = COALESCE(p_stripe_account_id, 'platform'))
      AND (p_from IS NULL OR sbt.created_at >= p_from)
      AND (p_to IS NULL OR sbt.created_at < p_to)
      AND (v_currency = '' OR COALESCE(sbt.currency, 'jpy') = v_currency)
    GROUP BY 1, 2
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'domain', domain, 'currency', currency,
           'grossAmountYen', gross, 'grossAmountYenText', gross::text,
           'feeAmountYen', fee, 'netAmountYen', net,
           'transactionCount', n
         ) ORDER BY domain, currency), '[]'::jsonb)
  INTO v_domains
  FROM agg;

  SELECT
    COALESCE(SUM((d ->> 'grossAmountYen')::bigint) FILTER (WHERE d ->> 'domain' = 'vip' AND d ->> 'currency' = 'jpy'), 0),
    COALESCE(SUM((d ->> 'feeAmountYen')::bigint)    FILTER (WHERE d ->> 'domain' = 'vip' AND d ->> 'currency' = 'jpy'), 0),
    COALESCE(SUM((d ->> 'netAmountYen')::bigint)    FILTER (WHERE d ->> 'domain' = 'vip' AND d ->> 'currency' = 'jpy'), 0),
    COALESCE(SUM((d ->> 'transactionCount')::int)   FILTER (WHERE d ->> 'domain' = 'vip' AND d ->> 'currency' = 'jpy'), 0),
    COALESCE(SUM((d ->> 'transactionCount')::int), 0)
  INTO v_vip_gross, v_vip_fee, v_vip_net, v_vip_count, v_total_count
  FROM jsonb_array_elements(v_domains) d;

  SELECT count(*)::int INTO v_open_reviews
  FROM public.external_finance_reviews r
  WHERE r.status = 'review_required'
    AND (COALESCE(p_scope_all, false) OR r.environment = p_environment)
    AND (p_stripe_account_id IS NULL OR r.stripe_account_key = COALESCE(p_stripe_account_id, 'platform'));

  RETURN jsonb_build_object(
    'scope', jsonb_build_object(
      'environment', p_environment,
      'stripeAccountId', p_stripe_account_id,
      'from', p_from,
      'to', p_to,
      'currency', NULLIF(v_currency, ''),
      'scopeAll', COALESCE(p_scope_all, false)
    ),
    'ledgerGrossAmountYen', v_ledger_gross,
    'ledgerGrossAmountYenText', v_ledger_gross::text,
    'vipStripeGrossAmountYen', v_vip_gross,
    'vipStripeGrossAmountYenText', v_vip_gross::text,
    'vipStripeFeeAmountYen', v_vip_fee,
    'vipStripeNetAmountYen', v_vip_net,
    'vipStripeTransactionCount', v_vip_count,
    'unexplainedGrossDifferenceYen', v_ledger_gross - v_vip_gross,
    'unexplainedGrossDifferenceYenText', (v_ledger_gross - v_vip_gross)::text,
    'stripeByDomain', v_domains,
    'unlinkedLedgerCount', v_unlinked,
    'importedBalanceTransactionCount', v_total_count,
    'openReviewCount', v_open_reviews
  );
END;
$$;

-- FUNCTION: summarize_worker_queues_v7()
CREATE FUNCTION public.summarize_worker_queues_v7() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
SELECT jsonb_build_object(
  'stripeWebhooks',
  (
    SELECT COALESCE(jsonb_object_agg(status, count), '{}'::jsonb)
    FROM (
      SELECT processing_status::text AS status, COUNT(*)::int AS count
      FROM webhook_events
      GROUP BY processing_status
    ) counts
  ),
  'reservationHolds',
  (
    SELECT COALESCE(jsonb_object_agg(status, count), '{}'::jsonb)
    FROM (
      SELECT status, COUNT(*)::int AS count
      FROM reservation_hold_requests
      GROUP BY status
    ) counts
  ),
  'offSessionCharges',
  (
    SELECT COALESCE(jsonb_object_agg(status, count), '{}'::jsonb)
    FROM (
      SELECT status, COUNT(*)::int AS count
      FROM off_session_charge_attempts
      GROUP BY status
    ) counts
  ),
  'refunds',
  (
    SELECT COALESCE(jsonb_object_agg(status, count), '{}'::jsonb)
    FROM (
      SELECT status, COUNT(*)::int AS count
      FROM refund_cases
      GROUP BY status
    ) counts
  ),
  'notifications',
  (
    SELECT COALESCE(jsonb_object_agg(status, count), '{}'::jsonb)
    FROM (
      SELECT status, COUNT(*)::int AS count
      FROM notification_jobs
      WHERE channel = 'line'
      GROUP BY status
    ) counts
  ),
  'balanceTransactions',
  jsonb_build_object(
    'imported',
    (SELECT COUNT(*)::int FROM stripe_balance_transactions)
  )
);
$$;

-- FUNCTION: sync_public_customer_profile_v10(uuid, uuid, text, bytea, bytea)
CREATE FUNCTION public.sync_public_customer_profile_v10(p_customer_id uuid, p_reservation_id uuid, p_request_hash text, p_phone_ciphertext bytea, p_email_ciphertext bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_reservation public.reservations%ROWTYPE;
  v_profile public.customer_profiles%ROWTYPE;
  v_profile_exists boolean := false;
  v_new_version bigint;
  v_audit_id uuid;
  v_revision_step jsonb;
BEGIN
  IF p_customer_id IS NULL
    OR p_reservation_id IS NULL
    OR NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL
    OR length(p_request_hash) > 255
    OR (p_phone_ciphertext IS NOT NULL AND octet_length(p_phone_ciphertext) = 0)
    OR (p_email_ciphertext IS NOT NULL AND octet_length(p_email_ciphertext) = 0)
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'error', 'invalid_command');
  END IF;

  IF p_phone_ciphertext IS NULL AND p_email_ciphertext IS NULL THEN
    RETURN jsonb_build_object('action', 'skipped', 'reason', 'no_contact_fields');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_customer_id::text, 10010));

  SELECT *
  INTO v_reservation
  FROM public.reservations
  WHERE id = p_reservation_id
    AND customer_id = p_customer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', 'reservation_customer_mismatch'
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.audit_logs
    WHERE action = 'vip_manager.public_customer_profile.synced'
      AND target_id = p_customer_id
      AND metadata_json ->> 'requestHash' = p_request_hash
  ) THEN
    RETURN jsonb_build_object(
      'action', 'reused',
      'customerId', p_customer_id
    );
  END IF;

  SELECT *
  INTO v_profile
  FROM public.customer_profiles
  WHERE customer_id = p_customer_id
  FOR UPDATE;
  v_profile_exists := FOUND;

  PERFORM set_config('ghost.vip_floor_v8_writer', 'on', true);

  INSERT INTO public.customer_profiles(
    customer_id,
    phone_ciphertext,
    email_ciphertext,
    version
  )
  VALUES (
    p_customer_id,
    p_phone_ciphertext,
    p_email_ciphertext,
    1
  )
  ON CONFLICT (customer_id) DO UPDATE
  SET phone_ciphertext = COALESCE(
        EXCLUDED.phone_ciphertext,
        public.customer_profiles.phone_ciphertext
      ),
      email_ciphertext = COALESCE(
        EXCLUDED.email_ciphertext,
        public.customer_profiles.email_ciphertext
      ),
      version = public.customer_profiles.version + 1,
      updated_at = now()
  RETURNING version INTO v_new_version;

  INSERT INTO public.audit_logs(
    actor_type,
    action,
    target_table,
    target_id,
    request_id,
    event_day_id,
    reservation_id,
    entity_type,
    entity_id,
    operation,
    version_before,
    version_after,
    changed_fields,
    before_json,
    after_json,
    metadata_json,
    source_contract
  )
  VALUES (
    'customer',
    'vip_manager.public_customer_profile.synced',
    'customer_profiles',
    p_customer_id,
    p_request_hash,
    v_reservation.event_day_id,
    p_reservation_id,
    'customer',
    p_customer_id,
    'public_customer_profile_sync',
    CASE WHEN v_profile_exists THEN v_profile.version ELSE NULL END,
    v_new_version,
    ARRAY['phone_ciphertext', 'email_ciphertext', 'version'],
    CASE WHEN v_profile_exists
      THEN jsonb_build_object('version', v_profile.version)
      ELSE NULL
    END,
    jsonb_build_object('version', v_new_version),
    jsonb_build_object(
      'sourceContract', 'ghost.vip-manager.v2',
      'redaction', 'field_names_and_versions_only',
      'requestHash', p_request_hash
    ),
    'ghost.vip-manager.v2'
  )
  RETURNING id INTO v_audit_id;

  v_revision_step := public.bump_vip_floor_day_revision_v8(
    v_reservation.event_day_id,
    v_audit_id
  );
  IF v_revision_step ->> 'action' <> 'bumped' THEN
    RAISE EXCEPTION 'VIP Manager customer profile revision bump failed';
  END IF;

  RETURN jsonb_build_object(
    'action', 'synced',
    'customerId', p_customer_id,
    'entityVersion', v_new_version,
    'created', NOT v_profile_exists
  );
END;
$$;

-- FUNCTION: sync_reservation_floor_note_v22(uuid, uuid, text)
CREATE FUNCTION public.sync_reservation_floor_note_v22(p_actor_admin_id uuid, p_reservation_id uuid, p_floor_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_note_id uuid;
  v_body text := NULLIF(btrim(COALESCE(p_floor_note, '')), '');
BEGIN
  PERFORM id FROM public.reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Reservation not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT id INTO v_note_id
  FROM public.reservation_notes
  WHERE reservation_id = p_reservation_id
    AND kind = 'floor'
    AND archived_at IS NULL
  ORDER BY updated_at DESC, id
  LIMIT 1
  FOR UPDATE;

  UPDATE public.reservation_notes
  SET archived_at = COALESCE(archived_at, now()),
      updated_by_admin_id = p_actor_admin_id,
      version = version + 1,
      updated_at = now()
  WHERE reservation_id = p_reservation_id
    AND kind = 'floor'
    AND archived_at IS NULL
    AND (v_note_id IS NULL OR id <> v_note_id);

  IF v_body IS NULL AND v_note_id IS NOT NULL THEN
    UPDATE public.reservation_notes
    SET archived_at = COALESCE(archived_at, now()),
        updated_by_admin_id = p_actor_admin_id,
        version = version + 1,
        updated_at = now()
    WHERE id = v_note_id;
  ELSIF v_body IS NOT NULL AND v_note_id IS NULL THEN
    INSERT INTO public.reservation_notes(
      reservation_id, kind, body, pinned, author_admin_id, updated_by_admin_id
    ) VALUES (
      p_reservation_id, 'floor', v_body, false, p_actor_admin_id, p_actor_admin_id
    );
  ELSIF v_body IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.reservation_notes WHERE id = v_note_id AND body IS DISTINCT FROM v_body
  ) THEN
    UPDATE public.reservation_notes
    SET body = v_body,
        updated_by_admin_id = p_actor_admin_id,
        version = version + 1,
        updated_at = now()
    WHERE id = v_note_id;
  END IF;

  -- The legacy column remains in the physical schema for rollback readers, but
  -- is never an authority after v22.
  UPDATE public.reservations SET operator_note = NULL
  WHERE id = p_reservation_id AND operator_note IS NOT NULL;
END;
$$;

-- FUNCTION: sync_reservation_origin_from_legacy_v22()
CREATE FUNCTION public.sync_reservation_origin_from_legacy_v22() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.origin_channel IS NULL
    OR (
      TG_OP = 'UPDATE'
      AND NEW.intake_channel IS DISTINCT FROM OLD.intake_channel
      AND NEW.origin_channel IS NOT DISTINCT FROM OLD.origin_channel
    )
  THEN
    NEW.origin_channel := CASE
      WHEN NEW.intake_channel = 'admin_hold' THEN 'admin'
      WHEN NEW.intake_channel = 'walk_in' THEN 'walk_in'
      ELSE 'online'
    END;
  END IF;
  RETURN NEW;
END;
$$;

-- FUNCTION: ticket_admission_execution_closes_v56(uuid)
CREATE FUNCTION public.ticket_admission_execution_closes_v56(p_session uuid) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ SELECT closes_at FROM public.ticket_admission_execution_window_v56(p_session) $$;

-- FUNCTION: ticket_admission_execution_opens_v56(uuid)
CREATE FUNCTION public.ticket_admission_execution_opens_v56(p_session uuid) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ SELECT opens_at FROM public.ticket_admission_execution_window_v56(p_session) $$;

-- FUNCTION: ticket_admission_execution_window_v56(uuid)
CREATE FUNCTION public.ticket_admission_execution_window_v56(p_session uuid) RETURNS TABLE(opens_at timestamp with time zone, closes_at timestamp with time zone, demo_test boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE e public.ticket_event_sessions%ROWTYPE; w public.ticket_demo_admission_windows_v56%ROWTYPE; authority jsonb;
BEGIN
 SELECT * INTO e FROM public.ticket_event_sessions WHERE id=p_session;
 IF NOT FOUND THEN RETURN; END IF;
 -- LIVE can never enter the TEST branch, even if an override row is inserted.
 SELECT * INTO w FROM public.ticket_demo_admission_windows_v56 WHERE event_session_id=e.id AND e.environment='test';
 IF NOT FOUND THEN RETURN QUERY SELECT e.admission_opens_at,e.admission_closes_at,false; RETURN; END IF;
 IF to_regclass('public.ticket_demo_authority') IS NOT NULL THEN
  EXECUTE 'SELECT to_jsonb(a) FROM public.ticket_demo_authority a WHERE singleton' INTO authority;
 END IF;
 IF authority IS NULL OR authority->>'run_id' IS DISTINCT FROM w.run_id::text
  OR authority->>'project_ref' IS DISTINCT FROM w.project_ref
  OR (authority->>'stopped')::boolean IS DISTINCT FROM false
  OR (authority->>'expires_at')::timestamptz<=statement_timestamp()
 THEN RETURN QUERY SELECT '1970-01-01T00:00:00Z'::timestamptz,'1970-01-01T00:00:00Z'::timestamptz,true; RETURN; END IF;
 RETURN QUERY SELECT w.opens_at,least(w.closes_at,(authority->>'expires_at')::timestamptz),true;
END $$;

-- FUNCTION: ticket_admission_policy_compatible_v30(uuid, bigint, bigint)
CREATE FUNCTION public.ticket_admission_policy_compatible_v30(p_event_session_id uuid, p_operation_policy_version bigint, p_current_policy_version bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    p_operation_policy_version = p_current_policy_version
    OR EXISTS (
      SELECT 1
      FROM public.ticket_event_session_policy_audits AS policy_audit
      WHERE policy_audit.ticket_event_session_id = p_event_session_id
        AND policy_audit.authority_action = 'begin_wallet_drain_v30'
        AND policy_audit.previous_policy_version = p_operation_policy_version
        AND policy_audit.new_policy_version = p_current_policy_version
        AND p_current_policy_version = p_operation_policy_version + 1
        AND policy_audit.before_json ->> 'salesState' = 'active'
        AND policy_audit.after_json ->> 'salesState' = 'draining'
        AND (policy_audit.before_json - 'salesState' - 'policyVersion')
          = (policy_audit.after_json - 'salesState' - 'policyVersion')
        AND EXISTS (
          SELECT 1
          FROM public.audit_logs AS audit_log
          WHERE audit_log.action = 'ticket_event_session.begin_wallet_drain'
            AND audit_log.target_table = 'ticket_event_sessions'
            AND audit_log.target_id = p_event_session_id
            AND audit_log.metadata_json ->> 'policyAuditId' = policy_audit.id::text
        )
    );
$$;

-- FUNCTION: ticket_auth_digest_equal_v29(text, text)
CREATE FUNCTION public.ticket_auth_digest_equal_v29(p_expected text, p_presented text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
DECLARE
  v_expected bytea;
  v_presented bytea;
  v_expected_length integer;
  v_presented_length integer;
  v_difference integer;
  v_index integer;
BEGIN
  IF p_expected IS NULL OR p_presented IS NULL
    OR octet_length(p_expected) > 256 OR octet_length(p_presented) > 256
  THEN
    RETURN false;
  END IF;

  v_expected := convert_to(p_expected, 'UTF8');
  v_presented := convert_to(p_presented, 'UTF8');
  v_expected_length := octet_length(v_expected);
  v_presented_length := octet_length(v_presented);
  v_difference := v_expected_length # v_presented_length;

  -- Always walk the full supported envelope rather than returning at the first
  -- different byte. The inputs are keyed HMAC encodings, never raw secrets.
  FOR v_index IN 0..255 LOOP
    v_difference := v_difference | (
      (CASE WHEN v_index < v_expected_length
        THEN get_byte(v_expected, v_index) ELSE 0 END)
      #
      (CASE WHEN v_index < v_presented_length
        THEN get_byte(v_presented, v_index) ELSE 0 END)
    );
  END LOOP;
  RETURN v_difference = 0;
END;
$$;

-- FUNCTION: ticket_daily_line_service_date_v41(timestamp with time zone)
CREATE FUNCTION public.ticket_daily_line_service_date_v41(p_now timestamp with time zone) RETURNS date
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  SELECT (p_now AT TIME ZONE 'Asia/Tokyo')::date
    - CASE WHEN (p_now AT TIME ZONE 'Asia/Tokyo')::time<time '23:30' THEN 1 ELSE 0 END
$$;

-- FUNCTION: ticket_entry_delivery_active_v53(uuid, jsonb)
CREATE FUNCTION public.ticket_entry_delivery_active_v53(p_order uuid, p_render jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT CASE WHEN NOT(p_render ? 'orderEntry') THEN true ELSE EXISTS(
  SELECT 1 FROM public.ticket_order_entry_links l JOIN public.ticket_event_sessions e ON e.id=l.event_session_id
  WHERE l.id::text=p_render#>>'{orderEntry,linkId}' AND l.ticket_order_id=p_order
   AND l.revoked_at IS NULL AND l.expires_at>clock_timestamp() AND public.ticket_admission_execution_closes_v56(e.id)>clock_timestamp()
   AND l.secret_ciphertext=p_render#>>'{orderEntry,ciphertext}') END;
$$;

-- FUNCTION: ticket_event_session_is_admission_open_v27(uuid, timestamp with time zone)
CREATE FUNCTION public.ticket_event_session_is_admission_open_v27(p_event_session_id uuid, p_observed_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.ticket_event_sessions AS session
    JOIN public.event_days AS event_day
      ON event_day.id = session.event_day_id
     AND event_day.business_date = session.event_date
    WHERE session.id = p_event_session_id
      AND session.enabled
      AND session.admission_state = 'scheduled'
      AND event_day.operating_status = 'open'
      AND p_observed_at >= public.ticket_admission_execution_opens_v56(session.id)
      AND p_observed_at < public.ticket_admission_execution_closes_v56(session.id)
  );
$$;

-- FUNCTION: ticket_group_entry_selection_v52(uuid, uuid[])
CREATE FUNCTION public.ticket_group_entry_selection_v52(p_order uuid, p_ids uuid[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT CASE WHEN o.admission_policy='individual_v1' THEN true ELSE
  cardinality(p_ids) BETWEEN 1 AND 20
  AND cardinality(p_ids)=(SELECT count(DISTINCT id) FROM unnest(p_ids) id)
  AND array_position(p_ids,NULL) IS NULL
  AND (SELECT count(*) FROM public.ticket_admissions a WHERE a.ticket_order_id=o.id)=o.total_quantity
  AND NOT EXISTS(SELECT 1 FROM public.ticket_admissions a WHERE a.ticket_order_id=o.id AND a.status NOT IN ('issued','void'))
  AND ARRAY(SELECT id FROM unnest(p_ids) id ORDER BY id)=ARRAY(SELECT a.id FROM public.ticket_admissions a WHERE a.ticket_order_id=o.id AND a.status='issued' ORDER BY a.id)
  END FROM public.ticket_orders o WHERE o.id=p_order;
$$;

-- FUNCTION: ticket_holder_has_order_v34(uuid, uuid)
CREATE FUNCTION public.ticket_holder_has_order_v34(p_holder_id uuid, p_order_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.ticket_holder_orders WHERE holder_id=p_holder_id AND ticket_order_id=p_order_id);
$$;

-- FUNCTION: ticket_order_has_settled_payment_v30(uuid)
CREATE FUNCTION public.ticket_order_has_settled_payment_v30(p_ticket_order_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.ticket_orders AS ticket_order
    JOIN public.ticket_checkout_actions AS checkout_action
      ON checkout_action.ticket_order_id = ticket_order.id
     AND checkout_action.event_session_id = ticket_order.event_session_id
     AND checkout_action.environment = ticket_order.environment
     AND checkout_action.stripe_account_key = ticket_order.stripe_account_key
     AND checkout_action.check_in_mode = ticket_order.check_in_mode
     AND checkout_action.checkout_session_id = ticket_order.checkout_session_id
    WHERE ticket_order.id = p_ticket_order_id
      AND ticket_order.check_in_mode = 'wallet_swipe'
      AND ticket_order.status = 'fulfilled'
      AND ticket_order.paid_at IS NOT NULL
      AND ticket_order.fulfilled_at IS NOT NULL
      AND NULLIF(btrim(COALESCE(ticket_order.checkout_session_id, '')), '') IS NOT NULL
      AND NULLIF(btrim(COALESCE(ticket_order.payment_intent_id, '')), '') IS NOT NULL
      AND ticket_order.payment_hold_reason IS NULL
      AND checkout_action.state = 'completed'
      AND checkout_action.completed_at IS NOT NULL
  );
$$;

-- FUNCTION: ticket_refund_observation_hash_v26(text, integer, text, integer[], boolean, text)
CREATE FUNCTION public.ticket_refund_observation_hash_v26(p_payment_intent_id text, p_amount_yen integer, p_provider_status text, p_input_admission_serials integer[], p_input_valid boolean, p_validation_reason text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(extensions.digest(pg_catalog.convert_to(pg_catalog.jsonb_build_object(
    'schemaVersion', 'ghost.ticket-refund-observation.v26',
    'paymentIntentId', p_payment_intent_id,
    'amountYen', p_amount_yen,
    'providerStatus', p_provider_status,
    'inputAdmissionSerials', pg_catalog.to_jsonb(COALESCE(p_input_admission_serials, '{}'::integer[])),
    'inputValid', p_input_valid,
    'validationReason', p_validation_reason
  )::text, 'UTF8'), 'sha256'), 'hex');
$$;

-- FUNCTION: ticket_wallet_gate_fence_v30()
CREATE FUNCTION public.ticket_wallet_gate_fence_v30() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ghost.ticket-wallet.gate-disable.v30', 0));
$$;

-- FUNCTION: ticket_wallet_gate_obligations_v30(uuid)
CREATE FUNCTION public.ticket_wallet_gate_obligations_v30(p_event_session_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH target_session AS MATERIALIZED (
    SELECT session.id, session.environment
    FROM public.ticket_event_sessions AS session
    WHERE session.id = p_event_session_id
  ), target_orders AS MATERIALIZED (
    SELECT ticket_order.*
    FROM public.ticket_orders AS ticket_order
    JOIN target_session ON target_session.id = ticket_order.event_session_id
    WHERE ticket_order.check_in_mode = 'wallet_swipe'
  ), target_identity AS MATERIALIZED (
    SELECT DISTINCT ticket_order.purchaser_email_hash AS identity_email_hash
    FROM target_orders AS ticket_order
    WHERE ticket_order.purchaser_email_hash IS NOT NULL
  )
  SELECT pg_catalog.jsonb_build_object(
    'walletOrders', (
      SELECT count(*)
      FROM target_orders AS ticket_order
      WHERE ticket_order.status IN ('pending', 'paid')
         OR ticket_order.payment_hold_reason IS NOT NULL
         OR EXISTS (
           SELECT 1 FROM public.ticket_admissions AS admission
           WHERE admission.ticket_order_id = ticket_order.id
             AND admission.status = 'issued')
    ) + (
      SELECT count(*) FROM target_orders o JOIN public.ticket_order_entry_links l ON l.ticket_order_id=o.id
      WHERE l.revoked_at IS NULL AND l.expires_at>clock_timestamp()
      AND o.status NOT IN ('pending','paid') AND o.payment_hold_reason IS NULL
      AND NOT EXISTS(SELECT 1 FROM public.ticket_admissions a WHERE a.ticket_order_id=o.id AND a.status='issued')
    ),
    'issuedAdmissions', (
      SELECT count(*)
      FROM public.ticket_admissions AS admission
      JOIN target_orders AS ticket_order ON ticket_order.id = admission.ticket_order_id
      WHERE admission.status = 'issued'
    ),
    'paidUnfulfilledOrders', (
      SELECT count(*)
      FROM target_orders AS ticket_order
      WHERE ticket_order.paid_at IS NOT NULL
        AND (
          ticket_order.fulfilled_at IS NULL
          OR ticket_order.status = 'paid'
          OR ticket_order.total_quantity <> (
            SELECT count(*) FROM public.ticket_admissions AS admission
            WHERE admission.ticket_order_id = ticket_order.id)
        )
    ),
    'checkoutActions', (
      SELECT count(*)
      FROM public.ticket_checkout_actions AS checkout_action
      WHERE checkout_action.event_session_id = p_event_session_id
        AND checkout_action.state IN (
          'initializing', 'claimed', 'provider_created', 'review_required')
    ),
    'checkoutRecoveryClaims', (
      SELECT count(*)
      FROM public.ticket_checkout_actions AS checkout_action
      WHERE checkout_action.event_session_id = p_event_session_id
        AND (
          checkout_action.recovery_claim_token IS NOT NULL
          OR checkout_action.state = 'review_required'
        )
    ),
    'activeSessions', (
      SELECT count(DISTINCT wallet_session.id)
      FROM public.ticket_wallet_sessions AS wallet_session
      JOIN target_identity AS identity
        ON identity.identity_email_hash = wallet_session.identity_email_hash
      JOIN target_session ON target_session.environment = wallet_session.environment
      WHERE wallet_session.revoked_at IS NULL
        AND wallet_session.expires_at > clock_timestamp()
    ) + (
      SELECT count(*) FROM public.ticket_order_entry_sessions s JOIN public.ticket_order_entry_links l ON l.id=s.link_id
      WHERE l.event_session_id=p_event_session_id AND l.revoked_at IS NULL AND l.expires_at>clock_timestamp() AND s.expires_at>clock_timestamp()
    ),
    'otpChallenges', (
      SELECT count(DISTINCT challenge.id)
      FROM public.ticket_wallet_otp_challenges AS challenge
      JOIN target_identity AS identity
        ON identity.identity_email_hash = challenge.identity_email_hash
      JOIN target_session ON target_session.environment = challenge.environment
      WHERE NOT challenge.is_decoy
        AND challenge.state IN ('pending', 'sending', 'sent')
    ),
    'admissionOperations', (
      SELECT count(*)
      FROM public.ticket_admission_operations AS operation
      WHERE operation.event_session_id = p_event_session_id
        AND operation.state IN ('initializing', 'prepared')
    ) + (
      SELECT count(*) FROM public.ticket_order_entry_operations op JOIN public.ticket_order_entry_sessions s ON s.id=op.order_session_id
      JOIN public.ticket_order_entry_links l ON l.id=s.link_id WHERE l.event_session_id=p_event_session_id
      AND op.state='prepared' AND op.expires_at>clock_timestamp() AND l.revoked_at IS NULL AND l.expires_at>clock_timestamp() AND s.expires_at>clock_timestamp()
    ),
    'admissionChallenges', (
      SELECT count(*)
      FROM public.ticket_admission_challenges AS challenge
      WHERE challenge.event_session_id = p_event_session_id
        AND challenge.state = 'active'
    ),
    'emailJobs', (
      SELECT count(DISTINCT job.id)
      FROM public.transactional_email_jobs AS job
      JOIN public.ticket_wallet_otp_challenges AS challenge
        ON challenge.id = job.otp_challenge_id
      JOIN target_identity AS identity
        ON identity.identity_email_hash = challenge.identity_email_hash
      JOIN target_session ON target_session.environment = challenge.environment
      WHERE NOT challenge.is_decoy
        AND job.state IN ('pending', 'processing', 'retry')
    ) + (
      SELECT count(*) FROM public.transactional_email_jobs j JOIN target_orders o ON o.id=j.ticket_order_id
      WHERE j.purpose='ticket_wallet_purchase' AND j.state IN ('pending','processing','retry')
    ) + (
      SELECT count(*) FROM public.ticket_purchase_notices n JOIN target_orders o ON o.id=n.ticket_order_id
      WHERE n.materialized_at IS NULL
    ),
    'legacyEmailJobs', (
      SELECT count(*)
      FROM public.notification_jobs AS job
      JOIN target_orders AS ticket_order ON ticket_order.id = job.ticket_order_id
      WHERE job.channel = 'email'
        AND job.status IN ('pending', 'processing', 'retry', 'dead')
    ),
    -- Provider correlation defects have no trustworthy event/environment
    -- authority. Until retained evidence is reviewed or expires, they block
    -- every customer-gate disable rather than being guessed foreign.
    'emailProviderSecurityReviews', (
      SELECT count(*)
      FROM public.transactional_email_provider_events AS provider_event
      WHERE provider_event.security_review_required
    ),
    -- A queued Stripe event with no complete ticket binding cannot safely be
    -- classified as foreign. Environment is the strongest signed authority
    -- available before the worker resolves its payload.
    'stripeWebhookEvents', (
      SELECT count(*)
      FROM public.webhook_events AS webhook_event
      JOIN target_session ON target_session.environment = webhook_event.environment
      WHERE webhook_event.processing_status IN ('received', 'processing', 'retry', 'dead')
    ),
    'refundReviews', (
      SELECT count(*)
      FROM public.ticket_refund_events AS refund
      JOIN target_orders AS ticket_order ON ticket_order.id = refund.ticket_order_id
      WHERE refund.resolved_at IS NULL
        AND (
          refund.resolution_status IN ('review_required', 'conflict_review')
          OR refund.observation_history_state = 'legacy_incomplete'
        )
    )
  );
$$;

-- FUNCTION: transition_admin_waitlist_entry_v11(uuid, text, text, text, uuid, bigint, text, uuid, text)
CREATE FUNCTION public.transition_admin_waitlist_entry_v11(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_waitlist_entry_id uuid, p_expected_version bigint, p_to_status text, p_seated_reservation_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_target text := lower(btrim(COALESCE(p_to_status, '')));
  v_action text;
  v_step jsonb;
  v_entry public.vip_waitlist_entries%ROWTYPE;
  v_version bigint;
  v_called_at timestamptz;
  v_expires_at timestamptz;
  v_job_id uuid;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_action := 'waitlist.' || v_target;
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.admin_users
      WHERE id = p_actor_admin_id AND active = true AND role = 'owner'
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', CASE WHEN EXISTS (
            SELECT 1 FROM public.admin_users WHERE id = p_actor_admin_id AND active = true
          ) THEN 'FORBIDDEN' ELSE 'UNAUTHENTICATED' END,
          'details', jsonb_build_object('capability', 'owner')
        )), ARRAY['allowed']
      );
    END IF;

    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_reason <> '管理画面操作'
      OR p_expected_version IS NULL OR p_expected_version < 1
      OR v_target NOT IN ('called', 'expired', 'seated', 'cancelled')
      OR (v_target = 'seated') <> (p_seated_reservation_id IS NOT NULL)
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND',
          'details', jsonb_build_object('field', 'waitlistTransition')
        )), ARRAY['allowed']
      );
    END IF;

    SELECT * INTO v_entry
    FROM public.vip_waitlist_entries
    WHERE id = p_waitlist_entry_id
    FOR UPDATE;
    IF NOT FOUND THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'NOT_FOUND', 'details', jsonb_build_object('entityType', 'waitlist')
        )), ARRAY['allowed']
      );
    END IF;
    IF v_entry.version <> p_expected_version THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'VERSION_CONFLICT',
          'currentVersion', v_entry.version,
          'details', '{}'::jsonb
        )), ARRAY['allowed']
      );
    END IF;
    IF v_entry.status IN ('expired', 'seated', 'cancelled')
      OR (v_target = 'expired' AND v_entry.status <> 'called')
      OR (v_target = 'seated' AND v_entry.status <> 'called')
      OR (v_target = 'called' AND v_entry.status NOT IN ('waiting', 'called'))
      OR (v_target = 'cancelled' AND v_entry.status NOT IN ('waiting', 'called'))
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION',
          'details', jsonb_build_object('fromStatus', v_entry.status, 'toStatus', v_target)
        )), ARRAY['allowed']
      );
    END IF;
    IF v_target = 'seated' AND NOT EXISTS (
      SELECT 1 FROM public.reservations
      WHERE id = p_seated_reservation_id
        AND event_day_id = v_entry.event_day_id
        AND status = 'confirmed'
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'NOT_FOUND',
          'details', jsonb_build_object('entityType', 'reservation')
        )), ARRAY['allowed']
      );
    END IF;

    v_called_at := CASE WHEN v_target = 'called' THEN clock_timestamp() ELSE v_entry.called_at END;
    v_expires_at := CASE
      WHEN v_target = 'called' THEN v_called_at + interval '30 minutes'
      ELSE v_entry.call_expires_at
    END;
    UPDATE public.vip_waitlist_entries
    SET status = v_target,
        called_at = v_called_at,
        call_expires_at = v_expires_at,
        seated_reservation_id = p_seated_reservation_id,
        updated_by_admin_id = p_actor_admin_id,
        version = version + 1,
        updated_at = now()
    WHERE id = v_entry.id
    RETURNING version INTO v_version;

    IF v_target = 'called' AND v_entry.email_ciphertext IS NOT NULL THEN
      INSERT INTO public.notification_jobs(
        reservation_id,
        waitlist_entry_id,
        channel,
        status,
        payload_json,
        attempt_count,
        next_attempt_at
      )
      VALUES (
        NULL,
        v_entry.id,
        'email',
        'pending',
        jsonb_build_object(
          'schemaVersion', 'ghost.vip-email.v1',
          'template', CASE WHEN v_entry.status = 'called'
            THEN 'waitlist_recalled' ELSE 'waitlist_called' END,
          'waitlistEntryId', v_entry.id
        ),
        0,
        now()
      )
      RETURNING id INTO v_job_id;
    END IF;

    INSERT INTO public.audit_logs(
      actor_admin_id, actor_type, action, target_table, target_id, request_id,
      before_json, after_json, reason, event_day_id, reservation_id,
      entity_type, entity_id, operation, expected_version, version_before,
      version_after, changed_fields, metadata_json, source_contract
    )
    VALUES (
      p_actor_admin_id, 'admin', v_action, 'vip_waitlist_entries', v_entry.id, p_request_id,
      jsonb_build_object('status', v_entry.status, 'version', v_entry.version),
      jsonb_build_object(
        'status', v_target,
        'version', v_version,
        'callExpiresAt', v_expires_at,
        'seatedReservationId', p_seated_reservation_id
      ),
      p_reason, v_entry.event_day_id, p_seated_reservation_id,
      'waitlist', v_entry.id, v_action, p_expected_version, v_entry.version,
      v_version,
      ARRAY['status', 'called_at', 'call_expires_at', 'seated_reservation_id'],
      jsonb_build_object(
        'notificationJobId', v_job_id,
        'notificationEnqueued', v_job_id IS NOT NULL,
        'contactMaterialStoredInAudit', false
      ),
      'ghost.vip-manager.v2'
    )
    RETURNING id INTO v_audit_id;

    PERFORM public.lock_vip_floor_day_revision_v32(v_entry.event_day_id);
    SELECT COALESCE(revision, 0) + 1
    INTO v_predicted_revision
    FROM public.vip_floor_day_revisions
    WHERE event_day_id = v_entry.event_day_id;
    v_predicted_revision := COALESCE(v_predicted_revision, 1);
    v_response := jsonb_build_object(
      'ok', true,
      'action', v_action,
      'reused', false,
      'waitlistEntryId', v_entry.id,
      'entityVersion', v_version,
      'boardRevision', v_predicted_revision,
      'auditLogId', v_audit_id,
      'status', v_target,
      'callExpiresAt', v_expires_at,
      'notificationJobId', v_job_id
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(v_entry.event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION 'waitlist revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: transition_claimed_waitlist_entry_v32(uuid, text, text, text, uuid, bigint, text, uuid, text)
CREATE FUNCTION public.transition_claimed_waitlist_entry_v32(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_waitlist_entry_id uuid, p_expected_version bigint, p_to_status text, p_seated_reservation_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_target text := lower(btrim(COALESCE(p_to_status, '')));
  v_action text;
  v_step jsonb;
  v_entry public.vip_waitlist_entries%ROWTYPE;
  v_version bigint;
  v_called_at timestamptz;
  v_expires_at timestamptz;
  v_job_id uuid;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_action := 'waitlist.' || v_target;

    IF NOT EXISTS (
      SELECT 1 FROM public.admin_users
      WHERE id = p_actor_admin_id AND active = true AND role = 'owner'
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', CASE WHEN EXISTS (
            SELECT 1 FROM public.admin_users WHERE id = p_actor_admin_id AND active = true
          ) THEN 'FORBIDDEN' ELSE 'UNAUTHENTICATED' END,
          'details', jsonb_build_object('capability', 'owner')
        )), ARRAY['allowed']
      );
    END IF;

    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_reason <> '管理画面操作'
      OR p_expected_version IS NULL OR p_expected_version < 1
      OR v_target NOT IN ('called', 'expired', 'seated', 'cancelled')
      OR (v_target = 'seated') <> (p_seated_reservation_id IS NOT NULL)
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND',
          'details', jsonb_build_object('field', 'waitlistTransition')
        )), ARRAY['allowed']
      );
    END IF;

    SELECT * INTO v_entry
    FROM public.vip_waitlist_entries
    WHERE id = p_waitlist_entry_id
    FOR UPDATE;
    IF NOT FOUND THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'NOT_FOUND', 'details', jsonb_build_object('entityType', 'waitlist')
        )), ARRAY['allowed']
      );
    END IF;
    IF v_entry.version <> p_expected_version THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'VERSION_CONFLICT',
          'currentVersion', v_entry.version,
          'details', '{}'::jsonb
        )), ARRAY['allowed']
      );
    END IF;
    IF v_entry.status IN ('expired', 'seated', 'cancelled')
      OR (v_target = 'expired' AND v_entry.status <> 'called')
      OR (v_target = 'seated' AND v_entry.status <> 'called')
      OR (v_target = 'called' AND v_entry.status NOT IN ('waiting', 'called'))
      OR (v_target = 'cancelled' AND v_entry.status NOT IN ('waiting', 'called'))
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION',
          'details', jsonb_build_object('fromStatus', v_entry.status, 'toStatus', v_target)
        )), ARRAY['allowed']
      );
    END IF;
    IF v_target = 'seated' AND NOT EXISTS (
      SELECT 1 FROM public.reservations
      WHERE id = p_seated_reservation_id
        AND event_day_id = v_entry.event_day_id
        AND status = 'confirmed'
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'NOT_FOUND',
          'details', jsonb_build_object('entityType', 'reservation')
        )), ARRAY['allowed']
      );
    END IF;

    v_called_at := CASE WHEN v_target = 'called' THEN clock_timestamp() ELSE v_entry.called_at END;
    v_expires_at := CASE
      WHEN v_target = 'called' THEN v_called_at + interval '30 minutes'
      ELSE v_entry.call_expires_at
    END;
    UPDATE public.vip_waitlist_entries
    SET status = v_target,
        called_at = v_called_at,
        call_expires_at = v_expires_at,
        seated_reservation_id = p_seated_reservation_id,
        updated_by_admin_id = p_actor_admin_id,
        version = version + 1,
        updated_at = now()
    WHERE id = v_entry.id
    RETURNING version INTO v_version;

    IF v_target = 'called' AND v_entry.email_ciphertext IS NOT NULL THEN
      INSERT INTO public.notification_jobs(
        reservation_id,
        waitlist_entry_id,
        channel,
        status,
        payload_json,
        attempt_count,
        next_attempt_at
      )
      VALUES (
        NULL,
        v_entry.id,
        'email',
        'pending',
        jsonb_build_object(
          'schemaVersion', 'ghost.vip-email.v1',
          'template', CASE WHEN v_entry.status = 'called'
            THEN 'waitlist_recalled' ELSE 'waitlist_called' END,
          'waitlistEntryId', v_entry.id
        ),
        0,
        now()
      )
      RETURNING id INTO v_job_id;
    END IF;

    INSERT INTO public.audit_logs(
      actor_admin_id, actor_type, action, target_table, target_id, request_id,
      before_json, after_json, reason, event_day_id, reservation_id,
      entity_type, entity_id, operation, expected_version, version_before,
      version_after, changed_fields, metadata_json, source_contract
    )
    VALUES (
      p_actor_admin_id, 'admin', v_action, 'vip_waitlist_entries', v_entry.id, p_request_id,
      jsonb_build_object('status', v_entry.status, 'version', v_entry.version),
      jsonb_build_object(
        'status', v_target,
        'version', v_version,
        'callExpiresAt', v_expires_at,
        'seatedReservationId', p_seated_reservation_id
      ),
      p_reason, v_entry.event_day_id, p_seated_reservation_id,
      'waitlist', v_entry.id, v_action, p_expected_version, v_entry.version,
      v_version,
      ARRAY['status', 'called_at', 'call_expires_at', 'seated_reservation_id'],
      jsonb_build_object(
        'notificationJobId', v_job_id,
        'notificationEnqueued', v_job_id IS NOT NULL,
        'contactMaterialStoredInAudit', false
      ),
      'ghost.vip-manager.v2'
    )
    RETURNING id INTO v_audit_id;

    PERFORM public.lock_vip_floor_day_revision_v32(v_entry.event_day_id);
    SELECT COALESCE(revision, 0) + 1
    INTO v_predicted_revision
    FROM public.vip_floor_day_revisions
    WHERE event_day_id = v_entry.event_day_id;
    v_predicted_revision := COALESCE(v_predicted_revision, 1);
    v_response := jsonb_build_object(
      'ok', true,
      'action', v_action,
      'reused', false,
      'waitlistEntryId', v_entry.id,
      'entityVersion', v_version,
      'boardRevision', v_predicted_revision,
      'auditLogId', v_audit_id,
      'status', v_target,
      'callExpiresAt', v_expires_at,
      'notificationJobId', v_job_id
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(v_entry.event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION 'waitlist revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: update_admin_customer_attributes_v14(uuid, text, text, text, uuid, uuid, uuid, bigint, text, date, date, text, text)
CREATE FUNCTION public.update_admin_customer_attributes_v14(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_day_id uuid, p_reservation_id uuid, p_customer_id uuid, p_expected_profile_version bigint, p_nationality_code text, p_birth_date date, p_anniversary_date date, p_vip_rank text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_action constant text := 'customer_profile.attributes_updated';
  v_step jsonb;
  v_profile public.customer_profiles%ROWTYPE;
  v_nationality_code text := NULLIF(upper(btrim(COALESCE(p_nationality_code, ''))), '');
  v_vip_rank text := NULLIF(btrim(COALESCE(p_vip_rank, '')), '');
  v_new_version bigint;
  v_audit_id uuid;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    IF NOT EXISTS (
      SELECT 1 FROM public.admin_users
      WHERE id = p_actor_admin_id AND active = true AND role = 'owner'
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object('code', 'FORBIDDEN')
        ),
        ARRAY['allowed']
      );
    END IF;
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_event_day_id IS NULL
      OR p_reservation_id IS NULL
      OR p_customer_id IS NULL
      OR p_expected_profile_version IS NULL OR p_expected_profile_version < 1
      OR (v_nationality_code IS NOT NULL AND v_nationality_code !~ '^[A-Z]{2}$')
      OR char_length(COALESCE(v_vip_rank, '')) > 32
      OR (p_birth_date IS NOT NULL AND p_birth_date > CURRENT_DATE)
      OR p_reason <> '管理画面操作'
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'customerAttributes')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.reservations
      WHERE id = p_reservation_id
        AND event_day_id = p_event_day_id
        AND customer_id = p_customer_id
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'NOT_FOUND',
            'details', jsonb_build_object('entityType', 'reservation_customer_context')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    SELECT * INTO v_profile
    FROM public.customer_profiles
    WHERE customer_id = p_customer_id
    FOR UPDATE;
    IF NOT FOUND THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'NOT_FOUND',
            'details', jsonb_build_object('entityType', 'customer_profile')
          )
        ),
        ARRAY['allowed']
      );
    END IF;
    IF v_profile.version <> p_expected_profile_version THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'VERSION_CONFLICT',
            'currentVersion', v_profile.version,
            'details', jsonb_build_object('entityType', 'customer_profile')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    UPDATE public.customer_profiles
    SET nationality_code = v_nationality_code,
        birth_date = p_birth_date,
        anniversary_date = p_anniversary_date,
        vip_rank = v_vip_rank,
        version = version + 1,
        updated_at = now()
    WHERE customer_id = p_customer_id
    RETURNING version INTO v_new_version;

    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, p_event_day_id, p_reservation_id,
      'customer', p_customer_id, v_action,
      p_request_id, p_reason,
      p_expected_profile_version, v_profile.version, v_new_version,
      ARRAY[
        'nationality_code', 'birth_date', 'anniversary_date', 'vip_rank', 'version'
      ],
      jsonb_build_object(
        'version', v_profile.version,
        'attributePresenceCount',
          (v_profile.nationality_code IS NOT NULL)::int
          + (v_profile.birth_date IS NOT NULL)::int
          + (v_profile.anniversary_date IS NOT NULL)::int
          + (v_profile.vip_rank IS NOT NULL)::int
      ),
      jsonb_build_object(
        'version', v_new_version,
        'attributePresenceCount',
          (v_nationality_code IS NOT NULL)::int
          + (p_birth_date IS NOT NULL)::int
          + (p_anniversary_date IS NOT NULL)::int
          + (v_vip_rank IS NOT NULL)::int
      ),
      jsonb_build_object('attributeOnly', true)
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_step := public.bump_vip_floor_day_revision_v8(p_event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;

    v_response := jsonb_build_object(
      'ok', true,
      'action', v_action,
      'reused', false,
      'customerId', p_customer_id,
      'entityVersion', v_new_version,
      'boardRevision', v_revision,
      'auditLogId', v_audit_id
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$_$;

-- FUNCTION: update_admin_reservation_block_v8(uuid, text, text, text, uuid, bigint, text, text, timestamp with time zone, timestamp with time zone, text, uuid[], uuid[], boolean, text)
CREATE FUNCTION public.update_admin_reservation_block_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_block_id uuid, p_expected_version bigint, p_scope text, p_kind text, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_memo text, p_seat_resource_ids uuid[], p_floor_section_ids uuid[], p_venue_wide boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation_block.updated';
  v_scope text := lower(btrim(COALESCE(p_scope, '')));
  v_kind text := lower(btrim(COALESCE(p_kind, '')));
  v_step jsonb;
  v_block public.reservation_blocks%ROWTYPE;
  v_table_ids uuid[];
  v_section_ids uuid[];
  v_old_seat_ids uuid[];
  v_old_table_ids uuid[];
  v_old_section_ids uuid[];
  v_old_venue_wide boolean;
  v_new_seat_ids uuid[];
  v_lock_seat_ids uuid[];
  v_conflict record;
  v_new_version bigint;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;
    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(p_actor_admin_id, 'reservation_block.write'),
      ARRAY['allowed']
    );

    SELECT * INTO v_block FROM public.reservation_blocks WHERE id = p_block_id;
    IF NOT FOUND THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'NOT_FOUND', 'details', jsonb_build_object('entityType', 'block')
        )), ARRAY['allowed']
      );
    END IF;
    SELECT COALESCE(array_agg(DISTINCT id ORDER BY id), '{}'::uuid[])
    INTO v_table_ids FROM unnest(COALESCE(p_seat_resource_ids, '{}'::uuid[])) AS requested(id);
    SELECT COALESCE(array_agg(DISTINCT id ORDER BY id), '{}'::uuid[])
    INTO v_section_ids FROM unnest(COALESCE(p_floor_section_ids, '{}'::uuid[])) AS requested(id);
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_expected_version IS NULL OR p_expected_version < 1
      OR v_scope NOT IN ('online_only', 'all_operations')
      OR v_kind NOT IN ('manual', 'maintenance', 'owner_hold', 'event', 'unassignment_guard')
      OR p_start_at IS NULL OR p_end_at IS NULL OR p_start_at >= p_end_at
      OR EXISTS (SELECT 1 FROM unnest(COALESCE(p_seat_resource_ids, '{}'::uuid[])) AS t(id) WHERE id IS NULL)
      OR EXISTS (SELECT 1 FROM unnest(COALESCE(p_floor_section_ids, '{}'::uuid[])) AS s(id) WHERE id IS NULL)
      OR cardinality(v_table_ids) <> cardinality(COALESCE(p_seat_resource_ids, '{}'::uuid[]))
      OR cardinality(v_section_ids) <> cardinality(COALESCE(p_floor_section_ids, '{}'::uuid[]))
      OR (COALESCE(p_venue_wide, false) AND (cardinality(v_table_ids) > 0 OR cardinality(v_section_ids) > 0))
      OR (NOT COALESCE(p_venue_wide, false) AND cardinality(v_table_ids) = 0 AND cardinality(v_section_ids) = 0)
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'blockCommand')
        )), ARRAY['allowed']
      );
    END IF;
    IF v_block.status <> 'active' THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_STATE_TRANSITION', 'details', jsonb_build_object('reason', 'block_not_active')
        )), ARRAY['allowed']
      );
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.event_days AS ed
      WHERE ed.id = v_block.event_day_id
        AND ed.sales_open_at <= p_start_at
        AND ed.sales_close_at >= p_end_at
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'schedule', 'reason', 'outside_business_day')
        )), ARRAY['allowed']
      );
    END IF;
    IF (SELECT count(*) FROM public.floor_sections WHERE id = ANY(v_section_ids)) <> cardinality(v_section_ids) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'NOT_FOUND', 'details', jsonb_build_object('entityType', 'floor_section')
        )), ARRAY['allowed']
      );
    END IF;

    SELECT COALESCE(array_agg(sr.id ORDER BY sr.id), '{}'::uuid[])
    INTO v_old_seat_ids
    FROM public.seat_resources AS sr
    WHERE EXISTS (
      SELECT 1 FROM public.reservation_block_targets AS rbt
      WHERE rbt.block_id = v_block.id
        AND (rbt.seat_resource_id = sr.id OR rbt.floor_section_id = sr.floor_section_id OR rbt.venue_wide)
    );
    SELECT
      COALESCE(array_agg(rbt.seat_resource_id ORDER BY rbt.seat_resource_id)
        FILTER (WHERE rbt.seat_resource_id IS NOT NULL), '{}'::uuid[]),
      COALESCE(array_agg(rbt.floor_section_id ORDER BY rbt.floor_section_id)
        FILTER (WHERE rbt.floor_section_id IS NOT NULL), '{}'::uuid[]),
      COALESCE(bool_or(rbt.venue_wide), false)
    INTO v_old_table_ids, v_old_section_ids, v_old_venue_wide
    FROM public.reservation_block_targets AS rbt
    WHERE rbt.block_id = v_block.id;
    SELECT COALESCE(array_agg(sr.id ORDER BY sr.id), '{}'::uuid[])
    INTO v_new_seat_ids
    FROM public.seat_resources AS sr
    WHERE COALESCE(p_venue_wide, false)
       OR sr.id = ANY(v_table_ids)
       OR sr.floor_section_id = ANY(v_section_ids);
    IF EXISTS (SELECT 1 FROM unnest(v_table_ids) AS t(id) WHERE NOT (id = ANY(v_new_seat_ids))) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'NOT_FOUND', 'details', jsonb_build_object('entityType', 'table')
        )), ARRAY['allowed']
      );
    END IF;
    v_lock_seat_ids := ARRAY(
      SELECT DISTINCT id FROM unnest(v_old_seat_ids || v_new_seat_ids) AS target(id) ORDER BY id
    );

    PERFORM sr.id FROM public.seat_resources AS sr
    WHERE sr.id = ANY(v_lock_seat_ids)
    ORDER BY sr.id FOR UPDATE OF sr;
    PERFORM rr.id
    FROM public.reservation_resources AS rr
    WHERE rr.seat_resource_id = ANY(v_lock_seat_ids)
      AND rr.assigned_start_at < GREATEST(v_block.end_at, p_end_at)
      AND rr.assigned_end_at > LEAST(v_block.start_at, p_start_at)
    ORDER BY rr.id FOR UPDATE OF rr;
    PERFORM rb.id
    FROM public.reservation_blocks AS rb
    WHERE rb.id = v_block.id
       OR (
         rb.event_day_id = v_block.event_day_id
         AND rb.status = 'active'
         AND rb.start_at < GREATEST(v_block.end_at, p_end_at)
         AND rb.end_at > LEAST(v_block.start_at, p_start_at)
         AND EXISTS (
           SELECT 1 FROM public.reservation_block_targets AS rbt
           JOIN public.seat_resources AS sr ON sr.id = ANY(v_lock_seat_ids)
           WHERE rbt.block_id = rb.id
             AND (rbt.seat_resource_id = sr.id OR rbt.floor_section_id = sr.floor_section_id OR rbt.venue_wide)
         )
       )
    ORDER BY rb.id FOR UPDATE OF rb;

    SELECT * INTO v_block FROM public.reservation_blocks WHERE id = p_block_id;
    IF v_block.version <> p_expected_version THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'VERSION_CONFLICT', 'currentVersion', v_block.version, 'details', '{}'::jsonb
        )), ARRAY['allowed']
      );
    END IF;

    IF v_scope = 'all_operations' THEN
      SELECT rr.id, r.public_code, sr.display_code, rr.assigned_start_at, rr.assigned_end_at
      INTO v_conflict
      FROM public.reservation_resources AS rr
      JOIN public.reservations AS r ON r.id = rr.reservation_id
      JOIN public.seat_resources AS sr ON sr.id = rr.seat_resource_id
      WHERE rr.seat_resource_id = ANY(v_new_seat_ids)
        AND rr.assigned_start_at < p_end_at
        AND rr.assigned_end_at > p_start_at
        AND public.active_reservation_assignment_v8(rr.id, now())
      ORDER BY rr.id LIMIT 1;
      IF FOUND THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
            'code', 'TABLE_TIME_CONFLICT', 'details', jsonb_build_object(
              'tableDisplayCode', v_conflict.display_code,
              'conflictingReservationPublicCode', v_conflict.public_code,
              'conflictingStartAt', v_conflict.assigned_start_at,
              'conflictingEndAt', v_conflict.assigned_end_at
            )
          )), ARRAY['allowed']
        );
      END IF;
    END IF;

    IF (v_block.scope, v_block.kind, v_block.start_at, v_block.end_at, v_block.memo)
        IS NOT DISTINCT FROM (
          v_scope, v_kind, p_start_at, p_end_at,
          NULLIF(btrim(COALESCE(p_memo, '')), '')
        )
      AND v_old_table_ids = v_table_ids
      AND v_old_section_ids = v_section_ids
      AND v_old_venue_wide = COALESCE(p_venue_wide, false)
    THEN
      PERFORM ed.id FROM public.event_days AS ed
      WHERE ed.id = v_block.event_day_id FOR KEY SHARE OF ed;
      PERFORM public.lock_vip_floor_day_revision_v32(v_block.event_day_id);
    SELECT COALESCE(vfr.revision, 0) INTO v_predicted_revision
      FROM (SELECT 1) AS seed LEFT JOIN public.vip_floor_day_revisions AS vfr
        ON vfr.event_day_id = v_block.event_day_id;
      v_step := public.append_vip_floor_audit_v8(
        p_actor_admin_id, v_block.event_day_id, NULL,
        'block', v_block.id, v_action || '.noop', p_request_id, p_reason,
        NULL, NULL, NULL, '{}'::text[],
        jsonb_build_object(
          'scope', v_block.scope, 'kind', v_block.kind,
          'startAt', v_block.start_at, 'endAt', v_block.end_at,
          'version', v_block.version
        ),
        jsonb_build_object(
          'scope', v_block.scope, 'kind', v_block.kind,
          'startAt', v_block.start_at, 'endAt', v_block.end_at,
          'version', v_block.version
        ), '{}'::jsonb
      );
      PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
      v_audit_id := (v_step ->> 'auditLogId')::uuid;
      v_response := jsonb_build_object(
        'ok', true, 'action', v_action, 'reused', false,
        'blockId', v_block.id, 'entityVersion', v_block.version,
        'boardRevision', v_predicted_revision, 'auditLogId', v_audit_id,
        'noOp', true
      );
      PERFORM public.complete_admin_action_request_v8(
        p_actor_admin_id, v_action, p_idempotency_key, v_response
      );
      RETURN v_response;
    END IF;

    UPDATE public.reservation_blocks
    SET scope = v_scope, kind = v_kind, start_at = p_start_at, end_at = p_end_at,
        memo = NULLIF(btrim(COALESCE(p_memo, '')), ''),
        version = version + 1, updated_at = now()
    WHERE id = v_block.id
    RETURNING version INTO v_new_version;
    DELETE FROM public.reservation_block_targets WHERE block_id = v_block.id;
    INSERT INTO public.reservation_block_targets(block_id, seat_resource_id)
    SELECT v_block.id, table_target.id
    FROM unnest(v_table_ids) AS table_target(id)
    ORDER BY table_target.id;
    INSERT INTO public.reservation_block_targets(block_id, floor_section_id)
    SELECT v_block.id, section_target.id
    FROM unnest(v_section_ids) AS section_target(id)
    ORDER BY section_target.id;
    IF COALESCE(p_venue_wide, false) THEN
      INSERT INTO public.reservation_block_targets(block_id, venue_wide) VALUES (v_block.id, true);
    END IF;

    PERFORM ed.id FROM public.event_days AS ed
    WHERE ed.id = v_block.event_day_id FOR KEY SHARE OF ed;
    PERFORM public.lock_vip_floor_day_revision_v32(v_block.event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1 INTO v_predicted_revision
    FROM (SELECT 1) AS seed
    LEFT JOIN public.vip_floor_day_revisions AS vfr ON vfr.event_day_id = v_block.event_day_id;
    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, v_block.event_day_id, NULL,
      'block', v_block.id, v_action, p_request_id, p_reason,
      p_expected_version, v_block.version, v_new_version,
      ARRAY['scope', 'kind', 'start_at', 'end_at', 'targets', 'version'],
      jsonb_build_object(
        'scope', v_block.scope, 'kind', v_block.kind,
        'startAt', v_block.start_at, 'endAt', v_block.end_at, 'version', v_block.version
      ),
      jsonb_build_object(
        'scope', v_scope, 'kind', v_kind,
        'startAt', p_start_at, 'endAt', p_end_at, 'version', v_new_version
      ),
      jsonb_build_object(
        'tableCount', cardinality(v_table_ids),
        'sectionCount', cardinality(v_section_ids),
        'venueWide', COALESCE(p_venue_wide, false)
      )
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_response := jsonb_build_object(
      'ok', true, 'action', v_action, 'reused', false,
      'blockId', v_block.id, 'entityVersion', v_new_version,
      'boardRevision', v_predicted_revision, 'auditLogId', v_audit_id
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(v_block.event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'XX000', MESSAGE = 'VIP floor revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS v_error_detail = PG_EXCEPTION_DETAIL, v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN RETURN v_error_detail::jsonb; END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: update_admin_reservation_v14(uuid, text, text, text, uuid, bigint, uuid, timestamp with time zone, timestamp with time zone, integer, uuid[], jsonb, text, text, text, public.vip_service_status, uuid, text, boolean, text)
CREATE FUNCTION public.update_admin_reservation_v14(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_version bigint, p_booking_offering_id uuid, p_scheduled_start_at timestamp with time zone, p_scheduled_end_at timestamp with time zone, p_guest_count integer, p_table_ids uuid[], p_expected_table_versions jsonb, p_guest_label text, p_operator_note text, p_source_channel text, p_service_status public.vip_service_status, p_booking_staff_member_id uuid, p_notification_preference text, p_capacity_override boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_action constant text := 'reservation.updated';
  v_step jsonb;
  v_reservation public.reservations%ROWTYPE;
  v_offering public.booking_offerings%ROWTYPE;
  v_table_ids uuid[];
  v_old_table_ids uuid[];
  v_lock_table_ids uuid[];
  v_table_id uuid;
  v_expected_table_version bigint;
  v_capacity int;
  v_assignment public.reservation_resources%ROWTYPE;
  v_role text;
  v_new_version bigint;
  v_audit_id uuid;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    IF NOT EXISTS (
      SELECT 1 FROM public.admin_users
      WHERE id = p_actor_admin_id AND active = true AND role = 'owner'
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object('code', 'FORBIDDEN')
        ),
        ARRAY['allowed']
      );
    END IF;

    SELECT COALESCE(array_agg(DISTINCT id ORDER BY id), '{}'::uuid[])
    INTO v_table_ids
    FROM unnest(COALESCE(p_table_ids, '{}'::uuid[])) AS requested(id);

    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_reservation_id IS NULL
      OR p_expected_version IS NULL OR p_expected_version < 1
      OR p_booking_offering_id IS NULL
      OR p_scheduled_start_at IS NULL OR p_scheduled_end_at IS NULL
      OR p_scheduled_start_at >= p_scheduled_end_at
      OR p_guest_count IS NULL OR p_guest_count < 1 OR p_guest_count > 99
      OR cardinality(v_table_ids) = 0 OR cardinality(v_table_ids) > 8
      OR cardinality(v_table_ids) <> cardinality(COALESCE(p_table_ids, '{}'::uuid[]))
      OR p_expected_table_versions IS NULL
      OR jsonb_typeof(p_expected_table_versions) <> 'array'
      OR jsonb_array_length(p_expected_table_versions) <> cardinality(v_table_ids)
      OR char_length(COALESCE(p_guest_label, '')) > 80
      OR char_length(COALESCE(p_operator_note, '')) > 500
      OR p_source_channel NOT IN ('admin_hold', 'online')
      OR p_service_status IS NULL
      OR p_notification_preference NOT IN ('none', 'email')
      OR p_reason <> '管理画面操作'
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'reservationEdit')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_expected_table_versions) AS item(value)
      WHERE jsonb_typeof(value) <> 'object'
         OR NOT (value ?& ARRAY['tableId', 'expectedVersion'])
         OR value - ARRAY['tableId', 'expectedVersion'] <> '{}'::jsonb
         OR value ->> 'tableId' !~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
         OR value ->> 'expectedVersion' !~ '^[1-9][0-9]*$'
    ) OR (
      SELECT count(DISTINCT (value ->> 'tableId')::uuid)
      FROM jsonb_array_elements(p_expected_table_versions) AS item(value)
    ) <> cardinality(v_table_ids)
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'expectedTableVersions')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;

    SELECT * INTO v_reservation
    FROM public.reservations
    WHERE id = p_reservation_id
    FOR UPDATE;
    IF NOT FOUND THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'NOT_FOUND',
            'details', jsonb_build_object('entityType', 'reservation')
          )
        ),
        ARRAY['allowed']
      );
    END IF;
    IF v_reservation.status <> 'confirmed' THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_STATE_TRANSITION',
            'details', jsonb_build_object('reason', 'reservation_not_confirmed')
          )
        ),
        ARRAY['allowed']
      );
    END IF;
    IF v_reservation.version <> p_expected_version THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'VERSION_CONFLICT',
            'currentVersion', v_reservation.version
          )
        ),
        ARRAY['allowed']
      );
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.event_days
      WHERE id = v_reservation.event_day_id
        AND sales_open_at <= p_scheduled_start_at
        AND sales_close_at >= p_scheduled_end_at
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'scheduledStartAt')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    SELECT * INTO v_offering
    FROM public.booking_offerings
    WHERE id = p_booking_offering_id AND active = true;
    IF NOT FOUND OR p_guest_count NOT BETWEEN v_offering.min_guests AND v_offering.max_guests THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'INVALID_COMMAND',
            'details', jsonb_build_object('field', 'guestCount')
          )
        ),
        ARRAY['allowed']
      );
    END IF;
    IF p_booking_staff_member_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.vip_staff_members
      WHERE id = p_booking_staff_member_id AND active = true
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'NOT_FOUND',
            'details', jsonb_build_object('entityType', 'staff_member')
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    SELECT COALESCE(array_agg(rr.seat_resource_id ORDER BY rr.seat_resource_id), '{}'::uuid[])
    INTO v_old_table_ids
    FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now());
    v_lock_table_ids := ARRAY(
      SELECT DISTINCT id
      FROM unnest(v_old_table_ids || v_table_ids) AS target(id)
      ORDER BY id
    );

    PERFORM id FROM public.seat_resources
    WHERE id = ANY(v_lock_table_ids)
    ORDER BY id
    FOR UPDATE;
    IF (SELECT count(*) FROM public.seat_resources
        WHERE id = ANY(v_table_ids) AND active = true) <> cardinality(v_table_ids)
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object('code', 'TABLE_LOCKED')
        ),
        ARRAY['allowed']
      );
    END IF;

    FOREACH v_table_id IN ARRAY v_table_ids LOOP
      SELECT (value ->> 'expectedVersion')::bigint
      INTO v_expected_table_version
      FROM jsonb_array_elements(p_expected_table_versions) AS item(value)
      WHERE (value ->> 'tableId')::uuid = v_table_id;
      IF NOT EXISTS (
        SELECT 1 FROM public.seat_resources
        WHERE id = v_table_id AND version = v_expected_table_version
      ) THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object(
            'action', 'rejected',
            'error', jsonb_build_object(
              'code', 'VERSION_CONFLICT',
              'currentVersion', (
                SELECT version FROM public.seat_resources WHERE id = v_table_id
              ),
              'details', jsonb_build_object('entityType', 'table')
            )
          ),
          ARRAY['allowed']
        );
      END IF;
      v_step := public.assert_assignment_conflict_free_v8(
        v_reservation.event_day_id, v_reservation.id, v_table_id,
        p_scheduled_start_at, p_scheduled_end_at, now()
      );
      PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
    END LOOP;

    SELECT COALESCE(sum(capacity_max), 0)::int INTO v_capacity
    FROM public.seat_resources
    WHERE id = ANY(v_table_ids);
    IF v_capacity < p_guest_count AND NOT COALESCE(p_capacity_override, false) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object(
          'action', 'rejected',
          'error', jsonb_build_object(
            'code', 'CAPACITY_WARNING_REQUIRES_OVERRIDE',
            'details', jsonb_build_object(
              'guestCount', p_guest_count,
              'combinedCapacity', v_capacity
            )
          )
        ),
        ARRAY['allowed']
      );
    END IF;

    INSERT INTO public.reservation_assignment_events(
      reservation_id, reservation_resource_id, seat_resource_id,
      event_type, interval_before, interval_after,
      actor_admin_id, reason, request_id
    )
    SELECT
      rr.reservation_id, rr.id, rr.seat_resource_id, 'released',
      jsonb_build_object(
        'startAt', rr.assigned_start_at,
        'endAt', rr.assigned_end_at
      ),
      NULL, p_actor_admin_id, p_reason, p_request_id
    FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now())
      AND NOT (rr.seat_resource_id = ANY(v_table_ids));

    UPDATE public.reservation_resources AS rr
    SET lock_status = 'released',
        released_at = now(),
        released_by_admin_id = p_actor_admin_id,
        release_reason = p_reason,
        version = rr.version + 1,
        updated_at = now()
    WHERE rr.reservation_id = v_reservation.id
      AND public.active_reservation_assignment_v8(rr.id, now())
      AND NOT (rr.seat_resource_id = ANY(v_table_ids));

    FOREACH v_table_id IN ARRAY v_table_ids LOOP
      v_role := CASE WHEN v_table_id = v_table_ids[1] THEN 'primary' ELSE 'additional' END;
      SELECT * INTO v_assignment
      FROM public.reservation_resources
      WHERE reservation_id = v_reservation.id
        AND seat_resource_id = v_table_id;

      IF NOT FOUND THEN
        INSERT INTO public.reservation_resources(
          reservation_id, seat_resource_id, lock_status, confirmed_at,
          assigned_start_at, assigned_end_at, assignment_role,
          assigned_by_admin_id, version
        )
        VALUES (
          v_reservation.id, v_table_id, 'confirmed', now(),
          p_scheduled_start_at, p_scheduled_end_at,
          v_role, p_actor_admin_id, 1
        )
        RETURNING * INTO v_assignment;
        INSERT INTO public.reservation_assignment_events(
          reservation_id, reservation_resource_id, seat_resource_id,
          event_type, interval_before, interval_after,
          actor_admin_id, reason, request_id
        )
        VALUES (
          v_reservation.id, v_assignment.id, v_table_id, 'assigned',
          NULL,
          jsonb_build_object(
            'startAt', p_scheduled_start_at,
            'endAt', p_scheduled_end_at
          ),
          p_actor_admin_id, p_reason, p_request_id
        );
      ELSE
        UPDATE public.reservation_resources
        SET lock_status = 'confirmed',
            confirmed_at = COALESCE(confirmed_at, now()),
            released_at = NULL,
            released_by_admin_id = NULL,
            release_reason = NULL,
            assigned_start_at = p_scheduled_start_at,
            assigned_end_at = p_scheduled_end_at,
            assignment_role = v_role,
            assigned_by_admin_id = p_actor_admin_id,
            version = version + 1,
            updated_at = now()
        WHERE id = v_assignment.id;
        INSERT INTO public.reservation_assignment_events(
          reservation_id, reservation_resource_id, seat_resource_id,
          event_type, interval_before, interval_after,
          actor_admin_id, reason, request_id
        )
        VALUES (
          v_reservation.id, v_assignment.id, v_table_id, 'interval_changed',
          jsonb_build_object(
            'startAt', v_assignment.assigned_start_at,
            'endAt', v_assignment.assigned_end_at
          ),
          jsonb_build_object(
            'startAt', p_scheduled_start_at,
            'endAt', p_scheduled_end_at
          ),
          p_actor_admin_id, p_reason, p_request_id
        );
      END IF;
    END LOOP;

    UPDATE public.reservations
    SET booking_offering_id = p_booking_offering_id,
        guest_count = p_guest_count,
        guest_label = NULLIF(btrim(COALESCE(p_guest_label, '')), ''),
        operator_note = NULLIF(btrim(COALESCE(p_operator_note, '')), ''),
        intake_channel = p_source_channel,
        scheduled_start_at = p_scheduled_start_at,
        scheduled_end_at = p_scheduled_end_at,
        expected_release_at = p_scheduled_end_at,
        service_status = p_service_status,
        service_status_changed_at = CASE
          WHEN service_status IS DISTINCT FROM p_service_status THEN now()
          ELSE service_status_changed_at
        END,
        booking_staff_member_id = p_booking_staff_member_id,
        manager_notification_preference = p_notification_preference,
        version = version + 1,
        updated_at = now()
    WHERE id = v_reservation.id
    RETURNING version INTO v_new_version;

    IF v_reservation.service_status IS DISTINCT FROM p_service_status THEN
      INSERT INTO public.reservation_service_events(
        reservation_id, from_status, to_status, occurred_at,
        actor_admin_id, reason, request_id, metadata_json
      )
      VALUES (
        v_reservation.id, v_reservation.service_status, p_service_status, now(),
        p_actor_admin_id, p_reason, p_request_id,
        jsonb_build_object('source', 'admin_reservation_edit')
      );
    END IF;

    IF NULLIF(btrim(COALESCE(p_operator_note, '')), '') IS NULL THEN
      UPDATE public.reservation_notes
      SET archived_at = COALESCE(archived_at, now()),
          updated_by_admin_id = p_actor_admin_id,
          version = version + 1,
          updated_at = now()
      WHERE reservation_id = v_reservation.id
        AND kind = 'floor'
        AND archived_at IS NULL;
    ELSIF EXISTS (
      SELECT 1 FROM public.reservation_notes
      WHERE reservation_id = v_reservation.id
        AND kind = 'floor'
        AND archived_at IS NULL
    ) THEN
      UPDATE public.reservation_notes
      SET body = btrim(p_operator_note),
          updated_by_admin_id = p_actor_admin_id,
          version = version + 1,
          updated_at = now()
      WHERE id = (
        SELECT id FROM public.reservation_notes
        WHERE reservation_id = v_reservation.id
          AND kind = 'floor'
          AND archived_at IS NULL
        ORDER BY updated_at DESC, id
        LIMIT 1
      );
    ELSE
      INSERT INTO public.reservation_notes(
        reservation_id, kind, body, pinned,
        author_admin_id, updated_by_admin_id
      )
      VALUES (
        v_reservation.id, 'floor', btrim(p_operator_note), false,
        p_actor_admin_id, p_actor_admin_id
      );
    END IF;

    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, v_reservation.event_day_id, v_reservation.id,
      'reservation', v_reservation.id, v_action,
      p_request_id, p_reason,
      p_expected_version, v_reservation.version, v_new_version,
      ARRAY[
        'booking_offering_id', 'guest_count', 'guest_label', 'operator_note',
        'intake_channel', 'scheduled_start_at', 'scheduled_end_at',
        'expected_release_at', 'service_status',
        'booking_staff_member_id', 'manager_notification_preference',
        'assignments', 'version'
      ],
      jsonb_build_object(
        'version', v_reservation.version,
        'serviceStatus', v_reservation.service_status,
        'scheduledStartAt', v_reservation.scheduled_start_at,
        'scheduledEndAt', v_reservation.scheduled_end_at
      ),
      jsonb_build_object(
        'version', v_new_version,
        'serviceStatus', p_service_status,
        'scheduledStartAt', p_scheduled_start_at,
        'scheduledEndAt', p_scheduled_end_at
      ),
      jsonb_build_object(
        'tableIds', to_jsonb(v_table_ids),
        'sourceChannel', p_source_channel,
        'notifyMode', p_notification_preference,
        'capacityOverride', COALESCE(p_capacity_override, false)
      )
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_step := public.bump_vip_floor_day_revision_v8(
      v_reservation.event_day_id, v_audit_id
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;

    v_response := jsonb_build_object(
      'ok', true,
      'action', v_action,
      'reused', false,
      'reservationId', v_reservation.id,
      'entityVersion', v_new_version,
      'boardRevision', v_revision,
      'auditLogId', v_audit_id,
      'tableIds', to_jsonb(v_table_ids),
      'notificationPreference', p_notification_preference
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN
      RETURN v_error_detail::jsonb;
    END IF;
    RAISE;
  END;
END;
$_$;

-- FUNCTION: update_admin_reservation_v22(uuid, text, text, text, uuid, bigint, uuid, timestamp with time zone, timestamp with time zone, integer, uuid[], jsonb, text, text, text, public.vip_service_status, uuid, text, boolean, text)
CREATE FUNCTION public.update_admin_reservation_v22(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_version bigint, p_booking_offering_id uuid, p_scheduled_start_at timestamp with time zone, p_scheduled_end_at timestamp with time zone, p_guest_count integer, p_table_ids uuid[], p_expected_table_versions jsonb, p_guest_label text, p_operator_note text, p_source_channel text, p_service_status public.vip_service_status, p_booking_staff_member_id uuid, p_notification_preference text, p_capacity_override boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_response jsonb;
  v_legacy_source text;
BEGIN
  IF p_source_channel NOT IN ('online', 'phone', 'admin') THEN
    RETURN jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
      'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'sourceChannel')
    ));
  END IF;
  v_legacy_source := CASE WHEN p_source_channel = 'online' THEN 'online' ELSE 'admin_hold' END;
  v_response := public.update_admin_reservation_v14(
    p_actor_admin_id, p_request_id, p_idempotency_key, p_request_hash,
    p_reservation_id, p_expected_version, p_booking_offering_id,
    p_scheduled_start_at, p_scheduled_end_at, p_guest_count, p_table_ids,
    p_expected_table_versions, p_guest_label, p_operator_note, v_legacy_source,
    p_service_status, p_booking_staff_member_id, p_notification_preference,
    p_capacity_override, p_reason
  );
  IF v_response ->> 'action' = 'rejected' THEN RETURN v_response; END IF;
  UPDATE public.reservations SET origin_channel = p_source_channel WHERE id = p_reservation_id;
  PERFORM public.sync_reservation_floor_note_v22(p_actor_admin_id, p_reservation_id, p_operator_note);
  RETURN v_response || jsonb_build_object('sourceChannel', p_source_channel);
END;
$$;

-- FUNCTION: update_admin_vip_staff_member_v12(uuid, text, text, text, uuid, bigint, text, boolean, text)
CREATE FUNCTION public.update_admin_vip_staff_member_v12(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_staff_member_id uuid, p_expected_version bigint, p_display_name text, p_active boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'staff_member.updated';
  v_step jsonb;
  v_staff public.vip_staff_members%ROWTYPE;
  v_new_version bigint;
  v_audit_id uuid;
  v_response jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admin_users
    WHERE id = p_actor_admin_id AND active = true AND role = 'owner'
  ) THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object('code', 'FORBIDDEN')
    );
  END IF;
  IF p_staff_member_id IS NULL
    OR p_expected_version IS NULL OR p_expected_version < 1
    OR NULLIF(btrim(COALESCE(p_display_name, '')), '') IS NULL
    OR char_length(btrim(p_display_name)) > 80
    OR p_active IS NULL
    OR p_reason <> '管理画面操作'
  THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'INVALID_COMMAND',
        'details', jsonb_build_object('field', 'staffMember')
      )
    );
  END IF;

  v_step := public.preclaim_admin_action_request_v8(
    p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
  );
  IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
  IF v_step ->> 'action' = 'reused' THEN
    RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
  END IF;

  SELECT * INTO v_staff
  FROM public.vip_staff_members
  WHERE id = p_staff_member_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object('code', 'NOT_FOUND')
    );
  END IF;
  IF v_staff.version <> p_expected_version THEN
    RETURN jsonb_build_object(
      'action', 'rejected',
      'error', jsonb_build_object(
        'code', 'VERSION_CONFLICT',
        'currentVersion', v_staff.version
      )
    );
  END IF;

  v_new_version := v_staff.version + 1;
  UPDATE public.vip_staff_members
  SET display_name = btrim(p_display_name),
      active = p_active,
      version = v_new_version,
      updated_by_admin_id = p_actor_admin_id,
      updated_at = now()
  WHERE id = p_staff_member_id;

  IF NOT p_active THEN
    UPDATE public.vip_table_staff_assignments
    SET released_at = now(),
        released_by_admin_id = p_actor_admin_id,
        version = version + 1,
        updated_at = now()
    WHERE staff_member_id = p_staff_member_id
      AND released_at IS NULL;
  END IF;

  INSERT INTO public.audit_logs(
    actor_admin_id, actor_type, action, target_table, target_id,
    request_id, reason, entity_type, entity_id, operation,
    expected_version, version_before, version_after, changed_fields,
    before_json, after_json, metadata_json, source_contract
  )
  VALUES (
    p_actor_admin_id, 'admin', v_action, 'vip_staff_members', p_staff_member_id,
    p_request_id, p_reason, 'staff_member', p_staff_member_id, v_action,
    p_expected_version, v_staff.version, v_new_version,
    ARRAY['display_name', 'active', 'version'],
    jsonb_build_object('version', v_staff.version, 'active', v_staff.active),
    jsonb_build_object('version', v_new_version, 'active', p_active),
    jsonb_build_object('redaction', 'staff_name_omitted'),
    'ghost.vip-manager.v2'
  )
  RETURNING id INTO v_audit_id;

  v_response := jsonb_build_object(
    'ok', true,
    'action', v_action,
    'reused', false,
    'staffMemberId', p_staff_member_id,
    'entityVersion', v_new_version,
    'boardRevision', 0,
    'auditLogId', v_audit_id
  );
  PERFORM public.complete_admin_action_request_v8(
    p_actor_admin_id, v_action, p_idempotency_key, v_response
  );
  RETURN v_response;
END;
$$;

-- FUNCTION: update_admin_vipapp_reservation_v7(uuid, text, text, text, text, uuid, timestamp with time zone, text, text, timestamp with time zone, text)
CREATE FUNCTION public.update_admin_vipapp_reservation_v7(p_actor_admin_id uuid, p_request_id text, p_action text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_updated_at timestamp with time zone, p_command text, p_value_text text, p_occurred_at timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin public.admin_users%ROWTYPE;
  v_existing public.admin_action_requests%ROWTYPE;
  v_reservation public.reservations%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_response jsonb;
  v_nested_result jsonb;
  v_before_service_status text;
  v_before_arrived_at timestamptz;
  v_before_operator_note_set boolean;
BEGIN
  SELECT *
  INTO v_admin
  FROM public.admin_users
  WHERE id = p_actor_admin_id
  FOR UPDATE;

  IF NOT FOUND OR v_admin.active = false THEN
    RAISE EXCEPTION 'retired or unknown admin actor';
  END IF;

  IF v_admin.role NOT IN ('staff', 'manager', 'owner', 'engineer') THEN
    RAISE EXCEPTION 'admin role cannot operate VIP Floor';
  END IF;

  SELECT *
  INTO v_existing
  FROM public.admin_action_requests
  WHERE actor_admin_id = p_actor_admin_id
    AND action = p_action
    AND idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RETURN jsonb_build_object(
        'action', 'mismatch',
        'error', 'idempotency_key_reused_with_different_request'
      );
    END IF;

    RETURN jsonb_build_object('action', 'reused', 'response', v_existing.response_json);
  END IF;

  SELECT *
  INTO v_reservation
  FROM public.reservations
  WHERE id = p_reservation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'reservation not found';
  END IF;

  IF v_reservation.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'reservation version conflict';
  END IF;

  v_before_service_status := v_reservation.vipapp_service_status;
  v_before_arrived_at := v_reservation.vipapp_arrived_at;
  v_before_operator_note_set := v_reservation.operator_note IS NOT NULL;

  IF p_command = 'check_in' THEN
    v_nested_result := public.check_in_admin_reservation_v7(
      p_actor_admin_id,
      p_request_id,
      p_action,
      p_idempotency_key,
      p_request_hash,
      p_reservation_id,
      p_reason
    );
    RETURN v_nested_result;
  END IF;

  IF p_command = 'seat_extension' THEN
    IF p_value_text IS DISTINCT FROM '30' THEN
      RAISE EXCEPTION 'invalid extension';
    END IF;

    v_nested_result := public.extend_checked_in_reservation_seat_v7(
      p_actor_admin_id,
      p_request_id,
      p_action,
      p_idempotency_key,
      p_request_hash,
      p_reservation_id,
      30,
      p_reason
    );
    RETURN v_nested_result;
  END IF;

  IF p_command = 'assignment' THEN
    IF v_admin.role NOT IN ('manager', 'owner', 'engineer') THEN
      RAISE EXCEPTION 'admin role cannot assign reservations';
    END IF;

    v_nested_result := public.assign_admin_reservation_resource_v7(
      p_actor_admin_id,
      p_request_id,
      p_action,
      p_idempotency_key,
      p_request_hash,
      p_reservation_id,
      p_value_text,
      p_reason
    );

    UPDATE public.reservations
    SET updated_at = v_now
    WHERE id = p_reservation_id;

    RETURN v_nested_result;
  END IF;

  IF p_command = 'service_status' THEN
    IF p_value_text NOT IN (
      'expected',
      'late',
      'no_contact',
      'arrived',
      'partial_arrival',
      'seated',
      'bottle_pending',
      'bottle_served',
      'bill_requested',
      'paid',
      'resetting',
      'completed',
      'no_show'
    ) THEN
      RAISE EXCEPTION 'invalid service status';
    END IF;

    UPDATE public.reservations
    SET vipapp_service_status = p_value_text,
        vipapp_arrived_at = CASE
          WHEN p_value_text IN ('arrived', 'partial_arrival', 'seated')
            THEN COALESCE(vipapp_arrived_at, p_occurred_at, v_now)
          ELSE vipapp_arrived_at
        END,
        updated_at = v_now
    WHERE id = p_reservation_id;
  ELSIF p_command = 'arrival_time' THEN
    IF p_occurred_at IS NULL
      OR p_occurred_at > v_now + interval '5 minutes'
      OR p_occurred_at < v_now - interval '7 days'
    THEN
      RAISE EXCEPTION 'invalid arrival time';
    END IF;

    UPDATE public.reservations
    SET vipapp_arrived_at = p_occurred_at,
        vipapp_service_status = CASE
          WHEN vipapp_service_status IS NULL OR vipapp_service_status = 'expected'
            THEN 'arrived'
          ELSE vipapp_service_status
        END,
        updated_at = v_now
    WHERE id = p_reservation_id;
  ELSIF p_command = 'note' THEN
    IF NULLIF(btrim(COALESCE(p_value_text, '')), '') IS NULL
      OR char_length(p_value_text) > 500
    THEN
      RAISE EXCEPTION 'invalid operator note';
    END IF;

    UPDATE public.reservations
    SET operator_note = btrim(p_value_text),
        updated_at = v_now
    WHERE id = p_reservation_id;
  ELSE
    RAISE EXCEPTION 'unsupported VIP Floor command';
  END IF;

  SELECT *
  INTO v_reservation
  FROM public.reservations
  WHERE id = p_reservation_id;

  v_response := jsonb_build_object(
    'reservationId', v_reservation.id,
    'command', p_command,
    'serviceStatus', v_reservation.vipapp_service_status,
    'arrivedAt', v_reservation.vipapp_arrived_at,
    'operatorNoteChanged', p_command = 'note',
    'updatedAt', v_reservation.updated_at
  );

  INSERT INTO public.admin_action_requests(
    actor_admin_id,
    action,
    idempotency_key,
    request_hash,
    response_json
  )
  VALUES (
    p_actor_admin_id,
    p_action,
    p_idempotency_key,
    p_request_hash,
    v_response
  );

  INSERT INTO public.audit_logs(
    actor_admin_id,
    actor_type,
    action,
    target_table,
    target_id,
    request_id,
    before_json,
    after_json,
    reason
  )
  VALUES (
    p_actor_admin_id,
    'admin',
    p_action,
    'reservations',
    p_reservation_id,
    p_request_id,
    jsonb_build_object(
      'serviceStatus', v_before_service_status,
      'arrivedAtWasSet', v_before_arrived_at IS NOT NULL,
      'operatorNoteWasSet', v_before_operator_note_set
    ),
    v_response,
    p_reason
  );

  RETURN jsonb_build_object('action', 'updated', 'response', v_response);
END;
$$;

-- FUNCTION: upsert_admin_customer_profile_v8(uuid, text, text, text, uuid, uuid, uuid, bigint, bytea, bytea, bytea, bytea, text, text, bytea, bytea, text)
CREATE FUNCTION public.upsert_admin_customer_profile_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_event_day_id uuid, p_reservation_id uuid, p_customer_id uuid, p_expected_profile_version bigint, p_display_name_ciphertext bytea, p_name_kana_ciphertext bytea, p_phone_ciphertext bytea, p_email_ciphertext bytea, p_display_name_search_token text, p_language_code text, p_allergies_ciphertext bytea, p_preferences_ciphertext bytea, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'customer_profile.upserted';
  v_step jsonb;
  v_reservation public.reservations%ROWTYPE;
  v_profile public.customer_profiles%ROWTYPE;
  v_profile_exists boolean := false;
  v_language_code text := NULLIF(lower(btrim(COALESCE(p_language_code, ''))), '');
  v_search_token text := NULLIF(btrim(COALESCE(p_display_name_search_token, '')), '');
  v_new_version bigint;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;
    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(p_actor_admin_id, 'customer_profile.write'),
      ARRAY['allowed']
    );
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR p_event_day_id IS NULL OR p_customer_id IS NULL
      OR (p_expected_profile_version IS NOT NULL AND p_expected_profile_version < 1)
      OR (v_language_code IS NOT NULL AND v_language_code NOT IN ('ja', 'en', 'ko', 'zh'))
      OR (p_display_name_ciphertext IS NOT NULL AND octet_length(p_display_name_ciphertext) = 0)
      OR (p_name_kana_ciphertext IS NOT NULL AND octet_length(p_name_kana_ciphertext) = 0)
      OR (p_phone_ciphertext IS NOT NULL AND octet_length(p_phone_ciphertext) = 0)
      OR (p_email_ciphertext IS NOT NULL AND octet_length(p_email_ciphertext) = 0)
      OR (p_allergies_ciphertext IS NOT NULL AND octet_length(p_allergies_ciphertext) = 0)
      OR (p_preferences_ciphertext IS NOT NULL AND octet_length(p_preferences_ciphertext) = 0)
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'customerProfileCommand')
        )), ARRAY['allowed']
      );
    END IF;

    IF p_reservation_id IS NOT NULL THEN
      SELECT * INTO v_reservation
      FROM public.reservations
      WHERE id = p_reservation_id
      FOR UPDATE;
      IF NOT FOUND
        OR v_reservation.event_day_id <> p_event_day_id
        OR v_reservation.customer_id <> p_customer_id
      THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
            'code', 'NOT_FOUND',
            'details', jsonb_build_object('entityType', 'reservation_customer_context')
          )), ARRAY['allowed']
        );
      END IF;
      PERFORM sr.id FROM public.seat_resources AS sr
      WHERE EXISTS (
        SELECT 1 FROM public.reservation_resources AS rr
        WHERE rr.reservation_id = v_reservation.id AND rr.seat_resource_id = sr.id
      ) ORDER BY sr.id FOR UPDATE OF sr;
      PERFORM rr.id FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id ORDER BY rr.id FOR UPDATE OF rr;
      PERFORM rb.id FROM public.reservation_blocks AS rb
      WHERE rb.event_day_id = p_event_day_id
        AND rb.status = 'active'
        AND rb.start_at < v_reservation.expected_release_at
        AND rb.end_at > v_reservation.scheduled_start_at
      ORDER BY rb.id FOR UPDATE OF rb;
    ELSIF NOT EXISTS (
      SELECT 1 FROM public.reservations AS r
      WHERE r.event_day_id = p_event_day_id AND r.customer_id = p_customer_id
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'NOT_FOUND', 'details', jsonb_build_object('entityType', 'customer_event_day_context')
        )), ARRAY['allowed']
      );
    END IF;

    SELECT * INTO v_profile
    FROM public.customer_profiles
    WHERE customer_id = p_customer_id
    FOR UPDATE;
    v_profile_exists := FOUND;
    IF v_profile_exists AND (
      p_expected_profile_version IS NULL
      OR v_profile.version <> p_expected_profile_version
    ) THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'VERSION_CONFLICT', 'currentVersion', v_profile.version,
          'details', jsonb_build_object('entityType', 'customer_profile')
        )), ARRAY['allowed']
      );
    ELSIF NOT v_profile_exists AND p_expected_profile_version IS NOT NULL THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'VERSION_CONFLICT', 'currentVersion', 0,
          'details', jsonb_build_object('entityType', 'customer_profile')
        )), ARRAY['allowed']
      );
    END IF;

    IF v_profile_exists
      AND (v_profile.display_name_ciphertext, v_profile.name_kana_ciphertext,
        v_profile.phone_ciphertext, v_profile.email_ciphertext,
        v_profile.display_name_search_token, v_profile.language_code,
        v_profile.allergies_ciphertext, v_profile.preferences_ciphertext)
      IS NOT DISTINCT FROM
        (p_display_name_ciphertext, p_name_kana_ciphertext,
        p_phone_ciphertext, p_email_ciphertext,
        v_search_token, v_language_code,
        p_allergies_ciphertext, p_preferences_ciphertext)
    THEN
      PERFORM ed.id FROM public.event_days AS ed
      WHERE ed.id = p_event_day_id FOR KEY SHARE OF ed;
      PERFORM public.lock_vip_floor_day_revision_v32(p_event_day_id);
    SELECT COALESCE(vfr.revision, 0) INTO v_predicted_revision
      FROM (SELECT 1) AS seed LEFT JOIN public.vip_floor_day_revisions AS vfr
        ON vfr.event_day_id = p_event_day_id;
      v_step := public.append_vip_floor_audit_v8(
        p_actor_admin_id, p_event_day_id, p_reservation_id,
        'customer', p_customer_id, v_action || '.noop', p_request_id, p_reason,
        NULL, NULL, NULL, '{}'::text[],
        jsonb_build_object('version', v_profile.version),
        jsonb_build_object('version', v_profile.version), '{}'::jsonb
      );
      PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
      v_audit_id := (v_step ->> 'auditLogId')::uuid;
      v_response := jsonb_build_object(
        'ok', true, 'action', v_action, 'reused', false,
        'customerId', p_customer_id, 'entityVersion', v_profile.version,
        'boardRevision', v_predicted_revision, 'auditLogId', v_audit_id,
        'noOp', true
      );
      PERFORM public.complete_admin_action_request_v8(
        p_actor_admin_id, v_action, p_idempotency_key, v_response
      );
      RETURN v_response;
    END IF;

    INSERT INTO public.customer_profiles(
      customer_id, display_name_ciphertext, name_kana_ciphertext,
      phone_ciphertext, email_ciphertext, display_name_search_token,
      language_code, allergies_ciphertext, preferences_ciphertext, version
    ) VALUES (
      p_customer_id, p_display_name_ciphertext, p_name_kana_ciphertext,
      p_phone_ciphertext, p_email_ciphertext, v_search_token,
      v_language_code, p_allergies_ciphertext, p_preferences_ciphertext, 1
    )
    ON CONFLICT (customer_id) DO UPDATE
    SET display_name_ciphertext = EXCLUDED.display_name_ciphertext,
        name_kana_ciphertext = EXCLUDED.name_kana_ciphertext,
        phone_ciphertext = EXCLUDED.phone_ciphertext,
        email_ciphertext = EXCLUDED.email_ciphertext,
        display_name_search_token = EXCLUDED.display_name_search_token,
        language_code = EXCLUDED.language_code,
        allergies_ciphertext = EXCLUDED.allergies_ciphertext,
        preferences_ciphertext = EXCLUDED.preferences_ciphertext,
        version = public.customer_profiles.version + 1,
        updated_at = now()
    RETURNING version INTO v_new_version;

    PERFORM ed.id FROM public.event_days AS ed
    WHERE ed.id = p_event_day_id FOR KEY SHARE OF ed;
    PERFORM public.lock_vip_floor_day_revision_v32(p_event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1 INTO v_predicted_revision
    FROM (SELECT 1) AS seed LEFT JOIN public.vip_floor_day_revisions AS vfr
      ON vfr.event_day_id = p_event_day_id;
    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, p_event_day_id, p_reservation_id,
      'customer', p_customer_id, v_action, p_request_id, p_reason,
      p_expected_profile_version,
      CASE WHEN v_profile_exists THEN v_profile.version ELSE NULL END,
      v_new_version,
      ARRAY[
        'display_name_ciphertext', 'name_kana_ciphertext',
        'phone_ciphertext', 'email_ciphertext', 'display_name_search_token',
        'language_code', 'allergies_ciphertext', 'preferences_ciphertext', 'version'
      ],
      CASE WHEN v_profile_exists THEN jsonb_build_object('version', v_profile.version) ELSE NULL END,
      jsonb_build_object('version', v_new_version, 'languageCode', v_language_code),
      jsonb_build_object('created', NOT v_profile_exists)
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_response := jsonb_build_object(
      'ok', true, 'action', v_action, 'reused', false,
      'customerId', p_customer_id, 'entityVersion', v_new_version,
      'boardRevision', v_predicted_revision, 'auditLogId', v_audit_id
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(p_event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'XX000', MESSAGE = 'VIP floor revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS v_error_detail = PG_EXCEPTION_DETAIL, v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN RETURN v_error_detail::jsonb; END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: upsert_admin_reservation_note_v8(uuid, text, text, text, uuid, bigint, uuid, bigint, text, text, boolean, text)
CREATE FUNCTION public.upsert_admin_reservation_note_v8(p_actor_admin_id uuid, p_request_id text, p_idempotency_key text, p_request_hash text, p_reservation_id uuid, p_expected_reservation_version bigint, p_note_id uuid, p_expected_note_version bigint, p_kind text, p_body text, p_pinned boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action constant text := 'reservation_note.upserted';
  v_kind text := lower(btrim(COALESCE(p_kind, '')));
  v_step jsonb;
  v_reservation public.reservations%ROWTYPE;
  v_note public.reservation_notes%ROWTYPE;
  v_note_id uuid;
  v_note_version bigint;
  v_reservation_version bigint;
  v_audit_id uuid;
  v_predicted_revision bigint;
  v_revision bigint;
  v_response jsonb;
  v_error_detail text;
  v_error_constraint text;
BEGIN
  BEGIN
    v_step := public.preclaim_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, p_request_hash
    );
    IF v_step ->> 'action' = 'rejected' THEN RETURN v_step; END IF;
    IF v_step ->> 'action' = 'reused' THEN
      RETURN jsonb_set(v_step -> 'response', '{reused}', 'true'::jsonb, true);
    END IF;
    PERFORM public.assert_vip_floor_helper_success_v8(
      public.require_admin_capability_v8(p_actor_admin_id, 'reservation_note.write'),
      ARRAY['allowed']
    );
    IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
      OR v_kind NOT IN ('floor', 'booking', 'private')
      OR NULLIF(btrim(COALESCE(p_body, '')), '') IS NULL
      OR char_length(p_body) > 2000
      OR p_pinned IS NULL
      OR (p_note_id IS NULL AND p_expected_note_version IS NOT NULL)
      OR (p_note_id IS NOT NULL AND (p_expected_note_version IS NULL OR p_expected_note_version < 1))
    THEN
      PERFORM public.assert_vip_floor_helper_success_v8(
        jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
          'code', 'INVALID_COMMAND', 'details', jsonb_build_object('field', 'noteCommand')
        )), ARRAY['allowed']
      );
    END IF;
    v_step := public.assert_reservation_version_v8(
      p_reservation_id, p_expected_reservation_version
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['allowed']);
    SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id;

    PERFORM sr.id FROM public.seat_resources AS sr
    WHERE EXISTS (
      SELECT 1 FROM public.reservation_resources AS rr
      WHERE rr.reservation_id = v_reservation.id AND rr.seat_resource_id = sr.id
    ) ORDER BY sr.id FOR UPDATE OF sr;
    PERFORM rr.id FROM public.reservation_resources AS rr
    WHERE rr.reservation_id = v_reservation.id ORDER BY rr.id FOR UPDATE OF rr;
    PERFORM rb.id FROM public.reservation_blocks AS rb
    WHERE rb.event_day_id = v_reservation.event_day_id
      AND rb.status = 'active'
      AND rb.start_at < v_reservation.expected_release_at
      AND rb.end_at > v_reservation.scheduled_start_at
      AND EXISTS (
        SELECT 1 FROM public.reservation_block_targets AS rbt
        JOIN public.reservation_resources AS rr ON rr.reservation_id = v_reservation.id
        JOIN public.seat_resources AS sr ON sr.id = rr.seat_resource_id
        WHERE rbt.block_id = rb.id
          AND (rbt.seat_resource_id = sr.id OR rbt.floor_section_id = sr.floor_section_id OR rbt.venue_wide)
      )
    ORDER BY rb.id FOR UPDATE OF rb;

    IF p_note_id IS NULL THEN
      INSERT INTO public.reservation_notes(
        reservation_id, kind, body, pinned, author_admin_id, updated_by_admin_id
      ) VALUES (
        v_reservation.id, v_kind, p_body, p_pinned,
        p_actor_admin_id, p_actor_admin_id
      ) RETURNING id, version INTO v_note_id, v_note_version;
    ELSE
      SELECT * INTO v_note FROM public.reservation_notes
      WHERE id = p_note_id FOR UPDATE;
      IF NOT FOUND OR v_note.reservation_id <> v_reservation.id THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
            'code', 'NOT_FOUND', 'details', jsonb_build_object('entityType', 'note')
          )), ARRAY['allowed']
        );
      END IF;
      IF v_note.version <> p_expected_note_version THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
            'code', 'VERSION_CONFLICT', 'currentVersion', v_note.version, 'details', '{}'::jsonb
          )), ARRAY['allowed']
        );
      END IF;
      IF v_note.archived_at IS NOT NULL THEN
        PERFORM public.assert_vip_floor_helper_success_v8(
          jsonb_build_object('action', 'rejected', 'error', jsonb_build_object(
            'code', 'INVALID_STATE_TRANSITION', 'details', jsonb_build_object('reason', 'note_archived')
          )), ARRAY['allowed']
        );
      END IF;

      IF (v_note.kind, v_note.body, v_note.pinned)
        IS NOT DISTINCT FROM (v_kind, p_body, p_pinned)
      THEN
        PERFORM ed.id FROM public.event_days AS ed
        WHERE ed.id = v_reservation.event_day_id FOR KEY SHARE OF ed;
        PERFORM public.lock_vip_floor_day_revision_v32(v_reservation.event_day_id);
    SELECT COALESCE(vfr.revision, 0) INTO v_predicted_revision
        FROM (SELECT 1) AS seed LEFT JOIN public.vip_floor_day_revisions AS vfr
          ON vfr.event_day_id = v_reservation.event_day_id;
        v_step := public.append_vip_floor_audit_v8(
          p_actor_admin_id, v_reservation.event_day_id, v_reservation.id,
          'note', v_note.id, v_action || '.noop', p_request_id, p_reason,
          NULL, NULL, NULL, '{}'::text[],
          jsonb_build_object('kind', v_note.kind, 'pinned', v_note.pinned, 'version', v_note.version),
          jsonb_build_object('kind', v_note.kind, 'pinned', v_note.pinned, 'version', v_note.version),
          '{}'::jsonb
        );
        PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
        v_audit_id := (v_step ->> 'auditLogId')::uuid;
        v_response := jsonb_build_object(
          'ok', true, 'action', v_action, 'reused', false,
          'noteId', v_note.id, 'entityVersion', v_note.version,
          'reservationVersion', v_reservation.version,
          'boardRevision', v_predicted_revision, 'auditLogId', v_audit_id,
          'noOp', true
        );
        PERFORM public.complete_admin_action_request_v8(
          p_actor_admin_id, v_action, p_idempotency_key, v_response
        );
        RETURN v_response;
      END IF;

      UPDATE public.reservation_notes
      SET kind = v_kind, body = p_body, pinned = p_pinned,
          updated_by_admin_id = p_actor_admin_id,
          version = version + 1, updated_at = now()
      WHERE id = v_note.id
      RETURNING id, version INTO v_note_id, v_note_version;
    END IF;

    UPDATE public.reservations
    SET version = version + 1, updated_at = now()
    WHERE id = v_reservation.id RETURNING version INTO v_reservation_version;
    PERFORM ed.id FROM public.event_days AS ed
    WHERE ed.id = v_reservation.event_day_id FOR KEY SHARE OF ed;
    PERFORM public.lock_vip_floor_day_revision_v32(v_reservation.event_day_id);
    SELECT COALESCE(vfr.revision, 0) + 1 INTO v_predicted_revision
    FROM (SELECT 1) AS seed LEFT JOIN public.vip_floor_day_revisions AS vfr
      ON vfr.event_day_id = v_reservation.event_day_id;
    v_step := public.append_vip_floor_audit_v8(
      p_actor_admin_id, v_reservation.event_day_id, v_reservation.id,
      'note', v_note_id, v_action, p_request_id, p_reason,
      p_expected_note_version,
      CASE WHEN p_note_id IS NULL THEN NULL ELSE v_note.version END,
      v_note_version,
      CASE WHEN p_note_id IS NULL THEN ARRAY['created']::text[]
        ELSE ARRAY['kind', 'body', 'pinned', 'version']::text[] END,
      CASE WHEN p_note_id IS NULL THEN NULL ELSE
        jsonb_build_object('kind', v_note.kind, 'pinned', v_note.pinned, 'version', v_note.version) END,
      jsonb_build_object('kind', v_kind, 'pinned', p_pinned, 'version', v_note_version),
      jsonb_build_object('bodyChanged', p_note_id IS NULL OR v_note.body IS DISTINCT FROM p_body)
    );
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['appended']);
    v_audit_id := (v_step ->> 'auditLogId')::uuid;
    v_response := jsonb_build_object(
      'ok', true, 'action', v_action, 'reused', false,
      'noteId', v_note_id, 'entityVersion', v_note_version,
      'reservationVersion', v_reservation_version,
      'boardRevision', v_predicted_revision, 'auditLogId', v_audit_id
    );
    PERFORM public.complete_admin_action_request_v8(
      p_actor_admin_id, v_action, p_idempotency_key, v_response
    );
    v_step := public.bump_vip_floor_day_revision_v8(v_reservation.event_day_id, v_audit_id);
    PERFORM public.assert_vip_floor_helper_success_v8(v_step, ARRAY['bumped']);
    v_revision := (v_step ->> 'revision')::bigint;
    IF v_revision <> v_predicted_revision THEN
      RAISE EXCEPTION USING ERRCODE = 'XX000', MESSAGE = 'VIP floor revision prediction diverged';
    END IF;
    RETURN v_response;
  EXCEPTION WHEN raise_exception THEN
    GET STACKED DIAGNOSTICS v_error_detail = PG_EXCEPTION_DETAIL, v_error_constraint = CONSTRAINT_NAME;
    IF v_error_constraint = 'vip_floor_business_rejection_v8' THEN RETURN v_error_detail::jsonb; END IF;
    RAISE;
  END;
END;
$$;

-- FUNCTION: upsert_public_customer_profile_v8(uuid, uuid, text, bytea, bytea)
CREATE FUNCTION public.upsert_public_customer_profile_v8(p_customer_id uuid, p_reservation_id uuid, p_request_hash text, p_phone_ciphertext bytea, p_email_ciphertext bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_reservation public.reservations%ROWTYPE;
  v_profile public.customer_profiles%ROWTYPE;
  v_profile_exists boolean := false;
  v_new_version bigint;
  v_audit_id uuid;
  v_revision_step jsonb;
BEGIN
  IF NOT public.vip_floor_v2_dual_write_enabled() THEN
    RETURN jsonb_build_object('action', 'rejected', 'error', 'flag_misaligned');
  END IF;

  IF p_customer_id IS NULL
    OR p_reservation_id IS NULL
    OR NULLIF(btrim(COALESCE(p_request_hash, '')), '') IS NULL
    OR (p_phone_ciphertext IS NOT NULL AND octet_length(p_phone_ciphertext) = 0)
    OR (p_email_ciphertext IS NOT NULL AND octet_length(p_email_ciphertext) = 0)
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'error', 'invalid_command');
  END IF;

  IF p_phone_ciphertext IS NULL AND p_email_ciphertext IS NULL THEN
    RETURN jsonb_build_object('action', 'skipped', 'reason', 'no_contact_fields');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_customer_id::text, 8089));

  SELECT * INTO v_reservation
  FROM public.reservations
  WHERE id = p_reservation_id
    AND customer_id = p_customer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('action', 'rejected', 'error', 'reservation_customer_mismatch');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.audit_logs
    WHERE action = 'vip_floor.public_customer_profile.upserted'
      AND target_id = p_customer_id
      AND metadata_json ->> 'requestHash' = p_request_hash
  ) THEN
    RETURN jsonb_build_object(
      'action', 'reused',
      'customerId', p_customer_id
    );
  END IF;

  SELECT * INTO v_profile
  FROM public.customer_profiles
  WHERE customer_id = p_customer_id
  FOR UPDATE;
  v_profile_exists := FOUND;

  PERFORM set_config('ghost.vip_floor_v8_writer', 'on', true);

  INSERT INTO public.customer_profiles(
    customer_id,
    phone_ciphertext,
    email_ciphertext,
    version
  )
  VALUES (
    p_customer_id,
    p_phone_ciphertext,
    p_email_ciphertext,
    1
  )
  ON CONFLICT (customer_id) DO UPDATE
  SET phone_ciphertext = COALESCE(
        EXCLUDED.phone_ciphertext,
        public.customer_profiles.phone_ciphertext
      ),
      email_ciphertext = COALESCE(
        EXCLUDED.email_ciphertext,
        public.customer_profiles.email_ciphertext
      ),
      version = public.customer_profiles.version + 1,
      updated_at = now()
  RETURNING version INTO v_new_version;

  PERFORM event_day.id
  FROM public.event_days AS event_day
  WHERE event_day.id = v_reservation.event_day_id
  FOR KEY SHARE OF event_day;

  INSERT INTO public.audit_logs(
    actor_type,
    action,
    target_table,
    target_id,
    request_id,
    event_day_id,
    reservation_id,
    entity_type,
    entity_id,
    operation,
    version_before,
    version_after,
    changed_fields,
    before_json,
    after_json,
    metadata_json,
    source_contract
  )
  VALUES (
    'customer',
    'vip_floor.public_customer_profile.upserted',
    'customer_profiles',
    p_customer_id,
    p_request_hash,
    v_reservation.event_day_id,
    p_reservation_id,
    'customer',
    p_customer_id,
    'public_customer_profile_upsert',
    CASE WHEN v_profile_exists THEN v_profile.version ELSE NULL END,
    v_new_version,
    ARRAY['phone_ciphertext', 'email_ciphertext', 'version'],
    CASE WHEN v_profile_exists
      THEN jsonb_build_object('version', v_profile.version)
      ELSE NULL
    END,
    jsonb_build_object('version', v_new_version),
    jsonb_build_object(
      'sourceContract', 'v8',
      'redaction', 'field_names_and_versions_only',
      'requestHash', p_request_hash
    ),
    'v8'
  )
  RETURNING id INTO v_audit_id;

  v_revision_step := public.bump_vip_floor_day_revision_v8(
    v_reservation.event_day_id,
    v_audit_id
  );
  IF v_revision_step ->> 'action' <> 'bumped' THEN
    RAISE EXCEPTION 'VIP Floor public customer profile revision bump failed';
  END IF;

  RETURN jsonb_build_object(
    'action', 'upserted',
    'customerId', p_customer_id,
    'entityVersion', v_new_version,
    'created', NOT v_profile_exists
  );
END;
$$;

-- FUNCTION: validate_reservation_resource_requirement_v7()
CREATE FUNCTION public.validate_reservation_resource_requirement_v7() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_booking_offering_id uuid;
BEGIN
  IF NEW.lock_status NOT IN ('held', 'payment_grace_locked', 'confirmed') THEN
    RETURN NEW;
  END IF;

  SELECT r.booking_offering_id
  INTO v_booking_offering_id
  FROM public.reservations AS r
  WHERE r.id = NEW.reservation_id;

  IF v_booking_offering_id IS NULL THEN
    RAISE EXCEPTION 'reservation not found for resource requirement validation';
  END IF;

  IF NOT public.seat_resource_satisfies_offering_requirement_v7(
    v_booking_offering_id,
    NEW.seat_resource_id
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'VIP floor business rejection',
      DETAIL = jsonb_build_object(
        'action', 'rejected',
        'error', jsonb_build_object(
          'code', 'OFFERING_TABLE_MISMATCH',
          'details', jsonb_build_object(
            'entityType', 'table',
            'reason', 'offering_requirement'
          )
        )
      )::text,
      CONSTRAINT = 'vip_floor_business_rejection_v8';
  END IF;

  RETURN NEW;
END;
$$;

-- FUNCTION: verify_admin_pin_session_v7(text, text, timestamp with time zone, text, text)
CREATE FUNCTION public.verify_admin_pin_session_v7(p_pin text, p_session_token_hash text, p_expires_at timestamp with time zone, p_request_id text, p_ip_hash text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'ok', false,
    'error', 'admin_pin_login_disabled'
  );
$$;

-- COMMENT: FUNCTION verify_admin_pin_session_v7(p_pin text, p_session_token_hash text, p_expires_at timestamp with time zone, p_request_id text, p_ip_hash text)
COMMENT ON FUNCTION public.verify_admin_pin_session_v7(p_pin text, p_session_token_hash text, p_expires_at timestamp with time zone, p_request_id text, p_ip_hash text) IS 'Retired legacy admin PIN authentication. Always fails closed and never creates a session.';

-- FUNCTION: verify_ticket_wallet_otp_v29(text, timestamp with time zone, uuid, text, text, text, text, uuid, text, text, text, timestamp with time zone, timestamp with time zone, integer)
CREATE FUNCTION public.verify_ticket_wallet_otp_v29(p_environment text, p_now timestamp with time zone, p_preauth_flow_id uuid, p_preauth_token_verifier text, p_preauth_csrf_verifier text, p_submitted_code_verifier text, p_abuse_ip_hash text, p_candidate_session_id uuid, p_candidate_session_token_verifier text, p_candidate_session_csrf_verifier text, p_candidate_key_id text, p_candidate_fresh_until timestamp with time zone, p_candidate_maximum_expires_at timestamp with time zone, p_maximum_active_sessions integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_flow public.ticket_wallet_preauth_flows%ROWTYPE;
  v_challenge public.ticket_wallet_otp_challenges%ROWTYPE;
  v_support_expires_at timestamptz;
  v_session_expires_at timestamptz;
  v_remaining integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('ticket-passkey-transition-v34',0));
  IF p_environment NOT IN ('test', 'live')
    OR p_now IS NULL OR abs(extract(epoch FROM (p_now - v_now))) > 300
    OR p_preauth_flow_id IS NULL OR p_candidate_session_id IS NULL
    OR p_submitted_code_verifier IS NULL OR char_length(p_submitted_code_verifier) NOT BETWEEN 16 AND 256
    OR p_abuse_ip_hash IS NULL OR char_length(p_abuse_ip_hash) NOT BETWEEN 16 AND 256
    OR p_candidate_session_token_verifier IS NULL
    OR char_length(p_candidate_session_token_verifier) NOT BETWEEN 16 AND 256
    OR p_candidate_session_csrf_verifier IS NULL
    OR char_length(p_candidate_session_csrf_verifier) NOT BETWEEN 16 AND 256
    OR p_candidate_key_id !~ '^[A-Za-z0-9._-]{1,64}$'
    OR p_candidate_fresh_until < v_now
    OR p_candidate_fresh_until > v_now + interval '12 hours 5 seconds'
    OR p_candidate_maximum_expires_at <= v_now
    OR p_candidate_maximum_expires_at > v_now + interval '30 days 5 seconds'
    OR p_maximum_active_sessions <> 3
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'preauth_invalid');
  END IF;

  SELECT * INTO v_flow
  FROM public.ticket_wallet_preauth_flows
  WHERE id = p_preauth_flow_id
  FOR UPDATE;
  IF NOT FOUND OR v_flow.state <> 'active' OR v_flow.expires_at <= v_now
    OR NOT public.ticket_auth_digest_equal_v29(v_flow.token_verifier, p_preauth_token_verifier)
    OR NOT public.ticket_auth_digest_equal_v29(v_flow.csrf_verifier, p_preauth_csrf_verifier)
  THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'preauth_invalid');
  END IF;

  SELECT * INTO v_challenge
  FROM public.ticket_wallet_otp_challenges
  WHERE preauth_flow_id = v_flow.id
  ORDER BY requested_at DESC, id
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND OR v_challenge.environment <> p_environment THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'preauth_invalid');
  END IF;
  IF v_challenge.state IN ('expired', 'superseded', 'failed', 'consumed') THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'challenge_expired');
  END IF;
  IF v_challenge.state = 'locked' OR v_challenge.attempt_count >= v_challenge.maximum_attempts THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'attempts_exhausted', 'attemptsRemaining', 0);
  END IF;
  IF v_challenge.expires_at <= v_now THEN
    UPDATE public.ticket_wallet_otp_challenges
    SET state = 'expired', code_ciphertext = NULL,
        terminal_at = v_now, updated_at = v_now
    WHERE id = v_challenge.id;
    UPDATE public.transactional_email_jobs
    SET state = 'cancelled', terminal_at = v_now,
        claimed_by = NULL, claim_token = NULL, claimed_at = NULL,
        lease_expires_at = NULL, updated_at = v_now
    WHERE otp_challenge_id = v_challenge.id
      AND state IN ('pending', 'processing', 'retry');
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'challenge_expired');
  END IF;

  IF NOT public.consume_ticket_wallet_rate_limit_v29('otp_verify_ip_10m', p_abuse_ip_hash, 600, 100) THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'rate_limited');
  END IF;

  IF v_challenge.is_decoy OR NOT public.ticket_auth_digest_equal_v29(
      v_challenge.code_verifier, p_submitted_code_verifier)
  THEN
    v_remaining := v_challenge.maximum_attempts - v_challenge.attempt_count - 1;
    IF v_remaining <= 0 THEN
      UPDATE public.ticket_wallet_otp_challenges
      SET attempt_count = maximum_attempts, state = 'locked',
          code_ciphertext = NULL, terminal_at = v_now, updated_at = v_now
      WHERE id = v_challenge.id;
      UPDATE public.transactional_email_jobs
      SET state = 'cancelled', terminal_at = v_now,
          claimed_by = NULL, claim_token = NULL, claimed_at = NULL,
          lease_expires_at = NULL, updated_at = v_now
      WHERE otp_challenge_id = v_challenge.id
        AND state IN ('pending', 'processing', 'retry');
      RETURN jsonb_build_object(
        'action', 'rejected', 'reason', 'attempts_exhausted', 'attemptsRemaining', 0);
    END IF;
    UPDATE public.ticket_wallet_otp_challenges
    SET attempt_count = attempt_count + 1, updated_at = v_now
    WHERE id = v_challenge.id;
    RETURN jsonb_build_object(
      'action', 'rejected', 'reason', 'invalid_code', 'attemptsRemaining', v_remaining);
  END IF;

  SELECT max(event_session.admission_closes_at + interval '8 days')
  INTO v_support_expires_at
  FROM public.ticket_orders AS ticket_order
  JOIN public.ticket_event_sessions AS event_session
    ON event_session.id = ticket_order.event_session_id
   AND event_session.environment = ticket_order.environment
   AND event_session.stripe_account_key = ticket_order.stripe_account_key
  WHERE ticket_order.environment = p_environment
    AND ticket_order.check_in_mode = 'wallet_swipe'
    AND ticket_order.purchaser_email_hash = v_challenge.identity_email_hash
    AND ticket_order.status = 'fulfilled'
    AND ticket_order.paid_at IS NOT NULL
    AND ticket_order.fulfilled_at IS NOT NULL
    AND ticket_order.payment_hold_reason IS NULL
    AND event_session.enabled
    AND event_session.admission_state <> 'cancelled'
    AND event_session.admission_closes_at + interval '8 days' > v_now;

  IF v_support_expires_at IS NULL THEN
    UPDATE public.ticket_wallet_otp_challenges
    SET state = 'failed', code_ciphertext = NULL,
        terminal_at = v_now, updated_at = v_now
    WHERE id = v_challenge.id;
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'preauth_invalid');
  END IF;

  v_session_expires_at := LEAST(p_candidate_maximum_expires_at, v_support_expires_at);
  IF v_session_expires_at <= v_now THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'preauth_invalid');
  END IF;

  -- Distinct valid Pre-Auth flows for one holder may verify concurrently.
  -- Serialize only that holder's session issuance so the maximum-of-three
  -- invariant cannot be defeated by a READ COMMITTED phantom race.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'ticket-wallet-session-v29:' || p_environment || ':'
        || v_challenge.identity_email_hash,
      0
    )
  );

  INSERT INTO public.ticket_wallet_sessions(
    id, environment, identity_email_hash, auth_key_id,
    token_verifier, csrf_verifier, verified_at, fresh_until,
    expires_at, created_at, updated_at
  ) VALUES (
    p_candidate_session_id, p_environment, v_challenge.identity_email_hash,
    p_candidate_key_id, p_candidate_session_token_verifier,
    p_candidate_session_csrf_verifier, v_now,
    LEAST(p_candidate_fresh_until, v_session_expires_at),
    v_session_expires_at, v_now, v_now
  );

  UPDATE public.ticket_wallet_otp_challenges
  SET state = 'consumed', code_ciphertext = NULL,
      consumed_at = v_now, terminal_at = v_now, updated_at = v_now
  WHERE id = v_challenge.id;
  UPDATE public.ticket_wallet_preauth_flows
  SET state = 'consumed', token_verifier = NULL, csrf_verifier = NULL,
      consumed_at = v_now, terminal_at = v_now, updated_at = v_now
  WHERE id = v_flow.id;
  UPDATE public.transactional_email_jobs
  SET state = 'cancelled', terminal_at = v_now,
      claimed_by = NULL, claim_token = NULL, claimed_at = NULL,
      lease_expires_at = NULL, updated_at = v_now
  WHERE otp_challenge_id = v_challenge.id
    AND state IN ('pending', 'processing', 'retry');

  WITH retire AS (
    SELECT session.id
    FROM public.ticket_wallet_sessions AS session
    WHERE session.environment = p_environment
      AND session.identity_email_hash = v_challenge.identity_email_hash
      AND session.revoked_at IS NULL
    ORDER BY session.verified_at DESC, (session.id = p_candidate_session_id) DESC, session.id DESC
    OFFSET p_maximum_active_sessions
    FOR UPDATE
  )
  UPDATE public.ticket_wallet_sessions AS session
  SET revoked_at = v_now, revocation_reason = 'session_limit',
      token_verifier = NULL, csrf_verifier = NULL, updated_at = v_now
  FROM retire
  WHERE session.id = retire.id;

  RETURN jsonb_build_object(
    'action', 'verified', 'sessionId', p_candidate_session_id,
    'verifiedAt', v_now,
    'freshUntil', LEAST(p_candidate_fresh_until, v_session_expires_at),
    'expiresAt', v_session_expires_at
  );
END;
$_$;

-- FUNCTION: vip_floor_compat_changed_fields(text, jsonb, jsonb)
CREATE FUNCTION public.vip_floor_compat_changed_fields(p_table_name text, p_old jsonb, p_new jsonb) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_fields text[];
BEGIN
  v_fields := CASE p_table_name
    WHEN 'reservations' THEN ARRAY[
      'public_code', 'customer_id', 'booking_slot_id', 'booking_offering_id',
      'guest_count', 'status', 'hold_expires_at', 'payment_grace_until_at',
      'admin_hold_expires_at', 'admin_hold_reason', 'created_by_admin_id',
      'confirmed_at', 'intake_channel', 'guest_label', 'operator_note',
      'checked_in_at', 'seat_due_at', 'seat_extended_until_at',
      'seat_extension_minutes', 'event_day_id', 'scheduled_start_at',
      'scheduled_end_at', 'expected_release_at', 'service_status',
      'service_status_changed_at', 'arrived_at', 'service_completed_at'
    ]
    WHEN 'reservation_resources' THEN ARRAY[
      'reservation_id', 'seat_resource_id', 'lock_status', 'hold_expires_at',
      'admin_hold_expires_at', 'confirmed_at', 'released_at',
      'assigned_start_at', 'assigned_end_at', 'assignment_role',
      'assigned_by_admin_id', 'released_by_admin_id', 'release_reason'
    ]
    WHEN 'reservation_blocks' THEN ARRAY[
      'event_day_id', 'scope', 'kind', 'start_at', 'end_at', 'memo',
      'status', 'created_by_admin_id', 'cancelled_by_admin_id', 'cancelled_at'
    ]
    WHEN 'reservation_block_targets' THEN ARRAY[
      'block_id', 'seat_resource_id', 'floor_section_id', 'venue_wide'
    ]
    WHEN 'reservation_notes' THEN ARRAY[
      'reservation_id', 'kind', 'body', 'pinned', 'author_admin_id',
      'updated_by_admin_id', 'archived_at'
    ]
    WHEN 'seat_resources' THEN ARRAY[
      'public_resource_code', 'name', 'capacity_min', 'capacity_max', 'active',
      'floor_section_id', 'display_code', 'sort_order', 'shape', 'x_percent',
      'y_percent', 'width_percent', 'height_percent', 'rotation_degrees',
      'online_eligible', 'operational_locked', 'lock_reason'
    ]
    WHEN 'floor_sections' THEN ARRAY['code', 'name', 'sort_order', 'active']
    WHEN 'event_days' THEN ARRAY[
      'business_date', 'venue_timezone', 'sales_open_at', 'sales_close_at'
    ]
    WHEN 'booking_slots' THEN ARRAY[
      'event_day_id', 'public_slot_id', 'start_at', 'end_at',
      'bookable_until_at', 'cancel_free_until_at', 'no_show_fee_yen',
      'late_cancel_fee_yen', 'admin_only', 'active'
    ]
    WHEN 'payments' THEN ARRAY[
      'reservation_id', 'status', 'type', 'amount_yen', 'payment_method_id'
    ]
    WHEN 'webhook_events' THEN ARRAY[
      'processing_status', 'ignored_reason', 'last_error_code'
    ]
    WHEN 'stripe_object_states' THEN ARRAY['stripe_status', 'terminal_at']
    ELSE NULL
  END;

  IF v_fields IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'unsupported VIP Floor compatibility table';
  END IF;

  RETURN ARRAY(
    SELECT field_name
    FROM unnest(v_fields) WITH ORDINALITY AS fields(field_name, position)
    WHERE (p_old -> field_name) IS DISTINCT FROM (p_new -> field_name)
    ORDER BY position
  );
END;
$$;

-- FUNCTION: vip_floor_compat_event_day_ids(text, jsonb, jsonb)
CREATE FUNCTION public.vip_floor_compat_event_day_ids(p_table_name text, p_old jsonb, p_new jsonb) RETURNS uuid[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  CASE p_table_name
    WHEN 'reservations' THEN
      v_ids := ARRAY[
        NULLIF(p_old ->> 'event_day_id', '')::uuid,
        NULLIF(p_new ->> 'event_day_id', '')::uuid
      ];
    WHEN 'reservation_resources', 'reservation_notes', 'payments' THEN
      SELECT COALESCE(array_agg(DISTINCT r.event_day_id ORDER BY r.event_day_id), ARRAY[]::uuid[])
      INTO v_ids
      FROM public.reservations AS r
      WHERE r.id = ANY(ARRAY[
        NULLIF(p_old ->> 'reservation_id', '')::uuid,
        NULLIF(p_new ->> 'reservation_id', '')::uuid
      ]);
    WHEN 'reservation_blocks' THEN
      v_ids := ARRAY[
        NULLIF(p_old ->> 'event_day_id', '')::uuid,
        NULLIF(p_new ->> 'event_day_id', '')::uuid
      ];
    WHEN 'reservation_block_targets' THEN
      SELECT COALESCE(array_agg(DISTINCT rb.event_day_id ORDER BY rb.event_day_id), ARRAY[]::uuid[])
      INTO v_ids
      FROM public.reservation_blocks AS rb
      WHERE rb.id = ANY(ARRAY[
        NULLIF(p_old ->> 'block_id', '')::uuid,
        NULLIF(p_new ->> 'block_id', '')::uuid
      ]);
    WHEN 'event_days' THEN
      v_ids := ARRAY[
        NULLIF(p_old ->> 'id', '')::uuid,
        NULLIF(p_new ->> 'id', '')::uuid
      ];
    WHEN 'booking_slots' THEN
      v_ids := ARRAY[
        NULLIF(p_old ->> 'event_day_id', '')::uuid,
        NULLIF(p_new ->> 'event_day_id', '')::uuid
      ];
    WHEN 'seat_resources', 'floor_sections' THEN
      SELECT COALESCE(array_agg(ed.id ORDER BY ed.id), ARRAY[]::uuid[])
      INTO v_ids
      FROM public.event_days AS ed;
    WHEN 'webhook_events' THEN
      SELECT COALESCE(array_agg(DISTINCT r.event_day_id ORDER BY r.event_day_id), ARRAY[]::uuid[])
      INTO v_ids
      FROM public.stripe_intent_bindings AS binding
      JOIN public.reservations AS r ON r.id = binding.reservation_id
      WHERE (
          binding.environment = p_old ->> 'environment'
          AND binding.stripe_account_key = p_old ->> 'stripe_account_key'
          AND binding.provider_object_type IS NOT DISTINCT FROM p_old ->> 'provider_object_type'
          AND binding.provider_object_id = p_old ->> 'provider_object_id'
        ) OR (
          binding.environment = p_new ->> 'environment'
          AND binding.stripe_account_key = p_new ->> 'stripe_account_key'
          AND binding.provider_object_type IS NOT DISTINCT FROM p_new ->> 'provider_object_type'
          AND binding.provider_object_id = p_new ->> 'provider_object_id'
        );
    WHEN 'stripe_object_states' THEN
      SELECT COALESCE(array_agg(DISTINCT r.event_day_id ORDER BY r.event_day_id), ARRAY[]::uuid[])
      INTO v_ids
      FROM public.stripe_intent_bindings AS binding
      JOIN public.reservations AS r ON r.id = binding.reservation_id
      WHERE (
          binding.environment = p_old ->> 'environment'
          AND binding.stripe_account_key = p_old ->> 'stripe_account_key'
          AND binding.provider_object_type IS NOT DISTINCT FROM p_old ->> 'object_type'
          AND binding.provider_object_id = p_old ->> 'object_id'
        ) OR (
          binding.environment = p_new ->> 'environment'
          AND binding.stripe_account_key = p_new ->> 'stripe_account_key'
          AND binding.provider_object_type IS NOT DISTINCT FROM p_new ->> 'object_type'
          AND binding.provider_object_id = p_new ->> 'object_id'
        );
    ELSE
      RAISE EXCEPTION USING
        ERRCODE = '22023',
        MESSAGE = 'unsupported VIP Floor compatibility table';
  END CASE;

  SELECT COALESCE(array_agg(DISTINCT event_day_id ORDER BY event_day_id), ARRAY[]::uuid[])
  INTO v_ids
  FROM unnest(v_ids) AS affected(event_day_id)
  WHERE event_day_id IS NOT NULL;

  IF cardinality(v_ids) > 512 THEN
    RAISE EXCEPTION USING
      ERRCODE = '54000',
      MESSAGE = 'VIP Floor compatibility event-day set exceeds the 512-day bound';
  END IF;

  RETURN v_ids;
END;
$$;

-- FUNCTION: vip_floor_reconciliation_counts_v8()
CREATE FUNCTION public.vip_floor_reconciliation_counts_v8() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH active_reservations AS (
    SELECT r.*
    FROM public.reservations AS r
    WHERE r.status NOT IN (
      'cancelled',
      'hold_expired',
      'payment_window_expired',
      'failed'
    )
      AND r.service_status IS DISTINCT FROM 'completed'
      AND r.service_status IS DISTINCT FROM 'no_show'
  ),
  active_assignments AS (
    SELECT rr.*
    FROM public.reservation_resources AS rr
    JOIN active_reservations AS r ON r.id = rr.reservation_id
    WHERE rr.released_at IS NULL
      AND rr.lock_status IN ('held', 'payment_grace_locked', 'confirmed')
  ),
  checks AS (
    SELECT
      (
        SELECT count(*)
        FROM active_reservations
        WHERE event_day_id IS NULL
           OR scheduled_start_at IS NULL
           OR scheduled_end_at IS NULL
           OR expected_release_at IS NULL
           OR version IS NULL
      ) AS active_reservation_required_nulls,
      (
        SELECT count(*)
        FROM active_assignments
        WHERE assigned_start_at IS NULL
           OR assigned_end_at IS NULL
           OR assignment_role IS NULL
           OR version IS NULL
      ) AS active_assignment_required_nulls,
      (
        SELECT count(*)
        FROM active_assignments AS rr
        JOIN active_reservations AS r ON r.id = rr.reservation_id
        WHERE rr.assigned_start_at < r.scheduled_start_at
           OR rr.assigned_end_at > r.expected_release_at
      ) AS assignment_outside_reservation_interval,
      (
        SELECT count(*)
        FROM active_assignments AS left_assignment
        JOIN active_assignments AS right_assignment
          ON right_assignment.id > left_assignment.id
         AND right_assignment.seat_resource_id = left_assignment.seat_resource_id
         AND right_assignment.assigned_start_at < left_assignment.assigned_end_at
         AND right_assignment.assigned_end_at > left_assignment.assigned_start_at
      ) AS active_resource_overlap,
      (
        SELECT count(*)
        FROM public.reservation_resources AS rr
        LEFT JOIN public.reservations AS r ON r.id = rr.reservation_id
        LEFT JOIN public.seat_resources AS sr ON sr.id = rr.seat_resource_id
        WHERE r.id IS NULL OR sr.id IS NULL
      ) + (
        SELECT count(*)
        FROM public.reservations AS r
        LEFT JOIN public.customers AS c ON c.id = r.customer_id
        WHERE r.customer_id IS NOT NULL AND c.id IS NULL
      ) AS orphan_links,
      (
        SELECT count(*)
        FROM public.reservations AS r
        WHERE (r.status = 'confirmed' AND r.service_status IS NULL)
           OR (
             r.status = 'checked_in'
             AND r.service_status IS DISTINCT FROM 'seated'::public.vip_service_status
           )
      ) AS unresolved_lifecycle_service_projection,
      (
        SELECT count(*)
        FROM public.event_days AS ed
        LEFT JOIN public.vip_floor_day_revisions AS revision
          ON revision.event_day_id = ed.id
        WHERE revision.event_day_id IS NULL
      ) AS missing_event_day_revision,
      (
        SELECT count(*)
        FROM public.reservations AS r
        WHERE r.event_day_id IS NULL
           OR r.scheduled_start_at IS NULL
           OR r.scheduled_end_at IS NULL
           OR r.expected_release_at IS NULL
      ) AS legacy_fallback_count,
      (
        SELECT count(*)
        FROM public.customer_profiles AS profile
        WHERE (
          profile.display_name_ciphertext IS NOT NULL
          AND NULLIF(profile.display_name_search_token, '') IS NULL
        ) OR (
          profile.display_name_ciphertext IS NULL
          AND profile.display_name_search_token IS NOT NULL
        )
      ) AS ciphertext_search_hash_consistency_failures
  )
  SELECT jsonb_build_object(
    'activeReservationRequiredNulls', active_reservation_required_nulls,
    'activeAssignmentRequiredNulls', active_assignment_required_nulls,
    'assignmentOutsideReservationInterval', assignment_outside_reservation_interval,
    'activeResourceOverlap', active_resource_overlap,
    'orphanLinks', orphan_links,
    'unresolvedLifecycleServiceProjection', unresolved_lifecycle_service_projection,
    'missingEventDayRevision', missing_event_day_revision,
    'legacyFallbackCount', legacy_fallback_count,
    'ciphertextSearchHashConsistencyFailures', ciphertext_search_hash_consistency_failures,
    'ambiguousRecordCount',
      assignment_outside_reservation_interval
      + active_resource_overlap
      + unresolved_lifecycle_service_projection
      + ciphertext_search_hash_consistency_failures
  )
  FROM checks;
$$;

-- FUNCTION: vip_floor_v2_dual_write_enabled()
CREATE FUNCTION public.vip_floor_v2_dual_write_enabled() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(
    (
      SELECT CASE
        WHEN jsonb_typeof(setting.value_json) = 'boolean'
          THEN (setting.value_json #>> '{}')::boolean
        ELSE false
      END
      FROM public.app_settings AS setting
      WHERE setting.key = 'vip_floor_v2_dual_write'
    ),
    false
  );
$$;

-- TABLE: abuse_audit_events
CREATE TABLE public.abuse_audit_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ip_hash text,
    ua_hash text,
    email_hash text,
    phone_hash text,
    booking_slot_id uuid,
    request_hash text,
    decision text NOT NULL,
    turnstile_result text,
    request_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE ONLY public.abuse_audit_events FORCE ROW LEVEL SECURITY;

-- TABLE: admin_action_requests
CREATE TABLE public.admin_action_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_admin_id uuid,
    action text NOT NULL,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    response_json jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    trial_run_id text
);

ALTER TABLE ONLY public.admin_action_requests FORCE ROW LEVEL SECURITY;

-- TABLE: admin_pin_credentials
CREATE TABLE public.admin_pin_credentials (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    admin_user_id uuid NOT NULL,
    pin_salt text NOT NULL,
    pin_hash text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    attempt_window_started_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    failed_attempt_count integer DEFAULT 0 NOT NULL,
    locked_until timestamp with time zone,
    last_used_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    trial_run_id text,
    CONSTRAINT admin_pin_credentials_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT admin_pin_credentials_failed_attempt_count_check CHECK ((failed_attempt_count >= 0)),
    CONSTRAINT admin_pin_credentials_pin_hash_check CHECK ((length(pin_hash) = 64)),
    CONSTRAINT admin_pin_credentials_pin_salt_check CHECK ((length(pin_salt) >= 32))
);

ALTER TABLE ONLY public.admin_pin_credentials FORCE ROW LEVEL SECURITY;

-- TABLE: admin_pin_ip_rate_limits
CREATE TABLE public.admin_pin_ip_rate_limits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ip_hash text NOT NULL,
    window_started_at timestamp with time zone DEFAULT now() NOT NULL,
    window_seconds integer DEFAULT 600 NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    blocked_until timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    trial_run_id text,
    CONSTRAINT admin_pin_ip_rate_limits_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT admin_pin_ip_rate_limits_window_seconds_check CHECK ((window_seconds > 0))
);

ALTER TABLE ONLY public.admin_pin_ip_rate_limits FORCE ROW LEVEL SECURITY;

-- TABLE: admin_sessions
CREATE TABLE public.admin_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    admin_user_id uuid NOT NULL,
    session_token_hash text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    retired_at timestamp with time zone,
    last_seen_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    trial_run_id text,
    CONSTRAINT admin_sessions_check CHECK ((expires_at > created_at))
);

ALTER TABLE ONLY public.admin_sessions FORCE ROW LEVEL SECURITY;

-- TABLE: admin_users
CREATE TABLE public.admin_users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    auth_user_id uuid,
    email_hash text,
    display_name text,
