    trial_run_id text,
    CONSTRAINT reservation_block_targets_exactly_one_target CHECK ((((
CASE
    WHEN (seat_resource_id IS NOT NULL) THEN 1
    ELSE 0
END +
CASE
    WHEN (floor_section_id IS NOT NULL) THEN 1
    ELSE 0
END) +
CASE
    WHEN venue_wide THEN 1
    ELSE 0
END) = 1))
);

