    origin_channel text NOT NULL,
    gclid text,
    CONSTRAINT reservations_check CHECK (((status <> ALL (ARRAY['admin_hold'::public.reservation_status, 'admin_hold_review'::public.reservation_status])) OR (admin_hold_expires_at IS NOT NULL))),
    CONSTRAINT reservations_guest_count_check CHECK ((guest_count > 0)),
    CONSTRAINT reservations_guest_label_length_check CHECK (((guest_label IS NULL) OR (char_length(guest_label) <= 80))),
    CONSTRAINT reservations_intake_channel_check CHECK ((intake_channel = ANY (ARRAY['online'::text, 'admin_hold'::text, 'walk_in'::text]))),
    CONSTRAINT reservations_manager_notification_preference_check CHECK ((manager_notification_preference = ANY (ARRAY['none'::text, 'email'::text]))),
    CONSTRAINT reservations_operator_note_length_check CHECK (((operator_note IS NULL) OR (char_length(operator_note) <= 500))),
    CONSTRAINT reservations_origin_channel_check CHECK ((origin_channel = ANY (ARRAY['online'::text, 'phone'::text, 'walk_in'::text, 'admin'::text]))),
    CONSTRAINT reservations_seat_extension_minutes_check CHECK ((seat_extension_minutes >= 0)),
