    CONSTRAINT reservations_vip_floor_expected_release_check CHECK ((expected_release_at >= scheduled_start_at)),
    CONSTRAINT reservations_vip_floor_interval_check CHECK ((scheduled_start_at < scheduled_end_at)),
    CONSTRAINT reservations_vip_floor_status_timestamp_check CHECK ((((service_status IS NULL) AND (service_status_changed_at IS NULL)) OR ((service_status IS NOT NULL) AND (service_status_changed_at IS NOT NULL)))),
    CONSTRAINT reservations_vip_floor_version_check CHECK ((version >= 1)),
    CONSTRAINT reservations_vipapp_service_status_check CHECK (((vipapp_service_status IS NULL) OR (vipapp_service_status = ANY (ARRAY['expected'::text, 'late'::text, 'no_contact'::text, 'arrived'::text, 'partial_arrival'::text, 'seated'::text, 'bottle_pending'::text, 'bottle_served'::text, 'bill_requested'::text, 'paid'::text, 'resetting'::text, 'completed'::text, 'no_show'::text]))))
);

