    CONSTRAINT ticket_wallet_preauth_key_check_v29 CHECK ((auth_key_id ~ '^[A-Za-z0-9._-]{1,64}$'::text)),
    CONSTRAINT ticket_wallet_preauth_lifetime_check_v29 CHECK (((expires_at > created_at) AND (expires_at <= (created_at + '00:15:05'::interval)))),
    CONSTRAINT ticket_wallet_preauth_state_check_v29 CHECK ((state = ANY (ARRAY['active'::text, 'consumed'::text, 'expired'::text, 'superseded'::text]))),
    CONSTRAINT ticket_wallet_preauth_state_shape_v29 CHECK ((((state = 'active'::text) AND (token_verifier IS NOT NULL) AND (csrf_verifier IS NOT NULL) AND (consumed_at IS NULL) AND (terminal_at IS NULL)) OR ((state = 'consumed'::text) AND (token_verifier IS NULL) AND (csrf_verifier IS NULL) AND (consumed_at IS NOT NULL) AND (terminal_at IS NOT NULL)) OR ((state = ANY (ARRAY['expired'::text, 'superseded'::text])) AND (token_verifier IS NULL) AND (csrf_verifier IS NULL) AND (consumed_at IS NULL) AND (terminal_at IS NOT NULL))))
);

